// Procedures 
// Chapter: Image / Channel
void add_colormap_to_image (HObject ho_GrayValueImage, HObject ho_Image, HObject *ho_ColoredImage, 
    HTuple hv_HeatmapColorScheme)
{

  // Local iconic variables
  HObject  ho_RGBValueImage, ho_Channels, ho_ChannelsScaled;
  HObject  ho_Channel, ho_ChannelScaled, ho_ChannelScaledByte;
  HObject  ho_ImageByte, ho_ImageByteR, ho_ImageByteG, ho_ImageByteB;

  // Local control variables
  HTuple  hv_Type, hv_NumChannels, hv_ChannelIndex;
  HTuple  hv_ChannelMin, hv_ChannelMax, hv__;

  //
  //This procedure adds a gray-value image to a RGB image with a chosen color map.
  //
  GetImageType(ho_GrayValueImage, &hv_Type);
  //The image LUT needs a byte image. Rescale real images.
  if (0 != (int(hv_Type==HTuple("real"))))
  {
    scale_image_range(ho_GrayValueImage, &ho_GrayValueImage, 0, 1);
    ConvertImageType(ho_GrayValueImage, &ho_GrayValueImage, "byte");
  }
  else if (0 != (int(hv_Type!=HTuple("byte"))))
  {
    throw HException(HTuple("For this transformation, a byte or real image is needed!"));
  }
  //
  //Apply the chosen color scheme on the gray value.
  apply_colorscheme_on_gray_value_image(ho_GrayValueImage, &ho_RGBValueImage, hv_HeatmapColorScheme);
  //
  //Convert input image to byte image for visualization.
  ImageToChannels(ho_Image, &ho_Channels);
  CountChannels(ho_Image, &hv_NumChannels);
  GenEmptyObj(&ho_ChannelsScaled);
  {
  HTuple end_val19 = hv_NumChannels;
  HTuple step_val19 = 1;
  for (hv_ChannelIndex=1; hv_ChannelIndex.Continue(end_val19, step_val19); hv_ChannelIndex += step_val19)
  {
    SelectObj(ho_Channels, &ho_Channel, hv_ChannelIndex);
    MinMaxGray(ho_Channel, ho_Channel, 0, &hv_ChannelMin, &hv_ChannelMax, &hv__);
    scale_image_range(ho_Channel, &ho_ChannelScaled, hv_ChannelMin, hv_ChannelMax);
    ConvertImageType(ho_ChannelScaled, &ho_ChannelScaledByte, "byte");
    ConcatObj(ho_ChannelsScaled, ho_ChannelScaledByte, &ho_ChannelsScaled);
  }
  }
  ChannelsToImage(ho_ChannelsScaled, &ho_ImageByte);
  //
  //Note that ImageByte needs to have the same number of channels as
  //RGBValueImage to display color map image correctly.
  CountChannels(ho_ImageByte, &hv_NumChannels);
  if (0 != (int(hv_NumChannels!=3)))
  {
    //Just take the first channel and use this to generate
    //an image with 3 channels for visualization.
    AccessChannel(ho_ImageByte, &ho_ImageByteR, 1);
    CopyImage(ho_ImageByteR, &ho_ImageByteG);
    CopyImage(ho_ImageByteR, &ho_ImageByteB);
    Compose3(ho_ImageByteR, ho_ImageByteG, ho_ImageByteB, &ho_ImageByte);
  }
  //
  AddImage(ho_ImageByte, ho_RGBValueImage, &ho_RGBValueImage, 0.5, 0);
  (*ho_ColoredImage) = ho_RGBValueImage;
  //
  return;
}

// Chapter: Deep Learning / Classification
// Short Description: Add out-of-distribution samples to a preprocessed DLDataset for Classification. 
void add_dl_out_of_distribution_data (HTuple hv_DLDataset, HTuple hv_RawImageFolder, 
    HTuple hv_GenParam)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_PreprocessedDataset, hv_IndexDir, hv_CurrentImageDirectory;
  HTuple  hv_ImageDir, hv_Directories, hv_Index, hv_DirExists;
  HTuple  hv_FileExists, hv_DLDatasetOOD, hv_Idx, hv_Sample;
  HTuple  hv_DataDirectory, hv_DLDatasetFileName, hv___Tmp_Ctrl_Dict_Init_0;
  HTuple  hv___Tmp_Ctrl_0, hv___Tmp_Ctrl_Type;

  //This procedure can be used to add out-of-distribution data to a preprocessed DLDataset dictionary.
  //This can be useful to evaluate the out-of-distribution detection of a deep-learning-based classification model.
  //The out-of-distribution samples will be present in the DLDataset under the key `'ood_samples'`.

  //Check the parameters.
  GetDictParam(hv_DLDataset, "key_exists", "dlsample_dir", &hv_PreprocessedDataset);
  if (0 != (hv_PreprocessedDataset.TupleNot()))
  {
    throw HException("The given dataset is not preprocessed.");
  }

  //Check if given directories are valid
  {
  HTuple end_val11 = (hv_RawImageFolder.TupleLength())-1;
  HTuple step_val11 = 1;
  for (hv_IndexDir=0; hv_IndexDir.Continue(end_val11, step_val11); hv_IndexDir += step_val11)
  {
    hv_CurrentImageDirectory = HTuple(hv_RawImageFolder[hv_IndexDir]);
    if (0 != (int(hv_CurrentImageDirectory==HTuple(""))))
    {
      hv_CurrentImageDirectory = ".";
    }
    get_image_dir(&hv_ImageDir);
    hv_Directories = hv_CurrentImageDirectory;
    {
    HTuple end_val18 = (hv_ImageDir.TupleLength())-1;
    HTuple step_val18 = 1;
    for (hv_Index=0; hv_Index.Continue(end_val18, step_val18); hv_Index += step_val18)
    {
      hv_Directories = hv_Directories.TupleConcat((HTuple(hv_ImageDir[hv_Index])+"/")+hv_CurrentImageDirectory);
    }
    }
    //
    hv_DirExists = 0;
    {
    HTuple end_val23 = (hv_Directories.TupleLength())-1;
    HTuple step_val23 = 1;
    for (hv_Index=0; hv_Index.Continue(end_val23, step_val23); hv_Index += step_val23)
    {
      FileExists(HTuple(hv_Directories[hv_Index]), &hv_FileExists);
      if (0 != (int(hv_FileExists==1)))
      {
        hv_DirExists = 1;
        break;
      }
    }
    }
    if (0 != (int(hv_DirExists==0)))
    {
      throw HException(("Error: Given directory does not exist: \""+HTuple(hv_RawImageFolder[hv_IndexDir]))+"\"");
    }
  }
  }
  //
  //Read the out-of-distribution data as a classification dataset.
  read_dl_dataset_classification(hv_RawImageFolder, "last_folder", &hv_DLDatasetOOD);
  //Add a key to each sample to indicate that it is to be treated as out-of-distribution.
  {
  HTuple end_val38 = ((hv_DLDatasetOOD.TupleGetDictTuple("samples")).TupleLength())-1;
  HTuple step_val38 = 1;
  for (hv_Idx=0; hv_Idx.Continue(end_val38, step_val38); hv_Idx += step_val38)
  {
    hv_Sample = HTuple((hv_DLDatasetOOD.TupleGetDictTuple("samples"))[hv_Idx]);
    SetDictTuple(hv_Sample, "is_ood", "true");
    //Remove image_label_id, as the image labels do not fit the dataset by definition.
    RemoveDictKey(hv_Sample, "image_label_id");
  }
  }
  //The preprocesssed data will be stored within the DLDataset with the in-distribution data.
  hv_DataDirectory = hv_DLDataset.TupleGetDictTuple("dlsample_dir");
  TupleRegexpReplace(hv_DataDirectory, "$", "/out_of_distribution_data", &hv_DataDirectory);
  //Preprocess samples.
  CreateDict(&hv___Tmp_Ctrl_Dict_Init_0);
  SetDictTuple(hv___Tmp_Ctrl_Dict_Init_0, "overwrite_files", "auto");
  SetDictTuple(hv___Tmp_Ctrl_Dict_Init_0, "ignore_missing_labels", 1);
  preprocess_dl_dataset(hv_DLDatasetOOD, hv_DataDirectory, hv_DLDataset.TupleGetDictTuple("preprocess_param"), 
      hv___Tmp_Ctrl_Dict_Init_0, &hv_DLDatasetFileName);
  hv___Tmp_Ctrl_Dict_Init_0 = HTuple::TupleConstant("HNULL");
  //Copy out-of-distribution data into the DLDataset with the in-distribution data.
  GetDictParam(hv_DLDatasetOOD, "key_data_type", "samples", &hv___Tmp_Ctrl_Type);
  if (0 != (int(hv___Tmp_Ctrl_Type==HTuple("object"))))
  {
    SetDictObject(hv_DLDatasetOOD.TupleGetDictObject("samples"), hv_DLDataset, "ood_samples");
  }
  else
  {
    SetDictTuple(hv_DLDataset, "ood_samples", hv_DLDatasetOOD.TupleGetDictTuple("samples"));
  }
  {
  HTuple end_val60 = ((hv_DLDataset.TupleGetDictTuple("ood_samples")).TupleLength())-1;
  HTuple step_val60 = 1;
  for (hv_Idx=0; hv_Idx.Continue(end_val60, step_val60); hv_Idx += step_val60)
  {
    hv_Sample = HTuple((hv_DLDataset.TupleGetDictTuple("ood_samples"))[hv_Idx]);
    //Make sure the image_file contains the absolute path, because the DLDataset does not store the out-of-distribution image_dir.
    if (0 != (int((hv_RawImageFolder.TupleLength())==1)))
    {
      TupleRegexpReplace(hv_Sample.TupleGetDictTuple("image_file_name"), "^", hv_RawImageFolder+"/", 
          &hv___Tmp_Ctrl_0);
      SetDictTuple(hv_Sample, "image_file_name", hv___Tmp_Ctrl_0);
    }
    //Adapt the dlsample_file_names with paths relative to the dlsample_dir.
    TupleRegexpReplace(hv_Sample.TupleGetDictTuple("dlsample_file_name"), "^", "out_of_distribution_data/samples/", 
        &hv___Tmp_Ctrl_0);
    SetDictTuple(hv_Sample, "dlsample_file_name", hv___Tmp_Ctrl_0);
  }
  }

  return;
}

// Chapter: Deep Learning / Object Detection and Instance Segmentation
// Short Description: Collect data concerning the shape of the ground truth bounding boxes provided in DLDataset. 
void analyze_dl_dataset_detection (HTuple hv_DLDataset, HTuple hv_InstanceType, HTuple hv_ImageWidthTarget, 
    HTuple hv_ImageHeightTarget, HTuple hv_GenParam, HTuple *hv_Areas, HTuple *hv_AspectRatios, 
    HTuple *hv_Angles, HTuple *hv_MaxOverlap, HTuple *hv_MaxOverlapClassAgnostic)
{

  // Local iconic variables
  HObject  ho_Image, ho_Domain;

  // Local control variables
  HTuple  hv_ImageWidthRaw, hv_ImageHeightRaw, hv_DomainHandling;
  HTuple  hv_DatasetSplit, hv_PreprocessedPath, hv_Preprocessed;
  HTuple  hv_ClassIDsNoOrientation, hv_IgnoreDirection, hv_MaxNumSamples;
  HTuple  hv_ImageSizeConstant, hv_ComputeMaxOverlap, hv_AllocationBlockLength;
  HTuple  hv_InstanceCount, hv_Rows1, hv_Cols1, hv_Rows2;
  HTuple  hv_Cols2, hv_Lengths1, hv_Lengths2, hv_Phis, hv_GenParamName;
  HTuple  hv_GenParamIndex, hv_PreprocessedKey, hv_PreprocessedKeyExists;
  HTuple  hv_FactorWidth, hv_FactorHeight, hv_DLSamples, hv_ImageDir;
  HTuple  hv_SampleIndices, hv_MaxOverlapDict, hv_IterationIndex;
  HTuple  hv_SampleIndex, hv_DLSampleCurrent, hv_KeyFileExists;
  HTuple  hv_FileNameSample, hv_FileNameRelative, hv_Exception;
  HTuple  hv_ImageName, hv_Width, hv_Height, hv_DomainRow1;
  HTuple  hv_DomainColumn1, hv_DomainRow2, hv_DomainColumn2;
  HTuple  hv_WidthDomain, hv_HeightDomain, hv_Row1, hv_Col1;
  HTuple  hv_Row2, hv_Col2, hv_BoxMask, hv_Row, hv_Col, hv_Length1;
  HTuple  hv_Length2, hv_Phi, hv_Label, hv_ClassIDsNoOrientationIndices;
  HTuple  hv_Index, hv_ClassIDsNoOrientationIndicesTmp, hv_DirectionLength1Row;
  HTuple  hv_DirectionLength1Col, hv_DirectionLength2Row;
  HTuple  hv_DirectionLength2Col, hv_Corner1Row, hv_Corner1Col;
  HTuple  hv_Corner2Row, hv_Corner2Col, hv_Pi, hv_PhiMod;
  HTuple  hv_IgnoreMask, hv_SwapMask, hv_SwapMaskInverted;
  HTuple  hv_Length1Tmp, hv_Length2Tmp, hv_PhiMultMask, hv_KeyExists;
  HTuple  hv_BoundingBox, hv_IdxsWithOverlap, hv_Percentile;
  HTuple  hv_RelaxFactor, hv_Heights, hv_Widths, hv___Tmp_Ctrl_Dict_Init_0;
  HTuple  hv___Tmp_Ctrl_Dict_Init_1, hv___Tmp_Ctrl_Dict_Init_2;
  HTuple  hv___Tmp_Ctrl_Dict_Init_3, hv___Tmp_Ctrl_Dict_Init_4;
  HTuple  hv___Tmp_Ctrl_Dict_Init_5, hv___Tmp_Ctrl_Type;

  //This procedure creates various data collections from the given DLDataset
  //for DL Object Detection which are
  //- the areas of the ground truth bounding boxes
  //- the aspect ratios of the ground truth bounding boxes
  //- the orientations of the ground truth bounding boxes for rectangle2 object detection.
  //
  //
  //Default generic parameter values.
  hv_ImageWidthRaw = HTuple();
  hv_ImageHeightRaw = HTuple();
  hv_DomainHandling = "full_domain";
  hv_DatasetSplit = "train";
  hv_PreprocessedPath = "";
  hv_Preprocessed = 0;
  hv_ClassIDsNoOrientation = HTuple();
  hv_IgnoreDirection = 0;
  hv_MaxNumSamples = 1500;
  hv_ImageSizeConstant = 1;
  hv_ComputeMaxOverlap = 1;
  //
  //Output data tuples.
  (*hv_Areas) = HTuple();
  (*hv_AspectRatios) = HTuple();
  (*hv_Angles) = HTuple();
  (*hv_MaxOverlap) = HTuple();
  (*hv_MaxOverlapClassAgnostic) = HTuple();
  //
  //Box parameter tuples are allocated in blocks to speed up the procedure.
  hv_AllocationBlockLength = 1000;
  hv_InstanceCount = 0;
  //
  //Bounding box parameters for rectangle1.
  hv_Rows1 = HTuple(hv_AllocationBlockLength,0.);
  hv_Cols1 = HTuple(hv_AllocationBlockLength,0.);
  hv_Rows2 = HTuple(hv_AllocationBlockLength,0.);
  hv_Cols2 = HTuple(hv_AllocationBlockLength,0.);
  //Bounding box parameters for rectangle2.
  hv_Lengths1 = HTuple(hv_AllocationBlockLength,0.);
  hv_Lengths2 = HTuple(hv_AllocationBlockLength,0.);
  hv_Phis = HTuple(hv_AllocationBlockLength,0.);
  //
  //Read generic parameters and check the provided values.
  if (0 != (int(hv_GenParam!=HTuple())))
  {
    GetDictParam(hv_GenParam, "keys", HTuple(), &hv_GenParamName);
    {
    HTuple end_val44 = (hv_GenParamName.TupleLength())-1;
    HTuple step_val44 = 1;
    for (hv_GenParamIndex=0; hv_GenParamIndex.Continue(end_val44, step_val44); hv_GenParamIndex += step_val44)
    {
      if (0 != (int(HTuple(hv_GenParamName[hv_GenParamIndex])==HTuple("raw_width"))))
      {
        hv_ImageWidthRaw = hv_GenParam.TupleGetDictTuple("raw_width");
        if (0 != ((hv_ImageWidthRaw.TupleIsInt()).TupleNot()))
        {
          throw HException(HTuple(hv_GenParamName[hv_GenParamIndex])+" should be of type int");
        }
        if (0 != (int(hv_ImageWidthRaw<1)))
        {
          throw HException(("Invalid value for parameter 'raw_width': "+hv_ImageWidthRaw)+".");
        }
      }
      else if (0 != (int(HTuple(hv_GenParamName[hv_GenParamIndex])==HTuple("raw_height"))))
      {
        hv_ImageHeightRaw = hv_GenParam.TupleGetDictTuple("raw_height");
        if (0 != ((hv_ImageHeightRaw.TupleIsInt()).TupleNot()))
        {
          throw HException(HTuple(hv_GenParamName[hv_GenParamIndex])+" should be of type int");
        }
        if (0 != (int(hv_ImageHeightRaw<1)))
        {
          throw HException(("Invalid value for parameter 'raw_height': "+hv_ImageHeightRaw)+".");
        }
      }
      else if (0 != (int(HTuple(hv_GenParamName[hv_GenParamIndex])==HTuple("domain_handling"))))
      {
        hv_DomainHandling = hv_GenParam.TupleGetDictTuple("domain_handling");
        if (0 != (HTuple(int(hv_DomainHandling!=HTuple("full_domain"))).TupleAnd(int(hv_DomainHandling!=HTuple("crop_domain")))))
        {
          throw HException(("Invalid value for parameter 'domain_handling': "+hv_DomainHandling)+".");
        }
      }
      else if (0 != (int(HTuple(hv_GenParamName[hv_GenParamIndex])==HTuple("split"))))
      {
        hv_DatasetSplit = hv_GenParam.TupleGetDictTuple("split");
        if (0 != ((hv_DatasetSplit.TupleIsString()).TupleNot()))
        {
          throw HException(HTuple(hv_GenParamName[hv_GenParamIndex])+" should be of type string");
        }
      }
      else if (0 != (int(HTuple(hv_GenParamName[hv_GenParamIndex])==HTuple("preprocessed_path"))))
      {
        hv_PreprocessedPath = hv_GenParam.TupleGetDictTuple("preprocessed_path");
        if (0 != ((hv_PreprocessedPath.TupleIsString()).TupleNot()))
        {
          throw HException(HTuple(hv_GenParamName[hv_GenParamIndex])+" should be of type string");
        }
      }
      else if (0 != (int(HTuple(hv_GenParamName[hv_GenParamIndex])==HTuple("class_ids_no_orientation"))))
      {
        hv_ClassIDsNoOrientation = hv_GenParam.TupleGetDictTuple("class_ids_no_orientation");
        if (0 != (int(hv_InstanceType!=HTuple("rectangle2"))))
        {
          throw HException((("Parameter '"+HTuple(hv_GenParamName[hv_GenParamIndex]))+"' is only available for ")+"detection type 'rectangle2'");
        }
      }
      else if (0 != (int(HTuple(hv_GenParamName[hv_GenParamIndex])==HTuple("ignore_direction"))))
      {
        CreateDict(&hv___Tmp_Ctrl_Dict_Init_0);
        SetDictTuple(hv___Tmp_Ctrl_Dict_Init_0, "comp", 1);
        CreateDict(&hv___Tmp_Ctrl_Dict_Init_1);
        SetDictTuple(hv___Tmp_Ctrl_Dict_Init_1, "comp", "true");
        hv_IgnoreDirection = ((hv_GenParam.TupleConcat(hv___Tmp_Ctrl_Dict_Init_1)).TupleTestEqualDictItem("ignore_direction","comp")).TupleOr((hv_GenParam.TupleConcat(hv___Tmp_Ctrl_Dict_Init_0)).TupleTestEqualDictItem("ignore_direction","comp"));
        hv___Tmp_Ctrl_Dict_Init_1 = HTuple::TupleConstant("HNULL");
        hv___Tmp_Ctrl_Dict_Init_0 = HTuple::TupleConstant("HNULL");
      }
      else if (0 != (int(HTuple(hv_GenParamName[hv_GenParamIndex])==HTuple("max_num_samples"))))
      {
        hv_MaxNumSamples = hv_GenParam.TupleGetDictTuple("max_num_samples");
        if (0 != ((hv_MaxNumSamples.TupleIsInt()).TupleNot()))
        {
          throw HException(HTuple(hv_GenParamName[hv_GenParamIndex])+" should be of type int");
        }
        if (0 != (HTuple(int(hv_MaxNumSamples<1)).TupleAnd(int(hv_MaxNumSamples!=-1))))
        {
          throw HException(("Invalid value for parameter 'max_num_samples': "+hv_MaxNumSamples)+". Only -1 or values greater or equal to 1 are allowed.");
        }
      }
      else if (0 != (int(HTuple(hv_GenParamName[hv_GenParamIndex])==HTuple("image_size_constant"))))
      {
        CreateDict(&hv___Tmp_Ctrl_Dict_Init_2);
        SetDictTuple(hv___Tmp_Ctrl_Dict_Init_2, "comp", 1);
        CreateDict(&hv___Tmp_Ctrl_Dict_Init_3);
        SetDictTuple(hv___Tmp_Ctrl_Dict_Init_3, "comp", "true");
        hv_ImageSizeConstant = ((hv_GenParam.TupleConcat(hv___Tmp_Ctrl_Dict_Init_3)).TupleTestEqualDictItem("image_size_constant","comp")).TupleOr((hv_GenParam.TupleConcat(hv___Tmp_Ctrl_Dict_Init_2)).TupleTestEqualDictItem("image_size_constant","comp"));
        hv___Tmp_Ctrl_Dict_Init_3 = HTuple::TupleConstant("HNULL");
        hv___Tmp_Ctrl_Dict_Init_2 = HTuple::TupleConstant("HNULL");
      }
      else if (0 != (int(HTuple(hv_GenParamName[hv_GenParamIndex])==HTuple("compute_max_overlap"))))
      {
        CreateDict(&hv___Tmp_Ctrl_Dict_Init_4);
        SetDictTuple(hv___Tmp_Ctrl_Dict_Init_4, "comp", 1);
        CreateDict(&hv___Tmp_Ctrl_Dict_Init_5);
        SetDictTuple(hv___Tmp_Ctrl_Dict_Init_5, "comp", "true");
        hv_ComputeMaxOverlap = ((hv_GenParam.TupleConcat(hv___Tmp_Ctrl_Dict_Init_5)).TupleTestEqualDictItem("compute_max_overlap","comp")).TupleOr((hv_GenParam.TupleConcat(hv___Tmp_Ctrl_Dict_Init_4)).TupleTestEqualDictItem("compute_max_overlap","comp"));
        hv___Tmp_Ctrl_Dict_Init_5 = HTuple::TupleConstant("HNULL");
        hv___Tmp_Ctrl_Dict_Init_4 = HTuple::TupleConstant("HNULL");
      }
    }
    }
  }
  //
  //Check whether the DLDataset is already preprocessed.
  hv_PreprocessedKey = "dlsample_dir";
  GetDictParam(hv_DLDataset, "key_exists", hv_PreprocessedKey, &hv_PreprocessedKeyExists);
  if (0 != hv_PreprocessedKeyExists)
  {
    hv_Preprocessed = 1;
    if (0 != (int(hv_PreprocessedPath==HTuple(""))))
    {
      hv_PreprocessedPath = hv_DLDataset.TupleGetDictTuple(hv_PreprocessedKey);
    }
    else
    {
      hv_PreprocessedPath += HTuple("/samples");
    }
  }
  else
  {
    if (0 != (int(hv_PreprocessedPath!=HTuple(""))))
    {
      throw HException(HTuple(HTuple("The given dataset is not preprocessed but a preprocessing path is given. Please either use ")+"a preprocessed dataset as input or remove the specification for 'preprocessed_path' from ")+"the generic parameter dictionary GenParam.");
    }
    else
    {
      //If the DLDataset is not preprocessed, check whether the necessary preprocessing parameters
      //are provided.
      if (0 != (HTuple(int(hv_ImageWidthTarget==HTuple())).TupleOr(int(hv_ImageHeightTarget==HTuple()))))
      {
        throw HException("Please enter values for the target image width and height.");
      }
      else if (0 != (HTuple(int(hv_ImageWidthTarget<1)).TupleOr(int(hv_ImageHeightTarget<1))))
      {
        throw HException("Please enter valid values for the target image width and height.");
      }
      //In case the original images are of the same size (specified by the input
      //parameters), the scaling factors can be calculated here.
      if (0 != (HTuple(int(hv_ImageWidthRaw!=HTuple())).TupleAnd(int(hv_ImageHeightRaw!=HTuple()))))
      {
        hv_FactorWidth = (hv_ImageWidthTarget.TupleReal())/hv_ImageWidthRaw;
        hv_FactorHeight = (hv_ImageHeightTarget.TupleReal())/hv_ImageHeightRaw;
      }
    }
  }
  //
  //Get the samples in the dataset.
  hv_DLSamples = hv_DLDataset.TupleGetDictTuple("samples");
  hv_ImageDir = hv_DLDataset.TupleGetDictTuple("image_dir");
  //
  //Get the relevant sample indices.
  hv_SampleIndices = HTuple::TupleGenSequence(0,(hv_DLSamples.TupleLength())-1,1);
  if (0 != (int(hv_DatasetSplit!=HTuple("all"))))
  {
    find_dl_samples(hv_DLSamples, "split", hv_DatasetSplit, "or", &hv_SampleIndices);
    if (0 != (int((hv_SampleIndices.TupleLength())==0)))
    {
      throw HException(("No samples found for the specified dataset split: "+hv_DatasetSplit)+".");
    }
  }
  //
  //Reduce the number of samples if max_num_samples is specified.
  if (0 != (HTuple(int(hv_MaxNumSamples!=-1)).TupleAnd(int((hv_SampleIndices.TupleLength())>hv_MaxNumSamples))))
  {
    tuple_shuffle(hv_SampleIndices, &hv_SampleIndices);
    hv_SampleIndices = hv_SampleIndices.TupleSelectRange(0,hv_MaxNumSamples-1);
  }
  //
  if (0 != hv_ComputeMaxOverlap)
  {
    //Initialize some variables.
    CreateDict(&hv_MaxOverlapDict);
    SetDictTuple(hv_MaxOverlapDict, "max_overlaps_class_agnostic", HTuple(hv_AllocationBlockLength,-1));
    SetDictTuple(hv_MaxOverlapDict, "max_overlaps", HTuple(hv_AllocationBlockLength,-1));
    SetDictTuple(hv_MaxOverlapDict, "max_overlap", 0.);
    SetDictTuple(hv_MaxOverlapDict, "max_overlap_class_agnostic", 0.);
    SetDictTuple(hv_MaxOverlapDict, "num_max_overlaps", 0);
    SetDictTuple(hv_MaxOverlapDict, "num_max_overlaps_class_agnostic", 0);
  }
  //
  //Iterate over the samples and store information on the ground truth
  //bounding boxes.
  {
  HTuple end_val179 = (hv_SampleIndices.TupleLength())-1;
  HTuple step_val179 = 1;
  for (hv_IterationIndex=0; hv_IterationIndex.Continue(end_val179, step_val179); hv_IterationIndex += step_val179)
  {
    hv_SampleIndex = HTuple(hv_SampleIndices[hv_IterationIndex]);
    hv_DLSampleCurrent = HTuple(hv_DLSamples[hv_SampleIndex]);
    if (0 != hv_Preprocessed)
    {
      //Check whether the file name key of the preprocessed samples is available.
      GetDictParam(hv_DLSampleCurrent, "key_exists", "dlsample_file_name", &hv_KeyFileExists);
      if (0 != hv_KeyFileExists)
      {
        hv_FileNameSample = (hv_PreprocessedPath+"/")+(hv_DLSampleCurrent.TupleGetDictTuple("dlsample_file_name"));
      }
      else
      {
        //If the key does not exist, check if a corresponding file exists.
        hv_FileNameRelative = (hv_DLSampleCurrent.TupleGetDictTuple("image_id"))+"_dlsample.hdict";
        hv_FileNameSample = (hv_PreprocessedPath+"/")+hv_FileNameRelative;
      }
      //Read the dictionary of the preprocessed sample.
      try
      {
        ReadDict(hv_FileNameSample, HTuple(), HTuple(), &hv_DLSampleCurrent);
      }
      // catch (Exception) 
      catch (HException &HDevExpDefaultException)
      {
        HDevExpDefaultException.ToHTuple(&hv_Exception);
        throw HException((("An error has occurred while reading "+hv_FileNameSample)+HTuple(" , HALCON error # "))+HTuple(hv_Exception[0]));
      }
      //Set the scaling factors to 1 since the samples are already preprocessed.
      hv_FactorWidth = 1.;
      hv_FactorHeight = 1.;
      if (0 != (HTuple(int(hv_ImageWidthTarget==HTuple())).TupleOr(int(hv_ImageHeightTarget==HTuple()))))
      {
        //Set the preprocessed width and height to be used in the output.
        //The GenParam dictionary is recycled for this.
        GetImageSize(hv_DLSampleCurrent.TupleGetDictObject("image"), &hv_ImageWidthTarget, 
            &hv_ImageHeightTarget);
        SetDictTuple(hv_GenParam, "image_width_target", hv_ImageWidthTarget);
        SetDictTuple(hv_GenParam, "image_height_target", hv_ImageHeightTarget);
      }
    }
    else
    {
      //In case the samples are not preprocessed, we need to scale them according
      //to the target image sizes as well as perform domain handling if necessary.
      //The images need to be read in case the raw sizes are not provided or
      //the domain should be cropped.
      if (0 != (HTuple(HTuple(int(hv_ImageWidthRaw==HTuple())).TupleOr(int(hv_ImageHeightRaw==HTuple()))).TupleOr(int(hv_DomainHandling==HTuple("crop_domain")))))
      {
        hv_ImageName = hv_DLSampleCurrent.TupleGetDictTuple("image_file_name");
        try
        {
          ReadImage(&ho_Image, (hv_ImageDir+"/")+hv_ImageName);
        }
        // catch (Exception) 
        catch (HException &HDevExpDefaultException)
        {
          HDevExpDefaultException.ToHTuple(&hv_Exception);
          throw HException(((("Error while reading image "+hv_ImageDir)+"/")+hv_ImageName)+".");
        }
      }
      //In case the original images have variable sizes, the image
      //sizes need to be read in order to calculate the scaling factors.
      if (0 != (HTuple(int(hv_ImageWidthRaw==HTuple())).TupleOr(int(hv_ImageHeightRaw==HTuple()))))
      {
        //Read the image.
        GetImageSize(ho_Image, &hv_Width, &hv_Height);
        //Get the object sizes after preprocessing.
        hv_FactorWidth = (hv_ImageWidthTarget.TupleReal())/hv_Width;
        hv_FactorHeight = (hv_ImageHeightTarget.TupleReal())/hv_Height;
        //If we know that each image has the same size we can use the size
        //of the first one for all other images.
        if (0 != hv_ImageSizeConstant)
        {
          hv_ImageWidthRaw = hv_Width;
          hv_ImageHeightRaw = hv_Height;
        }
      }
      //Get the domain borders if the domain should be cropped.
      if (0 != (int(hv_DomainHandling==HTuple("crop_domain"))))
      {
        //Get domain.
        GetDomain(ho_Image, &ho_Domain);
        //Set the size of the raw image to the domain extensions.
        SmallestRectangle1(ho_Domain, &hv_DomainRow1, &hv_DomainColumn1, &hv_DomainRow2, 
            &hv_DomainColumn2);
        //Get the object sizes after preprocessing.
        hv_WidthDomain = (hv_DomainColumn2-hv_DomainColumn1)+1;
        hv_HeightDomain = (hv_DomainRow2-hv_DomainRow1)+1;
        hv_FactorWidth = (hv_ImageWidthTarget.TupleReal())/hv_WidthDomain;
        hv_FactorHeight = (hv_ImageHeightTarget.TupleReal())/hv_HeightDomain;
      }
    }
    //
    //Collect ground truth information for instance type rectangle1.
    if (0 != (int(hv_InstanceType==HTuple("rectangle1"))))
    {
      //Get the sample bounding boxes.
      try
      {
        hv_Row1 = hv_DLSampleCurrent.TupleGetDictTuple("bbox_row1");
        if (0 != (int((hv_Row1.TupleLength())==0)))
        {
          continue;
        }
        hv_Col1 = hv_DLSampleCurrent.TupleGetDictTuple("bbox_col1");
        hv_Row2 = hv_DLSampleCurrent.TupleGetDictTuple("bbox_row2");
        hv_Col2 = hv_DLSampleCurrent.TupleGetDictTuple("bbox_col2");
      }
      // catch (Exception) 
      catch (HException &HDevExpDefaultException)
      {
        HDevExpDefaultException.ToHTuple(&hv_Exception);
        throw HException("Bounding box label missing for rectangle1 object detection.");
      }
      //Crop the bounding boxes if necessary.
      if (0 != (HTuple(hv_Preprocessed.TupleNot()).TupleAnd(int(hv_DomainHandling==HTuple("crop_domain")))))
      {
        hv_Row1 = hv_Row1.TupleMax2(hv_DomainRow1-.5);
        hv_Col1 = hv_Col1.TupleMax2(hv_DomainColumn1-.5);
        hv_Row2 = hv_Row2.TupleMin2(hv_DomainRow2+.5);
        hv_Col2 = hv_Col2.TupleMin2(hv_DomainColumn2+.5);
        //Remove empty boxes resulted from the clipping.
        hv_BoxMask = (hv_Row1.TupleLessElem(hv_Row2)).TupleAnd(hv_Col1.TupleLessElem(hv_Col2));
        hv_Row1 = (hv_Row1.TupleSelectMask(hv_BoxMask))-hv_DomainRow1;
        hv_Row2 = (hv_Row2.TupleSelectMask(hv_BoxMask))-hv_DomainRow1;
        hv_Col1 = (hv_Col1.TupleSelectMask(hv_BoxMask))-hv_DomainColumn1;
        hv_Col2 = (hv_Col2.TupleSelectMask(hv_BoxMask))-hv_DomainColumn1;
      }
      //Increase the pre-allocated tuple-length, if necessary.
      if (0 != (int((hv_InstanceCount+(hv_Row1.TupleLength()))>=(hv_Rows1.TupleLength()))))
      {
        hv_Rows1 = hv_Rows1.TupleConcat(HTuple(hv_AllocationBlockLength.TupleMax2(hv_Row1.TupleLength()),0.));
        hv_Rows2 = hv_Rows2.TupleConcat(HTuple(hv_AllocationBlockLength.TupleMax2(hv_Row1.TupleLength()),0.));
        hv_Cols1 = hv_Cols1.TupleConcat(HTuple(hv_AllocationBlockLength.TupleMax2(hv_Row1.TupleLength()),0.));
        hv_Cols2 = hv_Cols2.TupleConcat(HTuple(hv_AllocationBlockLength.TupleMax2(hv_Row1.TupleLength()),0.));
      }
      //Collect the scaled bounding box data.
      hv_Row1 = hv_Row1*hv_FactorHeight;
      hv_Row2 = hv_Row2*hv_FactorHeight;
      hv_Col1 = hv_Col1*hv_FactorWidth;
      hv_Col2 = hv_Col2*hv_FactorWidth;
      hv_Rows1[HTuple::TupleGenSequence(hv_InstanceCount,(hv_InstanceCount+(hv_Row1.TupleLength()))-1,1)] = hv_Row1;
      hv_Rows2[HTuple::TupleGenSequence(hv_InstanceCount,(hv_InstanceCount+(hv_Row1.TupleLength()))-1,1)] = hv_Row2;
      hv_Cols1[HTuple::TupleGenSequence(hv_InstanceCount,(hv_InstanceCount+(hv_Row1.TupleLength()))-1,1)] = hv_Col1;
      hv_Cols2[HTuple::TupleGenSequence(hv_InstanceCount,(hv_InstanceCount+(hv_Row1.TupleLength()))-1,1)] = hv_Col2;
      hv_InstanceCount += hv_Row1.TupleLength();
      //Collect ground truth information for instance type rectangle2.
    }
    else if (0 != (int(hv_InstanceType==HTuple("rectangle2"))))
    {
      //Get the sample bounding boxes.
      try
      {
        hv_Row = hv_DLSampleCurrent.TupleGetDictTuple("bbox_row");
        if (0 != (int((hv_Row.TupleLength())==0)))
        {
          continue;
        }
        hv_Col = hv_DLSampleCurrent.TupleGetDictTuple("bbox_col");
        hv_Length1 = hv_DLSampleCurrent.TupleGetDictTuple("bbox_length1");
        hv_Length2 = hv_DLSampleCurrent.TupleGetDictTuple("bbox_length2");
        hv_Phi = hv_DLSampleCurrent.TupleGetDictTuple("bbox_phi");
        hv_Label = hv_DLSampleCurrent.TupleGetDictTuple("bbox_label_id");
      }
      // catch (Exception) 
      catch (HException &HDevExpDefaultException)
      {
        HDevExpDefaultException.ToHTuple(&hv_Exception);
        throw HException("Bounding box label missing for rectangle2 object detection.");
      }
      //Crop the bounding boxes by removing boxes with centers outside
      //of the domain.
      if (0 != (HTuple(hv_Preprocessed.TupleNot()).TupleAnd(int(hv_DomainHandling==HTuple("crop_domain")))))
      {
        hv_BoxMask = HTuple(HTuple((hv_Row.TupleGreaterEqualElem(hv_DomainRow1)).TupleAnd(hv_Col.TupleGreaterEqualElem(hv_DomainColumn1))).TupleAnd(hv_Row.TupleLessElem(hv_DomainRow2))).TupleAnd(hv_Col.TupleLessElem(hv_DomainColumn2));
        //Store the bounding boxes after the clipping.
        hv_Row = (hv_Row.TupleSelectMask(hv_BoxMask))-hv_DomainRow1;
        hv_Col = (hv_Col.TupleSelectMask(hv_BoxMask))-hv_DomainColumn1;
        hv_Length1 = hv_Length1.TupleSelectMask(hv_BoxMask);
        hv_Length2 = hv_Length2.TupleSelectMask(hv_BoxMask);
        hv_Phi = hv_Phi.TupleSelectMask(hv_BoxMask);
        hv_Label = hv_Label.TupleSelectMask(hv_BoxMask);
      }
      //Turn bounding boxes of classes in ClassIDsNoOrientation to axis-aligned bounding boxes.
      hv_ClassIDsNoOrientationIndices = HTuple();
      {
      HTuple end_val324 = (hv_ClassIDsNoOrientation.TupleLength())-1;
      HTuple step_val324 = 1;
      for (hv_Index=0; hv_Index.Continue(end_val324, step_val324); hv_Index += step_val324)
      {
        hv_ClassIDsNoOrientationIndicesTmp = (hv_Label.TupleEqualElem(HTuple(hv_ClassIDsNoOrientation[hv_Index]))).TupleFind(1);
        if (0 != (int(hv_ClassIDsNoOrientationIndicesTmp!=-1)))
        {
          hv_ClassIDsNoOrientationIndices = hv_ClassIDsNoOrientationIndices.TupleConcat(hv_ClassIDsNoOrientationIndicesTmp);
        }
      }
      }
      if (0 != (int((hv_ClassIDsNoOrientationIndices.TupleLength())>0)))
      {
        //Calculate length1 and length2 using position of corners.
        hv_DirectionLength1Row = -(HTuple(hv_Phi[hv_ClassIDsNoOrientationIndices]).TupleSin());
        hv_DirectionLength1Col = HTuple(hv_Phi[hv_ClassIDsNoOrientationIndices]).TupleCos();
        hv_DirectionLength2Row = -hv_DirectionLength1Col;
        hv_DirectionLength2Col = hv_DirectionLength1Row;
        hv_Corner1Row = (HTuple(hv_Length1[hv_ClassIDsNoOrientationIndices])*hv_DirectionLength1Row)+(HTuple(hv_Length2[hv_ClassIDsNoOrientationIndices])*hv_DirectionLength2Row);
        hv_Corner1Col = (HTuple(hv_Length1[hv_ClassIDsNoOrientationIndices])*hv_DirectionLength1Col)+(HTuple(hv_Length2[hv_ClassIDsNoOrientationIndices])*hv_DirectionLength2Col);
        hv_Corner2Row = (HTuple(hv_Length1[hv_ClassIDsNoOrientationIndices])*hv_DirectionLength1Row)-(HTuple(hv_Length2[hv_ClassIDsNoOrientationIndices])*hv_DirectionLength2Row);
        hv_Corner2Col = (HTuple(hv_Length1[hv_ClassIDsNoOrientationIndices])*hv_DirectionLength1Col)-(HTuple(hv_Length2[hv_ClassIDsNoOrientationIndices])*hv_DirectionLength2Col);
        //
        hv_Phi[hv_ClassIDsNoOrientationIndices] = 0.0;
        hv_Length1[hv_ClassIDsNoOrientationIndices] = (hv_Corner1Col.TupleAbs()).TupleMax2(hv_Corner2Col.TupleAbs());
        hv_Length2[hv_ClassIDsNoOrientationIndices] = (hv_Corner1Row.TupleAbs()).TupleMax2(hv_Corner2Row.TupleAbs());
      }
      //Clip Phi to [-Pi,Pi].
      hv_Pi = HTuple(180).TupleRad();
      hv_PhiMod = hv_Phi.TupleFmod(2*hv_Pi);
      hv_Phi = hv_PhiMod-(((hv_PhiMod.TupleGreaterElem(hv_Pi))*2)*hv_Pi);
      hv_Phi += ((hv_Phi.TupleLessElem(-hv_Pi))*2)*hv_Pi;
      //Get the scaled bounding box data.
      if (0 != (int(hv_FactorHeight==hv_FactorWidth)))
      {
        //In case the factors in both directions are the same, the scaling
        //is simple and Phi stays unchanged.
        hv_Length1 = hv_Length1*hv_FactorHeight;
        hv_Length2 = hv_Length2*hv_FactorWidth;
        hv_Row = hv_Row*hv_FactorHeight;
        hv_Col = hv_Col*hv_FactorWidth;
      }
      else
      {
        //In case the factors in both directions are not the same, the scaling
        //differs for the two directions.
        scale_rectangle2_bbox(hv_Row, hv_Col, hv_Length1, hv_Length2, hv_Phi, hv_FactorHeight, 
            hv_FactorWidth, &hv_Row, &hv_Col, &hv_Length1, &hv_Length2, &hv_Phi);
      }
      //If 'ignore_direction' is set to true, we need to further process the
      //bounding box parameters so that the following two conditions are met:
      //1) -Pi/2 < Phi <= Pi/2
      //2) Length1 > Length2
      if (0 != hv_IgnoreDirection)
      {
        //-Pi/2 < Phi <= Pi/2
        hv_Phi = hv_Phi-((hv_Phi.TupleGreaterElem(hv_Pi/2))*hv_Pi);
        hv_Phi += (hv_Phi.TupleLessEqualElem((-hv_Pi)/2))*hv_Pi;
        //Ignore classes without orientation.
        hv_Phi[hv_ClassIDsNoOrientationIndices] = 0.0;
        hv_IgnoreMask = HTuple(hv_Phi.TupleLength(),1);
        hv_IgnoreMask[hv_ClassIDsNoOrientationIndices] = 0;
        //Length1 > Length2
        hv_SwapMask = (hv_Length2.TupleGreaterElem(hv_Length1))*hv_IgnoreMask;
        hv_SwapMaskInverted = 1-hv_SwapMask;
        hv_Length1Tmp = hv_Length1*hv_SwapMask;
        hv_Length2Tmp = hv_Length2*hv_SwapMask;
        hv_Length1 = (hv_Length1*hv_SwapMaskInverted)+hv_Length2Tmp;
        hv_Length2 = (hv_Length2*hv_SwapMaskInverted)+hv_Length1Tmp;
        hv_PhiMultMask = ((hv_Phi.TupleLessEqualElem(0))-(hv_Phi.TupleGreaterElem(0)))*hv_SwapMask;
        hv_Phi += (hv_PhiMultMask*hv_Pi)/2;
      }
      //Increase the pre-allocated tuple-length, if necessary.
      if (0 != (int((hv_InstanceCount+(hv_Length1.TupleLength()))>=(hv_Lengths1.TupleLength()))))
      {
        hv_Lengths1 = hv_Lengths1.TupleConcat(HTuple(hv_AllocationBlockLength.TupleMax2(hv_Length1.TupleLength()),0.));
        hv_Lengths2 = hv_Lengths2.TupleConcat(HTuple(hv_AllocationBlockLength.TupleMax2(hv_Length1.TupleLength()),0.));
        hv_Phis = hv_Phis.TupleConcat(HTuple(hv_AllocationBlockLength.TupleMax2(hv_Length1.TupleLength()),0.));
      }
      //Collect the scaled bounding box data.
      hv_Lengths1[HTuple::TupleGenSequence(hv_InstanceCount,(hv_InstanceCount+(hv_Length1.TupleLength()))-1,1)] = hv_Length1;
      hv_Lengths2[HTuple::TupleGenSequence(hv_InstanceCount,(hv_InstanceCount+(hv_Length1.TupleLength()))-1,1)] = hv_Length2;
      hv_Phis[HTuple::TupleGenSequence(hv_InstanceCount,(hv_InstanceCount+(hv_Length1.TupleLength()))-1,1)] = hv_Phi;
      hv_InstanceCount += hv_Length1.TupleLength();
    }
    else
    {
      throw HException("Wrong instance type for deep learning object detection.");
    }
    //
    if (0 != hv_ComputeMaxOverlap)
    {
      //Compute the maximum overlap values (class specific and class agnostic).
      GetDictParam(hv_DLSampleCurrent, "key_exists", "bbox_label_id", &hv_KeyExists);
      if (0 != (hv_KeyExists.TupleNot()))
      {
        throw HException("Bounding box label id is missing. Label id is necessary to compute max_overlap.");
      }
      CreateDict(&hv_BoundingBox);
      GetDictParam(hv_DLSampleCurrent, "key_data_type", "bbox_label_id", &hv___Tmp_Ctrl_Type);
      if (0 != (int(hv___Tmp_Ctrl_Type==HTuple("object"))))
      {
        SetDictObject(hv_DLSampleCurrent.TupleGetDictObject("bbox_label_id"), hv_BoundingBox, 
            "label_id");
      }
      else
      {
        SetDictTuple(hv_BoundingBox, "label_id", hv_DLSampleCurrent.TupleGetDictTuple("bbox_label_id"));
      }
      if (0 != (int(hv_InstanceType==HTuple("rectangle1"))))
      {
        SetDictTuple(hv_BoundingBox, "row1", hv_Row1);
        SetDictTuple(hv_BoundingBox, "col1", hv_Col1);
        SetDictTuple(hv_BoundingBox, "row2", hv_Row2);
        SetDictTuple(hv_BoundingBox, "col2", hv_Col2);
      }
      else if (0 != (int(hv_InstanceType==HTuple("rectangle2"))))
      {
        SetDictTuple(hv_BoundingBox, "row", hv_Row);
        SetDictTuple(hv_BoundingBox, "col", hv_Col);
        SetDictTuple(hv_BoundingBox, "length1", hv_Length1);
        SetDictTuple(hv_BoundingBox, "length2", hv_Length2);
        SetDictTuple(hv_BoundingBox, "phi", hv_Phi);
      }
      compute_max_overlap(hv_BoundingBox, hv_MaxOverlapDict);
    }
  }
  }
  //
  //
  if (0 != hv_ComputeMaxOverlap)
  {
    //Suppress outliers in IoU.
    hv_IdxsWithOverlap = ((hv_MaxOverlapDict.TupleGetDictTuple("max_overlaps_class_agnostic")).TupleGreaterElem(0)).TupleFind(1);
    hv_Percentile = 0.99;
    if (0 != (int(HTuple(hv_IdxsWithOverlap[0])>-1)))
    {
      tuple_percentile(HTuple((hv_MaxOverlapDict.TupleGetDictTuple("max_overlaps_class_agnostic"))[hv_IdxsWithOverlap]), 
          hv_Percentile, &(*hv_MaxOverlapClassAgnostic));
    }
    hv_IdxsWithOverlap = ((hv_MaxOverlapDict.TupleGetDictTuple("max_overlaps")).TupleGreaterElem(0)).TupleFind(1);
    if (0 != (int(HTuple(hv_IdxsWithOverlap[0])>-1)))
    {
      tuple_percentile(HTuple((hv_MaxOverlapDict.TupleGetDictTuple("max_overlaps"))[hv_IdxsWithOverlap]), 
          hv_Percentile, &(*hv_MaxOverlap));
    }
    //
    //Relax the max overlap values.
    hv_RelaxFactor = 1.1;
    (*hv_MaxOverlap) = ((((hv_RelaxFactor*(*hv_MaxOverlap))*100.).TupleRound())/100.).TupleMin2(1.0);
    (*hv_MaxOverlapClassAgnostic) = ((((hv_RelaxFactor*(*hv_MaxOverlapClassAgnostic))*100.).TupleRound())/100.).TupleMin2(1.0);
  }
  //
  //
  //Compute the areas and aspect ratios of all bounding boxes. Also set the
  //output angles in case of rectangle2.
  if (0 != (int(hv_InstanceType==HTuple("rectangle1"))))
  {
    //Remove unused pre-allocated memory from box parameter tuples.
    hv_Rows1 = hv_Rows1.TupleSelectRange(0,hv_InstanceCount-1);
    hv_Rows2 = hv_Rows2.TupleSelectRange(0,hv_InstanceCount-1);
    hv_Cols1 = hv_Cols1.TupleSelectRange(0,hv_InstanceCount-1);
    hv_Cols2 = hv_Cols2.TupleSelectRange(0,hv_InstanceCount-1);
    //
    hv_Heights = hv_Rows2-hv_Rows1;
    hv_Widths = hv_Cols2-hv_Cols1;
    (*hv_Areas) = hv_Heights*hv_Widths;
    (*hv_AspectRatios) = hv_Heights/(hv_Widths.TupleReal());
  }
  else if (0 != (int(hv_InstanceType==HTuple("rectangle2"))))
  {
    //Remove unused pre-allocated memory from box parameter tuples.
    hv_Lengths1 = hv_Lengths1.TupleSelectRange(0,hv_InstanceCount-1);
    hv_Lengths2 = hv_Lengths2.TupleSelectRange(0,hv_InstanceCount-1);
    hv_Phis = hv_Phis.TupleSelectRange(0,hv_InstanceCount-1);
    //
    (*hv_Areas) = (4*hv_Lengths1)*hv_Lengths2;
    (*hv_AspectRatios) = hv_Lengths2/(hv_Lengths1.TupleReal());
    (*hv_Angles) = hv_Phis;
  }
  //
  return;
}

// Chapter: Graphics / Output
// Short Description: Reflect the pose change that was introduced by the user by moving the mouse 
void analyze_graph_event (HObject ho_BackgroundImage, HTuple hv_Parameters, HTuple hv_MouseMapping, 
    HTuple hv_Button, HTuple hv_Row, HTuple hv_Column, HTuple hv_WindowHandle, HTuple hv_WindowHandleBuffer, 
    HTuple hv_VirtualTrackball, HTuple hv_TrackballSize, HTuple hv_SelectedObjectIn, 
    HTuple hv_Scene3D, HTuple hv_AlphaOrig, HTuple hv_ObjectModel3DID, HTuple hv_CamParam, 
    HTuple hv_Labels, HTuple hv_Title, HTuple hv_Information, HTuple hv_GenParamName, 
    HTuple hv_GenParamValue, HTuple hv_PosesIn, HTuple hv_ButtonHoldIn, HTuple hv_TBCenter, 
    HTuple hv_TBSize, HTuple hv_WindowCenteredRotationlIn, HTuple hv_MaxNumModels, 
    HTuple hv_MessageQueue, HTuple *hv_PosesOut, HTuple *hv_SelectedObjectOut, HTuple *hv_ButtonHoldOut, 
    HTuple *hv_WindowCenteredRotationOut)
{

  // Local iconic variables
  HObject  ho_ImageDump;

  // Local control variables
  HTuple  hv_VisualizeTB, hv_InvLog2, hv_Seconds;
  HTuple  hv_ModelIndex, hv_Exception1, hv_HomMat3DIdentity;
  HTuple  hv_NumModels, hv_Width, hv_Height, hv_MinImageSize;
  HTuple  hv_TrackballRadiusPixel, hv_TrackballCenterRow;
  HTuple  hv_TrackballCenterCol, hv_gIsSinglePose, hv_NumChannels;
  HTuple  hv_ColorImage, hv_BAnd, hv_SensFactor, hv_IsButtonTrans;
  HTuple  hv_IsButtonRot, hv_IsButtonDist, hv_MRow1, hv_MCol1;
  HTuple  hv_ButtonLoop, hv_MRow2, hv_MCol2, hv_PX, hv_PY;
  HTuple  hv_PZ, hv_QX1, hv_QY1, hv_QZ1, hv_QX2, hv_QY2, hv_QZ2;
  HTuple  hv_Len, hv_Dist, hv_Translate, hv_Index, hv_PoseIn;
  HTuple  hv_HomMat3DIn, hv_HomMat3DOut, hv_PoseOut, hv_Indices;
  HTuple  hv_Sequence, hv_Mod, hv_SequenceReal, hv_Sequence2Int;
  HTuple  hv_Selected, hv_InvSelected, hv_Exception, hv_DRow;
  HTuple  hv_TranslateZ, hv_MX1, hv_MY1, hv_MX2, hv_MY2, hv_RelQuaternion;
  HTuple  hv_HomMat3DRotRel, hv_HomMat3DInTmp1, hv_HomMat3DInTmp;
  HTuple  hv_PosesOut2;

  //This procedure reflects
  //- the pose change that was introduced by the user by
  //  moving the mouse
  //- the selection of a single object
  //
  (*hv_ButtonHoldOut) = hv_ButtonHoldIn;
  (*hv_PosesOut) = hv_PosesIn;
  (*hv_SelectedObjectOut) = hv_SelectedObjectIn;
  (*hv_WindowCenteredRotationOut) = hv_WindowCenteredRotationlIn;
  hv_VisualizeTB = int(((*hv_SelectedObjectOut).TupleMax())!=0);
  hv_InvLog2 = 1.0/(HTuple(2).TupleLog());
  //
  if (0 != (int(hv_Button==HTuple(hv_MouseMapping[6]))))
  {
    if (0 != (*hv_ButtonHoldOut))
    {
      return;
    }
    //Ctrl (16) + Alt (32) + left mouse button (1) => Toggle rotation center position
    //If WindowCenteredRotation is not 1, set it to 1, otherwise, set it to 2
    CountSeconds(&hv_Seconds);
    if (0 != (int((*hv_WindowCenteredRotationOut)==1)))
    {
      (*hv_WindowCenteredRotationOut) = 2;
    }
    else
    {
      (*hv_WindowCenteredRotationOut) = 1;
    }
    (*hv_ButtonHoldOut) = 1;
    return;
  }
  if (0 != (HTuple(int(hv_Button==HTuple(hv_MouseMapping[5]))).TupleAnd(int((hv_ObjectModel3DID.TupleLength())<=hv_MaxNumModels))))
  {
    if (0 != (*hv_ButtonHoldOut))
    {
      return;
    }
    //Ctrl (16) + left mouse button (1) => Select an object
    try
    {
      SetScene3dParam(hv_Scene3D, "object_index_persistence", "true");
      DisplayScene3d(hv_WindowHandleBuffer, hv_Scene3D, 0);
      GetDisplayScene3dInfo(hv_WindowHandleBuffer, hv_Scene3D, hv_Row, hv_Column, 
          "object_index", &hv_ModelIndex);
      SetScene3dParam(hv_Scene3D, "object_index_persistence", "false");
    }
    // catch (Exception1) 
    catch (HException &HDevExpDefaultException)
    {
      HDevExpDefaultException.ToHTuple(&hv_Exception1);
      //* NO OpenGL, no selection possible
      return;
    }
    if (0 != (int(hv_ModelIndex==-1)))
    {
      //Background click:
      if (0 != (int(((*hv_SelectedObjectOut).TupleSum())==((*hv_SelectedObjectOut).TupleLength()))))
      {
        //If all objects are already selected, deselect all
        (*hv_SelectedObjectOut) = HTuple(hv_ObjectModel3DID.TupleLength(),0);
      }
      else
      {
        //Otherwise select all
        (*hv_SelectedObjectOut) = HTuple(hv_ObjectModel3DID.TupleLength(),1);
      }
    }
    else
    {
      //Object click:
      (*hv_SelectedObjectOut)[hv_ModelIndex] = HTuple((*hv_SelectedObjectOut)[hv_ModelIndex]).TupleNot();
    }
    (*hv_ButtonHoldOut) = 1;
  }
  else
  {
    //Change the pose
    HomMat3dIdentity(&hv_HomMat3DIdentity);
    hv_NumModels = hv_ObjectModel3DID.TupleLength();
    get_cam_par_data(hv_CamParam, "image_width", &hv_Width);
    get_cam_par_data(hv_CamParam, "image_height", &hv_Height);
    hv_MinImageSize = (hv_Width.TupleConcat(hv_Height)).TupleMin();
    hv_TrackballRadiusPixel = (hv_TrackballSize*hv_MinImageSize)/2.0;
    //Set trackball fixed in the center of the window
    hv_TrackballCenterRow = hv_Height/2;
    hv_TrackballCenterCol = hv_Width/2;
    if (0 != (int((hv_ObjectModel3DID.TupleLength())<hv_MaxNumModels)))
    {
      if (0 != (int((*hv_WindowCenteredRotationOut)==1)))
      {
        get_trackball_center_fixed(hv_SelectedObjectIn, hv_TrackballCenterRow, hv_TrackballCenterCol, 
            hv_TrackballRadiusPixel, hv_Scene3D, hv_ObjectModel3DID, hv_PosesIn, 
            hv_WindowHandleBuffer, hv_CamParam, hv_GenParamName, hv_GenParamValue, 
            &hv_TBCenter, &hv_TBSize);
      }
      else
      {
        get_trackball_center(hv_SelectedObjectIn, hv_TrackballRadiusPixel, hv_ObjectModel3DID, 
            hv_PosesIn, &hv_TBCenter, &hv_TBSize);
      }
    }
    if (0 != (HTuple(int(((*hv_SelectedObjectOut).TupleMin())==0)).TupleAnd(int(((*hv_SelectedObjectOut).TupleMax())==1))))
    {
      //At this point, multiple objects do not necessary have the same
      //pose any more. Consequently, we have to return a tuple of poses
      //as output of visualize_object_model_3d
      hv_gIsSinglePose = 0;
      SetMessageTuple(hv_Parameters, "gIsSinglePose", hv_gIsSinglePose);
    }
    CountChannels(ho_BackgroundImage, &hv_NumChannels);
    hv_ColorImage = int(hv_NumChannels==3);
    //Alt (32) => lower sensitivity
    TupleRsh(hv_Button, 5, &hv_BAnd);
    if (0 != (hv_BAnd%2))
    {
      hv_SensFactor = 0.1;
    }
    else
    {
      hv_SensFactor = 1.0;
    }
    hv_IsButtonTrans = HTuple(int(HTuple(hv_MouseMapping[0])==hv_Button)).TupleOr(int((32+HTuple(hv_MouseMapping[0]))==hv_Button));
    hv_IsButtonRot = HTuple(int(HTuple(hv_MouseMapping[1])==hv_Button)).TupleOr(int((32+HTuple(hv_MouseMapping[1]))==hv_Button));
    hv_IsButtonDist = HTuple(HTuple(HTuple(HTuple(HTuple(int(HTuple(hv_MouseMapping[2])==hv_Button)).TupleOr(int((32+HTuple(hv_MouseMapping[2]))==hv_Button))).TupleOr(int(HTuple(hv_MouseMapping[3])==hv_Button))).TupleOr(int((32+HTuple(hv_MouseMapping[3]))==hv_Button))).TupleOr(int(HTuple(hv_MouseMapping[4])==hv_Button))).TupleOr(int((32+HTuple(hv_MouseMapping[4]))==hv_Button));
    if (0 != hv_IsButtonTrans)
    {
      //Translate in XY-direction
      hv_MRow1 = hv_Row;
      hv_MCol1 = hv_Column;
      while (0 != hv_IsButtonTrans)
      {
        try
        {
          get_mouse_info(hv_WindowHandle, hv_MessageQueue, HTuple(), &hv_Row, &hv_Column, 
              &hv_ButtonLoop);
          hv_IsButtonTrans = int(hv_ButtonLoop==hv_Button);
          hv_MRow2 = hv_MRow1+((hv_Row-hv_MRow1)*hv_SensFactor);
          hv_MCol2 = hv_MCol1+((hv_Column-hv_MCol1)*hv_SensFactor);
          GetLineOfSight(hv_MRow1, hv_MCol1, hv_CamParam, &hv_PX, &hv_PY, &hv_PZ, 
              &hv_QX1, &hv_QY1, &hv_QZ1);
          GetLineOfSight(hv_MRow2, hv_MCol2, hv_CamParam, &hv_PX, &hv_PY, &hv_PZ, 
              &hv_QX2, &hv_QY2, &hv_QZ2);
          hv_Len = (((hv_QX1*hv_QX1)+(hv_QY1*hv_QY1))+(hv_QZ1*hv_QZ1)).TupleSqrt();
          hv_Dist = (((HTuple(hv_TBCenter[0])*HTuple(hv_TBCenter[0]))+(HTuple(hv_TBCenter[1])*HTuple(hv_TBCenter[1])))+(HTuple(hv_TBCenter[2])*HTuple(hv_TBCenter[2]))).TupleSqrt();
          hv_Translate = ((((hv_QX2-hv_QX1).TupleConcat(hv_QY2-hv_QY1)).TupleConcat(hv_QZ2-hv_QZ1))*hv_Dist)/hv_Len;
          (*hv_PosesOut) = HTuple();
          if (0 != (int(hv_NumModels<=hv_MaxNumModels)))
          {
            {
            HTuple end_val109 = hv_NumModels-1;
            HTuple step_val109 = 1;
            for (hv_Index=0; hv_Index.Continue(end_val109, step_val109); hv_Index += step_val109)
            {
              hv_PoseIn = hv_PosesIn.TupleSelectRange(hv_Index*7,(hv_Index*7)+6);
              if (0 != (HTuple((*hv_SelectedObjectOut)[hv_Index])))
              {
                PoseToHomMat3d(hv_PoseIn, &hv_HomMat3DIn);
                HomMat3dTranslate(hv_HomMat3DIn, HTuple(hv_Translate[0]), HTuple(hv_Translate[1]), 
                    HTuple(hv_Translate[2]), &hv_HomMat3DOut);
                HomMat3dToPose(hv_HomMat3DOut, &hv_PoseOut);
                SetScene3dInstancePose(hv_Scene3D, hv_Index, hv_PoseOut);
              }
              else
              {
                hv_PoseOut = hv_PoseIn;
              }
              (*hv_PosesOut) = (*hv_PosesOut).TupleConcat(hv_PoseOut);
            }
            }
          }
          else
          {
            TupleFind((*hv_SelectedObjectOut), 1, &hv_Indices);
            hv_PoseIn = hv_PosesIn.TupleSelectRange(HTuple(hv_Indices[0])*7,(HTuple(hv_Indices[0])*7)+6);
            PoseToHomMat3d(hv_PoseIn, &hv_HomMat3DIn);
            HomMat3dTranslate(hv_HomMat3DIn, HTuple(hv_Translate[0]), HTuple(hv_Translate[1]), 
                HTuple(hv_Translate[2]), &hv_HomMat3DOut);
            HomMat3dToPose(hv_HomMat3DOut, &hv_PoseOut);
            hv_Sequence = HTuple::TupleGenSequence(0,(hv_NumModels*7)-1,1);
            TupleMod(hv_Sequence, 7, &hv_Mod);
            hv_SequenceReal = HTuple::TupleGenSequence(0,hv_NumModels-(1.0/7.0),1.0/7.0);
            hv_Sequence2Int = hv_SequenceReal.TupleInt();
            TupleSelect((*hv_SelectedObjectOut), hv_Sequence2Int, &hv_Selected);
            hv_InvSelected = 1-hv_Selected;
            TupleSelect(hv_PoseOut, hv_Mod, &(*hv_PosesOut));
            (*hv_PosesOut) = ((*hv_PosesOut)*hv_Selected)+(hv_PosesIn*hv_InvSelected);
            SetScene3dInstancePose(hv_Scene3D, HTuple::TupleGenSequence(0,hv_NumModels-1,1), 
                (*hv_PosesOut));
          }
          dump_image_output(ho_BackgroundImage, hv_Parameters, hv_WindowHandleBuffer, 
              hv_Scene3D, hv_AlphaOrig, hv_ObjectModel3DID, hv_GenParamName, hv_GenParamValue, 
              hv_CamParam, (*hv_PosesOut), hv_ColorImage, hv_Title, hv_Information, 
              hv_Labels, hv_VisualizeTB, "true", hv_TrackballCenterRow, hv_TrackballCenterCol, 
              hv_TBSize, (*hv_SelectedObjectOut), int((*hv_WindowCenteredRotationOut)==1), 
              hv_TBCenter, HTuple(), HTuple(), HTuple(), HTuple());
          DumpWindowImage(&ho_ImageDump, hv_WindowHandleBuffer);
          //dev_set_window (WindowHandle)
          //dev_display (ImageDump)
          DispObj(ho_ImageDump, hv_WindowHandle);
          send_pose_update(hv_Parameters, (*hv_PosesOut));
          //
          hv_MRow1 = hv_Row;
          hv_MCol1 = hv_Column;
          hv_PosesIn = (*hv_PosesOut);
        }
        // catch (Exception) 
        catch (HException &HDevExpDefaultException)
        {
          HDevExpDefaultException.ToHTuple(&hv_Exception);
          //Keep waiting
        }
      }
    }
    else if (0 != hv_IsButtonDist)
    {
      //Change the Z distance
      hv_MRow1 = hv_Row;
      while (0 != hv_IsButtonDist)
      {
        try
        {
          get_mouse_info(hv_WindowHandle, hv_MessageQueue, HTuple(), &hv_Row, &hv_Column, 
              &hv_ButtonLoop);
          hv_IsButtonDist = int(hv_ButtonLoop==hv_Button);
          hv_MRow2 = hv_Row;
          hv_DRow = hv_MRow2-hv_MRow1;
          hv_Dist = (((HTuple(hv_TBCenter[0])*HTuple(hv_TBCenter[0]))+(HTuple(hv_TBCenter[1])*HTuple(hv_TBCenter[1])))+(HTuple(hv_TBCenter[2])*HTuple(hv_TBCenter[2]))).TupleSqrt();
          hv_TranslateZ = (((-hv_Dist)*hv_DRow)*0.003)*hv_SensFactor;
          hv_TBCenter[2] = HTuple(hv_TBCenter[2])+hv_TranslateZ;
          (*hv_PosesOut) = HTuple();
          if (0 != (int(hv_NumModels<=hv_MaxNumModels)))
          {
            {
            HTuple end_val165 = hv_NumModels-1;
            HTuple step_val165 = 1;
            for (hv_Index=0; hv_Index.Continue(end_val165, step_val165); hv_Index += step_val165)
            {
              hv_PoseIn = hv_PosesIn.TupleSelectRange(hv_Index*7,(hv_Index*7)+6);
              if (0 != (HTuple((*hv_SelectedObjectOut)[hv_Index])))
              {
                //Transform the whole scene or selected object only
                PoseToHomMat3d(hv_PoseIn, &hv_HomMat3DIn);
                HomMat3dTranslate(hv_HomMat3DIn, 0, 0, hv_TranslateZ, &hv_HomMat3DOut);
                HomMat3dToPose(hv_HomMat3DOut, &hv_PoseOut);
                SetScene3dInstancePose(hv_Scene3D, hv_Index, hv_PoseOut);
              }
              else
              {
                hv_PoseOut = hv_PoseIn;
              }
              (*hv_PosesOut) = (*hv_PosesOut).TupleConcat(hv_PoseOut);
            }
            }
          }
          else
          {
            TupleFind((*hv_SelectedObjectOut), 1, &hv_Indices);
            hv_PoseIn = hv_PosesIn.TupleSelectRange(HTuple(hv_Indices[0])*7,(HTuple(hv_Indices[0])*7)+6);
            PoseToHomMat3d(hv_PoseIn, &hv_HomMat3DIn);
            HomMat3dTranslate(hv_HomMat3DIn, 0, 0, hv_TranslateZ, &hv_HomMat3DOut);
            HomMat3dToPose(hv_HomMat3DOut, &hv_PoseOut);
            hv_Sequence = HTuple::TupleGenSequence(0,(hv_NumModels*7)-1,1);
            TupleMod(hv_Sequence, 7, &hv_Mod);
            hv_SequenceReal = HTuple::TupleGenSequence(0,hv_NumModels-(1.0/7.0),1.0/7.0);
            hv_Sequence2Int = hv_SequenceReal.TupleInt();
            TupleSelect((*hv_SelectedObjectOut), hv_Sequence2Int, &hv_Selected);
            hv_InvSelected = 1-hv_Selected;
            TupleSelect(hv_PoseOut, hv_Mod, &(*hv_PosesOut));
            (*hv_PosesOut) = ((*hv_PosesOut)*hv_Selected)+(hv_PosesIn*hv_InvSelected);
            SetScene3dInstancePose(hv_Scene3D, HTuple::TupleGenSequence(0,hv_NumModels-1,1), 
                (*hv_PosesOut));
          }
          dump_image_output(ho_BackgroundImage, hv_Parameters, hv_WindowHandleBuffer, 
              hv_Scene3D, hv_AlphaOrig, hv_ObjectModel3DID, hv_GenParamName, hv_GenParamValue, 
              hv_CamParam, (*hv_PosesOut), hv_ColorImage, hv_Title, hv_Information, 
              hv_Labels, hv_VisualizeTB, "true", hv_TrackballCenterRow, hv_TrackballCenterCol, 
              hv_TBSize, (*hv_SelectedObjectOut), (*hv_WindowCenteredRotationOut), 
              hv_TBCenter, HTuple(), HTuple(), HTuple(), HTuple());
          DumpWindowImage(&ho_ImageDump, hv_WindowHandleBuffer);
          //dev_set_window (WindowHandle)
          //dev_display (ImageDump)
          DispObj(ho_ImageDump, hv_WindowHandle);
          send_pose_update(hv_Parameters, (*hv_PosesOut));
          //
          hv_MRow1 = hv_Row;
          hv_PosesIn = (*hv_PosesOut);
        }
        // catch (Exception) 
        catch (HException &HDevExpDefaultException)
        {
          HDevExpDefaultException.ToHTuple(&hv_Exception);
          //Keep waiting
        }
      }
    }
    else if (0 != hv_IsButtonRot)
    {
      //Rotate the object
      hv_MRow1 = hv_Row;
      hv_MCol1 = hv_Column;
      while (0 != hv_IsButtonRot)
      {
        try
        {
          get_mouse_info(hv_WindowHandle, hv_MessageQueue, HTuple(), &hv_Row, &hv_Column, 
              &hv_ButtonLoop);
          hv_IsButtonRot = int(hv_ButtonLoop==hv_Button);
          hv_MRow2 = hv_Row;
          hv_MCol2 = hv_Column;
          //Transform the pixel coordinates to relative image coordinates
          hv_MX1 = (hv_TrackballCenterCol-hv_MCol1)/(0.5*hv_MinImageSize);
          hv_MY1 = (hv_TrackballCenterRow-hv_MRow1)/(0.5*hv_MinImageSize);
          hv_MX2 = (hv_TrackballCenterCol-hv_MCol2)/(0.5*hv_MinImageSize);
          hv_MY2 = (hv_TrackballCenterRow-hv_MRow2)/(0.5*hv_MinImageSize);
          //Compute the quaternion rotation that corresponds to the mouse
          //movement
          trackball(hv_MX1, hv_MY1, hv_MX2, hv_MY2, hv_VirtualTrackball, hv_TrackballSize, 
              hv_SensFactor, &hv_RelQuaternion);
          //Transform the quaternion to a rotation matrix
          QuatToHomMat3d(hv_RelQuaternion, &hv_HomMat3DRotRel);
          (*hv_PosesOut) = HTuple();
          if (0 != (int(hv_NumModels<=hv_MaxNumModels)))
          {
            {
            HTuple end_val229 = hv_NumModels-1;
            HTuple step_val229 = 1;
            for (hv_Index=0; hv_Index.Continue(end_val229, step_val229); hv_Index += step_val229)
            {
              hv_PoseIn = hv_PosesIn.TupleSelectRange(hv_Index*7,(hv_Index*7)+6);
              if (0 != (HTuple((*hv_SelectedObjectOut)[hv_Index])))
              {
                //Transform the whole scene or selected object only
                PoseToHomMat3d(hv_PoseIn, &hv_HomMat3DIn);
                HomMat3dTranslate(hv_HomMat3DIn, -HTuple(hv_TBCenter[0]), -HTuple(hv_TBCenter[1]), 
                    -HTuple(hv_TBCenter[2]), &hv_HomMat3DIn);
                HomMat3dCompose(hv_HomMat3DRotRel, hv_HomMat3DIn, &hv_HomMat3DIn);
                HomMat3dTranslate(hv_HomMat3DIn, HTuple(hv_TBCenter[0]), HTuple(hv_TBCenter[1]), 
                    HTuple(hv_TBCenter[2]), &hv_HomMat3DOut);
                HomMat3dToPose(hv_HomMat3DOut, &hv_PoseOut);
                SetScene3dInstancePose(hv_Scene3D, hv_Index, hv_PoseOut);
              }
              else
              {
                hv_PoseOut = hv_PoseIn;
              }
              (*hv_PosesOut) = (*hv_PosesOut).TupleConcat(hv_PoseOut);
            }
            }
          }
          else
          {
            TupleFind((*hv_SelectedObjectOut), 1, &hv_Indices);
            hv_PoseIn = hv_PosesIn.TupleSelectRange(HTuple(hv_Indices[0])*7,(HTuple(hv_Indices[0])*7)+6);
            PoseToHomMat3d(hv_PoseIn, &hv_HomMat3DIn);
            HomMat3dTranslate(hv_HomMat3DIn, -HTuple(hv_TBCenter[0]), -HTuple(hv_TBCenter[1]), 
                -HTuple(hv_TBCenter[2]), &hv_HomMat3DInTmp1);
            HomMat3dCompose(hv_HomMat3DRotRel, hv_HomMat3DInTmp1, &hv_HomMat3DInTmp);
            HomMat3dTranslate(hv_HomMat3DInTmp, HTuple(hv_TBCenter[0]), HTuple(hv_TBCenter[1]), 
                HTuple(hv_TBCenter[2]), &hv_HomMat3DOut);
            HomMat3dToPose(hv_HomMat3DOut, &hv_PoseOut);
            hv_Sequence = HTuple::TupleGenSequence(0,(hv_NumModels*7)-1,1);
            TupleMod(hv_Sequence, 7, &hv_Mod);
            hv_SequenceReal = HTuple::TupleGenSequence(0,hv_NumModels-(1.0/7.0),1.0/7.0);
            hv_Sequence2Int = hv_SequenceReal.TupleInt();
            TupleSelect((*hv_SelectedObjectOut), hv_Sequence2Int, &hv_Selected);
            hv_InvSelected = 1-hv_Selected;
            TupleSelect(hv_PoseOut, hv_Mod, &(*hv_PosesOut));
            hv_PosesOut2 = ((*hv_PosesOut)*hv_Selected)+(hv_PosesIn*hv_InvSelected);
            (*hv_PosesOut) = hv_PosesOut2;
            SetScene3dInstancePose(hv_Scene3D, HTuple::TupleGenSequence(0,hv_NumModels-1,1), 
                (*hv_PosesOut));
          }
          dump_image_output(ho_BackgroundImage, hv_Parameters, hv_WindowHandleBuffer, 
              hv_Scene3D, hv_AlphaOrig, hv_ObjectModel3DID, hv_GenParamName, hv_GenParamValue, 
              hv_CamParam, (*hv_PosesOut), hv_ColorImage, hv_Title, hv_Information, 
              hv_Labels, hv_VisualizeTB, "true", hv_TrackballCenterRow, hv_TrackballCenterCol, 
              hv_TBSize, (*hv_SelectedObjectOut), (*hv_WindowCenteredRotationOut), 
              hv_TBCenter, HTuple(), HTuple(), HTuple(), HTuple());
          DumpWindowImage(&ho_ImageDump, hv_WindowHandleBuffer);
          //dev_set_window (WindowHandle)
          //dev_display (ImageDump)
          DispObj(ho_ImageDump, hv_WindowHandle);
          send_pose_update(hv_Parameters, (*hv_PosesOut));
          //
          hv_MRow1 = hv_Row;
          hv_MCol1 = hv_Column;
          hv_PosesIn = (*hv_PosesOut);
        }
        // catch (Exception) 
        catch (HException &HDevExpDefaultException)
        {
          HDevExpDefaultException.ToHTuple(&hv_Exception);
          //Keep waiting
        }
      }
    }
    (*hv_PosesOut) = hv_PosesIn;
  }
  return;
}

// Chapter: Graphics / Output
// Short Description: Reflect the pose change that was introduced by the user by moving the mouse 
void analyze_graph_event_visualize_object_model_3d (HObject ho_BackgroundImage, HTuple hv_MouseMapping, 
    HTuple hv_Button, HTuple hv_Row, HTuple hv_Column, HTuple hv_WindowHandle, HTuple hv_WindowHandleBuffer, 
    HTuple hv_VirtualTrackball, HTuple hv_TrackballSize, HTuple hv_SelectedObjectIn, 
    HTuple hv_Scene3D, HTuple hv_AlphaOrig, HTuple hv_ObjectModel3DID, HTuple hv_CamParam, 
    HTuple hv_Labels, HTuple hv_Title, HTuple hv_Information, HTuple hv_GenParamName, 
    HTuple hv_GenParamValue, HTuple hv_PosesIn, HTuple hv_ButtonHoldIn, HTuple hv_TBCenter, 
    HTuple hv_TBSize, HTuple hv_WindowCenteredRotationlIn, HTuple hv_MaxNumModels, 
    HTuple *hv_PosesOut, HTuple *hv_SelectedObjectOut, HTuple *hv_ButtonHoldOut, 
    HTuple *hv_WindowCenteredRotationOut)
{

  // Local iconic variables
  HObject  ho_ImageDump;

  // Local control variables
  HTuple  ExpTmpLocalVar_gIsSinglePose, hv_VisualizeTB;
  HTuple  hv_InvLog2, hv_Seconds, hv_ModelIndex, hv_Exception1;
  HTuple  hv_HomMat3DIdentity, hv_NumModels, hv_Width, hv_Height;
  HTuple  hv_MinImageSize, hv_TrackballRadiusPixel, hv_TrackballCenterRow;
  HTuple  hv_TrackballCenterCol, hv_NumChannels, hv_ColorImage;
  HTuple  hv_BAnd, hv_SensFactor, hv_IsButtonTrans, hv_IsButtonRot;
  HTuple  hv_IsButtonDist, hv_MRow1, hv_MCol1, hv_ButtonLoop;
  HTuple  hv_MRow2, hv_MCol2, hv_PX, hv_PY, hv_PZ, hv_QX1;
  HTuple  hv_QY1, hv_QZ1, hv_QX2, hv_QY2, hv_QZ2, hv_Len;
  HTuple  hv_Dist, hv_Translate, hv_Index, hv_PoseIn, hv_HomMat3DIn;
  HTuple  hv_HomMat3DOut, hv_PoseOut, hv_Indices, hv_Sequence;
  HTuple  hv_Mod, hv_SequenceReal, hv_Sequence2Int, hv_Selected;
  HTuple  hv_InvSelected, hv_Exception, hv_DRow, hv_TranslateZ;
  HTuple  hv_MX1, hv_MY1, hv_MX2, hv_MY2, hv_RelQuaternion;
  HTuple  hv_HomMat3DRotRel, hv_HomMat3DInTmp1, hv_HomMat3DInTmp;
  HTuple  hv_PosesOut2;

  //This procedure reflects
  //- the pose change that was introduced by the user by
  //  moving the mouse
  //- the selection of a single object
  //
  //global tuple gIsSinglePose
  //
  (*hv_ButtonHoldOut) = hv_ButtonHoldIn;
  (*hv_PosesOut) = hv_PosesIn;
  (*hv_SelectedObjectOut) = hv_SelectedObjectIn;
  (*hv_WindowCenteredRotationOut) = hv_WindowCenteredRotationlIn;
  hv_VisualizeTB = int(((*hv_SelectedObjectOut).TupleMax())!=0);
  hv_InvLog2 = 1.0/(HTuple(2).TupleLog());
  //
  if (0 != (int(hv_Button==HTuple(hv_MouseMapping[6]))))
  {
    if (0 != (*hv_ButtonHoldOut))
    {
      return;
    }
    //Ctrl (16) + Alt (32) + left mouse button (1) => Toggle rotation center position
    //If WindowCenteredRotation is not 1, set it to 1, otherwise, set it to 2
    CountSeconds(&hv_Seconds);
    if (0 != (int((*hv_WindowCenteredRotationOut)==1)))
    {
      (*hv_WindowCenteredRotationOut) = 2;
    }
    else
    {
      (*hv_WindowCenteredRotationOut) = 1;
    }
    (*hv_ButtonHoldOut) = 1;
    return;
  }
  if (0 != (HTuple(int(hv_Button==HTuple(hv_MouseMapping[5]))).TupleAnd(int((hv_ObjectModel3DID.TupleLength())<=hv_MaxNumModels))))
  {
    if (0 != (*hv_ButtonHoldOut))
    {
      return;
    }
    //Ctrl (16) + left mouse button (1) => Select an object
    try
    {
      SetScene3dParam(hv_Scene3D, "object_index_persistence", "true");
      DisplayScene3d(hv_WindowHandleBuffer, hv_Scene3D, 0);
      GetDisplayScene3dInfo(hv_WindowHandleBuffer, hv_Scene3D, hv_Row, hv_Column, 
          "object_index", &hv_ModelIndex);
      SetScene3dParam(hv_Scene3D, "object_index_persistence", "false");
    }
    // catch (Exception1) 
    catch (HException &HDevExpDefaultException)
    {
      HDevExpDefaultException.ToHTuple(&hv_Exception1);
      //* NO OpenGL, no selection possible
      return;
    }
    if (0 != (int(hv_ModelIndex==-1)))
    {
      //Background click:
      if (0 != (int(((*hv_SelectedObjectOut).TupleSum())==((*hv_SelectedObjectOut).TupleLength()))))
      {
        //If all objects are already selected, deselect all
        (*hv_SelectedObjectOut) = HTuple(hv_ObjectModel3DID.TupleLength(),0);
      }
      else
      {
        //Otherwise select all
        (*hv_SelectedObjectOut) = HTuple(hv_ObjectModel3DID.TupleLength(),1);
      }
    }
    else
    {
      //Object click:
      (*hv_SelectedObjectOut)[hv_ModelIndex] = HTuple((*hv_SelectedObjectOut)[hv_ModelIndex]).TupleNot();
    }
    (*hv_ButtonHoldOut) = 1;
  }
  else
  {
    //Change the pose
    HomMat3dIdentity(&hv_HomMat3DIdentity);
    hv_NumModels = hv_ObjectModel3DID.TupleLength();
    get_cam_par_data(hv_CamParam, "image_width", &hv_Width);
    get_cam_par_data(hv_CamParam, "image_height", &hv_Height);
    hv_MinImageSize = (hv_Width.TupleConcat(hv_Height)).TupleMin();
    hv_TrackballRadiusPixel = (hv_TrackballSize*hv_MinImageSize)/2.0;
    //Set trackball fixed in the center of the window
    hv_TrackballCenterRow = hv_Height/2;
    hv_TrackballCenterCol = hv_Width/2;
    if (0 != (int((hv_ObjectModel3DID.TupleLength())<hv_MaxNumModels)))
    {
      if (0 != (int((*hv_WindowCenteredRotationOut)==1)))
      {
        get_trackball_center_fixed_visualize_object_model_3d(hv_SelectedObjectIn, 
            hv_TrackballCenterRow, hv_TrackballCenterCol, hv_TrackballRadiusPixel, 
            hv_Scene3D, hv_ObjectModel3DID, hv_PosesIn, hv_WindowHandleBuffer, hv_CamParam, 
            hv_GenParamName, hv_GenParamValue, &hv_TBCenter, &hv_TBSize);
      }
      else
      {
        get_trackball_center_visualize_object_model_3d(hv_SelectedObjectIn, hv_TrackballRadiusPixel, 
            hv_ObjectModel3DID, hv_PosesIn, &hv_TBCenter, &hv_TBSize);
      }
    }
    if (0 != (HTuple(int(((*hv_SelectedObjectOut).TupleMin())==0)).TupleAnd(int(((*hv_SelectedObjectOut).TupleMax())==1))))
    {
      //At this point, multiple objects do not necessary have the same
      //pose any more. Consequently, we have to return a tuple of poses
      //as output of visualize_object_model_3d
      ExpTmpLocalVar_gIsSinglePose = 0;
      ExpSetGlobalVar_gIsSinglePose(ExpTmpLocalVar_gIsSinglePose);
    }
    CountChannels(ho_BackgroundImage, &hv_NumChannels);
    hv_ColorImage = int(hv_NumChannels==3);
    //Alt (32) => lower sensitivity
    TupleRsh(hv_Button, 5, &hv_BAnd);
    if (0 != (hv_BAnd%2))
    {
      hv_SensFactor = 0.1;
    }
    else
    {
      hv_SensFactor = 1.0;
    }
    hv_IsButtonTrans = HTuple(int(HTuple(hv_MouseMapping[0])==hv_Button)).TupleOr(int((32+HTuple(hv_MouseMapping[0]))==hv_Button));
    hv_IsButtonRot = HTuple(int(HTuple(hv_MouseMapping[1])==hv_Button)).TupleOr(int((32+HTuple(hv_MouseMapping[1]))==hv_Button));
    hv_IsButtonDist = HTuple(HTuple(HTuple(HTuple(HTuple(int(HTuple(hv_MouseMapping[2])==hv_Button)).TupleOr(int((32+HTuple(hv_MouseMapping[2]))==hv_Button))).TupleOr(int(HTuple(hv_MouseMapping[3])==hv_Button))).TupleOr(int((32+HTuple(hv_MouseMapping[3]))==hv_Button))).TupleOr(int(HTuple(hv_MouseMapping[4])==hv_Button))).TupleOr(int((32+HTuple(hv_MouseMapping[4]))==hv_Button));
    if (0 != hv_IsButtonTrans)
    {
      //Translate in XY-direction
      hv_MRow1 = hv_Row;
      hv_MCol1 = hv_Column;
      while (0 != hv_IsButtonTrans)
      {
        try
        {
          GetMpositionSubPix(hv_WindowHandle, &hv_Row, &hv_Column, &hv_ButtonLoop);
          hv_IsButtonTrans = int(hv_ButtonLoop==hv_Button);
          hv_MRow2 = hv_MRow1+((hv_Row-hv_MRow1)*hv_SensFactor);
          hv_MCol2 = hv_MCol1+((hv_Column-hv_MCol1)*hv_SensFactor);
          GetLineOfSight(hv_MRow1, hv_MCol1, hv_CamParam, &hv_PX, &hv_PY, &hv_PZ, 
              &hv_QX1, &hv_QY1, &hv_QZ1);
          GetLineOfSight(hv_MRow2, hv_MCol2, hv_CamParam, &hv_PX, &hv_PY, &hv_PZ, 
              &hv_QX2, &hv_QY2, &hv_QZ2);
          hv_Len = (((hv_QX1*hv_QX1)+(hv_QY1*hv_QY1))+(hv_QZ1*hv_QZ1)).TupleSqrt();
          hv_Dist = (((HTuple(hv_TBCenter[0])*HTuple(hv_TBCenter[0]))+(HTuple(hv_TBCenter[1])*HTuple(hv_TBCenter[1])))+(HTuple(hv_TBCenter[2])*HTuple(hv_TBCenter[2]))).TupleSqrt();
          hv_Translate = ((((hv_QX2-hv_QX1).TupleConcat(hv_QY2-hv_QY1)).TupleConcat(hv_QZ2-hv_QZ1))*hv_Dist)/hv_Len;
          (*hv_PosesOut) = HTuple();
          if (0 != (int(hv_NumModels<=hv_MaxNumModels)))
          {
            {
            HTuple end_val110 = hv_NumModels-1;
            HTuple step_val110 = 1;
            for (hv_Index=0; hv_Index.Continue(end_val110, step_val110); hv_Index += step_val110)
            {
              hv_PoseIn = hv_PosesIn.TupleSelectRange(hv_Index*7,(hv_Index*7)+6);
              if (0 != (HTuple((*hv_SelectedObjectOut)[hv_Index])))
              {
                PoseToHomMat3d(hv_PoseIn, &hv_HomMat3DIn);
                HomMat3dTranslate(hv_HomMat3DIn, HTuple(hv_Translate[0]), HTuple(hv_Translate[1]), 
                    HTuple(hv_Translate[2]), &hv_HomMat3DOut);
                HomMat3dToPose(hv_HomMat3DOut, &hv_PoseOut);
                SetScene3dInstancePose(hv_Scene3D, hv_Index, hv_PoseOut);
              }
              else
              {
                hv_PoseOut = hv_PoseIn;
              }
              (*hv_PosesOut) = (*hv_PosesOut).TupleConcat(hv_PoseOut);
            }
            }
          }
          else
          {
            TupleFind((*hv_SelectedObjectOut), 1, &hv_Indices);
            hv_PoseIn = hv_PosesIn.TupleSelectRange(HTuple(hv_Indices[0])*7,(HTuple(hv_Indices[0])*7)+6);
            PoseToHomMat3d(hv_PoseIn, &hv_HomMat3DIn);
            HomMat3dTranslate(hv_HomMat3DIn, HTuple(hv_Translate[0]), HTuple(hv_Translate[1]), 
                HTuple(hv_Translate[2]), &hv_HomMat3DOut);
            HomMat3dToPose(hv_HomMat3DOut, &hv_PoseOut);
            hv_Sequence = HTuple::TupleGenSequence(0,(hv_NumModels*7)-1,1);
            TupleMod(hv_Sequence, 7, &hv_Mod);
            hv_SequenceReal = HTuple::TupleGenSequence(0,hv_NumModels-(1.0/7.0),1.0/7.0);
            hv_Sequence2Int = hv_SequenceReal.TupleInt();
            TupleSelect((*hv_SelectedObjectOut), hv_Sequence2Int, &hv_Selected);
            hv_InvSelected = 1-hv_Selected;
            TupleSelect(hv_PoseOut, hv_Mod, &(*hv_PosesOut));
            (*hv_PosesOut) = ((*hv_PosesOut)*hv_Selected)+(hv_PosesIn*hv_InvSelected);
            SetScene3dInstancePose(hv_Scene3D, HTuple::TupleGenSequence(0,hv_NumModels-1,1), 
                (*hv_PosesOut));
          }
          dump_image_output_visualize_object_model_3d(ho_BackgroundImage, hv_WindowHandleBuffer, 
              hv_Scene3D, hv_AlphaOrig, hv_ObjectModel3DID, hv_GenParamName, hv_GenParamValue, 
              hv_CamParam, (*hv_PosesOut), hv_ColorImage, hv_Title, hv_Information, 
              hv_Labels, hv_VisualizeTB, "true", hv_TrackballCenterRow, hv_TrackballCenterCol, 
              hv_TBSize, (*hv_SelectedObjectOut), int((*hv_WindowCenteredRotationOut)==1), 
              hv_TBCenter);
          DumpWindowImage(&ho_ImageDump, hv_WindowHandleBuffer);
          HDevWindowStack::SetActive(hv_WindowHandle);
          if (HDevWindowStack::IsOpen())
            DispObj(ho_ImageDump, HDevWindowStack::GetActive());
          //
          hv_MRow1 = hv_Row;
          hv_MCol1 = hv_Column;
          hv_PosesIn = (*hv_PosesOut);
        }
        // catch (Exception) 
        catch (HException &HDevExpDefaultException)
        {
          HDevExpDefaultException.ToHTuple(&hv_Exception);
          //Keep waiting
        }
      }
    }
    else if (0 != hv_IsButtonDist)
    {
      //Change the Z distance
      hv_MRow1 = hv_Row;
      while (0 != hv_IsButtonDist)
      {
        try
        {
          GetMpositionSubPix(hv_WindowHandle, &hv_Row, &hv_Column, &hv_ButtonLoop);
          hv_IsButtonDist = int(hv_ButtonLoop==hv_Button);
          hv_MRow2 = hv_Row;
          hv_DRow = hv_MRow2-hv_MRow1;
          hv_Dist = (((HTuple(hv_TBCenter[0])*HTuple(hv_TBCenter[0]))+(HTuple(hv_TBCenter[1])*HTuple(hv_TBCenter[1])))+(HTuple(hv_TBCenter[2])*HTuple(hv_TBCenter[2]))).TupleSqrt();
          hv_TranslateZ = (((-hv_Dist)*hv_DRow)*0.003)*hv_SensFactor;
          hv_TBCenter[2] = HTuple(hv_TBCenter[2])+hv_TranslateZ;
          (*hv_PosesOut) = HTuple();
          if (0 != (int(hv_NumModels<=hv_MaxNumModels)))
          {
            {
            HTuple end_val164 = hv_NumModels-1;
            HTuple step_val164 = 1;
            for (hv_Index=0; hv_Index.Continue(end_val164, step_val164); hv_Index += step_val164)
            {
              hv_PoseIn = hv_PosesIn.TupleSelectRange(hv_Index*7,(hv_Index*7)+6);
              if (0 != (HTuple((*hv_SelectedObjectOut)[hv_Index])))
              {
                //Transform the whole scene or selected object only
                PoseToHomMat3d(hv_PoseIn, &hv_HomMat3DIn);
                HomMat3dTranslate(hv_HomMat3DIn, 0, 0, hv_TranslateZ, &hv_HomMat3DOut);
                HomMat3dToPose(hv_HomMat3DOut, &hv_PoseOut);
                SetScene3dInstancePose(hv_Scene3D, hv_Index, hv_PoseOut);
              }
              else
              {
                hv_PoseOut = hv_PoseIn;
              }
              (*hv_PosesOut) = (*hv_PosesOut).TupleConcat(hv_PoseOut);
            }
            }
          }
          else
          {
            TupleFind((*hv_SelectedObjectOut), 1, &hv_Indices);
            hv_PoseIn = hv_PosesIn.TupleSelectRange(HTuple(hv_Indices[0])*7,(HTuple(hv_Indices[0])*7)+6);
            PoseToHomMat3d(hv_PoseIn, &hv_HomMat3DIn);
            HomMat3dTranslate(hv_HomMat3DIn, 0, 0, hv_TranslateZ, &hv_HomMat3DOut);
            HomMat3dToPose(hv_HomMat3DOut, &hv_PoseOut);
            hv_Sequence = HTuple::TupleGenSequence(0,(hv_NumModels*7)-1,1);
            TupleMod(hv_Sequence, 7, &hv_Mod);
            hv_SequenceReal = HTuple::TupleGenSequence(0,hv_NumModels-(1.0/7.0),1.0/7.0);
            hv_Sequence2Int = hv_SequenceReal.TupleInt();
            TupleSelect((*hv_SelectedObjectOut), hv_Sequence2Int, &hv_Selected);
            hv_InvSelected = 1-hv_Selected;
            TupleSelect(hv_PoseOut, hv_Mod, &(*hv_PosesOut));
            (*hv_PosesOut) = ((*hv_PosesOut)*hv_Selected)+(hv_PosesIn*hv_InvSelected);
            SetScene3dInstancePose(hv_Scene3D, HTuple::TupleGenSequence(0,hv_NumModels-1,1), 
                (*hv_PosesOut));
          }
          dump_image_output_visualize_object_model_3d(ho_BackgroundImage, hv_WindowHandleBuffer, 
              hv_Scene3D, hv_AlphaOrig, hv_ObjectModel3DID, hv_GenParamName, hv_GenParamValue, 
              hv_CamParam, (*hv_PosesOut), hv_ColorImage, hv_Title, hv_Information, 
              hv_Labels, hv_VisualizeTB, "true", hv_TrackballCenterRow, hv_TrackballCenterCol, 
              hv_TBSize, (*hv_SelectedObjectOut), (*hv_WindowCenteredRotationOut), 
              hv_TBCenter);
          DumpWindowImage(&ho_ImageDump, hv_WindowHandleBuffer);
          HDevWindowStack::SetActive(hv_WindowHandle);
          if (HDevWindowStack::IsOpen())
            DispObj(ho_ImageDump, HDevWindowStack::GetActive());
          //
          hv_MRow1 = hv_Row;
          hv_PosesIn = (*hv_PosesOut);
        }
        // catch (Exception) 
        catch (HException &HDevExpDefaultException)
        {
          HDevExpDefaultException.ToHTuple(&hv_Exception);
          //Keep waiting
        }
      }
    }
    else if (0 != hv_IsButtonRot)
    {
      //Rotate the object
      hv_MRow1 = hv_Row;
      hv_MCol1 = hv_Column;
      while (0 != hv_IsButtonRot)
      {
        try
        {
          GetMpositionSubPix(hv_WindowHandle, &hv_Row, &hv_Column, &hv_ButtonLoop);
          hv_IsButtonRot = int(hv_ButtonLoop==hv_Button);
          hv_MRow2 = hv_Row;
          hv_MCol2 = hv_Column;
          //Transform the pixel coordinates to relative image coordinates
          hv_MX1 = (hv_TrackballCenterCol-hv_MCol1)/(0.5*hv_MinImageSize);
          hv_MY1 = (hv_TrackballCenterRow-hv_MRow1)/(0.5*hv_MinImageSize);
          hv_MX2 = (hv_TrackballCenterCol-hv_MCol2)/(0.5*hv_MinImageSize);
          hv_MY2 = (hv_TrackballCenterRow-hv_MRow2)/(0.5*hv_MinImageSize);
          //Compute the quaternion rotation that corresponds to the mouse
          //movement
          trackball_visualize_object_model_3d(hv_MX1, hv_MY1, hv_MX2, hv_MY2, hv_VirtualTrackball, 
              hv_TrackballSize, hv_SensFactor, &hv_RelQuaternion);
          //Transform the quaternion to a rotation matrix
          QuatToHomMat3d(hv_RelQuaternion, &hv_HomMat3DRotRel);
          (*hv_PosesOut) = HTuple();
          if (0 != (int(hv_NumModels<=hv_MaxNumModels)))
          {
            {
            HTuple end_val226 = hv_NumModels-1;
            HTuple step_val226 = 1;
            for (hv_Index=0; hv_Index.Continue(end_val226, step_val226); hv_Index += step_val226)
            {
              hv_PoseIn = hv_PosesIn.TupleSelectRange(hv_Index*7,(hv_Index*7)+6);
              if (0 != (HTuple((*hv_SelectedObjectOut)[hv_Index])))
              {
                //Transform the whole scene or selected object only
                PoseToHomMat3d(hv_PoseIn, &hv_HomMat3DIn);
                HomMat3dTranslate(hv_HomMat3DIn, -HTuple(hv_TBCenter[0]), -HTuple(hv_TBCenter[1]), 
                    -HTuple(hv_TBCenter[2]), &hv_HomMat3DIn);
                HomMat3dCompose(hv_HomMat3DRotRel, hv_HomMat3DIn, &hv_HomMat3DIn);
                HomMat3dTranslate(hv_HomMat3DIn, HTuple(hv_TBCenter[0]), HTuple(hv_TBCenter[1]), 
                    HTuple(hv_TBCenter[2]), &hv_HomMat3DOut);
                HomMat3dToPose(hv_HomMat3DOut, &hv_PoseOut);
                SetScene3dInstancePose(hv_Scene3D, hv_Index, hv_PoseOut);
              }
              else
              {
                hv_PoseOut = hv_PoseIn;
              }
              (*hv_PosesOut) = (*hv_PosesOut).TupleConcat(hv_PoseOut);
            }
            }
          }
          else
          {
            TupleFind((*hv_SelectedObjectOut), 1, &hv_Indices);
            hv_PoseIn = hv_PosesIn.TupleSelectRange(HTuple(hv_Indices[0])*7,(HTuple(hv_Indices[0])*7)+6);
            PoseToHomMat3d(hv_PoseIn, &hv_HomMat3DIn);
            HomMat3dTranslate(hv_HomMat3DIn, -HTuple(hv_TBCenter[0]), -HTuple(hv_TBCenter[1]), 
                -HTuple(hv_TBCenter[2]), &hv_HomMat3DInTmp1);
            HomMat3dCompose(hv_HomMat3DRotRel, hv_HomMat3DInTmp1, &hv_HomMat3DInTmp);
            HomMat3dTranslate(hv_HomMat3DInTmp, HTuple(hv_TBCenter[0]), HTuple(hv_TBCenter[1]), 
                HTuple(hv_TBCenter[2]), &hv_HomMat3DOut);
            HomMat3dToPose(hv_HomMat3DOut, &hv_PoseOut);
            hv_Sequence = HTuple::TupleGenSequence(0,(hv_NumModels*7)-1,1);
            TupleMod(hv_Sequence, 7, &hv_Mod);
            hv_SequenceReal = HTuple::TupleGenSequence(0,hv_NumModels-(1.0/7.0),1.0/7.0);
            hv_Sequence2Int = hv_SequenceReal.TupleInt();
            TupleSelect((*hv_SelectedObjectOut), hv_Sequence2Int, &hv_Selected);
            hv_InvSelected = 1-hv_Selected;
            TupleSelect(hv_PoseOut, hv_Mod, &(*hv_PosesOut));
            hv_PosesOut2 = ((*hv_PosesOut)*hv_Selected)+(hv_PosesIn*hv_InvSelected);
            (*hv_PosesOut) = hv_PosesOut2;
            SetScene3dInstancePose(hv_Scene3D, HTuple::TupleGenSequence(0,hv_NumModels-1,1), 
                (*hv_PosesOut));
          }
          dump_image_output_visualize_object_model_3d(ho_BackgroundImage, hv_WindowHandleBuffer, 
              hv_Scene3D, hv_AlphaOrig, hv_ObjectModel3DID, hv_GenParamName, hv_GenParamValue, 
              hv_CamParam, (*hv_PosesOut), hv_ColorImage, hv_Title, hv_Information, 
              hv_Labels, hv_VisualizeTB, "true", hv_TrackballCenterRow, hv_TrackballCenterCol, 
              hv_TBSize, (*hv_SelectedObjectOut), (*hv_WindowCenteredRotationOut), 
              hv_TBCenter);
          DumpWindowImage(&ho_ImageDump, hv_WindowHandleBuffer);
          HDevWindowStack::SetActive(hv_WindowHandle);
          if (HDevWindowStack::IsOpen())
            DispObj(ho_ImageDump, HDevWindowStack::GetActive());
          //
          hv_MRow1 = hv_Row;
          hv_MCol1 = hv_Column;
          hv_PosesIn = (*hv_PosesOut);
        }
        // catch (Exception) 
        catch (HException &HDevExpDefaultException)
        {
          HDevExpDefaultException.ToHTuple(&hv_Exception);
          //Keep waiting
        }
      }
    }
    (*hv_PosesOut) = hv_PosesIn;
  }
  return;
}

// Chapter: Classification / Misc
// Short Description: Extend results - auxiliary procedure for get_custom_features and get_features. 
void append_length_or_values (HTuple hv_Mode, HTuple hv_Feature, HTuple hv_AccumulatedResults, 
    HTuple *hv_ExtendedResults)
{

  // Local iconic variables

  //
  //Auxiliary procedure used only by get_features and get_custom_features
  //
  if (0 != (int(hv_Mode==HTuple("get_lengths"))))
  {
    //Output in 'get_lengths' mode is the length of the feature
    (*hv_ExtendedResults).Clear();
    (*hv_ExtendedResults).Append(hv_AccumulatedResults);
    (*hv_ExtendedResults).Append(hv_Feature.TupleLength());
  }
  else if (0 != (int(hv_Mode==HTuple("calculate"))))
  {
    //Output in 'calculate' mode is the feature vector
    (*hv_ExtendedResults).Clear();
    (*hv_ExtendedResults).Append(hv_AccumulatedResults);
    (*hv_ExtendedResults).Append(hv_Feature);
  }
  else
  {
    (*hv_ExtendedResults) = hv_AccumulatedResults;
  }
  return;
}

// Chapter: Classification / Misc
// Short Description: Extend results - auxiliary procedure for get_custom_features and get_features. 
void append_names_or_groups (HTuple hv_Mode, HTuple hv_Name, HTuple hv_Groups, HTuple hv_CurrentName, 
    HTuple hv_AccumulatedResults, HTuple *hv_ExtendedResults)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_FirstOccurrence, hv_BelongsToGroup;

  //
  //Auxiliary procedure used only by get_features and get_custom_features
  //
  (*hv_ExtendedResults) = hv_AccumulatedResults;
  if (0 != (int(hv_Mode==HTuple("get_names"))))
  {
    hv_FirstOccurrence = HTuple(int((hv_AccumulatedResults.TupleLength())==0)).TupleOr(int((hv_AccumulatedResults.TupleFind(hv_Name))==-1));
    hv_BelongsToGroup = HTuple(int(((hv_Name.TupleConcat(hv_Groups)).TupleFind(hv_CurrentName))!=-1)).TupleOr(int(hv_CurrentName==HTuple("all")));
    if (0 != (hv_FirstOccurrence.TupleAnd(hv_BelongsToGroup)))
    {
      //Output in 'get_names' mode is the name of the feature
      (*hv_ExtendedResults).Clear();
      (*hv_ExtendedResults).Append(hv_AccumulatedResults);
      (*hv_ExtendedResults).Append(hv_Name);
    }
  }
  else if (0 != (int(hv_Mode==HTuple("get_groups"))))
  {
    (*hv_ExtendedResults).Clear();
    (*hv_ExtendedResults).Append(hv_AccumulatedResults);
    (*hv_ExtendedResults).Append(hv_Groups);
  }
  return;
}

// Chapter: Classification / Misc
// Short Description: Extend results - auxiliary procedure for get_features. 
void append_names_or_groups_pyramid (HTuple hv_Mode, HTuple hv_Groups, HTuple hv_CurrentName, 
    HTuple hv_Names, HTuple hv_NameRegExp, HTuple hv_AccumulatedResults, HTuple *hv_ExtendedResults)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_BelongsToGroup, hv_TmpNames, hv_J;
  HTuple  hv_FirstOccurrence;

  //
  //Auxiliary procedure used only by get_features and get_custom_features
  //
  (*hv_ExtendedResults) = hv_AccumulatedResults;
  if (0 != (int(hv_Mode==HTuple("get_names"))))
  {
    hv_BelongsToGroup = HTuple(int((hv_Groups.TupleFind(hv_CurrentName))!=-1)).TupleOr(int(hv_CurrentName==HTuple("all")));
    if (0 != (hv_CurrentName.TupleRegexpTest(hv_NameRegExp)))
    {
      hv_Names = hv_CurrentName;
    }
    else if (0 != (hv_BelongsToGroup.TupleNot()))
    {
      hv_Names = HTuple();
    }
    hv_TmpNames = HTuple();
    {
    HTuple end_val12 = (hv_Names.TupleLength())-1;
    HTuple step_val12 = 1;
    for (hv_J=0; hv_J.Continue(end_val12, step_val12); hv_J += step_val12)
    {
      hv_FirstOccurrence = HTuple(int((hv_AccumulatedResults.TupleLength())==0)).TupleOr(int((hv_AccumulatedResults.TupleFind(HTuple(hv_Names[hv_J])))==-1));
      if (0 != hv_FirstOccurrence)
      {
        //Output in 'get_names' mode is the name of the feature
        hv_TmpNames = hv_TmpNames.TupleConcat(HTuple(hv_Names[hv_J]));
      }
    }
    }
    (*hv_ExtendedResults).Clear();
    (*hv_ExtendedResults).Append(hv_AccumulatedResults);
    (*hv_ExtendedResults).Append(hv_TmpNames);
  }
  else if (0 != (int(hv_Mode==HTuple("get_groups"))))
  {
    (*hv_ExtendedResults).Clear();
    (*hv_ExtendedResults).Append(hv_AccumulatedResults);
    (*hv_ExtendedResults).Append(hv_Groups);
  }
  return;
}

// Chapter: Image / Manipulation
void apply_brightness_variation_spot (HObject ho_Image, HObject *ho_ImageSpot, HTuple hv_SpotSize, 
    HTuple hv_SpotRow, HTuple hv_SpotColumn, HTuple hv_BrightnessVariation)
{

  // Local iconic variables
  HObject  ho_Filter, ho_GaussImage, ho_GaussFilter;
  HObject  ho_Gauss, ho_GaussTargetType, ho_AddImage;

  // Local control variables
  HTuple  hv_Direction, hv_Width, hv_Height, hv_ShiftRow;
  HTuple  hv_ShiftCol, hv_Type, hv_NChannels, hv_Index1;

  //This procedure applies a brightness spot
  //of a given intensity and size at a given location
  //to the input image.
  //The modified image is returned in ImageSpot.
  //
  if (0 != (int(hv_BrightnessVariation<0)))
  {
    hv_Direction = 0;
    hv_BrightnessVariation = -hv_BrightnessVariation;
  }
  else
  {
    hv_Direction = 1;
  }
  GetImageSize(ho_Image, &hv_Width, &hv_Height);
  //Generate Gauss filter that simulates an illumination spot of size 'SpotSize'.
  GenGaussFilter(&ho_Filter, 1, 1, 0, "none", "dc_center", hv_SpotSize, hv_SpotSize);
  //Shift the filter image to the given position.
  hv_ShiftRow = -((hv_SpotSize/2)-hv_SpotRow);
  hv_ShiftCol = -((hv_SpotSize/2)-hv_SpotColumn);
  TileImagesOffset(ho_Filter, &ho_GaussImage, hv_ShiftRow, hv_ShiftCol, -1, -1, -1, 
      -1, hv_Width, hv_Height);
  FullDomain(ho_GaussImage, &ho_GaussFilter);
  //Convert Gauss filter to target image type and apply brightness variation.
  GetImageType(ho_Image, &hv_Type);
  ScaleImage(ho_GaussFilter, &ho_Gauss, hv_BrightnessVariation, 0);
  ConvertImageType(ho_Gauss, &ho_GaussTargetType, hv_Type);
  //Add channels to fit input image.
  CountChannels(ho_Image, &hv_NChannels);
  CopyObj(ho_GaussTargetType, &ho_AddImage, 1, 1);
  {
  HTuple end_val26 = hv_NChannels-1;
  HTuple step_val26 = 1;
  for (hv_Index1=1; hv_Index1.Continue(end_val26, step_val26); hv_Index1 += step_val26)
  {
    AppendChannel(ho_AddImage, ho_GaussTargetType, &ho_AddImage);
  }
  }
  //Apply on image.
  if (0 != hv_Direction)
  {
    AddImage(ho_Image, ho_AddImage, &(*ho_ImageSpot), 1, 0);
  }
  else
  {
    SubImage(ho_Image, ho_AddImage, &(*ho_ImageSpot), 1, 0);
  }
  return;
}

// Chapter: Image / Channel
// Short Description: Create a lookup table and convert a gray scale image. 
void apply_colorscheme_on_gray_value_image (HObject ho_InputImage, HObject *ho_ResultImage, 
    HTuple hv_Schema)
{

  // Local iconic variables
  HObject  ho_ImageR, ho_ImageG, ho_ImageB;

  // Local control variables
  HTuple  hv_X, hv_Low, hv_High, hv_OffR, hv_OffG;
  HTuple  hv_OffB, hv_A1, hv_A0, hv_R, hv_G, hv_B, hv_A0R;
  HTuple  hv_A0G, hv_A0B;

  //
  //This procedure generates an RGB ResultImage for a gray-value InputImage.
  //In order to do so, create a color distribution as look up table
  //according to the Schema.
  //
  hv_X = HTuple::TupleGenSequence(0,255,1);
  TupleGenConst(256, 0, &hv_Low);
  TupleGenConst(256, 255, &hv_High);
  //
  if (0 != (int(hv_Schema==HTuple("jet"))))
  {
    //Scheme Jet: from blue to red
    hv_OffR = 3.0*64.0;
    hv_OffG = 2.0*64.0;
    hv_OffB = 64.0;
    hv_A1 = -4.0;
    hv_A0 = 255.0+128.0;
    hv_R = (((((hv_X-hv_OffR).TupleAbs())*hv_A1)+hv_A0).TupleMax2(hv_Low)).TupleMin2(hv_High);
    hv_G = (((((hv_X-hv_OffG).TupleAbs())*hv_A1)+hv_A0).TupleMax2(hv_Low)).TupleMin2(hv_High);
    hv_B = (((((hv_X-hv_OffB).TupleAbs())*hv_A1)+hv_A0).TupleMax2(hv_Low)).TupleMin2(hv_High);
    //
  }
  else if (0 != (int(hv_Schema==HTuple("inverse_jet"))))
  {
    //Scheme InvJet: from red to blue.
    hv_OffR = 64;
    hv_OffG = 2*64;
    hv_OffB = 3*64;
    hv_A1 = -4.0;
    hv_A0 = 255.0+128.0;
    hv_R = (((((hv_X-hv_OffR).TupleAbs())*hv_A1)+hv_A0).TupleMax2(hv_Low)).TupleMin2(hv_High);
    hv_G = (((((hv_X-hv_OffG).TupleAbs())*hv_A1)+hv_A0).TupleMax2(hv_Low)).TupleMin2(hv_High);
    hv_B = (((((hv_X-hv_OffB).TupleAbs())*hv_A1)+hv_A0).TupleMax2(hv_Low)).TupleMin2(hv_High);
    //
  }
  else if (0 != (int(hv_Schema==HTuple("hot"))))
  {
    //Scheme Hot.
    hv_A1 = 3.0;
    hv_A0R = 0.0;
    hv_A0G = ((1.0/3.0)*hv_A1)*255.0;
    hv_A0B = ((2.0/3.0)*hv_A1)*255.0;
    hv_R = (((hv_X*hv_A1)-hv_A0R).TupleMax2(hv_Low)).TupleMin2(hv_High);
    hv_G = (((hv_X*hv_A1)-hv_A0G).TupleMax2(hv_Low)).TupleMin2(hv_High);
    hv_B = (((hv_X*hv_A1)-hv_A0B).TupleMax2(hv_Low)).TupleMin2(hv_High);
    //
  }
  else if (0 != (int(hv_Schema==HTuple("inverse_hot"))))
  {
    //Scheme Inverse Hot.
    hv_A1 = -3.0;
    hv_A0R = hv_A1*255.0;
    hv_A0G = ((2.0/3.0)*hv_A1)*255.0;
    hv_A0B = ((1.0/3.0)*hv_A1)*255.0;
    hv_R = (((hv_X*hv_A1)-hv_A0R).TupleMax2(hv_Low)).TupleMin2(hv_High);
    hv_G = (((hv_X*hv_A1)-hv_A0G).TupleMax2(hv_Low)).TupleMin2(hv_High);
    hv_B = (((hv_X*hv_A1)-hv_A0B).TupleMax2(hv_Low)).TupleMin2(hv_High);
    //
  }
  else
  {
    //
    throw HException(("Unknown color schema: "+hv_Schema)+".");
    //
  }
  //
  LutTrans(ho_InputImage, &ho_ImageR, hv_R);
  LutTrans(ho_InputImage, &ho_ImageG, hv_G);
  LutTrans(ho_InputImage, &ho_ImageB, hv_B);
  Compose3(ho_ImageR, ho_ImageG, ho_ImageB, &(*ho_ResultImage));
  //
  return;
}

// Chapter: Legacy / DL Classification
// Short Description: Return the classification results for the given images. 
void apply_dl_classifier_batchwise (HTuple hv_ImageFiles, HTuple hv_DLClassifierHandle, 
    HTuple *hv_DLClassifierResultIDs, HTupleVector/*{eTupleVector,Dim=1}*/ *hvec_PredictedClasses, 
    HTupleVector/*{eTupleVector,Dim=1}*/ *hvec_Confidences)
{

  // Local iconic variables
  HObject  ho_BatchImages;

  // Local control variables
  HTuple  hv_BatchSize, hv_NumImages, hv_Sequence;
  HTuple  hv_BatchStartIndex, hv_BatchIndices, hv_BatchImageFiles;
  HTuple  hv_DLClassifierResultID, hv_Exception, hv_NumImagesInBatch;
  HTuple  hv_Index, hv_PredictedClass, hv_ClassConfidence;
  HTuple  hv_VectorIndex;

  //This procedure classifies the images given as paths
  //by ImageFiles using the operator apply_dl_classifier.
  //To avoid that the main memory is overloaded, the images
  //are classified batchwise, according to the hyperparameter 'batch_size',
  //which is stored in the DLClassifierHandle.
  //As result, the classification result handles for every batch
  //are returned in DLClassifierResultIDs.
  //Additionally, for every image the descending sorted
  //Confidences and corresponding PredictedClasses
  //are returned as vectors.
  //
  //Get batch size from handle.
  GetDlClassifierParam(hv_DLClassifierHandle, "batch_size", &hv_BatchSize);
  //
  //Check the input parameters.
  if (0 != (int((hv_ImageFiles.TupleLength())<1)))
  {
    throw HException("ImageFiles must not be empty.");
  }
  //
  //Sequence is used for easier indexing of the images.
  hv_NumImages = hv_ImageFiles.TupleLength();
  hv_Sequence = HTuple::TupleGenSequence(0,hv_NumImages-1,1);
  //
  //Loop through all selected images.
  (*hvec_PredictedClasses) = HTupleVector(1);
  (*hvec_Confidences) = HTupleVector(1);
  (*hv_DLClassifierResultIDs) = HTuple();
  {
  HTuple end_val27 = hv_NumImages-1;
  HTuple step_val27 = hv_BatchSize;
  for (hv_BatchStartIndex=0; hv_BatchStartIndex.Continue(end_val27, step_val27); hv_BatchStartIndex += step_val27)
  {
    //Select the data for the current batch.
    hv_BatchIndices = hv_Sequence.TupleSelectRange(hv_BatchStartIndex,((hv_BatchStartIndex+hv_BatchSize)-1).TupleMin2(hv_NumImages-1));
    hv_BatchImageFiles = HTuple(hv_ImageFiles[hv_BatchIndices]);
    //Read the current batch images.
    ReadImage(&ho_BatchImages, hv_BatchImageFiles);
    //Apply the classifier for this batch.
    try
    {
      ApplyDlClassifier(ho_BatchImages, hv_DLClassifierHandle, &hv_DLClassifierResultID);
    }
    // catch (Exception) 
    catch (HException &HDevExpDefaultException)
    {
      HDevExpDefaultException.ToHTuple(&hv_Exception);
      if (0 != ((HTuple(hv_Exception[0]).TupleEqualElem(((((HTuple(2106).Append(2107)).Append(3122)).Append(9001)).Append(9003)))).TupleSum()))
      {
        throw HException(HTuple("Images need to fulfill the network requirements, please provide preprocessed images."));
      }
      else
      {
        throw HException(hv_Exception);
      }
    }
    //Get results from result handle.
    hv_NumImagesInBatch = hv_BatchImageFiles.TupleLength();
    {
    HTuple end_val45 = hv_NumImagesInBatch-1;
    HTuple step_val45 = 1;
    for (hv_Index=0; hv_Index.Continue(end_val45, step_val45); hv_Index += step_val45)
    {
      GetDlClassifierResult(hv_DLClassifierResultID, hv_Index, "predicted_classes", 
          &hv_PredictedClass);
      GetDlClassifierResult(hv_DLClassifierResultID, hv_Index, "confidences", &hv_ClassConfidence);
      //Store the classification results.
      hv_VectorIndex = hv_BatchStartIndex+hv_Index;
      (*hvec_PredictedClasses)[hv_VectorIndex] = HTupleVector(hv_PredictedClass);
      (*hvec_Confidences)[hv_VectorIndex] = HTupleVector(hv_ClassConfidence);
    }
    }
    (*hv_DLClassifierResultIDs) = (*hv_DLClassifierResultIDs).TupleConcat(hv_DLClassifierResultID);
  }
  }
  return;
}

// Chapter: Deep Learning / Object Detection and Instance Segmentation
void area_iou (HTuple hv_Sample, HTuple hv_Result, HTuple hv_InstanceType, HTuple hv_ResultSortIndices, 
    HTuple *hv_SampleArea, HTuple *hv_ResultArea, HTuple *hv_IoU)
{

  // Local iconic variables
  HObject  ho_GtMask, ho_ResMask, ho_CurrentGtMask;
  HObject  ho_ValidResMask, ho_RegionIntersection;

  // Local control variables
  HTuple  hv_GtRow1, hv_GtCol1, hv_GtRow2, hv_GtCol2;
  HTuple  hv_ResRow1, hv_ResCol1, hv_ResRow2, hv_ResCol2;
  HTuple  hv_GtIdx, hv_Height, hv_Width, hv_ValidIdxs, hv_Intersection;
  HTuple  hv_Union, hv_GtRow, hv_GtCol, hv_GtLength1, hv_GtLength2;
  HTuple  hv_GtPhi, hv_ResRow, hv_ResCol, hv_ResLength1, hv_ResLength2;
  HTuple  hv_ResPhi, hv__, hv_NumGt, hv_NumRes;

  //
  //Compute the intersection over union (IoU) between
  //the ground truth and the inferred bounding box or instance
  //segmentation mask of the object instances.
  //The instance type is determined over the InstanceType.
  //
  if (0 != (int(hv_InstanceType==HTuple("rectangle1"))))
  {
    //Get bounding box coordinates.
    GetDictTuple(hv_Sample, "bbox_row1", &hv_GtRow1);
    GetDictTuple(hv_Sample, "bbox_col1", &hv_GtCol1);
    GetDictTuple(hv_Sample, "bbox_row2", &hv_GtRow2);
    GetDictTuple(hv_Sample, "bbox_col2", &hv_GtCol2);
    GetDictTuple(hv_Result, "bbox_row1", &hv_ResRow1);
    GetDictTuple(hv_Result, "bbox_col1", &hv_ResCol1);
    GetDictTuple(hv_Result, "bbox_row2", &hv_ResRow2);
    GetDictTuple(hv_Result, "bbox_col2", &hv_ResCol2);
    //
    //Sort the results.
    hv_ResRow1 = HTuple(hv_ResRow1[hv_ResultSortIndices]);
    hv_ResCol1 = HTuple(hv_ResCol1[hv_ResultSortIndices]);
    hv_ResRow2 = HTuple(hv_ResRow2[hv_ResultSortIndices]);
    hv_ResCol2 = HTuple(hv_ResCol2[hv_ResultSortIndices]);
    //
    //Compute areas.
    (*hv_SampleArea) = (hv_GtRow2-hv_GtRow1)*(hv_GtCol2-hv_GtCol1);
    (*hv_ResultArea) = (hv_ResRow2-hv_ResRow1)*(hv_ResCol2-hv_ResCol1);
    //
    //Compute IoUs.
    (*hv_IoU) = HTuple((hv_GtRow1.TupleLength())*(hv_ResRow1.TupleLength()),0);
    if (0 != (int(((*hv_IoU).TupleLength())>0)))
    {
      {
      HTuple end_val30 = (hv_GtRow1.TupleLength())-1;
      HTuple step_val30 = 1;
      for (hv_GtIdx=0; hv_GtIdx.Continue(end_val30, step_val30); hv_GtIdx += step_val30)
      {
        hv_Height = (HTuple(hv_GtRow2[hv_GtIdx]).TupleMin2(hv_ResRow2))-(HTuple(hv_GtRow1[hv_GtIdx]).TupleMax2(hv_ResRow1));
        hv_Width = (HTuple(hv_GtCol2[hv_GtIdx]).TupleMin2(hv_ResCol2))-(HTuple(hv_GtCol1[hv_GtIdx]).TupleMax2(hv_ResCol1));
        hv_ValidIdxs = HTuple((hv_Height.TupleGreaterElem(0)).TupleAnd(hv_Width.TupleGreaterElem(0))).TupleFind(1);
        if (0 != (int(hv_ValidIdxs>-1)))
        {
          hv_Intersection = HTuple(hv_Height[hv_ValidIdxs])*HTuple(hv_Width[hv_ValidIdxs]);
          hv_Union = (HTuple((*hv_SampleArea)[hv_GtIdx])+HTuple((*hv_ResultArea)[hv_ValidIdxs]))-hv_Intersection;
          (*hv_IoU)[(hv_GtIdx*(hv_ResRow1.TupleLength()))+hv_ValidIdxs] = (hv_Intersection.TupleReal())/hv_Union;
        }
      }
      }
    }
  }
  else if (0 != (int(hv_InstanceType==HTuple("rectangle2"))))
  {
    //Get bounding box coordinates.
    GetDictTuple(hv_Sample, "bbox_row", &hv_GtRow);
    GetDictTuple(hv_Sample, "bbox_col", &hv_GtCol);
    GetDictTuple(hv_Sample, "bbox_length1", &hv_GtLength1);
    GetDictTuple(hv_Sample, "bbox_length2", &hv_GtLength2);
    GetDictTuple(hv_Sample, "bbox_phi", &hv_GtPhi);
    GetDictTuple(hv_Result, "bbox_row", &hv_ResRow);
    GetDictTuple(hv_Result, "bbox_col", &hv_ResCol);
    GetDictTuple(hv_Result, "bbox_length1", &hv_ResLength1);
    GetDictTuple(hv_Result, "bbox_length2", &hv_ResLength2);
    GetDictTuple(hv_Result, "bbox_phi", &hv_ResPhi);
    //
    //Sort results.
    hv_ResRow = HTuple(hv_ResRow[hv_ResultSortIndices]);
    hv_ResCol = HTuple(hv_ResCol[hv_ResultSortIndices]);
    hv_ResLength1 = HTuple(hv_ResLength1[hv_ResultSortIndices]);
    hv_ResLength2 = HTuple(hv_ResLength2[hv_ResultSortIndices]);
    hv_ResPhi = HTuple(hv_ResPhi[hv_ResultSortIndices]);
    //
    //Compute Areas.
    (*hv_SampleArea) = (4.0*hv_GtLength1)*hv_GtLength2;
    (*hv_ResultArea) = (4.0*hv_ResLength1)*hv_ResLength2;
    //
    //Compute IoUs.
    (*hv_IoU) = HTuple((hv_GtRow.TupleLength())*(hv_ResRow.TupleLength()),0);
    if (0 != (int(((*hv_IoU).TupleLength())>0)))
    {
      {
      HTuple end_val68 = (hv_GtRow.TupleLength())-1;
      HTuple step_val68 = 1;
      for (hv_GtIdx=0; hv_GtIdx.Continue(end_val68, step_val68); hv_GtIdx += step_val68)
      {
        hv_ValidIdxs = HTuple((HTuple((*hv_SampleArea)[hv_GtIdx]).TupleGreaterElem(0)).TupleAnd((*hv_ResultArea).TupleGreaterElem(0))).TupleFind(1);
        if (0 != (int(hv_ValidIdxs>-1)))
        {
          AreaIntersectionRectangle2(HTuple(hv_GtRow[hv_GtIdx]), HTuple(hv_GtCol[hv_GtIdx]), 
              HTuple(hv_GtPhi[hv_GtIdx]), HTuple(hv_GtLength1[hv_GtIdx]), HTuple(hv_GtLength2[hv_GtIdx]), 
              HTuple(hv_ResRow[hv_ValidIdxs]), HTuple(hv_ResCol[hv_ValidIdxs]), HTuple(hv_ResPhi[hv_ValidIdxs]), 
              HTuple(hv_ResLength1[hv_ValidIdxs]), HTuple(hv_ResLength2[hv_ValidIdxs]), 
              &hv_Intersection);
          hv_Union = (HTuple((*hv_SampleArea)[hv_GtIdx])+HTuple((*hv_ResultArea)[hv_ValidIdxs]))-hv_Intersection;
          (*hv_IoU)[(hv_GtIdx*(hv_ResRow.TupleLength()))+hv_ValidIdxs] = (hv_Intersection.TupleReal())/hv_Union;
        }
      }
      }
    }
  }
  else if (0 != (int(hv_InstanceType==HTuple("mask"))))
  {
    //Get the ground truth mask.
    GetDictObject(&ho_GtMask, hv_Sample, "mask");
    //
    //Get the result mask.
    GetDictObject(&ho_ResMask, hv_Result, "mask");
    //
    //Sort the results.
    SelectObj(ho_ResMask, &ho_ResMask, hv_ResultSortIndices+1);
    //
    //Compute Areas.
    AreaCenter(ho_GtMask, &(*hv_SampleArea), &hv__, &hv__);
    AreaCenter(ho_ResMask, &(*hv_ResultArea), &hv__, &hv__);
    //
    //Compute IoUs.
    CountObj(ho_GtMask, &hv_NumGt);
    CountObj(ho_ResMask, &hv_NumRes);
    (*hv_IoU) = HTuple(hv_NumGt*hv_NumRes,0);
    if (0 != (int(((*hv_IoU).TupleLength())>0)))
    {
      {
      HTuple end_val96 = hv_NumGt-1;
      HTuple step_val96 = 1;
      for (hv_GtIdx=0; hv_GtIdx.Continue(end_val96, step_val96); hv_GtIdx += step_val96)
      {
        hv_ValidIdxs = HTuple((HTuple((*hv_SampleArea)[hv_GtIdx]).TupleGreaterElem(0)).TupleAnd((*hv_ResultArea).TupleGreaterElem(0))).TupleFind(1);
        if (0 != (int(hv_ValidIdxs>-1)))
        {
          SelectObj(ho_GtMask, &ho_CurrentGtMask, hv_GtIdx+1);
          SelectObj(ho_ResMask, &ho_ValidResMask, hv_ValidIdxs+1);
          Intersection(ho_ValidResMask, ho_CurrentGtMask, &ho_RegionIntersection);
          AreaCenter(ho_RegionIntersection, &hv_Intersection, &hv__, &hv__);
          hv_Union = (HTuple((*hv_SampleArea)[hv_GtIdx])+HTuple((*hv_ResultArea)[hv_ValidIdxs]))-hv_Intersection;
          (*hv_IoU)[(hv_GtIdx*hv_NumRes)+hv_ValidIdxs] = (hv_Intersection.TupleReal())/hv_Union;
        }
      }
      }
    }
  }
  else
  {
    throw HException(("Instance type '"+hv_InstanceType)+"' is not supported");
  }
  return;
}

// Chapter: Deep Learning / Model
void augment_dl_sample_brightness_variation (HTuple hv_DLSample, HTuple hv_BrightnessVariation)
{

  // Local iconic variables
  HObject  ho_Image, ho_ImageScaled;

  // Local control variables
  HTuple  hv_OCRType, hv_BrightnessShift;

  //This procedure should not be used outside of the augment_dl_samples procedure!
  //The name, parameters, and functionality of this procedure are subject to change.
  //
  //*** Input validation ***
  //
  //For OCR Recognition samples, only a certain range is allowed for BrightnessVariation.
  get_dl_sample_ocr_type(hv_DLSample, &hv_OCRType);
  if (0 != (HTuple(int(hv_OCRType==HTuple("ocr_recognition"))).TupleAnd(int(hv_BrightnessVariation>1))))
  {
    throw HException("Value of augmentation method 'brightness_variation' cannot be greater than 1 for ocr_recognition models.");
  }
  //
  //*** Augmentation ***
  //
  ho_Image = hv_DLSample.TupleGetDictObject("image");
  //
  //Add random brightness variation.
  hv_BrightnessShift = ((HTuple::TupleRand(1)*2)-1)*hv_BrightnessVariation;
  ScaleImage(ho_Image, &ho_ImageScaled, 1.0, hv_BrightnessShift);
  //
  //Set the augmented image to DLSample.
  SetDictObject(ho_ImageScaled, hv_DLSample, "image");
  return;
}

// Chapter: Deep Learning / Model
void augment_dl_sample_brightness_variation_spot (HTuple hv_DLSample, HTuple hv_BrightnessVariation)
{

  // Local iconic variables
  HObject  ho_Image, ho_Filter, ho_GaussImage, ho_GaussFilter;
  HObject  ho_Gauss, ho_GaussTargetType, ho_AddImage, ho_ImageSpot;

  // Local control variables
  HTuple  hv_OCRType, hv_ImageWidth, hv_ImageHeight;
  HTuple  hv_BrightnessShift, hv_SpotSize, hv_SpotRow, hv_SpotColumn;
  HTuple  hv_Direction, hv_ShiftRow, hv_ShiftCol, hv_Type;
  HTuple  hv_NChannels, hv__;

  //This procedure should not be used outside of the augment_dl_samples procedure!
  //The name, parameters, and functionality of this procedure are subject to change.
  //
  //*** Input validation ***
  //
  //This augmentation method should not be applied to OCR Recognition samples.
  get_dl_sample_ocr_type(hv_DLSample, &hv_OCRType);
  if (0 != (int(hv_OCRType==HTuple("ocr_recognition"))))
  {
    throw HException("The augmentation method 'brightness_variation_spot' is not supported by ocr_recognition models.");
  }
  //
  //*** Augmentation ***
  //
  ho_Image = hv_DLSample.TupleGetDictObject("image");
  GetImageSize(ho_Image, &hv_ImageWidth, &hv_ImageHeight);
  //Determine random brightness variation.
  hv_BrightnessShift = ((HTuple::TupleRand(1)*2)-1)*hv_BrightnessVariation;
  //Determine random spot size between [0.5*ImageHeight, ImageWidth]
  hv_SpotSize = hv_ImageWidth*((HTuple::TupleRand(1)/2)+0.5);
  //Determine random spot position.
  hv_SpotRow = HTuple::TupleRand(1)*hv_ImageHeight;
  hv_SpotColumn = HTuple::TupleRand(1)*hv_ImageWidth;
  //
  if (0 != (int(hv_BrightnessShift<0)))
  {
    hv_Direction = 0;
    hv_BrightnessShift = -hv_BrightnessShift;
  }
  else
  {
    hv_Direction = 1;
  }
  //Generate Gauss filter that simulates an illumination spot of size 'SpotSize'.
  GenGaussFilter(&ho_Filter, 1, 1, 0, "none", "dc_center", hv_SpotSize, hv_SpotSize);
  //Shift the filter image to the given position.
  hv_ShiftRow = -((hv_SpotSize/2)-hv_SpotRow);
  hv_ShiftCol = -((hv_SpotSize/2)-hv_SpotColumn);
  TileImagesOffset(ho_Filter, &ho_GaussImage, hv_ShiftRow, hv_ShiftCol, -1, -1, -1, 
      -1, hv_ImageWidth, hv_ImageHeight);
  FullDomain(ho_GaussImage, &ho_GaussFilter);
  //Convert Gauss filter to target image type and apply brightness variation.
  GetImageType(ho_Image, &hv_Type);
  ScaleImage(ho_GaussFilter, &ho_Gauss, hv_BrightnessShift, 0);
  ConvertImageType(ho_Gauss, &ho_GaussTargetType, hv_Type);
  //Add channels to fit input image.
  CountChannels(ho_Image, &hv_NChannels);
  CopyObj(ho_GaussTargetType, &ho_AddImage, 1, 1);
  {
  HTuple end_val43 = hv_NChannels-1;
  HTuple step_val43 = 1;
  for (hv__=1; hv__.Continue(end_val43, step_val43); hv__ += step_val43)
  {
    AppendChannel(ho_AddImage, ho_GaussTargetType, &ho_AddImage);
  }
  }
  //Apply on image.
  if (0 != hv_Direction)
  {
    AddImage(ho_Image, ho_AddImage, &ho_ImageSpot, 1, 0);
  }
  else
  {
    SubImage(ho_Image, ho_AddImage, &ho_ImageSpot, 1, 0);
  }
  //
  //Set the augmented image to DLSample.
  SetDictObject(ho_ImageSpot, hv_DLSample, "image");
  return;
}

// Chapter: Deep Learning / Model
void augment_dl_sample_contrast_variation (HTuple hv_DLSample, HTuple hv_ContrastVariation)
{

  // Local iconic variables
  HObject  ho_Image, ho_GrayImage, ho_MeanImage;
  HObject  ho_MeanImageScaled, ho_ImageScaled, ho_ImageOut;

  // Local control variables
  HTuple  hv_OCRType, hv_Borders, hv_Factor, hv_NumChannels;
  HTuple  hv_MeanGray, hv__;

  //This procedure should not be used outside of the augment_dl_samples procedure!
  //The name, parameters, and functionality of this procedure are subject to change.
  //
  //*** Input validation ***
  //
  //This augmentation method should not be applied to OCR Recognition samples.
  get_dl_sample_ocr_type(hv_DLSample, &hv_OCRType);
  if (0 != (int(hv_OCRType==HTuple("ocr_recognition"))))
  {
    throw HException(("The augmentation method 'contrast_variation' is not supported by "+hv_OCRType)+" models.");
  }
  //
  //*** Augmentation ***
  //
  //Adjust contrast of the input image by blending it with its mean image.
  //
  //Minimum and maximum blend factors.
  hv_Borders.Clear();
  hv_Borders.Append(HTuple(0.0).TupleMax2(1-hv_ContrastVariation));
  hv_Borders.Append(1+hv_ContrastVariation);
  //Random blend factor.
  hv_Factor = HTuple(hv_Borders[0])+((HTuple(hv_Borders[1])-HTuple(hv_Borders[0]))*HTuple::TupleRand(1));
  //
  if (0 != (int(hv_Factor==1.0)))
  {
    return;
  }
  //
  //Convert Image to a gray value image.
  ho_Image = hv_DLSample.TupleGetDictObject("image");
  CountChannels(ho_Image, &hv_NumChannels);
  if (0 != (int(hv_NumChannels==1)))
  {
    ho_GrayImage = ho_Image;
  }
  else if (0 != (int(hv_NumChannels==3)))
  {
    Rgb1ToGray(ho_Image, &ho_GrayImage);
  }
  else
  {
    throw HException("The augmentation method 'contrast_variation' can only be applied to gray scale and RGB images.");
  }
  //
  //Compute the mean of the gray value image.
  Intensity(ho_GrayImage, ho_GrayImage, &hv_MeanGray, &hv__);
  //Create a constant image with the gray value mean.
  GenImageProto(ho_GrayImage, &ho_MeanImage, hv_MeanGray);
  if (0 != (int(hv_NumChannels==3)))
  {
    Compose3(ho_MeanImage, ho_MeanImage, ho_MeanImage, &ho_MeanImage);
  }
  //
  //Blend Image and MeanImage.
  //The resulting ImageOut will have the same domain as Image.
  ScaleImage(ho_MeanImage, &ho_MeanImageScaled, 1.0-hv_Factor, 0.0);
  ScaleImage(ho_Image, &ho_ImageScaled, hv_Factor, 0.0);
  AddImage(ho_MeanImageScaled, ho_ImageScaled, &ho_ImageOut, 1.0, 0.0);
  //
  //Set the augmented image to DLSample.
  SetDictObject(ho_ImageOut, hv_DLSample, "image");
  return;
}

// Chapter: Deep Learning / Model
void augment_dl_sample_crop_percentage (HTuple hv_DLSample, HTuple hv_CropPercentage)
{

  // Local iconic variables
  HObject  ho_Image, ho_ImagePart;

  // Local control variables
  HTuple  hv_ClassificationLabelExists, hv_MLCLabelExists;
  HTuple  hv_XKeyExists, hv_SegmentationImageKeyExists, hv_GrippingPointKeysExists;
  HTuple  hv_ImageWidth, hv_ImageHeight, hv_CropRate, hv_Row1;
  HTuple  hv_Row2, hv_Column1, hv_Column2, hv_Keys, hv_Index;
  HTuple  hv_Key;

  //This procedure should not be used outside of the augment_dl_samples procedure!
  //The name, parameters, and functionality of this procedure are subject to change.
  //
  //*** Input validation ***
  //
  //This augmentation can only be applied to samples from classification,
  //multi-label classification (MLC) or 3D gripping point detection datasets.
  GetDictParam(hv_DLSample, "key_exists", "image_label_id", &hv_ClassificationLabelExists);
  GetDictParam(hv_DLSample, "key_exists", "image_label_ids", &hv_MLCLabelExists);
  GetDictParam(hv_DLSample, "key_exists", "x", &hv_XKeyExists);
  GetDictParam(hv_DLSample, "key_exists", "segmentation_image", &hv_SegmentationImageKeyExists);
  hv_GrippingPointKeysExists = hv_XKeyExists.TupleAnd(hv_SegmentationImageKeyExists);
  if (0 != (HTuple(HTuple(hv_ClassificationLabelExists.TupleOr(hv_MLCLabelExists)).TupleOr(hv_GrippingPointKeysExists)).TupleNot()))
  {
    throw HException(HTuple("The augmentation method 'crop_percentage' is only supported by classification, multi-label classification or 3D gripping point detection models."));
  }
  //
  //*** Augmentation ***
  //
  ho_Image = hv_DLSample.TupleGetDictObject("image");
  GetImageSize(ho_Image, &hv_ImageWidth, &hv_ImageHeight);
  //
  //Define cropping rectangle.
  hv_CropRate = hv_CropPercentage*0.01;
  hv_Row1 = (((1-hv_CropRate)*hv_ImageHeight)*HTuple::TupleRand(1)).TupleFloor();
  hv_Row2 = hv_Row1+(hv_CropRate*hv_ImageHeight);
  hv_Column1 = (((1-hv_CropRate)*hv_ImageWidth)*HTuple::TupleRand(1)).TupleFloor();
  hv_Column2 = hv_Column1+(hv_CropRate*hv_ImageWidth);
  //
  //Crop the image.
  CropRectangle1(ho_Image, &ho_ImagePart, hv_Row1, hv_Column1, hv_Row2, hv_Column2);
  //
  //Scale image to the input size and set the augmented image to DLSample.
  ZoomImageSize(ho_ImagePart, &ho_ImagePart, hv_ImageWidth, hv_ImageHeight, "constant");
  SetDictObject(ho_ImagePart, hv_DLSample, "image");
  //
  //3D sensor data should not be interpolated to avoid introducing unwanted
  //interpolation effects. Therefore we use 'nearest_neighbor' interpolation.
  if (0 != hv_GrippingPointKeysExists)
  {
    hv_Keys.Clear();
    hv_Keys[0] = "x";
    hv_Keys[1] = "y";
    hv_Keys[2] = "z";
    hv_Keys[3] = "normals";
    hv_Keys[4] = "segmentation_image";
    hv_Keys[5] = "weight_image";
    {
    HTuple end_val39 = (hv_Keys.TupleLength())-1;
    HTuple step_val39 = 1;
    for (hv_Index=0; hv_Index.Continue(end_val39, step_val39); hv_Index += step_val39)
    {
      hv_Key = HTuple(hv_Keys[hv_Index]);
      ho_Image = hv_DLSample.TupleGetDictObject(hv_Key);
      //
      //Crop the image.
      CropRectangle1(ho_Image, &ho_ImagePart, hv_Row1, hv_Column1, hv_Row2, hv_Column2);
      //
      //Scale image to the input size and set the augmented image to DLSample.
      ZoomImageSize(ho_ImagePart, &ho_ImagePart, hv_ImageWidth, hv_ImageHeight, "nearest_neighbor");
      SetDictObject(ho_ImagePart, hv_DLSample, hv_Key);
    }
    }
  }
  return;
}

// Chapter: Deep Learning / Model
void augment_dl_sample_crop_pixel (HTuple hv_DLSample, HTuple hv_CropPixel)
{

  // Local iconic variables
  HObject  ho_Image, ho_ImagePart;

  // Local control variables
  HTuple  hv_ClassificationLabelExists, hv_MLCLabelExists;
  HTuple  hv_ImageWidth, hv_ImageHeight, hv_Length, hv_Row1;
  HTuple  hv_Row2, hv_Column1, hv_Column2;

  //This procedure should not be used outside of the augment_dl_samples procedure!
  //The name, parameters, and functionality of this procedure are subject to change.
  //
  //*** Input validation ***
  //
  //This augmentation can only be applied to samples from classification or
  //multi-label classification (MLC) datasets.
  GetDictParam(hv_DLSample, "key_exists", "image_label_id", &hv_ClassificationLabelExists);
  GetDictParam(hv_DLSample, "key_exists", "image_label_ids", &hv_MLCLabelExists);
  if (0 != (HTuple(hv_ClassificationLabelExists.TupleOr(hv_MLCLabelExists)).TupleNot()))
  {
    throw HException("The augmentation method 'crop_pixel' is only supported by classification or multi-label classification models.");
  }
  //
  //*** Augmentation ***
  //
  ho_Image = hv_DLSample.TupleGetDictObject("image");
  GetImageSize(ho_Image, &hv_ImageWidth, &hv_ImageHeight);
  //
  //Define cropping rectangle.
  hv_Length = hv_CropPixel;
  hv_Row1 = HTuple::TupleRand(1)*(hv_ImageHeight-hv_Length);
  hv_Row2 = (hv_Row1+hv_Length)-1;
  hv_Column1 = HTuple::TupleRand(1)*(hv_ImageWidth-hv_Length);
  hv_Column2 = (hv_Column1+hv_Length)-1;
  //
  //Crop the image.
  CropRectangle1(ho_Image, &ho_ImagePart, hv_Row1, hv_Column1, hv_Row2, hv_Column2);
  //
  //Scale the image to the input size and set the augmented image to DLSample.
  ZoomImageSize(ho_ImagePart, &ho_ImagePart, hv_ImageWidth, hv_ImageHeight, "constant");
  SetDictObject(ho_ImagePart, hv_DLSample, "image");
  return;
}

// Chapter: Deep Learning / Model
void augment_dl_sample_mirror (HTuple hv_DLSample, HTuple hv_MirrorMethods, HTuple hv_ClassIDsNoOrientation, 
    HTuple hv_IgnoreDirection)
{

  // Local iconic variables
  HObject  ho_Image, ho_Mask, ho_SegmentationImage;
  HObject  ho_WeightImage;

  // Local control variables
  HTuple  hv_OCRType, hv_Rectangle1ParamExist, hv_Rectangle2ParamExist;
  HTuple  hv_InstanceMaskExists, hv_SegmentationImageExists;
  HTuple  hv_WeightImageExists, hv_BBoxRow1, hv_BBoxCol1;
  HTuple  hv_BBoxRow2, hv_BBoxCol2, hv_BBoxRow, hv_BBoxCol;
  HTuple  hv_BBoxPhi, hv_BBoxLabelID, hv_NumMirrorMethods;
  HTuple  hv_ProbabilityMethods, hv_StrMirror, hv_StrIdx;
  HTuple  hv_SelectedChar, hv_ImageWidth, hv_ImageHeight;
  HTuple  hv_BBoxCol1Mirror, hv_BBoxCol2Mirror, hv_ObjIdx;
  HTuple  hv_BBoxRow1Mirror, hv_BBoxRow2Mirror;

  //This procedure should not be used outside of the augment_dl_samples procedure!
  //The name, parameters, and functionality of this procedure are subject to change.
  //
  //*** Input validation ***
  //
  //This augmentation method should not be applied to OCR Detection/Recognition samples.
  get_dl_sample_ocr_type(hv_DLSample, &hv_OCRType);
  if (0 != (HTuple(int(hv_OCRType==HTuple("ocr_detection"))).TupleOr(int(hv_OCRType==HTuple("ocr_recognition")))))
  {
    throw HException(("The augmentation method 'mirror' is not supported by "+hv_OCRType)+" models.");
  }
  //
  //*** Augmentation ***
  //
  ho_Image = hv_DLSample.TupleGetDictObject("image");
  //Get the annotations from the sample that need to be
  //augmented together with the image.
  GetDictParam(hv_DLSample, "key_exists", "bbox_row1", &hv_Rectangle1ParamExist);
  GetDictParam(hv_DLSample, "key_exists", "bbox_phi", &hv_Rectangle2ParamExist);
  GetDictParam(hv_DLSample, "key_exists", "mask", &hv_InstanceMaskExists);
  GetDictParam(hv_DLSample, "key_exists", "segmentation_image", &hv_SegmentationImageExists);
  GetDictParam(hv_DLSample, "key_exists", "weight_image", &hv_WeightImageExists);
  if (0 != hv_Rectangle1ParamExist)
  {
    GetDictTuple(hv_DLSample, "bbox_row1", &hv_BBoxRow1);
    GetDictTuple(hv_DLSample, "bbox_col1", &hv_BBoxCol1);
    GetDictTuple(hv_DLSample, "bbox_row2", &hv_BBoxRow2);
    GetDictTuple(hv_DLSample, "bbox_col2", &hv_BBoxCol2);
  }
  else if (0 != hv_Rectangle2ParamExist)
  {
    GetDictTuple(hv_DLSample, "bbox_row", &hv_BBoxRow);
    GetDictTuple(hv_DLSample, "bbox_col", &hv_BBoxCol);
    GetDictTuple(hv_DLSample, "bbox_phi", &hv_BBoxPhi);
    if (0 != (int(hv_ClassIDsNoOrientation!=HTuple())))
    {
      GetDictTuple(hv_DLSample, "bbox_label_id", &hv_BBoxLabelID);
    }
  }
  if (0 != hv_InstanceMaskExists)
  {
    GetDictObject(&ho_Mask, hv_DLSample, "mask");
  }
  if (0 != hv_SegmentationImageExists)
  {
    GetDictObject(&ho_SegmentationImage, hv_DLSample, "segmentation_image");
  }
  if (0 != hv_WeightImageExists)
  {
    GetDictObject(&ho_WeightImage, hv_DLSample, "weight_image");
  }
  //
  //Mirroring
  //
  //If more than one axis is allowed,
  //choose mirror axis/axes to be applied.
  hv_NumMirrorMethods = hv_MirrorMethods.TupleStrlen();
  hv_ProbabilityMethods = 1.0/hv_NumMirrorMethods;
  hv_StrMirror = "";
  while (0 != (int(hv_StrMirror==HTuple(""))))
  {
    {
    HTuple end_val52 = hv_NumMirrorMethods-1;
    HTuple step_val52 = 1;
    for (hv_StrIdx=0; hv_StrIdx.Continue(end_val52, step_val52); hv_StrIdx += step_val52)
    {
      hv_SelectedChar = hv_MirrorMethods.TupleStrBitSelect(hv_StrIdx);
      if (0 != (int(HTuple::TupleRand(1)<hv_ProbabilityMethods)))
      {
        hv_StrMirror += hv_SelectedChar;
      }
    }
    }
  }
  //Apply the chosen mirror axis/axes to the given sample data.
  GetImageSize(ho_Image, &hv_ImageWidth, &hv_ImageHeight);
  if (0 != (hv_StrMirror.TupleRegexpTest("c")))
  {
    MirrorImage(ho_Image, &ho_Image, "column");
    if (0 != hv_Rectangle1ParamExist)
    {
      hv_BBoxCol1Mirror = (hv_ImageWidth-hv_BBoxCol2)-1;
      hv_BBoxCol2Mirror = (hv_ImageWidth-hv_BBoxCol1)-1;
      hv_BBoxCol1 = hv_BBoxCol1Mirror;
      hv_BBoxCol2 = hv_BBoxCol2Mirror;
    }
    else if (0 != hv_Rectangle2ParamExist)
    {
      hv_BBoxCol = (hv_ImageWidth-hv_BBoxCol)-1;
      //Check that BBoxPhi is only mirrored for classes with orientation.
      if (0 != (int(hv_ClassIDsNoOrientation!=HTuple())))
      {
        {
        HTuple end_val72 = (hv_BBoxLabelID.TupleLength())-1;
        HTuple step_val72 = 1;
        for (hv_ObjIdx=0; hv_ObjIdx.Continue(end_val72, step_val72); hv_ObjIdx += step_val72)
        {
          if (0 != (int((hv_ClassIDsNoOrientation.TupleFind(HTuple(hv_BBoxLabelID[hv_ObjIdx])))==-1)))
          {
            if (0 != hv_IgnoreDirection)
            {
              hv_BBoxPhi[hv_ObjIdx] = -HTuple(hv_BBoxPhi[hv_ObjIdx]);
            }
            else
            {
              hv_BBoxPhi[hv_ObjIdx] = (((-(HTuple(hv_BBoxPhi[hv_ObjIdx]).TupleLessElem(0.0)))+(HTuple(hv_BBoxPhi[hv_ObjIdx]).TupleGreaterEqualElem(0.0)))*(HTuple(180).TupleRad()))-HTuple(hv_BBoxPhi[hv_ObjIdx]);
            }
          }
        }
        }
      }
      else
      {
        if (0 != hv_IgnoreDirection)
        {
          hv_BBoxPhi = -hv_BBoxPhi;
        }
        else
        {
          hv_BBoxPhi = (((-(hv_BBoxPhi.TupleLessElem(0.0)))+(hv_BBoxPhi.TupleGreaterEqualElem(0.0)))*(HTuple(180).TupleRad()))-hv_BBoxPhi;
        }
      }
    }
    if (0 != hv_InstanceMaskExists)
    {
      MirrorRegion(ho_Mask, &ho_Mask, "column", hv_ImageWidth);
    }
    if (0 != hv_SegmentationImageExists)
    {
      MirrorImage(ho_SegmentationImage, &ho_SegmentationImage, "column");
    }
    if (0 != hv_WeightImageExists)
    {
      MirrorImage(ho_WeightImage, &ho_WeightImage, "column");
    }
  }
  //
  if (0 != (hv_StrMirror.TupleRegexpTest("r")))
  {
    MirrorImage(ho_Image, &ho_Image, "row");
    if (0 != hv_Rectangle1ParamExist)
    {
      hv_BBoxRow1Mirror = (hv_ImageHeight-hv_BBoxRow2)-1;
      hv_BBoxRow2Mirror = (hv_ImageHeight-hv_BBoxRow1)-1;
      hv_BBoxRow1 = hv_BBoxRow1Mirror;
      hv_BBoxRow2 = hv_BBoxRow2Mirror;
    }
    else if (0 != hv_Rectangle2ParamExist)
    {
      hv_BBoxRow = (hv_ImageHeight-hv_BBoxRow)-1;
      if (0 != (int(hv_ClassIDsNoOrientation!=HTuple())))
      {
        {
        HTuple end_val110 = (hv_BBoxLabelID.TupleLength())-1;
        HTuple step_val110 = 1;
        for (hv_ObjIdx=0; hv_ObjIdx.Continue(end_val110, step_val110); hv_ObjIdx += step_val110)
        {
          if (0 != (int((hv_ClassIDsNoOrientation.TupleFind(HTuple(hv_BBoxLabelID[hv_ObjIdx])))==-1)))
          {
            hv_BBoxPhi[hv_ObjIdx] = -HTuple(hv_BBoxPhi[hv_ObjIdx]);
          }
        }
        }
      }
      else
      {
        hv_BBoxPhi = -hv_BBoxPhi;
      }
    }
    if (0 != hv_InstanceMaskExists)
    {
      MirrorRegion(ho_Mask, &ho_Mask, "row", hv_ImageHeight);
    }
    if (0 != hv_SegmentationImageExists)
    {
      MirrorImage(ho_SegmentationImage, &ho_SegmentationImage, "row");
    }
    if (0 != hv_WeightImageExists)
    {
      MirrorImage(ho_WeightImage, &ho_WeightImage, "row");
    }
  }
  //
  //Set the mirrored data to DLSample.
  SetDictObject(ho_Image, hv_DLSample, "image");
  if (0 != hv_Rectangle1ParamExist)
  {
    SetDictTuple(hv_DLSample, "bbox_col1", hv_BBoxCol1);
    SetDictTuple(hv_DLSample, "bbox_row1", hv_BBoxRow1);
    SetDictTuple(hv_DLSample, "bbox_col2", hv_BBoxCol2);
    SetDictTuple(hv_DLSample, "bbox_row2", hv_BBoxRow2);
  }
  else if (0 != hv_Rectangle2ParamExist)
  {
    SetDictTuple(hv_DLSample, "bbox_row", hv_BBoxRow);
    SetDictTuple(hv_DLSample, "bbox_col", hv_BBoxCol);
    SetDictTuple(hv_DLSample, "bbox_phi", hv_BBoxPhi);
  }
  if (0 != hv_InstanceMaskExists)
  {
    SetDictObject(ho_Mask, hv_DLSample, "mask");
  }
  if (0 != hv_SegmentationImageExists)
  {
    SetDictObject(ho_SegmentationImage, hv_DLSample, "segmentation_image");
  }
  if (0 != hv_WeightImageExists)
  {
    SetDictObject(ho_WeightImage, hv_DLSample, "weight_image");
  }
  return;
}

// Chapter: Deep Learning / Model
void augment_dl_sample_remove_pixel (HTuple hv_DLSample, HTuple hv_NumPixelsToRemoveX, 
    HTuple hv_NumPixelsToRemoveY)
{

  // Local iconic variables
  HObject  ho_Image, ho_ImageHighRes, ho_Domain;
  HObject  ho_DomainHighRes, ho_ImagePart;

  // Local control variables
  HTuple  hv_OCRType, hv_IsOCRRecognition, hv_AugmentationDataExists;
  HTuple  hv_AugmentationData, hv_ImageHighResExists, hv_ImageWidth;
  HTuple  hv_ImageHeight, hv_Row1, hv_Column1, hv_Row2, hv_Column2;
  HTuple  hv_Width, hv_Height, hv_ImageHighResWidth, hv_ImageHighResHeight;

  //This procedure should not be used outside of the augment_dl_samples procedure!
  //The name, parameters, and functionality of this procedure are subject to change.
  //
  //*** Input validation ***
  //
  //This augmentation method applies only to OCR Recognition samples.
  get_dl_sample_ocr_type(hv_DLSample, &hv_OCRType);
  hv_IsOCRRecognition = int(hv_OCRType==HTuple("ocr_recognition"));
  if (0 != (hv_IsOCRRecognition.TupleNot()))
  {
    throw HException("The augmentation method 'remove_pixel' is only supported by ocr_recognition models.");
  }
  //
  //*** Augmentation ***
  //
  ho_Image = hv_DLSample.TupleGetDictObject("image");
  //
  //Select the augmentation image with high resolution if available for ocr_recognition models.
  //Note the difference between Image and ImageHighRes.
  GetDictParam(hv_DLSample, "key_exists", "augmentation_data", &hv_AugmentationDataExists);
  if (0 != (hv_IsOCRRecognition.TupleAnd(hv_AugmentationDataExists)))
  {
    hv_AugmentationData = hv_DLSample.TupleGetDictTuple("augmentation_data");
    GetDictParam(hv_AugmentationData, "key_exists", "image_high_res", &hv_ImageHighResExists);
    if (0 != hv_ImageHighResExists)
    {
      ho_ImageHighRes = hv_AugmentationData.TupleGetDictObject("image_high_res");
    }
  }
  //
  //Get dimensions of the domain of the preprocessed image,
  //The domain is assumed to be a rectangle1 domain.
  GetImageSize(ho_Image, &hv_ImageWidth, &hv_ImageHeight);
  GetDomain(ho_Image, &ho_Domain);
  SmallestRectangle1(ho_Domain, &hv_Row1, &hv_Column1, &hv_Row2, &hv_Column2);
  hv_Width = (hv_Column2-hv_Column1)+1;
  hv_Height = (hv_Row2-hv_Row1)+1;
  //Do nothing if no pixel would remain available.
  if (0 != (HTuple(int(hv_Width<=(2*hv_NumPixelsToRemoveX))).TupleOr(int(hv_Height<=(2*hv_NumPixelsToRemoveY)))))
  {
    return;
  }
  //In case of ocr_recognition use the high-resolution image if available.
  if (0 != (hv_IsOCRRecognition.TupleAnd(hv_AugmentationDataExists)))
  {
    GetImageSize(ho_ImageHighRes, &hv_ImageHighResWidth, &hv_ImageHighResHeight);
    hv_NumPixelsToRemoveX = ((hv_NumPixelsToRemoveX*hv_ImageHighResWidth)/(hv_Width.TupleReal())).TupleInt();
    hv_NumPixelsToRemoveY = ((hv_NumPixelsToRemoveY*hv_ImageHighResHeight)/(hv_Height.TupleReal())).TupleInt();
    ho_Image = ho_ImageHighRes;
    //The high-resolution image is expected to have full domain.
    GetDomain(ho_ImageHighRes, &ho_DomainHighRes);
    SmallestRectangle1(ho_DomainHighRes, &hv_Row1, &hv_Column1, &hv_Row2, &hv_Column2);
  }
  //Define cropping rectangle.
  if (0 != (int(hv_NumPixelsToRemoveY>0)))
  {
    hv_Row1 += ((HTuple::TupleRand(1)*hv_NumPixelsToRemoveY).TupleInt())+1;
    hv_Row2 = hv_Row2-(((HTuple::TupleRand(1)*hv_NumPixelsToRemoveY).TupleInt())+1);
  }
  if (0 != (int(hv_NumPixelsToRemoveX>0)))
  {
    hv_Column1 += ((HTuple::TupleRand(1)*hv_NumPixelsToRemoveX).TupleInt())+1;
    hv_Column2 = hv_Column2-(((HTuple::TupleRand(1)*hv_NumPixelsToRemoveX).TupleInt())+1);
  }
  //Crop the image.
  CropRectangle1(ho_Image, &ho_ImagePart, hv_Row1, hv_Column1, hv_Row2, hv_Column2);
  //Scale the image to the input size and set the augmented image to DLSample.
  if (0 != (hv_IsOCRRecognition.TupleAnd(hv_AugmentationDataExists)))
  {
    preprocess_dl_model_images_ocr_recognition(ho_ImagePart, &ho_ImagePart, hv_AugmentationData.TupleGetDictTuple("preprocess_params"));
  }
  else
  {
    ZoomImageSize(ho_ImagePart, &ho_ImagePart, hv_ImageWidth, hv_ImageHeight, "constant");
  }
  //Set the augmented image to DLSample.
  SetDictObject(ho_ImagePart, hv_DLSample, "image");
  return;
}

// Chapter: Deep Learning / Model
void augment_dl_sample_rotate (HTuple hv_DLSample, HTuple hv_RotationStep, HTuple hv_ClassIDsNoOrientation, 
    HTuple hv_IgnoreDirection)
{

  // Local iconic variables
  HObject  ho_Image, ho_Mask, ho_SegmentationImage;
  HObject  ho_WeightImage, ho_ImageRotate;

  // Local control variables
  HTuple  hv_OCRType, hv_Rectangle1ParamExist, hv_Rectangle2ParamExist;
  HTuple  hv_InstanceMaskExists, hv_SegmentationImageExists;
  HTuple  hv_WeightImageExists, hv_BBoxRow1, hv_BBoxCol1;
  HTuple  hv_BBoxRow2, hv_BBoxCol2, hv_BBoxRow, hv_BBoxCol;
  HTuple  hv_BBoxLength1, hv_BBoxLength2, hv_BBoxPhi, hv_BBoxLabelID;
  HTuple  hv_NumPossibleRotations, hv_CurrentRotation, hv_ImageWidth;
  HTuple  hv_ImageHeight, hv_HomMat2DIdentity, hv_HomMat2DTmp;
  HTuple  hv_HomMat2DAdapted, hv_Offset, hv_HomMat2DRotate;
  HTuple  hv_RowTrans1, hv_ColTrans1, hv_RowTrans2, hv_ColTrans2;
  HTuple  hv_RowTrans, hv_ColTrans, hv_MaxAngle, hv_DiffAngle;
  HTuple  hv_IndicesLarge, hv_ObjIdx, hv_BBoxLengthTmp;

  //This procedure should not be used outside of the augment_dl_samples procedure!
  //The name, parameters, and functionality of this procedure are subject to change.
  //
  //*** Input validation ***
  //
  //This augmentation method should not be applied to OCR Detection/Recognition samples.
  get_dl_sample_ocr_type(hv_DLSample, &hv_OCRType);
  if (0 != (HTuple(int(hv_OCRType==HTuple("ocr_detection"))).TupleOr(int(hv_OCRType==HTuple("ocr_recognition")))))
  {
    throw HException(("The augmentation method 'rotate' is not supported by "+hv_OCRType)+" models.");
  }
  //
  //*** Augmentation ***
  //
  ho_Image = hv_DLSample.TupleGetDictObject("image");
  //Get the annotations from the sample that need to be
  //augmented together with the image.
  GetDictParam(hv_DLSample, "key_exists", "bbox_row1", &hv_Rectangle1ParamExist);
  GetDictParam(hv_DLSample, "key_exists", "bbox_phi", &hv_Rectangle2ParamExist);
  GetDictParam(hv_DLSample, "key_exists", "mask", &hv_InstanceMaskExists);
  GetDictParam(hv_DLSample, "key_exists", "segmentation_image", &hv_SegmentationImageExists);
  GetDictParam(hv_DLSample, "key_exists", "weight_image", &hv_WeightImageExists);
  if (0 != hv_Rectangle1ParamExist)
  {
    GetDictTuple(hv_DLSample, "bbox_row1", &hv_BBoxRow1);
    GetDictTuple(hv_DLSample, "bbox_col1", &hv_BBoxCol1);
    GetDictTuple(hv_DLSample, "bbox_row2", &hv_BBoxRow2);
    GetDictTuple(hv_DLSample, "bbox_col2", &hv_BBoxCol2);
  }
  else if (0 != hv_Rectangle2ParamExist)
  {
    GetDictTuple(hv_DLSample, "bbox_row", &hv_BBoxRow);
    GetDictTuple(hv_DLSample, "bbox_col", &hv_BBoxCol);
    GetDictTuple(hv_DLSample, "bbox_length1", &hv_BBoxLength1);
    GetDictTuple(hv_DLSample, "bbox_length2", &hv_BBoxLength2);
    GetDictTuple(hv_DLSample, "bbox_phi", &hv_BBoxPhi);
    if (0 != (int(hv_ClassIDsNoOrientation!=HTuple())))
    {
      GetDictTuple(hv_DLSample, "bbox_label_id", &hv_BBoxLabelID);
    }
  }
  if (0 != hv_InstanceMaskExists)
  {
    GetDictObject(&ho_Mask, hv_DLSample, "mask");
  }
  if (0 != hv_SegmentationImageExists)
  {
    GetDictObject(&ho_SegmentationImage, hv_DLSample, "segmentation_image");
  }
  if (0 != hv_WeightImageExists)
  {
    GetDictObject(&ho_WeightImage, hv_DLSample, "weight_image");
  }
  //
  //Rotation
  //
  //Determine rotation angle for distortion type 'rotate' (angle in range (0:RotationStep:360)).
  hv_NumPossibleRotations = (360.0/hv_RotationStep)-1;
  hv_CurrentRotation = hv_RotationStep*(((hv_NumPossibleRotations*HTuple::TupleRand(1)).TupleInt())+1);
  //
  if (0 != (int(hv_CurrentRotation!=0)))
  {
    GetImageSize(ho_Image, &hv_ImageWidth, &hv_ImageHeight);
    if (0 != (HTuple(int(hv_ImageWidth!=hv_ImageHeight)).TupleAnd(int(hv_CurrentRotation!=180.0))))
    {
      //If an image is not quadratic, a rotation by 90 or 270 degrees is ignored.
      return;
    }
    //
    RotateImage(ho_Image, &ho_ImageRotate, hv_CurrentRotation, "constant");
    SetDictObject(ho_ImageRotate, hv_DLSample, "image");
    //
    if (0 != (hv_Rectangle1ParamExist.TupleOr(hv_Rectangle2ParamExist)))
    {
      //Create a transformation matrix for the rotation of the bounding boxes.
      GetImageSize(ho_Image, &hv_ImageWidth, &hv_ImageHeight);
      HomMat2dIdentity(&hv_HomMat2DIdentity);
      HomMat2dTranslate(hv_HomMat2DIdentity, 0.5, 0.5, &hv_HomMat2DTmp);
      HomMat2dTranslateLocal(hv_HomMat2DTmp, -0.5, -0.5, &hv_HomMat2DAdapted);
      hv_Offset = ((hv_ImageHeight-hv_ImageWidth)*0.5)*((hv_CurrentRotation.TupleRad()).TupleSin());
      HomMat2dTranslate(hv_HomMat2DAdapted, hv_Offset, hv_Offset, &hv_HomMat2DAdapted);
      HomMat2dRotate(hv_HomMat2DAdapted, hv_CurrentRotation.TupleRad(), hv_ImageHeight*0.5, 
          hv_ImageWidth*0.5, &hv_HomMat2DRotate);
    }
    if (0 != hv_Rectangle1ParamExist)
    {
      AffineTransPixel(hv_HomMat2DRotate, hv_BBoxRow1, hv_BBoxCol1, &hv_RowTrans1, 
          &hv_ColTrans1);
      AffineTransPixel(hv_HomMat2DRotate, hv_BBoxRow2, hv_BBoxCol2, &hv_RowTrans2, 
          &hv_ColTrans2);
      if (0 != (int(hv_CurrentRotation==90)))
      {
        hv_BBoxRow1 = hv_RowTrans2;
        hv_BBoxCol1 = hv_ColTrans1;
        hv_BBoxRow2 = hv_RowTrans1;
        hv_BBoxCol2 = hv_ColTrans2;
      }
      else if (0 != (int(hv_CurrentRotation==180)))
      {
        hv_BBoxRow1 = hv_RowTrans2;
        hv_BBoxCol1 = hv_ColTrans2;
        hv_BBoxRow2 = hv_RowTrans1;
        hv_BBoxCol2 = hv_ColTrans1;
      }
      else if (0 != (int(hv_CurrentRotation==270)))
      {
        hv_BBoxRow1 = hv_RowTrans1;
        hv_BBoxCol1 = hv_ColTrans2;
        hv_BBoxRow2 = hv_RowTrans2;
        hv_BBoxCol2 = hv_ColTrans1;
      }
      //
      SetDictTuple(hv_DLSample, "bbox_row1", hv_BBoxRow1);
      SetDictTuple(hv_DLSample, "bbox_col1", hv_BBoxCol1);
      SetDictTuple(hv_DLSample, "bbox_row2", hv_BBoxRow2);
      SetDictTuple(hv_DLSample, "bbox_col2", hv_BBoxCol2);
    }
    else if (0 != hv_Rectangle2ParamExist)
    {
      AffineTransPixel(hv_HomMat2DRotate, hv_BBoxRow, hv_BBoxCol, &hv_RowTrans, &hv_ColTrans);
      //Write the bounding box angles phi in the expected interval:
      //-180° < phi <= 180° or if IgnoreDirection set to true -90° < phi <= 90°.
      if (0 != (hv_IgnoreDirection.TupleNot()))
      {
        hv_BBoxPhi += hv_CurrentRotation.TupleRad();
        hv_MaxAngle = 180;
        hv_DiffAngle = 360;
      }
      else
      {
        if (0 != (HTuple(int(hv_CurrentRotation==90)).TupleOr(int(hv_CurrentRotation==270))))
        {
          hv_BBoxPhi += HTuple(90).TupleRad();
        }
        hv_MaxAngle = 90;
        hv_DiffAngle = 180;
      }
      hv_IndicesLarge = (hv_BBoxPhi.TupleGreaterElem(hv_MaxAngle.TupleRad())).TupleFind(1);
      if (0 != (int(hv_IndicesLarge!=-1)))
      {
        hv_BBoxPhi[hv_IndicesLarge] = HTuple(hv_BBoxPhi[hv_IndicesLarge])-(hv_DiffAngle.TupleRad());
      }
      //Check that the angle BBoxPhi for objects without orientation is always set to 0.0.
      if (0 != (int(hv_ClassIDsNoOrientation!=HTuple())))
      {
        {
        HTuple end_val117 = (hv_BBoxLabelID.TupleLength())-1;
        HTuple step_val117 = 1;
        for (hv_ObjIdx=0; hv_ObjIdx.Continue(end_val117, step_val117); hv_ObjIdx += step_val117)
        {
          if (0 != (int((hv_ClassIDsNoOrientation.TupleFind(HTuple(hv_BBoxLabelID[hv_ObjIdx])))!=-1)))
          {
            hv_BBoxPhi[hv_ObjIdx] = 0.0;
            //These classes require Length1 <= Length2: exchange them for 90° or 270° rotations.
            if (0 != (HTuple(int(hv_CurrentRotation==90)).TupleOr(int(hv_CurrentRotation==270))))
            {
              hv_BBoxLengthTmp = HTuple(hv_BBoxLength1[hv_ObjIdx]);
              hv_BBoxLength1[hv_ObjIdx] = HTuple(hv_BBoxLength2[hv_ObjIdx]);
              hv_BBoxLength2[hv_ObjIdx] = hv_BBoxLengthTmp;
            }
          }
        }
        }
      }
      SetDictTuple(hv_DLSample, "bbox_row", hv_RowTrans);
      SetDictTuple(hv_DLSample, "bbox_col", hv_ColTrans);
      SetDictTuple(hv_DLSample, "bbox_phi", hv_BBoxPhi);
      SetDictTuple(hv_DLSample, "bbox_length1", hv_BBoxLength1);
      SetDictTuple(hv_DLSample, "bbox_length2", hv_BBoxLength2);
    }
    if (0 != hv_InstanceMaskExists)
    {
      AffineTransRegion(ho_Mask, &ho_Mask, hv_HomMat2DRotate, "nearest_neighbor");
      SetDictObject(ho_Mask, hv_DLSample, "mask");
    }
    if (0 != hv_SegmentationImageExists)
    {
      RotateImage(ho_SegmentationImage, &ho_SegmentationImage, hv_CurrentRotation.TupleInt(), 
          "constant");
      SetDictObject(ho_SegmentationImage, hv_DLSample, "segmentation_image");
    }
    if (0 != hv_WeightImageExists)
    {
      RotateImage(ho_WeightImage, &ho_WeightImage, hv_CurrentRotation.TupleInt(), 
          "constant");
      SetDictObject(ho_WeightImage, hv_DLSample, "weight_image");
    }
  }
  return;
}

// Chapter: Deep Learning / Model
void augment_dl_sample_rotate_range (HTuple hv_DLSample, HTuple hv_RotateRange)
{

  // Local iconic variables
  HObject  ho_Image, ho_DomainRotated;

  // Local control variables
  HTuple  hv_OCRType, hv_IsOCRDetection, hv_IsOCRRecognition;
  HTuple  hv_IsOCR, hv_RotateRangeMax, hv_Rectangle1ParamExist;
  HTuple  hv_Rectangle2ParamExist, hv_InstanceMaskExists;
  HTuple  hv_SegmentationImageExists, hv_WeightImageExists;
  HTuple  hv_ImageHighResExists, hv_AugmentationDataExists;
  HTuple  hv_AugmentationData, hv_PreprocessParams, hv_SampleHighResExists;
  HTuple  hv_SampleHighRes, hv_ImageWidth, hv_ImageHeight;
  HTuple  hv_RotationAngle, hv_HomMat2DIdentity, hv_HomMat2DRotate;
  HTuple  hv_Row1, hv_Column1, hv_Row2, hv_Column2, hv_PreprocessWidth;
  HTuple  hv_PreprocessHeight, hv_FactorWidth, hv_FactorHeight;
  HTuple  hv_TempWidth, hv_TempHeight, hv_HomMat2DTranslate;
  HTuple  hv_HomMat2DTransform, hv_BBoxRow1, hv_BBoxCol1;
  HTuple  hv_BBoxRow2, hv_BBoxCol2, hv_BBoxRow3, hv_BBoxCol3;
  HTuple  hv_BBoxRow4, hv_BBoxCol4, hv_Row1Trans, hv_Col1Trans;
  HTuple  hv_Row2Trans, hv_Col2Trans, hv_Row3Trans, hv_Col3Trans;
  HTuple  hv_Row4Trans, hv_Col4Trans, hv___Tmp_Ctrl_0, hv___Tmp_Ctrl_1;
  HTuple  hv___Tmp_Ctrl_2, hv___Tmp_Ctrl_3, hv___Tmp_Ctrl_4;

  //This procedure should not be used outside of the augment_dl_samples procedure!
  //The name, parameters, and functionality of this procedure are subject to change.
  //
  //*** Input validation ***
  //
  get_dl_sample_ocr_type(hv_DLSample, &hv_OCRType);
  hv_IsOCRDetection = int(hv_OCRType==HTuple("ocr_detection"));
  hv_IsOCRRecognition = int(hv_OCRType==HTuple("ocr_recognition"));
  hv_IsOCR = hv_IsOCRDetection.TupleOr(hv_IsOCRRecognition);
  if (0 != hv_IsOCR)
  {
    //For OCR Recognition samples only a certain RotateRange is allowed.
    if (0 != hv_IsOCRRecognition)
    {
      hv_RotateRangeMax = 5;
      if (0 != (int(hv_RotateRange>hv_RotateRangeMax)))
      {
        throw HException(((("Value of augmentation method 'rotate_range' cannot be greater than "+hv_RotateRangeMax)+" for ")+hv_OCRType)+" models.");
      }
    }
  }
  else
  {
    //This augmentation method cannot be applied to samples with
    //object detection annotations or semantic segmentation annotations.
    GetDictParam(hv_DLSample, "key_exists", "bbox_row1", &hv_Rectangle1ParamExist);
    GetDictParam(hv_DLSample, "key_exists", "bbox_phi", &hv_Rectangle2ParamExist);
    GetDictParam(hv_DLSample, "key_exists", "mask", &hv_InstanceMaskExists);
    GetDictParam(hv_DLSample, "key_exists", "segmentation_image", &hv_SegmentationImageExists);
    GetDictParam(hv_DLSample, "key_exists", "weight_image", &hv_WeightImageExists);
    if (0 != (HTuple(HTuple(HTuple(hv_Rectangle1ParamExist.TupleOr(hv_Rectangle2ParamExist)).TupleOr(hv_InstanceMaskExists)).TupleOr(hv_SegmentationImageExists)).TupleOr(hv_WeightImageExists)))
    {
      throw HException(HTuple("The augmentation method 'rotate_range' is not supported for object detection, instance segmentation or semantic segmentation samples."));
    }
  }
  //
  //*** Augmentation ***
  //
  ho_Image = hv_DLSample.TupleGetDictObject("image");
  //
  //Select the augmentation image with high resolution if available for OCR Detection/Recognition models.
  hv_ImageHighResExists = 0;
  GetDictParam(hv_DLSample, "key_exists", "augmentation_data", &hv_AugmentationDataExists);
  if (0 != (hv_IsOCR.TupleAnd(hv_AugmentationDataExists)))
  {
    hv_AugmentationData = hv_DLSample.TupleGetDictTuple("augmentation_data");
    hv_PreprocessParams = hv_AugmentationData.TupleGetDictTuple("preprocess_params");
    if (0 != hv_IsOCRDetection)
    {
      GetDictParam(hv_AugmentationData, "key_exists", "sample_high_res", &hv_SampleHighResExists);
      if (0 != hv_SampleHighResExists)
      {
        hv_SampleHighRes = hv_AugmentationData.TupleGetDictTuple("sample_high_res");
        GetDictParam(hv_SampleHighRes, "key_exists", "image", &hv_ImageHighResExists);
        if (0 != hv_ImageHighResExists)
        {
          ho_Image = hv_SampleHighRes.TupleGetDictObject("image");
        }
      }
    }
    else
    {
      GetDictParam(hv_AugmentationData, "key_exists", "image_high_res", &hv_ImageHighResExists);
      if (0 != hv_ImageHighResExists)
      {
        ho_Image = hv_AugmentationData.TupleGetDictObject("image_high_res");
      }
    }
  }
  if (0 != (hv_IsOCRDetection.TupleAnd(hv_ImageHighResExists.TupleNot())))
  {
    throw HException("The augmentation method 'rotate_range' requires sample images with high resolution for ocr_detection models.");
  }
  //
  GetImageSize(ho_Image, &hv_ImageWidth, &hv_ImageHeight);
  //Determine rotation angle for method 'rotate_range': angle in range [1:RotateRange].
  hv_RotationAngle = ((hv_RotateRange*HTuple::TupleRand(1)).TupleInt())+1;
  //Select direction of rotation randomly.
  if (0 != (int(HTuple::TupleRand(1)<0.5)))
  {
    hv_RotationAngle = 360-hv_RotationAngle;
  }
  //For ocr_detection the transformation matrix is always needed so
  //the else-case is also used for angles multiple of 90 degrees.
  if (0 != (HTuple(int((hv_RotationAngle%90)==0)).TupleAnd(hv_IsOCRDetection.TupleNot())))
  {
    //Rotations around 90 degrees are faster with rotate_image.
    RotateImage(ho_Image, &ho_Image, hv_RotationAngle, "constant");
  }
  else
  {
    HomMat2dIdentity(&hv_HomMat2DIdentity);
    if (0 != (hv_IsOCRDetection.TupleNot()))
    {
      //Create rotation matrix and apply the rotation.
      HomMat2dRotate(hv_HomMat2DIdentity, hv_RotationAngle.TupleRad(), hv_ImageHeight/2.0, 
          hv_ImageWidth/2.0, &hv_HomMat2DRotate);
      AffineTransImage(ho_Image, &ho_Image, hv_HomMat2DRotate, "constant", "false");
      //Remove potential undefined domain.
      GetDomain(ho_Image, &ho_DomainRotated);
      InnerRectangle1(ho_DomainRotated, &hv_Row1, &hv_Column1, &hv_Row2, &hv_Column2);
      CropRectangle1(ho_Image, &ho_Image, hv_Row1, hv_Column1, hv_Row2, hv_Column2);
    }
    else
    {
      //Calculate temporary image dimensions with the same aspect ratio
      //as the preprocessed image to enlarge the input image, such that
      //the rotation output fits most part of it without zooming the content.
      hv_PreprocessWidth = hv_PreprocessParams.TupleGetDictTuple("image_width");
      hv_PreprocessHeight = hv_PreprocessParams.TupleGetDictTuple("image_height");
      calculate_dl_image_zoom_factors(hv_ImageWidth, hv_ImageHeight, hv_PreprocessWidth, 
          hv_PreprocessHeight, hv_PreprocessParams, &hv_FactorWidth, &hv_FactorHeight);
      hv_TempWidth = hv_PreprocessWidth/(hv_FactorWidth.TupleReal());
      hv_TempHeight = hv_PreprocessHeight/(hv_FactorHeight.TupleReal());
      //Rotate image.
      HomMat2dTranslate(hv_HomMat2DIdentity, (-hv_ImageHeight)/2.0, (-hv_ImageWidth)/2.0, 
          &hv_HomMat2DTranslate);
      HomMat2dRotate(hv_HomMat2DTranslate, hv_RotationAngle.TupleRad(), 0, 0, &hv_HomMat2DRotate);
      HomMat2dTranslate(hv_HomMat2DRotate, hv_ImageHeight/2.0, hv_ImageWidth/2.0, 
          &hv_HomMat2DTransform);
      AffineTransImageSize(ho_Image, &ho_Image, hv_HomMat2DTransform, "constant", 
          hv_TempWidth, hv_TempHeight);
      //Rotate bounding boxes.
      convert_rect2_5to8param(hv_SampleHighRes.TupleGetDictTuple("bbox_row"), hv_SampleHighRes.TupleGetDictTuple("bbox_col"), 
          hv_SampleHighRes.TupleGetDictTuple("bbox_length1"), hv_SampleHighRes.TupleGetDictTuple("bbox_length2"), 
          hv_SampleHighRes.TupleGetDictTuple("bbox_phi"), &hv_BBoxRow1, &hv_BBoxCol1, 
          &hv_BBoxRow2, &hv_BBoxCol2, &hv_BBoxRow3, &hv_BBoxCol3, &hv_BBoxRow4, &hv_BBoxCol4);
      AffineTransPixel(hv_HomMat2DTransform, hv_BBoxRow1, hv_BBoxCol1, &hv_Row1Trans, 
          &hv_Col1Trans);
      AffineTransPixel(hv_HomMat2DTransform, hv_BBoxRow2, hv_BBoxCol2, &hv_Row2Trans, 
          &hv_Col2Trans);
      AffineTransPixel(hv_HomMat2DTransform, hv_BBoxRow3, hv_BBoxCol3, &hv_Row3Trans, 
          &hv_Col3Trans);
      AffineTransPixel(hv_HomMat2DTransform, hv_BBoxRow4, hv_BBoxCol4, &hv_Row4Trans, 
          &hv_Col4Trans);
      convert_rect2_8to5param(hv_Row1Trans, hv_Col1Trans, hv_Row2Trans, hv_Col2Trans, 
          hv_Row3Trans, hv_Col3Trans, hv_Row4Trans, hv_Col4Trans, 0, &hv___Tmp_Ctrl_0, 
          &hv___Tmp_Ctrl_1, &hv___Tmp_Ctrl_2, &hv___Tmp_Ctrl_3, &hv___Tmp_Ctrl_4);
      SetDictTuple(hv_DLSample, "bbox_phi", hv___Tmp_Ctrl_4);
      SetDictTuple(hv_DLSample, "bbox_length2", hv___Tmp_Ctrl_3);
      SetDictTuple(hv_DLSample, "bbox_length1", hv___Tmp_Ctrl_2);
      SetDictTuple(hv_DLSample, "bbox_col", hv___Tmp_Ctrl_1);
      SetDictTuple(hv_DLSample, "bbox_row", hv___Tmp_Ctrl_0);
    }
  }
  //Scale image to the input size.
  if (0 != (hv_IsOCR.TupleAnd(hv_ImageHighResExists)))
  {
    if (0 != hv_IsOCRDetection)
    {
      //Scale bounding boxes to the input size.
      preprocess_dl_model_bbox_rect2(ho_Image, hv_DLSample, hv_PreprocessParams);
      //Scale rotated image to the input size.
      preprocess_dl_model_images_ocr_detection(ho_Image, &ho_Image, hv_PreprocessParams);
      //Generate targets from the scaled rotated image.
      SetDictObject(ho_Image, hv_DLSample, "image");
      gen_dl_ocr_detection_targets(hv_DLSample, hv_PreprocessParams);
    }
    else
    {
      preprocess_dl_model_images_ocr_recognition(ho_Image, &ho_Image, hv_PreprocessParams);
    }
  }
  else
  {
    ZoomImageSize(ho_Image, &ho_Image, hv_ImageWidth, hv_ImageHeight, "constant");
  }
  //
  //Set the augmented image to DLSample.
  SetDictObject(ho_Image, hv_DLSample, "image");
  return;
}

// Chapter: Deep Learning / Model
void augment_dl_sample_saturation_variation (HTuple hv_DLSample, HTuple hv_SaturationVariation)
{

  // Local iconic variables
  HObject  ho_Image, ho_GrayImage, ho_GrayRGBChannelImage;
  HObject  ho_GrayRGBChannelImageScaled, ho_ImageScaled, ho_ImageOut;

  // Local control variables
  HTuple  hv_OCRType, hv_NumChannels, hv_Borders;
  HTuple  hv_Factor;

  //This procedure should not be used outside of the augment_dl_samples procedure!
  //The name, parameters, and functionality of this procedure are subject to change.
  //
  //*** Input validation ***
  //
  //This augmentation method should not be applied to OCR Recognition samples.
  get_dl_sample_ocr_type(hv_DLSample, &hv_OCRType);
  if (0 != (int(hv_OCRType==HTuple("ocr_recognition"))))
  {
    throw HException("The augmentation method 'saturation_variation' is not supported by ocr_recognition models.");
  }
  //
  ho_Image = hv_DLSample.TupleGetDictObject("image");
  //
  //If the image has only one channel, this augmentation has no effect.
  CountChannels(ho_Image, &hv_NumChannels);
  if (0 != (int(hv_NumChannels==1)))
  {
    return;
  }
  else if (0 != (int(hv_NumChannels!=3)))
  {
    //Otherwise, only RGB images are allowed.
    throw HException("The augmentation method 'saturation_variation' can only be applied to gray scale and RGB images.");
  }
  //
  //*** Augmentation ***
  //
  //Adjust the saturation of the input image by blending it with its gray value version.
  //
  //Minimum and maximum blend factors.
  hv_Borders.Clear();
  hv_Borders.Append(HTuple(0.0).TupleMax2(1-hv_SaturationVariation));
  hv_Borders.Append(1+hv_SaturationVariation);
  hv_Factor = HTuple(hv_Borders[0])+((HTuple(hv_Borders[1])-HTuple(hv_Borders[0]))*HTuple::TupleRand(1));
  //
  if (0 != (int(hv_Factor==1.0)))
  {
    return;
  }
  //
  //Get the gray value image as an RGB image.
  Rgb1ToGray(ho_Image, &ho_GrayImage);
  Compose3(ho_GrayImage, ho_GrayImage, ho_GrayImage, &ho_GrayRGBChannelImage);
  //
  //Blend Image and GrayRGBChannelImage.
  ScaleImage(ho_GrayRGBChannelImage, &ho_GrayRGBChannelImageScaled, 1.0-hv_Factor, 
      0.0);
  ScaleImage(ho_Image, &ho_ImageScaled, hv_Factor, 0.0);
  AddImage(ho_GrayRGBChannelImageScaled, ho_ImageScaled, &ho_ImageOut, 1.0, 0.0);
  //
  //Set the augmented image to DLSample.
  SetDictObject(ho_ImageOut, hv_DLSample, "image");
  return;
}

// Chapter: Deep Learning / Model
// Short Description: Perform data augmentation on the given samples. 
void augment_dl_samples (HTuple hv_DLSampleBatch, HTuple hv_GenParam)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_NumSamples, hv_AugParams, hv_GenKeys;
  HTuple  hv_KeyIndex, hv_GenKey, hv_AugMethodsToApply, hv_SampleIndex;
  HTuple  hv_DLSample, hv_ChosenIndex, hv_AugMethod, hv_AugMethodValue;
  HTuple  hv___Tmp_Ctrl_Dict_Init_1, hv___Tmp_Ctrl_Type;

  //
  //This procedure augments samples in the DLSampleBatch randomly.
  //The augmentation methods have to be specified using the dictionary GenParam.
  //
  //
  //*** Input validation ***
  //
  //If no augmentation parameter is given we return directly and the samples stay unchanged.
  if (0 != (int((hv_GenParam.TupleLength())==0)))
  {
    return;
  }
  //
  //Check number of samples to be augmented.
  hv_NumSamples = hv_DLSampleBatch.TupleLength();
  if (0 != (int(hv_NumSamples==0)))
  {
    throw HException("There are no DLSamples to be processed.");
  }
  //
  //Validate and sanitize the input.
  //Note that this is just a shallow check of the given GenParam dict.
  //The compatibility of the resulting augmentation parameters dict with the
  //DLSampleBatch at hand needs to be checked below.
  check_augment_dl_samples_gen_param(hv_GenParam);
  //
  //
  //*** Default augmentation values ***
  //
  CreateDict(&hv_AugParams);
  //
  //Augmentation methods:
  //
  //The absolute brightness change can vary in the range [-value, +value].
  SetDictTuple(hv_AugParams, "brightness_variation", 0);
  //The absolute brightness peak of a randomly positioned spot can vary in the range [-value, +value].
  SetDictTuple(hv_AugParams, "brightness_variation_spot", 0);
  //Contrast variation can be enabled by setting a value larger than zero, for example 0.2.
  SetDictTuple(hv_AugParams, "contrast_variation", 0);
  //Fraction of image length and width that remains after cropping (in %).
  SetDictTuple(hv_AugParams, "crop_percentage", "off");
  //Image length and width that remains after cropping (in pixel).
  SetDictTuple(hv_AugParams, "crop_pixel", "off");
  //Allowed mirroring types are coded by 'r' (row), 'c' (column).
  SetDictTuple(hv_AugParams, "mirror", "off");
  //In case of a ocr_recognition model:
  //Maximum amount of pixels that can be removed from the image borders: [x,y] => x:left,right and y:top,bottom.
  SetDictTuple(hv_AugParams, "remove_pixel", (HTuple(0).Append(0)));
  //Step size for possible rotations.
  //This parameter and augmentation method is independent from the 'rotate_range' parameter.
  SetDictTuple(hv_AugParams, "rotate", 0);
  //Step range for rotations with step size 1.
  //This parameter and augmentation method is independent from the 'rotate' parameter.
  SetDictTuple(hv_AugParams, "rotate_range", 0);
  //Saturation variation can be enabled by setting a value larger than zero, for example 0.2.
  SetDictTuple(hv_AugParams, "saturation_variation", 0);
  //
  //Other settings:
  //
  //The percentage of the images that are to be augmented.
  SetDictTuple(hv_AugParams, "augmentation_percentage", 50);
  //In case of a detection model of instance_type 'rectangle2': Use directions of instances within bounding boxes.
  SetDictTuple(hv_AugParams, "ignore_direction", 0);
  //In case of a detection model of instance_type 'rectangle2': Class IDs without orientation.
  //These are the IDs of the classes, for whose instances the orientation is not to be considered.
  SetDictTuple(hv_AugParams, "class_ids_no_orientation", HTuple());
  //
  //
  //*** Get the augmentation that should be applied ***
  //
  //Set user-defined parameters:
  GetDictParam(hv_GenParam, "keys", HTuple(), &hv_GenKeys);
  {
  HTuple end_val70 = (hv_GenKeys.TupleLength())-1;
  HTuple step_val70 = 1;
  for (hv_KeyIndex=0; hv_KeyIndex.Continue(end_val70, step_val70); hv_KeyIndex += step_val70)
  {
    hv_GenKey = HTuple(hv_GenKeys[hv_KeyIndex]);
    GetDictParam(hv_GenParam, "key_data_type", hv_GenKey, &hv___Tmp_Ctrl_Type);
    if (0 != (int(hv___Tmp_Ctrl_Type==HTuple("object"))))
    {
      SetDictObject(hv_GenParam.TupleGetDictObject(hv_GenKey), hv_AugParams, hv_GenKey);
    }
    else
    {
      SetDictTuple(hv_AugParams, hv_GenKey, hv_GenParam.TupleGetDictTuple(hv_GenKey));
    }
  }
  }
  //
  //Get all methods that would actually have an effect when applied with the
  //augmentation value stored in AugParams.
  hv_AugMethodsToApply = HTuple();
  //Brightness variation.
  if (0 != (int((hv_AugParams.TupleGetDictTuple("brightness_variation"))>0)))
  {
    hv_AugMethodsToApply = hv_AugMethodsToApply.TupleConcat("brightness_variation");
  }
  //Brightness variation spot.
  if (0 != (int((hv_AugParams.TupleGetDictTuple("brightness_variation_spot"))>0)))
  {
    hv_AugMethodsToApply = hv_AugMethodsToApply.TupleConcat("brightness_variation_spot");
  }
  //Contrast variation.
  if (0 != (int((hv_AugParams.TupleGetDictTuple("contrast_variation"))>0)))
  {
    hv_AugMethodsToApply = hv_AugMethodsToApply.TupleConcat("contrast_variation");
  }
  //Cropping percentage.
  if (0 != ((hv_AugParams.TupleGetDictTuple("crop_percentage")).TupleIsNumber()))
  {
    hv_AugMethodsToApply = hv_AugMethodsToApply.TupleConcat("crop_percentage");
  }
  //Cropping pixels.
  if (0 != ((hv_AugParams.TupleGetDictTuple("crop_pixel")).TupleIsNumber()))
  {
    hv_AugMethodsToApply = hv_AugMethodsToApply.TupleConcat("crop_pixel");
  }
  //Mirroring is allowed in row and column direction.
  if (0 != (HTuple((hv_AugParams.TupleGetDictTuple("mirror")).TupleRegexpTest("r")).TupleOr((hv_AugParams.TupleGetDictTuple("mirror")).TupleRegexpTest("c"))))
  {
    hv_AugMethodsToApply = hv_AugMethodsToApply.TupleConcat("mirror");
  }
  //Removing pixels.
  if (0 != (HTuple(int(HTuple((hv_AugParams.TupleGetDictTuple("remove_pixel"))[0])>0)).TupleOr(int(HTuple((hv_AugParams.TupleGetDictTuple("remove_pixel"))[1])>0))))
  {
    hv_AugMethodsToApply = hv_AugMethodsToApply.TupleConcat("remove_pixel");
  }
  //Rotation with a given angular step size.
  if (0 != (int((hv_AugParams.TupleGetDictTuple("rotate"))>0)))
  {
    hv_AugMethodsToApply = hv_AugMethodsToApply.TupleConcat("rotate");
  }
  //Rotation within a given range (step size 1).
  if (0 != (int((hv_AugParams.TupleGetDictTuple("rotate_range"))>0)))
  {
    hv_AugMethodsToApply = hv_AugMethodsToApply.TupleConcat("rotate_range");
  }
  //Saturation variation.
  if (0 != (int((hv_AugParams.TupleGetDictTuple("saturation_variation"))>0)))
  {
    hv_AugMethodsToApply = hv_AugMethodsToApply.TupleConcat("saturation_variation");
  }
  //
  //Exit early if there is nothing to be applied
  CreateDict(&hv___Tmp_Ctrl_Dict_Init_1);
  SetDictTuple(hv___Tmp_Ctrl_Dict_Init_1, "comp", 0);
  if (0 != (HTuple(int((hv_AugMethodsToApply.TupleLength())==0)).TupleOr((hv_AugParams.TupleConcat(hv___Tmp_Ctrl_Dict_Init_1)).TupleTestEqualDictItem("augmentation_percentage","comp"))))
  {
    return;
  }
  hv___Tmp_Ctrl_Dict_Init_1 = HTuple::TupleConstant("HNULL");
  //
  //
  //*** Augment the samples ***
  //
  {
  HTuple end_val135 = (hv_DLSampleBatch.TupleLength())-1;
  HTuple step_val135 = 1;
  for (hv_SampleIndex=0; hv_SampleIndex.Continue(end_val135, step_val135); hv_SampleIndex += step_val135)
  {
    hv_DLSample = HTuple(hv_DLSampleBatch[hv_SampleIndex]);
    //Only augment the given percentage of samples.
    if (0 != (int((HTuple::TupleRand(1)*100)>(hv_AugParams.TupleGetDictTuple("augmentation_percentage")))))
    {
      continue;
    }
    //Select the augmentation method.
    hv_ChosenIndex = HTuple(HTuple::TupleRand(1)*(hv_AugMethodsToApply.TupleLength())).TupleInt();
    hv_AugMethod = HTuple(hv_AugMethodsToApply[hv_ChosenIndex]);
    hv_AugMethodValue = hv_AugParams.TupleGetDictTuple(hv_AugMethod);
    //
    if (0 != (int(hv_AugMethod==HTuple("brightness_variation"))))
    {
      augment_dl_sample_brightness_variation(hv_DLSample, hv_AugMethodValue);
    }
    else if (0 != (int(hv_AugMethod==HTuple("brightness_variation_spot"))))
    {
      augment_dl_sample_brightness_variation_spot(hv_DLSample, hv_AugMethodValue);
    }
    else if (0 != (int(hv_AugMethod==HTuple("contrast_variation"))))
    {
      augment_dl_sample_contrast_variation(hv_DLSample, hv_AugMethodValue);
    }
    else if (0 != (int(hv_AugMethod==HTuple("crop_percentage"))))
    {
      augment_dl_sample_crop_percentage(hv_DLSample, hv_AugMethodValue);
    }
    else if (0 != (int(hv_AugMethod==HTuple("crop_pixel"))))
    {
      augment_dl_sample_crop_pixel(hv_DLSample, hv_AugMethodValue);
    }
    else if (0 != (int(hv_AugMethod==HTuple("mirror"))))
    {
      augment_dl_sample_mirror(hv_DLSample, hv_AugMethodValue, hv_AugParams.TupleGetDictTuple("class_ids_no_orientation"), 
          hv_AugParams.TupleGetDictTuple("ignore_direction"));
    }
    else if (0 != (int(hv_AugMethod==HTuple("remove_pixel"))))
    {
      augment_dl_sample_remove_pixel(hv_DLSample, HTuple(hv_AugMethodValue[0]), HTuple(hv_AugMethodValue[1]));
    }
    else if (0 != (int(hv_AugMethod==HTuple("rotate"))))
    {
      augment_dl_sample_rotate(hv_DLSample, hv_AugMethodValue, hv_AugParams.TupleGetDictTuple("class_ids_no_orientation"), 
          hv_AugParams.TupleGetDictTuple("ignore_direction"));
    }
    else if (0 != (int(hv_AugMethod==HTuple("rotate_range"))))
    {
      augment_dl_sample_rotate_range(hv_DLSample, hv_AugMethodValue);
    }
    else if (0 != (int(hv_AugMethod==HTuple("saturation_variation"))))
    {
      augment_dl_sample_saturation_variation(hv_DLSample, hv_AugMethodValue);
    }
  }
  }
  return;
}

// Chapter: Image / Manipulation
// Short Description: Augment/distort the given images. 
void augment_images (HObject ho_Images, HObject *ho_ImagesAugmented, HTuple hv_GenParamName, 
    HTuple hv_GenParamValue)
{

  // Local iconic variables
  HObject  ho_ImageSelected, ho_ImagePart, ho_ImageRotated;
  HObject  ho_DomainRotated, ho_ImageScaled, ho_ImageSpot;

  // Local control variables
  HTuple  hv_AugmentationPercentage, hv_CropPercentage;
  HTuple  hv_CropPixel, hv_Rotation, hv_RotationRange, hv_Mirror;
  HTuple  hv_BrightnessVariation, hv_BrightnessVariationSpot;
  HTuple  hv_GenParamIndex, hv_CurrentParamName, hv_CurrentParamValue;
  HTuple  hv_NumAvailableDistortions, hv_NumImages, hv_AugmentationRate;
  HTuple  hv_NumAugmentations, hv_ImageIndices, hv_SelectedImages;
  HTuple  hv_SelectedDistortions, hv_IndexDistortion, hv_Index;
  HTuple  hv_ImageIndex, hv_CurrentDistortion, hv_Width, hv_Height;
  HTuple  hv_CropRate, hv_Row1, hv_Row2, hv_Column1, hv_Column2;
  HTuple  hv_Length, hv_RotationStep, hv_NumPossibleRotations;
  HTuple  hv_CurrentRotation, hv_HomMat2DIdentity, hv_HomMat2DRotate;
  HTuple  hv_NumMirrorMethods, hv_PropabilityMethods, hv_StrMirror;
  HTuple  hv_StrIdx, hv_SelectedChar, hv_BrightnessVariationValue;
  HTuple  hv_SpotSize, hv_SpotRow, hv_SpotColumn;
  HTupleVector  hvec_AvailableDistortions(1), hvec_Distortions(1);

  //This procedure can be used to augment given input Images
  //using different methods, which can be specified using
  //GenParamName and GenParamValue. The augmented images are returned
  //in ImagesAugmented.
  //
  //Set default parameters.
  //
  //The percentages of the images that are to be augmented.
  hv_AugmentationPercentage.Clear();
  hv_AugmentationPercentage[0] = "augmentation_percentage";
  hv_AugmentationPercentage[1] = 50;
  //Fraction of image length and width that remains after cropping (in %).
  hv_CropPercentage.Clear();
  hv_CropPercentage[0] = "crop_percentage";
  hv_CropPercentage[1] = "off";
  //Image length and width that remains after cropping (in pixel).
  hv_CropPixel.Clear();
  hv_CropPixel[0] = "crop_pixel";
  hv_CropPixel[1] = "off";
  //Step size for possible rotations.
  hv_Rotation.Clear();
  hv_Rotation[0] = "rotate";
  hv_Rotation[1] = 0;
  //Step range for rotations with step size 1.
  hv_RotationRange.Clear();
  hv_RotationRange[0] = "rotate_range";
  hv_RotationRange[1] = 0;
  //Allowed mirroring methods coded by 'r' (row), 'c' (column).
  hv_Mirror.Clear();
  hv_Mirror[0] = "mirror";
  hv_Mirror[1] = "off";
  //The absolute brightness change can vary in the range[-value, +value].
  hv_BrightnessVariation.Clear();
  hv_BrightnessVariation[0] = "brightness_variation";
  hv_BrightnessVariation[1] = 0;
  //The absolute brightness peak of a randomly positioned spot can vary in the range[-value, +value].
  hv_BrightnessVariationSpot.Clear();
  hv_BrightnessVariationSpot[0] = "brightness_variation_spot";
  hv_BrightnessVariationSpot[1] = 0;
  //
  //Parse the generic parameters.
  //
  //Check if GenParamName matches GenParamValue.
  if (0 != (int((hv_GenParamName.TupleLength())!=(hv_GenParamValue.TupleLength()))))
  {
    throw HException("Number of generic parameters does not match number of generic parameter values");
  }
  //Check for generic parameter names and overwrite defaults.
  {
  HTuple end_val31 = (hv_GenParamName.TupleLength())-1;
  HTuple step_val31 = 1;
  for (hv_GenParamIndex=0; hv_GenParamIndex.Continue(end_val31, step_val31); hv_GenParamIndex += step_val31)
  {
    hv_CurrentParamName = HTuple(hv_GenParamName[hv_GenParamIndex]);
    hv_CurrentParamValue = HTuple(hv_GenParamValue[hv_GenParamIndex]);
    //
    if (0 != (int(hv_CurrentParamName==HTuple(hv_AugmentationPercentage[0]))))
    {
      //Set augmentation percentage.
      hv_AugmentationPercentage[1] = hv_CurrentParamValue;
      //Check if input value is in range of 1-100 %.
      if (0 != (hv_CurrentParamValue.TupleIsNumber()))
      {
        if (0 != (HTuple(int(hv_CurrentParamValue<1)).TupleOr(int(hv_CurrentParamValue>100))))
        {
          throw HException("The given value for augmentation_percentage has to be in the range 1-100.");
        }
      }
      else
      {
        throw HException("The given value for augmentation_percentage has to be in the range 1-100.");
      }
    }
    else if (0 != (int(hv_CurrentParamName==HTuple(hv_Rotation[0]))))
    {
      //Set rotation.
      hv_Rotation[1] = hv_CurrentParamValue;
      //Check if input value is in range of 0-180 deg.
      if (0 != (hv_CurrentParamValue.TupleIsNumber()))
      {
        if (0 != (HTuple(int(hv_CurrentParamValue<0)).TupleOr(int(hv_CurrentParamValue>180))))
        {
          throw HException("The given value for rotate has to be in the range 0-180.");
        }
      }
      else
      {
        throw HException("The given value for rotate has to be in the range 0-180.");
      }
    }
    else if (0 != (int(hv_CurrentParamName==HTuple(hv_RotationRange[0]))))
    {
      //Set rotation.
      hv_RotationRange[1] = hv_CurrentParamValue;
      //Check if input value is in range of 0-180 deg.
      if (0 != (hv_CurrentParamValue.TupleIsNumber()))
      {
        if (0 != (HTuple(int(hv_CurrentParamValue<0)).TupleOr(int(hv_CurrentParamValue>180))))
        {
          throw HException("The given value for rotate_range has to be in the range 0-180.\"");
        }
      }
      else
      {
        throw HException("The given value for rotate_range has to be in the range 0-180.");
      }
    }
    else if (0 != (int(hv_CurrentParamName==HTuple(hv_Mirror[0]))))
    {
      //Set mirroring.
      hv_Mirror[1] = hv_CurrentParamValue;
      //Check if input is string and is 'off' or contains the wanted strings.
      if (0 != ((hv_CurrentParamValue.TupleIsNumber()).TupleOr(HTuple(HTuple(HTuple(HTuple(HTuple(int(hv_CurrentParamValue==HTuple("off"))).TupleOr(int(hv_CurrentParamValue==HTuple("c")))).TupleOr(int(hv_CurrentParamValue==HTuple("r")))).TupleOr(int(hv_CurrentParamValue==HTuple("cr")))).TupleOr(int(hv_CurrentParamValue==HTuple("rc")))).TupleNot())))
      {
        throw HException("Unknown mirror method.");
      }
    }
    else if (0 != (int(hv_CurrentParamName==HTuple(hv_CropPercentage[0]))))
    {
      //Set cropping with percentage.
      hv_CropPercentage[1] = hv_CurrentParamValue;
      //Check if input value is in range of 1-100 %.
      if (0 != (hv_CurrentParamValue.TupleIsNumber()))
      {
        if (0 != (HTuple(int(hv_CurrentParamValue<1)).TupleOr(int(hv_CurrentParamValue>100))))
        {
          throw HException("The given value for crop_percentage has to be in the range 1-100.");
        }
      }
      else
      {
        throw HException("The given value for crop_percentage has to be in the range 1-100.");
      }
    }
    else if (0 != (int(hv_CurrentParamName==HTuple(hv_CropPixel[0]))))
    {
      //Set cropping with pixels.
      hv_CropPixel[1] = hv_CurrentParamValue;
      //Check if input value is greater 0.
      if (0 != (hv_CurrentParamValue.TupleIsNumber()))
      {
        if (0 != (int(hv_CurrentParamValue<1)))
        {
          throw HException("The given value for crop_pixel has to be greater then or equal to 1.");
        }
      }
      else
      {
        throw HException("The given value for crop_pixel has to be a string.");
      }
    }
    else if (0 != (int(hv_CurrentParamName==HTuple(hv_BrightnessVariation[0]))))
    {
      //Set brightness variation.
      hv_BrightnessVariation[1] = hv_CurrentParamValue;
      //Check if input value is in range of 0-255.
      if (0 != (hv_CurrentParamValue.TupleIsNumber()))
      {
        if (0 != (HTuple(int(hv_CurrentParamValue<0)).TupleOr(int(hv_CurrentParamValue>255))))
        {
          throw HException("The given value for brightness_variation has to be in the range 0-255.");
        }
      }
      else
      {
        throw HException("The given value for brightness_variation has to be in the range 0-255.");
      }
    }
    else if (0 != (int(hv_CurrentParamName==HTuple(hv_BrightnessVariationSpot[0]))))
    {
      //Set brightness variation of spot.
      hv_BrightnessVariationSpot[1] = hv_CurrentParamValue;
      //Check if input value is in range of 0-255.
      if (0 != (hv_CurrentParamValue.TupleIsNumber()))
      {
        if (0 != (HTuple(int(hv_CurrentParamValue<0)).TupleOr(int(hv_CurrentParamValue>255))))
        {
          throw HException("The given value for brightness_variation_spot has to be in the range 0-255.");
        }
      }
      else
      {
        throw HException("The given value for brightness_variation_spot has to be in the range 0-255.");
      }
    }
    else
    {
      throw HException(("Unknown generic parameter: '"+HTuple(hv_GenParamName[hv_GenParamIndex]))+"'");
    }
  }
  }
  //
  //Aggregate all possible distortions and parameter values into a vector.
  //
  hvec_AvailableDistortions = HTupleVector(1);
  //Cropping percentage.
  if (0 != (HTuple(hv_CropPercentage[1]).TupleIsNumber()))
  {
    hvec_AvailableDistortions[HTuple(hvec_AvailableDistortions.Length())] = HTupleVector(hv_CropPercentage);
  }
  //Cropping pixel.
  if (0 != (HTuple(hv_CropPixel[1]).TupleIsNumber()))
  {
    hvec_AvailableDistortions[HTuple(hvec_AvailableDistortions.Length())] = HTupleVector(hv_CropPixel);
  }
  //Rotation with a given angular step size.
  if (0 != (int(HTuple(hv_Rotation[1])>0)))
  {
    hvec_AvailableDistortions[HTuple(hvec_AvailableDistortions.Length())] = HTupleVector(hv_Rotation);
  }
  //Rotation within a given range (step size 1).
  if (0 != (int(HTuple(hv_RotationRange[1])>0)))
  {
    hvec_AvailableDistortions[HTuple(hvec_AvailableDistortions.Length())] = HTupleVector(hv_RotationRange);
  }
  //Mirroring: in row and column direction are allowed.
  if (0 != (HTuple(HTuple(hv_Mirror[1]).TupleRegexpTest("r")).TupleOr(HTuple(hv_Mirror[1]).TupleRegexpTest("c"))))
  {
    hvec_AvailableDistortions[HTuple(hvec_AvailableDistortions.Length())] = HTupleVector(hv_Mirror);
  }
  //Brightness variation.
  if (0 != (int(HTuple(hv_BrightnessVariation[1])>0)))
  {
    hvec_AvailableDistortions[HTuple(hvec_AvailableDistortions.Length())] = HTupleVector(hv_BrightnessVariation);
  }
  //Brightness variation spot.
  if (0 != (int(HTuple(hv_BrightnessVariationSpot[1])>0)))
  {
    hvec_AvailableDistortions[HTuple(hvec_AvailableDistortions.Length())] = HTupleVector(hv_BrightnessVariationSpot);
  }
  //Check number of available distortions
  hv_NumAvailableDistortions = HTuple(hvec_AvailableDistortions.Length());
  if (0 != (int(hv_NumAvailableDistortions==0)))
  {
    (*ho_ImagesAugmented) = ho_Images;
    return;
  }
  //
  //Randomly choose images and augmentation methods.
  //
  //Number of images to be augmented.
  CountObj(ho_Images, &hv_NumImages);
  if (0 != (int(hv_NumImages==0)))
  {
    throw HException("There are no images to be processed.");
  }
  //Calculate how many images are to be augmented.
  hv_AugmentationRate = HTuple(hv_AugmentationPercentage[1])*0.01;
  hv_NumAugmentations = ((hv_AugmentationRate*hv_NumImages).TupleCeil()).TupleInt();
  //Select a random subset of images
  //that are to be augmented.
  tuple_shuffle(HTuple::TupleGenSequence(0,hv_NumImages-1,1), &hv_ImageIndices);
  hv_SelectedImages = hv_ImageIndices.TupleSelectRange(0,hv_NumAugmentations-1);
  //Select a random distortion method for each image.
  hv_SelectedDistortions = ((HTuple::TupleRand(hv_NumAugmentations)*hv_NumAvailableDistortions).TupleFloor()).TupleInt();
  //Fill up vector of distortions for all input images.
  hvec_Distortions = HTupleVector(1);
  hv_IndexDistortion = 0;
  {
  HTuple end_val181 = hv_NumImages-1;
  HTuple step_val181 = 1;
  for (hv_Index=0; hv_Index.Continue(end_val181, step_val181); hv_Index += step_val181)
  {
    //Check if Index corresponds to a selected image.
    if (0 != (int(((hv_SelectedImages.TupleEqualElem(hv_Index)).TupleSum())>0)))
    {
      //Add a distortion method.
      hvec_Distortions[hv_Index] = hvec_AvailableDistortions[HTuple(hv_SelectedDistortions[hv_IndexDistortion])];
      hv_IndexDistortion += 1;
    }
    else
    {
      //Image will not be distorted.
      hvec_Distortions[hv_Index] = HTupleVector((HTuple("none").Append(0)));
    }
  }
  }
  //
  //Augment (distort) the images.
  //
  //Generate output image array.
  GenEmptyObj(&(*ho_ImagesAugmented));
  //Loop over all images and apply distortions.
  {
  HTuple end_val198 = hv_NumImages-1;
  HTuple step_val198 = 1;
  for (hv_ImageIndex=0; hv_ImageIndex.Continue(end_val198, step_val198); hv_ImageIndex += step_val198)
  {
    //Get distortion method.
    hv_CurrentDistortion = hvec_Distortions[hv_ImageIndex].T();
    //Get image to be processed.
    SelectObj(ho_Images, &ho_ImageSelected, hv_ImageIndex+1);
    GetImageSize(ho_ImageSelected, &hv_Width, &hv_Height);
    if (0 != (int(HTuple(hv_CurrentDistortion[0])==HTuple(hv_CropPercentage[0]))))
    {
      //Cropping:
      //Define cropping rectangle.
      hv_CropRate = HTuple(hv_CurrentDistortion[1])*0.01;
      hv_Row1 = (((1-hv_CropRate)*hv_Height)*HTuple::TupleRand(1)).TupleFloor();
      hv_Row2 = hv_Row1+(hv_CropRate*hv_Height);
      hv_Column1 = (((1-hv_CropRate)*hv_Width)*HTuple::TupleRand(1)).TupleFloor();
      hv_Column2 = hv_Column1+(hv_CropRate*hv_Width);
      //Crop the image and add to output.
      CropRectangle1(ho_ImageSelected, &ho_ImagePart, hv_Row1, hv_Column1, hv_Row2, 
          hv_Column2);
      ConcatObj((*ho_ImagesAugmented), ho_ImagePart, &(*ho_ImagesAugmented));
    }
    else if (0 != (int(HTuple(hv_CurrentDistortion[0])==HTuple(hv_CropPixel[0]))))
    {
      //Cropping:
      //Define cropping rectangle.
      hv_Length = ((const HTuple&)hv_CurrentDistortion)[1];
      hv_Row1 = HTuple::TupleRand(1)*(hv_Height-hv_Length);
      hv_Row2 = (hv_Row1+hv_Length)-1;
      hv_Column1 = HTuple::TupleRand(1)*(hv_Width-hv_Length);
      hv_Column2 = (hv_Column1+hv_Length)-1;
      //Crop the image and add to output.
      CropRectangle1(ho_ImageSelected, &ho_ImagePart, hv_Row1, hv_Column1, hv_Row2, 
          hv_Column2);
      ConcatObj((*ho_ImagesAugmented), ho_ImagePart, &(*ho_ImagesAugmented));
    }
    else if (0 != (HTuple(int(HTuple(hv_CurrentDistortion[0])==HTuple(hv_Rotation[0]))).TupleOr(int(HTuple(hv_CurrentDistortion[0])==HTuple(hv_RotationRange[0])))))
    {
      //Rotation:
      if (0 != (int(HTuple(hv_CurrentDistortion[0])==HTuple(hv_Rotation[0]))))
      {
        //Determine rotation angle for method 'rotate' (angle in range [0:CurrentDistortion[1]:360)).
        hv_RotationStep = ((const HTuple&)hv_CurrentDistortion)[1];
        hv_NumPossibleRotations = 360.0/hv_RotationStep;
        hv_CurrentRotation = hv_RotationStep*(((hv_NumPossibleRotations*HTuple::TupleRand(1)).TupleInt())+1);
      }
      else
      {
        //Determine rotation angle for method 'rotate_range' (angle in range [0:1:CurrentDistortion[1])).
        hv_RotationStep = 1;
        hv_NumPossibleRotations = ((const HTuple&)hv_CurrentDistortion)[1];
        hv_CurrentRotation = hv_RotationStep*(((hv_NumPossibleRotations*HTuple::TupleRand(1)).TupleInt())+1);
        //Select direction of rotation randomly.
        if (0 != (int((HTuple::TupleRand(1).TupleRound())>0.5)))
        {
          hv_CurrentRotation = 360.0-hv_CurrentRotation;
        }
      }
      if (0 != (HTuple(int((hv_CurrentRotation.TupleInt())==hv_CurrentRotation)).TupleAnd(int(((hv_CurrentRotation.TupleInt())%90)==0))))
      {
        //Rotations around 90 degrees are faster with rotate_image
        RotateImage(ho_ImageSelected, &ho_ImagePart, hv_CurrentRotation.TupleInt(), 
            "constant");
      }
      else
      {
        //Create rotation matrix.
        HomMat2dIdentity(&hv_HomMat2DIdentity);
        HomMat2dRotate(hv_HomMat2DIdentity, hv_CurrentRotation.TupleRad(), hv_Height/2.0, 
            hv_Width/2.0, &hv_HomMat2DRotate);
        //Apply rotation.
        AffineTransImage(ho_ImageSelected, &ho_ImageRotated, hv_HomMat2DRotate, "constant", 
            "false");
        //Remove potential undefined domain.
        GetDomain(ho_ImageRotated, &ho_DomainRotated);
        InnerRectangle1(ho_DomainRotated, &hv_Row1, &hv_Column1, &hv_Row2, &hv_Column2);
        CropRectangle1(ho_ImageRotated, &ho_ImagePart, hv_Row1, hv_Column1, hv_Row2, 
            hv_Column2);
      }
      //Add the image to the output.
      ConcatObj((*ho_ImagesAugmented), ho_ImagePart, &(*ho_ImagesAugmented));
    }
    else if (0 != (int(HTuple(hv_CurrentDistortion[0])==HTuple(hv_Mirror[0]))))
    {
      //Mirroring:
      //If more than one method is allowed, chose mirroring method(s) to be applied.
      hv_NumMirrorMethods = HTuple(hv_CurrentDistortion[1]).TupleStrlen();
      hv_PropabilityMethods = 1.0/hv_NumMirrorMethods;
      hv_StrMirror = "";
      while (0 != (int(hv_StrMirror==HTuple(""))))
      {
        {
        HTuple end_val266 = hv_NumMirrorMethods-1;
        HTuple step_val266 = 1;
        for (hv_StrIdx=0; hv_StrIdx.Continue(end_val266, step_val266); hv_StrIdx += step_val266)
        {
          hv_SelectedChar = HTuple(hv_CurrentDistortion[1]).TupleStrBitSelect(hv_StrIdx);
          if (0 != (int(HTuple::TupleRand(1)<hv_PropabilityMethods)))
          {
            hv_StrMirror += hv_SelectedChar;
          }
        }
        }
      }
      //Apply the chosen mirroring method(s).
      if (0 != (hv_StrMirror.TupleRegexpTest("c")))
      {
        MirrorImage(ho_ImageSelected, &ho_ImageSelected, "column");
      }
      if (0 != (hv_StrMirror.TupleRegexpTest("r")))
      {
        MirrorImage(ho_ImageSelected, &ho_ImageSelected, "row");
      }
      //Add the image to the output.
      ConcatObj((*ho_ImagesAugmented), ho_ImageSelected, &(*ho_ImagesAugmented));
    }
    else if (0 != (int(HTuple(hv_CurrentDistortion[0])==HTuple(hv_BrightnessVariation[0]))))
    {
      //Brightness variation:
      //Add random brightness variation.
      hv_BrightnessVariationValue = ((HTuple::TupleRand(1)*2)-1)*HTuple(hv_CurrentDistortion[1]);
      ScaleImage(ho_ImageSelected, &ho_ImageScaled, 1.0, hv_BrightnessVariationValue);
      //Add the image to the output.
      ConcatObj((*ho_ImagesAugmented), ho_ImageScaled, &(*ho_ImagesAugmented));
    }
    else if (0 != (int(HTuple(hv_CurrentDistortion[0])==HTuple(hv_BrightnessVariationSpot[0]))))
    {
      //Determine random brightness variation.
      hv_BrightnessVariationValue = ((HTuple::TupleRand(1)*2)-1)*HTuple(hv_CurrentDistortion[1]);
      //Determine random spot size between [0.5*Width, Width].
      hv_SpotSize = hv_Width*((HTuple::TupleRand(1)/2)+.5);
      //Determine random spot position.
      hv_SpotRow = HTuple::TupleRand(1)*hv_Height;
      hv_SpotColumn = HTuple::TupleRand(1)*hv_Width;
      apply_brightness_variation_spot(ho_ImageSelected, &ho_ImageSpot, hv_SpotSize, 
          hv_SpotRow, hv_SpotColumn, hv_BrightnessVariationValue);
      //Add the image to the output.
      ConcatObj((*ho_ImagesAugmented), ho_ImageSpot, &(*ho_ImagesAugmented));
    }
    else
    {
      //Add unchanged image to the output.
      ConcatObj((*ho_ImagesAugmented), ho_ImageSelected, &(*ho_ImagesAugmented));
    }
  }
  }
  return;
}

// Chapter: Classification / Misc
// Short Description: Calculate color intensity features. 
void calc_feature_color_intensity (HObject ho_Region, HObject ho_Image, HTuple hv_ColorSpace, 
    HTuple hv_Mode, HTuple *hv_Feature)
{

  // Local iconic variables
  HObject  ho_R, ho_G, ho_B, ho_I1, ho_I2, ho_I3;

  // Local control variables
  HTuple  hv_Channels, hv_Mean1, hv_Deviation1;
  HTuple  hv_Mean2, hv_Deviation2, hv_Mean3, hv_Deviation3;
  HTuple  hv_Tmp1, hv_Tmp2, hv_Tmp3, hv_NumRegions, hv_Index;

  //
  //Calculate color features
  //
  //Transform an RGB image into the given ColorSpace
  //and calculate the mean gray value and the deviation
  //for all three channels.
  //
  CountChannels(ho_Image, &hv_Channels);
  if (0 != (int(hv_Channels!=3)))
  {
    throw HException(((("Error when calculating feature "+hv_ColorSpace)+"_")+hv_Mode).TupleConcat("Please use a 3-channel RGB image or remove color feature from the list."));
  }
  Decompose3(ho_Image, &ho_R, &ho_G, &ho_B);
  if (0 != (int(hv_ColorSpace==HTuple("rgb"))))
  {
    Intensity(ho_Region, ho_R, &hv_Mean1, &hv_Deviation1);
    Intensity(ho_Region, ho_G, &hv_Mean2, &hv_Deviation2);
    Intensity(ho_Region, ho_B, &hv_Mean3, &hv_Deviation3);
  }
  else
  {
    TransFromRgb(ho_R, ho_G, ho_B, &ho_I1, &ho_I2, &ho_I3, hv_ColorSpace);
    Intensity(ho_Region, ho_I1, &hv_Mean1, &hv_Deviation1);
    Intensity(ho_Region, ho_I2, &hv_Mean2, &hv_Deviation2);
    Intensity(ho_Region, ho_I3, &hv_Mean3, &hv_Deviation3);
  }
  if (0 != (int(hv_Mode==HTuple("mean"))))
  {
    hv_Tmp1 = hv_Mean1;
    hv_Tmp2 = hv_Mean2;
    hv_Tmp3 = hv_Mean3;
  }
  else if (0 != (int(hv_Mode==HTuple("deviation"))))
  {
    hv_Tmp1 = hv_Deviation1;
    hv_Tmp2 = hv_Deviation2;
    hv_Tmp3 = hv_Deviation3;
  }
  CountObj(ho_Region, &hv_NumRegions);
  if (0 != (int(hv_NumRegions>0)))
  {
    hv_Index = HTuple::TupleGenSequence(0,(3*hv_NumRegions)-1,3);
    (*hv_Feature)[hv_Index] = hv_Tmp1;
    (*hv_Feature)[1+hv_Index] = hv_Tmp2;
    (*hv_Feature)[2+hv_Index] = hv_Tmp3;
  }
  else
  {
    (*hv_Feature) = HTuple();
  }
  return;
}

// Chapter: Classification / Misc
// Short Description: Calculate edge density. 
void calc_feature_edge_density (HObject ho_Region, HObject ho_Image, HTuple *hv_Feature)
{

  // Local iconic variables
  HObject  ho_RegionUnion, ho_ImageReduced, ho_EdgeAmplitude;

  // Local control variables
  HTuple  hv_Area, hv_Row, hv_Column, hv_Width;
  HTuple  hv_Height, hv_AreaGray, hv_ZeroIndex;

  //
  //Calculate the edge density, i.e.
  //the ratio of the edge amplitudes to the area of the region.
  //
  Union1(ho_Region, &ho_RegionUnion);
  ReduceDomain(ho_Image, ho_RegionUnion, &ho_ImageReduced);
  AreaCenter(ho_Region, &hv_Area, &hv_Row, &hv_Column);
  GetImageSize(ho_ImageReduced, &hv_Width, &hv_Height);
  if (0 != (HTuple(int(hv_Width>1)).TupleAnd(int(hv_Height>1))))
  {
    SobelAmp(ho_ImageReduced, &ho_EdgeAmplitude, "sum_abs", 3);
    AreaCenterGray(ho_Region, ho_EdgeAmplitude, &hv_AreaGray, &hv_Row, &hv_Column);
    hv_ZeroIndex = hv_Area.TupleFind(0);
    if (0 != (int(hv_ZeroIndex!=-1)))
    {
      hv_Area[hv_ZeroIndex] = 1;
      hv_AreaGray[hv_ZeroIndex] = 0;
    }
    (*hv_Feature) = hv_AreaGray/hv_Area;
  }
  else
  {
    (*hv_Feature) = HTuple(hv_Area.TupleLength(),0.0);
  }
  return;
}

// Chapter: Classification / Misc
// Short Description: Calculate edge density histogram feature. 
void calc_feature_edge_density_histogram (HObject ho_Region, HObject ho_Image, HTuple hv_NumBins, 
    HTuple *hv_Feature)
{

  // Local iconic variables
  HObject  ho_Channel1, ho_EdgeAmplitude, ho_RegionSelected;

  // Local control variables
  HTuple  hv_ImageWidth, hv_ImageHeight, hv_NumRegions;
  HTuple  hv_J, hv_Area, hv_Row, hv_Column, hv_Min, hv_Max;
  HTuple  hv_Range, hv_Histo, hv_BinSize;

  //
  //Calculate the edge density histogram, i.e.
  //the ratio of the edge amplitude histogram to the area of the region.
  //
  (*hv_Feature) = HTuple();
  GetImageSize(ho_Image, &hv_ImageWidth, &hv_ImageHeight);
  CountObj(ho_Region, &hv_NumRegions);
  if (0 != (HTuple(int(hv_ImageWidth>1)).TupleAnd(int(hv_ImageHeight>1))))
  {
    AccessChannel(ho_Image, &ho_Channel1, 1);
    SobelAmp(ho_Channel1, &ho_EdgeAmplitude, "sum_abs", 3);
    {
    HTuple end_val10 = hv_NumRegions;
    HTuple step_val10 = 1;
    for (hv_J=1; hv_J.Continue(end_val10, step_val10); hv_J += step_val10)
    {
      SelectObj(ho_Region, &ho_RegionSelected, hv_J);
      AreaCenter(ho_RegionSelected, &hv_Area, &hv_Row, &hv_Column);
      MinMaxGray(ho_RegionSelected, ho_EdgeAmplitude, 0, &hv_Min, &hv_Max, &hv_Range);
      if (0 != (int(hv_Area>0)))
      {
        GrayHistoRange(ho_RegionSelected, ho_EdgeAmplitude, hv_Min, hv_Max, hv_NumBins, 
            &hv_Histo, &hv_BinSize);
        (*hv_Feature) = (*hv_Feature).TupleConcat((hv_Histo.TupleReal())/(hv_Histo.TupleSum()));
      }
      else
      {
        (*hv_Feature) = ((*hv_Feature).TupleConcat(1.0)).TupleConcat(HTuple(hv_NumBins-1,0.0));
      }
    }
    }
  }
  else
  {
    (*hv_Feature) = HTuple(hv_NumRegions*hv_NumBins,0.0);
  }
  return;
}

// Chapter: Classification / Misc
// Short Description: Calculate the gradient direction histogram. 
void calc_feature_grad_dir_histo (HObject ho_Region, HObject ho_Image, HTuple hv_NumBins, 
    HTuple *hv_Feature)
{

  // Local iconic variables
  HObject  ho_Channel1, ho_RegionSelected, ho_ImageReduced;
  HObject  ho_EdgeAmplitude, ho_EdgeDirection;

  // Local control variables
  HTuple  hv_NumRegions, hv_Index, hv_Histo, hv_BinSize;
  HTuple  hv_Sum;

  //
  //Calculate gradient direction histogram
  //
  AccessChannel(ho_Image, &ho_Channel1, 1);
  CountObj(ho_Region, &hv_NumRegions);
  (*hv_Feature) = HTuple();
  {
  HTuple end_val6 = hv_NumRegions;
  HTuple step_val6 = 1;
  for (hv_Index=1; hv_Index.Continue(end_val6, step_val6); hv_Index += step_val6)
  {
    SelectObj(ho_Region, &ho_RegionSelected, hv_Index);
    ReduceDomain(ho_Channel1, ho_RegionSelected, &ho_ImageReduced);
    SobelDir(ho_ImageReduced, &ho_EdgeAmplitude, &ho_EdgeDirection, "sum_abs_binomial", 
        3);
    GrayHistoRange(ho_RegionSelected, ho_EdgeDirection, 0, 179, hv_NumBins, &hv_Histo, 
        &hv_BinSize);
    hv_Sum = hv_Histo.TupleSum();
    if (0 != (int(hv_Sum!=0)))
    {
      (*hv_Feature) = (*hv_Feature).TupleConcat((hv_Histo.TupleReal())/hv_Sum);
    }
    else
    {
      (*hv_Feature) = (*hv_Feature).TupleConcat(hv_Histo);
    }
  }
  }
  return;
}

// Chapter: Classification / Misc
// Short Description: Calculate gray-value projections and their histograms. 
void calc_feature_gray_proj (HObject ho_Region, HObject ho_Image, HTuple hv_Mode, 
    HTuple hv_Size, HTuple *hv_Feature)
{

  // Local iconic variables
  HObject  ho_RegionTmp, ho_RegionMoved, ho_ImageTmp;

  // Local control variables
  HTuple  hv_NumRegions, hv_Index, hv_RowsTmp, hv_ColumnsTmp;
  HTuple  hv_HorProjectionFilledUp, hv_VertProjectionFilledUp;
  HTuple  hv_Row1, hv_Column1, hv_Row2, hv_Column2, hv_ScaleHeight;
  HTuple  hv_ScaleWidth, hv_HorProjection, hv_VertProjection;
  HTuple  hv_HorProjectionFilledUpFront, hv_VertProjectionFilledUpFront;
  HTuple  hv_Histo, hv_BinSize;

  //
  //Calculate gray-value projections and their histograms
  //
  CountObj(ho_Region, &hv_NumRegions);
  (*hv_Feature) = HTuple();
  //
  {
  HTuple end_val6 = hv_NumRegions;
  HTuple step_val6 = 1;
  for (hv_Index=1; hv_Index.Continue(end_val6, step_val6); hv_Index += step_val6)
  {
    SelectObj(ho_Region, &ho_RegionTmp, hv_Index);
    //Test empty region
    GetRegionPoints(ho_RegionTmp, &hv_RowsTmp, &hv_ColumnsTmp);
    if (0 != (int((hv_RowsTmp.TupleLength())==0)))
    {
      hv_HorProjectionFilledUp = HTuple(hv_Size,-1.0);
      hv_VertProjectionFilledUp = HTuple(hv_Size,-1.0);
    }
    else
    {
      //Zoom image and region to Size x Size pixels
      SmallestRectangle1(ho_RegionTmp, &hv_Row1, &hv_Column1, &hv_Row2, &hv_Column2);
      MoveRegion(ho_RegionTmp, &ho_RegionMoved, -hv_Row1, -hv_Column1);
      CropRectangle1(ho_Image, &ho_ImageTmp, hv_Row1, hv_Column1, hv_Row2, hv_Column2);
      hv_ScaleHeight = (hv_Size.TupleReal())/((hv_Row2-hv_Row1)+1);
      hv_ScaleWidth = (hv_Size.TupleReal())/((hv_Column2-hv_Column1)+1);
      ZoomImageFactor(ho_ImageTmp, &ho_ImageTmp, hv_ScaleWidth, hv_ScaleHeight, "constant");
      ZoomRegion(ho_RegionMoved, &ho_RegionTmp, hv_ScaleWidth, hv_ScaleHeight);
      //Calculate gray value projection
      GrayProjections(ho_RegionTmp, ho_ImageTmp, "simple", &hv_HorProjection, &hv_VertProjection);
      //Fill up projection in case the zoomed region is smaller than
      //Size x Size pixels due to interpolation effects
      SmallestRectangle1(ho_RegionTmp, &hv_Row1, &hv_Column1, &hv_Row2, &hv_Column2);
      hv_HorProjectionFilledUpFront.Clear();
      hv_HorProjectionFilledUpFront.Append(HTuple(HTuple(0).TupleMax2(hv_Row1),-1.0));
      hv_HorProjectionFilledUpFront.Append(hv_HorProjection);
      hv_HorProjectionFilledUp.Clear();
      hv_HorProjectionFilledUp.Append(hv_HorProjectionFilledUpFront);
      hv_HorProjectionFilledUp.Append(HTuple(hv_Size-(hv_HorProjectionFilledUpFront.TupleLength()),-1.0));
      hv_VertProjectionFilledUpFront.Clear();
      hv_VertProjectionFilledUpFront.Append(HTuple(HTuple(0).TupleMax2(hv_Column1),-1.0));
      hv_VertProjectionFilledUpFront.Append(hv_VertProjection);
      hv_VertProjectionFilledUp.Clear();
      hv_VertProjectionFilledUp.Append(hv_VertProjectionFilledUpFront);
      hv_VertProjectionFilledUp.Append(HTuple(hv_Size-(hv_VertProjectionFilledUpFront.TupleLength()),-1.0));
    }
    if (0 != (int(hv_Mode==HTuple("hor"))))
    {
      (*hv_Feature) = (*hv_Feature).TupleConcat(hv_HorProjectionFilledUp);
    }
    else if (0 != (int(hv_Mode==HTuple("vert"))))
    {
      (*hv_Feature) = (*hv_Feature).TupleConcat(hv_VertProjectionFilledUp);
    }
    else if (0 != (int(hv_Mode==HTuple("hor_histo"))))
    {
      TupleHistoRange(hv_HorProjectionFilledUp, 0, 255, hv_Size, &hv_Histo, &hv_BinSize);
      (*hv_Feature) = (*hv_Feature).TupleConcat(hv_Histo);
    }
    else if (0 != (int(hv_Mode==HTuple("vert_histo"))))
    {
      TupleHistoRange(hv_VertProjectionFilledUp, 0, 255, hv_Size, &hv_Histo, &hv_BinSize);
      (*hv_Feature) = (*hv_Feature).TupleConcat(hv_Histo);
    }
  }
  }
  return;
}

// Chapter: Classification / Misc
// Short Description: Calculate gray-value projections of polar-transformed image regions. 
void calc_feature_polar_gray_proj (HObject ho_Region, HObject ho_Image, HTuple hv_Mode, 
    HTuple hv_Width, HTuple hv_Height, HTuple *hv_Features)
{

  // Local iconic variables
  HObject  ho_RegionSelected, ho_PolarTransImage;
  HObject  ho_EdgeAmplitude, ho_ImageAbs;

  // Local control variables
  HTuple  hv_NumRegions, hv_Index, hv_Row, hv_Column;
  HTuple  hv_Radius, hv_HorProjection, hv_VertProjection;

  //
  //Calculate gray-value projections of
  //polar-transformed image regions.
  //
  CountObj(ho_Region, &hv_NumRegions);
  (*hv_Features) = HTuple();
  {
  HTuple end_val6 = hv_NumRegions;
  HTuple step_val6 = 1;
  for (hv_Index=1; hv_Index.Continue(end_val6, step_val6); hv_Index += step_val6)
  {
    SelectObj(ho_Region, &ho_RegionSelected, hv_Index);
    SmallestCircle(ho_RegionSelected, &hv_Row, &hv_Column, &hv_Radius);
    PolarTransImageExt(ho_Image, &ho_PolarTransImage, hv_Row, hv_Column, 0, HTuple(360).TupleRad(), 
        0, (hv_Radius.TupleConcat(1)).TupleMax(), hv_Width, hv_Height, "bilinear");
    //
    if (0 != (int(hv_Mode==HTuple("hor_gray"))))
    {
      GrayProjections(ho_PolarTransImage, ho_PolarTransImage, "simple", &hv_HorProjection, 
          &hv_VertProjection);
      (*hv_Features) = (*hv_Features).TupleConcat(hv_HorProjection);
    }
    else if (0 != (int(hv_Mode==HTuple("vert_gray"))))
    {
      GrayProjections(ho_PolarTransImage, ho_PolarTransImage, "simple", &hv_HorProjection, 
          &hv_VertProjection);
      (*hv_Features) = (*hv_Features).TupleConcat(hv_VertProjection);
    }
    else if (0 != (int(hv_Mode==HTuple("hor_sobel_amp"))))
    {
      SobelAmp(ho_PolarTransImage, &ho_EdgeAmplitude, "sum_abs", 3);
      AbsImage(ho_EdgeAmplitude, &ho_ImageAbs);
      GrayProjections(ho_ImageAbs, ho_ImageAbs, "simple", &hv_HorProjection, &hv_VertProjection);
      (*hv_Features) = (*hv_Features).TupleConcat(hv_HorProjection);
    }
    else if (0 != (int(hv_Mode==HTuple("vert_sobel_amp"))))
    {
      SobelAmp(ho_PolarTransImage, &ho_EdgeAmplitude, "sum_abs", 3);
      AbsImage(ho_EdgeAmplitude, &ho_ImageAbs);
      GrayProjections(ho_ImageAbs, ho_ImageAbs, "simple", &hv_HorProjection, &hv_VertProjection);
      (*hv_Features) = (*hv_Features).TupleConcat(hv_VertProjection);
    }
    else if (0 != (int(hv_Mode==HTuple("hor_sobel_x"))))
    {
      SobelAmp(ho_PolarTransImage, &ho_EdgeAmplitude, "x_binomial", 3);
      AbsImage(ho_EdgeAmplitude, &ho_ImageAbs);
      GrayProjections(ho_ImageAbs, ho_ImageAbs, "simple", &hv_HorProjection, &hv_VertProjection);
      (*hv_Features) = (*hv_Features).TupleConcat(hv_HorProjection);
    }
    else if (0 != (int(hv_Mode==HTuple("vert_sobel_x"))))
    {
      SobelAmp(ho_PolarTransImage, &ho_EdgeAmplitude, "x_binomial", 3);
      AbsImage(ho_EdgeAmplitude, &ho_ImageAbs);
      GrayProjections(ho_ImageAbs, ho_ImageAbs, "simple", &hv_HorProjection, &hv_VertProjection);
      (*hv_Features) = (*hv_Features).TupleConcat(hv_VertProjection);
    }
    else if (0 != (int(hv_Mode==HTuple("hor_sobel_y"))))
    {
      SobelAmp(ho_PolarTransImage, &ho_EdgeAmplitude, "y_binomial", 3);
      AbsImage(ho_EdgeAmplitude, &ho_ImageAbs);
      GrayProjections(ho_ImageAbs, ho_ImageAbs, "simple", &hv_HorProjection, &hv_VertProjection);
      (*hv_Features) = (*hv_Features).TupleConcat(hv_HorProjection);
    }
    else if (0 != (int(hv_Mode==HTuple("vert_sobel_y"))))
    {
      SobelAmp(ho_PolarTransImage, &ho_EdgeAmplitude, "y_binomial", 3);
      AbsImage(ho_EdgeAmplitude, &ho_ImageAbs);
      GrayProjections(ho_ImageAbs, ho_ImageAbs, "simple", &hv_HorProjection, &hv_VertProjection);
      (*hv_Features) = (*hv_Features).TupleConcat(hv_VertProjection);
    }
    else
    {
      throw HException(("Unknown Mode: "+hv_Mode)+" in calc_feature_polar_proj");
    }
  }
  }
  return;
}

// Chapter: Classification / Misc
// Short Description: Calculate a feature on different image pyramid levels. 
void calc_feature_pyramid (HObject ho_Region, HObject ho_Image, HTuple hv_FeatureName, 
    HTuple hv_NumLevels, HTuple *hv_Feature)
{

  // Local iconic variables
  HObject  ho_ImageZoom, ho_RegionZoom;

  // Local control variables
  HTuple  hv_Zoom, hv_NumRegions, hv_I, hv_Features;
  HTuple  hv_FeatureLength, hv_Step, hv_Indices, hv_J, hv_Start;
  HTuple  hv_End;

  //
  //Calculate a feature for different pyramid levels
  //
  hv_Zoom = 0.5;
  (*hv_Feature) = HTuple();
  CountObj(ho_Region, &hv_NumRegions);
  if (0 != (int(hv_NumRegions>0)))
  {
    {
    HTuple end_val7 = hv_NumLevels;
    HTuple step_val7 = 1;
    for (hv_I=1; hv_I.Continue(end_val7, step_val7); hv_I += step_val7)
    {
      if (0 != (int(hv_I>1)))
      {
        ZoomImageFactor(ho_ImageZoom, &ho_ImageZoom, hv_Zoom, hv_Zoom, "constant");
        ZoomRegion(ho_RegionZoom, &ho_RegionZoom, hv_Zoom, hv_Zoom);
        calculate_features(ho_RegionZoom, ho_ImageZoom, hv_FeatureName, &hv_Features);
      }
      else
      {
        CopyObj(ho_Image, &ho_ImageZoom, 1, 1);
        CopyObj(ho_Region, &ho_RegionZoom, 1, hv_NumRegions);
        calculate_features(ho_RegionZoom, ho_ImageZoom, hv_FeatureName, &hv_Features);
        hv_FeatureLength = (hv_Features.TupleLength())/hv_NumRegions;
        hv_Step = hv_NumLevels*hv_FeatureLength;
      }
      hv_Indices = HTuple();
      {
      HTuple end_val20 = hv_NumRegions-1;
      HTuple step_val20 = 1;
      for (hv_J=0; hv_J.Continue(end_val20, step_val20); hv_J += step_val20)
      {
        hv_Start = (hv_J*hv_Step)+((hv_I-1)*hv_FeatureLength);
        hv_End = (hv_Start+hv_FeatureLength)-1;
        hv_Indices = hv_Indices.TupleConcat(HTuple::TupleGenSequence(hv_Start,hv_End,1));
      }
      }
      (*hv_Feature)[hv_Indices] = hv_Features;
    }
    }
  }
  return;
}

// Chapter: Deep Learning / Anomaly Detection and Global Context Anomaly Detection
// Short Description: Calculate quantiles of pixel anomaly scores. 
void calculate_dl_anomaly_quantiles (HTuple hv_DLModelHandle, HTuple hv_LayerName, 
    HTuple hv_DLSamples, HTuple hv_Ps, HTuple *hv_Quantiles)
{

  // Local iconic variables
  HObject  ho_LayerOutput;

  // Local control variables
  HTuple  hv_Shape, hv_N, hv_C, hv_H, hv_W, hv_PixelScores;
  HTuple  hv_NumIterations, hv_Index, hv_FirstSampleIdx, hv_LastSampleIdx;
  HTuple  hv_DLSamplesBatch, hv_DLResultBatch, hv_IndexSamples;
  HTuple  hv_Iteration, hv_SampleDict, hv_Rows, hv_Columns;
  HTuple  hv_LayerOutputValues, hv_SliceStart, hv_SliceEnd;
  HTuple  hv_IndexP;

  //This procedure calculates quantiles of unnormalized pixel anomaly
  //scores returned by a given GC-AD model.
  //
  //The layer output has the shape N x C x H x W, where
  //- N is the batch size,
  //- C is number of channels, and
  //- H and W are the height and width, respectively.
  //
  GetDlModelLayerParam(hv_DLModelHandle, hv_LayerName, "shape", &hv_Shape);
  hv_N = ((const HTuple&)hv_Shape)[3];
  hv_C = ((const HTuple&)hv_Shape)[2];
  if (0 != (int(hv_C!=1)))
  {
    throw HException("Only layers with a single output channel are supported.");
  }
  hv_H = ((const HTuple&)hv_Shape)[1];
  hv_W = ((const HTuple&)hv_Shape)[0];
  hv_PixelScores = HTuple(((hv_DLSamples.TupleLength())*hv_H)*hv_W,0.0);
  hv_NumIterations = ((hv_DLSamples.TupleLength())/(hv_N.TupleReal())).TupleCeil();
  {
  HTuple end_val18 = hv_NumIterations-1;
  HTuple step_val18 = 1;
  for (hv_Index=0; hv_Index.Continue(end_val18, step_val18); hv_Index += step_val18)
  {
    hv_FirstSampleIdx = hv_Index*hv_N;
    hv_LastSampleIdx = (((hv_Index+1)*hv_N)-1).TupleMin2((hv_DLSamples.TupleLength())-1);
    hv_DLSamplesBatch = hv_DLSamples.TupleSelectRange(hv_FirstSampleIdx,hv_LastSampleIdx);
    ApplyDlModel(hv_DLModelHandle, hv_DLSamplesBatch, hv_LayerName, &hv_DLResultBatch);
    //
    {
    HTuple end_val24 = (hv_DLResultBatch.TupleLength())-1;
    HTuple step_val24 = 1;
    for (hv_IndexSamples=0; hv_IndexSamples.Continue(end_val24, step_val24); hv_IndexSamples += step_val24)
    {
      hv_Iteration = (hv_Index*hv_N)+hv_IndexSamples;
      //
      hv_SampleDict = HTuple(hv_DLResultBatch[hv_IndexSamples]);
      ho_LayerOutput = hv_SampleDict.TupleGetDictObject(hv_LayerName);
      //
      GetRegionPoints(ho_LayerOutput, &hv_Rows, &hv_Columns);
      GetGrayval(ho_LayerOutput, hv_Rows, hv_Columns, &hv_LayerOutputValues);
      hv_SliceStart = (hv_Iteration*hv_H)*hv_W;
      hv_SliceEnd = (hv_SliceStart+(hv_H*hv_W))-1;
      hv_PixelScores[HTuple::TupleGenSequence(hv_SliceStart,hv_SliceEnd,1)] = hv_LayerOutputValues;
    }
    }
  }
  }
  hv_PixelScores = hv_PixelScores.TupleSort();
  //
  (*hv_Quantiles) = HTuple(hv_Ps.TupleLength(),0.0);
  {
  HTuple end_val40 = (hv_Ps.TupleLength())-1;
  HTuple step_val40 = 1;
  for (hv_IndexP=0; hv_IndexP.Continue(end_val40, step_val40); hv_IndexP += step_val40)
  {
    (*hv_Quantiles)[hv_IndexP] = HTuple(hv_PixelScores[(HTuple(hv_Ps[hv_IndexP])*((hv_PixelScores.TupleLength())-1)).TupleRound()]);
  }
  }
  //
  return;
}

// Chapter: Deep Learning / Model
// Short Description: Compute zoom factors to fit an image to a target size. 
void calculate_dl_image_zoom_factors (HTuple hv_ImageWidth, HTuple hv_ImageHeight, 
    HTuple hv_TargetWidth, HTuple hv_TargetHeight, HTuple hv_DLPreprocessParam, HTuple *hv_ZoomFactorWidth, 
    HTuple *hv_ZoomFactorHeight)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_ScaleWidthUnit, hv_ScaleHeightUnit;
  HTuple  hv_PreserveAspectRatio, hv_Scale, hv___Tmp_Ctrl_Dict_Init_0;

  //Calculate the unit zoom factors, which zoom the input image to 1px.
  hv_ScaleWidthUnit = 1.0/(hv_ImageWidth.TupleReal());
  hv_ScaleHeightUnit = 1.0/(hv_ImageHeight.TupleReal());
  //
  //Calculate the required zoom factors for the available target size.
  (*hv_ZoomFactorWidth) = hv_TargetWidth*hv_ScaleWidthUnit;
  (*hv_ZoomFactorHeight) = hv_TargetHeight*hv_ScaleHeightUnit;
  //
  //Aspect-ratio preserving zoom is supported for model type 'ocr_detection' only.
  CreateDict(&hv___Tmp_Ctrl_Dict_Init_0);
  SetDictTuple(hv___Tmp_Ctrl_Dict_Init_0, "comp", "ocr_detection");
  hv_PreserveAspectRatio = (hv_DLPreprocessParam.TupleConcat(hv___Tmp_Ctrl_Dict_Init_0)).TupleTestEqualDictItem("model_type","comp");
  hv___Tmp_Ctrl_Dict_Init_0 = HTuple::TupleConstant("HNULL");
  //
  if (0 != hv_PreserveAspectRatio)
  {
    //
    //Use smaller scaling factor, which results in unfilled domain
    //on the respective other axis.
    hv_Scale = (*hv_ZoomFactorWidth).TupleMin2((*hv_ZoomFactorHeight));
    //Ensure that the zoom factors result in lengths of at least 1px.
    (*hv_ZoomFactorWidth) = hv_Scale.TupleMax2(hv_ScaleWidthUnit);
    (*hv_ZoomFactorHeight) = hv_Scale.TupleMax2(hv_ScaleHeightUnit);
  }
  return;
}

// Chapter: Deep Learning / Anomaly Detection and Global Context Anomaly Detection
// Short Description: Calculate the channel-wise mean and standard deviation of a DL model layer. 
void calculate_dl_model_layer_mean_stddev (HTuple hv_DLModelHandle, HTuple hv_LayerName, 
    HTuple hv_DLSamples, HTuple *hv_Mean, HTuple *hv_StdDev)
{

  // Local iconic variables
  HObject  ho_LayerOutput, ho_SquaredLayerOutput;
  HObject  ho_MeanOfFeatureMaps, ho_MeanOfSquaredFeatureMaps;
  HObject  ho_UpdateScaled, ho_MeanOfFeatureMap, ho_MeanOfSquaredFeatureMap;

  // Local control variables
  HTuple  hv_Shape, hv_N, hv_C, hv_NumIterations;
  HTuple  hv_Index, hv_FirstSampleIdx, hv_LastSampleIdx, hv_DLSamplesBatch;
  HTuple  hv_DLResultBatch, hv_IndexSamples, hv_Iteration;
  HTuple  hv_SampleDict, hv_Var, hv_IndexC, hv_FeatureMapMean;
  HTuple  hv__, hv_FeatureMapSquaredMean;

  //Calculate the running mean and standard deviation of a
  //DL model layer. The layer output has the shape
  //N x C x H x W, where
  //- N is the batch size,
  //- C is number of channels, and
  //- H and W are the height and width, respectively.
  //
  GetDlModelLayerParam(hv_DLModelHandle, hv_LayerName, "shape", &hv_Shape);
  hv_N = ((const HTuple&)hv_Shape)[3];
  hv_C = ((const HTuple&)hv_Shape)[2];
  //Compute the average of the layer output and its square
  //over all samples.
  hv_NumIterations = ((hv_DLSamples.TupleLength())/(hv_N.TupleReal())).TupleCeil();
  {
  HTuple end_val13 = hv_NumIterations-1;
  HTuple step_val13 = 1;
  for (hv_Index=0; hv_Index.Continue(end_val13, step_val13); hv_Index += step_val13)
  {
    hv_FirstSampleIdx = hv_Index*hv_N;
    hv_LastSampleIdx = (((hv_Index+1)*hv_N)-1).TupleMin2((hv_DLSamples.TupleLength())-1);
    hv_DLSamplesBatch = hv_DLSamples.TupleSelectRange(hv_FirstSampleIdx,hv_LastSampleIdx);
    ApplyDlModel(hv_DLModelHandle, hv_DLSamplesBatch, hv_LayerName, &hv_DLResultBatch);
    //
    {
    HTuple end_val19 = (hv_DLResultBatch.TupleLength())-1;
    HTuple step_val19 = 1;
    for (hv_IndexSamples=0; hv_IndexSamples.Continue(end_val19, step_val19); hv_IndexSamples += step_val19)
    {
      hv_Iteration = (hv_Index*hv_N)+hv_IndexSamples;
      //
      hv_SampleDict = HTuple(hv_DLResultBatch[hv_IndexSamples]);
      ho_LayerOutput = hv_SampleDict.TupleGetDictObject(hv_LayerName);
      MultImage(ho_LayerOutput, ho_LayerOutput, &ho_SquaredLayerOutput, 1, 0);
      //
      if (0 != (int(hv_Iteration==0)))
      {
        ScaleImage(ho_LayerOutput, &ho_MeanOfFeatureMaps, 1.0/(hv_DLSamples.TupleLength()), 
            0);
        ScaleImage(ho_SquaredLayerOutput, &ho_MeanOfSquaredFeatureMaps, 1.0/(hv_DLSamples.TupleLength()), 
            0);
      }
      else
      {
        ScaleImage(ho_LayerOutput, &ho_UpdateScaled, 1.0/(hv_DLSamples.TupleLength()), 
            0);
        AddImage(ho_MeanOfFeatureMaps, ho_UpdateScaled, &ho_MeanOfFeatureMaps, 1, 
            0);
        //
        ScaleImage(ho_SquaredLayerOutput, &ho_UpdateScaled, 1.0/(hv_DLSamples.TupleLength()), 
            0);
        AddImage(ho_MeanOfSquaredFeatureMaps, ho_UpdateScaled, &ho_MeanOfSquaredFeatureMaps, 
            1, 0);
      }
    }
    }
  }
  }
  //
  (*hv_Mean) = HTuple(hv_C,0.0);
  hv_Var = HTuple(hv_C,0.0);
  //
  {
  HTuple end_val42 = hv_C-1;
  HTuple step_val42 = 1;
  for (hv_IndexC=0; hv_IndexC.Continue(end_val42, step_val42); hv_IndexC += step_val42)
  {
    //Compute Var[X] as E[X^2] - (E[X])^2.
    AccessChannel(ho_MeanOfFeatureMaps, &ho_MeanOfFeatureMap, hv_IndexC+1);
    Intensity(ho_MeanOfFeatureMap, ho_MeanOfFeatureMap, &hv_FeatureMapMean, &hv__);
    AccessChannel(ho_MeanOfSquaredFeatureMaps, &ho_MeanOfSquaredFeatureMap, hv_IndexC+1);
    Intensity(ho_MeanOfSquaredFeatureMap, ho_MeanOfSquaredFeatureMap, &hv_FeatureMapSquaredMean, 
        &hv__);
    (*hv_Mean)[hv_IndexC] = hv_FeatureMapMean;
    hv_Var[hv_IndexC] = hv_FeatureMapSquaredMean-(hv_FeatureMapMean*hv_FeatureMapMean);
  }
  }
  (*hv_StdDev) = hv_Var.TupleSqrt();
  return;
}

// Chapter: Deep Learning / Semantic Segmentation and Edge Extraction
// Short Description: Calculate the class weights for a semantic segmentation dataset. 
void calculate_dl_segmentation_class_weights (HTuple hv_DLDataset, HTuple hv_MaxWeight, 
    HTuple hv_IgnoreClassIDs, HTuple *hv_ClassWeights)
{

  // Local iconic variables
  HObject  ho_SegmentationImage;

  // Local control variables
  HTuple  hv_KeysExists, hv_DLSamples, hv_SampleIndices;
  HTuple  hv_ClassIDs, hv_ClassIDsToClassIndex, hv_ClassAreas;
  HTuple  hv_SampleIndex, hv_DLSample, hv_ImageType, hv_AbsoluteHisto;
  HTuple  hv_IgnoreAreas, hv_TotalArea, hv_ValidClasses, hv_ClassFreq;
  HTuple  hv_IndicesToClip;

  //
  //This procedure calculates a weight for each class that is present in the Dataset.
  //The class weights are calculated according to the inverse class frequencies
  //in the training dataset.
  //Therefore, the dataset has to be split before calling this procedure.
  //
  //Check if the input is correct.
  GetDictParam(hv_DLDataset, "key_exists", (HTuple("samples").Append("class_ids")), 
      &hv_KeysExists);
  if (0 != (HTuple(hv_KeysExists[0]).TupleNot()))
  {
    throw HException("DLDataset must contain a key-value pair for 'samples'");
  }
  if (0 != (HTuple(hv_KeysExists[1]).TupleNot()))
  {
    throw HException("DLDataset must contain a key-value pair for 'class_ids'");
  }
  if (0 != (int(hv_MaxWeight<=0)))
  {
    throw HException("MaxWeight must be greater than 0");
  }
  //
  //Get the samples of the dataset.
  GetDictTuple(hv_DLDataset, "samples", &hv_DLSamples);
  //Get the train samples.
  find_dl_samples(hv_DLSamples, "split", "train", "match", &hv_SampleIndices);
  if (0 != (int((hv_SampleIndices.TupleLength())==0)))
  {
    throw HException("The DLDataset does not contain any samples with value 'train' for key 'split'");
  }
  //
  //Get the class IDs of the dataset.
  GetDictTuple(hv_DLDataset, "class_ids", &hv_ClassIDs);
  //
  //Define mapping from class ID to class index.
  create_dl_class_id_mapping(hv_ClassIDs, &hv_ClassIDsToClassIndex);
  //
  //We want to collect the number of pixels for each class.
  hv_ClassAreas = HTuple(hv_ClassIDs.TupleLength(),0);
  //
  //Loop over the samples.
  {
  HTuple end_val36 = (hv_SampleIndices.TupleLength())-1;
  HTuple step_val36 = 1;
  for (hv_SampleIndex=0; hv_SampleIndex.Continue(end_val36, step_val36); hv_SampleIndex += step_val36)
  {
    //
    //Read the sample.
    read_dl_samples(hv_DLDataset, HTuple(hv_SampleIndices[hv_SampleIndex]), &hv_DLSample);
    //
    //Get the segmentation image.
    GetDictObject(&ho_SegmentationImage, hv_DLSample, "segmentation_image");
    //
    //Convert the segmentation image if necessary.
    GetImageType(ho_SegmentationImage, &hv_ImageType);
    if (0 != (int(((((HTuple("int1").Append("int2")).Append("uint2")).Append("byte")).TupleFind(hv_ImageType))==-1)))
    {
      ConvertImageType(ho_SegmentationImage, &ho_SegmentationImage, "uint2");
    }
    //
    //Get the number of pixels for each class.
    GrayHistoAbs(ho_SegmentationImage, ho_SegmentationImage, 1, &hv_AbsoluteHisto);
    //
    //Accumulate the areas.
    hv_ClassAreas += HTuple(hv_AbsoluteHisto[hv_ClassIDs]);
  }
  }
  //
  //Get the total number of pixels without the area of ignore classes.
  GetDictTuple(hv_ClassIDsToClassIndex, hv_IgnoreClassIDs, &hv_IgnoreAreas);
  hv_ClassAreas[hv_IgnoreAreas] = 0;
  hv_TotalArea = hv_ClassAreas.TupleSum();
  //
  //Calculate the inverse class frequencies.
  (*hv_ClassWeights) = HTuple(hv_ClassIDs.TupleLength(),0.);
  hv_ValidClasses = (hv_ClassAreas.TupleNotEqualElem(0)).TupleFind(1);
  hv_ClassFreq = hv_ClassAreas/(hv_TotalArea.TupleReal());
  (*hv_ClassWeights)[hv_ValidClasses] = 1./(HTuple(hv_ClassFreq[hv_ValidClasses])+0.0001);
  //
  //Scale the weights to obtain a final output of 1.0 for the most frequent class.
  (*hv_ClassWeights) = (*hv_ClassWeights)/(HTuple((*hv_ClassWeights)[hv_ValidClasses]).TupleMin());
  //Clip the weights.
  hv_IndicesToClip = ((*hv_ClassWeights).TupleGreaterElem(hv_MaxWeight)).TupleFind(1);
  if (0 != (int(hv_IndicesToClip!=-1)))
  {
    (*hv_ClassWeights)[hv_IndicesToClip] = hv_MaxWeight;
  }

  return;
}

// Chapter: Deep Learning / Model
// Short Description: Calculate evaluation measures based on the values of RunningMeasures and the settings in EvalParams. 
void calculate_evaluation_measures (HTuple hv_RunningMeasures, HTuple hv_EvalParams, 
    HTuple *hv_EvaluationResult)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_EvaluationType, hv_EvaluationResultTmp;
  HTuple  hv_PixelMeasures, hv_PixelMeasureValues, hv_ResultKeys;
  HTuple  hv_KeyIndex, hv___Tmp_Ctrl_Type;

  //
  //This procedure calculates the final measures depending on the evaluation type.
  //
  GetDictTuple(hv_EvalParams, "evaluation_type", &hv_EvaluationType);
  if (0 != (HTuple(int(hv_EvaluationType==HTuple("anomaly_detection"))).TupleOr(int(hv_EvaluationType==HTuple("gc_anomaly_detection")))))
  {
    calculate_image_anomaly_measures(hv_RunningMeasures, hv_EvalParams, &(*hv_EvaluationResult));
  }
  else if (0 != (int(hv_EvaluationType==HTuple("classification"))))
  {
    calculate_image_classification_measures(hv_RunningMeasures, hv_EvalParams, &(*hv_EvaluationResult));
  }
  else if (0 != (int(hv_EvaluationType==HTuple("multi_label_classification"))))
  {
    calculate_multi_label_classification_measures(hv_RunningMeasures, hv_EvalParams, 
        &(*hv_EvaluationResult));
  }
  else if (0 != (HTuple(int(hv_EvaluationType==HTuple("detection"))).TupleOr(int(hv_EvaluationType==HTuple("ocr_detection")))))
  {
    calculate_instance_measures(hv_RunningMeasures, hv_EvalParams, &(*hv_EvaluationResult));
    if (0 != (int(hv_EvaluationType==HTuple("ocr_detection"))))
    {
      calculate_ocr_detection_measures((*hv_EvaluationResult), &(*hv_EvaluationResult));
    }
  }
  else if (0 != (HTuple(int(hv_EvaluationType==HTuple("segmentation"))).TupleOr(int(hv_EvaluationType==HTuple("3d_gripping_point_detection")))))
  {
    calculate_pixel_measures(hv_RunningMeasures, hv_EvalParams, &(*hv_EvaluationResult));
    if (0 != (int(hv_EvaluationType==HTuple("3d_gripping_point_detection"))))
    {
      calculate_region_measures(hv_RunningMeasures, hv_EvalParams, &hv_EvaluationResultTmp);
      //Only report requested pixel and region measures.
      get_requested_pixel_measures(hv_EvalParams.TupleGetDictTuple("measures"), hv_EvaluationType, 
          &hv_PixelMeasures);
      GetDictTuple((*hv_EvaluationResult), hv_PixelMeasures, &hv_PixelMeasureValues);
      SetDictTuple(hv_EvaluationResultTmp, hv_PixelMeasures, hv_PixelMeasureValues);
      (*hv_EvaluationResult) = hv_EvaluationResultTmp;
      calculate_running_gripping_point_measures(hv_RunningMeasures, hv_EvalParams, 
          &hv_EvaluationResultTmp);
      GetDictParam(hv_EvaluationResultTmp, "keys", HTuple(), &hv_ResultKeys);
      {
      HTuple end_val26 = (hv_ResultKeys.TupleLength())-1;
      HTuple step_val26 = 1;
      for (hv_KeyIndex=0; hv_KeyIndex.Continue(end_val26, step_val26); hv_KeyIndex += step_val26)
      {
        GetDictParam(hv_EvaluationResultTmp, "key_data_type", HTuple(hv_ResultKeys[hv_KeyIndex]), 
            &hv___Tmp_Ctrl_Type);
        if (0 != (int(hv___Tmp_Ctrl_Type==HTuple("object"))))
        {
          SetDictObject(hv_EvaluationResultTmp.TupleGetDictObject(HTuple(hv_ResultKeys[hv_KeyIndex])), 
              (*hv_EvaluationResult), HTuple(hv_ResultKeys[hv_KeyIndex]));
        }
        else
        {
          SetDictTuple((*hv_EvaluationResult), HTuple(hv_ResultKeys[hv_KeyIndex]), 
              hv_EvaluationResultTmp.TupleGetDictTuple(HTuple(hv_ResultKeys[hv_KeyIndex])));
        }
      }
      }
    }
  }
  else if (0 != (int(hv_EvaluationType==HTuple("ocr_recognition"))))
  {
    calculate_ocr_recognition_measures(hv_RunningMeasures, hv_EvalParams, &(*hv_EvaluationResult));
  }
  //
  return;
}

// Chapter: Classification / Misc
// Short Description: Calculate one or more features of a given image and/or region. 
void calculate_features (HObject ho_Region, HObject ho_Image, HTuple hv_FeatureNames, 
    HTuple *hv_Features)
{

  //
  //Calculate features given in FeatureNames
  //for the input regions in Region
  //(if needed supported by the underlying
  //gray-value or color image Image).
  //
  get_features(ho_Region, ho_Image, hv_FeatureNames, "calculate", &(*hv_Features));
  return;
}

// Chapter: Deep Learning / Anomaly Detection and Global Context Anomaly Detection
// Short Description: Calculate anomaly measures based on RunningMeasures. 
void calculate_image_anomaly_measures (HTuple hv_RunningMeasures, HTuple hv_EvalParams, 
    HTuple *hv_EvaluationResult)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_CalcAnomalyHistogram, hv_CalcPrecision;
  HTuple  hv_CalcRecall, hv_CalcAbsoluteConfusionMatrix, hv_CalcRelativeConfusionMatrix;
  HTuple  hv_MeasuresExists, hv_Measures, hv_M, hv_AnomalyClassificationThresholdExists;
  HTuple  hv_AnomalyClassificationThreshold, hv_ImageIDs;
  HTuple  hv_AnomalyLabelIDs, hv_AnomalyScores, hv_OKIndices;
  HTuple  hv_NOKIndices, hv_HistoOKXValues, hv_HistoOKYValues;
  HTuple  hv_NumOKEvalData, hv_ImageLevelScoresOK, hv_HistoNOKXValues;
  HTuple  hv_HistoNOKYValues, hv_NumNOKEvalData, hv_ImageLevelScoresNOK;
  HTuple  hv_ScoreHistogram, hv_NumClasses, hv_ClassIDs, hv_AllPredictions;
  HTuple  hv_IndThreshold, hv_CurrentThresholdValue, hv_CurrentThresholdKey;
  HTuple  hv_Predictions, hv_AbsoluteConfustionMatrices, hv_AbsoluteConfusionMatrix;
  HTuple  hv_Rows, hv_Columns, hv_Value, hv_AbsoluteConfusionMatrixDictionary;
  HTuple  hv_RelativeConfustionMatrices, hv_RelativeConfusionMatrix;
  HTuple  hv_RelativeConfusionMatrixDictionary, hv_GlobalEvaluation;
  HTuple  hv_AllClassPrecisions, hv_AllMeanPrecisions, hv_AbsoluteConfusionMatrices;
  HTuple  hv_ClassPrecisions, hv_MatrixRowSumID, hv_MatrixColumnSumID;
  HTuple  hv_Index, hv_TruePositive, hv_SumPredictedClass;
  HTuple  hv_SumLabel, hv_ClassPrecision, hv_ValidClassPrecisions;
  HTuple  hv_MeanPrecision, hv_AllClassRecalls, hv_AllMeanRecalls;
  HTuple  hv_ClassRecalls, hv_ClassRecall, hv_ValidClassRecalls;
  HTuple  hv_MeanRecall;

  //
  //This procedure calculates the final summarizing image anomaly measures based on the running measures.
  //
  hv_CalcAnomalyHistogram = 1;
  hv_CalcPrecision = 0;
  hv_CalcRecall = 0;
  hv_CalcAbsoluteConfusionMatrix = 0;
  hv_CalcRelativeConfusionMatrix = 0;
  GetDictParam(hv_EvalParams, "key_exists", "measures", &hv_MeasuresExists);
  if (0 != hv_MeasuresExists)
  {
    GetDictTuple(hv_EvalParams, "measures", &hv_Measures);
    {
    HTuple end_val11 = (hv_Measures.TupleLength())-1;
    HTuple step_val11 = 1;
    for (hv_M=0; hv_M.Continue(end_val11, step_val11); hv_M += step_val11)
    {
      if (0 != (int(HTuple(hv_Measures[hv_M])==HTuple("anomaly_score_histogram"))))
      {
        //The default, just here for consistency.
        hv_CalcAnomalyHistogram = 1;
      }
      else if (0 != (int(HTuple(hv_Measures[hv_M])==HTuple("precision"))))
      {
        hv_CalcPrecision = 1;
        hv_CalcAbsoluteConfusionMatrix = 1;
      }
      else if (0 != (int(HTuple(hv_Measures[hv_M])==HTuple("recall"))))
      {
        hv_CalcRecall = 1;
        hv_CalcAbsoluteConfusionMatrix = 1;
      }
      else if (0 != (int(HTuple(hv_Measures[hv_M])==HTuple("absolute_confusion_matrix"))))
      {
        hv_CalcAbsoluteConfusionMatrix = 1;
      }
      else if (0 != (int(HTuple(hv_Measures[hv_M])==HTuple("relative_confusion_matrix"))))
      {
        hv_CalcRelativeConfusionMatrix = 1;
      }
      else if (0 != (int(HTuple(hv_Measures[hv_M])==HTuple("all"))))
      {
        hv_CalcPrecision = 1;
        hv_CalcRecall = 1;
        hv_CalcAbsoluteConfusionMatrix = 1;
        hv_CalcRelativeConfusionMatrix = 1;
      }
      else
      {
        throw HException(("Unknown Measure: "+HTuple(hv_Measures[hv_M]))+".");
      }
    }
    }
  }
  //
  GetDictParam(hv_EvalParams, "key_exists", "anomaly_classification_thresholds", 
      &hv_AnomalyClassificationThresholdExists);
  if (0 != hv_AnomalyClassificationThresholdExists)
  {
    GetDictTuple(hv_EvalParams, "anomaly_classification_thresholds", &hv_AnomalyClassificationThreshold);
  }
  else if (0 != (hv_CalcRelativeConfusionMatrix.TupleOr(hv_CalcAbsoluteConfusionMatrix)))
  {
    throw HException("A threshold value is needed to calculate a confusion matrix.");
  }
  //
  //Get and check values in RunningMeasures.
  //
  //Get image ids.
  GetDictTuple(hv_RunningMeasures, "image_ids", &hv_ImageIDs);
  //Get anomaly ids.
  GetDictTuple(hv_RunningMeasures, "anomaly_label_ids", &hv_AnomalyLabelIDs);
  //Get image scores.
  GetDictTuple(hv_RunningMeasures, "anomaly_scores", &hv_AnomalyScores);
  //
  //Calculate histograms.
  //
  //Find scores of 'ok' and 'nok' images.
  hv_OKIndices = hv_AnomalyLabelIDs.TupleFind(0);
  hv_NOKIndices = hv_AnomalyLabelIDs.TupleFind(1);
  if (0 != (HTuple(int(hv_OKIndices==-1)).TupleAnd(int(hv_NOKIndices==-1))))
  {
    throw HException("No data available for evaluation");
  }
  //
  //Calculate histogram for 'ok' images.
  hv_HistoOKXValues = HTuple();
  hv_HistoOKYValues = HTuple();
  hv_NumOKEvalData = 0;
  if (0 != (int(hv_OKIndices!=-1)))
  {
    hv_NumOKEvalData = hv_OKIndices.TupleLength();
    hv_ImageLevelScoresOK = HTuple(hv_AnomalyScores[hv_OKIndices]);
    hv_HistoOKXValues = hv_ImageLevelScoresOK.TupleSort();
    hv_HistoOKYValues = (HTuple::TupleGenSequence(hv_ImageLevelScoresOK.TupleLength(),1,-1).TupleReal())/(hv_ImageLevelScoresOK.TupleLength());
  }
  //
  //Calculate histogram for 'nok' images.
  hv_HistoNOKXValues = HTuple();
  hv_HistoNOKYValues = HTuple();
  hv_NumNOKEvalData = 0;
  if (0 != (int(hv_NOKIndices!=-1)))
  {
    hv_NumNOKEvalData = hv_NOKIndices.TupleLength();
    hv_ImageLevelScoresNOK = HTuple(hv_AnomalyScores[hv_NOKIndices]);
    hv_HistoNOKXValues = hv_ImageLevelScoresNOK.TupleSort();
    hv_HistoNOKYValues = (HTuple::TupleGenSequence(1,hv_ImageLevelScoresNOK.TupleLength(),1).TupleReal())/(hv_ImageLevelScoresNOK.TupleLength());
  }
  //
  //Create dictionary for the score histogram.
  CreateDict(&hv_ScoreHistogram);
  SetDictTuple(hv_ScoreHistogram, "ok_x", hv_HistoOKXValues);
  SetDictTuple(hv_ScoreHistogram, "ok_y", hv_HistoOKYValues);
  SetDictTuple(hv_ScoreHistogram, "nok_x", hv_HistoNOKXValues);
  SetDictTuple(hv_ScoreHistogram, "nok_y", hv_HistoNOKYValues);
  //
  //Set the score histogram in the results dictionary.
  CreateDict(&(*hv_EvaluationResult));
  SetDictTuple((*hv_EvaluationResult), "anomaly_score_histogram", hv_ScoreHistogram);
  //
  //Get Predictions according to given Threshold value(s).
  //Remember, precision and recall base on the absolute confusion matrix.
  if (0 != (hv_CalcAbsoluteConfusionMatrix.TupleOr(hv_CalcRelativeConfusionMatrix)))
  {
    GetDictTuple(hv_EvalParams, "num_classes", &hv_NumClasses);
    GetDictTuple(hv_EvalParams, "class_ids", &hv_ClassIDs);
    CreateDict(&hv_AllPredictions);
    {
    HTuple end_val100 = (hv_AnomalyClassificationThreshold.TupleLength())-1;
    HTuple step_val100 = 1;
    for (hv_IndThreshold=0; hv_IndThreshold.Continue(end_val100, step_val100); hv_IndThreshold += step_val100)
    {
      hv_CurrentThresholdValue = HTuple(hv_AnomalyClassificationThreshold[hv_IndThreshold]);
      hv_CurrentThresholdKey = hv_IndThreshold.TupleString(".3d");
      hv_Predictions = hv_AnomalyScores.TupleGreaterEqualElem(hv_CurrentThresholdValue);
      SetDictTuple(hv_AllPredictions, hv_CurrentThresholdKey, hv_Predictions);
    }
    }
  }
  //
  //Calculate absolute confusion matrix.
  if (0 != hv_CalcAbsoluteConfusionMatrix)
  {
    hv_AbsoluteConfustionMatrices = HTuple();
    {
    HTuple end_val111 = (hv_AnomalyClassificationThreshold.TupleLength())-1;
    HTuple step_val111 = 1;
    for (hv_IndThreshold=0; hv_IndThreshold.Continue(end_val111, step_val111); hv_IndThreshold += step_val111)
    {
      hv_CurrentThresholdValue = HTuple(hv_AnomalyClassificationThreshold[hv_IndThreshold]);
      hv_CurrentThresholdKey = hv_IndThreshold.TupleString(".3d");
      GetDictTuple(hv_AllPredictions, hv_CurrentThresholdKey, &hv_Predictions);
      gen_confusion_matrix(hv_AnomalyLabelIDs, hv_Predictions, (HTuple("display_matrix").Append("return_matrix")), 
          (HTuple("none").Append("absolute")), HTuple(), &hv_AbsoluteConfusionMatrix);
      GetSizeMatrix(hv_AbsoluteConfusionMatrix, &hv_Rows, &hv_Columns);
      if (0 != (HTuple(HTuple(int(hv_NumOKEvalData<=0)).TupleOr(int(hv_NumNOKEvalData<=0))).TupleAnd(HTuple(int(hv_Rows<2)).TupleOr(int(hv_Columns<2)))))
      {
        //Patch matrix to 2x2 in case only 'ok' or only 'nok'
        //data is used for evaluation.
        GetValueMatrix(hv_AbsoluteConfusionMatrix, 0, 0, &hv_Value);
        CreateMatrix(2, 2, 0, &hv_AbsoluteConfusionMatrix);
        if (0 != (int(hv_NumOKEvalData<=0)))
        {
          SetValueMatrix(hv_AbsoluteConfusionMatrix, 0, 1, (hv_Predictions.TupleLength())-hv_Value);
          SetValueMatrix(hv_AbsoluteConfusionMatrix, 1, 1, hv_Value);
        }
        if (0 != (int(hv_NumNOKEvalData<=0)))
        {
          SetValueMatrix(hv_AbsoluteConfusionMatrix, 0, 0, hv_Value);
          SetValueMatrix(hv_AbsoluteConfusionMatrix, 1, 0, (hv_Predictions.TupleLength())-hv_Value);
        }
      }
      CreateDict(&hv_AbsoluteConfusionMatrixDictionary);
      SetDictTuple(hv_AbsoluteConfusionMatrixDictionary, "confusion_matrix", hv_AbsoluteConfusionMatrix);
      SetDictTuple(hv_AbsoluteConfusionMatrixDictionary, "threshold", hv_CurrentThresholdValue);
      hv_AbsoluteConfustionMatrices[hv_IndThreshold] = hv_AbsoluteConfusionMatrixDictionary;
    }
    }
    SetDictTuple((*hv_EvaluationResult), "absolute_confusion_matrix", hv_AbsoluteConfustionMatrices);
  }
  //
  //Calculate relative confusion matrix.
  if (0 != hv_CalcRelativeConfusionMatrix)
  {
    hv_RelativeConfustionMatrices = HTuple();
    {
    HTuple end_val142 = (hv_AnomalyClassificationThreshold.TupleLength())-1;
    HTuple step_val142 = 1;
    for (hv_IndThreshold=0; hv_IndThreshold.Continue(end_val142, step_val142); hv_IndThreshold += step_val142)
    {
      hv_CurrentThresholdValue = HTuple(hv_AnomalyClassificationThreshold[hv_IndThreshold]);
      hv_CurrentThresholdKey = hv_IndThreshold.TupleString(".3d");
      GetDictTuple(hv_AllPredictions, hv_CurrentThresholdKey, &hv_Predictions);
      gen_confusion_matrix(hv_AnomalyLabelIDs, hv_Predictions, (HTuple("display_matrix").Append("return_matrix")), 
          (HTuple("none").Append("relative")), HTuple(), &hv_RelativeConfusionMatrix);
      GetSizeMatrix(hv_RelativeConfusionMatrix, &hv_Rows, &hv_Columns);
      if (0 != (HTuple(HTuple(int(hv_NumOKEvalData<=0)).TupleOr(int(hv_NumNOKEvalData<=0))).TupleAnd(HTuple(int(hv_Rows<2)).TupleOr(int(hv_Columns<2)))))
      {
        //Patch matrix to 2x2 in case only 'ok' or only 'nok'
        //data is used for evaluation.
        GetValueMatrix(hv_RelativeConfusionMatrix, 0, 0, &hv_Value);
        CreateMatrix(2, 2, 0, &hv_RelativeConfusionMatrix);
        if (0 != (int(hv_NumOKEvalData<=0)))
        {
          SetValueMatrix(hv_RelativeConfusionMatrix, 0, 1, 1.0-hv_Value);
          SetValueMatrix(hv_RelativeConfusionMatrix, 1, 1, hv_Value);
        }
        if (0 != (int(hv_NumNOKEvalData<=0)))
        {
          SetValueMatrix(hv_RelativeConfusionMatrix, 0, 0, hv_Value);
          SetValueMatrix(hv_RelativeConfusionMatrix, 1, 0, 1.0-hv_Value);
        }
      }
      CreateDict(&hv_RelativeConfusionMatrixDictionary);
      SetDictTuple(hv_RelativeConfusionMatrixDictionary, "confusion_matrix", hv_RelativeConfusionMatrix);
      SetDictTuple(hv_RelativeConfusionMatrixDictionary, "threshold", hv_CurrentThresholdValue);
      hv_RelativeConfustionMatrices[hv_IndThreshold] = hv_RelativeConfusionMatrixDictionary;
    }
    }
    SetDictTuple((*hv_EvaluationResult), "relative_confusion_matrix", hv_RelativeConfustionMatrices);
  }
  //
  if (0 != (hv_CalcPrecision.TupleOr(hv_CalcRecall)))
  {
    CreateDict(&hv_GlobalEvaluation);
  }
  //Calculate precision.
  if (0 != hv_CalcPrecision)
  {
    hv_AllClassPrecisions = HTuple();
    hv_AllMeanPrecisions = HTuple();
    GetDictTuple((*hv_EvaluationResult), "absolute_confusion_matrix", &hv_AbsoluteConfusionMatrices);
    {
    HTuple end_val178 = (hv_AbsoluteConfusionMatrices.TupleLength())-1;
    HTuple step_val178 = 1;
    for (hv_IndThreshold=0; hv_IndThreshold.Continue(end_val178, step_val178); hv_IndThreshold += step_val178)
    {
      hv_AbsoluteConfusionMatrixDictionary = HTuple(hv_AbsoluteConfusionMatrices[hv_IndThreshold]);
      GetDictTuple(hv_AbsoluteConfusionMatrixDictionary, "confusion_matrix", &hv_AbsoluteConfusionMatrix);
      hv_ClassPrecisions = HTuple();
      SumMatrix(hv_AbsoluteConfusionMatrix, "rows", &hv_MatrixRowSumID);
      SumMatrix(hv_AbsoluteConfusionMatrix, "columns", &hv_MatrixColumnSumID);
      {
      HTuple end_val184 = hv_NumClasses-1;
      HTuple step_val184 = 1;
      for (hv_Index=0; hv_Index.Continue(end_val184, step_val184); hv_Index += step_val184)
      {
        //Compute the precision for every selected class.
        GetValueMatrix(hv_AbsoluteConfusionMatrix, HTuple(hv_ClassIDs[hv_Index]), 
            HTuple(hv_ClassIDs[hv_Index]), &hv_TruePositive);
        GetValueMatrix(hv_MatrixRowSumID, HTuple(hv_ClassIDs[hv_Index]), 0, &hv_SumPredictedClass);
        GetValueMatrix(hv_MatrixColumnSumID, 0, HTuple(hv_ClassIDs[hv_Index]), &hv_SumLabel);
        if (0 != (int(hv_SumLabel<=0)))
        {
          //Invalid per-class precision.
          hv_ClassPrecision = -1.0;
        }
        else if (0 != (int(hv_SumPredictedClass==0)))
        {
          hv_ClassPrecision = 0.0;
        }
        else
        {
          hv_ClassPrecision = hv_TruePositive/hv_SumPredictedClass;
        }
        hv_ClassPrecisions = hv_ClassPrecisions.TupleConcat(hv_ClassPrecision);
      }
      }
      TupleSelectMask(hv_ClassPrecisions, hv_ClassPrecisions.TupleGreaterEqualElem(0.0), 
          &hv_ValidClassPrecisions);
      hv_MeanPrecision = hv_ValidClassPrecisions.TupleMean();
      hv_AllClassPrecisions = hv_AllClassPrecisions.TupleConcat(hv_ClassPrecisions);
      hv_AllMeanPrecisions = hv_AllMeanPrecisions.TupleConcat(hv_MeanPrecision);
      ClearMatrix(hv_MatrixRowSumID);
    }
    }
    SetDictTuple(hv_GlobalEvaluation, "precision_per_class", hv_AllClassPrecisions);
    SetDictTuple(hv_GlobalEvaluation, "mean_precision", hv_AllMeanPrecisions);
  }
  //
  //Calculate recall.
  if (0 != hv_CalcRecall)
  {
    hv_AllClassRecalls = HTuple();
    hv_AllMeanRecalls = HTuple();
    GetDictTuple((*hv_EvaluationResult), "absolute_confusion_matrix", &hv_AbsoluteConfustionMatrices);
    {
    HTuple end_val214 = (hv_AbsoluteConfustionMatrices.TupleLength())-1;
    HTuple step_val214 = 1;
    for (hv_IndThreshold=0; hv_IndThreshold.Continue(end_val214, step_val214); hv_IndThreshold += step_val214)
    {
      hv_AbsoluteConfusionMatrixDictionary = HTuple(hv_AbsoluteConfustionMatrices[hv_IndThreshold]);
      GetDictTuple(hv_AbsoluteConfusionMatrixDictionary, "confusion_matrix", &hv_AbsoluteConfusionMatrix);
      hv_ClassRecalls = HTuple();
      SumMatrix(hv_AbsoluteConfusionMatrix, "columns", &hv_MatrixColumnSumID);
      {
      HTuple end_val219 = hv_NumClasses-1;
      HTuple step_val219 = 1;
      for (hv_Index=0; hv_Index.Continue(end_val219, step_val219); hv_Index += step_val219)
      {
        //Compute the recall for every selected class.
        GetValueMatrix(hv_AbsoluteConfusionMatrix, HTuple(hv_ClassIDs[hv_Index]), 
            HTuple(hv_ClassIDs[hv_Index]), &hv_TruePositive);
        GetValueMatrix(hv_MatrixColumnSumID, 0, HTuple(hv_ClassIDs[hv_Index]), &hv_SumLabel);
        if (0 != (int(hv_SumLabel==0)))
        {
          //Invalid per-class recall.
          hv_ClassRecall = -1.0;
        }
        else
        {
          hv_ClassRecall = hv_TruePositive/hv_SumLabel;
        }
        hv_ClassRecalls = hv_ClassRecalls.TupleConcat(hv_ClassRecall);
      }
      }
      TupleSelectMask(hv_ClassRecalls, hv_ClassRecalls.TupleGreaterEqualElem(0.0), 
          &hv_ValidClassRecalls);
      hv_MeanRecall = hv_ValidClassRecalls.TupleMean();
      hv_AllClassRecalls = hv_AllClassRecalls.TupleConcat(hv_ClassRecalls);
      hv_AllMeanRecalls = hv_AllMeanRecalls.TupleConcat(hv_MeanRecall);
      ClearMatrix(hv_MatrixColumnSumID);
      //
    }
    }
    SetDictTuple(hv_GlobalEvaluation, "recall_per_class", hv_AllClassRecalls);
    SetDictTuple(hv_GlobalEvaluation, "mean_recall", hv_AllMeanRecalls);
  }
  //
  if (0 != (hv_CalcPrecision.TupleOr(hv_CalcRecall)))
  {
    SetDictTuple((*hv_EvaluationResult), "global_evaluation", hv_GlobalEvaluation);
  }
  //
  return;
}

// Chapter: Deep Learning / Classification
// Short Description: Calculate image classification measures based on RunningMeasures. 
void calculate_image_classification_measures (HTuple hv_RunningMeasures, HTuple hv_EvalParams, 
    HTuple *hv_EvaluationResult)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_TopKErrorKs, hv_CalcPrecision, hv_CalcRecall;
  HTuple  hv_CalcFScore, hv_CalcAbsoluteConfusionMatrix, hv_CalcRelativeConfusionMatrix;
  HTuple  hv_Measures, hv_OODDetectionMeasures, hv_RegExpTopKError;
  HTuple  hv_M, hv_ComputeTopKError, hv_K, hv_ClassIDs, hv_KeyExists;
  HTuple  hv_ClassesToEvaluate, hv_ClassIDsToEvaluate, hv_ClassNames;
  HTuple  hv_Index, hv_Position, hv_ImageIDs, hv_ImageLabelIDs;
  HTuple  hv_Predictions, hv_TopKPredictions, hv_EvalIndex;
  HTuple  hv_CurrentEvalClass, hv_IndexClass, hv_EvaluatedSamples;
  HTuple  hv_ConfusionMatrix, hv_RelativeConfusionMatrix;
  HTuple  hv_EvalClassID, hv_KIndex, hv_Indices, hv_TopKError;
  HTuple  hv_NumClasses, hv_ClassPrecisions, hv_MatrixRowSumID;
  HTuple  hv_TruePositive, hv_SumPredictedClass, hv_ClassPrecision;
  HTuple  hv_Precision, hv_ClassRecalls, hv_MatrixColumnSumID;
  HTuple  hv_SumLabel, hv_ClassRecall, hv_Recall, hv_ClassFScores;
  HTuple  hv_SumPrecisionRecall, hv_PositiveIndices, hv_FScore;
  HTuple  hv_KeyName, hv_CalculateOodMeasuresExists;

  //
  //This procedure calculates the final summarizing image classification measures based on the running measures.
  //
  //Set default values.
  hv_TopKErrorKs = HTuple();
  hv_CalcPrecision = 0;
  hv_CalcRecall = 0;
  hv_CalcFScore = 0;
  hv_CalcAbsoluteConfusionMatrix = 0;
  hv_CalcRelativeConfusionMatrix = 0;
  //
  //Check which measures are to be calculated.
  GetDictTuple(hv_EvalParams, "measures", &hv_Measures);
  hv_OODDetectionMeasures.Clear();
  hv_OODDetectionMeasures[0] = "ood_confusion_matrix";
  hv_OODDetectionMeasures[1] = "ood_precision";
  hv_OODDetectionMeasures[2] = "ood_recall";
  hv_OODDetectionMeasures[3] = "ood_f_score";
  hv_OODDetectionMeasures[4] = "ood_false_positive_rate";
  hv_OODDetectionMeasures[5] = "ood_score_histogram";
  hv_OODDetectionMeasures[6] = "ood_thresholds";
  hv_RegExpTopKError = "top([0-9]+)_error";
  {
  HTuple end_val15 = (hv_Measures.TupleLength())-1;
  HTuple step_val15 = 1;
  for (hv_M=0; hv_M.Continue(end_val15, step_val15); hv_M += step_val15)
  {
    hv_ComputeTopKError = HTuple(hv_Measures[hv_M]).TupleRegexpTest("top([0-9]+)_error");
    if (0 != hv_ComputeTopKError)
    {
      hv_K = (HTuple(hv_Measures[hv_M]).TupleRegexpMatch(hv_RegExpTopKError)).TupleNumber();
      hv_TopKErrorKs = (hv_TopKErrorKs.TupleConcat(hv_K)).TupleSort();
    }
    else if (0 != (int(HTuple(hv_Measures[hv_M])==HTuple("precision"))))
    {
      hv_CalcPrecision = 1;
    }
    else if (0 != (int(HTuple(hv_Measures[hv_M])==HTuple("recall"))))
    {
      hv_CalcRecall = 1;
    }
    else if (0 != (int(HTuple(hv_Measures[hv_M])==HTuple("f_score"))))
    {
      hv_CalcFScore = 1;
    }
    else if (0 != (int(HTuple(hv_Measures[hv_M])==HTuple("absolute_confusion_matrix"))))
    {
      hv_CalcAbsoluteConfusionMatrix = 1;
    }
    else if (0 != (int(HTuple(hv_Measures[hv_M])==HTuple("relative_confusion_matrix"))))
    {
      hv_CalcRelativeConfusionMatrix = 1;
    }
    else if (0 != (int(HTuple(hv_Measures[hv_M])==HTuple("all"))))
    {
      hv_TopKErrorKs = (hv_TopKErrorKs.TupleConcat(1)).TupleSort();
      hv_CalcPrecision = 1;
      hv_CalcRecall = 1;
      hv_CalcFScore = 1;
      hv_CalcAbsoluteConfusionMatrix = 1;
      hv_CalcRelativeConfusionMatrix = 1;
    }
    else if (0 != (int((hv_OODDetectionMeasures.TupleFind(HTuple(hv_Measures[hv_M])))!=-1)))
    {
      //OOD detection measures are computed in a separate procedure.
    }
    else
    {
      throw HException("Unknown image classification measure: "+HTuple(hv_Measures[hv_M]));
    }
  }
  }
  //
  //Initialize output dictionary and get necessary evaluation parameters.
  CreateDict(&(*hv_EvaluationResult));
  GetDictTuple(hv_EvalParams, "class_ids", &hv_ClassIDs);
  GetDictParam(hv_EvalParams, "key_exists", "class_names_to_evaluate", &hv_KeyExists);
  if (0 != hv_KeyExists)
  {
    GetDictTuple(hv_EvalParams, "class_names_to_evaluate", &hv_ClassesToEvaluate);
    hv_ClassIDsToEvaluate = HTuple();
    GetDictTuple(hv_EvalParams, "class_names", &hv_ClassNames);
    {
    HTuple end_val52 = (hv_ClassesToEvaluate.TupleLength())-1;
    HTuple step_val52 = 1;
    for (hv_Index=0; hv_Index.Continue(end_val52, step_val52); hv_Index += step_val52)
    {
      hv_Position = ((HTuple("global").TupleConcat(hv_ClassNames)).TupleEqualElem(HTuple(hv_ClassesToEvaluate[hv_Index]))).TupleFind(1);
      if (0 != (HTuple(int(hv_Position==-1)).TupleOr(int(hv_Position==HTuple()))))
      {
        throw HException("Invalid entry in  'class_names_to_evaluate': "+HTuple((HTuple("global").TupleConcat(hv_ClassesToEvaluate))[hv_Index]));
      }
      hv_ClassIDsToEvaluate = hv_ClassIDsToEvaluate.TupleConcat(HTuple((HTuple("global").TupleConcat(hv_ClassIDs))[hv_Position]));
    }
    }
    SetDictTuple(hv_EvalParams, "class_ids_to_evaluate", hv_ClassIDsToEvaluate);
  }
  GetDictTuple(hv_EvalParams, "class_ids_to_evaluate", &hv_ClassIDsToEvaluate);
  //
  //Get and check values in RunningMeasures.
  GetDictTuple(hv_RunningMeasures, "image_ids", &hv_ImageIDs);
  GetDictTuple(hv_RunningMeasures, "image_label_ids", &hv_ImageLabelIDs);
  GetDictTuple(hv_RunningMeasures, "top1_predictions", &hv_Predictions);
  GetDictTuple(hv_RunningMeasures, "topk_predictions", &hv_TopKPredictions);
  //
  //Check if needed classes appear in image label IDs.
  //For the confusion matrices, all classes need to be represented.
  hv_CalcAbsoluteConfusionMatrix = HTuple(HTuple(hv_CalcPrecision.TupleOr(hv_CalcRecall)).TupleOr(hv_CalcFScore)).TupleOr(hv_CalcAbsoluteConfusionMatrix);
  hv_CalcRelativeConfusionMatrix = HTuple(HTuple(hv_CalcPrecision.TupleOr(hv_CalcRecall)).TupleOr(hv_CalcFScore)).TupleOr(hv_CalcRelativeConfusionMatrix);
  if (0 != (hv_CalcAbsoluteConfusionMatrix.TupleOr(hv_CalcRelativeConfusionMatrix)))
  {
    if (0 != (int(((hv_ImageLabelIDs.TupleSort()).TupleUniq())!=(hv_ClassIDs.TupleSort()))))
    {
      throw HException("Not all classes are represented in the ground truth labels. \nPlease check your data split.");
    }
  }
  //For top-K errors, the evaluated classes need to be represented.
  if (0 != (int(hv_TopKErrorKs!=HTuple())))
  {
    {
    HTuple end_val80 = (hv_ClassIDsToEvaluate.TupleLength())-1;
    HTuple step_val80 = 1;
    for (hv_EvalIndex=0; hv_EvalIndex.Continue(end_val80, step_val80); hv_EvalIndex += step_val80)
    {
      hv_CurrentEvalClass = HTuple(hv_ClassIDsToEvaluate[hv_EvalIndex]);
      if (0 != (int(hv_CurrentEvalClass!=HTuple("global"))))
      {
        hv_IndexClass = hv_ImageLabelIDs.TupleFind(hv_CurrentEvalClass);
        if (0 != (HTuple(int(hv_IndexClass==-1)).TupleOr(int(hv_IndexClass==HTuple()))))
        {
          throw HException(("The evaluated class ID "+hv_CurrentEvalClass)+" is not represented in the ground truth labels.");
        }
      }
    }
    }
  }
  //
  //Set image IDs, image label IDs, and top1-predictions to of evaluated samples EvaluationResult.
  CreateDict(&hv_EvaluatedSamples);
  SetDictTuple(hv_EvaluatedSamples, "image_ids", hv_ImageIDs);
  SetDictTuple(hv_EvaluatedSamples, "image_label_ids", hv_ImageLabelIDs);
  SetDictTuple(hv_EvaluatedSamples, "top1_predictions", hv_Predictions);
  SetDictTuple((*hv_EvaluationResult), "evaluated_samples", hv_EvaluatedSamples);
  //
  //Calculate absolute confusion matrix if needed and set it to EvaluationResult.
  if (0 != hv_CalcAbsoluteConfusionMatrix)
  {
    gen_confusion_matrix(hv_ImageLabelIDs, hv_Predictions, "display_matrix", "none", 
        HTuple(), &hv_ConfusionMatrix);
    SetDictTuple((*hv_EvaluationResult), "absolute_confusion_matrix", hv_ConfusionMatrix);
  }
  //
  //Calculate relative confusion matrix.
  if (0 != hv_CalcRelativeConfusionMatrix)
  {
    gen_confusion_matrix(hv_ImageLabelIDs, hv_Predictions, (HTuple("display_matrix").Append("return_matrix")), 
        (HTuple("none").Append("relative")), HTuple(), &hv_RelativeConfusionMatrix);
    SetDictTuple((*hv_EvaluationResult), "relative_confusion_matrix", hv_RelativeConfusionMatrix);
  }
  //
  // Calculate measures for every class to be evaluated.
  {
  HTuple end_val111 = (hv_ClassIDsToEvaluate.TupleLength())-1;
  HTuple step_val111 = 1;
  for (hv_EvalIndex=0; hv_EvalIndex.Continue(end_val111, step_val111); hv_EvalIndex += step_val111)
  {
    hv_CurrentEvalClass = HTuple(hv_ClassIDsToEvaluate[hv_EvalIndex]);
    CreateDict(&hv_EvalClassID);
    //
    //Calculate top-K errors.
    {
    HTuple end_val116 = (hv_TopKErrorKs.TupleLength())-1;
    HTuple step_val116 = 1;
    for (hv_KIndex=0; hv_KIndex.Continue(end_val116, step_val116); hv_KIndex += step_val116)
    {
      hv_K = HTuple(hv_TopKErrorKs[hv_KIndex]);
      if (0 != (int(hv_CurrentEvalClass==HTuple("global"))))
      {
        hv_Indices = HTuple::TupleGenSequence(0,(hv_ImageLabelIDs.TupleLength())-1,1);
      }
      else
      {
        hv_Indices = hv_ImageLabelIDs.TupleFind(hv_CurrentEvalClass);
      }
      compute_top_k_error_dl_evaluation(HTuple(hv_ImageLabelIDs[hv_Indices]), HTuple(hv_TopKPredictions[hv_Indices]), 
          hv_K, &hv_TopKError);
      SetDictTuple(hv_EvalClassID, ("top"+hv_K)+"_error", hv_TopKError);
    }
    }
    //
    if (0 != (int(hv_CurrentEvalClass==HTuple("global"))))
    {
      //Compute the mean of the measures for all classes.
      hv_NumClasses = hv_ClassIDs.TupleLength();
      hv_IndexClass = hv_ClassIDs;
    }
    else
    {
      //Compute the measures for a certain class.
      hv_NumClasses = 1;
      hv_IndexClass = hv_ClassIDs.TupleFind(hv_CurrentEvalClass);
    }
    //
    //Calculate prediction.
    if (0 != (hv_CalcPrecision.TupleOr(hv_CalcFScore)))
    {
      hv_ClassPrecisions = HTuple();
      SumMatrix(hv_ConfusionMatrix, "rows", &hv_MatrixRowSumID);
      {
      HTuple end_val141 = hv_NumClasses-1;
      HTuple step_val141 = 1;
      for (hv_Index=0; hv_Index.Continue(end_val141, step_val141); hv_Index += step_val141)
      {
        //Compute the precision for every selected class.
        GetValueMatrix(hv_ConfusionMatrix, HTuple(hv_IndexClass[hv_Index]), HTuple(hv_IndexClass[hv_Index]), 
            &hv_TruePositive);
        GetValueMatrix(hv_MatrixRowSumID, HTuple(hv_IndexClass[hv_Index]), 0, &hv_SumPredictedClass);
        if (0 != (int(hv_SumPredictedClass==0)))
        {
          hv_ClassPrecision = 0;
        }
        else
        {
          hv_ClassPrecision = hv_TruePositive/hv_SumPredictedClass;
        }
        hv_ClassPrecisions = hv_ClassPrecisions.TupleConcat(hv_ClassPrecision);
      }
      }
      hv_Precision = hv_ClassPrecisions.TupleMean();
      ClearMatrix(hv_MatrixRowSumID);
      if (0 != (int(hv_NumClasses==1)))
      {
        SetDictTuple(hv_EvalClassID, "precision", hv_Precision);
      }
      else
      {
        SetDictTuple(hv_EvalClassID, "mean_precision", hv_Precision);
        SetDictTuple(hv_EvalClassID, "precision_per_class", hv_ClassPrecisions);
      }
    }
    //
    //Calculate recall.
    if (0 != (hv_CalcRecall.TupleOr(hv_CalcFScore)))
    {
      hv_ClassRecalls = HTuple();
      SumMatrix(hv_ConfusionMatrix, "columns", &hv_MatrixColumnSumID);
      {
      HTuple end_val166 = hv_NumClasses-1;
      HTuple step_val166 = 1;
      for (hv_Index=0; hv_Index.Continue(end_val166, step_val166); hv_Index += step_val166)
      {
        //Compute the recall for every class.
        GetValueMatrix(hv_ConfusionMatrix, HTuple(hv_IndexClass[hv_Index]), HTuple(hv_IndexClass[hv_Index]), 
            &hv_TruePositive);
        GetValueMatrix(hv_MatrixColumnSumID, 0, HTuple(hv_IndexClass[hv_Index]), 
            &hv_SumLabel);
        hv_ClassRecall = hv_TruePositive/hv_SumLabel;
        hv_ClassRecalls = hv_ClassRecalls.TupleConcat(hv_ClassRecall);
      }
      }
      hv_Recall = hv_ClassRecalls.TupleMean();
      ClearMatrix(hv_MatrixColumnSumID);
      if (0 != (int(hv_NumClasses==1)))
      {
        SetDictTuple(hv_EvalClassID, "recall", hv_Recall);
      }
      else
      {
        SetDictTuple(hv_EvalClassID, "mean_recall", hv_Recall);
        SetDictTuple(hv_EvalClassID, "recall_per_class", hv_ClassRecalls);
      }
    }
    //
    //Calculate F-score.
    if (0 != hv_CalcFScore)
    {
      TupleGenConst(hv_ClassPrecisions.TupleLength(), 0.0, &hv_ClassFScores);
      hv_SumPrecisionRecall = hv_ClassPrecisions+hv_ClassRecalls;
      hv_PositiveIndices = (hv_SumPrecisionRecall.TupleNotEqualElem(0.0)).TupleFind(1);
      if (0 != (HTuple(int(hv_PositiveIndices!=-1)).TupleAnd(int(hv_PositiveIndices!=HTuple()))))
      {
        hv_ClassFScores[hv_PositiveIndices] = ((2*HTuple(hv_ClassPrecisions[hv_PositiveIndices]))*HTuple(hv_ClassRecalls[hv_PositiveIndices]))/HTuple(hv_SumPrecisionRecall[hv_PositiveIndices]);
      }
      hv_FScore = hv_ClassFScores.TupleMean();
      if (0 != (int(hv_NumClasses==1)))
      {
        SetDictTuple(hv_EvalClassID, "f_score", hv_FScore);
      }
      else
      {
        SetDictTuple(hv_EvalClassID, "mean_f_score", hv_FScore);
        SetDictTuple(hv_EvalClassID, "f_score_per_class", hv_ClassFScores);
      }
    }
    //
    //Set evaluation results for current class ID.
    hv_KeyName = HTuple(hv_ClassIDsToEvaluate[hv_EvalIndex]);
    if (0 != (int(HTuple(hv_ClassIDsToEvaluate[hv_EvalIndex])!=HTuple("global"))))
    {
      hv_KeyName = "class_id_"+hv_KeyName;
    }
    SetDictTuple((*hv_EvaluationResult), hv_KeyName, hv_EvalClassID);
  }
  }
  //
  GetDictParam(hv_EvalParams, "key_exists", "calculate_ood_measures", &hv_CalculateOodMeasuresExists);
  if (0 != hv_CalculateOodMeasuresExists)
  {
    if (0 != (hv_EvalParams.TupleGetDictTuple("calculate_ood_measures")))
    {
      calculate_ood_detection_measures(hv_RunningMeasures, hv_EvalParams, (*hv_EvaluationResult));
    }
  }
  //
  return;
}

// Chapter: Deep Learning / Object Detection and Instance Segmentation
// Short Description: Calculate instance measures based on RunningMeasures. 
void calculate_instance_measures (HTuple hv_RunningMeasures, HTuple hv_EvalParams, 
    HTuple *hv_EvaluationResult)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_CalcClassAP, hv_CalcMeanAP, hv_CalcSoAP;
  HTuple  hv_EvalType, hv_InstanceType, hv_Measures, hv_M;
  HTuple  hv_ClassIDs, hv_NumClasses, hv_MaxNumDetections;
  HTuple  hv_AreaRanges, hv_IoUThresholds, hv_DetailedEvaluation;
  HTuple  hv_InterpolatePRCurves, hv_KeyExists, hv_AreaNames;
  HTuple  hv_MinAreas, hv_MaxAreas, hv_RecThreshs, hv_MDIdx;
  HTuple  hv_MaxNum, hv_MaxNumStr, hv_CurrentRunningMeasures;
  HTuple  hv_PerMaxNumEvaluationResult, hv_AreaIdx, hv_MinArea;
  HTuple  hv_MaxArea, hv_AreaName, hv_AreaRunningMeasures;
  HTuple  hv_PerClassNumGt, hv_PerClassNumPred, hv_PerClassConfidence;
  HTuple  hv_PerClassNumGtIgnore, hv_CurrentEvaluationResult;
  HTuple  hv_ITIdx, hv_PerIoUAP, hv_PerIoUSoAP, hv_PerIoUDetailedEvaluation;
  HTuple  hv_ClsIdx, hv_PerClassDetailedEvaluation, hv_DetectionConfusionMatrix;
  HTuple  hv_PerIoUMeasure, hv_NumImgIDsWithFN, hv_NumImgIDsWithFP;
  HTuple  hv_ImgIDsWithFN, hv_ImgIDsWithFP, hv_ClassMAPDict;
  HTuple  hv_ClassMSoAPDict, hv_ClassesWithGt, hv_PerClassMAP;
  HTuple  hv_PerIoUMAP, hv_PerClassMSoAP, hv_PerIoUMSoAP;
  HTuple  hv_PerIoUNumClassesWithTP, hv_PerIoUTP, hv_PerIoUFN;
  HTuple  hv_PerIoUFP, hv_PerIoUFPClass, hv_PerIoUFPBackground;
  HTuple  hv_PerIoUFPLocalization, hv_PerIoUFPDuplicate, hv_PerIoUFPMultiple;
  HTuple  hv_PerIoUSoAPClass, hv_PerIoUSoAPLocalization, hv_PerIoUSoAPDuplicate;
  HTuple  hv_PerIoUSoAPMultiple, hv_PerIoUNumClassesWithFPClass;
  HTuple  hv_PerIoUNumClassesWithFPLocalization, hv_PerIoUNumClassesWithFPDuplicate;
  HTuple  hv_PerIoUNumClassesWithFPMultiple, hv_ClassAPPerIoU;
  HTuple  hv_ClassSoAPPerIoU, hv_NumGt, hv_NumGtIgnore, hv_NumPred;
  HTuple  hv_Confidences, hv_SortIdxs, hv_CurrentClassMeasures;
  HTuple  hv_IsTP, hv_Ignore, hv_NoIgnoreIdxs, hv_IsFP, hv_AccumulatedIsTP;
  HTuple  hv_AccumulatedIsFP, hv_Recall, hv_Precision, hv_InterpolatedPrecision;
  HTuple  hv_PIdx, hv_PrecisionAtRecThreshs, hv_RTIdx, hv_RecQuantile;
  HTuple  hv_AOD, hv_IdxsTP, hv_IsFPClass, hv_IsFPBackground;
  HTuple  hv_IsFPLocalization, hv_IsFPDuplicate, hv_IsFPMultiple;
  HTuple  hv_NumTP, hv_NumFP, hv_NumFN, hv_NumFPClass, hv_NumFPBackground;
  HTuple  hv_NumFPLocalization, hv_NumFPDuplicate, hv_NumFPMultiple;
  HTuple  hv_IndicesWithClassConfusion, hv_IsFPClassIdxs;
  HTuple  hv_ClassIdxsConfused, hv_Idx, hv_NumConfusedThisIdx;
  HTuple  hv_AODClass, hv_IdxsClass, hv_ResSoAPClass, hv_AODLocalization;
  HTuple  hv_IdxsLocalization, hv_ResSoAPLocalization, hv_AODDuplicate;
  HTuple  hv_IdxsDuplicate, hv_ResSoAPDuplicate, hv_AODMultiple;
  HTuple  hv_IdxsMultiple, hv_ResSoAPMultiple, hv_SoAPIoUIdxsPositive;
  HTuple  hv_MeanClassAP, hv_MeanClassSoAP, hv_MAP, hv_MSoAP;
  HTuple  hv_IoUsWithTP, hv_MSoAPAll, hv_NumSoAPAll, hv_IoUsWithFPClass;
  HTuple  hv_IoUsWithFPLocalization, hv_IoUsWithFPDuplicate;
  HTuple  hv_IoUsWithFPMultiple;

  //
  //This procedure calculates the final summarizing instance measures based on the running measures.
  //
  //Set default values.
  hv_CalcClassAP = 0;
  hv_CalcMeanAP = 0;
  hv_CalcSoAP = 0;
  //Check which measures are to be calculated.
  GetDictTuple(hv_EvalParams, "evaluation_type", &hv_EvalType);
  GetDictTuple(hv_EvalParams, "instance_type", &hv_InstanceType);
  GetDictTuple(hv_EvalParams, "measures", &hv_Measures);
  {
  HTuple end_val11 = (hv_Measures.TupleLength())-1;
  HTuple step_val11 = 1;
  for (hv_M=0; hv_M.Continue(end_val11, step_val11); hv_M += step_val11)
  {
    if (0 != (int(HTuple(hv_Measures[hv_M])==HTuple("mean_ap"))))
    {
      hv_CalcMeanAP = 1;
      //As we need to calculate the class APs anyway, we also write them out.
      hv_CalcClassAP = 1;
    }
    else if (0 != (HTuple(int(HTuple(hv_Measures[hv_M])==HTuple("soap"))).TupleAnd(int(hv_InstanceType==HTuple("rectangle2")))))
    {
      hv_CalcSoAP = 1;
    }
    else if (0 != (int(HTuple(hv_Measures[hv_M])==HTuple("all"))))
    {
      hv_CalcClassAP = 1;
      hv_CalcMeanAP = 1;
      if (0 != (int(hv_InstanceType==HTuple("rectangle2"))))
      {
        hv_CalcSoAP = 1;
      }
    }
    else
    {
      if (0 != (HTuple(int(hv_EvalType==HTuple("ocr_detection"))).TupleAnd(HTuple(HTuple(int(HTuple(hv_Measures[hv_M])==HTuple("recall"))).TupleOr(int(HTuple(hv_Measures[hv_M])==HTuple("precision")))).TupleOr(int(HTuple(hv_Measures[hv_M])==HTuple("f_score"))))))
      {
        hv_CalcMeanAP = 1;
        hv_CalcClassAP = 1;
        continue;
      }
      else
      {
        throw HException("Unknown Instance Measure: "+HTuple(hv_Measures[hv_M]));
      }
    }
  }
  }
  //*
  //Dependencies of measures:
  //
  //Recall (per-class)       *                   --> AP per class --> mAP
  //Precision (per-class)  /
  //
  //*
  //Initialize output dictionary and get necessary evaluation parameters.
  CreateDict(&(*hv_EvaluationResult));
  GetDictTuple(hv_EvalParams, "class_ids", &hv_ClassIDs);
  GetDictTuple(hv_EvalParams, "num_classes", &hv_NumClasses);
  GetDictTuple(hv_EvalParams, "max_num_detections", &hv_MaxNumDetections);
  GetDictTuple(hv_EvalParams, "area_ranges", &hv_AreaRanges);
  GetDictTuple(hv_EvalParams, "iou_threshold", &hv_IoUThresholds);
  //Check if a detailed evaluation should be done and if PR-curves should be interpolated.
  hv_DetailedEvaluation = 0;
  hv_InterpolatePRCurves = 0;
  GetDictParam(hv_EvalParams, "key_exists", (HTuple("detailed_evaluation").Append("interpolate_pr_curves")), 
      &hv_KeyExists);
  if (0 != (HTuple(hv_KeyExists[0])))
  {
    GetDictTuple(hv_EvalParams, "detailed_evaluation", &hv_DetailedEvaluation);
  }
  if (0 != (HTuple(hv_KeyExists[1])))
  {
    GetDictTuple(hv_EvalParams, "interpolate_pr_curves", &hv_InterpolatePRCurves);
  }
  //
  //Get information about area ranges.
  GetDictTuple(hv_AreaRanges, "name", &hv_AreaNames);
  GetDictTuple(hv_AreaRanges, "min", &hv_MinAreas);
  GetDictTuple(hv_AreaRanges, "max", &hv_MaxAreas);
  //
  //Equidistant thresholds used to approximate the area under the Precision-Recall curve.
  hv_RecThreshs = HTuple::TupleGenSequence(0.0,1.0,0.01);
  //Start with calculation.
  if (0 != (HTuple(hv_CalcClassAP.TupleOr(hv_CalcMeanAP)).TupleOr(hv_CalcSoAP)))
  {
    //Loop over maximal number of detections.
    {
    HTuple end_val69 = (hv_MaxNumDetections.TupleLength())-1;
    HTuple step_val69 = 1;
    for (hv_MDIdx=0; hv_MDIdx.Continue(end_val69, step_val69); hv_MDIdx += step_val69)
    {
      //
      //Get corresponding running measures.
      hv_MaxNum = HTuple(hv_MaxNumDetections[hv_MDIdx]);
      hv_MaxNumStr = ""+hv_MaxNum;
      if (0 != (int(hv_MaxNum==-1)))
      {
        hv_MaxNumStr = "all";
      }
      GetDictTuple(hv_RunningMeasures, "max_num_detections_"+hv_MaxNumStr, &hv_CurrentRunningMeasures);
      //
      //Initialize output dictionary.
      CreateDict(&hv_PerMaxNumEvaluationResult);
      //
      //Loop over area ranges.
      {
      HTuple end_val83 = (hv_AreaNames.TupleLength())-1;
      HTuple step_val83 = 1;
      for (hv_AreaIdx=0; hv_AreaIdx.Continue(end_val83, step_val83); hv_AreaIdx += step_val83)
      {
        //Get area thresholds.
        hv_MinArea = HTuple(hv_MinAreas[hv_AreaIdx]);
        hv_MaxArea = HTuple(hv_MaxAreas[hv_AreaIdx]);
        hv_AreaName = HTuple(hv_AreaNames[hv_AreaIdx]);
        //
        GetDictTuple(hv_CurrentRunningMeasures, "area_"+hv_AreaName, &hv_AreaRunningMeasures);
        //
        GetDictTuple(hv_AreaRunningMeasures, "num_gt", &hv_PerClassNumGt);
        GetDictTuple(hv_AreaRunningMeasures, "num_pred", &hv_PerClassNumPred);
        GetDictTuple(hv_AreaRunningMeasures, "confidence", &hv_PerClassConfidence);
        GetDictTuple(hv_AreaRunningMeasures, "num_gt_ignore", &hv_PerClassNumGtIgnore);
        //
        //Initialize output dictionary.
        CreateDict(&hv_CurrentEvaluationResult);
        {
        HTuple end_val98 = (hv_IoUThresholds.TupleLength())-1;
        HTuple step_val98 = 1;
        for (hv_ITIdx=0; hv_ITIdx.Continue(end_val98, step_val98); hv_ITIdx += step_val98)
        {
          CreateDict(&hv_PerIoUAP);
          SetDictTuple(hv_CurrentEvaluationResult, "ap_iou_"+((""+HTuple(hv_IoUThresholds[hv_ITIdx])).TupleRegexpReplace("\\.","")), 
              hv_PerIoUAP);
          if (0 != hv_CalcSoAP)
          {
            CreateDict(&hv_PerIoUSoAP);
            SetDictTuple(hv_CurrentEvaluationResult, "soap_tp_iou_"+((""+HTuple(hv_IoUThresholds[hv_ITIdx])).TupleRegexpReplace("\\.","")), 
                hv_PerIoUSoAP);
          }
          if (0 != hv_DetailedEvaluation)
          {
            //Initialize detailed measures.
            CreateDict(&hv_PerIoUDetailedEvaluation);
            {
            HTuple end_val108 = hv_NumClasses-1;
            HTuple step_val108 = 1;
            for (hv_ClsIdx=0; hv_ClsIdx.Continue(end_val108, step_val108); hv_ClsIdx += step_val108)
            {
              CreateDict(&hv_PerClassDetailedEvaluation);
              //Initialize with zeros in case there is no ground truth for this class.
              SetDictTuple(hv_PerClassDetailedEvaluation, "num_tp", 0);
              SetDictTuple(hv_PerClassDetailedEvaluation, "num_fn", 0);
              SetDictTuple(hv_PerClassDetailedEvaluation, "num_fp", 0);
              SetDictTuple(hv_PerClassDetailedEvaluation, "num_fp_class", 0);
              SetDictTuple(hv_PerClassDetailedEvaluation, "num_fp_background", 0);
              SetDictTuple(hv_PerClassDetailedEvaluation, "num_fp_duplicate", 0);
              SetDictTuple(hv_PerClassDetailedEvaluation, "num_fp_localization", 
                  0);
              SetDictTuple(hv_PerClassDetailedEvaluation, "num_fp_multiple", 0);
              if (0 != hv_CalcSoAP)
              {
                SetDictTuple(hv_PerClassDetailedEvaluation, "soap_fp_class", -1);
                SetDictTuple(hv_PerClassDetailedEvaluation, "soap_fp_duplicate", 
                    -1);
                SetDictTuple(hv_PerClassDetailedEvaluation, "soap_fp_localization", 
                    -1);
                SetDictTuple(hv_PerClassDetailedEvaluation, "soap_fp_multiple", -1);
              }
              SetDictTuple(hv_PerIoUDetailedEvaluation, "class_"+HTuple(hv_ClassIDs[hv_ClsIdx]), 
                  hv_PerClassDetailedEvaluation);
            }
            }
            CreateMatrix(hv_NumClasses+1, hv_NumClasses+4, 0, &hv_DetectionConfusionMatrix);
            SetDictTuple(hv_PerIoUDetailedEvaluation, "detection_confusion_matrix", 
                hv_DetectionConfusionMatrix);
            //
            //Get and set image IDs with false negatives and false positives.
            GetDictTuple(hv_AreaRunningMeasures, "iou_"+((""+HTuple(hv_IoUThresholds[hv_ITIdx])).TupleRegexpReplace("\\.","")), 
                &hv_PerIoUMeasure);
            //Get image IDs with false negatives and false positives, respectively.
            GetDictTuple(hv_PerIoUMeasure, "num_image_ids_with_false_negatives", 
                &hv_NumImgIDsWithFN);
            GetDictTuple(hv_PerIoUMeasure, "num_image_ids_with_false_positives", 
                &hv_NumImgIDsWithFP);
            GetDictTuple(hv_PerIoUMeasure, "image_ids_with_false_negatives", &hv_ImgIDsWithFN);
            GetDictTuple(hv_PerIoUMeasure, "image_ids_with_false_positives", &hv_ImgIDsWithFP);
            //Set in current output.
            SetDictTuple(hv_PerIoUDetailedEvaluation, "image_ids_with_false_negatives", 
                hv_ImgIDsWithFN.TupleSelectRange(0,hv_NumImgIDsWithFN-1));
            SetDictTuple(hv_PerIoUDetailedEvaluation, "image_ids_with_false_positives", 
                hv_ImgIDsWithFP.TupleSelectRange(0,hv_NumImgIDsWithFP-1));
            //
            //Set output for this IoU.
            SetDictTuple(hv_CurrentEvaluationResult, "detailed_evaluation_iou_"+((""+HTuple(hv_IoUThresholds[hv_ITIdx])).TupleRegexpReplace("\\.","")), 
                hv_PerIoUDetailedEvaluation);
          }
        }
        }
        CreateDict(&hv_ClassMAPDict);
        SetDictTuple(hv_CurrentEvaluationResult, "mean_iou_ap", hv_ClassMAPDict);
        if (0 != hv_CalcSoAP)
        {
          CreateDict(&hv_ClassMSoAPDict);
          SetDictTuple(hv_CurrentEvaluationResult, "mean_iou_soap_tp", hv_ClassMSoAPDict);
        }
        //
        //Check which classes have ground truth annotations.
        hv_ClassesWithGt = ((hv_PerClassNumGt-hv_PerClassNumGtIgnore).TupleGreaterElem(0)).TupleFind(1);
        if (0 != (int(hv_ClassesWithGt==-1)))
        {
          hv_ClassesWithGt = HTuple();
        }
        //
        //Initialize PerClassMAP, i.e. mean average precision over IoU-thresholds per class.
        hv_PerClassMAP = HTuple(hv_NumClasses,-1.0);
        //
        //Initialize PerIoUMAP, i.e. mean average precision over classes per IoU-threshold.
        hv_PerIoUMAP = HTuple(hv_IoUThresholds.TupleLength(),0.0);
        //
        if (0 != hv_CalcSoAP)
        {
          //Initialize PerClassMSoAP, i.e. mean SoAP over IoU-thresholds per class.
          hv_PerClassMSoAP = HTuple(hv_NumClasses,-1.0);
          //Initialize PerIoUMSoAP, i.e. mean SoAP over classes per IoU-threshold.
          hv_PerIoUMSoAP = HTuple(hv_IoUThresholds.TupleLength(),0.0);
          //Initialize PerIoUNumClassesWithTP to store the class-indices where true positives occurred.
          hv_PerIoUNumClassesWithTP = HTuple(hv_IoUThresholds.TupleLength(),0);
        }
        //
        if (0 != hv_DetailedEvaluation)
        {
          //Initialize overall num_fn, num_tp, ...
          hv_PerIoUTP = HTuple(hv_IoUThresholds.TupleLength(),0);
          hv_PerIoUFN = HTuple(hv_IoUThresholds.TupleLength(),0);
          hv_PerIoUFP = HTuple(hv_IoUThresholds.TupleLength(),0);
          hv_PerIoUFPClass = HTuple(hv_IoUThresholds.TupleLength(),0);
          hv_PerIoUFPBackground = HTuple(hv_IoUThresholds.TupleLength(),0);
          hv_PerIoUFPLocalization = HTuple(hv_IoUThresholds.TupleLength(),0);
          hv_PerIoUFPDuplicate = HTuple(hv_IoUThresholds.TupleLength(),0);
          hv_PerIoUFPMultiple = HTuple(hv_IoUThresholds.TupleLength(),0);
          if (0 != hv_CalcSoAP)
          {
            hv_PerIoUSoAPClass = HTuple(hv_IoUThresholds.TupleLength(),-1);
            hv_PerIoUSoAPLocalization = HTuple(hv_IoUThresholds.TupleLength(),-1);
            hv_PerIoUSoAPDuplicate = HTuple(hv_IoUThresholds.TupleLength(),-1);
            hv_PerIoUSoAPMultiple = HTuple(hv_IoUThresholds.TupleLength(),-1);
            hv_PerIoUNumClassesWithFPClass = HTuple(hv_IoUThresholds.TupleLength(),0);
            hv_PerIoUNumClassesWithFPLocalization = HTuple(hv_IoUThresholds.TupleLength(),0);
            hv_PerIoUNumClassesWithFPDuplicate = HTuple(hv_IoUThresholds.TupleLength(),0);
            hv_PerIoUNumClassesWithFPMultiple = HTuple(hv_IoUThresholds.TupleLength(),0);
          }
        }
        //Loop over all classes.
        {
        HTuple end_val195 = hv_NumClasses-1;
        HTuple step_val195 = 1;
        for (hv_ClsIdx=0; hv_ClsIdx.Continue(end_val195, step_val195); hv_ClsIdx += step_val195)
        {
          //
          //Initialize per-class AP per IoU-threshold (only for one class).
          hv_ClassAPPerIoU = HTuple(hv_IoUThresholds.TupleLength(),-1.0);
          //
          if (0 != hv_CalcSoAP)
          {
            hv_ClassSoAPPerIoU = HTuple(hv_IoUThresholds.TupleLength(),-1.0);
          }
          //Get results for this class.
          hv_NumGt = HTuple(hv_PerClassNumGt[hv_ClsIdx]);
          hv_NumGtIgnore = HTuple(hv_PerClassNumGtIgnore[hv_ClsIdx]);
          if (0 != (int((hv_NumGt-hv_NumGtIgnore)>0)))
          {
            hv_NumPred = HTuple(hv_PerClassNumPred[hv_ClsIdx]);
            GetDictTuple(hv_PerClassConfidence, "class_"+HTuple(hv_ClassIDs[hv_ClsIdx]), 
                &hv_Confidences);
            //
            //Sort the confidences in descending order and
            //only take the first NumPred ones due to block allocation.
            hv_SortIdxs = (-(hv_Confidences.TupleSelectRange(0,hv_NumPred-1))).TupleSortIndex();
            hv_Confidences = HTuple(hv_Confidences[hv_SortIdxs]);
          }
          //
          //Loop over IoU thresholds.
          {
          HTuple end_val217 = (hv_IoUThresholds.TupleLength())-1;
          HTuple step_val217 = 1;
          for (hv_ITIdx=0; hv_ITIdx.Continue(end_val217, step_val217); hv_ITIdx += step_val217)
          {
            //
            //Check if there are ground truth labels for this class.
            if (0 != (int((hv_NumGt-hv_NumGtIgnore)>0)))
            {
              //
              //Get results for this class and IoU-threshold.
              GetDictTuple(hv_AreaRunningMeasures, "iou_"+((""+HTuple(hv_IoUThresholds[hv_ITIdx])).TupleRegexpReplace("\\.","")), 
                  &hv_PerIoUMeasure);
              GetDictTuple(hv_PerIoUMeasure, "class_"+HTuple(hv_ClassIDs[hv_ClsIdx]), 
                  &hv_CurrentClassMeasures);
              GetDictTuple(hv_CurrentClassMeasures, "is_tp", &hv_IsTP);
              GetDictTuple(hv_CurrentClassMeasures, "ignore", &hv_Ignore);
              //
              //Sort the arrays IsTP and Ignore according to the confidence values.
              hv_IsTP = HTuple(hv_IsTP[hv_SortIdxs]);
              hv_Ignore = HTuple(hv_Ignore[hv_SortIdxs]);
              //
              //Sort out the ignored results.
              if (0 != (int((hv_IsTP.TupleLength())>0)))
              {
                hv_NoIgnoreIdxs = hv_Ignore.TupleFind(0);
                if (0 != (int(hv_NoIgnoreIdxs!=-1)))
                {
                  hv_IsTP = HTuple(hv_IsTP[hv_NoIgnoreIdxs]);
                  hv_IsFP = hv_IsTP.TupleNot();
                }
                else
                {
                  hv_IsTP = HTuple();
                  hv_IsFP = HTuple();
                }
              }
              else
              {
                hv_IsFP = HTuple();
              }
              //
              //Accumulate IsTP and IsFP.
              hv_AccumulatedIsTP = hv_IsTP.TupleCumul();
              hv_AccumulatedIsFP = hv_IsFP.TupleCumul();
              //
              //Compute recall.
              //The recall is computed with respect to all ground truth instances,
              //independent of MaxNum.
              hv_Recall = (hv_AccumulatedIsTP.TupleReal())/(hv_NumGt-hv_NumGtIgnore);
              //
              //Compute precision.
              hv_Precision = (hv_AccumulatedIsTP.TupleReal())/(hv_AccumulatedIsTP+hv_AccumulatedIsFP);
              //
              //(Optionally) smooth precision-recall curve.
              hv_InterpolatedPrecision = hv_Precision;
              if (0 != hv_InterpolatePRCurves)
              {
                for (hv_PIdx=hv_NumPred-2; hv_PIdx>=0; hv_PIdx+=-1)
                {
                  hv_InterpolatedPrecision[hv_PIdx] = HTuple(hv_InterpolatedPrecision[hv_PIdx]).TupleMax2(HTuple(hv_InterpolatedPrecision[hv_PIdx+1]));
                }
              }
              //Compute approximated area under the Precision-Recall curve using Recall-Thresholds.
              hv_PrecisionAtRecThreshs = HTuple(hv_RecThreshs.TupleLength(),0.);
              {
              HTuple end_val267 = (hv_RecThreshs.TupleLength())-1;
              HTuple step_val267 = 1;
              for (hv_RTIdx=0; hv_RTIdx.Continue(end_val267, step_val267); hv_RTIdx += step_val267)
              {
                hv_RecQuantile = (hv_Recall.TupleGreaterEqualElem(HTuple(hv_RecThreshs[hv_RTIdx]))).TupleFindFirst(1);
                if (0 != (int(hv_RecQuantile>-1)))
                {
                  hv_PrecisionAtRecThreshs[hv_RTIdx] = HTuple(hv_InterpolatedPrecision[hv_RecQuantile]);
                }
              }
              }
              //
              //Calculate AP as mean of precision at equidistant recall values.
              hv_ClassAPPerIoU[hv_ITIdx] = hv_PrecisionAtRecThreshs.TupleMean();
              //
              //Accumulate AP over classes.
              hv_PerIoUMAP[hv_ITIdx] = HTuple(hv_PerIoUMAP[hv_ITIdx])+HTuple(hv_ClassAPPerIoU[hv_ITIdx]);
              //
              if (0 != hv_CalcSoAP)
              {
                //Calculate SoAP out of the mean over absolute orientation differences.
                GetDictTuple(hv_CurrentClassMeasures, "abs_orientation_diff", &hv_AOD);
                hv_IdxsTP = hv_IsTP.TupleFind(1);
                if (0 != (HTuple(int((hv_IdxsTP.TupleLength())>0)).TupleAnd(int(hv_IdxsTP!=-1))))
                {
                  hv_ClassSoAPPerIoU[hv_ITIdx] = 1.0-((HTuple(hv_AOD[HTuple(hv_SortIdxs[HTuple(hv_NoIgnoreIdxs[hv_IdxsTP])])]).TupleMean())/(HTuple(180).TupleRad()));
                  //Accumulate SoAP over classes.
                  hv_PerIoUMSoAP[hv_ITIdx] = HTuple(hv_PerIoUMSoAP[hv_ITIdx])+HTuple(hv_ClassSoAPPerIoU[hv_ITIdx]);
                }
                //Update PerIoUNumClassesWithTP.
                if (0 != (int((hv_AccumulatedIsTP.TupleLength())>0)))
                {
                  hv_PerIoUNumClassesWithTP[hv_ITIdx] = HTuple(hv_PerIoUNumClassesWithTP[hv_ITIdx])+(HTuple(hv_AccumulatedIsTP[(hv_AccumulatedIsTP.TupleLength())-1]).TupleGreaterElem(0));
                }
              }
              //
              if (0 != hv_DetailedEvaluation)
              {
                //Summarize detailed evaluation running measures, set matrix-values and update overall detailed measures.
                //
                //Get the necessary running measures.
                GetDictTuple(hv_CurrentClassMeasures, "is_fp_class", &hv_IsFPClass);
                GetDictTuple(hv_CurrentClassMeasures, "is_fp_background", &hv_IsFPBackground);
                GetDictTuple(hv_CurrentClassMeasures, "is_fp_localization", &hv_IsFPLocalization);
                GetDictTuple(hv_CurrentClassMeasures, "is_fp_duplicate", &hv_IsFPDuplicate);
                GetDictTuple(hv_CurrentClassMeasures, "is_fp_multiple", &hv_IsFPMultiple);
                //
                //We use the values with maximal recall,
                //in case a higher precision is desired, increase 'min_confidence'.
                if (0 != (int((hv_AccumulatedIsTP.TupleLength())>0)))
                {
                  hv_NumTP = ((const HTuple&)hv_AccumulatedIsTP)[(hv_AccumulatedIsTP.TupleLength())-1];
                }
                else
                {
                  hv_NumTP = 0;
                }
                if (0 != (int((hv_AccumulatedIsFP.TupleLength())>0)))
                {
                  hv_NumFP = ((const HTuple&)hv_AccumulatedIsFP)[(hv_AccumulatedIsFP.TupleLength())-1];
                }
                else
                {
                  hv_NumFP = 0;
                }
                hv_NumFN = (hv_NumGt-hv_NumGtIgnore)-hv_NumTP;
                hv_NumFPClass = (HTuple(hv_IsFPClass[hv_SortIdxs]).TupleGreaterElem(-1)).TupleSum();
                hv_NumFPBackground = (HTuple(hv_IsFPBackground[hv_SortIdxs]).TupleGreaterElem(0)).TupleSum();
                hv_NumFPLocalization = (HTuple(hv_IsFPLocalization[hv_SortIdxs]).TupleGreaterElem(0)).TupleSum();
                hv_NumFPDuplicate = (HTuple(hv_IsFPDuplicate[hv_SortIdxs]).TupleGreaterElem(0)).TupleSum();
                hv_NumFPMultiple = (HTuple(hv_IsFPMultiple[hv_SortIdxs]).TupleGreaterElem(0)).TupleSum();
                if (0 != (int((hv_SortIdxs.TupleLength())==0)))
                {
                  hv_NumFPClass = 0;
                  hv_NumFPBackground = 0;
                  hv_NumFPLocalization = 0;
                  hv_NumFPDuplicate = 0;
                  hv_NumFPMultiple = 0;
                }
                //Consistency checks.
                if (0 != (int(((((((((hv_NumTP.TupleConcat(hv_NumFN)).TupleConcat(hv_NumFP)).TupleConcat(hv_NumFPClass)).TupleConcat(hv_NumFPBackground)).TupleConcat(hv_NumFPLocalization)).TupleConcat(hv_NumFPDuplicate)).TupleConcat(hv_NumFPMultiple)).TupleMin())<0)))
                {
                  throw HException("Fatal error while calculating instance measures.");
                }
                if (0 != (int(hv_NumFP!=((((hv_NumFPClass+hv_NumFPBackground)+hv_NumFPLocalization)+hv_NumFPDuplicate)+hv_NumFPMultiple))))
                {
                  throw HException("Fatal error while calculating instance measures.");
                }
                //
                //Set per-class measures.
                GetDictTuple(hv_CurrentEvaluationResult, "detailed_evaluation_iou_"+((""+HTuple(hv_IoUThresholds[hv_ITIdx])).TupleRegexpReplace("\\.","")), 
                    &hv_PerIoUDetailedEvaluation);
                GetDictTuple(hv_PerIoUDetailedEvaluation, "class_"+HTuple(hv_ClassIDs[hv_ClsIdx]), 
                    &hv_PerClassDetailedEvaluation);
                SetDictTuple(hv_PerClassDetailedEvaluation, "num_tp", hv_NumTP);
                SetDictTuple(hv_PerClassDetailedEvaluation, "num_fn", hv_NumFN);
                SetDictTuple(hv_PerClassDetailedEvaluation, "num_fp", hv_NumFP);
                SetDictTuple(hv_PerClassDetailedEvaluation, "num_fp_class", hv_NumFPClass);
                SetDictTuple(hv_PerClassDetailedEvaluation, "num_fp_background", 
                    hv_NumFPBackground);
                SetDictTuple(hv_PerClassDetailedEvaluation, "num_fp_duplicate", hv_NumFPDuplicate);
                SetDictTuple(hv_PerClassDetailedEvaluation, "num_fp_localization", 
                    hv_NumFPLocalization);
                SetDictTuple(hv_PerClassDetailedEvaluation, "num_fp_multiple", hv_NumFPMultiple);
                //
                //Set detection confusion matrix values.
                GetDictTuple(hv_PerIoUDetailedEvaluation, "detection_confusion_matrix", 
                    &hv_DetectionConfusionMatrix);
                SetValueMatrix(hv_DetectionConfusionMatrix, hv_ClsIdx, hv_ClsIdx, 
                    hv_NumTP);
                SetValueMatrix(hv_DetectionConfusionMatrix, hv_NumClasses, hv_ClsIdx, 
                    hv_NumFN);
                SetValueMatrix(hv_DetectionConfusionMatrix, hv_ClsIdx, hv_NumClasses, 
                    hv_NumFPBackground);
                SetValueMatrix(hv_DetectionConfusionMatrix, hv_ClsIdx, hv_NumClasses+1, 
                    hv_NumFPLocalization);
                SetValueMatrix(hv_DetectionConfusionMatrix, hv_ClsIdx, hv_NumClasses+2, 
                    hv_NumFPDuplicate);
                SetValueMatrix(hv_DetectionConfusionMatrix, hv_ClsIdx, hv_NumClasses+3, 
                    hv_NumFPMultiple);
                //
                //Go over IsFPClass and set confusions in matrix.
                hv_IndicesWithClassConfusion = (HTuple(hv_IsFPClass[hv_SortIdxs]).TupleGreaterElem(-1)).TupleFind(1);
                hv_IsFPClassIdxs = HTuple();
                if (0 != (int(hv_IndicesWithClassConfusion>-1)))
                {
                  hv_IsFPClassIdxs = HTuple(hv_IsFPClass[HTuple(hv_SortIdxs[hv_IndicesWithClassConfusion])]);
                }
                hv_ClassIdxsConfused = (hv_IsFPClassIdxs.TupleSort()).TupleUniq();
                {
                HTuple end_val366 = (hv_ClassIdxsConfused.TupleLength())-1;
                HTuple step_val366 = 1;
                for (hv_Idx=0; hv_Idx.Continue(end_val366, step_val366); hv_Idx += step_val366)
                {
                  hv_NumConfusedThisIdx = ((hv_IsFPClassIdxs.TupleFind(HTuple(hv_ClassIdxsConfused[hv_Idx]))).TupleGreaterElem(-1)).TupleSum();
                  SetValueMatrix(hv_DetectionConfusionMatrix, hv_ClsIdx, HTuple(hv_ClassIdxsConfused[hv_Idx]), 
                      hv_NumConfusedThisIdx);
                }
                }
                //
                //Update overall measures.
                hv_PerIoUFN[hv_ITIdx] = HTuple(hv_PerIoUFN[hv_ITIdx])+hv_NumFN;
                hv_PerIoUTP[hv_ITIdx] = HTuple(hv_PerIoUTP[hv_ITIdx])+hv_NumTP;
                hv_PerIoUFP[hv_ITIdx] = HTuple(hv_PerIoUFP[hv_ITIdx])+hv_NumFP;
                hv_PerIoUFPClass[hv_ITIdx] = HTuple(hv_PerIoUFPClass[hv_ITIdx])+hv_NumFPClass;
                hv_PerIoUFPBackground[hv_ITIdx] = HTuple(hv_PerIoUFPBackground[hv_ITIdx])+hv_NumFPBackground;
                hv_PerIoUFPLocalization[hv_ITIdx] = HTuple(hv_PerIoUFPLocalization[hv_ITIdx])+hv_NumFPLocalization;
                hv_PerIoUFPDuplicate[hv_ITIdx] = HTuple(hv_PerIoUFPDuplicate[hv_ITIdx])+hv_NumFPDuplicate;
                hv_PerIoUFPMultiple[hv_ITIdx] = HTuple(hv_PerIoUFPMultiple[hv_ITIdx])+hv_NumFPMultiple;
                if (0 != hv_CalcSoAP)
                {
                  //Calculate and update absolute difference of orientation for class false positives.
                  GetDictTuple(hv_CurrentClassMeasures, "abs_orientation_diff_class", 
                      &hv_AODClass);
                  hv_IdxsClass = (hv_AODClass.TupleGreaterElem(-1)).TupleFind(1);
                  if (0 != (int(hv_IdxsClass!=-1)))
                  {
                    hv_ResSoAPClass = 1.0-((HTuple(hv_AODClass[hv_IdxsClass]).TupleMean())/(HTuple(180).TupleRad()));
                    SetDictTuple(hv_PerClassDetailedEvaluation, "soap_fp_class", 
                        hv_ResSoAPClass);
                    //Update mean over classes.
                    hv_PerIoUNumClassesWithFPClass[hv_ITIdx] = HTuple(hv_PerIoUNumClassesWithFPClass[hv_ITIdx])+1;
                    if (0 != (int(HTuple(hv_PerIoUSoAPClass[hv_ITIdx])==-1)))
                    {
                      hv_PerIoUSoAPClass[hv_ITIdx] = hv_ResSoAPClass;
                    }
                    else
                    {
                      hv_PerIoUSoAPClass[hv_ITIdx] = HTuple(hv_PerIoUSoAPClass[hv_ITIdx])+hv_ResSoAPClass;
                    }
                  }
                  //Calculate and update absolute difference of orientation for localization false positives.
                  GetDictTuple(hv_CurrentClassMeasures, "abs_orientation_diff_localization", 
                      &hv_AODLocalization);
                  hv_IdxsLocalization = (hv_AODLocalization.TupleGreaterElem(-1)).TupleFind(1);
                  if (0 != (int(hv_IdxsLocalization!=-1)))
                  {
                    hv_ResSoAPLocalization = 1.0-((HTuple(hv_AODLocalization[hv_IdxsLocalization]).TupleMean())/(HTuple(180).TupleRad()));
                    SetDictTuple(hv_PerClassDetailedEvaluation, "soap_fp_localization", 
                        hv_ResSoAPLocalization);
                    //Update mean over classes.
                    hv_PerIoUNumClassesWithFPLocalization[hv_ITIdx] = HTuple(hv_PerIoUNumClassesWithFPLocalization[hv_ITIdx])+1;
                    if (0 != (int(HTuple(hv_PerIoUSoAPLocalization[hv_ITIdx])==-1)))
                    {
                      hv_PerIoUSoAPLocalization[hv_ITIdx] = hv_ResSoAPLocalization;
                    }
                    else
                    {
                      hv_PerIoUSoAPLocalization[hv_ITIdx] = HTuple(hv_PerIoUSoAPLocalization[hv_ITIdx])+hv_ResSoAPLocalization;
                    }
                  }
                  //Calculate and update absolute difference of orientation for class false positives.
                  GetDictTuple(hv_CurrentClassMeasures, "abs_orientation_diff_duplicate", 
                      &hv_AODDuplicate);
                  hv_IdxsDuplicate = (hv_AODDuplicate.TupleGreaterElem(-1)).TupleFind(1);
                  if (0 != (int(hv_IdxsDuplicate!=-1)))
                  {
                    hv_ResSoAPDuplicate = 1.0-((HTuple(hv_AODDuplicate[hv_IdxsDuplicate]).TupleMean())/(HTuple(180).TupleRad()));
                    SetDictTuple(hv_PerClassDetailedEvaluation, "soap_fp_duplicate", 
                        hv_ResSoAPDuplicate);
                    //Update mean over classes.
                    hv_PerIoUNumClassesWithFPDuplicate[hv_ITIdx] = HTuple(hv_PerIoUNumClassesWithFPDuplicate[hv_ITIdx])+1;
                    if (0 != (int(HTuple(hv_PerIoUSoAPDuplicate[hv_ITIdx])==-1)))
                    {
                      hv_PerIoUSoAPDuplicate[hv_ITIdx] = hv_ResSoAPDuplicate;
                    }
                    else
                    {
                      hv_PerIoUSoAPDuplicate[hv_ITIdx] = HTuple(hv_PerIoUSoAPDuplicate[hv_ITIdx])+hv_ResSoAPDuplicate;
                    }
                  }
                  //Calculate and update absolute difference of orientation for multiple false positives.
                  GetDictTuple(hv_CurrentClassMeasures, "abs_orientation_diff_multiple", 
                      &hv_AODMultiple);
                  hv_IdxsMultiple = (hv_AODMultiple.TupleGreaterElem(-1)).TupleFind(1);
                  if (0 != (int(hv_IdxsMultiple!=-1)))
                  {
                    hv_ResSoAPMultiple = 1.0-((HTuple(hv_AODMultiple[hv_IdxsMultiple]).TupleMean())/(HTuple(180).TupleRad()));
                    SetDictTuple(hv_PerClassDetailedEvaluation, "soap_fp_multiple", 
                        hv_ResSoAPMultiple);
                    //Update mean over classes.
                    hv_PerIoUNumClassesWithFPMultiple[hv_ITIdx] = HTuple(hv_PerIoUNumClassesWithFPMultiple[hv_ITIdx])+1;
                    if (0 != (int(HTuple(hv_PerIoUSoAPMultiple[hv_ITIdx])==-1)))
                    {
                      hv_PerIoUSoAPMultiple[hv_ITIdx] = hv_ResSoAPMultiple;
                    }
                    else
                    {
                      hv_PerIoUSoAPMultiple[hv_ITIdx] = HTuple(hv_PerIoUSoAPMultiple[hv_ITIdx])+hv_ResSoAPMultiple;
                    }
                  }
                }
              }
            }
            //
            //Write to output.
            GetDictTuple(hv_CurrentEvaluationResult, "ap_iou_"+((""+HTuple(hv_IoUThresholds[hv_ITIdx])).TupleRegexpReplace("\\.","")), 
                &hv_PerIoUAP);
            SetDictTuple(hv_PerIoUAP, "class_"+HTuple(hv_ClassIDs[hv_ClsIdx]), HTuple(hv_ClassAPPerIoU[hv_ITIdx]));
            if (0 != hv_CalcSoAP)
            {
              GetDictTuple(hv_CurrentEvaluationResult, "soap_tp_iou_"+((""+HTuple(hv_IoUThresholds[hv_ITIdx])).TupleRegexpReplace("\\.","")), 
                  &hv_PerIoUSoAP);
              SetDictTuple(hv_PerIoUSoAP, "class_"+HTuple(hv_ClassIDs[hv_ClsIdx]), 
                  HTuple(hv_ClassSoAPPerIoU[hv_ITIdx]));
            }
          }
          }
          //
          //Class mAP is the mean over IoU-thresholds.
          hv_PerClassMAP[hv_ClsIdx] = hv_ClassAPPerIoU.TupleMean();
          GetDictTuple(hv_CurrentEvaluationResult, "mean_iou_ap", &hv_ClassMAPDict);
          SetDictTuple(hv_ClassMAPDict, "class_"+HTuple(hv_ClassIDs[hv_ClsIdx]), 
              HTuple(hv_PerClassMAP[hv_ClsIdx]));
          if (0 != hv_CalcSoAP)
          {
            //ClassMSoAP is the mean over IoU-thresholds.
            hv_SoAPIoUIdxsPositive = (hv_ClassSoAPPerIoU.TupleGreaterEqualElem(0.0)).TupleFind(1);
            if (0 != (int(hv_SoAPIoUIdxsPositive!=-1)))
            {
              hv_PerClassMSoAP[hv_ClsIdx] = HTuple(hv_ClassSoAPPerIoU[hv_SoAPIoUIdxsPositive]).TupleMean();
            }
            else
            {
              hv_PerClassMSoAP[hv_ClsIdx] = -1.0;
            }
            GetDictTuple(hv_CurrentEvaluationResult, "mean_iou_soap_tp", &hv_ClassMSoAPDict);
            SetDictTuple(hv_ClassMSoAPDict, "class_"+HTuple(hv_ClassIDs[hv_ClsIdx]), 
                HTuple(hv_PerClassMSoAP[hv_ClsIdx]));
          }
        }
        }
        //
        //Calculate the mean AP and optionally mean SoAP (over classes) per IoU-threshold.
        {
        HTuple end_val468 = (hv_IoUThresholds.TupleLength())-1;
        HTuple step_val468 = 1;
        for (hv_ITIdx=0; hv_ITIdx.Continue(end_val468, step_val468); hv_ITIdx += step_val468)
        {
          GetDictTuple(hv_CurrentEvaluationResult, "ap_iou_"+((""+HTuple(hv_IoUThresholds[hv_ITIdx])).TupleRegexpReplace("\\.","")), 
              &hv_PerIoUAP);
          //
          //Consider only present classes.
          hv_MeanClassAP = -1.0;
          if (0 != (int((hv_ClassesWithGt.TupleLength())>0)))
          {
            hv_MeanClassAP = HTuple(hv_PerIoUMAP[hv_ITIdx])/(hv_ClassesWithGt.TupleLength());
          }
          SetDictTuple(hv_PerIoUAP, "mean_class_ap", hv_MeanClassAP);
          if (0 != hv_CalcSoAP)
          {
            GetDictTuple(hv_CurrentEvaluationResult, "soap_tp_iou_"+((""+HTuple(hv_IoUThresholds[hv_ITIdx])).TupleRegexpReplace("\\.","")), 
                &hv_PerIoUSoAP);
            //
            //Consider only present classes.
            hv_MeanClassSoAP = -1.0;
            if (0 != (int(HTuple(hv_PerIoUNumClassesWithTP[hv_ITIdx])>0)))
            {
              hv_MeanClassSoAP = HTuple(hv_PerIoUMSoAP[hv_ITIdx])/HTuple(hv_PerIoUNumClassesWithTP[hv_ITIdx]);
            }
            SetDictTuple(hv_PerIoUSoAP, "mean_class_soap_tp", hv_MeanClassSoAP);
          }
          //
          if (0 != hv_DetailedEvaluation)
          {
            //Add overall measures for TP, FN, FP, ...
            GetDictTuple(hv_CurrentEvaluationResult, "detailed_evaluation_iou_"+((""+HTuple(hv_IoUThresholds[hv_ITIdx])).TupleRegexpReplace("\\.","")), 
                &hv_PerIoUDetailedEvaluation);
            SetDictTuple(hv_PerIoUDetailedEvaluation, "num_tp", HTuple(hv_PerIoUTP[hv_ITIdx]));
            SetDictTuple(hv_PerIoUDetailedEvaluation, "num_fn", HTuple(hv_PerIoUFN[hv_ITIdx]));
            SetDictTuple(hv_PerIoUDetailedEvaluation, "num_fp", HTuple(hv_PerIoUFP[hv_ITIdx]));
            SetDictTuple(hv_PerIoUDetailedEvaluation, "num_fp_class", HTuple(hv_PerIoUFPClass[hv_ITIdx]));
            SetDictTuple(hv_PerIoUDetailedEvaluation, "num_fp_background", HTuple(hv_PerIoUFPBackground[hv_ITIdx]));
            SetDictTuple(hv_PerIoUDetailedEvaluation, "num_fp_duplicate", HTuple(hv_PerIoUFPDuplicate[hv_ITIdx]));
            SetDictTuple(hv_PerIoUDetailedEvaluation, "num_fp_localization", HTuple(hv_PerIoUFPLocalization[hv_ITIdx]));
            SetDictTuple(hv_PerIoUDetailedEvaluation, "num_fp_multiple", HTuple(hv_PerIoUFPMultiple[hv_ITIdx]));
            if (0 != hv_CalcSoAP)
            {
              if (0 != (int(HTuple(hv_PerIoUNumClassesWithFPClass[hv_ITIdx])>0)))
              {
                hv_PerIoUSoAPClass[hv_ITIdx] = HTuple(hv_PerIoUSoAPClass[hv_ITIdx])/HTuple(hv_PerIoUNumClassesWithFPClass[hv_ITIdx]);
              }
              if (0 != (int(HTuple(hv_PerIoUNumClassesWithFPLocalization[hv_ITIdx])>0)))
              {
                hv_PerIoUSoAPLocalization[hv_ITIdx] = HTuple(hv_PerIoUSoAPLocalization[hv_ITIdx])/HTuple(hv_PerIoUNumClassesWithFPLocalization[hv_ITIdx]);
              }
              if (0 != (int(HTuple(hv_PerIoUNumClassesWithFPDuplicate[hv_ITIdx])>0)))
              {
                hv_PerIoUSoAPDuplicate[hv_ITIdx] = HTuple(hv_PerIoUSoAPDuplicate[hv_ITIdx])/HTuple(hv_PerIoUNumClassesWithFPDuplicate[hv_ITIdx]);
              }
              if (0 != (int(HTuple(hv_PerIoUNumClassesWithFPMultiple[hv_ITIdx])>0)))
              {
                hv_PerIoUSoAPMultiple[hv_ITIdx] = HTuple(hv_PerIoUSoAPMultiple[hv_ITIdx])/HTuple(hv_PerIoUNumClassesWithFPMultiple[hv_ITIdx]);
              }
              SetDictTuple(hv_PerIoUDetailedEvaluation, "soap_fp_class", HTuple(hv_PerIoUSoAPClass[hv_ITIdx]));
              SetDictTuple(hv_PerIoUDetailedEvaluation, "soap_fp_localization", HTuple(hv_PerIoUSoAPLocalization[hv_ITIdx]));
              SetDictTuple(hv_PerIoUDetailedEvaluation, "soap_fp_duplicate", HTuple(hv_PerIoUSoAPDuplicate[hv_ITIdx]));
              SetDictTuple(hv_PerIoUDetailedEvaluation, "soap_fp_multiple", HTuple(hv_PerIoUSoAPMultiple[hv_ITIdx]));
            }
          }
        }
        }
        //
        //Calculate overall mean AP (over classes and IoU-thresholds).
        //Also here only classes with ground truth annotations are taken into account.
        hv_MAP = -1.0;
        if (0 != (int((hv_ClassesWithGt.TupleLength())>0)))
        {
          hv_MAP = (HTuple(hv_PerClassMAP[hv_ClassesWithGt]).TupleSum())/(hv_ClassesWithGt.TupleLength());
        }
        SetDictTuple(hv_CurrentEvaluationResult, "mean_ap", hv_MAP);
        if (0 != hv_CalcSoAP)
        {
          hv_MSoAP = -1.0;
          if (0 != (int((hv_PerIoUNumClassesWithTP.TupleSum())>0)))
          {
            hv_IoUsWithTP = (hv_PerIoUNumClassesWithTP.TupleGreaterElem(0)).TupleFind(1);
            hv_MSoAP = ((HTuple(hv_PerIoUMSoAP[hv_IoUsWithTP])/HTuple(hv_PerIoUNumClassesWithTP[hv_IoUsWithTP])).TupleSum())/(hv_IoUsWithTP.TupleLength());
          }
          SetDictTuple(hv_CurrentEvaluationResult, "mean_soap_tp", hv_MSoAP);
          if (0 != hv_DetailedEvaluation)
          {
            hv_MSoAPAll = 0.0;
            hv_NumSoAPAll = 0;
            if (0 != (int((hv_PerIoUNumClassesWithTP.TupleSum())>0)))
            {
              hv_IoUsWithTP = (hv_PerIoUNumClassesWithTP.TupleGreaterElem(0)).TupleFind(1);
              hv_MSoAPAll = hv_MSoAP*(HTuple(hv_PerIoUNumClassesWithTP[hv_IoUsWithTP]).TupleSum());
              hv_NumSoAPAll += HTuple(hv_PerIoUNumClassesWithTP[hv_IoUsWithTP]).TupleSum();
            }
            if (0 != (int((hv_PerIoUNumClassesWithFPClass.TupleSum())>0)))
            {
              hv_IoUsWithFPClass = (hv_PerIoUNumClassesWithFPClass.TupleGreaterElem(0)).TupleFind(1);
              hv_MSoAPAll += ((HTuple(hv_PerIoUSoAPClass[hv_IoUsWithFPClass]).TupleSum())/(hv_IoUsWithFPClass.TupleLength()))*(HTuple(hv_PerIoUNumClassesWithFPClass[hv_IoUsWithFPClass]).TupleSum());
              hv_NumSoAPAll += HTuple(hv_PerIoUNumClassesWithFPClass[hv_IoUsWithFPClass]).TupleSum();
            }
            if (0 != (int((hv_PerIoUNumClassesWithFPLocalization.TupleSum())>0)))
            {
              hv_IoUsWithFPLocalization = (hv_PerIoUNumClassesWithFPLocalization.TupleGreaterElem(0)).TupleFind(1);
              hv_MSoAPAll += ((HTuple(hv_PerIoUSoAPLocalization[hv_IoUsWithFPLocalization]).TupleSum())/(hv_IoUsWithFPLocalization.TupleLength()))*(HTuple(hv_PerIoUNumClassesWithFPLocalization[hv_IoUsWithFPLocalization]).TupleSum());
              hv_NumSoAPAll += HTuple(hv_PerIoUNumClassesWithFPLocalization[hv_IoUsWithFPLocalization]).TupleSum();
            }
            if (0 != (int((hv_PerIoUNumClassesWithFPDuplicate.TupleSum())>0)))
            {
              hv_IoUsWithFPDuplicate = (hv_PerIoUNumClassesWithFPDuplicate.TupleGreaterElem(0)).TupleFind(1);
              hv_MSoAPAll += ((HTuple(hv_PerIoUSoAPDuplicate[hv_IoUsWithFPDuplicate]).TupleSum())/(hv_IoUsWithFPDuplicate.TupleLength()))*(HTuple(hv_PerIoUNumClassesWithFPDuplicate[hv_IoUsWithFPDuplicate]).TupleSum());
              hv_NumSoAPAll += HTuple(hv_PerIoUNumClassesWithFPDuplicate[hv_IoUsWithFPDuplicate]).TupleSum();
            }
            if (0 != (int((hv_PerIoUNumClassesWithFPMultiple.TupleSum())>0)))
            {
              hv_IoUsWithFPMultiple = (hv_PerIoUNumClassesWithFPMultiple.TupleGreaterElem(0)).TupleFind(1);
              hv_MSoAPAll += ((HTuple(hv_PerIoUSoAPMultiple[hv_IoUsWithFPMultiple]).TupleSum())/(hv_IoUsWithFPMultiple.TupleLength()))*(HTuple(hv_PerIoUNumClassesWithFPMultiple[hv_IoUsWithFPMultiple]).TupleSum());
              hv_NumSoAPAll += HTuple(hv_PerIoUNumClassesWithFPMultiple[hv_IoUsWithFPMultiple]).TupleSum();
            }
            if (0 != (int(hv_NumSoAPAll>0)))
            {
              SetDictTuple(hv_CurrentEvaluationResult, "mean_soap_all", (hv_MSoAPAll.TupleReal())/hv_NumSoAPAll);
            }
            else
            {
              SetDictTuple(hv_CurrentEvaluationResult, "mean_soap_all", -1);
            }
            //
          }
        }
        //
        //Add CurrentEvaluationResult to output.
        SetDictTuple(hv_PerMaxNumEvaluationResult, "area_"+hv_AreaName, hv_CurrentEvaluationResult);
      }
      }
      //Add PerMaxNumEvaluationResult to output.
      SetDictTuple((*hv_EvaluationResult), "max_num_detections_"+hv_MaxNumStr, hv_PerMaxNumEvaluationResult);
    }
    }
  }
  //
  return;
}

// Chapter: Filters / Lines
// Short Description: Calculate the parameters Sigma, Low, and High for lines_gauss. 
void calculate_lines_gauss_parameters (HTuple hv_MaxLineWidth, HTuple hv_Contrast, 
    HTuple *hv_Sigma, HTuple *hv_Low, HTuple *hv_High)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_ContrastHigh, hv_ContrastLow, hv_HalfWidth;
  HTuple  hv_Help;

  //Check control parameters
  if (0 != (int((hv_MaxLineWidth.TupleLength())!=1)))
  {
    throw HException("Wrong number of values of control parameter: 1");
  }
  if (0 != ((hv_MaxLineWidth.TupleIsNumber()).TupleNot()))
  {
    throw HException("Wrong type of control parameter: 1");
  }
  if (0 != (int(hv_MaxLineWidth<=0)))
  {
    throw HException("Wrong value of control parameter: 1");
  }
  if (0 != (HTuple(int((hv_Contrast.TupleLength())!=1)).TupleAnd(int((hv_Contrast.TupleLength())!=2))))
  {
    throw HException("Wrong number of values of control parameter: 2");
  }
  if (0 != (int(((hv_Contrast.TupleIsNumber()).TupleMin())==0)))
  {
    throw HException("Wrong type of control parameter: 2");
  }
  //Set and check ContrastHigh
  hv_ContrastHigh = ((const HTuple&)hv_Contrast)[0];
  if (0 != (int(hv_ContrastHigh<0)))
  {
    throw HException("Wrong value of control parameter: 2");
  }
  //Set or derive ContrastLow
  if (0 != (int((hv_Contrast.TupleLength())==2)))
  {
    hv_ContrastLow = ((const HTuple&)hv_Contrast)[1];
  }
  else
  {
    hv_ContrastLow = hv_ContrastHigh/3.0;
  }
  //Check ContrastLow
  if (0 != (int(hv_ContrastLow<0)))
  {
    throw HException("Wrong value of control parameter: 2");
  }
  if (0 != (int(hv_ContrastLow>hv_ContrastHigh)))
  {
    throw HException("Wrong value of control parameter: 2");
  }
  //
  //Calculate the parameters Sigma, Low, and High for lines_gauss
  if (0 != (int(hv_MaxLineWidth<(HTuple(3.0).TupleSqrt()))))
  {
    //Note that LineWidthMax < sqrt(3.0) would result in a Sigma < 0.5,
    //which does not make any sense, because the corresponding smoothing
    //filter mask would be of size 1x1.
    //To avoid this, LineWidthMax is restricted to values greater or equal
    //to sqrt(3.0) and the contrast values are adapted to reflect the fact
    //that lines that are thinner than sqrt(3.0) pixels have a lower contrast
    //in the smoothed image (compared to lines that are sqrt(3.0) pixels wide).
    hv_ContrastLow = (hv_ContrastLow*hv_MaxLineWidth)/(HTuple(3.0).TupleSqrt());
    hv_ContrastHigh = (hv_ContrastHigh*hv_MaxLineWidth)/(HTuple(3.0).TupleSqrt());
    hv_MaxLineWidth = HTuple(3.0).TupleSqrt();
  }
  //Convert LineWidthMax and the given contrast values into the input parameters
  //Sigma, Low, and High required by lines_gauss
  hv_HalfWidth = hv_MaxLineWidth/2.0;
  (*hv_Sigma) = hv_HalfWidth/(HTuple(3.0).TupleSqrt());
  hv_Help = ((-2.0*hv_HalfWidth)/((HTuple(6.283185307178).TupleSqrt())*((*hv_Sigma).TuplePow(3.0))))*((-0.5*((hv_HalfWidth/(*hv_Sigma)).TuplePow(2.0))).TupleExp());
  (*hv_High) = (hv_ContrastHigh*hv_Help).TupleFabs();
  (*hv_Low) = (hv_ContrastLow*hv_Help).TupleFabs();
  return;
}

// Chapter: Deep Learning / Multi-Label Classification
// Short Description: Calculate multi-label classification measures based on RunningMeasures. 
void calculate_multi_label_classification_measures (HTuple hv_RunningMeasures, HTuple hv_EvalParams, 
    HTuple *hv_EvaluationResult)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_ClassIDs, hv_ClassNames, hv_MinConfidence;
  HTuple  hv_InterpolatePRCurves, hv_KeyExists, hv_CalcPrecision;
  HTuple  hv_CalcRecall, hv_CalcFScore, hv_CalcMap, hv_CalcAccuracy;
  HTuple  hv_AveragePrecisions, hv_ClassIdx, hv_ResultClassDict;
  HTuple  hv_ClassKey, hv_RunningMeasuresClassDict, hv_TP;
  HTuple  hv_FP, hv_FN, hv_SortIdxs, hv_GroundTruth, hv_Confidences;
  HTuple  hv_Thresholds, hv_ThreshIdx, hv_Threshold, hv_PredictedPositives;
  HTuple  hv_DivisorPrec, hv_DivisorRec, hv_InvalidIndPrec;
  HTuple  hv_InvalidIndRec, hv_Precision, hv_Recall, hv_InterpolatedPrecision;
  HTuple  hv_PIdx, hv_AreaUnderCurve, hv_RecIdx, hv_DivisorFscore;
  HTuple  hv_NSamples, hv_CorrectPredictions, hv___Tmp_Ctrl_Dict_Init_1;
  HTuple  hv___Tmp_Ctrl_Dict_Init_3;

  //
  //Retrieve information from EvalParams
  hv_ClassIDs = hv_EvalParams.TupleGetDictTuple("class_ids");
  hv_ClassNames = hv_EvalParams.TupleGetDictTuple("class_names");
  hv_MinConfidence = hv_EvalParams.TupleGetDictTuple("min_confidence");
  hv_InterpolatePRCurves = 0;
  GetDictParam(hv_EvalParams, "key_exists", "interpolate_pr_curves", &hv_KeyExists);
  if (0 != hv_KeyExists)
  {
    GetDictTuple(hv_EvalParams, "interpolate_pr_curves", &hv_InterpolatePRCurves);
  }
  check_multi_label_classification_measures(hv_EvalParams, &hv_CalcPrecision, &hv_CalcRecall, 
      &hv_CalcFScore, &hv_CalcMap, &hv_CalcAccuracy);
  //
  //Initialize EvaluationResult
  CreateDict(&(*hv_EvaluationResult));
  CreateDict(&hv___Tmp_Ctrl_Dict_Init_1);
  SetDictTuple((*hv_EvaluationResult), "classes", hv___Tmp_Ctrl_Dict_Init_1);
  hv___Tmp_Ctrl_Dict_Init_1 = HTuple::TupleConstant("HNULL");
  if (0 != (HTuple(hv_CalcPrecision.TupleOr(hv_CalcRecall)).TupleOr(hv_CalcFScore)))
  {
    SetDictTuple((*hv_EvaluationResult), "mean_precision", 0.0);
    SetDictTuple((*hv_EvaluationResult), "mean_recall", 0.0);
    SetDictTuple((*hv_EvaluationResult), "mean_f_score", 0.0);
  }
  if (0 != hv_CalcMap)
  {
    SetDictTuple((*hv_EvaluationResult), "mean_ap", 0.0);
  }
  if (0 != hv_CalcAccuracy)
  {
    SetDictTuple((*hv_EvaluationResult), "accuracy", 0.0);
  }
  //
  hv_AveragePrecisions = HTuple();
  //Iterate over all classes
  {
  HTuple end_val31 = (hv_ClassIDs.TupleLength())-1;
  HTuple step_val31 = 1;
  for (hv_ClassIdx=0; hv_ClassIdx.Continue(end_val31, step_val31); hv_ClassIdx += step_val31)
  {
    CreateDict(&hv_ResultClassDict);
    SetDictTuple(hv_ResultClassDict, "class_name", HTuple(hv_ClassNames[hv_ClassIdx]));
    hv_ClassKey = "class_"+HTuple(hv_ClassIDs[hv_ClassIdx]);
    GetDictTuple(hv_RunningMeasures, hv_ClassKey, &hv_RunningMeasuresClassDict);
    //
    if (0 != hv_CalcMap)
    {
      SetDictTuple(hv_ResultClassDict, "ap", 0);
      CreateDict(&hv___Tmp_Ctrl_Dict_Init_3);
      SetDictTuple(hv___Tmp_Ctrl_Dict_Init_3, "comp", HTuple());
      if (0 != (((hv_RunningMeasuresClassDict.TupleConcat(hv___Tmp_Ctrl_Dict_Init_3)).TupleTestEqualDictItem("confidences","comp")).TupleNot()))
      {
        //Iterate over confidence thresholds (for mAP)
        hv_TP = HTuple();
        hv_FP = HTuple();
        hv_FN = HTuple();
        hv_SortIdxs = (-(hv_RunningMeasuresClassDict.TupleGetDictTuple("confidences"))).TupleSortIndex();
        hv_GroundTruth = HTuple((hv_RunningMeasuresClassDict.TupleGetDictTuple("ground_truth"))[hv_SortIdxs]);
        hv_Confidences = HTuple((hv_RunningMeasuresClassDict.TupleGetDictTuple("confidences"))[hv_SortIdxs]);
        hv_Thresholds.Clear();
        hv_Thresholds[0] = 1;
        hv_Thresholds.Append(hv_Confidences);
        hv_Thresholds.Append(0);
        //
        {
        HTuple end_val51 = (hv_Thresholds.TupleLength())-1;
        HTuple step_val51 = 1;
        for (hv_ThreshIdx=0; hv_ThreshIdx.Continue(end_val51, step_val51); hv_ThreshIdx += step_val51)
        {
          hv_Threshold = HTuple(hv_Thresholds[hv_ThreshIdx]);
          hv_PredictedPositives = hv_Confidences.TupleGreaterEqualElem(hv_Threshold);
          hv_TP[hv_ThreshIdx] = HTuple(hv_PredictedPositives.TupleAnd(hv_GroundTruth)).TupleSum();
          hv_FP[hv_ThreshIdx] = HTuple(hv_PredictedPositives.TupleAnd(hv_GroundTruth.TupleNot())).TupleSum();
          hv_FN[hv_ThreshIdx] = HTuple(HTuple(hv_PredictedPositives.TupleNot()).TupleAnd(hv_GroundTruth)).TupleSum();
        }
        }
        //Calculate Precision and Recall
        hv_DivisorPrec = hv_FP+hv_TP;
        hv_DivisorRec = hv_FN+hv_TP;
        //Avoid division by zero by replacing divisor with dummy values
        TupleFind(hv_DivisorPrec, 0, &hv_InvalidIndPrec);
        TupleFind(hv_DivisorRec, 0, &hv_InvalidIndRec);
        if (0 != (int(hv_InvalidIndPrec!=-1)))
        {
          hv_DivisorPrec[hv_InvalidIndPrec] = -1;
        }
        if (0 != (int(hv_InvalidIndRec!=-1)))
        {
          hv_DivisorRec[hv_InvalidIndRec] = -1;
        }
        //
        hv_Precision = (hv_TP.TupleReal())/hv_DivisorPrec;
        hv_Recall = (hv_TP.TupleReal())/hv_DivisorRec;
        //
        //Fix dummy values in precision and recall
        if (0 != (int(hv_InvalidIndPrec!=-1)))
        {
          hv_Precision[hv_InvalidIndPrec] = 1.0;
        }
        if (0 != (int(hv_InvalidIndRec!=-1)))
        {
          hv_Recall[hv_InvalidIndRec] = 1.0;
        }
        //
        //(Optionally) smooth precision-recall curve.
        hv_InterpolatedPrecision = hv_Precision;
        if (0 != hv_InterpolatePRCurves)
        {
          for (hv_PIdx=(hv_Precision.TupleLength())-2; hv_PIdx>=0; hv_PIdx+=-1)
          {
            hv_InterpolatedPrecision[hv_PIdx] = HTuple(hv_InterpolatedPrecision[hv_PIdx]).TupleMax2(HTuple(hv_InterpolatedPrecision[hv_PIdx+1]));
          }
        }
        //Approximate the area under the Precision-Recall curve.
        hv_AreaUnderCurve = 0;
        hv_AreaUnderCurve += (HTuple(hv_Recall[0])-0)*HTuple(hv_InterpolatedPrecision[0]);
        {
        HTuple end_val92 = (hv_Recall.TupleLength())-2;
        HTuple step_val92 = 1;
        for (hv_RecIdx=0; hv_RecIdx.Continue(end_val92, step_val92); hv_RecIdx += step_val92)
        {
          hv_AreaUnderCurve += (HTuple(hv_Recall[hv_RecIdx+1])-HTuple(hv_Recall[hv_RecIdx]))*HTuple(hv_InterpolatedPrecision[hv_RecIdx]);
        }
        }
        hv_AreaUnderCurve += (1-HTuple(hv_Recall[hv_RecIdx]))*HTuple(hv_InterpolatedPrecision[hv_RecIdx]);
        SetDictTuple(hv_ResultClassDict, "ap", hv_AreaUnderCurve);
        SetDictTuple((*hv_EvaluationResult), "mean_ap", ((*hv_EvaluationResult).TupleGetDictTuple("mean_ap"))+hv_AreaUnderCurve);
      }
      hv___Tmp_Ctrl_Dict_Init_3 = HTuple::TupleConstant("HNULL");
    }
    //Record precision, recall and f_score for min_confidence threshold
    if (0 != (HTuple(hv_CalcPrecision.TupleOr(hv_CalcRecall)).TupleOr(hv_CalcFScore)))
    {
      GetDictTuple(hv_RunningMeasuresClassDict, "tp", &hv_TP);
      GetDictTuple(hv_RunningMeasuresClassDict, "fp", &hv_FP);
      GetDictTuple(hv_RunningMeasuresClassDict, "fn", &hv_FN);
      hv_DivisorPrec = hv_FP+hv_TP;
      hv_DivisorRec = hv_FN+hv_TP;
      hv_DivisorFscore = ((2*hv_TP)+hv_FP)+hv_FN;
      //
      //Avoid division by zero for edge cases
      if (0 != (int(hv_DivisorPrec==0)))
      {
        SetDictTuple(hv_ResultClassDict, "precision", 1.0);
      }
      else
      {
        SetDictTuple(hv_ResultClassDict, "precision", (hv_TP.TupleReal())/hv_DivisorPrec);
      }
      if (0 != (int(hv_DivisorRec==0)))
      {
        SetDictTuple(hv_ResultClassDict, "recall", 1.0);
      }
      else
      {
        SetDictTuple(hv_ResultClassDict, "recall", (hv_TP.TupleReal())/hv_DivisorRec);
      }
      if (0 != (int(hv_DivisorFscore==0)))
      {
        SetDictTuple(hv_ResultClassDict, "f_score", 1.0);
      }
      else
      {
        SetDictTuple(hv_ResultClassDict, "f_score", (2.0*hv_TP)/hv_DivisorFscore);
      }
      //
      //Store sum of all valid class values to calculate average below
      SetDictTuple((*hv_EvaluationResult), "mean_precision", ((*hv_EvaluationResult).TupleGetDictTuple("mean_precision"))+(hv_ResultClassDict.TupleGetDictTuple("precision")));
      SetDictTuple((*hv_EvaluationResult), "mean_recall", ((*hv_EvaluationResult).TupleGetDictTuple("mean_recall"))+(hv_ResultClassDict.TupleGetDictTuple("recall")));
      SetDictTuple((*hv_EvaluationResult), "mean_f_score", ((*hv_EvaluationResult).TupleGetDictTuple("mean_f_score"))+(hv_ResultClassDict.TupleGetDictTuple("f_score")));
    }
    //Calculate and store per-class accuracy
    if (0 != hv_CalcAccuracy)
    {
      SetDictTuple(hv_ResultClassDict, "accuracy", 0);
      hv_NSamples = (hv_RunningMeasures.TupleGetDictTuple("image_ids")).TupleLength();
      if (0 != (int(hv_NSamples>0)))
      {
        GetDictTuple(hv_RunningMeasuresClassDict, "fp", &hv_FP);
        GetDictTuple(hv_RunningMeasuresClassDict, "fn", &hv_FN);
        hv_CorrectPredictions = (hv_NSamples-hv_FP)-hv_FN;
        SetDictTuple(hv_ResultClassDict, "accuracy", (hv_CorrectPredictions.TupleReal())/hv_NSamples);
      }
    }
    //Store values
    SetDictTuple((*hv_EvaluationResult).TupleGetDictTuple("classes"), HTuple(hv_ClassIDs[hv_ClassIdx]), 
        hv_ResultClassDict);
  }
  }
  //Calculate and store overall accuracy
  if (0 != hv_CalcAccuracy)
  {
    hv_NSamples = (hv_RunningMeasures.TupleGetDictTuple("image_ids")).TupleLength();
    if (0 != (int(hv_NSamples>0)))
    {
      SetDictTuple((*hv_EvaluationResult), "accuracy", ((hv_RunningMeasures.TupleGetDictTuple("correct_predictions")).TupleReal())/hv_NSamples);
    }
  }
  //Calculate and store mAP over thresholds in 'EvalParams.confidence_threshold'
  if (0 != hv_CalcMap)
  {
    SetDictTuple((*hv_EvaluationResult), "mean_ap", ((*hv_EvaluationResult).TupleGetDictTuple("mean_ap"))/(hv_ClassIDs.TupleLength()));
  }
  //Calculate and store mean precision, mean recall and mean f_score over all classes
  if (0 != (HTuple(hv_CalcPrecision.TupleOr(hv_CalcRecall)).TupleOr(hv_CalcFScore)))
  {
    SetDictTuple((*hv_EvaluationResult), "mean_precision", ((*hv_EvaluationResult).TupleGetDictTuple("mean_precision"))/(hv_ClassIDs.TupleLength()));
    SetDictTuple((*hv_EvaluationResult), "mean_recall", ((*hv_EvaluationResult).TupleGetDictTuple("mean_recall"))/(hv_ClassIDs.TupleLength()));
    SetDictTuple((*hv_EvaluationResult), "mean_f_score", ((*hv_EvaluationResult).TupleGetDictTuple("mean_f_score"))/(hv_ClassIDs.TupleLength()));
  }
  //
  return;
}

// Chapter: OCR / Deep OCR
// Short Description: Computes the ocr_detection relevant evaluation measures. 
void calculate_ocr_detection_measures (HTuple hv_DetectionEvaluationResult, HTuple *hv_EvaluationResult)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_Keys, hv_Matches, hv_Key, hv_WordEval;
  HTuple  hv_NumAll, hv_NumTPFP, hv_Divisor, hv___Tmp_Ctrl_Type;

  GetDictParam((hv_DetectionEvaluationResult.TupleGetDictTuple("max_num_detections_all")).TupleGetDictTuple("area_all"), 
      "keys", HTuple(), &hv_Keys);
  //Use the first matching key in order to compute the measures.
  TupleRegexpSelect(hv_Keys, "detailed_evaluation_iou_.*", &hv_Matches);
  hv_Key = ((const HTuple&)hv_Matches)[0];
  hv_WordEval = (((hv_DetectionEvaluationResult.TupleGetDictTuple("max_num_detections_all")).TupleGetDictTuple("area_all")).TupleGetDictTuple(hv_Key)).TupleGetDictTuple("class_0");
  CreateDict(&(*hv_EvaluationResult));
  //Recall
  hv_NumAll = (hv_WordEval.TupleGetDictTuple("num_tp"))+(hv_WordEval.TupleGetDictTuple("num_fn"));
  if (0 != (int(hv_NumAll>0)))
  {
    SetDictTuple((*hv_EvaluationResult), "recall", (hv_WordEval.TupleGetDictTuple("num_tp"))/(hv_NumAll.TupleReal()));
  }
  else
  {
    SetDictTuple((*hv_EvaluationResult), "recall", 0.0);
  }
  //Precision
  hv_NumTPFP = (hv_WordEval.TupleGetDictTuple("num_tp"))+(hv_WordEval.TupleGetDictTuple("num_fp"));
  if (0 != (int(hv_NumTPFP>0)))
  {
    SetDictTuple((*hv_EvaluationResult), "precision", (hv_WordEval.TupleGetDictTuple("num_tp"))/(hv_NumTPFP.TupleReal()));
  }
  else
  {
    SetDictTuple((*hv_EvaluationResult), "precision", 0.0);
  }
  //F-Score
  hv_Divisor = ((*hv_EvaluationResult).TupleGetDictTuple("precision"))+((*hv_EvaluationResult).TupleGetDictTuple("recall"));
  if (0 != (int(hv_Divisor!=0)))
  {
    SetDictTuple((*hv_EvaluationResult), "f_score", ((2*((*hv_EvaluationResult).TupleGetDictTuple("precision")))*((*hv_EvaluationResult).TupleGetDictTuple("recall")))/hv_Divisor);
  }
  else
  {
    SetDictTuple((*hv_EvaluationResult), "f_score", 0.0);
  }
  //SoAP
  TupleRegexpSelect(hv_Keys, "soap_tp_iou_.*", &hv_Matches);
  if (0 != (int((hv_Matches.TupleLength())>0)))
  {
    hv_Key = ((const HTuple&)hv_Matches)[0];
    GetDictParam(((hv_DetectionEvaluationResult.TupleGetDictTuple("max_num_detections_all")).TupleGetDictTuple("area_all")).TupleGetDictTuple(hv_Key), 
        "key_data_type", "class_0", &hv___Tmp_Ctrl_Type);
    if (0 != (int(hv___Tmp_Ctrl_Type==HTuple("object"))))
    {
      SetDictObject((((hv_DetectionEvaluationResult.TupleGetDictTuple("max_num_detections_all")).TupleGetDictTuple("area_all")).TupleGetDictTuple(hv_Key)).TupleGetDictObject("class_0"), 
          (*hv_EvaluationResult), "soap");
    }
    else
    {
      SetDictTuple((*hv_EvaluationResult), "soap", (((hv_DetectionEvaluationResult.TupleGetDictTuple("max_num_detections_all")).TupleGetDictTuple("area_all")).TupleGetDictTuple(hv_Key)).TupleGetDictTuple("class_0"));
    }
  }
  return;
}

// Chapter: OCR / Deep OCR
// Short Description: Calculate OCR recognition measures based on RunningMeasures. 
void calculate_ocr_recognition_measures (HTuple hv_RunningMeasures, HTuple hv_EvalParams, 
    HTuple *hv_EvaluationResult)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_Equal;

  //
  //This procedure calculates the final summarizing OCR recognition measures based on the running measures.
  //
  //
  //Initialize output dictionary and get necessary evaluation parameters.
  CreateDict(&(*hv_EvaluationResult));
  //
  //Compute Accuracy
  hv_Equal = (hv_RunningMeasures.TupleGetDictTuple("words_ground_truth")).TupleEqualElem(hv_RunningMeasures.TupleGetDictTuple("words_prediction"));
  if (0 != (int((hv_Equal.TupleLength())>0)))
  {
    SetDictTuple((*hv_EvaluationResult), "accuracy", ((hv_Equal.TupleSum())/(HTuple(hv_Equal.TupleLength()).TupleReal()))*100);
  }
  else
  {
    SetDictTuple((*hv_EvaluationResult), "accuracy", 0);
  }
  return;
}

// Chapter: Deep Learning / Classification
// Short Description: Calculate out-of-distribution detection measures based on RunningMeasures. 
void calculate_ood_detection_measures (HTuple hv_RunningMeasures, HTuple hv_EvalParams, 
    HTuple hv_EvaluationResult)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_CalcOODConfusionMatrix, hv_CalcOODPrecision;
  HTuple  hv_CalcOODRecall, hv_CalcOODFScore, hv_CalcOODFPR;
  HTuple  hv_CalcOODScoreHistogram, hv_CalcOODScoreThresholds;
  HTuple  hv_Measures, hv_M, hv_OODPredictionsID, hv_OODScoresID;
  HTuple  hv_OODPredictionsOOD, hv_OODScoresOOD, hv_NumIDSamples;
  HTuple  hv_NumOODSamples, hv_OODConfusionMatrix, hv_Rows;
  HTuple  hv_Columns, hv_Value, hv_NumTruePositives, hv_NumFalsePositives;
  HTuple  hv_NumFalseNegatives, hv_NumPredictedPositives;
  HTuple  hv_HistoIDXValues, hv_HistoIDYValues, hv_HistoOODXValues;
  HTuple  hv_HistoOODYValues, hv_ScoreHistogram, hv_ModelThresholdExists;
  HTuple  hv_NoFPThreshold, hv_NoFNThreshold, hv_OODScores;
  HTuple  hv_MinErrorThreshold, hv_OODScoresSortIndices, hv_OODScoresSorted;
  HTuple  hv_TmpID, hv_TmpIDSorted, hv_TrueNegativesPerScore;
  HTuple  hv_FPRate, hv_TmpOOD, hv_TmpOODSorted, hv_FalseNegativesPerScore;
  HTuple  hv_FNRate, hv_FprFnrSum, hv_MinFprFnRSum, hv_ThresholdIndex;
  HTuple  hv___Tmp_Ctrl_Dict_Init_0, hv___Tmp_Ctrl_Dict_Init_1;
  HTuple  hv___Tmp_Ctrl_Dict_Init_3, hv___Tmp_Ctrl_Type;

  //
  //This procedure calculates the final summarizing out-of-distribution detection measures based on the running measures.
  //
  //Set default values.
  hv_CalcOODConfusionMatrix = 0;
  hv_CalcOODPrecision = 0;
  hv_CalcOODRecall = 0;
  hv_CalcOODFScore = 0;
  hv_CalcOODFPR = 0;
  hv_CalcOODScoreHistogram = 0;
  hv_CalcOODScoreThresholds = 0;
  //
  //Check which measures are to be calculated.
  GetDictTuple(hv_EvalParams, "measures", &hv_Measures);
  {
  HTuple end_val14 = (hv_Measures.TupleLength())-1;
  HTuple step_val14 = 1;
  for (hv_M=0; hv_M.Continue(end_val14, step_val14); hv_M += step_val14)
  {
    if (0 != (int(HTuple(hv_Measures[hv_M])==HTuple("ood_confusion_matrix"))))
    {
      hv_CalcOODConfusionMatrix = 1;
    }
    else if (0 != (int(HTuple(hv_Measures[hv_M])==HTuple("ood_precision"))))
    {
      hv_CalcOODPrecision = 1;
    }
    else if (0 != (int(HTuple(hv_Measures[hv_M])==HTuple("ood_recall"))))
    {
      hv_CalcOODRecall = 1;
    }
    else if (0 != (int(HTuple(hv_Measures[hv_M])==HTuple("ood_f_score"))))
    {
      hv_CalcOODPrecision = 1;
      hv_CalcOODRecall = 1;
      hv_CalcOODFScore = 1;
    }
    else if (0 != (int(HTuple(hv_Measures[hv_M])==HTuple("ood_false_positive_rate"))))
    {
      hv_CalcOODFPR = 1;
    }
    else if (0 != (int(HTuple(hv_Measures[hv_M])==HTuple("ood_score_histogram"))))
    {
      hv_CalcOODScoreHistogram = 1;
      hv_CalcOODScoreThresholds = 1;
    }
    else if (0 != (int(HTuple(hv_Measures[hv_M])==HTuple("ood_thresholds"))))
    {
      hv_CalcOODScoreThresholds = 1;
    }
    else if (0 != (int(HTuple(hv_Measures[hv_M])==HTuple("all"))))
    {
      hv_CalcOODConfusionMatrix = 1;
      hv_CalcOODScoreHistogram = 1;
      hv_CalcOODScoreThresholds = 1;
      hv_CalcOODPrecision = 1;
      hv_CalcOODRecall = 1;
      hv_CalcOODFScore = 1;
      hv_CalcOODFPR = 1;
    }
  }
  }
  //
  if (0 != (HTuple(HTuple(hv_CalcOODPrecision.TupleOr(hv_CalcOODRecall)).TupleOr(hv_CalcOODFScore)).TupleOr(hv_CalcOODFPR)))
  {
    CreateDict(&hv___Tmp_Ctrl_Dict_Init_0);
    SetDictTuple(hv_EvaluationResult, "ood_measures", hv___Tmp_Ctrl_Dict_Init_0);
    hv___Tmp_Ctrl_Dict_Init_0 = HTuple::TupleConstant("HNULL");
  }
  //
  hv_OODPredictionsID = hv_RunningMeasures.TupleGetDictTuple("ood_predictions");
  hv_OODScoresID = hv_RunningMeasures.TupleGetDictTuple("ood_scores");
  hv_OODPredictionsOOD = (hv_RunningMeasures.TupleGetDictTuple("evaluated_ood_samples")).TupleGetDictTuple("ood_predictions");
  hv_OODScoresOOD = (hv_RunningMeasures.TupleGetDictTuple("evaluated_ood_samples")).TupleGetDictTuple("ood_scores");
  //Set OOD ground truths, predictions and scores for the evaluated samples in EvaluationResult.
  SetDictTuple(hv_EvaluationResult.TupleGetDictTuple("evaluated_samples"), "ood_predictions", 
      hv_OODPredictionsID);
  SetDictTuple(hv_EvaluationResult.TupleGetDictTuple("evaluated_samples"), "ood_scores", 
      hv_OODScoresID);
  CreateDict(&hv___Tmp_Ctrl_Dict_Init_1);
  SetDictTuple(hv_EvaluationResult, "evaluated_ood_samples", hv___Tmp_Ctrl_Dict_Init_1);
  hv___Tmp_Ctrl_Dict_Init_1 = HTuple::TupleConstant("HNULL");
  GetDictParam(hv_RunningMeasures.TupleGetDictTuple("evaluated_ood_samples"), "key_data_type", 
      "image_ids", &hv___Tmp_Ctrl_Type);
  if (0 != (int(hv___Tmp_Ctrl_Type==HTuple("object"))))
  {
    SetDictObject((hv_RunningMeasures.TupleGetDictTuple("evaluated_ood_samples")).TupleGetDictObject("image_ids"), 
        hv_EvaluationResult.TupleGetDictTuple("evaluated_ood_samples"), "image_ids");
  }
  else
  {
    SetDictTuple(hv_EvaluationResult.TupleGetDictTuple("evaluated_ood_samples"), 
        "image_ids", (hv_RunningMeasures.TupleGetDictTuple("evaluated_ood_samples")).TupleGetDictTuple("image_ids"));
  }
  SetDictTuple(hv_EvaluationResult.TupleGetDictTuple("evaluated_ood_samples"), "ood_predictions", 
      hv_OODPredictionsOOD);
  SetDictTuple(hv_EvaluationResult.TupleGetDictTuple("evaluated_ood_samples"), "ood_scores", 
      hv_OODScoresOOD);
  //
  hv_NumIDSamples = hv_OODScoresID.TupleLength();
  hv_NumOODSamples = hv_OODScoresOOD.TupleLength();
  //
  //Calculate OOD confusion matrix.
  if (0 != hv_CalcOODConfusionMatrix)
  {
    //Ground truth and predictions are inverted as the matrix sorts by 'class_ids' which do not exist in this case.
    //Instead we want "class 1" - OOD - to be on the left column, s.t. TP are in the upper left corner.
    gen_confusion_matrix((HTuple(hv_NumIDSamples,0).TupleConcat(HTuple(hv_NumOODSamples,1))).TupleNot(), 
        (hv_OODPredictionsID.TupleConcat(hv_OODPredictionsOOD)).TupleNot(), "display_matrix", 
        "none", HTuple(), &hv_OODConfusionMatrix);
    GetSizeMatrix(hv_OODConfusionMatrix, &hv_Rows, &hv_Columns);
    if (0 != (HTuple(HTuple(int(hv_NumIDSamples==0)).TupleOr(int(hv_NumOODSamples==0))).TupleAnd(HTuple(int(hv_Rows<2)).TupleOr(int(hv_Columns<2)))))
    {
      //Patch matrix to 2x2 in case only in-distribution or
      //only out-of-distribution data is used for evaluation.
      GetValueMatrix(hv_OODConfusionMatrix, 0, 0, &hv_Value);
      CreateMatrix(2, 2, 0, &hv_OODConfusionMatrix);
      if (0 != (int(hv_NumIDSamples==0)))
      {
        SetValueMatrix(hv_OODConfusionMatrix, 1, 0, hv_NumOODSamples-hv_Value);
        SetValueMatrix(hv_OODConfusionMatrix, 0, 0, hv_Value);
      }
      if (0 != (int(hv_NumOODSamples==0)))
      {
        SetValueMatrix(hv_OODConfusionMatrix, 1, 1, hv_Value);
        SetValueMatrix(hv_OODConfusionMatrix, 0, 1, hv_NumIDSamples-hv_Value);
      }
    }
    SetDictTuple(hv_EvaluationResult, "ood_confusion_matrix", hv_OODConfusionMatrix);
  }
  //
  //Compute the number of true positives. Append zero to the tuple in case it is empty.
  hv_NumTruePositives = (hv_OODPredictionsOOD.TupleConcat(0)).TupleSum();
  //Compute the number of false positives. Append zero to the tuple in case it is empty.
  hv_NumFalsePositives = (hv_OODPredictionsID.TupleConcat(0)).TupleSum();
  //Compute the number of false negatives. Append !zero to the tuple in case it is empty.
  hv_NumFalseNegatives = HTuple((hv_OODPredictionsOOD.TupleConcat(1)).TupleNot()).TupleSum();
  //
  //Calculate OOD detection precision.
  if (0 != hv_CalcOODPrecision)
  {
    hv_NumPredictedPositives = hv_NumTruePositives+hv_NumFalsePositives;
    if (0 != (HTuple(int(hv_NumPredictedPositives>0)).TupleAnd(int(hv_NumOODSamples>0))))
    {
      SetDictTuple(hv_EvaluationResult.TupleGetDictTuple("ood_measures"), "ood_precision", 
          (hv_NumTruePositives.TupleReal())/hv_NumPredictedPositives);
    }
    else
    {
      //No valid precision value can be computed.
      SetDictTuple(hv_EvaluationResult.TupleGetDictTuple("ood_measures"), "ood_precision", 
          -1.0);
    }
  }
  //
  //Calculate OOD detection recall.
  if (0 != hv_CalcOODRecall)
  {
    //Compute the number of true and false positives. Append zero to the tuples in case they are empty.
    if (0 != (int(hv_NumOODSamples>0)))
    {
      SetDictTuple(hv_EvaluationResult.TupleGetDictTuple("ood_measures"), "ood_recall", 
          (hv_NumTruePositives.TupleReal())/hv_NumOODSamples);
    }
    else
    {
      //No valid recall value can be computed.
      SetDictTuple(hv_EvaluationResult.TupleGetDictTuple("ood_measures"), "ood_recall", 
          -1.0);
    }
  }
  //
  //Calculate OOD detection F-Score.
  if (0 != hv_CalcOODFScore)
  {
    if (0 != (int(hv_NumOODSamples>0)))
    {
      SetDictTuple(hv_EvaluationResult.TupleGetDictTuple("ood_measures"), "ood_f_score", 
          (2*hv_NumTruePositives)/(((2.0*hv_NumTruePositives)+hv_NumFalsePositives)+hv_NumFalseNegatives));
    }
    else
    {
      SetDictTuple(hv_EvaluationResult.TupleGetDictTuple("ood_measures"), "ood_f_score", 
          -1.0);
    }
  }
  //
  //Calculate OOD false-positive-rate.
  if (0 != hv_CalcOODFPR)
  {
    if (0 != (int(hv_NumIDSamples>0)))
    {
      SetDictTuple(hv_EvaluationResult.TupleGetDictTuple("ood_measures"), "ood_false_positive_rate", 
          (hv_NumFalsePositives.TupleReal())/hv_NumIDSamples);
    }
    else
    {
      SetDictTuple(hv_EvaluationResult.TupleGetDictTuple("ood_measures"), "ood_false_positive_rate", 
          -1.0);
    }
  }
  //
  //Calculate histograms.
  if (0 != (hv_CalcOODScoreHistogram.TupleOr(hv_CalcOODScoreThresholds)))
  {
    //Calculate histogram for in-distribution images.
    hv_HistoIDXValues = HTuple();
    hv_HistoIDYValues = HTuple();
    if (0 != (int(hv_NumIDSamples!=0)))
    {
      hv_HistoIDXValues = hv_OODScoresID.TupleSort();
      hv_HistoIDYValues = (HTuple::TupleGenSequence(hv_OODScoresID.TupleLength(),1,-1).TupleReal())/hv_NumIDSamples;
    }
    //
    //Calculate histogram for out-of-distribution images.
    hv_HistoOODXValues = HTuple();
    hv_HistoOODYValues = HTuple();
    if (0 != (int(hv_NumOODSamples!=0)))
    {
      hv_HistoOODXValues = hv_OODScoresOOD.TupleSort();
      hv_HistoOODYValues = (HTuple::TupleGenSequence(1,hv_OODScoresOOD.TupleLength(),1).TupleReal())/hv_NumOODSamples;
    }
    //
    //Create dictionary for the score histogram.
    CreateDict(&hv_ScoreHistogram);
    SetDictTuple(hv_ScoreHistogram, "id_x", hv_HistoIDXValues);
    SetDictTuple(hv_ScoreHistogram, "id_y", hv_HistoIDYValues);
    SetDictTuple(hv_ScoreHistogram, "ood_x", hv_HistoOODXValues);
    SetDictTuple(hv_ScoreHistogram, "ood_y", hv_HistoOODYValues);
    //
    //Set the score histogram in the results dictionary.
    if (0 != hv_CalcOODScoreHistogram)
    {
      SetDictTuple(hv_EvaluationResult, "ood_score_histogram", hv_ScoreHistogram);
    }
    //
    CreateDict(&hv___Tmp_Ctrl_Dict_Init_3);
    SetDictTuple(hv_EvaluationResult, "ood_thresholds", hv___Tmp_Ctrl_Dict_Init_3);
    hv___Tmp_Ctrl_Dict_Init_3 = HTuple::TupleConstant("HNULL");
    GetDictParam(hv_EvalParams, "key_exists", "ood_threshold", &hv_ModelThresholdExists);
    if (0 != hv_ModelThresholdExists)
    {
      GetDictParam(hv_EvalParams, "key_data_type", "ood_threshold", &hv___Tmp_Ctrl_Type);
      if (0 != (int(hv___Tmp_Ctrl_Type==HTuple("object"))))
      {
        SetDictObject(hv_EvalParams.TupleGetDictObject("ood_threshold"), hv_EvaluationResult.TupleGetDictTuple("ood_thresholds"), 
            "current_model_threshold");
      }
      else
      {
        SetDictTuple(hv_EvaluationResult.TupleGetDictTuple("ood_thresholds"), "current_model_threshold", 
            hv_EvalParams.TupleGetDictTuple("ood_threshold"));
      }
    }
    else
    {
      throw HException("Cannot find OOD threshold within model.");
    }
    //
    //Calculate suggested thresholds
    if (0 != (int(hv_HistoIDXValues!=HTuple())))
    {
      //We multiply it, otherwise 1 sample would still be a FP
      hv_NoFPThreshold = (hv_HistoIDXValues.TupleMax())*1.000001;
      SetDictTuple(hv_EvaluationResult.TupleGetDictTuple("ood_thresholds"), "no_fp_threshold", 
          hv_NoFPThreshold);
    }
    //
    if (0 != (int(hv_HistoOODXValues!=HTuple())))
    {
      hv_NoFNThreshold = hv_HistoOODXValues.TupleMin();
      SetDictTuple(hv_EvaluationResult.TupleGetDictTuple("ood_thresholds"), "no_fn_threshold", 
          hv_NoFNThreshold);
    }
    //
    if (0 != (HTuple(int(hv_HistoOODXValues!=HTuple())).TupleAnd(int(hv_HistoIDXValues!=HTuple()))))
    {
      hv_OODScores.Clear();
      hv_OODScores.Append(hv_HistoIDXValues);
      hv_OODScores.Append(hv_HistoOODXValues);
      //Get minimum and maximum values of the OOD scores.
      if (0 != (int(hv_NoFPThreshold<=hv_NoFNThreshold)))
      {
        //In this case the ID and OOD samples can be perfectly separated
        //by a threshold.
        hv_MinErrorThreshold = (hv_NoFPThreshold+hv_NoFNThreshold)/2.0;
      }
      else
      {
        //In this case there will be false positives or false negatives
        //for any threshold.
        //
        //Sort the OOD scores.
        hv_OODScoresSortIndices = hv_OODScores.TupleSortIndex();
        hv_OODScoresSorted = HTuple(hv_OODScores[hv_OODScoresSortIndices]);
        //
        //Compute the false positive rates.
        hv_TmpID.Clear();
        hv_TmpID.Append(HTuple(hv_HistoIDXValues.TupleLength(),1.0));
        hv_TmpID.Append(HTuple(hv_HistoOODXValues.TupleLength(),0.0));
        hv_TmpIDSorted = HTuple(hv_TmpID[hv_OODScoresSortIndices]);
        hv_TrueNegativesPerScore = (hv_TmpIDSorted.TupleCumul())-hv_TmpIDSorted;
        hv_FPRate = 1.0-(hv_TrueNegativesPerScore/(hv_HistoIDXValues.TupleLength()));
        //
        //Compute the false negative rates.
        hv_TmpOOD.Clear();
        hv_TmpOOD.Append(HTuple(hv_HistoIDXValues.TupleLength(),0.0));
        hv_TmpOOD.Append(HTuple(hv_HistoOODXValues.TupleLength(),1.0));
        hv_TmpOODSorted = HTuple(hv_TmpOOD[hv_OODScoresSortIndices]);
        hv_FalseNegativesPerScore = (hv_TmpOODSorted.TupleCumul())-hv_TmpOODSorted;
        hv_FNRate = hv_FalseNegativesPerScore/(hv_HistoOODXValues.TupleLength());
        //
        //Get the threshold for which the sum of the false positive
        //and false negative rates is the lowest.
        hv_FprFnrSum = hv_FPRate+hv_FNRate;
        hv_MinFprFnRSum = hv_FprFnrSum.TupleMin();
        hv_ThresholdIndex = hv_FprFnrSum.TupleFindFirst(hv_MinFprFnRSum);
        hv_MinErrorThreshold = HTuple(hv_OODScoresSorted[hv_ThresholdIndex]);
        //
        //In some cases MinErrorThreshold may be smaller than NoFNThreshold.
        //We set it to at least that value.
        hv_MinErrorThreshold = hv_MinErrorThreshold.TupleMax2(hv_NoFNThreshold);
      }
      SetDictTuple(hv_EvaluationResult.TupleGetDictTuple("ood_thresholds"), "min_error_threshold", 
          hv_MinErrorThreshold);
    }
    //
  }
  return;
}

// Chapter: Deep Learning / Semantic Segmentation and Edge Extraction
// Short Description: Calculate pixel measures based on RunningMeasures. 
void calculate_pixel_measures (HTuple hv_RunningMeasures, HTuple hv_EvalParams, HTuple *hv_EvaluationResult)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_CalcClassPixelAccuracy, hv_CalcPixelAccuracy;
  HTuple  hv_CalcPixelConfusionMatrix, hv_CalcMeanAccuracy;
  HTuple  hv_CalcMeanPrecision, hv_CalcMeanIou, hv_CalcClassIou;
  HTuple  hv_CalcFWIou, hv_Measures, hv_EvaluationType, hv_PixelMeasures;
  HTuple  hv_M, hv_ConfMatrix, hv_TPMat, hv_TP, hv_SumRowMat;
  HTuple  hv_RowSum, hv_FP, hv_SumColMat, hv_ColSum, hv_FN;
  HTuple  hv_IgnoreClassIDs, hv_Rows, hv_Columns, hv_FPIgnore;
  HTuple  hv_GT, hv_ClsIdxValid, hv_ClassPixelAccuracy, hv_MeanAccuracy;
  HTuple  hv_PixelAccuracy, hv_PD, hv_PDIdxValid, hv_ClassPixelPrecision;
  HTuple  hv_MeanPrecision, hv_ClassIoU, hv_MeanIoU, hv_FWIoU;
  HTuple  hv_FwWeights;

  //
  //This procedure calculates the pixel-wise measures based on the values in running measures.
  //
  //Set default values.
  hv_CalcClassPixelAccuracy = 0;
  hv_CalcPixelAccuracy = 0;
  hv_CalcPixelConfusionMatrix = 0;
  hv_CalcMeanAccuracy = 0;
  hv_CalcMeanPrecision = 0;
  hv_CalcMeanIou = 0;
  hv_CalcClassIou = 0;
  hv_CalcFWIou = 0;
  CreateDict(&(*hv_EvaluationResult));
  //
  //Check which measures are to be calculated.
  GetDictTuple(hv_EvalParams, "measures", &hv_Measures);
  GetDictTuple(hv_EvalParams, "evaluation_type", &hv_EvaluationType);
  get_requested_pixel_measures(hv_Measures, hv_EvaluationType, &hv_PixelMeasures);
  if (0 != (int((hv_PixelMeasures.TupleLength())==0)))
  {
    return;
  }
  //
  {
  HTuple end_val22 = (hv_PixelMeasures.TupleLength())-1;
  HTuple step_val22 = 1;
  for (hv_M=0; hv_M.Continue(end_val22, step_val22); hv_M += step_val22)
  {
    if (0 != (int(HTuple(hv_PixelMeasures[hv_M])==HTuple("pixel_accuracy"))))
    {
      hv_CalcPixelAccuracy = 1;
    }
    else if (0 != (int(HTuple(hv_PixelMeasures[hv_M])==HTuple("class_pixel_accuracy"))))
    {
      hv_CalcClassPixelAccuracy = 1;
    }
    else if (0 != (int(HTuple(hv_PixelMeasures[hv_M])==HTuple("pixel_confusion_matrix"))))
    {
      hv_CalcPixelConfusionMatrix = 1;
    }
    else if (0 != (int(HTuple(hv_PixelMeasures[hv_M])==HTuple("mean_accuracy"))))
    {
      hv_CalcMeanAccuracy = 1;
    }
    else if (0 != (int(HTuple(hv_PixelMeasures[hv_M])==HTuple("mean_precision"))))
    {
      hv_CalcMeanPrecision = 1;
    }
    else if (0 != (int(HTuple(hv_PixelMeasures[hv_M])==HTuple("mean_iou"))))
    {
      hv_CalcMeanIou = 1;
    }
    else if (0 != (int(HTuple(hv_PixelMeasures[hv_M])==HTuple("class_iou"))))
    {
      hv_CalcClassIou = 1;
    }
    else if (0 != (int(HTuple(hv_PixelMeasures[hv_M])==HTuple("frequency_weighted_iou"))))
    {
      hv_CalcFWIou = 1;
    }
    else
    {
      throw HException("Unknown pixel measure: "+HTuple(hv_PixelMeasures[hv_M]));
    }
  }
  }
  //
  //Depending on the running measure values (ConfusionMatrix or TP/FP/FN),
  //we first calculate TP/FP/FN from the ConfusionMatrix.
  if (0 != hv_CalcPixelConfusionMatrix)
  {
    //Get the running measures.
    GetDictTuple(hv_RunningMeasures, "pixel_confusion_matrix", &hv_ConfMatrix);
    //Get the per-class true positives as the diagonal of the matrix.
    GetDiagonalMatrix(hv_ConfMatrix, 0, &hv_TPMat);
    GetFullMatrix(hv_TPMat, &hv_TP);
    //For the confusion matrix, the row determines the predicted class-IDs,
    //the column determines the ground truth class-IDs.
    //Get the per-class false positives (FP) as the sum over the rows minus the diagonal (TP).
    SumMatrix(hv_ConfMatrix, "rows", &hv_SumRowMat);
    GetFullMatrix(hv_SumRowMat, &hv_RowSum);
    hv_FP = hv_RowSum-hv_TP;
    //Get the per-class false negatives (FN) as the sum over the columns minus the diagonal (TP).
    SumMatrix(hv_ConfMatrix, "columns", &hv_SumColMat);
    GetFullMatrix(hv_SumColMat, &hv_ColSum);
    hv_FN = hv_ColSum-hv_TP;
    //We do not want to count the false positives (FP) in the ignore region.
    //The false negatives (FN) are not affected, since the model does not predict the ignore class.
    GetDictTuple(hv_EvalParams, "ignore_class_ids", &hv_IgnoreClassIDs);
    if (0 != (int((hv_IgnoreClassIDs.TupleLength())>0)))
    {
      //The ignore class corresponds to the last row/column in the confusion matrix.
      GetSizeMatrix(hv_ConfMatrix, &hv_Rows, &hv_Columns);
      GetValueMatrix(hv_ConfMatrix, HTuple::TupleGenSequence(0,hv_Rows-1,1), HTuple(hv_Rows,hv_Columns-1), 
          &hv_FPIgnore);
      hv_FP = hv_FP-hv_FPIgnore;
      //Remove last entries of TP, FP, FN (those related to the ignore class).
      hv_TP = hv_TP.TupleSelectRange(0,(hv_TP.TupleLength())-2);
      hv_FP = hv_FP.TupleSelectRange(0,(hv_FP.TupleLength())-2);
      hv_FN = hv_FN.TupleSelectRange(0,(hv_FN.TupleLength())-2);
      //Remove last row/column from confusion matrix.
      GetSubMatrix(hv_ConfMatrix, 0, 0, hv_Rows-1, hv_Columns-1, &hv_ConfMatrix);
    }
    //Paste the confusion matrix to the output.
    SetDictTuple((*hv_EvaluationResult), "pixel_confusion_matrix", hv_ConfMatrix);
  }
  else
  {
    //Get the running measure values.
    GetDictTuple(hv_RunningMeasures, "tp", &hv_TP);
    GetDictTuple(hv_RunningMeasures, "fp", &hv_FP);
    GetDictTuple(hv_RunningMeasures, "fn", &hv_FN);
  }
  //
  //It might be the case, that some of the classes are not present in the set of validation images.
  //--> Exclude these classes (they are indirectly present as they reduce the number of TP for other classes).
  hv_GT = hv_TP+hv_FN;
  hv_ClsIdxValid = (hv_GT.TupleGreaterElem(0)).TupleFind(1);
  //
  //Mean Accuracy, Class Pixel Accuracy.
  //-> If one of 'mean_accuracy', 'class_pixel_accuracy' is specified, we give back both of them
  //   as they have to be calculated anyway (to the most part).
  if (0 != (hv_CalcClassPixelAccuracy.TupleOr(hv_CalcMeanAccuracy)))
  {
    //Compute pixel accuracy per class (although we might only use it for the overall pixel accuracy).
    hv_ClassPixelAccuracy = HTuple(hv_GT.TupleLength(),-1);
    hv_MeanAccuracy = -1;
    if (0 != (int(HTuple(hv_ClsIdxValid[0])>-1)))
    {
      hv_ClassPixelAccuracy[hv_ClsIdxValid] = (HTuple(hv_TP[hv_ClsIdxValid]).TupleReal())/HTuple(hv_GT[hv_ClsIdxValid]);
      hv_MeanAccuracy = HTuple(hv_ClassPixelAccuracy[hv_ClsIdxValid]).TupleMean();
    }
    SetDictTuple((*hv_EvaluationResult), "class_pixel_accuracy", hv_ClassPixelAccuracy);
    SetDictTuple((*hv_EvaluationResult), "mean_accuracy", hv_MeanAccuracy);
  }
  //Pixel Accuracy.
  if (0 != hv_CalcPixelAccuracy)
  {
    //Compute pixel accuracy as the total ratio of pixels that have been correctly predicted.
    hv_PixelAccuracy = -1;
    if (0 != (int(HTuple(hv_ClsIdxValid[0])>-1)))
    {
      hv_PixelAccuracy = ((HTuple(hv_TP[hv_ClsIdxValid]).TupleSum()).TupleReal())/(HTuple(hv_GT[hv_ClsIdxValid]).TupleSum());
    }
    SetDictTuple((*hv_EvaluationResult), "pixel_accuracy", hv_PixelAccuracy);
  }
  //Mean Precision.
  //-> Also includes precisions for each of the classes which are
  //   used to calculate the mean precision.
  if (0 != hv_CalcMeanPrecision)
  {
    //Compute pixel-level precision averaged over all classes.
    hv_PD = hv_TP+hv_FP;
    hv_PDIdxValid = (hv_PD.TupleGreaterElem(0.0)).TupleFind(1);
    hv_ClassPixelPrecision = HTuple(hv_PD.TupleLength(),-1);
    hv_MeanPrecision = -1;
    if (0 != (int(HTuple(hv_PDIdxValid[0])>-1)))
    {
      hv_ClassPixelPrecision[hv_PDIdxValid] = (HTuple(hv_TP[hv_PDIdxValid]).TupleReal())/HTuple(hv_PD[hv_PDIdxValid]);
      hv_MeanPrecision = HTuple(hv_ClassPixelPrecision[hv_PDIdxValid]).TupleMean();
    }
    SetDictTuple((*hv_EvaluationResult), "mean_precision", hv_MeanPrecision);
  }
  //Mean IoU, class IoU, frequency weighted IoU:
  //-> If the measures 'class_iou', 'mean_iou' or 'frequency_weighted_iou' is specified,
  //   we return all three of them as they have to be calculated anyway (to the most part).
  if (0 != (HTuple(hv_CalcMeanIou.TupleOr(hv_CalcClassIou)).TupleOr(hv_CalcFWIou)))
  {
    hv_ClassIoU = HTuple(hv_GT.TupleLength(),-1);
    hv_MeanIoU = -1;
    hv_FWIoU = -1;
    if (0 != (int(HTuple(hv_ClsIdxValid[0])>-1)))
    {
      hv_ClassIoU[hv_ClsIdxValid] = (HTuple(hv_TP[hv_ClsIdxValid]).TupleReal())/(HTuple(hv_GT[hv_ClsIdxValid])+HTuple(hv_FP[hv_ClsIdxValid]));
      hv_MeanIoU = HTuple(hv_ClassIoU[hv_ClsIdxValid]).TupleMean();
      hv_FwWeights = (hv_GT.TupleReal())/(hv_GT.TupleSum());
      hv_FWIoU = (HTuple(hv_FwWeights[hv_ClsIdxValid])*HTuple(hv_ClassIoU[hv_ClsIdxValid])).TupleSum();
    }
    SetDictTuple((*hv_EvaluationResult), "class_iou", hv_ClassIoU);
    SetDictTuple((*hv_EvaluationResult), "mean_iou", hv_MeanIoU);
    SetDictTuple((*hv_EvaluationResult), "frequency_weighted_iou", hv_FWIoU);
  }
  //
  return;
}

// Chapter: Deep Learning / Model
// Short Description: Calculate region measures based on running measure values. 
void calculate_region_measures (HTuple hv_RunningMeasures, HTuple hv_EvalParams, 
    HTuple *hv_EvaluationResult)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_CalcMeanPRO, hv_Measures, hv_M, hv_ClsIdxValid;
  HTuple  hv_ClassPRO, hv_MeanPRO;

  //
  //This procedure calculates the region measures based on the
  //values in running measures.
  //
  //Set default values.
  hv_CalcMeanPRO = 0;
  CreateDict(&(*hv_EvaluationResult));
  //
  //Check which measures are to be calculated.
  GetDictTuple(hv_EvalParams, "measures", &hv_Measures);
  {
  HTuple end_val10 = (hv_Measures.TupleLength())-1;
  HTuple step_val10 = 1;
  for (hv_M=0; hv_M.Continue(end_val10, step_val10); hv_M += step_val10)
  {
    if (0 != (int(HTuple(hv_Measures[hv_M])==HTuple("mean_pro"))))
    {
      hv_CalcMeanPRO = 1;
    }
    else if (0 != (int(HTuple(hv_Measures[hv_M])==HTuple("all"))))
    {
      hv_CalcMeanPRO = 1;
    }
  }
  }
  //
  if (0 != hv_CalcMeanPRO)
  {
    //It might be the case, that some of the classes are not present
    //in the set of evaluation images and are excluded.
    hv_ClsIdxValid = ((hv_RunningMeasures.TupleGetDictTuple("num_gt_regions")).TupleGreaterElem(0)).TupleFind(1);
    //
    //Compute per-region-overlap averaged over the valid classes.
    hv_ClassPRO = HTuple((hv_RunningMeasures.TupleGetDictTuple("num_gt_regions")).TupleLength(),-1);
    hv_MeanPRO = -1;
    if (0 != (int(HTuple(hv_ClsIdxValid[0])>-1)))
    {
      hv_ClassPRO[hv_ClsIdxValid] = HTuple((hv_RunningMeasures.TupleGetDictTuple("gt_overlap"))[hv_ClsIdxValid])/(HTuple((hv_RunningMeasures.TupleGetDictTuple("num_gt_regions"))[hv_ClsIdxValid]).TupleReal());
      hv_MeanPRO = HTuple(hv_ClassPRO[hv_ClsIdxValid]).TupleMean();
    }
    SetDictTuple((*hv_EvaluationResult), "mean_pro", hv_MeanPRO);
  }
  //
  return;
}

// Chapter: 3D Matching / 3D Gripping Point Detection
// Short Description: Calculate 3D gripping point measures based on RunningMeasures. 
void calculate_running_gripping_point_measures (HTuple hv_RunningMeasures, HTuple hv_EvalParams, 
    HTuple *hv_EvaluationResult)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_Positives, hv_GT, hv_Precision, hv_Recall;
  HTuple  hv_SumPrecisionRecall, hv_FScore;

  CreateDict(&(*hv_EvaluationResult));
  if (0 != (int((HTuple((hv_EvalParams.TupleGetDictTuple("measures")).TupleRegexpSelect("gripping_point_.*|all")).TupleLength())>0)))
  {
    hv_Positives = (hv_RunningMeasures.TupleGetDictTuple("gp_tp"))+(hv_RunningMeasures.TupleGetDictTuple("gp_fp"));
    hv_GT = (hv_RunningMeasures.TupleGetDictTuple("gp_tp"))+(hv_RunningMeasures.TupleGetDictTuple("gp_fn"));
    if (0 != (int(hv_Positives>0.0)))
    {
      hv_Precision = (hv_RunningMeasures.TupleGetDictTuple("gp_tp"))/hv_Positives;
    }
    else
    {
      hv_Precision = 0.0;
    }
    if (0 != (int(hv_GT>0.0)))
    {
      hv_Recall = (hv_RunningMeasures.TupleGetDictTuple("gp_tp"))/hv_GT;
    }
    else
    {
      hv_Recall = 0.0;
    }
    hv_SumPrecisionRecall = hv_Precision+hv_Recall;
    if (0 != (int(hv_SumPrecisionRecall>0.0)))
    {
      hv_FScore = ((2*hv_Precision)*hv_Recall)/hv_SumPrecisionRecall;
    }
    else
    {
      hv_FScore = 0.0;
    }
    if (0 != (int((HTuple((hv_EvalParams.TupleGetDictTuple("measures")).TupleRegexpSelect("gripping_point_precision|all")).TupleLength())>0)))
    {
      SetDictTuple((*hv_EvaluationResult), "gripping_point_precision", hv_Precision);
    }
    if (0 != (int((HTuple((hv_EvalParams.TupleGetDictTuple("measures")).TupleRegexpSelect("gripping_point_recall|all")).TupleLength())>0)))
    {
      SetDictTuple((*hv_EvaluationResult), "gripping_point_recall", hv_Recall);
    }
    if (0 != (int((HTuple((hv_EvalParams.TupleGetDictTuple("measures")).TupleRegexpSelect("gripping_point_f_score|all")).TupleLength())>0)))
    {
      SetDictTuple((*hv_EvaluationResult), "gripping_point_f_score", hv_FScore);
    }
  }
  return;
}

// Chapter: Transformations / Poses
// Short Description: Calculate the poses to grasp an object. 
void calculate_tool_in_base_robot_path_poses (HTupleVector/*{eTupleVector,Dim=1}*/ hvec_ToolInModelRobotPathPoses, 
    HTuple hv_ModelInBasePose, HTuple hv_Poses, HTupleVector/*{eTupleVector,Dim=1}*/ *hvec_ToolInBaseRobotPathPoses)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_Index1, hv_ToolInBaseRobotPathPose;

  {
  HTuple end_val0 = HTuple(hvec_ToolInModelRobotPathPoses.Length())-1;
  HTuple step_val0 = 1;
  for (hv_Index1=0; hv_Index1.Continue(end_val0, step_val0); hv_Index1 += step_val0)
  {
    PoseCompose(hv_ModelInBasePose, hvec_ToolInModelRobotPathPoses[hv_Index1].T(), 
        &hv_ToolInBaseRobotPathPose);
    ConvertPoseType(hv_ToolInBaseRobotPathPose, hv_Poses.TupleGetDictTuple("OrderOfTransform"), 
        hv_Poses.TupleGetDictTuple("OrderOfRotation"), hv_Poses.TupleGetDictTuple("ViewOfTransform"), 
        &hv_ToolInBaseRobotPathPose);
    (*hvec_ToolInBaseRobotPathPoses)[hv_Index1] = HTupleVector(hv_ToolInBaseRobotPathPose);
  }
  }
  return;
}

// Chapter: Calibration / Monocular
// Short Description: Calibrate a camera with a single image. 
void calibrate_camera_and_plane_single_image (HTuple hv_CalibObjectData)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_StartCamParam, hv_CalibDataID, hv_ErrorCamCalibInPixel;
  HTuple  hv_CamParam, hv_PlaneInCamPose0, hv_PlaneInCamPose;

  hv_StartCamParam = hv_CalibObjectData.TupleGetDictTuple("StartCamParam");
  //
  //Check input
  if (0 != (HTuple(hv_StartCamParam[0]).TupleRegexpTest("line_scan")))
  {
    throw HException("Line scan cameras are not supported");
  }
  //
  //Create a HALCON calibration data model.
  CreateCalibData("calibration_object", 1, 1, &hv_CalibDataID);
  //Set the needed calibration information.
  SetCalibDataCamParam(hv_CalibDataID, 0, HTuple(), hv_StartCamParam);
  SetCalibDataCalibObject(hv_CalibDataID, 0, hv_CalibObjectData.TupleGetDictTuple("CalPlateDescr"));
  //Find the calibration plate.
  FindCalibObject(hv_CalibObjectData.TupleGetDictObject("ImageCaltab"), hv_CalibDataID, 
      0, 0, 0, HTuple(), HTuple());
  //Calibrating from only one view requires some parameter to be excluded
  //from the optimization.
  SetCalibData(hv_CalibDataID, "camera", 0, "excluded_settings", "focus");
  //Calibrate the camera.
  CalibrateCameras(hv_CalibDataID, &hv_ErrorCamCalibInPixel);
  //Get the calibration results.
  GetCalibData(hv_CalibDataID, "camera", 0, "params", &hv_CamParam);
  GetCalibData(hv_CalibDataID, "calib_obj_pose", (HTuple(0).Append(0)), "pose", &hv_PlaneInCamPose0);
  SetOriginPose(hv_PlaneInCamPose0, 0, 0, hv_CalibObjectData.TupleGetDictTuple("CalPlateThickness"), 
      &hv_PlaneInCamPose);
  //Convert pose to standard pose type.
  ConvertPoseType(hv_PlaneInCamPose, "Rp+T", "gba", "point", &hv_PlaneInCamPose);
  //
  //Add data to output dict.
  SetDictTuple(hv_CalibObjectData, "ErrorCamCalibInPixel", hv_ErrorCamCalibInPixel);
  SetDictTuple(hv_CalibObjectData, "CamParam", hv_CamParam);
  SetDictTuple(hv_CalibObjectData, "PlaneInCamPose", hv_PlaneInCamPose);
  //Clean up.
  ClearCalibData(hv_CalibDataID);
  return;
}

// Chapter: Calibration / Hand-Eye
// Short Description: Perform a hand-eye calibration with a stationary camera. 
void calibrate_hand_eye_stationary_cam_approx (HTuple hv_RobotTouchingPointInToolCoordinates, 
    HTuple hv_RowsTouchingPointInPlane, HTuple hv_ColumnsTouchingPointInPlane, HTupleVector/*{eTupleVector,Dim=1}*/ hvec_ToolInBasePoses, 
    HTuple hv_CalibObjectData, HTuple *hv_HandEyeCalibData)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_CamParam, hv_CalPlateThickness, hv_PlaneInCamPose;
  HTuple  hv_OrderOfTransform0, hv_OrderOfRotation0, hv_ViewOfTransform0;
  HTuple  hv_Index, hv_OrderOfTransform, hv_OrderOfRotation;
  HTuple  hv_ViewOfTransform, hv_TouchingPointInToolPose;
  HTuple  hv_XBase, hv_YBase, hv_ZBase, hv_TouchingPointInBasePose;
  HTuple  hv_XPlane, hv_YPlane, hv_ZPlane, hv_HomMat3DPlaneToBase;
  HTuple  hv_PlaneInBasePose, hv_BaseInPlanePose, hv_BaseInCamPose;
  HTuple  hv_XPlaneBase, hv_YPlaneBase, hv_ZPlaneBase, hv_DiffX;
  HTuple  hv_DiffY, hv_DiffZ, hv_SqrDiff, hv_PlanePointsRMS;
  HTuple  hv_PlanePointsMaxDiff;

  //
  hv_CamParam = hv_CalibObjectData.TupleGetDictTuple("CamParam");
  hv_CalPlateThickness = hv_CalibObjectData.TupleGetDictTuple("CalPlateThickness");
  hv_PlaneInCamPose = hv_CalibObjectData.TupleGetDictTuple("PlaneInCamPose");
  //
  //Check input
  if (0 != (HTuple(HTuple(int((hv_RowsTouchingPointInPlane.TupleLength())<3)).TupleOr(int((hv_ColumnsTouchingPointInPlane.TupleLength())<3))).TupleOr(int(HTuple(hvec_ToolInBasePoses.Length())<3))))
  {
    throw HException("Please specify at least three image coordinates and robot poses.");
  }
  if (0 != (HTuple(int((hv_RowsTouchingPointInPlane.TupleLength())!=(hv_ColumnsTouchingPointInPlane.TupleLength()))).TupleOr(int((hv_RowsTouchingPointInPlane.TupleLength())!=HTuple(hvec_ToolInBasePoses.Length())))))
  {
    throw HException("The number of image coordinates and robot poses have to be equal.");
  }
  if (0 != (HTuple(hv_CamParam[0]).TupleRegexpTest("line_scan")))
  {
    throw HException("Line scan cameras are not supported");
  }
  //
  //If points on top of the calibration plate are approached, we have to adapt the PlaneInCamPose accordingly.
  SetOriginPose(hv_PlaneInCamPose, 0, 0, -hv_CalPlateThickness, &hv_PlaneInCamPose);
  //Keep track of the pose type used by the robot.
  GetPoseType(hvec_ToolInBasePoses[0].T(), &hv_OrderOfTransform0, &hv_OrderOfRotation0, 
      &hv_ViewOfTransform0);
  {
  HTuple ExpTmpOutVar_0;
  ConvertPoseType(hvec_ToolInBasePoses[0].T(), "Rp+T", "gba", "point", &ExpTmpOutVar_0);
  hvec_ToolInBasePoses[0].T() = ExpTmpOutVar_0;
  }
  {
  HTuple end_val21 = HTuple(hvec_ToolInBasePoses.Length())-1;
  HTuple step_val21 = 1;
  for (hv_Index=1; hv_Index.Continue(end_val21, step_val21); hv_Index += step_val21)
  {
    GetPoseType(hvec_ToolInBasePoses[hv_Index].T(), &hv_OrderOfTransform, &hv_OrderOfRotation, 
        &hv_ViewOfTransform);
    if (0 != (HTuple(HTuple(int(hv_OrderOfTransform0!=hv_OrderOfTransform)).TupleOr(int(hv_OrderOfRotation0!=hv_OrderOfRotation))).TupleOr(int(hv_ViewOfTransform0!=hv_ViewOfTransform))))
    {
      throw HException("ToolInBasePoses have different pose types.");
    }
    //Convert to default pose type.
    {
    HTuple ExpTmpOutVar_0;
    ConvertPoseType(hvec_ToolInBasePoses[hv_Index].T(), "Rp+T", "gba", "point", &ExpTmpOutVar_0);
    hvec_ToolInBasePoses[hv_Index].T() = ExpTmpOutVar_0;
    }
  }
  }
  //
  //Collect the robot translations.
  CreatePose(HTuple(hv_RobotTouchingPointInToolCoordinates[0]), HTuple(hv_RobotTouchingPointInToolCoordinates[1]), 
      HTuple(hv_RobotTouchingPointInToolCoordinates[2]), 0, 0, 0, "Rp+T", "gba", 
      "point", &hv_TouchingPointInToolPose);
  hv_XBase = HTuple();
  hv_YBase = HTuple();
  hv_ZBase = HTuple();
  {
  HTuple end_val35 = (hv_RowsTouchingPointInPlane.TupleLength())-1;
  HTuple step_val35 = 1;
  for (hv_Index=0; hv_Index.Continue(end_val35, step_val35); hv_Index += step_val35)
  {
    PoseCompose(hvec_ToolInBasePoses[hv_Index].T(), hv_TouchingPointInToolPose, &hv_TouchingPointInBasePose);
    hv_XBase = hv_XBase.TupleConcat(HTuple(hv_TouchingPointInBasePose[0]));
    hv_YBase = hv_YBase.TupleConcat(HTuple(hv_TouchingPointInBasePose[1]));
    hv_ZBase = hv_ZBase.TupleConcat(HTuple(hv_TouchingPointInBasePose[2]));
  }
  }
  //
  //Get the plane coordinates of the input image points.
  ImagePointsToWorldPlane(hv_CamParam, hv_PlaneInCamPose, hv_RowsTouchingPointInPlane, 
      hv_ColumnsTouchingPointInPlane, "m", &hv_XPlane, &hv_YPlane);
  TupleGenConst(hv_XPlane.TupleLength(), 0, &hv_ZPlane);
  VectorToHomMat3d("rigid", hv_XPlane, hv_YPlane, hv_ZPlane, hv_XBase, hv_YBase, 
      hv_ZBase, &hv_HomMat3DPlaneToBase);
  HomMat3dToPose(hv_HomMat3DPlaneToBase, &hv_PlaneInBasePose);
  //If points on top of the calibration plate are approached, we have to readapt the Plane accordingly.
  SetOriginPose(hv_PlaneInCamPose, 0, 0, hv_CalPlateThickness, &hv_PlaneInCamPose);
  SetOriginPose(hv_PlaneInBasePose, 0, 0, hv_CalPlateThickness, &hv_PlaneInBasePose);
  PoseInvert(hv_PlaneInBasePose, &hv_BaseInPlanePose);
  PoseCompose(hv_PlaneInCamPose, hv_BaseInPlanePose, &hv_BaseInCamPose);
  //
  //Get the BaseInCamPose.
  PoseInvert(hv_PlaneInBasePose, &hv_BaseInPlanePose);
  PoseCompose(hv_PlaneInCamPose, hv_BaseInPlanePose, &hv_BaseInCamPose);
  //Convert to output pose type.
  ConvertPoseType(hv_BaseInCamPose, hv_OrderOfTransform0, hv_OrderOfRotation0, hv_ViewOfTransform0, 
      &hv_BaseInCamPose);
  ConvertPoseType(hv_PlaneInBasePose, hv_OrderOfTransform0, hv_OrderOfRotation0, 
      hv_ViewOfTransform0, &hv_PlaneInBasePose);

  //Get the difference of the points in the plane as seen by the camera
  //to the points in the plane as approached by the robot.
  AffineTransPoint3d(hv_HomMat3DPlaneToBase, hv_XPlane, hv_YPlane, hv_ZPlane, &hv_XPlaneBase, 
      &hv_YPlaneBase, &hv_ZPlaneBase);
  hv_DiffX = hv_XPlaneBase-hv_XBase;
  hv_DiffY = hv_YPlaneBase-hv_YBase;
  hv_DiffZ = hv_ZPlaneBase-hv_ZBase;
  hv_SqrDiff = ((hv_DiffX*hv_DiffX)+(hv_DiffY*hv_DiffY))+(hv_DiffZ*hv_DiffZ);
  hv_PlanePointsRMS = ((hv_SqrDiff.TupleSum())/(hv_DiffX.TupleLength())).TupleSqrt();
  hv_PlanePointsMaxDiff = (hv_SqrDiff.TupleSqrt()).TupleMax();
  //
  //Create output dict.
  CreateDict(&(*hv_HandEyeCalibData));
  SetDictTuple((*hv_HandEyeCalibData), "CamParam", hv_CamParam);
  SetDictTuple((*hv_HandEyeCalibData), "BaseInCamPose", hv_BaseInCamPose);
  SetDictTuple((*hv_HandEyeCalibData), "PlaneInBasePose", hv_PlaneInBasePose);
  SetDictTuple((*hv_HandEyeCalibData), "PlaneInCamPose0", hv_PlaneInCamPose);
  SetDictTuple((*hv_HandEyeCalibData), "PlanePointsRMS", hv_PlanePointsRMS);
  SetDictTuple((*hv_HandEyeCalibData), "PlanePointsMaxDiff", hv_PlanePointsMaxDiff);
  return;
}

// Chapter: Calibration / Hand-Eye
// Short Description: Perform a hand-eye calibration with a stationary camera. 
void calibrate_hand_eye_stationary_cam_approx_without_calib_plate (HTuple hv_RowsTouchingPointInPlane, 
    HTuple hv_ColumnsTouchingPointInPlane, HTupleVector/*{eTupleVector,Dim=1}*/ hvec_ToolInBasePoses, 
    HTuple hv_RobotTouchingPointInToolCoordinates, HTuple hv_DistanceObjectTouchingPointToPlane, 
    HTuple hv_DistancePlaneToCamera, HTuple hv_Width, HTuple hv_Height, HTuple *hv_HandEyeCalibData)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_OrderOfTransform0, hv_OrderOfRotation0;
  HTuple  hv_ViewOfTransform0, hv_Index, hv_OrderOfTransform;
  HTuple  hv_OrderOfRotation, hv_ViewOfTransform, hv_RobotTouchingPointToToolXYZPose;
  HTuple  hv_XBase, hv_YBase, hv_ZBase, hv_TouchingPointInBasePose;
  HTuple  hv_OM3DPlanePoints, hv_OM3DPlane, hv_TouchingPointPlaneInBasePose;
  HTuple  hv_FocusOrig, hv_DiffRow, hv_DiffCol, hv_DistPixel;
  HTuple  hv_DiffX, hv_DiffY, hv_DiffZ, hv_DistWorld, hv_Quotient;
  HTuple  hv_SX, hv_SY, hv_FocusShift, hv_BestIndex, hv_ErrorBasePoseInPixel;
  HTuple  hv_NumFocus, hv_Focus, hv_CamParam0, hv_BaseInCamPose0;
  HTuple  hv_ErrorBasePoseInPixelTmp, hv_BaseInCamPose, hv_CamParam;
  HTuple  hv_TouchingPointPlaneInCamPose, hv_TouchingPointPlaneInCamPose0Rot;
  HTuple  hv_HomMat3D, hv_Qx, hv_Qy, hv_CosAngleBetweenZAxis;
  HTuple  hv_SwitchZDirection, hv_TouchingPointPlaneInCamPose1;
  HTuple  hv_CamInBasePose, hv_TouchingPointPlanePointsCamX;
  HTuple  hv_TouchingPointPlanePointsCamY, hv_TouchingPointPlanePointsCamZ;
  HTuple  hv_BaseInTouchingPointPlanePose, hv_HomMat3D1, hv_TouchingPointPlanePointsToolX;
  HTuple  hv_TouchingPointPlanePointsToolY, hv_TouchingPointPlanePointsToolZ;
  HTuple  hv_SqrDiff, hv_PlanePointsRMS, hv_PlanePointsMaxDiff;
  HTuple  hv_PlaneInBasePose, hv_PlaneInCamPose;

  //Check input.
  if (0 != (HTuple(HTuple(int((hv_RowsTouchingPointInPlane.TupleLength())<4)).TupleOr(int((hv_ColumnsTouchingPointInPlane.TupleLength())<4))).TupleOr(int(HTuple(hvec_ToolInBasePoses.Length())<4))))
  {
    throw HException("Please specify at least four image coordinates and robot poses.");
  }
  if (0 != (HTuple(int((hv_RowsTouchingPointInPlane.TupleLength())!=(hv_ColumnsTouchingPointInPlane.TupleLength()))).TupleOr(int((hv_RowsTouchingPointInPlane.TupleLength())!=HTuple(hvec_ToolInBasePoses.Length())))))
  {
    throw HException("The number of image coordinates and robot poses have to be equal.");
  }
  if (0 != (HTuple(int(hv_Width<=0)).TupleOr(int(hv_Height<=0))))
  {
    throw HException("Width or Height must be greater than 0.");
  }
  if (0 != (int(hv_DistancePlaneToCamera<=0)))
  {
    throw HException("DistancePlaneToCamera must be greater than 0.");
  }
  if (0 != (int(hv_DistancePlaneToCamera<=0)))
  {
    throw HException("DistanceObjectTouchingPointToPlane must be greater than 0.");
  }
  //
  //Keep track of the pose type used by the robot.
  GetPoseType(hvec_ToolInBasePoses[0].T(), &hv_OrderOfTransform0, &hv_OrderOfRotation0, 
      &hv_ViewOfTransform0);
  {
  HTuple ExpTmpOutVar_0;
  ConvertPoseType(hvec_ToolInBasePoses[0].T(), "Rp+T", "gba", "point", &ExpTmpOutVar_0);
  hvec_ToolInBasePoses[0].T() = ExpTmpOutVar_0;
  }
  {
  HTuple end_val20 = HTuple(hvec_ToolInBasePoses.Length())-1;
  HTuple step_val20 = 1;
  for (hv_Index=1; hv_Index.Continue(end_val20, step_val20); hv_Index += step_val20)
  {
    GetPoseType(hvec_ToolInBasePoses[hv_Index].T(), &hv_OrderOfTransform, &hv_OrderOfRotation, 
        &hv_ViewOfTransform);
    if (0 != (HTuple(HTuple(int(hv_OrderOfTransform0!=hv_OrderOfTransform)).TupleOr(int(hv_OrderOfRotation0!=hv_OrderOfRotation))).TupleOr(int(hv_ViewOfTransform0!=hv_ViewOfTransform))))
    {
      throw HException("ToolInBasePoses have different pose types.");
    }
    //Convert to default pose type.
    {
    HTuple ExpTmpOutVar_0;
    ConvertPoseType(hvec_ToolInBasePoses[hv_Index].T(), "Rp+T", "gba", "point", &ExpTmpOutVar_0);
    hvec_ToolInBasePoses[hv_Index].T() = ExpTmpOutVar_0;
    }
  }
  }
  //
  //Collect the robot translations.
  CreatePose(HTuple(hv_RobotTouchingPointInToolCoordinates[0]), HTuple(hv_RobotTouchingPointInToolCoordinates[1]), 
      HTuple(hv_RobotTouchingPointInToolCoordinates[2]), 0, 0, 0, "Rp+T", "gba", 
      "point", &hv_RobotTouchingPointToToolXYZPose);
  hv_XBase = HTuple();
  hv_YBase = HTuple();
  hv_ZBase = HTuple();
  {
  HTuple end_val34 = (hv_RowsTouchingPointInPlane.TupleLength())-1;
  HTuple step_val34 = 1;
  for (hv_Index=0; hv_Index.Continue(end_val34, step_val34); hv_Index += step_val34)
  {
    PoseCompose(hvec_ToolInBasePoses[hv_Index].T(), hv_RobotTouchingPointToToolXYZPose, 
        &hv_TouchingPointInBasePose);
    hv_XBase = hv_XBase.TupleConcat(HTuple(hv_TouchingPointInBasePose[0]));
    hv_YBase = hv_YBase.TupleConcat(HTuple(hv_TouchingPointInBasePose[1]));
    hv_ZBase = hv_ZBase.TupleConcat(HTuple(hv_TouchingPointInBasePose[2]));
  }
  }
  //
  // Use the specified robot translations to obtain the PlaneInBasePose.
  GenObjectModel3dFromPoints(hv_XBase, hv_YBase, hv_ZBase, &hv_OM3DPlanePoints);
  FitPrimitivesObjectModel3d(hv_OM3DPlanePoints, "primitive_type", "plane", &hv_OM3DPlane);
  GetObjectModel3dParams(hv_OM3DPlane, "primitive_pose", &hv_TouchingPointPlaneInBasePose);
  //
  //Obtain fictitious camera parameters.
  hv_FocusOrig = 0.008;
  hv_DiffRow = (hv_RowsTouchingPointInPlane.TupleSelectRange(0,(hv_RowsTouchingPointInPlane.TupleLength())-2))-(hv_RowsTouchingPointInPlane.TupleSelectRange(1,(hv_RowsTouchingPointInPlane.TupleLength())-1));
  hv_DiffCol = (hv_ColumnsTouchingPointInPlane.TupleSelectRange(0,(hv_ColumnsTouchingPointInPlane.TupleLength())-2))-(hv_ColumnsTouchingPointInPlane.TupleSelectRange(1,(hv_ColumnsTouchingPointInPlane.TupleLength())-1));
  hv_DistPixel = ((hv_DiffRow*hv_DiffRow)+(hv_DiffCol*hv_DiffCol)).TupleSqrt();
  hv_DiffX = (hv_XBase.TupleSelectRange(0,(hv_XBase.TupleLength())-2))-(hv_XBase.TupleSelectRange(1,(hv_XBase.TupleLength())-1));
  hv_DiffY = (hv_YBase.TupleSelectRange(0,(hv_YBase.TupleLength())-2))-(hv_YBase.TupleSelectRange(1,(hv_YBase.TupleLength())-1));
  hv_DiffZ = (hv_ZBase.TupleSelectRange(0,(hv_ZBase.TupleLength())-2))-(hv_ZBase.TupleSelectRange(1,(hv_ZBase.TupleLength())-1));
  hv_DistWorld = (((hv_DiffX*hv_DiffX)+(hv_DiffY*hv_DiffY))+(hv_DiffZ*hv_DiffZ)).TupleSqrt();
  hv_Quotient = (hv_DistWorld/hv_DistPixel).TupleMedian();
  //Camera parameter will be generated in the following form:
  //SX := Quotient * FocusOrig / DistancePlaneToCamera
  //SY := SX
  //gen_cam_par_area_scan_division (FocusOrig, 0, SX, SY, Width / 2.0, Height / 2.0, Width, Height, HandEyeCalibData)
  //
  //Use the specified image points and robot translations to obtain the BaseInCamPose.
  hv_FocusShift.Clear();
  hv_FocusShift[0] = 0.1;
  hv_FocusShift[1] = 0.2;
  hv_FocusShift[2] = 0.33;
  hv_FocusShift[3] = 0.5;
  hv_FocusShift[4] = 0.75;
  hv_FocusShift[5] = 1.0;
  hv_FocusShift[6] = 1.5;
  hv_FocusShift[7] = 2;
  hv_FocusShift[8] = 3;
  hv_FocusShift[9] = 3.125;
  hv_FocusShift[10] = 3.5;
  hv_FocusShift[11] = 4;
  hv_BestIndex = -1;
  //The value of focus should not have much influence when camera and plane are parallel,
  //but just in case, check different values.
  hv_ErrorBasePoseInPixel = 1e9;
  {
  HTuple end_val67 = (hv_FocusShift.TupleLength())-1;
  HTuple step_val67 = 1;
  for (hv_NumFocus=0; hv_NumFocus.Continue(end_val67, step_val67); hv_NumFocus += step_val67)
  {
    hv_Focus = hv_FocusOrig*HTuple(hv_FocusShift[hv_NumFocus]);
    hv_SX = (hv_Quotient*hv_Focus)/hv_DistancePlaneToCamera;
    hv_SY = hv_SX;
    gen_cam_par_area_scan_division(hv_Focus, 0, hv_SX, hv_SY, hv_Width/2.0, hv_Height/2.0, 
        hv_Width, hv_Height, &hv_CamParam0);
    VectorToPose(hv_XBase, hv_YBase, hv_ZBase, hv_RowsTouchingPointInPlane, hv_ColumnsTouchingPointInPlane, 
        hv_CamParam0, "iterative", "error", &hv_BaseInCamPose0, &hv_ErrorBasePoseInPixelTmp);
    if (0 != (int(hv_ErrorBasePoseInPixel>hv_ErrorBasePoseInPixelTmp)))
    {
      hv_BaseInCamPose = hv_BaseInCamPose0;
      hv_ErrorBasePoseInPixel = hv_ErrorBasePoseInPixelTmp;
      hv_CamParam = hv_CamParam0;
    }
  }
  }
  //Get the PlaneInCamPose.
  PoseCompose(hv_BaseInCamPose, hv_TouchingPointPlaneInBasePose, &hv_TouchingPointPlaneInCamPose);
  //
  //The z-axis of the plane should point away from the camera.
  hv_TouchingPointPlaneInCamPose0Rot = hv_TouchingPointPlaneInCamPose;
  hv_TouchingPointPlaneInCamPose0Rot[HTuple::TupleGenSequence(0,2,1)] = ((HTuple(0).Append(0)).Append(0));
  PoseToHomMat3d(hv_TouchingPointPlaneInCamPose0Rot, &hv_HomMat3D);
  AffineTransPoint3d(hv_HomMat3D, 0, 0, 1, &hv_Qx, &hv_Qy, &hv_CosAngleBetweenZAxis);
  if (0 != (int(hv_CosAngleBetweenZAxis<0)))
  {
    CreatePose(0, 0, 0, 180, 0, 0, "Rp+T", "gba", "point", &hv_SwitchZDirection);
    PoseCompose(hv_TouchingPointPlaneInCamPose, hv_SwitchZDirection, &hv_TouchingPointPlaneInCamPose1);
    hv_TouchingPointPlaneInCamPose = hv_TouchingPointPlaneInCamPose1;
    PoseInvert(hv_BaseInCamPose, &hv_CamInBasePose);
    PoseCompose(hv_CamInBasePose, hv_TouchingPointPlaneInCamPose, &hv_TouchingPointPlaneInBasePose);
  }
  //
  //Get the difference of the points in the plane as seen by the camera
  //to the points in the plane as approached by the robot.
  ImagePointsToWorldPlane(hv_CamParam, hv_TouchingPointPlaneInCamPose, hv_RowsTouchingPointInPlane, 
      hv_ColumnsTouchingPointInPlane, "m", &hv_TouchingPointPlanePointsCamX, &hv_TouchingPointPlanePointsCamY);
  TupleGenConst(hv_TouchingPointPlanePointsCamY.TupleLength(), 0.0, &hv_TouchingPointPlanePointsCamZ);
  PoseInvert(hv_TouchingPointPlaneInBasePose, &hv_BaseInTouchingPointPlanePose);
  PoseToHomMat3d(hv_BaseInTouchingPointPlanePose, &hv_HomMat3D1);
  AffineTransPoint3d(hv_HomMat3D1, hv_XBase, hv_YBase, hv_ZBase, &hv_TouchingPointPlanePointsToolX, 
      &hv_TouchingPointPlanePointsToolY, &hv_TouchingPointPlanePointsToolZ);
  hv_DiffX = hv_TouchingPointPlanePointsCamX-hv_TouchingPointPlanePointsToolX;
  hv_DiffY = hv_TouchingPointPlanePointsCamY-hv_TouchingPointPlanePointsToolY;
  hv_DiffZ = hv_TouchingPointPlanePointsCamZ-hv_TouchingPointPlanePointsToolZ;
  hv_SqrDiff = ((hv_DiffX*hv_DiffX)+(hv_DiffY*hv_DiffY))+(hv_DiffZ*hv_DiffZ);
  hv_PlanePointsRMS = ((hv_SqrDiff.TupleSum())/(hv_DiffX.TupleLength())).TupleSqrt();
  hv_PlanePointsMaxDiff = (hv_SqrDiff.TupleSqrt()).TupleMax();
  //
  SetOriginPose(hv_TouchingPointPlaneInBasePose, 0, 0, hv_DistanceObjectTouchingPointToPlane, 
      &hv_PlaneInBasePose);
  SetOriginPose(hv_TouchingPointPlaneInCamPose, 0, 0, hv_DistanceObjectTouchingPointToPlane, 
      &hv_PlaneInCamPose);
  //
  //Convert to output pose type.
  ConvertPoseType(hv_BaseInCamPose, hv_OrderOfTransform0, hv_OrderOfRotation0, hv_ViewOfTransform0, 
      &hv_BaseInCamPose);
  ConvertPoseType(hv_PlaneInBasePose, hv_OrderOfTransform0, hv_OrderOfRotation0, 
      hv_ViewOfTransform0, &hv_PlaneInBasePose);
  ConvertPoseType(hv_PlaneInCamPose, hv_OrderOfTransform0, hv_OrderOfRotation0, hv_ViewOfTransform0, 
      &hv_PlaneInCamPose);
  //
  //Create output dict.
  CreateDict(&(*hv_HandEyeCalibData));
  SetDictTuple((*hv_HandEyeCalibData), "CamParam", hv_CamParam);
  SetDictTuple((*hv_HandEyeCalibData), "BaseInCamPose", hv_BaseInCamPose);
  SetDictTuple((*hv_HandEyeCalibData), "PlaneInBasePose", hv_PlaneInBasePose);
  SetDictTuple((*hv_HandEyeCalibData), "PlaneInCamPose0", hv_PlaneInCamPose);
  SetDictTuple((*hv_HandEyeCalibData), "PlanePointsRMS", hv_PlanePointsRMS);
  SetDictTuple((*hv_HandEyeCalibData), "PlanePointsMaxDiff", hv_PlanePointsMaxDiff);
  return;
}

// Chapter: Calibration / Hand-Eye
// Short Description: Calibrate the X, Y, Z coordinates of a touching point of a robot. 
void calibrate_robot_touching_point (HTuple hv_DataDir, HTuple *hv_RobotTouchingPointInToolCoordinates)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_WindowHandle, hv_WindowHandleGraphics;
  HTuple  hv_Index, hv_ToolInBasePoseTouchingPoint;
  HTupleVector  hvec_ToolInBasePosesTouchingPoint(1);

  //
  //Open a new window.
  open_new_window(&hv_WindowHandle, &hv_WindowHandleGraphics);
  //Display introduction.
  dev_disp_introduction(hv_WindowHandle, hv_WindowHandleGraphics);
  // stop(...); only in hdevelop
  //
  //Read three ToolInBasesPoses which are used
  //to calibrate the RobotTouchingPointInToolCoordinates.
  for (hv_Index=1; hv_Index<=3; hv_Index+=1)
  {
    ReadPose(((hv_DataDir+"tool_in_base_pose_touching_point_0")+hv_Index)+".dat", 
        &hv_ToolInBasePoseTouchingPoint);
    dev_disp_approach_pose_touching_point_instructions(hv_WindowHandle, hv_WindowHandleGraphics, 
        hv_Index);
    // stop(...); only in hdevelop
    //Collect poses in vector.
    hvec_ToolInBasePosesTouchingPoint[hv_Index-1] = HTupleVector(hv_ToolInBasePoseTouchingPoint);
  }
  HDevWindowStack::SetActive(hv_WindowHandleGraphics);
  if (HDevWindowStack::IsOpen())
    CloseWindow(HDevWindowStack::Pop());
  //
  //Calculate the coordinates of the touching point
  //of the robot with respect to the robot's tool.
  get_robot_touching_point_in_tool_coordinates(hvec_ToolInBasePosesTouchingPoint, 
      &(*hv_RobotTouchingPointInToolCoordinates));
  //
  //Visualize results.
  visualize_calibrated_touching_point((*hv_RobotTouchingPointInToolCoordinates), 
      hvec_ToolInBasePosesTouchingPoint, hv_WindowHandle);
  return;
}

// Chapter: Deep Learning / Model
// Short Description: Check and sanitize the parameters of augment_dl_samples. 
void check_augment_dl_samples_gen_param (HTuple hv_GenParam)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_GenKeys, hv_ValidAugMethods, hv_ValidOtherKeys;
  HTuple  hv_ValidKeys, hv_InvalidKeys, hv_Exception, hv_KeyIndex;
  HTuple  hv_GenKey, hv_GenValue, hv_NumValues, hv_V, hv_Value;
  HTuple  hv_SanitizedValue;

  //This procedure validates and sanitizes the GenParam parameter of the
  //augment_dl_samples procedure.
  //
  //This procedure should not be used outside of the augment_dl_samples procedure!
  //The name, parameters, and functionality of this procedure are subject to change.
  //
  //Check that there are no unknown parameters.
  GetDictParam(hv_GenParam, "keys", HTuple(), &hv_GenKeys);
  hv_ValidAugMethods.Clear();
  hv_ValidAugMethods[0] = "brightness_variation";
  hv_ValidAugMethods[1] = "brightness_variation_spot";
  hv_ValidAugMethods[2] = "contrast_variation";
  hv_ValidAugMethods[3] = "crop_percentage";
  hv_ValidAugMethods[4] = "crop_pixel";
  hv_ValidAugMethods[5] = "mirror";
  hv_ValidAugMethods[6] = "remove_pixel";
  hv_ValidAugMethods[7] = "rotate";
  hv_ValidAugMethods[8] = "rotate_range";
  hv_ValidAugMethods[9] = "saturation_variation";
  hv_ValidOtherKeys.Clear();
  hv_ValidOtherKeys[0] = "augmentation_percentage";
  hv_ValidOtherKeys[1] = "class_ids_no_orientation";
  hv_ValidOtherKeys[2] = "ignore_direction";
  hv_ValidKeys.Clear();
  hv_ValidKeys.Append(hv_ValidAugMethods);
  hv_ValidKeys.Append(hv_ValidOtherKeys);
  TupleDifference(hv_GenKeys, hv_ValidKeys, &hv_InvalidKeys);
  if (0 != (int((hv_InvalidKeys.TupleLength())>0)))
  {
    hv_Exception = "These keys in GenParam are not supported by augment_dl_samples: '"+(hv_InvalidKeys.TupleJoin(HTuple("', '")+"'"));
    throw HException(hv_Exception);
  }
  //
  //Check each parameter.
  {
  HTuple end_val18 = (hv_GenKeys.TupleLength())-1;
  HTuple step_val18 = 1;
  for (hv_KeyIndex=0; hv_KeyIndex.Continue(end_val18, step_val18); hv_KeyIndex += step_val18)
  {
    //Get the key and value, for example 'rotate_range' and 3.
    hv_GenKey = HTuple(hv_GenKeys[hv_KeyIndex]);
    hv_GenValue = hv_GenParam.TupleGetDictTuple(hv_GenKey);
    //Perform validation
    if (0 != (int(hv_GenKey==HTuple("augmentation_percentage"))))
    {
      //Check if input value is in range of 0-100 %.
      hv_Exception = "The given value for 'augmentation_percentage' has to be in the range 0-100.";
      if (0 != (hv_GenValue.TupleIsNumber()))
      {
        if (0 != (HTuple(int(hv_GenValue<0)).TupleOr(int(hv_GenValue>100))))
        {
          throw HException(hv_Exception);
        }
      }
      else
      {
        throw HException(hv_Exception);
      }
    }
    if (0 != (int(hv_GenKey==HTuple("brightness_variation"))))
    {
      //Check if the input value is in range of 0-255.
      hv_Exception = "The given value for 'brightness_variation' has to be in the range 0-255.";
      if (0 != (hv_GenValue.TupleIsNumber()))
      {
        if (0 != (HTuple(int(hv_GenValue<0)).TupleOr(int(hv_GenValue>255))))
        {
          throw HException(hv_Exception);
        }
      }
      else
      {
        throw HException(hv_Exception);
      }
    }
    if (0 != (int(hv_GenKey==HTuple("brightness_variation_spot"))))
    {
      //Check if the input value is in range of 0-255.
      hv_Exception = "The given value for 'brightness_variation_spot' has to be in the range 0-255.";
      if (0 != (hv_GenValue.TupleIsNumber()))
      {
        if (0 != (HTuple(int(hv_GenValue<0)).TupleOr(int(hv_GenValue>255))))
        {
          throw HException(hv_Exception);
        }
      }
      else
      {
        throw HException(hv_Exception);
      }
    }
    if (0 != (int(hv_GenKey==HTuple("contrast_variation"))))
    {
      //Check if the input value is not negative.
      hv_Exception = "The given value for 'contrast_variation' has to be greater than or equal to zero.";
      if (0 != (hv_GenValue.TupleIsNumber()))
      {
        if (0 != (int(hv_GenValue<0)))
        {
          throw HException(hv_Exception);
        }
      }
      else
      {
        throw HException(hv_Exception);
      }
    }
    if (0 != (int(hv_GenKey==HTuple("crop_percentage"))))
    {
      //Check if the input value is in range of 1-100%.
      hv_Exception = "The given value for 'crop_percentage' has to be in the range 1-100.";
      if (0 != (hv_GenValue.TupleIsNumber()))
      {
        if (0 != (HTuple(int(hv_GenValue<1)).TupleOr(int(hv_GenValue>100))))
        {
          throw HException(hv_Exception);
        }
      }
      else
      {
        throw HException(hv_Exception);
      }
    }
    if (0 != (int(hv_GenKey==HTuple("crop_pixel"))))
    {
      //Check if the input value is greater 0.
      hv_Exception = "The given value for 'crop_pixel' has to be greater or equal to 1.";
      if (0 != (hv_GenValue.TupleIsNumber()))
      {
        if (0 != (int(hv_GenValue<1)))
        {
          throw HException(hv_Exception);
        }
      }
      else
      {
        throw HException(hv_Exception);
      }
    }
    if (0 != (int(hv_GenKey==HTuple("ignore_direction"))))
    {
      hv_Exception = HTuple("The value given for 'ignore_direction' has to be either 'true','false', true or false.");
      if (0 != (int(((((HTuple("true").Append("false")).Append(1)).Append(0)).TupleFind(hv_GenValue))==-1)))
      {
        throw HException(hv_Exception);
      }
      //Sanitize string values to Booleans.
      if (0 != (int(hv_GenValue==HTuple("false"))))
      {
        hv_GenValue = 0;
      }
      else if (0 != (int(hv_GenValue==HTuple("true"))))
      {
        hv_GenValue = 1;
      }
      //Overwrite the value in GenParam.
      SetDictTuple(hv_GenParam, hv_GenKey, hv_GenValue);
    }
    if (0 != (int(hv_GenKey==HTuple("mirror"))))
    {
      //Check if the input is a string and contains either 'off' or the mirroring code.
      if (0 != ((hv_GenValue.TupleIsNumber()).TupleOr(HTuple(HTuple(HTuple(HTuple(HTuple(int(hv_GenValue==HTuple("off"))).TupleOr(int(hv_GenValue==HTuple("c")))).TupleOr(int(hv_GenValue==HTuple("r")))).TupleOr(int(hv_GenValue==HTuple("cr")))).TupleOr(int(hv_GenValue==HTuple("rc")))).TupleNot())))
      {
        throw HException("Unknown type for mirroring.");
      }
    }
    if (0 != (int(hv_GenKey==HTuple("remove_pixel"))))
    {
      //Set pixels to remove.
      //Check if the input values are valid. Valid are either 1d-tuples with
      //the pixels to remove for both dimensions, or 2d-tuples with the pixels
      //to remove for each dimension [x,y].
      hv_NumValues = hv_GenValue.TupleLength();
      if (0 != (HTuple(int(hv_NumValues!=1)).TupleAnd(int(hv_NumValues!=2))))
      {
        throw HException("The number of values for 'remove_pixel' has to be 1 or 2.");
      }
      {
      HTuple end_val118 = hv_NumValues-1;
      HTuple step_val118 = 1;
      for (hv_V=0; hv_V.Continue(end_val118, step_val118); hv_V += step_val118)
      {
        hv_Value = HTuple(hv_GenValue[hv_V]);
        if (0 != ((hv_Value.TupleIsInt()).TupleNot()))
        {
          throw HException("The given value for 'remove_pixel' has to be an integer value.");
        }
        if (0 != (int(hv_Value<0)))
        {
          throw HException("The given value for 'remove_pixel' has to be equal or greater than 0.");
        }
      }
      }
      //Store the input values for each dimension [x,y].
      hv_SanitizedValue = ((const HTuple&)hv_GenValue)[0];
      if (0 != (int(hv_NumValues==1)))
      {
        hv_SanitizedValue[1] = HTuple(hv_GenValue[0]);
      }
      else
      {
        hv_SanitizedValue[1] = HTuple(hv_GenValue[1]);
      }
      //Overwrite the value in GenParam.
      SetDictTuple(hv_GenParam, hv_GenKey, hv_SanitizedValue);
    }
    if (0 != (int(hv_GenKey==HTuple("rotate"))))
    {
      //Check if the input value is either 0, 90, or 180.
      hv_Exception = HTuple("The value given for 'rotate' has to be either 0, 90, or 180.");
      if (0 != (hv_GenValue.TupleIsNumber()))
      {
        if (0 != (int((((HTuple(0).Append(90)).Append(180)).TupleFind(hv_GenValue))==-1)))
        {
          throw HException(hv_Exception);
        }
      }
      else
      {
        throw HException(hv_Exception);
      }
    }
    if (0 != (int(hv_GenKey==HTuple("rotate_range"))))
    {
      //Check if the input value is in range of 0-180.
      hv_Exception = "The given value for 'rotate_range' has to be in the range 0-180.";
      if (0 != (hv_GenValue.TupleIsNumber()))
      {
        if (0 != (HTuple(int(hv_GenValue<0)).TupleOr(int(hv_GenValue>180))))
        {
          throw HException(hv_Exception);
        }
      }
      else
      {
        throw HException(hv_Exception);
      }
    }
    if (0 != (int(hv_GenKey==HTuple("saturation_variation"))))
    {
      //Check if the input value is not negative.
      hv_Exception = "The given value for 'saturation_variation' has to be greater than or equal to zero.";
      if (0 != (hv_GenValue.TupleIsNumber()))
      {
        if (0 != (int(hv_GenValue<0)))
        {
          throw HException(hv_Exception);
        }
      }
      else
      {
        throw HException(hv_Exception);
      }
    }
  }
  }
  return;
}

// Chapter: 3D Matching / 3D Gripping Point Detection
// Short Description: Initialize and check parameter for the generation of 3D gripping points and poses. 
void check_dl_3d_gripping_points_and_poses_params (HTuple hv_DLGrippingPointParams)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_HasMinAreaSize, hv_HasSortingDir, hv_SortingDirectionRaw;
  HTuple  hv_LenSortingDirectionRaw;

  GetDictParam(hv_DLGrippingPointParams, "key_exists", "min_area_size", &hv_HasMinAreaSize);
  if (0 != hv_HasMinAreaSize)
  {
    if (0 != (int((hv_DLGrippingPointParams.TupleGetDictTuple("min_area_size"))<=0)))
    {
      throw HException("DLGrippingPointParams.min_area_size has to be at least 1.");
    }
  }
  else
  {
    SetDictTuple(hv_DLGrippingPointParams, "min_area_size", 1);
  }
  //
  GetDictParam(hv_DLGrippingPointParams, "key_exists", "sorting_direction", &hv_HasSortingDir);
  if (0 != hv_HasSortingDir)
  {
    if (0 != (int(((hv_DLGrippingPointParams.TupleGetDictTuple("sorting_direction")).TupleLength())!=3)))
    {
      throw HException("DLGrippingPointParams.sorting_direction has to be a 3D-vector.");
    }
    hv_SortingDirectionRaw = hv_DLGrippingPointParams.TupleGetDictTuple("sorting_direction");
    hv_LenSortingDirectionRaw = ((hv_SortingDirectionRaw*hv_SortingDirectionRaw).TupleSum()).TupleSqrt();
    if (0 != (int(hv_LenSortingDirectionRaw<1.0e-06)))
    {
      throw HException("DLGrippingPointParams.sorting_direction must not be the zero-vector.");
    }
    SetDictTuple(hv_DLGrippingPointParams, "sorting_direction", hv_SortingDirectionRaw/hv_LenSortingDirectionRaw);
  }
  else
  {
    SetDictTuple(hv_DLGrippingPointParams, "sorting_direction", ((HTuple(0.0).Append(0.0)).Append(0.1)));
  }
  return;
}

// Chapter: Deep Learning / Model
// Short Description: Check for devices supporting deep learning applications. 
void check_dl_devices (HTuple *hv_PossibleRuntimes)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_HalconArch, hv_ACLLoaded, hv_CUDADevices;
  HTuple  hv_CUDALoaded, hv_cuDNNLoaded, hv_cuBLASLoaded;

  //This procedure checks, which devices
  //fulfill the driver and library requirements
  //imposed by the deep learning application.
  //
  (*hv_PossibleRuntimes) = HTuple();
  //Check for CPU. These requirements depend on the system used.
  GetSystem("halcon_arch", &hv_HalconArch);
  if (0 != (hv_HalconArch.TupleRegexpTest("x64")))
  {
    (*hv_PossibleRuntimes) = (*hv_PossibleRuntimes).TupleConcat("cpu");
  }
  else if (0 != (hv_HalconArch.TupleRegexpTest("aarch64")))
  {
    GetSystem("arm_compute_loaded", &hv_ACLLoaded);
    if (0 != (int(hv_ACLLoaded==HTuple("true"))))
    {
      (*hv_PossibleRuntimes) = (*hv_PossibleRuntimes).TupleConcat("cpu");
    }
  }
  //Check for GPU.
  GetSystem("cuda_devices", &hv_CUDADevices);
  if (0 != (int((hv_CUDADevices.TupleLength())>0)))
  {
    GetSystem("cuda_loaded", &hv_CUDALoaded);
    GetSystem("cudnn_loaded", &hv_cuDNNLoaded);
    GetSystem("cublas_loaded", &hv_cuBLASLoaded);
    if (0 != (HTuple(HTuple(int(hv_CUDALoaded==HTuple("true"))).TupleAnd(int(hv_cuDNNLoaded==HTuple("true")))).TupleAnd(int(hv_cuBLASLoaded==HTuple("true")))))
    {
      (*hv_PossibleRuntimes) = (*hv_PossibleRuntimes).TupleConcat("gpu");
    }
  }
  //
  return;
}

// Chapter: Deep Learning / Anomaly Detection and Global Context Anomaly Detection
// Short Description: Check if scores of a Global Context Anomaly Detection model have been normalized 
void check_dl_gc_anomaly_scores_normalization (HTuple hv_DLModelHandle, HTuple hv_GenParam)
{

  // Local iconic variables
  HObject  ho_Weights, ho_Bias;

  // Local control variables
  HTuple  hv_DLModelIsConverted, hv_Networks, hv_HasLocalNetwork;
  HTuple  hv_HasGlobalNetwork, hv_NormalizationLayers, hv_Index;
  HTuple  hv_LayerName, hv_Rows, hv_Columns, hv_WeightsValues;
  HTuple  hv_HasDefaultWeights, hv_BiasValues, hv_HasDefaultBias;

  //This procedure checks if all gc anomaly scores have been normalized.
  //
  //Make sure GenParam is an empty tuple.
  if (0 != (int(hv_GenParam!=HTuple())))
  {
    throw HException("The parameter GenParam must be an empty tuple.");
  }
  //
  //For models using an AI accelerator interface for inference, the
  //weights of internal layers are no longer available. They are
  //removed to reduce the memory footprint of the model. Therefore
  //we have no means to check if the gc anomaly scores have been
  //normalized, and thus we assume that this is already the case.
  GetDlModelParam(hv_DLModelHandle, "precision_is_converted", &hv_DLModelIsConverted);
  if (0 != (int(hv_DLModelIsConverted==HTuple("true"))))
  {
    return;
  }
  //
  //Find networks to be normalized.
  GetDlModelParam(hv_DLModelHandle, "gc_anomaly_networks", &hv_Networks);
  hv_HasLocalNetwork = int((hv_Networks.TupleFind("local"))!=-1);
  hv_HasGlobalNetwork = int((hv_Networks.TupleFind("global"))!=-1);
  hv_NormalizationLayers = HTuple();
  if (0 != hv_HasLocalNetwork)
  {
    hv_NormalizationLayers = hv_NormalizationLayers.TupleConcat("local_normalization");
  }
  if (0 != hv_HasGlobalNetwork)
  {
    hv_NormalizationLayers = hv_NormalizationLayers.TupleConcat("global_normalization");
  }
  //
  {
  HTuple end_val29 = (hv_NormalizationLayers.TupleLength())-1;
  HTuple step_val29 = 1;
  for (hv_Index=0; hv_Index.Continue(end_val29, step_val29); hv_Index += step_val29)
  {
    hv_LayerName = HTuple(hv_NormalizationLayers[hv_Index]);
    GetDlModelLayerWeights(&ho_Weights, hv_DLModelHandle, hv_LayerName, "weights");
    GetRegionPoints(ho_Weights, &hv_Rows, &hv_Columns);
    GetGrayval(ho_Weights, hv_Rows, hv_Columns, &hv_WeightsValues);
    //Calculate if weights are equal since some floating point arithmetic
    //is involved in their creation.
    hv_HasDefaultWeights = int(((((hv_WeightsValues.TupleLength())*hv_WeightsValues)-HTuple(hv_WeightsValues.TupleLength(),1.0)).TupleAbs())<((hv_WeightsValues.TupleLength())*1e-6));
    //
    GetDlModelLayerWeights(&ho_Bias, hv_DLModelHandle, hv_LayerName, "bias");
    GetRegionPoints(ho_Bias, &hv_Rows, &hv_Columns);
    GetGrayval(ho_Bias, hv_Rows, hv_Columns, &hv_BiasValues);
    //The bias is set directly, hence an equality check is sufficient.
    hv_HasDefaultBias = int(hv_BiasValues==HTuple(hv_BiasValues.TupleLength(),0.0));
    //
    if (0 != (hv_HasDefaultWeights.TupleAnd(hv_HasDefaultBias)))
    {
      throw HException(HTuple("For a model of type gc_anomaly_detection, the anomaly scores must be normalized first."));
    }
  }
  }
  //
  return;
}

