    RigidTransObjectModel3d(hv_VisibleReferencePoints, hv_PoseResult, &hv_ObjectModel3DVisible);
    RigidTransObjectModel3d(hv_ObjectModel3DModelSampled, hv_PoseResult, &hv_ObjectModel3DModelSampled);
