  hcppthread_handle->SetInputCtrlParamTuple(5,((((((((HTuple("green").Append("red")).Append("gray")).Append("gray")).Append("white")).Append(0.5)).Append("true")).Append("false")).Append("true")));
  hcppthread_handle->SetInputCtrlParamTuple(6,"Inspect Visible Points");
