      SetMessageTuple(hv_MessageHandle, "model", (hv_ObjectModel3DVisible.TupleConcat(hv_OM3DCamera)).TupleConcat(hv_OM3DLineSphereToScene));
      EnqueueMessage(HTuple(hv_MessageQueues2[1]), hv_MessageHandle, HTuple(), HTuple());
