// Chapter: Deep Learning / Anomaly Detection and Global Context Anomaly Detection
// Short Description: Create a block of anomaly samples for a DLDataset. 
void create_dl_dataset_anomaly_samples (HTuple hv_ImageList, HTuple hv_LabelList, 
    HTuple hv_AnomalyList, HTuple hv_AnomalyDirGiven, HTuple hv_NumSamplesPerThread, 
    HTuple hv_UniqueIndex, HTuple *hv_SamplesOutput, HTuple *hv_Exception)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_SampleIndex, hv_Sample, hv_Label, hv_AnomalyFileName;

  //This procedure creates a block of samples for a given thread.
  TupleGenConst(hv_NumSamplesPerThread, "", &(*hv_SamplesOutput));
  (*hv_Exception) = HTuple();
  //
  //Loop over samples.
  {
  HTuple end_val5 = hv_NumSamplesPerThread-1;
  HTuple step_val5 = 1;
  for (hv_SampleIndex=0; hv_SampleIndex.Continue(end_val5, step_val5); hv_SampleIndex += step_val5)
  {
    //
    //Create the dictionary Sample.
    CreateDict(&hv_Sample);
    //
    //Set information about this sample.
    SetDictTuple(hv_Sample, "image_id", hv_UniqueIndex);
    SetDictTuple(hv_Sample, "image_file_name", HTuple(hv_ImageList[hv_SampleIndex]));
    hv_UniqueIndex += 1;
    //
    hv_Label = HTuple(hv_LabelList[hv_SampleIndex]);
    if (0 != (int(hv_Label==HTuple(""))))
    {
      (*hv_Exception) = "Could not determine label for image: "+HTuple(hv_ImageList[hv_SampleIndex]);
      return;
    }
    //
    //Match for good labels.
    if (0 != (HTuple(int((hv_Label.TupleRegexpMatch((HTuple("^ok$").Append("ignore_case"))))!=HTuple(""))).TupleOr(int((hv_Label.TupleRegexpMatch((HTuple("^good$").Append("ignore_case"))))!=HTuple("")))))
    {
      SetDictTuple(hv_Sample, "anomaly_label", "ok");
    }
    else
    {
      SetDictTuple(hv_Sample, "anomaly_label", "nok");
    }
    //
    //Check if sample has an anomaly annotation.
    if (0 != hv_AnomalyDirGiven)
    {
      hv_AnomalyFileName = HTuple(hv_AnomalyList[hv_SampleIndex]);
      if (0 != (int(hv_AnomalyFileName!=HTuple(""))))
      {
        SetDictTuple(hv_Sample, "anomaly_file_name", hv_AnomalyFileName);
      }
    }
    //
    //Append this sample.
    (*hv_SamplesOutput)[hv_SampleIndex] = hv_Sample;
  }
  }
  //
  return;
}

// Chapter: Deep Learning / Classification
// Short Description: Create a block of classification samples for a DLDataset. 
void create_dl_dataset_classification_samples (HTuple hv_ImageFiles, HTuple hv_LabelIndices, 
    HTuple hv_RawImageFolder, HTuple hv_ImageDir, HTuple hv_NumSamplesPerThread, 
    HTuple hv_UniqueIndex, HTuple *hv_SamplesOutput)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_SampleIndex, hv_Sample, hv_ImageID;
  HTuple  hv_ImageFile, hv_Positions, hv_Position, hv_ImageDirLength;
  HTuple  hv_ImageFileName;

  //This procedure creates a block of samples for a given thread.
  TupleGenConst(hv_NumSamplesPerThread, "", &(*hv_SamplesOutput));
  //
  {
  HTuple end_val3 = hv_NumSamplesPerThread-1;
  HTuple step_val3 = 1;
  for (hv_SampleIndex=0; hv_SampleIndex.Continue(end_val3, step_val3); hv_SampleIndex += step_val3)
  {
    //Create the dictionary Sample.
    CreateDict(&hv_Sample);
    //Set information about this sample.
    hv_ImageID = hv_UniqueIndex;
    SetDictTuple(hv_Sample, "image_id", hv_ImageID);
    hv_UniqueIndex += 1;
    //'image_file_name' has to be relative to ImageDir.
    hv_ImageFile = HTuple(hv_ImageFiles[hv_SampleIndex]);
    if (0 != (int(hv_ImageDir==HTuple("."))))
    {
      TupleStrstr(hv_ImageFile, hv_RawImageFolder, &hv_Positions);
      hv_Position = HTuple(hv_Positions[(hv_Positions.TupleNotEqualElem(-1)).TupleFind(1)]);
    }
    else
    {
      TupleStrstr(hv_ImageFile, hv_ImageDir, &hv_Position);
      TupleStrlen(hv_ImageDir, &hv_ImageDirLength);
      hv_Position = (hv_Position+hv_ImageDirLength)+1;
    }
    hv_ImageFileName = hv_ImageFile.TupleStrLastN(hv_Position);
    SetDictTuple(hv_Sample, "image_file_name", hv_ImageFileName);
    //Set class ID.
    SetDictTuple(hv_Sample, "image_label_id", HTuple(hv_LabelIndices[hv_SampleIndex]));
    //
    //Append this sample.
    (*hv_SamplesOutput)[hv_SampleIndex] = hv_Sample;
  }
  }
  //
  return;
}

// Chapter: Deep Learning / Object Detection and Instance Segmentation
// Short Description: Create a block of samples for a given thread. 
void create_dl_dataset_from_coco_samples (HTuple hv_ImageList, HTuple hv_ImageKeys, 
    HTuple hv_ImageDir, HTuple hv_AnnotationList, HTuple hv_AnnotationKeys, HTuple hv_AnnotImageIDs, 
    HTuple hv_Purpose, HTuple hv_ReadOnlyNonCrowd, HTuple hv_ReadRawAnnotations, 
    HTuple hv_ReadMasks, HTuple hv_NumSamplesPerThread, HTuple hv_UniqueIndex, HTuple *hv_DLSamplesOutput, 
    HTuple *hv_Exception)
{

  // Local iconic variables
  HObject  ho_Segmentations, ho_AnnotRegion;

  // Local control variables
  HTuple  hv_Index, hv_Image, hv_ImageName, hv_ImageID;
  HTuple  hv_ExceptionImage, hv_FileExists, hv_AnnotationIndicesThisImage;
  HTuple  hv_AnnotClassIDs, hv_AnnotBboxColumn1s, hv_AnnotBboxRow1s;
  HTuple  hv_AnnotBboxColumn2s, hv_AnnotBboxRow2s, hv_HaveSegmentations;
  HTuple  hv_AnnotationPerImage, hv_AnnotationKeysThisImage;
  HTuple  hv_AnnotIndexCounter, hv_AnnotIndex, hv_Annotation;
  HTuple  hv_IsCrowd, hv_ExceptionIsCrowd, hv_AnnotClassID;
  HTuple  hv_BBox, hv_AnnotBboxColumn1, hv_AnnotBboxRow1;
  HTuple  hv_AnnotBboxWidth, hv_AnnotBboxHeight, hv_ExceptionAnnot;
  HTuple  hv_Segmentation, hv_AnnotBboxRow2, hv_AnnotBboxColumn2;
  HTuple  hv_DLSample;

  //This procedure creates a block of samples for a given thread.
  TupleGenConst(hv_NumSamplesPerThread, "", &(*hv_DLSamplesOutput));
  (*hv_Exception) = HTuple();
  //
  //Iterate over the images and fill according sample.
  {
  HTuple end_val5 = hv_NumSamplesPerThread-1;
  HTuple step_val5 = 1;
  for (hv_Index=0; hv_Index.Continue(end_val5, step_val5); hv_Index += step_val5)
  {
    //
    //Get the image information.
    try
    {
      GetDictTuple(hv_ImageList, HTuple(hv_ImageKeys[hv_Index]), &hv_Image);
      GetDictTuple(hv_Image, "file_name", &hv_ImageName);
      GetDictTuple(hv_Image, "id", &hv_ImageID);
    }
    // catch (ExceptionImage) 
    catch (HException &HDevExpDefaultException)
    {
      HDevExpDefaultException.ToHTuple(&hv_ExceptionImage);
      (*hv_Exception) = ("COCO image number "+hv_UniqueIndex)+" does not contain id or file_name.";
      return;
    }
    //
    //Check that the image is found at the given location.
    FileExists(hv_ImageDir+hv_ImageName, &hv_FileExists);
    if (0 != (hv_FileExists.TupleNot()))
    {
      (*hv_Exception) = ((((("COCO image number "+hv_UniqueIndex)+" (id = ")+hv_ImageID)+") could not be found at the location ImageDir + file_name = ")+hv_ImageDir)+hv_ImageName;
      return;
    }
    //
    //Get the annotation data for the selected image.
    TupleFind(hv_AnnotImageIDs, hv_ImageID, &hv_AnnotationIndicesThisImage);
    if (0 != (int(hv_Purpose==HTuple("object_detection"))))
    {
      //For object detection, several annotations per image are possible.
      hv_AnnotClassIDs = HTuple();
      hv_AnnotBboxColumn1s = HTuple();
      hv_AnnotBboxRow1s = HTuple();
      hv_AnnotBboxColumn2s = HTuple();
      hv_AnnotBboxRow2s = HTuple();
      //0 == unknown, -1 == no segmentation annotations, 1 = with segmentation annotations.
      hv_HaveSegmentations = 0;
      GenEmptyObj(&ho_Segmentations);
    }
    if (0 != (int(hv_AnnotationIndicesThisImage==-1)))
    {
      //If no annotation was found for this image.
      hv_AnnotationPerImage = HTuple();
    }
    else
    {
      //Otherwise, process the annotations.
      hv_AnnotationKeysThisImage = HTuple(hv_AnnotationKeys[hv_AnnotationIndicesThisImage]);
      TupleGenConst(hv_AnnotationKeysThisImage.TupleLength(), HTuple::TupleConstant("HNULL"), 
          &hv_AnnotationPerImage);
      hv_AnnotIndexCounter = 0;
      {
      HTuple end_val45 = (hv_AnnotationKeysThisImage.TupleLength())-1;
      HTuple step_val45 = 1;
      for (hv_AnnotIndex=0; hv_AnnotIndex.Continue(end_val45, step_val45); hv_AnnotIndex += step_val45)
      {
        GetDictTuple(hv_AnnotationList, HTuple(hv_AnnotationKeysThisImage[hv_AnnotIndex]), 
            &hv_Annotation);
        //
        if (0 != (int(hv_Purpose==HTuple("object_detection"))))
        {
          try
          {
            GetDictTuple(hv_Annotation, "iscrowd", &hv_IsCrowd);
          }
          // catch (ExceptionIsCrowd) 
          catch (HException &HDevExpDefaultException)
          {
            HDevExpDefaultException.ToHTuple(&hv_ExceptionIsCrowd);
            //If IsCrowd is not set, we assume it is 0 and set IsCrowd=0.
            hv_IsCrowd = 0;
          }
          if (0 != (hv_ReadOnlyNonCrowd.TupleAnd(hv_IsCrowd)))
          {
            continue;
          }
          if (0 != hv_ReadRawAnnotations)
          {
            hv_AnnotationPerImage[hv_AnnotIndexCounter] = hv_Annotation;
          }
          try
          {
            GetDictTuple(hv_Annotation, "category_id", &hv_AnnotClassID);
            GetDictTuple(hv_Annotation, "bbox", &hv_BBox);
            GetDictTuple(hv_BBox, 0, &hv_AnnotBboxColumn1);
            GetDictTuple(hv_BBox, 1, &hv_AnnotBboxRow1);
            GetDictTuple(hv_BBox, 2, &hv_AnnotBboxWidth);
            GetDictTuple(hv_BBox, 3, &hv_AnnotBboxHeight);
          }
          // catch (ExceptionAnnot) 
          catch (HException &HDevExpDefaultException)
          {
            HDevExpDefaultException.ToHTuple(&hv_ExceptionAnnot);
            (*hv_Exception) = ((("A COCO annotation for the COCO image number "+hv_UniqueIndex)+" (id = ")+hv_ImageID)+") does not contain the entry category_id or correct bounding box.";
            return;
          }

          if (0 != hv_ReadMasks)
          {
            try
            {
              GetDictTuple(hv_Annotation, "segmentation", &hv_Segmentation);
              if (0 != (int(hv_HaveSegmentations==-1)))
              {
                (*hv_Exception) = ((("A COCO annotation for the COCO image number "+hv_UniqueIndex)+" (id = ")+hv_ImageID)+") has segmentation annotations only for some of its annotations.";
                return;
              }
              hv_HaveSegmentations = 1;
              try
              {
                convert_coco_segmentation_to_region(&ho_AnnotRegion, hv_Segmentation);
              }
              // catch (ExceptionAnnot) 
              catch (HException &HDevExpDefaultException)
              {
                HDevExpDefaultException.ToHTuple(&hv_ExceptionAnnot);
                (*hv_Exception) = ((("A COCO annotation for the COCO image number "+hv_UniqueIndex)+" (id = ")+hv_ImageID)+") does not contain a readable segmentation.";
                return;
              }
            }
            // catch (Exception) 
            catch (HException &HDevExpDefaultException)
            {
              HDevExpDefaultException.ToHTuple(&(*hv_Exception));
              if (0 != (int(hv_HaveSegmentations==1)))
              {
                //Some, but not all annotations have segmentations. This would mess up the indexing.
                (*hv_Exception) = ((("A COCO annotation for the COCO image number "+hv_UniqueIndex)+" (id = ")+hv_ImageID)+") has segmentation annotations only for some of its annotations.";
                return;
              }
              hv_HaveSegmentations = -1;
              (*hv_Exception) = HTuple();
            }
          }
          //Get the HALCON format for the bounding box coordinates.
          //COCO-format assumes that the origin of the coordinate-system
          //is shifted by (-.5, -.5) compared to the origin of the
          //HALCON coordinate-system.
          hv_AnnotBboxRow1 = hv_AnnotBboxRow1-0.5;
          hv_AnnotBboxColumn1 = hv_AnnotBboxColumn1-0.5;
          hv_AnnotBboxRow2 = hv_AnnotBboxRow1+hv_AnnotBboxHeight;
          hv_AnnotBboxColumn2 = hv_AnnotBboxColumn1+hv_AnnotBboxWidth;
          //Store the annotations.
          hv_AnnotClassIDs[hv_AnnotIndexCounter] = hv_AnnotClassID;
          hv_AnnotBboxColumn1s[hv_AnnotIndexCounter] = hv_AnnotBboxColumn1;
          hv_AnnotBboxRow1s[hv_AnnotIndexCounter] = hv_AnnotBboxRow1;
          hv_AnnotBboxColumn2s[hv_AnnotIndexCounter] = hv_AnnotBboxColumn2;
          hv_AnnotBboxRow2s[hv_AnnotIndexCounter] = hv_AnnotBboxRow2;
          if (0 != (int(hv_HaveSegmentations==1)))
          {
            InsertObj(ho_Segmentations, ho_AnnotRegion, &ho_Segmentations, hv_AnnotIndexCounter+1);
          }
          hv_AnnotIndexCounter += 1;
        }
      }
      }
    }
    //Generate the sample for this image.
    CreateDict(&hv_DLSample);
    SetDictTuple(hv_DLSample, "image_id", hv_ImageID);
    SetDictTuple(hv_DLSample, "image_file_name", hv_ImageName);
    if (0 != (int(hv_Purpose==HTuple("object_detection"))))
    {
      SetDictTuple(hv_DLSample, "bbox_row1", hv_AnnotBboxRow1s);
      SetDictTuple(hv_DLSample, "bbox_col1", hv_AnnotBboxColumn1s);
      SetDictTuple(hv_DLSample, "bbox_row2", hv_AnnotBboxRow2s);
      SetDictTuple(hv_DLSample, "bbox_col2", hv_AnnotBboxColumn2s);
      SetDictTuple(hv_DLSample, "bbox_label_id", hv_AnnotClassIDs);
      if (0 != hv_HaveSegmentations)
      {
        SetDictObject(ho_Segmentations, hv_DLSample, "mask");
      }
    }
    if (0 != hv_ReadRawAnnotations)
    {
      SetDictTuple(hv_DLSample, "coco_raw_annotations", hv_AnnotationPerImage);
    }
    //Remember the sample for this image.
    (*hv_DLSamplesOutput)[hv_Index] = hv_DLSample;
    hv_UniqueIndex += 1;
  }
  }
  //
  return;
}

// Chapter: Deep Learning / Semantic Segmentation and Edge Extraction
// Short Description: Create a block of segmentation samples for a DLDataset. 
void create_dl_dataset_segmentation_samples (HTuple hv_ImageList, HTuple hv_SegmentationList, 
    HTuple hv_NumSamplesPerThread, HTuple hv_UniqueIndex, HTuple *hv_SamplesOutput)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_SampleIndex, hv_Sample, hv_ImageID;

  //This procedure creates a block of samples for a given thread.
  TupleGenConst(hv_NumSamplesPerThread, "", &(*hv_SamplesOutput));
  //Loop over samples.
  {
  HTuple end_val3 = hv_NumSamplesPerThread-1;
  HTuple step_val3 = 1;
  for (hv_SampleIndex=0; hv_SampleIndex.Continue(end_val3, step_val3); hv_SampleIndex += step_val3)
  {
    //Create the dictionary Sample.
    CreateDict(&hv_Sample);
    //Set information about this sample.
    hv_ImageID = hv_UniqueIndex;
    SetDictTuple(hv_Sample, "image_id", hv_ImageID);
    hv_UniqueIndex += 1;
    SetDictTuple(hv_Sample, "image_file_name", HTuple(hv_ImageList[hv_SampleIndex]));
    SetDictTuple(hv_Sample, "segmentation_file_name", HTuple(hv_SegmentationList[hv_SampleIndex]));
    //
    //Append this sample.
    (*hv_SamplesOutput)[hv_SampleIndex] = hv_Sample;
  }
  }
  //
  return;
}

// Chapter: Deep Learning / Multi-Label Classification
// Short Description: Create a multi-label classification model. 
void create_dl_model_multi_label_classification (HTuple hv_Backbone, HTuple hv_GenParam, 
    HTuple *hv_DLModelHandle)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_SemType, hv_KnownKeys, hv_GenParamKeys;
  HTuple  hv_I, hv_Key, hv_Index, hv_KeyExists, hv_ErrorMsgNoDockingLayers;
  HTuple  hv_BackboneDockingLayers, hv_Exception, hv_ClassIDsBackbone;
  HTuple  hv_InitialNumClasses, hv_DockingLayer, hv_GAPLayer;
  HTuple  hv_DLLayerClassify, hv_Target, hv_DLLayerActivation;
  HTuple  hv_DLLayerLossFocal, hv_Params, hv_ParamIdx, hv_Param;
  HTuple  hv_Value;

  //This procedure creates a multi-label classification model based on a backbone.
  //
  TupleSemType(hv_Backbone, &hv_SemType);
  if (0 != (int(hv_SemType==HTuple("string"))))
  {
    ReadDlModel(hv_Backbone, &hv_Backbone);
  }
  else if (0 != (int(hv_SemType!=HTuple("dl_model"))))
  {
    throw HException("Unknown sem_type for input Backbone: "+hv_SemType);
  }
  //
  //Generic parameter handling.
  if (0 != (int((hv_GenParam.TupleLength())==0)))
  {
    //If no parameter is given, we will initialize default values later.
    CreateDict(&hv_GenParam);
  }
  //
  //Check for unknown keys.
  hv_KnownKeys = "backbone_docking_layer";
  GetDictParam(hv_GenParam, "keys", HTuple(), &hv_GenParamKeys);
  {
  HTuple end_val18 = (hv_GenParamKeys.TupleLength())-1;
  HTuple step_val18 = 1;
  for (hv_I=0; hv_I.Continue(end_val18, step_val18); hv_I += step_val18)
  {
    hv_Key = HTuple(hv_GenParamKeys[hv_I]);
    TupleFindFirst(hv_KnownKeys, hv_Key, &hv_Index);
    if (0 != (int(hv_Index==-1)))
    {
      throw HException(((("The generic parameter key \""+hv_Key)+"\" is unknown. The known keys are: [ ")+((hv_KnownKeys+" ").TupleSum()))+"]");
    }
  }
  }
  //
  //Set a default backbone_docking_layer if needed.
  GetDictParam(hv_GenParam, "key_exists", "backbone_docking_layer", &hv_KeyExists);
  if (0 != (hv_KeyExists.TupleNot()))
  {
    //By default we use the last item of backbone_docking_layer as the docking layer.
    //However even earlier layers might work and reduce runtime/memory usage.
    hv_ErrorMsgNoDockingLayers = "The given backbone model has no docking layers defined. ";
    hv_ErrorMsgNoDockingLayers += HTuple("You have to define a docking layer name directly via ");
    hv_ErrorMsgNoDockingLayers += HTuple("GenParam.backbone_docking_layer.");
    //
    try
    {
      GetDlModelParam(hv_Backbone, "backbone_docking_layers", &hv_BackboneDockingLayers);
    }
    // catch (Exception) 
    catch (HException &HDevExpDefaultException)
    {
      HDevExpDefaultException.ToHTuple(&hv_Exception);
      if (0 != (int(HTuple(hv_Exception[0])==7713)))
      {
        throw HException(hv_ErrorMsgNoDockingLayers);
      }
      else
      {
        throw HException(hv_Exception);
      }
    }
    if (0 != (int((hv_BackboneDockingLayers.TupleLength())==0)))
    {
      throw HException(hv_ErrorMsgNoDockingLayers);
    }
    SetDictTuple(hv_GenParam, "backbone_docking_layer", HTuple(hv_BackboneDockingLayers[(hv_BackboneDockingLayers.TupleLength())-1]));
  }
  //
  //Get the initial number of classes.
  //Later the created model can be changed for any number of classes.
  try
  {
    GetDlModelParam(hv_Backbone, "class_ids", &hv_ClassIDsBackbone);
  }
  // catch (Exception) 
  catch (HException &HDevExpDefaultException)
  {
    HDevExpDefaultException.ToHTuple(&hv_Exception);
    if (0 != (int(HTuple(hv_Exception[0])==7713)))
    {
      hv_ClassIDsBackbone.Clear();
      hv_ClassIDsBackbone[0] = 0;
      hv_ClassIDsBackbone[1] = 1;
    }
    else
    {
      throw HException(hv_Exception);
    }
  }
  hv_InitialNumClasses = hv_ClassIDsBackbone.TupleLength();
  GetDlModelLayer(hv_Backbone, hv_GenParam.TupleGetDictTuple("backbone_docking_layer"), 
      &hv_DockingLayer);
  //
  CreateDlLayerPooling(hv_DockingLayer, "multi_label_pooling", 1, 1, "none", "global_average", 
      HTuple(), HTuple(), &hv_GAPLayer);
  CreateDlLayerConvolution(hv_GAPLayer, "multi_label_classify", 1, 1, 1, hv_InitialNumClasses, 
      1, "none", "none", HTuple(), HTuple(), &hv_DLLayerClassify);
  CreateDlLayerInput("multi_label_target", (HTuple(1).Append(1)).TupleConcat(hv_InitialNumClasses), 
      HTuple(), HTuple(), &hv_Target);
  CreateDlLayerActivation(hv_DLLayerClassify, "multi_label_sigmoid", "sigmoid", HTuple(), 
      HTuple(), &hv_DLLayerActivation);
  CreateDlLayerLossFocal(hv_DLLayerClassify, hv_Target, HTuple(), HTuple(), "multi_label_loss", 
      1.0, 0.0, 0.5, "sigmoid_focal_binary", HTuple(), HTuple(), &hv_DLLayerLossFocal);
  //
  CreateDlModel(hv_DLLayerLossFocal.TupleConcat(hv_DLLayerActivation), &(*hv_DLModelHandle));
  SetDlModelParam((*hv_DLModelHandle), "type", "multi_label_classification");
  //
  //Get some parameters from the backbone as defaults.
  hv_Params.Clear();
  hv_Params[0] = "class_ids";
  hv_Params[1] = "class_names";
  hv_Params[2] = "solver_type";
  hv_Params[3] = "learning_rate";
  hv_Params[4] = "momentum";
  hv_Params[5] = "weight_prior";
  {
  HTuple end_val75 = (hv_Params.TupleLength())-1;
  HTuple step_val75 = 1;
  for (hv_ParamIdx=0; hv_ParamIdx.Continue(end_val75, step_val75); hv_ParamIdx += step_val75)
  {
    hv_Param = HTuple(hv_Params[hv_ParamIdx]);
    try
    {
      GetDlModelParam(hv_Backbone, hv_Param, &hv_Value);
    }
    // catch (Exception) 
    catch (HException &HDevExpDefaultException)
    {
      HDevExpDefaultException.ToHTuple(&hv_Exception);
      //Ignore parameters that do not belong to backbone.
      continue;
    }
    SetDlModelParam((*hv_DLModelHandle), hv_Param, hv_Value);
  }
  }
  return;
}

// Chapter: Deep Learning / Model
// Short Description: Create a dictionary with preprocessing parameters. 
void create_dl_preprocess_param (HTuple hv_DLModelType, HTuple hv_ImageWidth, HTuple hv_ImageHeight, 
    HTuple hv_ImageNumChannels, HTuple hv_ImageRangeMin, HTuple hv_ImageRangeMax, 
    HTuple hv_NormalizationType, HTuple hv_DomainHandling, HTuple hv_IgnoreClassIDs, 
    HTuple hv_SetBackgroundID, HTuple hv_ClassIDsBackground, HTuple hv_GenParam, 
    HTuple *hv_DLPreprocessParam)
{

  // Local control variables
  HTuple  hv_GenParamNames, hv_GenParamIndex, hv_GenParamValue;
  HTuple  hv_KeysExist, hv_InstanceType, hv_IsInstanceSegmentation;

  //
  //This procedure creates a dictionary with all parameters needed for preprocessing.
  //
  CreateDict(&(*hv_DLPreprocessParam));
  SetDictTuple((*hv_DLPreprocessParam), "model_type", hv_DLModelType);
  SetDictTuple((*hv_DLPreprocessParam), "image_width", hv_ImageWidth);
  SetDictTuple((*hv_DLPreprocessParam), "image_height", hv_ImageHeight);
  SetDictTuple((*hv_DLPreprocessParam), "image_num_channels", hv_ImageNumChannels);
  if (0 != (int(hv_ImageRangeMin==HTuple())))
  {
    SetDictTuple((*hv_DLPreprocessParam), "image_range_min", -127);
  }
  else
  {
    SetDictTuple((*hv_DLPreprocessParam), "image_range_min", hv_ImageRangeMin);
  }
  if (0 != (int(hv_ImageRangeMax==HTuple())))
  {
    SetDictTuple((*hv_DLPreprocessParam), "image_range_max", 128);
  }
  else
  {
    SetDictTuple((*hv_DLPreprocessParam), "image_range_max", hv_ImageRangeMax);
  }
  SetDictTuple((*hv_DLPreprocessParam), "normalization_type", hv_NormalizationType);
  //Replace possible legacy parameters.
  replace_legacy_preprocessing_parameters((*hv_DLPreprocessParam));
  SetDictTuple((*hv_DLPreprocessParam), "domain_handling", hv_DomainHandling);
  //
  //Set segmentation and '3d_gripping_point_detection' parameters.
  if (0 != (HTuple(int(hv_DLModelType==HTuple("segmentation"))).TupleOr(int(hv_DLModelType==HTuple("3d_gripping_point_detection")))))
  {
    SetDictTuple((*hv_DLPreprocessParam), "ignore_class_ids", hv_IgnoreClassIDs);
    SetDictTuple((*hv_DLPreprocessParam), "set_background_id", hv_SetBackgroundID);
    SetDictTuple((*hv_DLPreprocessParam), "class_ids_background", hv_ClassIDsBackground);
  }
  //
  //Set default values of generic parameters.
  SetDictTuple((*hv_DLPreprocessParam), "augmentation", "false");
  //
  //Set generic parameters.
  if (0 != (int(hv_GenParam!=HTuple())))
  {
    GetDictParam(hv_GenParam, "keys", HTuple(), &hv_GenParamNames);
    {
    HTuple end_val36 = (hv_GenParamNames.TupleLength())-1;
    HTuple step_val36 = 1;
    for (hv_GenParamIndex=0; hv_GenParamIndex.Continue(end_val36, step_val36); hv_GenParamIndex += step_val36)
    {
      GetDictTuple(hv_GenParam, HTuple(hv_GenParamNames[hv_GenParamIndex]), &hv_GenParamValue);
      SetDictTuple((*hv_DLPreprocessParam), HTuple(hv_GenParamNames[hv_GenParamIndex]), 
          hv_GenParamValue);
    }
    }
  }
  //
  //Set necessary default values.
  if (0 != (int(hv_DLModelType==HTuple("detection"))))
  {
    GetDictParam((*hv_DLPreprocessParam), "key_exists", ((HTuple("instance_type").Append("ignore_direction")).Append("instance_segmentation")), 
        &hv_KeysExist);
    if (0 != (HTuple(hv_KeysExist[0]).TupleNot()))
    {
      SetDictTuple((*hv_DLPreprocessParam), "instance_type", "rectangle1");
    }
    //Set default for 'ignore_direction' only if instance_type is 'rectangle2'.
    GetDictTuple((*hv_DLPreprocessParam), "instance_type", &hv_InstanceType);
    if (0 != (HTuple(int(hv_InstanceType==HTuple("rectangle2"))).TupleAnd(HTuple(hv_KeysExist[1]).TupleNot())))
    {
      SetDictTuple((*hv_DLPreprocessParam), "ignore_direction", 0);
    }
    //In case of instance_segmentation we overwrite the instance_type to mask.
    if (0 != (HTuple(hv_KeysExist[2])))
    {
      GetDictTuple((*hv_DLPreprocessParam), "instance_segmentation", &hv_IsInstanceSegmentation);
      if (0 != (int(((((HTuple(1).Append(0)).Append("true")).Append("false")).TupleFind(hv_IsInstanceSegmentation))==-1)))
      {
        throw HException(("Invalid generic parameter for 'instance_segmentation': "+hv_IsInstanceSegmentation)+HTuple(", only true and false are allowed"));
      }
      if (0 != (HTuple(int(hv_IsInstanceSegmentation==HTuple("true"))).TupleOr(int(hv_IsInstanceSegmentation==1))))
      {
        SetDictTuple((*hv_DLPreprocessParam), "instance_type", "mask");
      }
    }
  }
  //
  //Check the validity of the preprocessing parameters.
  check_dl_preprocess_param((*hv_DLPreprocessParam));
  //
  return;
}

// Chapter: Deep Learning / Model
// Short Description: Create a dictionary with the preprocessing parameters based on a given DL model. 
void create_dl_preprocess_param_from_model (HTuple hv_DLModelHandle, HTuple hv_NormalizationType, 
    HTuple hv_DomainHandling, HTuple hv_SetBackgroundID, HTuple hv_ClassIDsBackground, 
    HTuple hv_GenParam, HTuple *hv_DLPreprocessParam)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_ModelType, hv_ImageWidth, hv_ImageHeight;
  HTuple  hv_ImageNumChannels, hv_ImageRangeMin, hv_ImageRangeMax;
  HTuple  hv_IgnoreClassIDs, hv_InstanceType, hv_IsInstanceSegmentation;
  HTuple  hv_IgnoreDirection, hv_ClassIDsNoOrientation;

  //
  //This procedure creates a dictionary with all parameters needed for preprocessing
  //according to a model provided through DLModelHandle.
  //
  //Get the relevant model parameters.
  GetDlModelParam(hv_DLModelHandle, "type", &hv_ModelType);
  GetDlModelParam(hv_DLModelHandle, "image_width", &hv_ImageWidth);
  GetDlModelParam(hv_DLModelHandle, "image_height", &hv_ImageHeight);
  GetDlModelParam(hv_DLModelHandle, "image_num_channels", &hv_ImageNumChannels);
  GetDlModelParam(hv_DLModelHandle, "image_range_min", &hv_ImageRangeMin);
  GetDlModelParam(hv_DLModelHandle, "image_range_max", &hv_ImageRangeMax);
  hv_IgnoreClassIDs = HTuple();
  //
  //Get model specific parameters.
  if (0 != (HTuple(int(hv_ModelType==HTuple("anomaly_detection"))).TupleOr(int(hv_ModelType==HTuple("gc_anomaly_detection")))))
  {
    //No specific parameters for both anomaly detection
    //and Global Context Anomaly Detection model types.
  }
  else if (0 != (HTuple(int(hv_ModelType==HTuple("classification"))).TupleOr(int(hv_ModelType==HTuple("multi_label_classification")))))
  {
    //No classification specific parameters.
  }
  else if (0 != (int(hv_ModelType==HTuple("counting"))))
  {
    //No counting specific parameters.
  }
  else if (0 != (int(hv_ModelType==HTuple("detection"))))
  {
    //Get detection specific parameters.
    //If GenParam has not been created yet, create it to add new generic parameters.
    if (0 != (int((hv_GenParam.TupleLength())==0)))
    {
      CreateDict(&hv_GenParam);
    }
    //Add instance_type.
    GetDlModelParam(hv_DLModelHandle, "instance_type", &hv_InstanceType);
    //If the model can do instance segmentation, the preprocessing instance_type
    //needs to be 'mask'.
    GetDlModelParam(hv_DLModelHandle, "instance_segmentation", &hv_IsInstanceSegmentation);
    if (0 != (int(hv_IsInstanceSegmentation==HTuple("true"))))
    {
      SetDictTuple(hv_GenParam, "instance_type", "mask");
    }
    else
    {
      SetDictTuple(hv_GenParam, "instance_type", hv_InstanceType);
    }
    //For instance_type 'rectangle2', add the boolean ignore_direction and class IDs without orientation.
    if (0 != (int(hv_InstanceType==HTuple("rectangle2"))))
    {
      GetDlModelParam(hv_DLModelHandle, "ignore_direction", &hv_IgnoreDirection);
      if (0 != (int(hv_IgnoreDirection==HTuple("true"))))
      {
        SetDictTuple(hv_GenParam, "ignore_direction", 1);
      }
      else if (0 != (int(hv_IgnoreDirection==HTuple("false"))))
      {
        SetDictTuple(hv_GenParam, "ignore_direction", 0);
      }
      GetDlModelParam(hv_DLModelHandle, "class_ids_no_orientation", &hv_ClassIDsNoOrientation);
      SetDictTuple(hv_GenParam, "class_ids_no_orientation", hv_ClassIDsNoOrientation);
    }
  }
  else if (0 != (HTuple(int(hv_ModelType==HTuple("ocr_detection"))).TupleOr(int(hv_ModelType==HTuple("ocr_recognition")))))
  {
    //No ocr specific parameters.
  }
  else if (0 != (int(hv_ModelType==HTuple("segmentation"))))
  {
    //Get segmentation specific parameters.
    GetDlModelParam(hv_DLModelHandle, "ignore_class_ids", &hv_IgnoreClassIDs);
  }
  else if (0 != (int(hv_ModelType==HTuple("3d_gripping_point_detection"))))
  {
    //The input image is expected to be a single channel image.
    hv_ImageNumChannels = 1;
  }
  else
  {
    throw HException(("Current model type is not supported: \""+hv_ModelType)+"\"");
  }
  //
  //Create the dictionary with the preprocessing parameters returned by this procedure.
  create_dl_preprocess_param(hv_ModelType, hv_ImageWidth, hv_ImageHeight, hv_ImageNumChannels, 
      hv_ImageRangeMin, hv_ImageRangeMax, hv_NormalizationType, hv_DomainHandling, 
      hv_IgnoreClassIDs, hv_SetBackgroundID, hv_ClassIDsBackground, hv_GenParam, 
      &(*hv_DLPreprocessParam));
  //
  return;
}

// Chapter: Deep Learning / Model
// Short Description: Create a training parameter dictionary which is used in train_dl_model. 
void create_dl_train_param (HTuple hv_DLModelHandle, HTuple hv_NumEpochs, HTuple hv_EvaluationIntervalEpochs, 
    HTuple hv_EnableDisplay, HTuple hv_RandomSeed, HTuple hv_GenParamName, HTuple hv_GenParamValue, 
    HTuple *hv_TrainParam)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_ModelType, hv_AvailableGenParam, hv_IndexGenParam;
  HTuple  hv_IndexFind, hv_IsString, hv_TrainParamAnomaly;
  HTuple  hv_DomainRatioKeyExists, hv_ErrorThresholdKeyExists;
  HTuple  hv_RegularizationNoiseKeyExists, hv_DisplayParam;
  HTuple  hv_EvaluateBeforeTrain, hv_EvaluationParam, hv_AugmentationParam;
  HTuple  hv_ClassIDsNoOrientation, hv_Exception, hv_ChangeStrategies;
  HTuple  hv_Indices, hv_SerializationStrategy, hv_SerializationStrategies;
  HTuple  hv_Seconds, hv_SetDisplayParam, hv_EvaluationComparisonKeys;
  HTuple  hv_ConvertToMean, hv_Index, hv_FoundIndices;

  //
  //This procedure creates a dictionary with all needed training parameters,
  //as required by train_dl_model as input.
  //
  //Check length of input GenParam tuple.
  if (0 != (int((hv_GenParamName.TupleLength())!=(hv_GenParamValue.TupleLength()))))
  {
    throw HException("GenParamName and GenParamValue have to have the same length.");
  }
  //
  //Some default parameters depend on model type.
  GetDlModelParam(hv_DLModelHandle, "type", &hv_ModelType);
  if (0 != (HTuple(HTuple(HTuple(HTuple(HTuple(HTuple(HTuple(HTuple(int(hv_ModelType!=HTuple("anomaly_detection"))).TupleAnd(int(hv_ModelType!=HTuple("classification")))).TupleAnd(int(hv_ModelType!=HTuple("multi_label_classification")))).TupleAnd(int(hv_ModelType!=HTuple("detection")))).TupleAnd(int(hv_ModelType!=HTuple("gc_anomaly_detection")))).TupleAnd(int(hv_ModelType!=HTuple("ocr_recognition")))).TupleAnd(int(hv_ModelType!=HTuple("ocr_detection")))).TupleAnd(int(hv_ModelType!=HTuple("segmentation")))).TupleAnd(int(hv_ModelType!=HTuple("3d_gripping_point_detection")))))
  {
    throw HException(("Current model type is not supported: \""+hv_ModelType)+"\"");
  }
  //
  //Check if the given GenParamName strings are available.
  if (0 != (int(hv_ModelType!=HTuple("anomaly_detection"))))
  {
    hv_AvailableGenParam.Clear();
    hv_AvailableGenParam[0] = "evaluate";
    hv_AvailableGenParam[1] = "augment";
    hv_AvailableGenParam[2] = "change";
    hv_AvailableGenParam[3] = "serialize";
    hv_AvailableGenParam[4] = "display";
    hv_AvailableGenParam[5] = "evaluate_before_train";
    if (0 != (int(hv_ModelType==HTuple("gc_anomaly_detection"))))
    {
      hv_AvailableGenParam.Clear();
      hv_AvailableGenParam[0] = "augment";
      hv_AvailableGenParam[1] = "change";
      hv_AvailableGenParam[2] = "serialize";
      hv_AvailableGenParam[3] = "display";
    }
  }
  else
  {
    hv_AvailableGenParam = "anomaly";
  }
  {
  HTuple end_val24 = (hv_GenParamName.TupleLength())-1;
  HTuple step_val24 = 1;
  for (hv_IndexGenParam=0; hv_IndexGenParam.Continue(end_val24, step_val24); hv_IndexGenParam += step_val24)
  {
    hv_IndexFind = hv_AvailableGenParam.TupleFind(HTuple(hv_GenParamName[hv_IndexGenParam]));
    if (0 != (int(hv_IndexFind==-1)))
    {
      throw HException(("The provided GenParamName "+HTuple(hv_GenParamName[hv_IndexGenParam]))+" is invalid.");
    }
  }
  }
  //
  //Check if display is enabled.
  TupleIsString(hv_EnableDisplay, &hv_IsString);
  if (0 != hv_IsString)
  {
    hv_EnableDisplay = int(hv_EnableDisplay==HTuple("true"));
  }
  else
  {
    hv_EnableDisplay = int(hv_EnableDisplay==1);
  }
  //
  //Initialize the dictionary holding the training parameters.
  CreateDict(&(*hv_TrainParam));
  //
  //** User supplied parameters: ***
  //
  //Set training parameters for anomaly detection models.
  if (0 != (int(hv_ModelType==HTuple("anomaly_detection"))))
  {
    get_genparam_single_value(hv_GenParamName, hv_GenParamValue, "anomaly", &hv_TrainParamAnomaly);
    //Set default values in case no values are provided.
    if (0 != (int(hv_TrainParamAnomaly==HTuple())))
    {
      CreateDict(&hv_TrainParamAnomaly);
    }
    GetDictParam(hv_TrainParamAnomaly, "key_exists", "domain_ratio", &hv_DomainRatioKeyExists);
    if (0 != (hv_DomainRatioKeyExists.TupleNot()))
    {
      SetDictTuple(hv_TrainParamAnomaly, "domain_ratio", 0.1);
    }
    GetDictParam(hv_TrainParamAnomaly, "key_exists", "error_threshold", &hv_ErrorThresholdKeyExists);
    if (0 != (hv_ErrorThresholdKeyExists.TupleNot()))
    {
      SetDictTuple(hv_TrainParamAnomaly, "error_threshold", 0.001);
    }
    GetDictParam(hv_TrainParamAnomaly, "key_exists", "regularization_noise", &hv_RegularizationNoiseKeyExists);
    if (0 != (hv_RegularizationNoiseKeyExists.TupleNot()))
    {
      SetDictTuple(hv_TrainParamAnomaly, "regularization_noise", 0.0001);
    }
    //
    SetDictTuple(hv_TrainParamAnomaly, "max_num_epochs", hv_NumEpochs);
    SetDictTuple((*hv_TrainParam), "anomaly_param", hv_TrainParamAnomaly);
    CreateDict(&hv_DisplayParam);
    SetDictTuple(hv_DisplayParam, "enabled", hv_EnableDisplay);
    SetDictTuple((*hv_TrainParam), "display_param", hv_DisplayParam);
    return;
  }
  //
  //Set training parameters for all model types except 'anomaly_detection'.
  //
  //Number of epochs to train the model on the train split of the dataset.
  SetDictTuple((*hv_TrainParam), "num_epochs", hv_NumEpochs);
  //
  //Interval (in epochs) to evaluate the model on the validation split of the dataset.
  if (0 != (int(hv_ModelType==HTuple("gc_anomaly_detection"))))
  {
    //For models of type 'gc_anomaly_detection' no evaluation can be done.
    SetDictTuple((*hv_TrainParam), "evaluation_interval_epochs", 0);
  }
  else
  {
    SetDictTuple((*hv_TrainParam), "evaluation_interval_epochs", hv_EvaluationIntervalEpochs);
  }
  //
  //Transfer the parameter defining if an evaluation before training is to be done.
  get_genparam_single_value(hv_GenParamName, hv_GenParamValue, "evaluate_before_train", 
      &hv_EvaluateBeforeTrain);
  SetDictTuple((*hv_TrainParam), "evaluate_before_train", hv_EvaluateBeforeTrain);
  //
  //Transfer evaluation parameters used in further steps.
  get_genparam_single_value(hv_GenParamName, hv_GenParamValue, "evaluate", &hv_EvaluationParam);
  SetDictTuple((*hv_TrainParam), "evaluation_param", hv_EvaluationParam);
  //
  //Transfer augmentation parameters used in further steps.
  get_genparam_single_value(hv_GenParamName, hv_GenParamValue, "augment", &hv_AugmentationParam);
  if (0 != (int(hv_ModelType==HTuple("detection"))))
  {
    //In addition, add class IDs without orientation, since these classes require
    //special treatment during the augmentation.
    try
    {
      GetDlModelParam(hv_DLModelHandle, "class_ids_no_orientation", &hv_ClassIDsNoOrientation);
    }
    // catch (Exception) 
    catch (HException &HDevExpDefaultException)
    {
      HDevExpDefaultException.ToHTuple(&hv_Exception);
      hv_ClassIDsNoOrientation = HTuple();
    }
    if (0 != (int((hv_ClassIDsNoOrientation.TupleLength())>0)))
    {
      if (0 != (int(hv_AugmentationParam==HTuple())))
      {
        CreateDict(&hv_AugmentationParam);
      }
      SetDictTuple(hv_AugmentationParam, "class_ids_no_orientation", hv_ClassIDsNoOrientation);
    }
  }
  SetDictTuple((*hv_TrainParam), "augmentation_param", hv_AugmentationParam);
  //
  //Change strategies for any parameters that need to be changed during training.
  get_genparam_single_value(hv_GenParamName, hv_GenParamValue, "change", &hv_ChangeStrategies);
  SetDictTuple((*hv_TrainParam), "change_strategies", hv_ChangeStrategies);
  //
  //Serialization strategies used during training.
  hv_Indices = hv_GenParamName.TupleFind("serialize");
  if (0 != (HTuple(int((hv_Indices.TupleLength())==0)).TupleOr(int(hv_Indices==-1))))
  {
    //Set a default in case no value is provided.
    CreateDict(&hv_SerializationStrategy);
    SetDictTuple(hv_SerializationStrategy, "type", "best");
    SetDictTuple(hv_SerializationStrategy, "basename", "model_best");
    hv_SerializationStrategies = hv_SerializationStrategy;
  }
  else
  {
    //Set user provided values.
    hv_SerializationStrategies = HTuple(hv_GenParamValue[hv_Indices]);
  }
  SetDictTuple((*hv_TrainParam), "serialization_strategies", hv_SerializationStrategies);
  //
  //Get random seed or set a useful default value.
  if (0 != (int((hv_RandomSeed.TupleLength())>0)))
  {
    SetDictTuple((*hv_TrainParam), "seed_rand", hv_RandomSeed);
  }
  else
  {
    //If no random seed is given we will use system time as a default.
    CountSeconds(&hv_Seconds);
    hv_RandomSeed = hv_Seconds.TupleInt();
    SetDictTuple((*hv_TrainParam), "seed_rand", hv_RandomSeed);
  }
  //
  //** Display parameters: ***
  //
  //Create display parameter dictionary.
  get_genparam_single_value(hv_GenParamName, hv_GenParamValue, "display", &hv_SetDisplayParam);
  if (0 != (int(hv_SetDisplayParam!=HTuple())))
  {
    hv_DisplayParam = hv_SetDisplayParam;
  }
  else
  {
    CreateDict(&hv_DisplayParam);
  }
  //
  SetDictTuple(hv_DisplayParam, "enabled", hv_EnableDisplay);
  SetDictTuple((*hv_TrainParam), "display_param", hv_DisplayParam);
  //
  //** Generic internal defaults: ***
  //
  //Default update interval (in seconds) of TrainInfo calculation and text/plot updates
  //in case display is enabled.
  SetDictTuple((*hv_TrainParam), "update_interval_seconds", 2);
  //
  //Evaluation comparison keys. Note, that internally only those keys apply which
  //are really available. No error is thrown as long as a valid key is given.
  //Hence, we use the major defaults here for classification ('top1_error'),
  //for detection ('mean_ap'), and for segmentation ('mean_iou') if no valid key
  //is given.
  hv_EvaluationComparisonKeys = HTuple();
  //
  try
  {
    GetDictTuple(hv_EvaluationParam, "measures", &hv_EvaluationComparisonKeys);
  }
  // catch (Exception) 
  catch (HException &HDevExpDefaultException)
  {
    HDevExpDefaultException.ToHTuple(&hv_Exception);
  }
  //
  if (0 != (int(hv_EvaluationComparisonKeys==HTuple())))
  {
    if (0 != (int(hv_ModelType==HTuple("classification"))))
    {
      hv_EvaluationComparisonKeys = "top1_error";
    }
    else if (0 != (int(hv_ModelType==HTuple("multi_label_classification"))))
    {
      hv_EvaluationComparisonKeys = "mean_ap";
    }
    else if (0 != (int(hv_ModelType==HTuple("detection"))))
    {
      hv_EvaluationComparisonKeys = "mean_ap";
    }
    else if (0 != (int(hv_ModelType==HTuple("gc_anomaly_detection"))))
    {
      hv_EvaluationComparisonKeys = "none";
    }
    else if (0 != (int(hv_ModelType==HTuple("ocr_detection"))))
    {
      hv_EvaluationComparisonKeys = "f_score";
    }
    else if (0 != (int(hv_ModelType==HTuple("ocr_recognition"))))
    {
      hv_EvaluationComparisonKeys = "accuracy";
    }
    else if (0 != (int(hv_ModelType==HTuple("segmentation"))))
    {
      hv_EvaluationComparisonKeys = "mean_iou";
    }
    else if (0 != (int(hv_ModelType==HTuple("3d_gripping_point_detection"))))
    {
      hv_EvaluationComparisonKeys = "mean_iou";
    }
  }

  if (0 != (int(hv_ModelType!=HTuple("ocr_detection"))))
  {
    //If the evaluation metric is 'precision', 'recall', 'f_score', or
    //'soap' we always take the mean value.
    hv_ConvertToMean.Clear();
    hv_ConvertToMean[0] = "precision";
    hv_ConvertToMean[1] = "recall";
    hv_ConvertToMean[2] = "f_score";
    hv_ConvertToMean[3] = "soap";
    {
    HTuple end_val195 = (hv_ConvertToMean.TupleLength())-1;
    HTuple step_val195 = 1;
    for (hv_Index=0; hv_Index.Continue(end_val195, step_val195); hv_Index += step_val195)
    {
      hv_FoundIndices = (hv_EvaluationComparisonKeys.TupleEqualElem(HTuple(hv_ConvertToMean[hv_Index]))).TupleFind(1);
      if (0 != (int(hv_FoundIndices!=-1)))
      {
        hv_EvaluationComparisonKeys[hv_FoundIndices] = "mean_"+HTuple(hv_EvaluationComparisonKeys[hv_FoundIndices]);
        if (0 != (int(HTuple(hv_ConvertToMean[hv_Index])==HTuple("soap"))))
        {
          hv_EvaluationComparisonKeys[hv_FoundIndices] = HTuple(hv_EvaluationComparisonKeys[hv_FoundIndices])+"_tp";
        }
      }
    }
    }
  }
  //
  SetDictTuple((*hv_TrainParam), "evaluation_comparison_keys", hv_EvaluationComparisonKeys);
  //
  //Number of samples used to average the loss during training. Note, this is used for display
  //and information calculation only and does not have an effect on training the model.
  SetDictTuple((*hv_TrainParam), "num_samples_mean_loss", 1000);
  //
  return;
}

// Chapter: Deep Learning / Model
// Short Description: Generate a dictionary EvalParams, which contains default values for evaluation parameters. 
void create_evaluation_default_param (HTuple hv_EvaluationType, HTuple hv_ClassIDsModel, 
    HTuple *hv_EvalParams)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_AvailableEvaluationTypes, hv_EvaluationTypesStr;
  HTuple  hv_Indices, hv_EvaluateInstances, hv_Measures, hv_GrippingPointParams;
  HTuple  hv_AreaRanges, hv_AllocationBlockLength;

  //
  //This procedure generates a dictionary EvalParams,
  //which contains default values for evaluation parameters.
  //Depending on the evaluation type, the corresponding default parameters and values are set.
  //The class IDs that the model can predict must be given via ClassIDsModel.
  //
  //Check inputs.
  hv_AvailableEvaluationTypes.Clear();
  hv_AvailableEvaluationTypes[0] = "3d_gripping_point_detection";
  hv_AvailableEvaluationTypes[1] = "anomaly_detection";
  hv_AvailableEvaluationTypes[2] = "classification";
  hv_AvailableEvaluationTypes[3] = "multi_label_classification";
  hv_AvailableEvaluationTypes[4] = "detection";
  hv_AvailableEvaluationTypes[5] = "gc_anomaly_detection";
  hv_AvailableEvaluationTypes[6] = "ocr_detection";
  hv_AvailableEvaluationTypes[7] = "ocr_recognition";
  hv_AvailableEvaluationTypes[8] = "segmentation";
  TupleGenConst((2*(hv_AvailableEvaluationTypes.TupleLength()))-1, HTuple("','"), 
      &hv_EvaluationTypesStr);
  hv_EvaluationTypesStr[HTuple::TupleGenSequence(0,hv_EvaluationTypesStr.TupleLength(),2)] = hv_AvailableEvaluationTypes;
  hv_EvaluationTypesStr = hv_EvaluationTypesStr.TupleSum();
  TupleFind(hv_AvailableEvaluationTypes, hv_EvaluationType, &hv_Indices);
  if (0 != (HTuple(int(hv_Indices==-1)).TupleOr(int(hv_Indices==HTuple()))))
  {
    throw HException(((("Unknown evaluation_type: "+hv_EvaluationType)+". Choose one of ['")+hv_EvaluationTypesStr)+"']");
  }
  //
  if (0 != (int((hv_ClassIDsModel.TupleLength())<1)))
  {
    if (0 != (int(hv_EvaluationType==HTuple("ocr_detection"))))
    {
      hv_ClassIDsModel = 0;
    }
    else
    {
      throw HException("ClassIDsModel should have at least one entry");
    }
  }
  //
  //Initialize EvalParams.
  CreateDict(&(*hv_EvalParams));
  SetDictTuple((*hv_EvalParams), "evaluation_type", hv_EvaluationType);
  //
  //Set the class IDs.
  SetDictTuple((*hv_EvalParams), "class_ids", hv_ClassIDsModel);
  SetDictTuple((*hv_EvalParams), "num_classes", hv_ClassIDsModel.TupleLength());
  //
  //Set specific parameters depending on the evaluation type.
  hv_EvaluateInstances = 0;
  if (0 != (int(hv_EvaluationType==HTuple("3d_gripping_point_detection"))))
  {
    //
    //Set default 3D Gripping Point Detection measures.
    hv_Measures.Clear();
    hv_Measures[0] = "mean_pro";
    hv_Measures[1] = "mean_precision";
    hv_Measures[2] = "mean_iou";
    //
    //There are no ignored classes for this model type.
    SetDictTuple((*hv_EvalParams), "ignore_class_ids", HTuple());
    //
    //Set default 3D gripping point generation parameters.
    CreateDict(&hv_GrippingPointParams);
    check_dl_3d_gripping_points_and_poses_params(hv_GrippingPointParams);
    SetDictTuple((*hv_EvalParams), "gripping_point_params", hv_GrippingPointParams);
  }
  else if (0 != (HTuple(int(hv_EvaluationType==HTuple("anomaly_detection"))).TupleOr(int(hv_EvaluationType==HTuple("gc_anomaly_detection")))))
  {
    //
    //Set default image level measures.
    hv_Measures = "anomaly_score_histogram";
  }
  else if (0 != (int(hv_EvaluationType==HTuple("classification"))))
  {
    //
    //Set default classification measures.
    hv_Measures = "top1_error";
    //
    //Per default all classes are used for evaluation.
    SetDictTuple((*hv_EvalParams), "class_ids_to_evaluate", "global");
  }
  else if (0 != (int(hv_EvaluationType==HTuple("multi_label_classification"))))
  {
    //
    //Set default detection measures.
    hv_Measures = "mean_ap";
    //Interpolate the precision-recall curves per default.
    SetDictTuple((*hv_EvalParams), "interpolate_pr_curves", 1);
    //
  }
  else if (0 != (int(hv_EvaluationType==HTuple("detection"))))
  {
    //
    //Set default detection measures.
    hv_Measures = "mean_ap";
    //
    //Set detection-specific default values.
    hv_EvaluateInstances = 1;
    SetDictTuple((*hv_EvalParams), "instance_type", "rectangle1");
    //Generate ten IoU-thresholds from 0.5 to 0.95 in steps of 0.05.
    SetDictTuple((*hv_EvalParams), "iou_threshold", HTuple::TupleGenSequence(0.5,0.96,0.05));
    //Set maximal number of detections to -1, i.e. all results per image will be evaluated.
    SetDictTuple((*hv_EvalParams), "max_num_detections", -1);
    //Set default area range named 'all', thus areas from 0 to a value larger than all likely occurring values.
    CreateDict(&hv_AreaRanges);
    SetDictTuple(hv_AreaRanges, "name", "all");
    SetDictTuple(hv_AreaRanges, "min", 0);
    SetDictTuple(hv_AreaRanges, "max", 2e8);
    SetDictTuple((*hv_EvalParams), "area_ranges", hv_AreaRanges);
    //Some tuples are changing their length during the evaluation. As this slows down the
    //evaluation process they are allocated in blocks of AllocationBlockLength.
    hv_AllocationBlockLength = 200;
    SetDictTuple((*hv_EvalParams), "allocation_block_length", hv_AllocationBlockLength);
    //Detailed evaluation is not switched on per default, as it slows down the evaluation-process.
    SetDictTuple((*hv_EvalParams), "detailed_evaluation", 0);
    //Interpolate the precision-recall curves per default.
    SetDictTuple((*hv_EvalParams), "interpolate_pr_curves", 1);
  }
  else if (0 != (int(hv_EvaluationType==HTuple("segmentation"))))
  {
    //
    //Set default pixel measures.
    hv_Measures.Clear();
    hv_Measures[0] = "pixel_accuracy";
    hv_Measures[1] = "mean_accuracy";
    hv_Measures[2] = "mean_iou";
    //
    //Per default there are no ignored classes.
    SetDictTuple((*hv_EvalParams), "ignore_class_ids", HTuple());
  }
  else if (0 != (int(hv_EvaluationType==HTuple("ocr_recognition"))))
  {
    //
    //Set default OCR recognition measures
    hv_Measures = "accuracy";
  }
  else if (0 != (int(hv_EvaluationType==HTuple("ocr_detection"))))
  {
    //
    //Set default ocr_detection measures.
    hv_Measures = "f_score";
    SetDictTuple((*hv_EvalParams), "detailed_evaluation", 1);
    SetDictTuple((*hv_EvalParams), "iou_threshold", 0.5);
    SetDictTuple((*hv_EvalParams), "max_num_detections", -1);
    SetDictTuple((*hv_EvalParams), "instance_type", "rectangle2");
    SetDictTuple((*hv_EvalParams), "allocation_block_length", 100);
    //
    //Configure area constraints.
    CreateDict(&hv_AreaRanges);
    SetDictTuple(hv_AreaRanges, "name", "all");
    SetDictTuple(hv_AreaRanges, "min", 0);
    SetDictTuple(hv_AreaRanges, "max", HTuple::TupleConstant("H_INT_MAX"));
    SetDictTuple((*hv_EvalParams), "area_ranges", hv_AreaRanges);
  }
  //
  SetDictTuple((*hv_EvalParams), "evaluate_instances", hv_EvaluateInstances);
  SetDictTuple((*hv_EvalParams), "measures", hv_Measures);
  //
  return;
}

// Chapter: System / Multithreading
void create_visualization_message_queues (HTuple *hv_MessageQueues)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_QueueHandleInMouse, hv_QueueHandleInEvents;
  HTuple  hv_QueueHandleOut;

  CreateMessageQueue(&hv_QueueHandleInMouse);
  CreateMessageQueue(&hv_QueueHandleInEvents);
  CreateMessageQueue(&hv_QueueHandleOut);
  SetMessageQueueParam(hv_QueueHandleInMouse, "max_message_num", 1);
  (*hv_MessageQueues).Clear();
  (*hv_MessageQueues).Append(hv_QueueHandleInMouse);
  (*hv_MessageQueues).Append(hv_QueueHandleInEvents);
  (*hv_MessageQueues).Append(hv_QueueHandleOut);
  return;

}

// Chapter: Deep Learning / Model
// Short Description: Crops a given image object based on the given domain handling. 
void crop_dl_sample_image (HObject ho_Domain, HTuple hv_DLSample, HTuple hv_Key, 
    HTuple hv_DLPreprocessParam)
{

  // Local iconic variables
  HObject  ho___Tmp_Obj_0;

  // Local control variables
  HTuple  hv_KeyExists, hv_Row1, hv_Column1, hv_Row2;
  HTuple  hv_Column2, hv___Tmp_Ctrl_Dict_Init_0;

  GetDictParam(hv_DLSample, "key_exists", hv_Key, &hv_KeyExists);
  if (0 != hv_KeyExists)
  {
    CreateDict(&hv___Tmp_Ctrl_Dict_Init_0);
    SetDictTuple(hv___Tmp_Ctrl_Dict_Init_0, "comp", "crop_domain");
    if (0 != ((hv_DLPreprocessParam.TupleConcat(hv___Tmp_Ctrl_Dict_Init_0)).TupleTestEqualDictItem("domain_handling","comp")))
    {
      SmallestRectangle1(ho_Domain, &hv_Row1, &hv_Column1, &hv_Row2, &hv_Column2);
      CropPart(hv_DLSample.TupleGetDictObject(hv_Key), &ho___Tmp_Obj_0, hv_Row1, 
          hv_Column1, (hv_Column2-hv_Column1)+1, (hv_Row2-hv_Row1)+1);
      SetDictObject(ho___Tmp_Obj_0, hv_DLSample, hv_Key);
    }
    hv___Tmp_Ctrl_Dict_Init_0 = HTuple::TupleConstant("HNULL");
  }
  return;
}

// Chapter: 3D Matching / 3D Box
// Short Description: Inspect the parameters for the generic box finder. 
void debug_find_box_3d (HTuple hv_ObjectModel3DBox, HTuple hv_ObjectModel3DScene, 
    HTuple hv_BoxInformation, HTuple *hv_FindBox3DGenParam)
{

  // Local iconic variables
  HObject  ho_MenuRegions;

  // Local control variables
  HTuple  hv_WindowScaling, hv_WindowSize, hv_FontSize;
  HTuple  hv_WidthMenu, hv_HeightMenu, hv_WindowHandleMenu;
  HTuple  hv_WindowHandle1, hv_WindowHandle2, hv_Row, hv_Column;
  HTuple  hv_Width, hv_Height, hv_MenuText, hv_MenuCode, hv_TopBottom;
  HTuple  hv_NumCols, hv_NumRows, hv_PercentageHeight, hv_CheckedCase;
  HTuple  hv_Case, hv_RowButtons0, hv_ColumnButtons0, hv_RowButtons1;
  HTuple  hv_ColumnButtons1, hv_MenuBottom, hv_BoxResultsDict;
  HTuple  hv_AllBoxResultsDictKeys, hv_Pose, hv_Score, hv_Index;
  HTuple  hv_CurrResultDict, hv_CurrPose, hv_CurrScore, hv_Exception;
  HTuple  hv_CasesDone, hv_CurrentCase, hv_LastException;
  HTuple  hv_GenParamDict, hv_MaxGap, hv_MinAmplitude, hv_ErrorMessage;
  HTuple  hv_Message, hv_EdgeParamsSet, hv_AllParamKeys, hv_Key;
  HTuple  hv_OldParamValue;

  //Please adjust the WindowScaling parameter in order to zoom the window size as desired.
  hv_WindowScaling = 1.2;
  //
  hv_WindowSize = (512*hv_WindowScaling).TupleInt();
  hv_FontSize = 13.5*hv_WindowScaling;
  //
  hv_WidthMenu = hv_WindowSize*2;
  hv_HeightMenu = (hv_WindowSize/3)+(hv_FontSize*2);
  //
  SetWindowAttr("background_color","black");
  OpenWindow(0,0,hv_WidthMenu,hv_HeightMenu,0,"visible","",&hv_WindowHandleMenu);
  HDevWindowStack::Push(hv_WindowHandleMenu);
  hv_WindowHandle1 = HTuple();
  hv_WindowHandle2 = HTuple();
  //
  GetWindowExtents(hv_WindowHandleMenu, &hv_Row, &hv_Column, &hv_Width, &hv_Height);
  set_display_font(hv_WindowHandleMenu, hv_FontSize, "mono", "true", "false");
  //
  //Define the entries in the menu.
  hv_MenuText = "Automatic Value Check";
  hv_MenuCode = "check";
  //Add Edge menu items.
  hv_MenuText = hv_MenuText.TupleConcat("3D Edge Extraction");
  hv_MenuCode = hv_MenuCode.TupleConcat("scene_edge_params");
  //Add Results inspection.
  hv_MenuText = hv_MenuText.TupleConcat("FindBox Results");
  hv_MenuCode = hv_MenuCode.TupleConcat("results");
  //Add Exit menu item.
  hv_MenuText = hv_MenuText.TupleConcat("Exit");
  hv_MenuCode = hv_MenuCode.TupleConcat("exit");
  //
  //Generate the menu buttons.
  hv_TopBottom = "top";
  hv_NumCols = 4;
  hv_NumRows = 1+(((hv_MenuText.TupleLength())-1)/hv_NumCols);
  hv_PercentageHeight = 20*hv_NumRows;
  hv_CheckedCase = hv_NumCols+1;
  hv_Case = hv_NumCols+1;
  gen_menu_regions_ext(&ho_MenuRegions, hv_TopBottom, hv_WindowHandleMenu, hv_PercentageHeight, 
      hv_NumRows, hv_NumCols);
  //
  SmallestRectangle1(ho_MenuRegions, &hv_RowButtons0, &hv_ColumnButtons0, &hv_RowButtons1, 
      &hv_ColumnButtons1);
  hv_MenuBottom = hv_RowButtons1.TupleMax();
  SetTposition(hv_WindowHandleMenu, hv_MenuBottom+6, 1);
  //
  //Fetch poses and scores: This acts as a sanity check for input data, too.
  GetDictTuple(hv_BoxInformation, "results", &hv_BoxResultsDict);
  GetDictParam(hv_BoxResultsDict, "keys", HTuple(), &hv_AllBoxResultsDictKeys);
  if (0 != (int((hv_AllBoxResultsDictKeys.TupleLength())>0)))
  {
    try
    {
      hv_Pose = HTuple();
      hv_Score = HTuple();
      {
      HTuple end_val49 = (hv_AllBoxResultsDictKeys.TupleLength())-1;
      HTuple step_val49 = 1;
      for (hv_Index=0; hv_Index.Continue(end_val49, step_val49); hv_Index += step_val49)
      {
        GetDictTuple(hv_BoxResultsDict, hv_Index, &hv_CurrResultDict);
        GetDictTuple(hv_CurrResultDict, "box_pose", &hv_CurrPose);
        hv_Pose = hv_Pose.TupleConcat(hv_CurrPose);
        GetDictTuple(hv_CurrResultDict, "score", &hv_CurrScore);
        hv_Score = hv_Score.TupleConcat(hv_CurrScore);
      }
      }
    }
    // catch (Exception) 
    catch (HException &HDevExpDefaultException)
    {
      HDevExpDefaultException.ToHTuple(&hv_Exception);
      //Result handle is invalid, or we are in an unsupported HALCON version.
      HDevWindowStack::SetActive(hv_WindowHandleMenu);
      if (HDevWindowStack::IsOpen())
        ClearWindow(HDevWindowStack::GetActive());
      disp_message(hv_WindowHandleMenu, HTuple("Error: This version of HALCON is not supported by this procedure, or the given result handle\n was not created with find_box_3d"), 
          "window", 12, 12, "red", "false");
      wait_continue_button(hv_WindowHandleMenu);
      if (HDevWindowStack::IsOpen())
        CloseWindow(HDevWindowStack::Pop());
      return;
    }
  }
  //
  hv_CasesDone = HTuple();
  hv_CurrentCase = HTuple();
  hv_LastException = HTuple();
  //
  //Find the parameters used for the edge extraction.
  GetDictTuple(hv_BoxInformation, "gen_param", &hv_GenParamDict);
  GetDictTuple(hv_GenParamDict, "max_gap", &hv_MaxGap);
  GetDictTuple(hv_GenParamDict, "3d_edge_min_amplitude", &hv_MinAmplitude);
  //
  while (true)
  {
    ClearWindow(hv_WindowHandleMenu);
    disp_menu_ext(ho_MenuRegions, hv_WindowHandleMenu, hv_MenuText, hv_CasesDone, 
        HTuple(), hv_WindowScaling);
    SetTposition(hv_WindowHandleMenu, hv_MenuBottom+6, 1);
    write_note(hv_WindowHandleMenu, "info", "Please consider the limitations of this procedure as described in its documentation.");
    write_note(hv_WindowHandleMenu, "instruction", "Select a test from above. It is recommended to start with the Automatic Value Check.");
    if (0 != (int((hv_AllBoxResultsDictKeys.TupleLength())==0)))
    {
      write_note(hv_WindowHandleMenu, "warning", HTuple("No box was found in this run of find_box_3d. Therefore, not all tests are available."));
    }
    if (0 != (int(hv_LastException!=HTuple())))
    {
      HException::GetExceptionData(hv_LastException,"error_message",&hv_ErrorMessage);
      write_note(hv_WindowHandleMenu, "warning", ("Exception while running tool: "+hv_ErrorMessage).TupleConcat(HTuple("The scene, model or edges might be empty. Try the Automatic Value Check first.")));
      hv_LastException = HTuple();
    }
    select_case(ho_MenuRegions, hv_WindowHandleMenu, hv_MenuText, &hv_CurrentCase);
    if (0 != (int(hv_CurrentCase==-1)))
    {
      //Window was closed -> abort.
      break;
    }
    if (0 != (int(HTuple(hv_MenuCode[hv_CurrentCase])==HTuple("exit"))))
    {
      break;
    }
    TupleUnion(hv_CasesDone, hv_CurrentCase, &hv_CasesDone);
    disp_menu_ext(ho_MenuRegions, hv_WindowHandleMenu, hv_MenuText, hv_CasesDone, 
        hv_CurrentCase, hv_WindowScaling);
    //
    try
    {
      //***************************
      //Check the data structure. *
      //***************************
      //
      if (0 != (int(HTuple(hv_MenuCode[hv_CurrentCase])==HTuple("check"))))
      {
        //Update the visualization of the menu.
        HDevWindowStack::SetActive(hv_WindowHandleMenu);
        SetTposition(hv_WindowHandleMenu, hv_MenuBottom+6, 1);
        write_note(hv_WindowHandleMenu, "instruction", "Please wait while an automatic check of parameters and values is performed.");
        //
        SetWindowAttr("background_color","black");
        OpenWindow(hv_HeightMenu+50,0,hv_WindowSize*2,hv_WindowSize,0,"visible","",&hv_WindowHandle1);
        HDevWindowStack::Push(hv_WindowHandle1);
        set_display_font(hv_WindowHandle1, hv_FontSize, "mono", "true", "false");
        //
        check_find_box_3d_params(hv_WindowHandle1, hv_ObjectModel3DBox, hv_ObjectModel3DScene, 
            hv_BoxInformation);
        //
        dev_close_window_if_open(hv_WindowHandle1);
      }
      //
      //*********************
      //3D Edge Extraction. *
      //*********************
      //
      if (0 != (int(HTuple(hv_MenuCode[hv_CurrentCase])==HTuple("scene_edge_params"))))
      {
        HDevWindowStack::SetActive(hv_WindowHandleMenu);
        SetTposition(hv_WindowHandleMenu, hv_MenuBottom+6, 1);
        hv_Message = "Find the 3D edges by adjusting the MinAmplitude and the MaxGap accordingly";
        write_note(hv_WindowHandleMenu, "instruction", hv_Message);
        //
        SetWindowAttr("background_color","black");
        OpenWindow(hv_HeightMenu+50,0,hv_WindowSize,hv_WindowSize,0,"visible","",&hv_WindowHandle1);
        HDevWindowStack::Push(hv_WindowHandle1);
        SetWindowAttr("background_color","black");
        OpenWindow(hv_HeightMenu+50,hv_WindowSize,hv_WindowSize,hv_WindowSize,0,"visible","",&hv_WindowHandle2);
        HDevWindowStack::Push(hv_WindowHandle2);
        set_display_font(hv_WindowHandle1, hv_FontSize, "mono", "true", "false");
        set_display_font(hv_WindowHandle2, hv_FontSize, "mono", "true", "false");
        //
        inspect_scene_edge_parameters_find_box_3d(hv_WindowHandle1, hv_WindowHandle2, 
            hv_ObjectModel3DBox, hv_ObjectModel3DScene, hv_BoxInformation, &hv_MaxGap, 
            &hv_MinAmplitude);
        hv_EdgeParamsSet = 1;
        //
        dev_close_window_if_open(hv_WindowHandle1);
        dev_close_window_if_open(hv_WindowHandle2);
      }
      //
      //*****************************
      //Inspect Box Finder Results. *
      //*****************************
      //
      if (0 != (int(HTuple(hv_MenuCode[hv_CurrentCase])==HTuple("results"))))
      {
        //Update the visualization of the menu.
        HDevWindowStack::SetActive(hv_WindowHandleMenu);
        SetTposition(hv_WindowHandleMenu, hv_MenuBottom+6, 1);
        write_note(hv_WindowHandleMenu, "instruction", "Inspect the box finder results below.");
        //
        SetWindowAttr("background_color","black");
        OpenWindow(hv_HeightMenu+50,0,hv_WindowSize,hv_WindowSize,0,"visible","",&hv_WindowHandle1);
        HDevWindowStack::Push(hv_WindowHandle1);
        set_display_font(hv_WindowHandle1, hv_FontSize, "mono", "true", "false");
        //
        dev_display_find_box_3d_results(hv_WindowHandle1, hv_BoxInformation, hv_ObjectModel3DBox, 
            hv_ObjectModel3DScene, hv_Score, hv_Pose);
        //
        dev_close_window_if_open(hv_WindowHandle1);
      }
    }
    // catch (Exception) 
    catch (HException &HDevExpDefaultException)
    {
      HDevExpDefaultException.ToHTuple(&hv_Exception);
      hv_LastException = hv_Exception;
      dev_close_window_if_open(hv_WindowHandle1);
      dev_close_window_if_open(hv_WindowHandle2);
    }
  }
  //
  dev_close_window_if_open(hv_WindowHandleMenu);
  //
  //Construct the parameters.
  CreateDict(&(*hv_FindBox3DGenParam));
  //Copy the old parameters, but without lengths and min_score.
  GetDictParam(hv_GenParamDict, "keys", HTuple(), &hv_AllParamKeys);
  {
  HTuple end_val172 = (hv_AllParamKeys.TupleLength())-1;
  HTuple step_val172 = 1;
  for (hv_Index=0; hv_Index.Continue(end_val172, step_val172); hv_Index += step_val172)
  {
    hv_Key = HTuple(hv_AllParamKeys[hv_Index]);
    if (0 != (HTuple(int(hv_Key==HTuple("lengths"))).TupleOr(int(hv_Key==HTuple("min_score")))))
    {
      continue;
    }
    else
    {
      GetDictTuple(hv_GenParamDict, hv_Key, &hv_OldParamValue);
      SetDictTuple((*hv_FindBox3DGenParam), hv_Key, hv_OldParamValue);
    }
  }
  }
  //Set the new parameters.
  SetDictTuple((*hv_FindBox3DGenParam), "3d_edge_min_amplitude", hv_MinAmplitude);
  SetDictTuple((*hv_FindBox3DGenParam), "max_gap", hv_MaxGap);
}

// Chapter: 3D Matching / Surface-Based
// Short Description: Inspect the parameters for surface-based matching. 
void debug_find_surface_model (HTuple hv_SurfaceModelID, HTuple hv_ObjectModel3DModel, 
    HTuple hv_ObjectModel3DScene, HTuple hv_SurfaceMatchingResultID, HTuple *hv_CreateSurfaceModelParamName, 
    HTuple *hv_CreateSurfaceModelParamValue, HTuple *hv_FindSurfaceModelParamName, 
    HTuple *hv_FindSurfaceModelParamValue)
{

  // Local iconic variables
  HObject  ho_MenuRegions;

  // Local control variables
  HTuple  hv_WindowScaling, hv_WindowSize, hv_FontSize;
  HTuple  hv_WidthMenu, hv_HeightMenu, hv_WindowHandleMenu;
  HTuple  hv_WindowHandle1, hv_WindowHandle2, hv_Row, hv_Column;
  HTuple  hv_Width, hv_Height, hv_HasEdges, hv_HasViewBased;
  HTuple  hv_MenuText, hv_MenuCode, hv_TopBottom, hv_NumCols;
  HTuple  hv_NumRows, hv_PercentageHeight, hv_CheckedCase;
  HTuple  hv_Case, hv_RowButtons0, hv_ColumnButtons0, hv_RowButtons1;
  HTuple  hv_ColumnButtons1, hv_MenuBottom, hv_RelSamplingDistance;
  HTuple  hv_KeyPointFraction, hv_MinScore, hv_GenParamNames;
  HTuple  hv_GenParamValues, hv_NumPoses, hv_Pose, hv_Score;
  HTuple  hv_Index, hv_CurrPose, hv_CurrScore, hv_Exception;
  HTuple  hv_CasesDone, hv_CurrentCase, hv_MaxGap, hv_MinAmplitudeAbs;
  HTuple  hv_Viewpoint, hv_LastException, hv_UserProvidedEdges;
  HTuple  hv_ModelDiameter, hv_MinAmplitudeRel, hv_OM3DProvidedEdges;
  HTuple  hv_ViewpointStr, hv_NormalParamsSet, hv_ErrorMessage;
  HTuple  hv_Message, hv_CreateName, hv_CreateValue, hv_FindNames;
  HTuple  hv_FindValues, hv_EdgeParamsSet;

  //Please adjust the WindowScaling parameter in order to zoom the window size as desired
  hv_WindowScaling = 1.2;
  //
  hv_WindowSize = (512*hv_WindowScaling).TupleInt();
  hv_FontSize = 13.5*hv_WindowScaling;
  //
  hv_WidthMenu = hv_WindowSize*2;
  hv_HeightMenu = (hv_WindowSize/3)+(hv_FontSize*2);
  //
  SetWindowAttr("background_color","black");
  OpenWindow(0,0,hv_WidthMenu,hv_HeightMenu,0,"visible","",&hv_WindowHandleMenu);
  HDevWindowStack::Push(hv_WindowHandleMenu);
  hv_WindowHandle1 = HTuple();
  hv_WindowHandle2 = HTuple();
  //
  GetWindowExtents(hv_WindowHandleMenu, &hv_Row, &hv_Column, &hv_Width, &hv_Height);
  set_display_font(hv_WindowHandleMenu, hv_FontSize, "mono", "true", "false");
  //
  //Define the entries in the menu
  GetSurfaceModelParam(hv_SurfaceModelID, "3d_edges_trained", &hv_HasEdges);
  GetSurfaceModelParam(hv_SurfaceModelID, "view_based_trained", &hv_HasViewBased);
  hv_MenuText = "Automatic Value Check";
  hv_MenuCode = "check";
  //Add Normals menu item
  if (0 != (int((hv_SurfaceMatchingResultID.TupleLength())>0)))
  {
    hv_MenuText = hv_MenuText.TupleConcat("Normal Directions");
    hv_MenuCode = hv_MenuCode.TupleConcat("normals");
  }
  //Add Edge menu items
  if (0 != (int(hv_HasEdges==HTuple("true"))))
  {
    hv_MenuText = hv_MenuText.TupleConcat("Inspect Model Edges");
    hv_MenuCode = hv_MenuCode.TupleConcat("model_edges");

    if (0 != (int((hv_SurfaceMatchingResultID.TupleLength())>0)))
    {
      hv_MenuText = hv_MenuText.TupleConcat((HTuple("3D Edge Extraction").Append("Inspect Scene Edges")));
      hv_MenuCode = hv_MenuCode.TupleConcat((HTuple("scene_edge_params").Append("scene_edge_dirs")));
    }
  }
  //Add view-based menu items
  if (0 != (int(hv_HasViewBased==HTuple("true"))))
  {
    if (0 != (int((hv_SurfaceMatchingResultID.TupleLength())>=0)))
    {
      hv_MenuText = hv_MenuText.TupleConcat("View-Based Check");
      hv_MenuCode = hv_MenuCode.TupleConcat("scene_visibility");
    }
  }
  //Add Results inspection
  if (0 != (int((hv_SurfaceMatchingResultID.TupleLength())>0)))
  {
    hv_MenuText = hv_MenuText.TupleConcat("Matching Results");
    hv_MenuCode = hv_MenuCode.TupleConcat("results");
  }
  //Add Exit menu item
  hv_MenuText = hv_MenuText.TupleConcat("Exit");
  hv_MenuCode = hv_MenuCode.TupleConcat("exit");
  //
  //Generate the menu buttons
  hv_TopBottom = "top";
  hv_NumCols = 4;
  hv_NumRows = 1+(((hv_MenuText.TupleLength())-1)/hv_NumCols);
  hv_PercentageHeight = 20*hv_NumRows;
  hv_CheckedCase = hv_NumCols+1;
  hv_Case = hv_NumCols+1;
  gen_menu_regions_ext(&ho_MenuRegions, hv_TopBottom, hv_WindowHandleMenu, hv_PercentageHeight, 
      hv_NumRows, hv_NumCols);
  //
  SmallestRectangle1(ho_MenuRegions, &hv_RowButtons0, &hv_ColumnButtons0, &hv_RowButtons1, 
      &hv_ColumnButtons1);
  hv_MenuBottom = hv_RowButtons1.TupleMax();
  SetTposition(hv_WindowHandleMenu, hv_MenuBottom+6, 1);
  write_note(hv_WindowHandleMenu, "instruction", "Handlungsanweisung");
  //
  if (0 != (int((hv_SurfaceMatchingResultID.TupleLength())>0)))
  {
    try
    {
      GetSurfaceMatchingResult(hv_SurfaceMatchingResultID, "sampling_rate", 0, &hv_RelSamplingDistance);
      GetSurfaceMatchingResult(hv_SurfaceMatchingResultID, "refpt_rate", 0, &hv_KeyPointFraction);
      GetSurfaceMatchingResult(hv_SurfaceMatchingResultID, "min_score", 0, &hv_MinScore);
      GetSurfaceMatchingResult(hv_SurfaceMatchingResultID, "param_names", 0, &hv_GenParamNames);
      GetSurfaceMatchingResult(hv_SurfaceMatchingResultID, "param_values", 0, &hv_GenParamValues);
      GetSurfaceMatchingResult(hv_SurfaceMatchingResultID, "num_poses", 0, &hv_NumPoses);
      hv_Pose = HTuple();
      hv_Score = HTuple();
      {
      HTuple end_val76 = hv_NumPoses-1;
      HTuple step_val76 = 1;
      for (hv_Index=0; hv_Index.Continue(end_val76, step_val76); hv_Index += step_val76)
      {
        GetSurfaceMatchingResult(hv_SurfaceMatchingResultID, "pose", hv_Index, &hv_CurrPose);
        hv_Pose = hv_Pose.TupleConcat(hv_CurrPose);
        GetSurfaceMatchingResult(hv_SurfaceMatchingResultID, "score", hv_Index, &hv_CurrScore);
        hv_Score = hv_Score.TupleConcat(hv_CurrScore);
      }
      }
    }
    // catch (Exception) 
    catch (HException &HDevExpDefaultException)
    {
      HDevExpDefaultException.ToHTuple(&hv_Exception);
      //Result handle is invalid, or we are in an unsupported HALCON version
      HDevWindowStack::SetActive(hv_WindowHandleMenu);
      if (HDevWindowStack::IsOpen())
        ClearWindow(HDevWindowStack::GetActive());
      disp_message(hv_WindowHandleMenu, HTuple("Error: This version of HALCON is not supported by this procedure, or the given result handle\n was not created with find_surface_model"), 
          "window", 12, 12, "red", "false");
      wait_continue_button(hv_WindowHandleMenu);
      if (HDevWindowStack::IsOpen())
        CloseWindow(HDevWindowStack::Pop());
      return;
    }
    if (0 != (int(hv_RelSamplingDistance==0)))
    {
      HDevWindowStack::SetActive(hv_WindowHandleMenu);
      if (HDevWindowStack::IsOpen())
        ClearWindow(HDevWindowStack::GetActive());
      disp_message(hv_WindowHandleMenu, "Error: The given result handle was not created with find_surface_model. Please pass a result handle\n created by find_surface_model.", 
          "window", 12, 12, "red", "false");
      wait_continue_button(hv_WindowHandleMenu);
      if (HDevWindowStack::IsOpen())
        CloseWindow(HDevWindowStack::Pop());
      return;
    }
  }
  else
  {
    hv_GenParamNames = HTuple();
    hv_GenParamValues = HTuple();
  }
  //
  hv_CasesDone = HTuple();
  hv_CurrentCase = HTuple();
  //
  //Find the parameters used for the edge extraction
  hv_MaxGap = HTuple();
  hv_MinAmplitudeAbs = HTuple();
  hv_Viewpoint = HTuple();
  hv_LastException = HTuple();
  hv_UserProvidedEdges = 0;
  if (0 != (HTuple(int(hv_HasEdges==HTuple("true"))).TupleAnd(int((hv_SurfaceMatchingResultID.TupleLength())>0))))
  {
    GetSurfaceModelParam(hv_SurfaceModelID, "diameter", &hv_ModelDiameter);
    get_find_parameter(hv_GenParamNames, hv_GenParamValues, "max_gap", 30, &hv_MaxGap);
    get_find_parameter(hv_GenParamNames, hv_GenParamValues, "3d_edge_min_amplitude_rel", 
        HTuple(), &hv_MinAmplitudeRel);
    if (0 != (int(hv_MinAmplitudeRel!=HTuple())))
    {
      hv_MinAmplitudeAbs = hv_MinAmplitudeRel*hv_ModelDiameter;
    }
    else
    {
      get_find_parameter(hv_GenParamNames, hv_GenParamValues, "3d_edge_min_amplitude_abs", 
          0.05*hv_ModelDiameter, &hv_MinAmplitudeAbs);
    }
    //
    get_find_parameter(hv_GenParamNames, hv_GenParamValues, "3d_edges", HTuple(), 
        &hv_OM3DProvidedEdges);
    hv_UserProvidedEdges = int((hv_OM3DProvidedEdges.TupleLength())>0);
  }
  if (0 != (HTuple(int(hv_HasViewBased==HTuple("true"))).TupleAnd(int((hv_SurfaceMatchingResultID.TupleLength())>0))))
  {
    GetSurfaceModelParam(hv_SurfaceModelID, "diameter", &hv_ModelDiameter);
    get_find_parameter(hv_GenParamNames, hv_GenParamValues, "viewpoint", "0 0 0", 
        &hv_ViewpointStr);
    hv_Viewpoint = (hv_ViewpointStr.TupleSplit(" ")).TupleNumber();
  }
  hv_NormalParamsSet = 0;
  //
  while (true)
  {
    ClearWindow(hv_WindowHandleMenu);
    disp_menu_ext(ho_MenuRegions, hv_WindowHandleMenu, hv_MenuText, hv_CasesDone, 
        HTuple(), hv_WindowScaling);
    SetTposition(hv_WindowHandleMenu, hv_MenuBottom+6, 1);
    write_note(hv_WindowHandleMenu, "info", "Please consider the limitations of this procedure as described in its documentation.");
    write_note(hv_WindowHandleMenu, "instruction", "Select a test from above. It is recommended to start with the Automatic Value Check.");
    if (0 != (int((hv_SurfaceMatchingResultID.TupleLength())==0)))
    {
      write_note(hv_WindowHandleMenu, "warning", HTuple("No result handle was provided. To enable more tests, run find_surface_model() with 'ReturnResultHandle' set to 'true' beforehand and pass the result handle to this procedure."));
    }
    if (0 != hv_UserProvidedEdges)
    {
      write_note(hv_WindowHandleMenu, "warning", HTuple("Edges were passed to find_surface_model manually with the '3d_edges' parameter. Some checks of scene edges might be incorrect, since they assume that edges are extracted by find_surface_model."));
    }
    if (0 != (int(hv_LastException!=HTuple())))
    {
      HException::GetExceptionData(hv_LastException,"error_message",&hv_ErrorMessage);
      write_note(hv_WindowHandleMenu, "warning", ("Exception while running tool: "+hv_ErrorMessage).TupleConcat(HTuple("The scene, model or edges might be empty. Try the Automatic Value Check first.")));
      hv_LastException = HTuple();
    }
    select_case(ho_MenuRegions, hv_WindowHandleMenu, hv_MenuText, &hv_CurrentCase);
    if (0 != (int(hv_CurrentCase==-1)))
    {
      //Window was closed -> abort
      break;
    }
    if (0 != (int(HTuple(hv_MenuCode[hv_CurrentCase])==HTuple("exit"))))
    {
      break;
    }
    TupleUnion(hv_CasesDone, hv_CurrentCase, &hv_CasesDone);
    disp_menu_ext(ho_MenuRegions, hv_WindowHandleMenu, hv_MenuText, hv_CasesDone, 
        hv_CurrentCase, hv_WindowScaling);
    //
    try
    {
      //****************************
      //Inspect Normal Directions *
      //****************************
      if (0 != (int(HTuple(hv_MenuCode[hv_CurrentCase])==HTuple("normals"))))
      {
        HDevWindowStack::SetActive(hv_WindowHandleMenu);
        SetTposition(hv_WindowHandleMenu, hv_MenuBottom+6, 1);
        hv_Message = HTuple("Check visually, if the normals of the model point approximately in the same direction as the normals of the scene by moving the model and the scene accordingly");
        write_note(hv_WindowHandleMenu, "instruction", hv_Message);
        //
        SetWindowAttr("background_color","black");
        OpenWindow(hv_HeightMenu+50,0,hv_WindowSize,hv_WindowSize,0,"visible","",&hv_WindowHandle1);
        HDevWindowStack::Push(hv_WindowHandle1);
        SetWindowAttr("background_color","black");
        OpenWindow(hv_HeightMenu+50,hv_WindowSize,hv_WindowSize,hv_WindowSize,0,"visible","",&hv_WindowHandle2);
        HDevWindowStack::Push(hv_WindowHandle2);
        set_display_font(hv_WindowHandle1, hv_FontSize, "mono", "true", "false");
        set_display_font(hv_WindowHandle2, hv_FontSize, "mono", "true", "false");
        //
        inspect_normal_direction(ho_MenuRegions, hv_WindowHandle1, hv_WindowHandle2, 
            hv_WindowHandleMenu, hv_SurfaceModelID, hv_ObjectModel3DScene, hv_RelSamplingDistance, 
            hv_KeyPointFraction, hv_MinScore, hv_GenParamNames, hv_GenParamValues, 
            hv_SurfaceMatchingResultID, hv_MenuText, hv_CurrentCase, hv_CasesDone, 
            hv_FontSize, hv_WindowScaling, &hv_CreateName, &hv_CreateValue, &hv_FindNames, 
            &hv_FindValues);
        hv_NormalParamsSet = 1;
        //
        dev_close_window_if_open(hv_WindowHandle1);
        dev_close_window_if_open(hv_WindowHandle2);
      }
      //
      //***************************
      //Check the data structure *
      //***************************
      //
      if (0 != (int(HTuple(hv_MenuCode[hv_CurrentCase])==HTuple("check"))))
      {
        //Update the visualization of the menu
        HDevWindowStack::SetActive(hv_WindowHandleMenu);
        SetTposition(hv_WindowHandleMenu, hv_MenuBottom+6, 1);
        write_note(hv_WindowHandleMenu, "instruction", "Please wait while an automatic check of parameters and values is performed");
        //
        SetWindowAttr("background_color","black");
        OpenWindow(hv_HeightMenu+50,0,hv_WindowSize*2,hv_WindowSize,0,"visible","",&hv_WindowHandle1);
        HDevWindowStack::Push(hv_WindowHandle1);
        set_display_font(hv_WindowHandle1, hv_FontSize, "mono", "true", "false");
        //
        check_find_surface_model_params(hv_WindowHandle1, hv_SurfaceModelID, hv_ObjectModel3DScene, 
            hv_GenParamNames, hv_GenParamValues);
        //
        dev_close_window_if_open(hv_WindowHandle1);
      }
      //
      //****************
      //Prepare edges *
      //****************
      //
      if (0 != (int(HTuple(hv_MenuCode[hv_CurrentCase])==HTuple("scene_edge_params"))))
      {
        HDevWindowStack::SetActive(hv_WindowHandleMenu);
        SetTposition(hv_WindowHandleMenu, hv_MenuBottom+6, 1);
        hv_Message = "Find the 3D edges by adjusting the MinAmplitude and the MaxGap accordingly";
        write_note(hv_WindowHandleMenu, "instruction", hv_Message);
        //
        SetWindowAttr("background_color","black");
        OpenWindow(hv_HeightMenu+50,0,hv_WindowSize,hv_WindowSize,0,"visible","",&hv_WindowHandle1);
        HDevWindowStack::Push(hv_WindowHandle1);
        SetWindowAttr("background_color","black");
        OpenWindow(hv_HeightMenu+50,hv_WindowSize,hv_WindowSize,hv_WindowSize,0,"visible","",&hv_WindowHandle2);
        HDevWindowStack::Push(hv_WindowHandle2);
        set_display_font(hv_WindowHandle1, hv_FontSize, "mono", "true", "false");
        set_display_font(hv_WindowHandle2, hv_FontSize, "mono", "true", "false");
        //
        inspect_scene_edge_parameters(hv_WindowHandle1, hv_WindowHandle2, hv_SurfaceModelID, 
            hv_ObjectModel3DScene, hv_SurfaceMatchingResultID, hv_MaxGap, hv_MinAmplitudeAbs, 
            &hv_MaxGap, &hv_MinAmplitudeAbs);
        hv_EdgeParamsSet = 1;
        //
        dev_close_window_if_open(hv_WindowHandle1);
        dev_close_window_if_open(hv_WindowHandle2);
      }
      //
      //******************
      //Edge Directions *
      //******************
      //
      if (0 != (int(HTuple(hv_MenuCode[hv_CurrentCase])==HTuple("scene_edge_dirs"))))
      {
        //Update the visualization of the menu
        HDevWindowStack::SetActive(hv_WindowHandleMenu);
        SetTposition(hv_WindowHandleMenu, hv_MenuBottom+6, 1);
        write_note(hv_WindowHandleMenu, "instruction", HTuple(HTuple("Inspect the viewing and edge directions extracted from the scene. ")+"The viewing directions show away from the viewpoint. ")+"The edge directions should be perpendicular to the edges and point outward.");
        //
        SetWindowAttr("background_color","black");
        OpenWindow(hv_HeightMenu+50,0,hv_WindowSize,hv_WindowSize,0,"visible","",&hv_WindowHandle1);
        HDevWindowStack::Push(hv_WindowHandle1);
        set_display_font(hv_WindowHandle1, hv_FontSize, "mono", "true", "false");
        //
        inspect_scene_edge_directions(hv_WindowHandle1, hv_SurfaceModelID, hv_ObjectModel3DScene, 
            hv_SurfaceMatchingResultID, hv_MaxGap, hv_MinAmplitudeAbs);
        //
        dev_close_window_if_open(hv_WindowHandle1);
      }
      //
      //***************************
      //Inspect Model Edges      *
      //***************************
      //
      if (0 != (int(HTuple(hv_MenuCode[hv_CurrentCase])==HTuple("model_edges"))))
      {
        //Update the visualization of the menu
        HDevWindowStack::SetActive(hv_WindowHandleMenu);
        SetTposition(hv_WindowHandleMenu, hv_MenuBottom+6, 1);
        write_note(hv_WindowHandleMenu, "info", "This tool allows to inspect the edges that create_surface_model found in the object.");
        write_note(hv_WindowHandleMenu, "instruction", "Use the left window to move the viewpoint and the right window to inspect the edges.");
        write_note(hv_WindowHandleMenu, "info", "The visualized \"edge directions\" should be perpendicular to the direction of the model edges and point outward.");
        //
        SetWindowAttr("background_color","black");
        OpenWindow(hv_HeightMenu+50,0,hv_WindowSize,hv_WindowSize,0,"visible","",&hv_WindowHandle1);
        HDevWindowStack::Push(hv_WindowHandle1);
        SetWindowAttr("background_color","black");
        OpenWindow(hv_HeightMenu+50,hv_WindowSize,hv_WindowSize,hv_WindowSize,0,"visible","",&hv_WindowHandle2);
        HDevWindowStack::Push(hv_WindowHandle2);
        set_display_font(hv_WindowHandle1, hv_FontSize, "mono", "true", "false");
        set_display_font(hv_WindowHandle2, hv_FontSize, "mono", "true", "false");
        //
        check_model_edges(hv_SurfaceModelID, hv_ObjectModel3DModel, hv_WindowHandle1, 
            hv_WindowHandle2);
        //
        dev_close_window_if_open(hv_WindowHandle1);
        dev_close_window_if_open(hv_WindowHandle2);
      }
      //
      //***************************
      //Inspect Visibility        *
      //***************************
      //
      if (0 != (int(HTuple(hv_MenuCode[hv_CurrentCase])==HTuple("scene_visibility"))))
      {
        //Update the visualization of the menu
        HDevWindowStack::SetActive(hv_WindowHandleMenu);
        SetTposition(hv_WindowHandleMenu, hv_MenuBottom+6, 1);
        write_note(hv_WindowHandleMenu, "info", "This tool allows to inspect the scene visibility.");
        write_note(hv_WindowHandleMenu, "instruction", "Use the left window to move the viewpoint and the right window to inspect the visibility.");
        //
        SetWindowAttr("background_color","black");
        OpenWindow(hv_HeightMenu+50,0,hv_WindowSize,hv_WindowSize,0,"visible","",&hv_WindowHandle1);
        HDevWindowStack::Push(hv_WindowHandle1);
        SetWindowAttr("background_color","black");
        OpenWindow(hv_HeightMenu+50,hv_WindowSize,hv_WindowSize,hv_WindowSize,0,"visible","",&hv_WindowHandle2);
        HDevWindowStack::Push(hv_WindowHandle2);
        set_display_font(hv_WindowHandle1, hv_FontSize, "mono", "true", "false");
        set_display_font(hv_WindowHandle2, hv_FontSize, "mono", "true", "false");
        //
        check_visibility(hv_WindowHandle1, hv_WindowHandle2, hv_SurfaceModelID, hv_ObjectModel3DScene, 
            hv_ObjectModel3DModel, hv_SurfaceMatchingResultID, hv_Viewpoint, &hv_Viewpoint);
        //
        dev_close_window_if_open(hv_WindowHandle1);
        dev_close_window_if_open(hv_WindowHandle2);
      }
      //
      //***************************
      //Inspect Matching Results *
      //***************************
      //
      if (0 != (int(HTuple(hv_MenuCode[hv_CurrentCase])==HTuple("results"))))
      {
        //Update the visualization of the menu
        HDevWindowStack::SetActive(hv_WindowHandleMenu);
        SetTposition(hv_WindowHandleMenu, hv_MenuBottom+6, 1);
        write_note(hv_WindowHandleMenu, "instruction", "Inspect the matching results below.");
        //
        SetWindowAttr("background_color","black");
        OpenWindow(hv_HeightMenu+50,0,hv_WindowSize,hv_WindowSize,0,"visible","",&hv_WindowHandle1);
        HDevWindowStack::Push(hv_WindowHandle1);
        set_display_font(hv_WindowHandle1, hv_FontSize, "mono", "true", "false");
        //
        dev_display_surface_matching_results(hv_WindowHandle1, hv_SurfaceMatchingResultID, 
            hv_ObjectModel3DModel, hv_ObjectModel3DScene, hv_Score, hv_Pose, hv_HasEdges, 
            hv_HasViewBased);
        //
        dev_close_window_if_open(hv_WindowHandle1);
      }
    }
    // catch (Exception) 
    catch (HException &HDevExpDefaultException)
    {
      HDevExpDefaultException.ToHTuple(&hv_Exception);
      hv_LastException = hv_Exception;
      dev_close_window_if_open(hv_WindowHandle1);
      dev_close_window_if_open(hv_WindowHandle2);
    }
  }
  //
  dev_close_window_if_open(hv_WindowHandleMenu);
  //
  //Construct the parameters
  (*hv_CreateSurfaceModelParamName) = HTuple();
  (*hv_CreateSurfaceModelParamValue) = HTuple();
  (*hv_FindSurfaceModelParamName) = HTuple();
  (*hv_FindSurfaceModelParamValue) = HTuple();

  if (0 != hv_NormalParamsSet)
  {
    (*hv_CreateSurfaceModelParamName) = (*hv_CreateSurfaceModelParamName).TupleConcat(hv_CreateName);
    (*hv_CreateSurfaceModelParamValue) = (*hv_CreateSurfaceModelParamValue).TupleConcat(hv_CreateValue);
    (*hv_FindSurfaceModelParamName) = (*hv_FindSurfaceModelParamName).TupleConcat(hv_FindNames);
    (*hv_FindSurfaceModelParamValue) = (*hv_FindSurfaceModelParamValue).TupleConcat(hv_FindValues);
  }

  if (0 != (int(hv_MaxGap!=HTuple())))
  {
    (*hv_FindSurfaceModelParamName) = (*hv_FindSurfaceModelParamName).TupleConcat((HTuple("3d_edge_min_amplitude_abs").Append("max_gap")));
    (*hv_FindSurfaceModelParamValue) = ((*hv_FindSurfaceModelParamValue).TupleConcat(hv_MinAmplitudeAbs)).TupleConcat(hv_MaxGap);
  }

  if (0 != (int(hv_Viewpoint!=HTuple())))
  {
    (*hv_FindSurfaceModelParamName) = (*hv_FindSurfaceModelParamName).TupleConcat("viewpoint");
    (*hv_FindSurfaceModelParamValue) = (*hv_FindSurfaceModelParamValue).TupleConcat((((HTuple(hv_Viewpoint[0])+" ")+HTuple(hv_Viewpoint[1]))+" ")+HTuple(hv_Viewpoint[2]));
  }

}

// Chapter: Deep Learning / Object Detection and Instance Segmentation
// Short Description: Decompress a compressed COCO runlength encoding. 
void decompress_coco_rle (HTuple hv_CompressedRLE, HTuple hv_Width, HTuple hv_Height, 
    HTuple *hv_RunLengthEncoding)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_Ords, hv_Chars, hv_HasMore, hv_IsLast;
  HTuple  hv_IsFirst, hv_BlockID, hv_BlockIDToFirst, hv_BlockIDToLast;
  HTuple  hv_k2, hv_k3, hv_k, hv_x_parts, hv_RunLengthEncoding2;
  HTuple  hv_LongerThanOne, hv_Index, hv_Block, hv_Index2;
  HTuple  hv_do_last_shift, hv_Tmp, hv_RCumulEvens, hv_RCumulOdds;
  HTuple  hv_Total;

  //Decompress a compressed COCO runlength encoding.
  TupleOrds(hv_CompressedRLE, &hv_Ords);
  hv_Chars = hv_Ords-48;
  hv_HasMore = (hv_Chars&0x20).TupleNotEqualElem(0);
  //
  //Compute the numbers encoded in the string.
  hv_IsLast = 1-hv_HasMore;
  hv_IsFirst.Clear();
  hv_IsFirst[0] = 1;
  hv_IsFirst.Append(1-(hv_HasMore.TupleSelectRange(0,(hv_HasMore.TupleLength())-2)));
  hv_BlockID = (hv_IsFirst.TupleCumul())-1;
  hv_BlockIDToFirst = hv_IsFirst.TupleFind(1);
  hv_BlockIDToLast = hv_IsLast.TupleFind(1);
  //
  hv_k2 = HTuple(hv_HasMore.TupleOr(hv_IsLast)).TupleAnd(hv_IsFirst.TupleNot());
  hv_k3 = hv_k2.TupleCumul();
  hv_k = hv_k3-HTuple(hv_k3[HTuple(hv_BlockIDToFirst[hv_BlockID])]);
  //
  hv_x_parts = ((hv_Chars&0x1f)<<(5*hv_k));
  //
  hv_RunLengthEncoding2 = HTuple(hv_x_parts[hv_BlockIDToFirst]);
  //
  //Process encodings that are longer than one character.
  hv_LongerThanOne = (hv_BlockIDToFirst.TupleNotEqualElem(hv_BlockIDToLast)).TupleFind(1);
  if (0 != (HTuple(int(hv_LongerThanOne!=HTuple())).TupleAnd(int(hv_LongerThanOne!=-1))))
  {
    {
    HTuple end_val23 = (hv_LongerThanOne.TupleLength())-1;
    HTuple step_val23 = 1;
    for (hv_Index=0; hv_Index.Continue(end_val23, step_val23); hv_Index += step_val23)
    {
      hv_Block = HTuple(hv_LongerThanOne[hv_Index]);
      {
      HTuple end_val25 = HTuple(hv_BlockIDToLast[hv_Block]);
      HTuple step_val25 = 1;
      for (hv_Index2=HTuple(hv_BlockIDToFirst[hv_Block])+1; hv_Index2.Continue(end_val25, step_val25); hv_Index2 += step_val25)
      {
        hv_RunLengthEncoding2[hv_Block] = HTuple(hv_RunLengthEncoding2[hv_Block])|HTuple(hv_x_parts[hv_Index2]);
      }
      }
    }
    }
  }
  //
  //Apply the additional, optional - sign.
  hv_do_last_shift = (HTuple(hv_Chars[hv_BlockIDToLast])&0x10).TupleNotEqualElem(0);
  hv_RunLengthEncoding2 = hv_RunLengthEncoding2|(hv_do_last_shift*(-1<<(5*(1+HTuple(hv_k[hv_BlockIDToLast])))));
  //
  //For indices > 2, the final value is the delta to its previous value.
  hv_Tmp = ((const HTuple&)hv_RunLengthEncoding2)[0];
  hv_RunLengthEncoding2[0] = 0;
  hv_RCumulEvens = HTuple(hv_RunLengthEncoding2[HTuple::TupleGenSequence(0,(hv_RunLengthEncoding2.TupleLength())-1,2)]).TupleCumul();
  hv_RCumulOdds = HTuple(hv_RunLengthEncoding2[HTuple::TupleGenSequence(1,(hv_RunLengthEncoding2.TupleLength())-1,2)]).TupleCumul();
  (*hv_RunLengthEncoding)[HTuple::TupleGenSequence(1,(hv_RunLengthEncoding2.TupleLength())-1,2)] = hv_RCumulOdds;
  (*hv_RunLengthEncoding)[HTuple::TupleGenSequence(0,(hv_RunLengthEncoding2.TupleLength())-1,2)] = hv_RCumulEvens;
  (*hv_RunLengthEncoding)[0] = hv_Tmp;
  //
  //Sanity-check the size of the encoding
  hv_Total = (*hv_RunLengthEncoding).TupleSum();
  if (0 != (int(hv_Total>(hv_Width*hv_Height))))
  {
    throw HException("Invalid mask: Mask size exceeds image size");
  }
  //
  return;
}

// Chapter: Inspection / Structured Light
// Short Description: Determine point correspondences between the camera and the projector of a structured light setup used for surface reconstruction. 
void determine_camera_to_projector_correspondence_structured_light (HObject ho_ImageSequence, 
    HTuple hv_StructuredLightModel, HTuple hv_CameraRows, HTuple hv_CameraColumns, 
    HTuple *hv_ProjectorRows, HTuple *hv_ProjectorColumns)
{

  // Local iconic variables
  HObject  ho_PatternImages, ho_CorrespondenceImages;
  HObject  ho_CorresImageVert, ho_CorresImageHor, ho_WhiteCamImage;
  HObject  ho_TargetRegion, ho_ConnectedRegions, ho_SelectedRegions;
  HObject  ho_RegionErosion, ho_VertValidRegion, ho_HorValidRegion;
  HObject  ho_ValidRegion, ho_Circle, ho_PatchRegion;

  // Local control variables
  HTuple  hv_UsedThreshold, hv_CenterRow, hv_CenterColumn;
  HTuple  hv_Radius, hv_PatchRadius, hv_NumTargetPoints, hv_IndexPoints;
  HTuple  hv_PatchCamRows, hv_PatchCamCols, hv_PatchProjRows;
  HTuple  hv_PatchProjCols, hv_HomMat2D, hv_Covariance, hv_Qx;
  HTuple  hv_Qy, hv_Qw;

  //This procedure determines point correspondences between the
  //camera and the projector by decoding the vertical and
  //horizontal fringe patterns and using the resulting
  //correspondence maps.
  //
  //Get the vertical and horizontal correspondence images.
  GenStructuredLightPattern(&ho_PatternImages, hv_StructuredLightModel);
  DecodeStructuredLightPattern(ho_ImageSequence, hv_StructuredLightModel);
  GetStructuredLightObject(&ho_CorrespondenceImages, hv_StructuredLightModel, "correspondence_image");
  SelectObj(ho_CorrespondenceImages, &ho_CorresImageVert, 1);
  SelectObj(ho_CorrespondenceImages, &ho_CorresImageHor, 2);
  //
  //Estimate subpixel precise point correspondence by estimating
  //a local homography within a circular image patch of radius
  //PatchRadius.
  retrieve_texture_structured_light(ho_ImageSequence, &ho_WhiteCamImage);
  BinaryThreshold(ho_WhiteCamImage, &ho_TargetRegion, "max_separability", "light", 
      &hv_UsedThreshold);
  Connection(ho_TargetRegion, &ho_ConnectedRegions);
  FillUp(ho_ConnectedRegions, &ho_ConnectedRegions);
  SelectShape(ho_ConnectedRegions, &ho_SelectedRegions, (HTuple("area").Append("roundness")), 
      "and", (HTuple(5).Append(0.95)), (HTuple(1e4).Append(1)));
  ErosionCircle(ho_SelectedRegions, &ho_RegionErosion, 2.5);
  SmallestCircle(ho_RegionErosion, &hv_CenterRow, &hv_CenterColumn, &hv_Radius);
  hv_PatchRadius = hv_Radius.TupleMean();
  //
  GetDomain(ho_CorresImageVert, &ho_VertValidRegion);
  GetDomain(ho_CorresImageHor, &ho_HorValidRegion);
  Intersection(ho_VertValidRegion, ho_HorValidRegion, &ho_ValidRegion);
  hv_NumTargetPoints = hv_CameraRows.TupleLength();
  (*hv_ProjectorRows) = HTuple(hv_NumTargetPoints,0);
  (*hv_ProjectorColumns) = HTuple(hv_NumTargetPoints,0);
  {
  HTuple end_val30 = hv_NumTargetPoints-1;
  HTuple step_val30 = 1;
  for (hv_IndexPoints=0; hv_IndexPoints.Continue(end_val30, step_val30); hv_IndexPoints += step_val30)
  {
    //
    GenCircle(&ho_Circle, HTuple(hv_CameraRows[hv_IndexPoints]), HTuple(hv_CameraColumns[hv_IndexPoints]), 
        hv_PatchRadius);
    Intersection(ho_ValidRegion, ho_Circle, &ho_PatchRegion);
    //Get the gray values for the valid points inside the patch.
    GetRegionPoints(ho_PatchRegion, &hv_PatchCamRows, &hv_PatchCamCols);
    GetGrayval(ho_CorresImageHor, hv_PatchCamRows, hv_PatchCamCols, &hv_PatchProjRows);
    GetGrayval(ho_CorresImageVert, hv_PatchCamRows, hv_PatchCamCols, &hv_PatchProjCols);
    //
    //Compute the projective transformation from the
    //correspondences between camera and projector points.
    VectorToProjHomMat2d(hv_PatchCamRows, hv_PatchCamCols, hv_PatchProjRows, hv_PatchProjCols, 
        "normalized_dlt", HTuple(), HTuple(), HTuple(), HTuple(), HTuple(), HTuple(), 
        &hv_HomMat2D, &hv_Covariance);
    //Apply the projective transformation to the calibration
    //target centers.
    ProjectiveTransPoint2d(hv_HomMat2D, HTuple(hv_CameraRows[hv_IndexPoints]), HTuple(hv_CameraColumns[hv_IndexPoints]), 
        1, &hv_Qx, &hv_Qy, &hv_Qw);
    //Since Qx, Qy, Qw are homogeneous coordinates with Qw
    //possibly != 1, Qx, Qy need to be scaled.
    (*hv_ProjectorRows)[hv_IndexPoints] = hv_Qx/hv_Qw;
    (*hv_ProjectorColumns)[hv_IndexPoints] = hv_Qy/hv_Qw;
  }
  }
  //
  return;
}

// Chapter: Deep Learning / Object Detection and Instance Segmentation
// Short Description: Analyze the provided DLDataset for object detection to find model parameters relevant for anchor generation. 
void determine_dl_model_detection_param (HTuple hv_DLDataset, HTuple hv_ImageWidthTarget, 
    HTuple hv_ImageHeightTarget, HTuple hv_GenParam, HTuple *hv_DLDetectionModelParam)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_MinLevel, hv_MaxLevel, hv_AnchorNumSubscales;
  HTuple  hv_DatasetSplit, hv_DisplayHistogram, hv_IgnoreDirection;
  HTuple  hv_ClassIDsNoOrientation, hv_MaxNumSamples, hv_ComputeMaxOverlap;
  HTuple  hv_AvailableGenParams, hv_GenParamName, hv_GenParamIndex;
  HTuple  hv_DatasetKeys, hv_KeyIndex, hv_DatasetKeyExists;
  HTuple  hv_Rect1Keys, hv_Rect2Keys, hv_Rect1KeysExist, hv_Rect2KeysExist;
  HTuple  hv_InstanceType, hv_ClassIdsExist, hv_ClassNamesExist;
  HTuple  hv_Areas, hv_AspectRatios, hv_Angles, hv_MaxOverlap;
  HTuple  hv_MaxOverlapClassAgnostic, hv_AreasReduced, hv_AspectRatiosReduced;
  HTuple  hv_AnglesReduced, hv_MinLevelToUse, hv_MaxLevelToUse;
  HTuple  hv_AnchorNumSubscalesToUse, hv_ErrorMessage, hv_MinRatio;
  HTuple  hv_MinDiff, hv_K, hv_ClusteredAspectRatios, hv_ClusteredAngles;
  HTuple  hv_MinAngleIdx, hv_WindowBGColor, hv_SplitText;
  HTuple  hv_WindowHandle, hv_WindowHandle2, hv_WindowHandle3;
  HTuple  hv___Tmp_Ctrl_Dict_Init_0, hv___Tmp_Ctrl_Dict_Init_1;
  HTuple  hv___Tmp_Ctrl_Dict_Init_2, hv___Tmp_Ctrl_Dict_Init_3;
  HTuple  hv___Tmp_Ctrl_Dict_Init_4, hv___Tmp_Ctrl_Dict_Init_5;
  HTuple  hv___Tmp_Ctrl_Type;

  //This procedure analyzes the input DLDataset for object detection
  //in order to find good values for parameters which control the
  //generation of anchor bounding boxes.
  //
  //
  //Set default values for generic parameters.
  hv_MinLevel = 2;
  hv_MaxLevel = 6;
  hv_AnchorNumSubscales = 3;
  hv_DatasetSplit = "train";
  hv_DisplayHistogram = 0;
  hv_IgnoreDirection = 0;
  hv_ClassIDsNoOrientation = HTuple();
  hv_MaxNumSamples = 1500;
  hv_ComputeMaxOverlap = 1;
  //
  hv_AvailableGenParams.Clear();
  hv_AvailableGenParams[0] = "min_level";
  hv_AvailableGenParams[1] = "max_level";
  hv_AvailableGenParams[2] = "anchor_num_subscales";
  hv_AvailableGenParams[3] = "display_histogram";
  hv_AvailableGenParams[4] = "split";
  hv_AvailableGenParams[5] = "raw_width";
  hv_AvailableGenParams[6] = "raw_height";
  hv_AvailableGenParams[7] = "domain_handling";
  hv_AvailableGenParams[8] = "preprocessed_path";
  hv_AvailableGenParams[9] = "class_ids_no_orientation";
  hv_AvailableGenParams[10] = "ignore_direction";
  hv_AvailableGenParams[11] = "max_num_samples";
  hv_AvailableGenParams[12] = "compute_max_overlap";
  hv_AvailableGenParams[13] = "image_size_constant";
  //Read generic parameters and check the provided values.
  if (0 != (int(hv_GenParam!=HTuple())))
  {
    GetDictParam(hv_GenParam, "keys", HTuple(), &hv_GenParamName);
    {
    HTuple end_val20 = (hv_GenParamName.TupleLength())-1;
    HTuple step_val20 = 1;
    for (hv_GenParamIndex=0; hv_GenParamIndex.Continue(end_val20, step_val20); hv_GenParamIndex += step_val20)
    {
      if (0 != (int(HTuple(hv_GenParamName[hv_GenParamIndex])==HTuple("min_level"))))
      {
        hv_MinLevel = hv_GenParam.TupleGetDictTuple("min_level");
        if (0 != ((hv_MinLevel.TupleIsInt()).TupleNot()))
        {
          throw HException(HTuple(hv_GenParamName[hv_GenParamIndex])+" should be of type int");
        }
        if (0 != (int(hv_MinLevel<2)))
        {
          throw HException(("Invalid value for parameter 'min_level': "+hv_MinLevel)+". The minimum value is 2.");
        }
      }
      else if (0 != (int(HTuple(hv_GenParamName[hv_GenParamIndex])==HTuple("max_level"))))
      {
        hv_MaxLevel = hv_GenParam.TupleGetDictTuple("max_level");
        if (0 != ((hv_MaxLevel.TupleIsInt()).TupleNot()))
        {
          throw HException(HTuple(hv_GenParamName[hv_GenParamIndex])+" should be of type int");
        }
        if (0 != (int(hv_MaxLevel<2)))
        {
          throw HException(("Invalid value for parameter 'max_level': "+hv_MaxLevel)+". The minimum value is 2.");
        }
      }
      else if (0 != (int(HTuple(hv_GenParamName[hv_GenParamIndex])==HTuple("anchor_num_subscales"))))
      {
        hv_AnchorNumSubscales = hv_GenParam.TupleGetDictTuple("anchor_num_subscales");
        if (0 != ((hv_AnchorNumSubscales.TupleIsInt()).TupleNot()))
        {
          throw HException(HTuple(hv_GenParamName[hv_GenParamIndex])+" should be of type int");
        }
        if (0 != (int(hv_AnchorNumSubscales<1)))
        {
          throw HException(("Invalid value for parameter 'anchor_num_subscales': "+hv_AnchorNumSubscales)+". The minimum value is 1.");
        }
      }
      else if (0 != (int(HTuple(hv_GenParamName[hv_GenParamIndex])==HTuple("display_histogram"))))
      {
        CreateDict(&hv___Tmp_Ctrl_Dict_Init_0);
        SetDictTuple(hv___Tmp_Ctrl_Dict_Init_0, "comp", 1);
        CreateDict(&hv___Tmp_Ctrl_Dict_Init_1);
        SetDictTuple(hv___Tmp_Ctrl_Dict_Init_1, "comp", "true");
        hv_DisplayHistogram = ((hv_GenParam.TupleConcat(hv___Tmp_Ctrl_Dict_Init_1)).TupleTestEqualDictItem("display_histogram","comp")).TupleOr((hv_GenParam.TupleConcat(hv___Tmp_Ctrl_Dict_Init_0)).TupleTestEqualDictItem("display_histogram","comp"));
        hv___Tmp_Ctrl_Dict_Init_1 = HTuple::TupleConstant("HNULL");
        hv___Tmp_Ctrl_Dict_Init_0 = HTuple::TupleConstant("HNULL");
      }
      else if (0 != (int(HTuple(hv_GenParamName[hv_GenParamIndex])==HTuple("split"))))
      {
        hv_DatasetSplit = hv_GenParam.TupleGetDictTuple("split");
        if (0 != ((hv_DatasetSplit.TupleIsString()).TupleNot()))
        {
          throw HException(HTuple(hv_GenParamName[hv_GenParamIndex])+" should be of type string");
        }
      }
      else if (0 != (int(HTuple(hv_GenParamName[hv_GenParamIndex])==HTuple("class_ids_no_orientation"))))
      {
        hv_ClassIDsNoOrientation = hv_GenParam.TupleGetDictTuple("class_ids_no_orientation");
      }
      else if (0 != (int(HTuple(hv_GenParamName[hv_GenParamIndex])==HTuple("ignore_direction"))))
      {
        CreateDict(&hv___Tmp_Ctrl_Dict_Init_2);
        SetDictTuple(hv___Tmp_Ctrl_Dict_Init_2, "comp", 1);
        CreateDict(&hv___Tmp_Ctrl_Dict_Init_3);
        SetDictTuple(hv___Tmp_Ctrl_Dict_Init_3, "comp", "true");
        hv_IgnoreDirection = ((hv_GenParam.TupleConcat(hv___Tmp_Ctrl_Dict_Init_3)).TupleTestEqualDictItem("ignore_direction","comp")).TupleOr((hv_GenParam.TupleConcat(hv___Tmp_Ctrl_Dict_Init_2)).TupleTestEqualDictItem("ignore_direction","comp"));
        hv___Tmp_Ctrl_Dict_Init_3 = HTuple::TupleConstant("HNULL");
        hv___Tmp_Ctrl_Dict_Init_2 = HTuple::TupleConstant("HNULL");
      }
      else if (0 != (int(HTuple(hv_GenParamName[hv_GenParamIndex])==HTuple("max_num_samples"))))
      {
        hv_MaxNumSamples = hv_GenParam.TupleGetDictTuple("max_num_samples");
        if (0 != ((hv_MaxNumSamples.TupleIsInt()).TupleNot()))
        {
          throw HException(HTuple(hv_GenParamName[hv_GenParamIndex])+" should be of type int");
        }
        if (0 != (HTuple(int(hv_MaxNumSamples<1)).TupleAnd(int(hv_MaxNumSamples!=-1))))
        {
          throw HException(("Invalid value for parameter 'max_num_samples': "+hv_MaxNumSamples)+". Only -1 or values greater or equal to 1 are allowed.");
        }
      }
      else if (0 != (int(HTuple(hv_GenParamName[hv_GenParamIndex])==HTuple("compute_max_overlap"))))
      {
        CreateDict(&hv___Tmp_Ctrl_Dict_Init_4);
        SetDictTuple(hv___Tmp_Ctrl_Dict_Init_4, "comp", 1);
        CreateDict(&hv___Tmp_Ctrl_Dict_Init_5);
        SetDictTuple(hv___Tmp_Ctrl_Dict_Init_5, "comp", "true");
        hv_ComputeMaxOverlap = ((hv_GenParam.TupleConcat(hv___Tmp_Ctrl_Dict_Init_5)).TupleTestEqualDictItem("compute_max_overlap","comp")).TupleOr((hv_GenParam.TupleConcat(hv___Tmp_Ctrl_Dict_Init_4)).TupleTestEqualDictItem("compute_max_overlap","comp"));
        hv___Tmp_Ctrl_Dict_Init_5 = HTuple::TupleConstant("HNULL");
        hv___Tmp_Ctrl_Dict_Init_4 = HTuple::TupleConstant("HNULL");
      }
      else if (0 != (int((hv_AvailableGenParams.TupleFind(HTuple(hv_GenParamName[hv_GenParamIndex])))==-1)))
      {
        throw HException(("Unsupported generic parameter: '"+HTuple(hv_GenParamName[hv_GenParamIndex]))+"'");
      }
    }
    }
  }
  else
  {
    CreateDict(&hv_GenParam);
  }
  //
  //Check that all necessary keys (for this procedure) exist in the input dataset.
  hv_DatasetKeys.Clear();
  hv_DatasetKeys[0] = "image_dir";
  hv_DatasetKeys[1] = "samples";
  {
  HTuple end_val94 = (hv_DatasetKeys.TupleLength())-1;
  HTuple step_val94 = 1;
  for (hv_KeyIndex=0; hv_KeyIndex.Continue(end_val94, step_val94); hv_KeyIndex += step_val94)
  {
    GetDictParam(hv_DLDataset, "key_exists", HTuple(hv_DatasetKeys[hv_KeyIndex]), 
        &hv_DatasetKeyExists);
    if (0 != (hv_DatasetKeyExists.TupleNot()))
    {
      throw HException(("Missing key in DLDataset: '"+HTuple(hv_DatasetKeys[hv_KeyIndex]))+"'.");
    }
  }
  }
  //Check that MaxLevel >= MinLevel
  if (0 != (int(hv_MaxLevel<hv_MinLevel)))
  {
    throw HException("Value for parameter 'max_level' should not be smaller than 'min_level'.");
  }
  //
  //Get instance type of the dataset.
  //
  //Keys defining bounding boxes of instance type rectangle1 and rectangle2, respectively.
  hv_Rect1Keys.Clear();
  hv_Rect1Keys[0] = "bbox_row1";
  hv_Rect1Keys[1] = "bbox_col1";
  hv_Rect1Keys[2] = "bbox_row2";
  hv_Rect1Keys[3] = "bbox_col2";
  hv_Rect2Keys.Clear();
  hv_Rect2Keys[0] = "bbox_row";
  hv_Rect2Keys[1] = "bbox_col";
  hv_Rect2Keys[2] = "bbox_length1";
  hv_Rect2Keys[3] = "bbox_length2";
  hv_Rect2Keys[4] = "bbox_phi";
  //
  GetDictParam(HTuple((hv_DLDataset.TupleGetDictTuple("samples"))[0]), "key_exists", 
      hv_Rect1Keys, &hv_Rect1KeysExist);
  GetDictParam(HTuple((hv_DLDataset.TupleGetDictTuple("samples"))[0]), "key_exists", 
      hv_Rect2Keys, &hv_Rect2KeysExist);
  if (0 != (int((hv_Rect1KeysExist.TupleSum())==(hv_Rect1Keys.TupleLength()))))
  {
    hv_InstanceType = "rectangle1";
  }
  else if (0 != (int((hv_Rect2KeysExist.TupleSum())==(hv_Rect2Keys.TupleLength()))))
  {
    hv_InstanceType = "rectangle2";
  }
  else
  {
    throw HException("Please provide the data labeled for an object detection model of either instance type rectangle1 or rectangle2.");
  }
  //
  //Create output parameter dictionary.
  CreateDict(&(*hv_DLDetectionModelParam));
  //First we can set the class ids to the output dictionary.
  GetDictParam(hv_DLDataset, "key_exists", "class_ids", &hv_ClassIdsExist);
  if (0 != hv_ClassIdsExist)
  {
    GetDictParam(hv_DLDataset, "key_data_type", "class_ids", &hv___Tmp_Ctrl_Type);
    if (0 != (int(hv___Tmp_Ctrl_Type==HTuple("object"))))
    {
      SetDictObject(hv_DLDataset.TupleGetDictObject("class_ids"), (*hv_DLDetectionModelParam), 
          "class_ids");
    }
    else
    {
      SetDictTuple((*hv_DLDetectionModelParam), "class_ids", hv_DLDataset.TupleGetDictTuple("class_ids"));
    }
  }
  GetDictParam(hv_DLDataset, "key_exists", "class_names", &hv_ClassNamesExist);
  if (0 != hv_ClassNamesExist)
  {
    GetDictParam(hv_DLDataset, "key_data_type", "class_names", &hv___Tmp_Ctrl_Type);
    if (0 != (int(hv___Tmp_Ctrl_Type==HTuple("object"))))
    {
      SetDictObject(hv_DLDataset.TupleGetDictObject("class_names"), (*hv_DLDetectionModelParam), 
          "class_names");
    }
    else
    {
      SetDictTuple((*hv_DLDetectionModelParam), "class_names", hv_DLDataset.TupleGetDictTuple("class_names"));
    }
  }
  //Then, we also already know the instance type.
  SetDictTuple((*hv_DLDetectionModelParam), "instance_type", hv_InstanceType);
  //In case of rectangle2 we can add the parameter 'ignore_direction'.
  if (0 != (int(hv_InstanceType==HTuple("rectangle2"))))
  {
    if (0 != hv_IgnoreDirection)
    {
      SetDictTuple((*hv_DLDetectionModelParam), "ignore_direction", "true");
    }
    else
    {
      SetDictTuple((*hv_DLDetectionModelParam), "ignore_direction", "false");
    }
  }
  //
  //Create relevant information collections from the dataset.
  analyze_dl_dataset_detection(hv_DLDataset, hv_InstanceType, hv_ImageWidthTarget, 
      hv_ImageHeightTarget, hv_GenParam, &hv_Areas, &hv_AspectRatios, &hv_Angles, 
      &hv_MaxOverlap, &hv_MaxOverlapClassAgnostic);
  //Set the image width and target to the output dictionary.
  if (0 != (HTuple(int(hv_ImageWidthTarget==HTuple())).TupleOr(int(hv_ImageHeightTarget==HTuple()))))
  {
    hv_ImageWidthTarget = hv_GenParam.TupleGetDictTuple("image_width_target");
    hv_ImageHeightTarget = hv_GenParam.TupleGetDictTuple("image_height_target");
    RemoveDictKey(hv_GenParam, "image_width_target");
    RemoveDictKey(hv_GenParam, "image_height_target");
  }
  SetDictTuple((*hv_DLDetectionModelParam), "image_width", hv_ImageWidthTarget);
  SetDictTuple((*hv_DLDetectionModelParam), "image_height", hv_ImageHeightTarget);
  //
  if (0 != hv_ComputeMaxOverlap)
  {
    SetDictTuple((*hv_DLDetectionModelParam), "max_overlap", hv_MaxOverlap);
    SetDictTuple((*hv_DLDetectionModelParam), "max_overlap_class_agnostic", hv_MaxOverlapClassAgnostic);
  }
  //
  //Remove outliers in the data which could potentially have a big impact on the results
  //of this procedure. If you wish not to do so, comment out the following procedure calls
  //and set the variables AreasReduce, AspectRatiosReduced and AnglesReduced accordingly.
  remove_dl_data_outliers(hv_Areas, &hv_AreasReduced);
  remove_dl_data_outliers(hv_AspectRatios, &hv_AspectRatiosReduced);
  remove_dl_data_outliers(hv_Angles, &hv_AnglesReduced);
  //
  //Select min_level, max_level and anchor_num_subscales based on the retrieved ground truth
  //bounding box areas.
  select_dl_detection_levels(hv_AreasReduced, hv_MinLevel, hv_MaxLevel, hv_AnchorNumSubscales, 
      &hv_MinLevelToUse, &hv_MaxLevelToUse, &hv_AnchorNumSubscalesToUse);
  SetDictTuple((*hv_DLDetectionModelParam), "min_level", hv_MinLevelToUse);
  SetDictTuple((*hv_DLDetectionModelParam), "max_level", hv_MaxLevelToUse);
  SetDictTuple((*hv_DLDetectionModelParam), "anchor_num_subscales", hv_AnchorNumSubscalesToUse);
  //
  //Check if the given image dimensions and computed levels are compatible.
  if (0 != (HTuple(int((hv_ImageWidthTarget.TupleFmod(HTuple(2).TuplePow(hv_MaxLevelToUse)))>0)).TupleOr(int((hv_ImageHeightTarget.TupleFmod(HTuple(2).TuplePow(hv_MaxLevelToUse)))>0))))
  {
    hv_ErrorMessage = ((((("The target image dimensions "+hv_ImageWidthTarget)+"x")+hv_ImageHeightTarget)+" are not compatible with the computed maximum level ")+hv_MaxLevelToUse)+".\nThe image width and height must be a multiple of 2 to the power of the maximum level.";
    throw HException(hv_ErrorMessage);
  }
  //
  //Determine values for anchor aspect ratios and angles using k-means clustering.
  //
  //Minimum ratio of members each cluster should at least have.
  hv_MinRatio = 0.01;
  //Minimum distance between the cluster centers.
  hv_MinDiff = 0.1;
  //Number of centers to start k-means with. For aspect ratios, set K to 4.
  hv_K = 4;
  //Perform clustering of collected aspect ratios.
  cluster_dl_detection_param(hv_AspectRatiosReduced, hv_K, hv_MinRatio, hv_MinDiff, 
      0, &hv_ClusteredAspectRatios);
  SetDictTuple((*hv_DLDetectionModelParam), "anchor_aspect_ratios", hv_ClusteredAspectRatios);
  //
  //For rectangle2, also perform clustering on the angles.
  if (0 != (int(hv_InstanceType==HTuple("rectangle2"))))
  {
    //Since the variance for the angles is usually greater,
    //adapt K and MinDiff accordingly.
    hv_K = 8;
    hv_MinDiff = HTuple(45).TupleRad();
    //If 'ignore_direction' is set to true, we multiply the angles by 2 in order to stretch
    //the range from (-pi/2, pi/2] to (-pi, pi]. MinDiff has to be increased as well.
    if (0 != hv_IgnoreDirection)
    {
      hv_AnglesReduced = 2.0*hv_AnglesReduced;
      hv_MinDiff = HTuple(60).TupleRad();
    }
    //Perform clustering of collected angles.
    cluster_dl_detection_param(hv_AnglesReduced, hv_K, hv_MinRatio, hv_MinDiff, 1, 
        &hv_ClusteredAngles);
    //In case of 'ignore_direction', we have to retransform the cluster centers
    //from range (-pi, pi] to (-pi/2, pi/2].
    if (0 != hv_IgnoreDirection)
    {
      hv_ClusteredAngles = hv_ClusteredAngles/2.0;
    }
    //If we have ClassIDsNoOrientation and if there is a cluster center that is close
    //to 0.0, we set this cluster center to 0.0 to account for the typically many
    //ground truth boxes with angle 0.0.
    if (0 != (int((hv_ClassIDsNoOrientation.TupleLength())>0)))
    {
      hv_MinAngleIdx = ((hv_ClusteredAngles.TupleAbs()).TupleEqualElem((hv_ClusteredAngles.TupleAbs()).TupleMin())).TupleFind(1);
      if (0 != (int((HTuple(hv_ClusteredAngles[HTuple(hv_MinAngleIdx[0])]).TupleAbs())<(HTuple(5).TupleRad()))))
      {
        hv_ClusteredAngles[HTuple(hv_MinAngleIdx[0])] = 0.0;
      }
    }
    SetDictTuple((*hv_DLDetectionModelParam), "anchor_angles", hv_ClusteredAngles);
  }
  //
  //Display the histograms calculated from the data collections.
  hv_WindowBGColor = "light gray";
  hv_SplitText = "";
  if (0 != (int(hv_DatasetSplit!=HTuple("all"))))
  {
    hv_SplitText = (" ("+hv_DatasetSplit)+")";
  }
  if (0 != hv_DisplayHistogram)
  {
    //Plot histogram of bounding box areas.
    SetWindowAttr("background_color",hv_WindowBGColor);
    OpenWindow(0,0,512,400,0,"visible","",&hv_WindowHandle);
    HDevWindowStack::Push(hv_WindowHandle);
    plot_dl_detection_histogram(hv_Areas, "#ff6384", (HTuple("title").Append("label_x")), 
        ("Histogram of bounding box areas"+hv_SplitText).TupleConcat("Bounding box area"), 
        hv_WindowHandle);
    //Plot histogram of aspect ratios.
    SetWindowAttr("background_color",hv_WindowBGColor);
    OpenWindow(0,520,512,400,0,"visible","",&hv_WindowHandle2);
    HDevWindowStack::Push(hv_WindowHandle2);
    plot_dl_detection_histogram(hv_AspectRatios, "#66ff92", (HTuple("title").Append("label_x")), 
        ("Histogram of aspect ratios"+hv_SplitText).TupleConcat("Aspect ratio"), 
        hv_WindowHandle2);
    if (0 != (int(hv_InstanceType==HTuple("rectangle2"))))
    {
      //Plot histogram of anchor angles.
      SetWindowAttr("background_color",hv_WindowBGColor);
      OpenWindow(450,0,512,400,0,"visible","",&hv_WindowHandle3);
      HDevWindowStack::Push(hv_WindowHandle3);
      plot_dl_detection_histogram(hv_Angles, "#36a2eb", (HTuple("title").Append("label_x")), 
          ("Histogram of angles"+hv_SplitText).TupleConcat("Angle (rad)"), hv_WindowHandle3);
    }
  }
  //
  return;
}

// Chapter: Graphics / Output
// Short Description: Determine the optimum distance of the object to obtain a reasonable visualization 
void determine_optimum_pose_distance (HTuple hv_ObjectModel3DID, HTuple hv_CamParam, 
    HTuple hv_ImageCoverage, HTuple hv_PoseIn, HTuple *hv_PoseOut)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_Rows, hv_Cols, hv_MinMinZ, hv_BB, hv_Index;
  HTuple  hv_CurrBB, hv_Exception, hv_Seq, hv_DXMax, hv_DYMax;
  HTuple  hv_DZMax, hv_Diameter, hv_ZAdd, hv_BBX0, hv_BBX1;
  HTuple  hv_BBY0, hv_BBY1, hv_BBZ0, hv_BBZ1, hv_X, hv_Y;
  HTuple  hv_Z, hv_HomMat3DIn, hv_QX_In, hv_QY_In, hv_QZ_In;
  HTuple  hv_PoseInter, hv_HomMat3D, hv_QX, hv_QY, hv_QZ;
  HTuple  hv_Cx, hv_Cy, hv_DR, hv_DC, hv_MaxDist, hv_HomMat3DRotate;
  HTuple  hv_ImageWidth, hv_ImageHeight, hv_MinImageSize;
  HTuple  hv_Zs, hv_ZDiff, hv_ScaleZ, hv_ZNew;

  //Determine the optimum distance of the object to obtain
  //a reasonable visualization
  //
  hv_Rows = HTuple();
  hv_Cols = HTuple();
  hv_MinMinZ = 1e30;
  hv_BB = HTuple();
  {
  HTuple end_val7 = (hv_ObjectModel3DID.TupleLength())-1;
  HTuple step_val7 = 1;
  for (hv_Index=0; hv_Index.Continue(end_val7, step_val7); hv_Index += step_val7)
  {
    try
    {
      GetObjectModel3dParams(HTuple(hv_ObjectModel3DID[hv_Index]), "bounding_box1", 
          &hv_CurrBB);
      hv_BB = hv_BB.TupleConcat(hv_CurrBB);
    }
    // catch (Exception) 
    catch (HException &HDevExpDefaultException)
    {
      HDevExpDefaultException.ToHTuple(&hv_Exception);
      //3D object model is empty / has no bounding box -> ignore it
    }
  }
  }
  if (0 != (int((((hv_BB.TupleAbs()).TupleConcat(0)).TupleSum())==0.0)))
  {
    hv_BB.Clear();
    hv_BB.Append(-(HTuple(HTuple::TupleRand(3)*1e-20).TupleAbs()));
    hv_BB.Append(HTuple(HTuple::TupleRand(3)*1e-20).TupleAbs());
  }
  //Calculate diameter over all objects to be visualized
  hv_Seq = HTuple::TupleGenSequence(0,(hv_BB.TupleLength())-1,6);
  hv_DXMax = (HTuple(hv_BB[hv_Seq+3]).TupleMax())-(HTuple(hv_BB[hv_Seq]).TupleMin());
  hv_DYMax = (HTuple(hv_BB[hv_Seq+4]).TupleMax())-(HTuple(hv_BB[hv_Seq+1]).TupleMin());
  hv_DZMax = (HTuple(hv_BB[hv_Seq+5]).TupleMax())-(HTuple(hv_BB[hv_Seq+2]).TupleMin());
  hv_Diameter = (((hv_DXMax*hv_DXMax)+(hv_DYMax*hv_DYMax))+(hv_DZMax*hv_DZMax)).TupleSqrt();
  //Allow the visualization of single points or extremely small objects
  hv_ZAdd = 0.0;
  if (0 != (int((hv_Diameter.TupleMax())<1e-10)))
  {
    hv_ZAdd = 0.01;
  }
  //Set extremely small diameters to 1e-10 to avoid CZ == 0.0, which would lead
  //to projection errors
  if (0 != (int((hv_Diameter.TupleMin())<1e-10)))
  {
    hv_Diameter = hv_Diameter-(((((hv_Diameter-1e-10).TupleSgn())-1).TupleSgn())*1e-10);
  }
  //Move all points in front of the camera
  hv_BBX0 = HTuple(hv_BB[hv_Seq+0]);
  hv_BBX1 = HTuple(hv_BB[hv_Seq+3]);
  hv_BBY0 = HTuple(hv_BB[hv_Seq+1]);
  hv_BBY1 = HTuple(hv_BB[hv_Seq+4]);
  hv_BBZ0 = HTuple(hv_BB[hv_Seq+2]);
  hv_BBZ1 = HTuple(hv_BB[hv_Seq+5]);
  hv_X.Clear();
  hv_X.Append(hv_BBX0);
  hv_X.Append(hv_BBX0);
  hv_X.Append(hv_BBX0);
  hv_X.Append(hv_BBX0);
  hv_X.Append(hv_BBX1);
  hv_X.Append(hv_BBX1);
  hv_X.Append(hv_BBX1);
  hv_X.Append(hv_BBX1);
  hv_Y.Clear();
  hv_Y.Append(hv_BBY0);
  hv_Y.Append(hv_BBY0);
  hv_Y.Append(hv_BBY1);
  hv_Y.Append(hv_BBY1);
  hv_Y.Append(hv_BBY0);
  hv_Y.Append(hv_BBY0);
  hv_Y.Append(hv_BBY1);
  hv_Y.Append(hv_BBY1);
  hv_Z.Clear();
  hv_Z.Append(hv_BBZ0);
  hv_Z.Append(hv_BBZ1);
  hv_Z.Append(hv_BBZ0);
  hv_Z.Append(hv_BBZ1);
  hv_Z.Append(hv_BBZ0);
  hv_Z.Append(hv_BBZ1);
  hv_Z.Append(hv_BBZ0);
  hv_Z.Append(hv_BBZ1);
  PoseToHomMat3d(hv_PoseIn, &hv_HomMat3DIn);
  AffineTransPoint3d(hv_HomMat3DIn, hv_X, hv_Y, hv_Z, &hv_QX_In, &hv_QY_In, &hv_QZ_In);
  PoseCompose(((HTuple(0).Append(0)).TupleConcat((-(hv_QZ_In.TupleMin()))+(2*(hv_Diameter.TupleMax())))).TupleConcat((((HTuple(0).Append(0)).Append(0)).Append(0))), 
      hv_PoseIn, &hv_PoseInter);
  PoseToHomMat3d(hv_PoseInter, &hv_HomMat3D);
  //Determine the maximum extension of the projection
  AffineTransPoint3d(hv_HomMat3D, hv_X, hv_Y, hv_Z, &hv_QX, &hv_QY, &hv_QZ);
  Project3dPoint(hv_QX, hv_QY, hv_QZ, hv_CamParam, &hv_Rows, &hv_Cols);
  hv_MinMinZ = hv_QZ.TupleMin();
  get_cam_par_data(hv_CamParam, "cx", &hv_Cx);
  get_cam_par_data(hv_CamParam, "cy", &hv_Cy);
  hv_DR = hv_Rows-hv_Cy;
  hv_DC = hv_Cols-hv_Cx;
  hv_DR = (hv_DR.TupleMax())-(hv_DR.TupleMin());
  hv_DC = (hv_DC.TupleMax())-(hv_DC.TupleMin());
  hv_MaxDist = ((hv_DR*hv_DR)+(hv_DC*hv_DC)).TupleSqrt();
  //
  if (0 != (int(hv_MaxDist<1e-10)))
  {
    //If the object has no extension in the above projection (looking along
    //a line), we determine the extension of the object in a rotated view
    HomMat3dRotateLocal(hv_HomMat3D, HTuple(90).TupleRad(), "x", &hv_HomMat3DRotate);
    AffineTransPoint3d(hv_HomMat3DRotate, hv_X, hv_Y, hv_Z, &hv_QX, &hv_QY, &hv_QZ);
    Project3dPoint(hv_QX, hv_QY, hv_QZ, hv_CamParam, &hv_Rows, &hv_Cols);
    hv_DR = hv_Rows-hv_Cy;
    hv_DC = hv_Cols-hv_Cx;
    hv_DR = (hv_DR.TupleMax())-(hv_DR.TupleMin());
    hv_DC = (hv_DC.TupleMax())-(hv_DC.TupleMin());
    hv_MaxDist = (hv_MaxDist.TupleConcat(((hv_DR*hv_DR)+(hv_DC*hv_DC)).TupleSqrt())).TupleMax();
  }
  //
  get_cam_par_data(hv_CamParam, "image_width", &hv_ImageWidth);
  get_cam_par_data(hv_CamParam, "image_height", &hv_ImageHeight);
  hv_MinImageSize = (hv_ImageWidth.TupleConcat(hv_ImageHeight)).TupleMin();
  //
  hv_Z = ((const HTuple&)hv_PoseInter)[2];
  hv_Zs = hv_MinMinZ;
  hv_ZDiff = hv_Z-hv_Zs;
  hv_ScaleZ = hv_MaxDist/(((0.5*hv_MinImageSize)*hv_ImageCoverage)*2.0);
  hv_ZNew = ((hv_ScaleZ*hv_Zs)+hv_ZDiff)+hv_ZAdd;
  (*hv_PoseOut) = hv_PoseInter.TupleReplace(2,hv_ZNew);
  //
  return;
}

// Chapter: 3D Object Model / Transformations
void determine_visualization_pose_distance_aligned_with_y_axis (HTuple hv_ObjectModel3DRigidTrans5Tmp, 
    HTuple hv_WindowHandle1, HTuple *hv_PoseEstimatedDistance, HTuple *hv_Center)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_PoseCenterScene, hv_ObjectModel3DRigidTrans4;
  HTuple  hv_PoseRot, hv_ObjectModel3DRigidTrans5, hv_PoseTrans;
  HTuple  hv_ObjectModel3DRigidTrans6, hv_ObjectModel3D0;
  HTuple  hv_UnionObjectModel3D1, hv_RowNotUsed, hv_ColumnNotUsed;
  HTuple  hv_Width, hv_Height, hv_CamParam;

  get_object_models_center(hv_ObjectModel3DRigidTrans5Tmp, &(*hv_Center));
  CreatePose(-HTuple((*hv_Center)[0]), -HTuple((*hv_Center)[1]), -HTuple((*hv_Center)[2]), 
      0, 0, 0, "Rp+T", "gba", "point", &hv_PoseCenterScene);
  RigidTransObjectModel3d(hv_ObjectModel3DRigidTrans5Tmp, hv_PoseCenterScene, &hv_ObjectModel3DRigidTrans4);
  hv_PoseRot.Clear();
  hv_PoseRot[0] = 0;
  hv_PoseRot[1] = 0;
  hv_PoseRot[2] = 0;
  hv_PoseRot[3] = 90;
  hv_PoseRot[4] = 0;
  hv_PoseRot[5] = 0;
  hv_PoseRot[6] = 0;
  RigidTransObjectModel3d(hv_ObjectModel3DRigidTrans4, hv_PoseRot, &hv_ObjectModel3DRigidTrans5);
  hv_PoseTrans.Clear();
  hv_PoseTrans.Append(HTuple((*hv_Center)[0]));
  hv_PoseTrans.Append(HTuple((*hv_Center)[2]));
  hv_PoseTrans.Append(HTuple((*hv_Center)[1]));
  hv_PoseTrans.Append(0);
  hv_PoseTrans.Append(0);
  hv_PoseTrans.Append(0);
  hv_PoseTrans.Append(0);
  RigidTransObjectModel3d(hv_ObjectModel3DRigidTrans5, hv_PoseTrans, &hv_ObjectModel3DRigidTrans6);
  GenObjectModel3dFromPoints(0, 0, 0, &hv_ObjectModel3D0);
  UnionObjectModel3d(hv_ObjectModel3D0.TupleConcat(hv_ObjectModel3DRigidTrans6), 
      "points_surface", &hv_UnionObjectModel3D1);
  //
  GetWindowExtents(hv_WindowHandle1, &hv_RowNotUsed, &hv_ColumnNotUsed, &hv_Width, 
      &hv_Height);
  gen_cam_par_area_scan_division(0.06, 0, 8.5e-6, 8.5e-6, hv_Width/2, hv_Height/2, 
      hv_Width, hv_Height, &hv_CamParam);
  determine_optimum_pose_distance(hv_UnionObjectModel3D1, hv_CamParam, 0.9, hv_PoseCenterScene, 
      &(*hv_PoseEstimatedDistance));
  return;
}

// Chapter: Graphics / Window
// Short Description: Close all window handles contained in a dictionary. 
void dev_close_window_dict (HTuple hv_WindowHandleDict)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_WindowHandleDicts, hv_WindowDictIdx;
  HTuple  hv_WindowHandleKeys, hv_Index, hv_WindowHandles;
  HTuple  hv_Exception, hv_RemovedWindowIndices, hv_WindowHandleIndex;

  //
  //This procedure closes all window handles
  //that are contained in the dictionary WindowHandleDict.
  //
  hv_WindowHandleDicts = hv_WindowHandleDict;
  {
  HTuple end_val5 = (hv_WindowHandleDicts.TupleLength())-1;
  HTuple step_val5 = 1;
  for (hv_WindowDictIdx=0; hv_WindowDictIdx.Continue(end_val5, step_val5); hv_WindowDictIdx += step_val5)
  {
    hv_WindowHandleDict = HTuple(hv_WindowHandleDicts[hv_WindowDictIdx]);
    GetDictParam(hv_WindowHandleDict, "keys", HTuple(), &hv_WindowHandleKeys);
    {
    HTuple end_val8 = (hv_WindowHandleKeys.TupleLength())-1;
    HTuple step_val8 = 1;
    for (hv_Index=0; hv_Index.Continue(end_val8, step_val8); hv_Index += step_val8)
    {
      try
      {
        GetDictTuple(hv_WindowHandleDict, HTuple(hv_WindowHandleKeys[hv_Index]), 
            &hv_WindowHandles);
      }
      // catch (Exception) 
      catch (HException &HDevExpDefaultException)
      {
        HDevExpDefaultException.ToHTuple(&hv_Exception);
        continue;
      }
      hv_RemovedWindowIndices = HTuple();
      {
      HTuple end_val15 = (hv_WindowHandles.TupleLength())-1;
      HTuple step_val15 = 1;
      for (hv_WindowHandleIndex=0; hv_WindowHandleIndex.Continue(end_val15, step_val15); hv_WindowHandleIndex += step_val15)
      {
        //Not every entry has to be a window handle, therefore use try-catch.
        try
        {
          //Call set_window_param to check if the handle is a window handle.
          SetWindowParam(HTuple(hv_WindowHandles[hv_WindowHandleIndex]), "flush", 
              "true");
          HDevWindowStack::SetActive(HTuple(hv_WindowHandles[hv_WindowHandleIndex]));
          if (HDevWindowStack::IsOpen())
            CloseWindow(HDevWindowStack::Pop());
          hv_RemovedWindowIndices = hv_RemovedWindowIndices.TupleConcat(hv_WindowHandleIndex);
        }
        // catch (Exception) 
        catch (HException &HDevExpDefaultException)
        {
          HDevExpDefaultException.ToHTuple(&hv_Exception);
        }
      }
      }
      TupleRemove(hv_WindowHandles, hv_RemovedWindowIndices, &hv_WindowHandles);
      //If some entries remained, set reduced tuple. Otherwise, remove whole key entry.
      if (0 != (int((hv_WindowHandles.TupleLength())>0)))
      {
        SetDictTuple(hv_WindowHandleDict, HTuple(hv_WindowHandleKeys[hv_Index]), 
            hv_WindowHandles);
      }
      else
      {
        RemoveDictKey(hv_WindowHandleDict, HTuple(hv_WindowHandleKeys[hv_Index]));
      }
    }
    }
  }
  }
  //
  return;
}

// Chapter: Graphics / Window
// Short Description: Close the window if it is still open. 
void dev_close_window_if_open (HTuple hv_WindowHandle)
{

  // Local control variables
  HTuple  hv_CurrWindowHandle, hv_Exception;

  try
  {
    HDevWindowStack::SetActive(hv_WindowHandle);
    if (HDevWindowStack::IsOpen())
      hv_CurrWindowHandle = HDevWindowStack::GetActive();
    if (0 != (int(hv_CurrWindowHandle==hv_WindowHandle)))
    {
      if (HDevWindowStack::IsOpen())
        CloseWindow(HDevWindowStack::Pop());
    }
  }
  // catch (Exception) 
  catch (HException &HDevExpDefaultException)
  {
    HDevExpDefaultException.ToHTuple(&hv_Exception);
    //Window might already be closed -> ignore errors
  }
  return;
}

// Chapter: Graphics / Output
// Short Description: Display the axes of a 3d coordinate system 
void dev_disp_3d_coord_system (HTuple hv_WindowHandle, HTuple hv_CamParam, HTuple hv_Pose, 
    HTuple hv_CoordAxesLength)
{

  // Local iconic variables
  HObject  ho_Arrows;

  // Local control variables
  HTuple  hv_CameraType, hv_IsTelecentric, hv_TransWorld2Cam;
  HTuple  hv_OrigCamX, hv_OrigCamY, hv_OrigCamZ, hv_Row0;
  HTuple  hv_Column0, hv_X, hv_Y, hv_Z, hv_RowAxX, hv_ColumnAxX;
  HTuple  hv_RowAxY, hv_ColumnAxY, hv_RowAxZ, hv_ColumnAxZ;
  HTuple  hv_Distance, hv_HeadLength;

  //This procedure displays a 3D coordinate system.
  //It needs the procedure gen_arrow_contour_xld.
  //
  //Input parameters:
  //WindowHandle: The window where the coordinate system shall be displayed
  //CamParam: The camera parameters
  //Pose: The pose to be displayed
  //CoordAxesLength: The length of the coordinate axes in world coordinates
  //
  //Check, if Pose is a correct pose tuple.
  if (0 != (int((hv_Pose.TupleLength())!=7)))
  {
    return;
  }
  get_cam_par_data(hv_CamParam, "camera_type", &hv_CameraType);
  hv_IsTelecentric = int((hv_CameraType.TupleStrstr("telecentric"))!=-1);
  if (0 != (HTuple(int(HTuple(hv_Pose[2])==0.0)).TupleAnd(hv_IsTelecentric.TupleNot())))
  {
    //For projective cameras:
    //Poses with Z position zero cannot be projected
    //(that would lead to a division by zero error).
    return;
  }
  //Convert pose to a transformation matrix.
  PoseToHomMat3d(hv_Pose, &hv_TransWorld2Cam);
  //Project the world origin into the image.
  AffineTransPoint3d(hv_TransWorld2Cam, 0, 0, 0, &hv_OrigCamX, &hv_OrigCamY, &hv_OrigCamZ);
  Project3dPoint(hv_OrigCamX, hv_OrigCamY, hv_OrigCamZ, hv_CamParam, &hv_Row0, &hv_Column0);
  //Project the coordinate axes into the image.
  AffineTransPoint3d(hv_TransWorld2Cam, hv_CoordAxesLength, 0, 0, &hv_X, &hv_Y, &hv_Z);
  Project3dPoint(hv_X, hv_Y, hv_Z, hv_CamParam, &hv_RowAxX, &hv_ColumnAxX);
  AffineTransPoint3d(hv_TransWorld2Cam, 0, hv_CoordAxesLength, 0, &hv_X, &hv_Y, &hv_Z);
  Project3dPoint(hv_X, hv_Y, hv_Z, hv_CamParam, &hv_RowAxY, &hv_ColumnAxY);
  AffineTransPoint3d(hv_TransWorld2Cam, 0, 0, hv_CoordAxesLength, &hv_X, &hv_Y, &hv_Z);
  Project3dPoint(hv_X, hv_Y, hv_Z, hv_CamParam, &hv_RowAxZ, &hv_ColumnAxZ);
  //
  //Generate an XLD contour for each axis.
  DistancePp((hv_Row0.TupleConcat(hv_Row0)).TupleConcat(hv_Row0), (hv_Column0.TupleConcat(hv_Column0)).TupleConcat(hv_Column0), 
      (hv_RowAxX.TupleConcat(hv_RowAxY)).TupleConcat(hv_RowAxZ), (hv_ColumnAxX.TupleConcat(hv_ColumnAxY)).TupleConcat(hv_ColumnAxZ), 
      &hv_Distance);
  hv_HeadLength = ((((hv_Distance.TupleMax())/12.0).TupleConcat(5.0)).TupleMax()).TupleInt();
  gen_arrow_contour_xld(&ho_Arrows, (hv_Row0.TupleConcat(hv_Row0)).TupleConcat(hv_Row0), 
      (hv_Column0.TupleConcat(hv_Column0)).TupleConcat(hv_Column0), (hv_RowAxX.TupleConcat(hv_RowAxY)).TupleConcat(hv_RowAxZ), 
      (hv_ColumnAxX.TupleConcat(hv_ColumnAxY)).TupleConcat(hv_ColumnAxZ), hv_HeadLength, 
      hv_HeadLength);
  //
  if (HDevWindowStack::IsOpen())
    DispObj(ho_Arrows, HDevWindowStack::GetActive());
  if (HDevWindowStack::IsOpen())
    DispText(HDevWindowStack::GetActive(),"X", "image", hv_RowAxX+3, hv_ColumnAxX+3, 
        "red", "box", "false");
  if (HDevWindowStack::IsOpen())
    DispText(HDevWindowStack::GetActive(),"Y", "image", hv_RowAxY+3, hv_ColumnAxY+3, 
        "green", "box", "false");
  if (HDevWindowStack::IsOpen())
    DispText(HDevWindowStack::GetActive(),"Z", "image", hv_RowAxZ+3, hv_ColumnAxZ+3, 
        "blue", "box", "false");
  return;
}

