// Chapter: Matching / Deep Counting
// Short Description: Draw templates for Deep Counting models. 
void draw_deep_counting_templates (HObject ho_Image, HObject *ho_TemplateRegion, 
    HObject *ho_Template)
{

  // Local iconic variables
  HObject  ho_Rectangle1, ho_ImageReduced, ho_Rectangle2;

  // Local control variables
  HTuple  hv_DrawText, hv_TextRow, hv_TextColumn;
  HTuple  hv_ButtonHeight, hv_ButtonWidth, hv_ValueColors;
  HTuple  hv_BoxColor, hv_HighlightColor, hv_TemplateRegionColor;
  HTuple  hv_Rectangles, hv_WindowRow, hv_WindowColumn, hv_Width;
  HTuple  hv_Height, hv_WindowHandle, hv__, hv_WindowWidth;
  HTuple  hv_WindowHeight, hv_WindowHeightExtension, hv_WindowImageRatioHeight;
  HTuple  hv_WindowImageRatioWidth, hv_WindowRow2, hv_WindowColumn2;
  HTuple  hv_WindowRatio, hv_ImageRow2, hv_ImageColumn2, hv_ImageRatio;
  HTuple  hv_SetPartColumn2, hv_ImageWindowRatioWidth, hv_ImageRow2InWindow;
  HTuple  hv_SetPartRow2, hv_ImageWindowRatioHeight, hv_ImageCol2InWindow;
  HTuple  hv_ExplanationText, hv_PrevWindowHeight, hv_TextWindowRow;
  HTuple  hv_TextWindowColumn, hv_WindowHandleText, hv_RectText;
  HTuple  hv_Index, hv_RectTextWidth, hv_RectTextHeight, hv_UndoTextWidth;
  HTuple  hv_UndoTextHeight, hv_ContinueTextWidth, hv_ContinueTextHeight;
  HTuple  hv_SelectedButton, hv_Row1, hv_Column1, hv_Row2;
  HTuple  hv_Column2, hv_Phi1, hv_Length1, hv_Length2, hv_Count;

  //This procedure is used to draw user-defined templates
  //for the Deep Counting workflow.
  //
  //Output parameters:
  //Template: The template which is later used for finding the objects.
  //TemplateRegion: The regions for later creating the matching template.
  //
  //Initialize parameters for draw procedure.
  hv_DrawText = HTuple();
  hv_TextRow = HTuple();
  hv_TextColumn = HTuple();
  hv_ButtonHeight = HTuple();
  hv_ButtonWidth = HTuple();
  hv_ValueColors = HTuple();
  hv_BoxColor = HTuple();
  hv_HighlightColor = "#fce9d4";
  hv_TemplateRegionColor = "#00f0f0c0";
  //
  hv_Rectangles = HTuple();
  GenEmptyObj(&(*ho_Template));
  GenEmptyObj(&(*ho_TemplateRegion));
  //
  //Open new window for drawing the regions.
  hv_WindowRow = 0;
  hv_WindowColumn = 0;
  GetImageSize(ho_Image, &hv_Width, &hv_Height);
  dev_open_window_fit_size(hv_WindowRow, hv_WindowColumn, hv_Width, hv_Height, (HTuple(500).Append(800)), 
      (HTuple(400).Append(600)), &hv_WindowHandle);
  GetWindowExtents(hv_WindowHandle, &hv__, &hv__, &hv_WindowWidth, &hv_WindowHeight);
  hv_WindowHeightExtension = 40;
  if (HDevWindowStack::IsOpen())
    SetWindowExtents(HDevWindowStack::GetActive(),hv_WindowRow, hv_WindowColumn, 
        hv_WindowWidth, hv_WindowHeight+hv_WindowHeightExtension);
  //
  // dev_set_preferences(...); only in hdevelop
  // dev_set_preferences(...); only in hdevelop
  //
  //Set part for the image to be displayed later and adapt window size (+ MarginBottom + MapColorBarWidth).
  GetWindowExtents(hv_WindowHandle, &hv__, &hv__, &hv_WindowWidth, &hv_WindowHeight);
  hv_WindowImageRatioHeight = hv_WindowHeight/(hv_Height*1.0);
  hv_WindowImageRatioWidth = hv_WindowWidth/(hv_Width*1.0);
  //
  //Set window part such that image is displayed undistorted.
  hv_WindowRow2 = hv_WindowHeight;
  hv_WindowColumn2 = hv_WindowWidth;
  hv_WindowRatio = hv_WindowColumn2/(hv_WindowRow2*1.0);
  //
  hv_ImageRow2 = hv_Height+(hv_WindowHeightExtension/hv_WindowImageRatioHeight);
  hv_ImageColumn2 = hv_Width+(0/hv_WindowImageRatioWidth);
  hv_ImageRatio = hv_ImageColumn2/(hv_ImageRow2*1.0);
  if (0 != (int(hv_ImageRatio>hv_WindowRatio)))
  {
    //
    //Extend image until right window border.
    hv_SetPartColumn2 = hv_ImageColumn2;
    hv_ImageWindowRatioWidth = hv_ImageColumn2/(hv_WindowColumn2*1.0);
    hv_ImageRow2InWindow = hv_ImageRow2/hv_ImageWindowRatioWidth;
    hv_SetPartRow2 = hv_ImageRow2+((hv_WindowRow2-hv_ImageRow2InWindow)/hv_WindowImageRatioWidth);
  }
  else
  {
    //
    //Extend image until bottom of window.
    hv_SetPartRow2 = hv_ImageRow2;
    hv_ImageWindowRatioHeight = hv_ImageRow2/(hv_WindowRow2*1.0);
    hv_ImageCol2InWindow = hv_ImageColumn2/hv_ImageWindowRatioHeight;
    hv_SetPartColumn2 = hv_ImageColumn2+((hv_WindowColumn2-hv_ImageCol2InWindow)/hv_WindowImageRatioHeight);
  }
  if (HDevWindowStack::IsOpen())
    SetPart(HDevWindowStack::GetActive(),0, 0, hv_SetPartRow2-1, hv_SetPartColumn2-1);
  if (HDevWindowStack::IsOpen())
    DispObj(ho_Image, HDevWindowStack::GetActive());
  //
  //
  //Calculate the window size.
  GetWindowExtents(hv_WindowHandle, &hv__, &hv__, &hv_WindowWidth, &hv_WindowHeight);
  //
  //Visualize explanation text and image.
  hv_ExplanationText = HTuple();
  hv_ExplanationText[hv_ExplanationText.TupleLength()] = " * Choose between 'Rectangle1' or 'Rectangle2' templates.";
  hv_ExplanationText[hv_ExplanationText.TupleLength()] = " ";
  hv_ExplanationText[hv_ExplanationText.TupleLength()] = " * Draw one or more templates.";
  hv_ExplanationText[hv_ExplanationText.TupleLength()] = "   (Right-click) to finish drawing the current template.";
  hv_ExplanationText[hv_ExplanationText.TupleLength()] = " ";
  hv_ExplanationText[hv_ExplanationText.TupleLength()] = " * Press the 'Undo' button to remove the last drawn object.";
  hv_ExplanationText[hv_ExplanationText.TupleLength()] = " ";
  hv_ExplanationText[hv_ExplanationText.TupleLength()] = " * Click 'Continue' to finish.";
  //
  //Get coordinates of previous window.
  hv_PrevWindowHeight = ((const HTuple&)hv_WindowHeight)[0];
  //
  //Open window in same row.
  hv_TextWindowRow = hv_WindowRow;
  hv_TextWindowColumn = hv_WindowColumn+hv_WindowWidth;
  if (0 != (int(hv_TextWindowColumn!=0)))
  {
    hv_TextWindowColumn += 5;
  }
  //
  dev_open_window_fit_size(hv_TextWindowRow, hv_TextWindowColumn, 560, hv_PrevWindowHeight, 
      560, hv_PrevWindowHeight, &hv_WindowHandleText);
  set_display_font(hv_WindowHandleText, 14, "mono", "true", "false");
  if (HDevWindowStack::IsOpen())
    DispText(HDevWindowStack::GetActive(),hv_ExplanationText, "window", "top", "left", 
        "black", HTuple(), HTuple());
  HDevWindowStack::SetActive(hv_WindowHandle);
  //
  //
  //Visualize the buttons for drawing the template regions.
  //
  //Add the 'Rectangle1' and 'Rectangle2' buttons.
  hv_RectText.Clear();
  hv_RectText[0] = "Rectangle1";
  hv_RectText[1] = "Rectangle2";
  hv_DrawText = hv_DrawText.TupleConcat(hv_RectText);
  {
  HTuple end_val101 = (hv_RectText.TupleLength())-1;
  HTuple step_val101 = 1;
  for (hv_Index=0; hv_Index.Continue(end_val101, step_val101); hv_Index += step_val101)
  {
    //Calculate the text size for 'Rectangle1' and 'Rectangle2' button.
    GetStringExtents(hv_WindowHandle, HTuple(hv_RectText[hv_Index]), &hv__, &hv__, 
        &hv_RectTextWidth, &hv_RectTextHeight);
    //
    hv_TextRow = hv_TextRow.TupleConcat((hv_WindowHeight-hv_RectTextHeight)-20);
    //
    if (0 != (int(HTuple(hv_RectText[hv_Index])==HTuple("Rectangle1"))))
    {
      hv_TextColumn = hv_TextColumn.TupleConcat(20);
    }
    else
    {
      hv_TextColumn = hv_TextColumn.TupleConcat(40+hv_RectTextWidth);
    }
    //Set the button size and color for 'Rectangle1' and 'Rectangle2'.
    hv_ButtonWidth = hv_ButtonWidth.TupleConcat(hv_RectTextWidth*1.2);
    hv_ButtonHeight = hv_ButtonHeight.TupleConcat(hv_RectTextHeight*1.5);
    hv_ValueColors = hv_ValueColors.TupleConcat("black");
    hv_BoxColor = hv_BoxColor.TupleConcat("#f28d26");
  }
  }
  //
  //Add the 'Undo' button.
  hv_DrawText = hv_DrawText.TupleConcat("Undo");
  //Calculate the text size for 'Undo' button.
  GetStringExtents(hv_WindowHandle, "Undo", &hv__, &hv__, &hv_UndoTextWidth, &hv_UndoTextHeight);
  //
  hv_TextRow = hv_TextRow.TupleConcat((hv_WindowHeight-hv_UndoTextHeight)-20);
  hv_TextColumn = hv_TextColumn.TupleConcat((40+(2*hv_RectTextWidth))+40);
  //Set the button size and color for 'Undo'.
  hv_ButtonWidth = hv_ButtonWidth.TupleConcat(hv_UndoTextWidth*1.2);
  hv_ButtonHeight = hv_ButtonHeight.TupleConcat(hv_UndoTextHeight*1.5);
  hv_ValueColors = hv_ValueColors.TupleConcat("black");
  hv_BoxColor = hv_BoxColor.TupleConcat("#f28d26");
  //
  //Add the 'Continue' button.
  hv_DrawText = hv_DrawText.TupleConcat("Continue");
  //Calculate the text size for 'Continue' button.
  GetStringExtents(hv_WindowHandle, "Continue", &hv__, &hv__, &hv_ContinueTextWidth, 
      &hv_ContinueTextHeight);
  //
  hv_TextRow = hv_TextRow.TupleConcat((hv_WindowHeight-hv_ContinueTextHeight)-20);
  hv_TextColumn = hv_TextColumn.TupleConcat((hv_WindowWidth-hv_ContinueTextWidth)-30);
  //Set the button size and color for 'Continue'.
  hv_ButtonWidth = hv_ButtonWidth.TupleConcat(hv_ContinueTextWidth*1.2);
  hv_ButtonHeight = hv_ButtonHeight.TupleConcat(hv_ContinueTextHeight*1.5);
  hv_ValueColors = hv_ValueColors.TupleConcat("black");
  hv_BoxColor = hv_BoxColor.TupleConcat("#f28d26");
  //
  while (true)
  {
    //Visualize image and templates.
    if (HDevWindowStack::IsOpen())
      DispObj(ho_Image, HDevWindowStack::GetActive());
    if (HDevWindowStack::IsOpen())
      SetColor(HDevWindowStack::GetActive(),hv_TemplateRegionColor);
    if (HDevWindowStack::IsOpen())
      DispObj((*ho_TemplateRegion), HDevWindowStack::GetActive());
    //
    dev_disp_button(hv_DrawText, hv_TextRow, hv_TextColumn, hv_ButtonWidth, hv_ButtonHeight, 
        hv_ValueColors, hv_BoxColor, hv_HighlightColor, hv_WindowHandle, &hv_SelectedButton);
    //
    //Re-draw image and templates.
    if (HDevWindowStack::IsOpen())
      DispObj(ho_Image, HDevWindowStack::GetActive());
    if (HDevWindowStack::IsOpen())
      SetColor(HDevWindowStack::GetActive(),hv_TemplateRegionColor);
    if (HDevWindowStack::IsOpen())
      DispObj((*ho_TemplateRegion), HDevWindowStack::GetActive());
    //
    if (0 != (int(hv_SelectedButton==0)))
    {
      //This is the 'Rectangle1' case.
      DrawRectangle1(hv_WindowHandle, &hv_Row1, &hv_Column1, &hv_Row2, &hv_Column2);
      if (0 != (int(hv_Column2==0)))
      {
        //Right-click --> abort drawing the rectangle
        continue;
      }
      GenRectangle1(&ho_Rectangle1, hv_Row1, hv_Column1, hv_Row2, hv_Column2);
      ConcatObj((*ho_TemplateRegion), ho_Rectangle1, &(*ho_TemplateRegion));
      ReduceDomain(ho_Image, ho_Rectangle1, &ho_ImageReduced);
      ConcatObj((*ho_Template), ho_ImageReduced, &(*ho_Template));
    }
    else if (0 != (int(hv_SelectedButton==1)))
    {
      //This is the 'Rectangle2' case.
      DrawRectangle2(hv_WindowHandle, &hv_Row1, &hv_Column1, &hv_Phi1, &hv_Length1, 
          &hv_Length2);
      if (0 != (int(hv_Length1==0)))
      {
        //Right-click --> abort drawing the rectangle
        continue;
      }
      GenRectangle2(&ho_Rectangle2, hv_Row1, hv_Column1, hv_Phi1, hv_Length1, hv_Length2);
      ConcatObj((*ho_TemplateRegion), ho_Rectangle2, &(*ho_TemplateRegion));
      ReduceDomain(ho_Image, ho_Rectangle2, &ho_ImageReduced);
      ConcatObj((*ho_Template), ho_ImageReduced, &(*ho_Template));
    }
    else if (0 != (int(hv_SelectedButton==2)))
    {
      //This is the 'Undo' button case.
      CountObj((*ho_TemplateRegion), &hv_Count);
      if (0 != (int(hv_Count==0)))
      {
        continue;
      }
      else
      {
        RemoveObj((*ho_TemplateRegion), &(*ho_TemplateRegion), hv_Count);
        RemoveObj((*ho_Template), &(*ho_Template), hv_Count);
      }
    }
    else if (0 != (int(hv_SelectedButton==3)))
    {
      //This is the 'Continue' button case.
      break;
    }
  }
  //
  // dev_set_preferences(...); only in hdevelop
  // dev_set_preferences(...); only in hdevelop
  //
  //Close the windows.
  if (HDevWindowStack::IsOpen())
    CloseWindow(HDevWindowStack::Pop());
  if (HDevWindowStack::IsOpen())
    CloseWindow(HDevWindowStack::Pop());
  return;
}

// Chapter: Graphics / Output
// Short Description: Render 3D object models in a buffer window. 
void dump_image_output (HObject ho_BackgroundImage, HTuple hv_Parameters, HTuple hv_WindowHandleBuffer, 
    HTuple hv_Scene3D, HTuple hv_AlphaOrig, HTuple hv_ObjectModel3DID, HTuple hv_GenParamName, 
    HTuple hv_GenParamValue, HTuple hv_CamParam, HTuple hv_Poses, HTuple hv_ColorImage, 
    HTuple hv_Title, HTuple hv_Information, HTuple hv_Labels, HTuple hv_VisualizeTrackball, 
    HTuple hv_DisplayButtons, HTuple hv_TrackballCenterRow, HTuple hv_TrackballCenterCol, 
    HTuple hv_TrackballRadiusPixel, HTuple hv_SelectedObject, HTuple hv_VisualizeRotationCenter, 
    HTuple hv_RotationCenter, HTuple hv_Type, HTuple hv_Message, HTuple hv_DispViewPoint, 
    HTuple hv_ViewPoint)
{

  // Local iconic variables
  HObject  ho_ModelContours, ho_TrackballContour;
  HObject  ho_CrossRotCenter;

  // Local control variables
  HTuple  hv_gUsesOpenGL, hv_gAlphaDeselected, hv_gButtons;
  HTuple  hv_Exception, hv_Index, hv_Exception1, hv_DeselectedIdx;
  HTuple  hv_DeselectedName, hv_DeselectedValue, hv_gLabelsDecor;
  HTuple  hv_Pose, hv_HomMat3D, hv_Center, hv_CenterCamX;
  HTuple  hv_CenterCamY, hv_CenterCamZ, hv_CenterRow, hv_CenterCol;
  HTuple  hv_Label, hv_Ascent, hv_Descent, hv_TextWidth, hv_TextHeight;
  HTuple  hv_gDispObjOffset, hv_RotCenterRow, hv_RotCenterCol;
  HTuple  hv_Orientation, hv_Colors, hv_Type1, hv_Message1;
  HTuple  hv_Type2, hv_Message2;

  GetMessageTuple(hv_Parameters, "gUsesOpenGL", &hv_gUsesOpenGL);
  GetMessageTuple(hv_Parameters, "gAlphaDeselected", &hv_gAlphaDeselected);
  GetMessageTuple(hv_Parameters, "gButtons", &hv_gButtons);

  //
  //Display background image
  ClearWindow(hv_WindowHandleBuffer);
  if (0 != hv_ColorImage)
  {
    DispColor(ho_BackgroundImage, hv_WindowHandleBuffer);
  }
  else
  {
    DispImage(ho_BackgroundImage, hv_WindowHandleBuffer);
  }
  //
  //Display objects
  if (0 != (int((hv_SelectedObject.TupleSum())==(hv_SelectedObject.TupleLength()))))
  {
    if (0 != (int(hv_gUsesOpenGL==HTuple("true"))))
    {
      try
      {
        DisplayScene3d(hv_WindowHandleBuffer, hv_Scene3D, 0);
      }
      // catch (Exception) 
      catch (HException &HDevExpDefaultException)
      {
        HDevExpDefaultException.ToHTuple(&hv_Exception);
        if (0 != (HTuple(HTuple(int(HTuple(hv_Exception[0])==5185)).TupleOr(int(HTuple(hv_Exception[0])==5188))).TupleOr(int(HTuple(hv_Exception[0])==5187))))
        {
          hv_gUsesOpenGL = "false";
          SetMessageTuple(hv_Parameters, "gUsesOpenGL", hv_gUsesOpenGL);
        }
        else
        {
          throw HException(hv_Exception);
        }
      }
    }
    if (0 != (int(hv_gUsesOpenGL==HTuple("false"))))
    {
      //* NO OpenGL, use fallback
      disp_object_model_no_opengl(&ho_ModelContours, hv_ObjectModel3DID, hv_GenParamName, 
          hv_GenParamValue, hv_WindowHandleBuffer, hv_CamParam, hv_Poses);
    }
  }
  else
  {
    {
    HTuple end_val32 = (hv_AlphaOrig.TupleLength())-1;
    HTuple step_val32 = 1;
    for (hv_Index=0; hv_Index.Continue(end_val32, step_val32); hv_Index += step_val32)
    {
      if (0 != (int(HTuple(hv_SelectedObject[hv_Index])==1)))
      {
        SetScene3dInstanceParam(hv_Scene3D, hv_Index, "alpha", HTuple(hv_AlphaOrig[hv_Index]));
      }
      else
      {
        SetScene3dInstanceParam(hv_Scene3D, hv_Index, "alpha", hv_gAlphaDeselected);
      }
    }
    }
    try
    {
      if (0 != (int(hv_gUsesOpenGL==HTuple("false"))))
      {
        throw HException(HTuple());
      }
      DisplayScene3d(hv_WindowHandleBuffer, hv_Scene3D, 0);
    }
    // catch (Exception1) 
    catch (HException &HDevExpDefaultException)
    {
      HDevExpDefaultException.ToHTuple(&hv_Exception1);
      //* NO OpenGL, use fallback
      hv_DeselectedIdx = hv_SelectedObject.TupleFind(0);
      if (0 != (int(hv_DeselectedIdx!=-1)))
      {
        hv_DeselectedName = "color_"+hv_DeselectedIdx;
        hv_DeselectedValue = HTuple(hv_DeselectedName.TupleLength(),"gray");
      }
      disp_object_model_no_opengl(&ho_ModelContours, hv_ObjectModel3DID, hv_GenParamName.TupleConcat(hv_DeselectedName), 
          hv_GenParamValue.TupleConcat(hv_DeselectedValue), hv_WindowHandleBuffer, 
          hv_CamParam, hv_Poses);
    }
    {
    HTuple end_val53 = (hv_AlphaOrig.TupleLength())-1;
    HTuple step_val53 = 1;
    for (hv_Index=0; hv_Index.Continue(end_val53, step_val53); hv_Index += step_val53)
    {
      SetScene3dInstanceParam(hv_Scene3D, hv_Index, "alpha", HTuple(hv_AlphaOrig[hv_Index]));
    }
    }
  }
  //
  //Display labels
  if (0 != (int(hv_Labels!=HTuple())))
  {
    GetMessageTuple(hv_Parameters, "gLabelsDecor", &hv_gLabelsDecor);
    SetColor(hv_WindowHandleBuffer, HTuple(hv_gLabelsDecor[0]));
    {
    HTuple end_val62 = (hv_ObjectModel3DID.TupleLength())-1;
    HTuple step_val62 = 1;
    for (hv_Index=0; hv_Index.Continue(end_val62, step_val62); hv_Index += step_val62)
    {
      //Project the center point of the current model
      hv_Pose = hv_Poses.TupleSelectRange(hv_Index*7,(hv_Index*7)+6);
      PoseToHomMat3d(hv_Pose, &hv_HomMat3D);
      try
      {
        GetObjectModel3dParams(HTuple(hv_ObjectModel3DID[hv_Index]), "center", &hv_Center);
        AffineTransPoint3d(hv_HomMat3D, HTuple(hv_Center[0]), HTuple(hv_Center[1]), 
            HTuple(hv_Center[2]), &hv_CenterCamX, &hv_CenterCamY, &hv_CenterCamZ);
        Project3dPoint(hv_CenterCamX, hv_CenterCamY, hv_CenterCamZ, hv_CamParam, 
            &hv_CenterRow, &hv_CenterCol);
        hv_Label = HTuple(hv_Labels[hv_Index]);
        if (0 != (int(hv_Label!=HTuple(""))))
        {
          GetStringExtents(hv_WindowHandleBuffer, hv_Label, &hv_Ascent, &hv_Descent, 
              &hv_TextWidth, &hv_TextHeight);
          GetMessageTuple(hv_Parameters, "gDispObjOffset", &hv_gDispObjOffset);
          disp_message(hv_WindowHandleBuffer, hv_Label, "window", (hv_CenterRow-(hv_TextHeight/2))+HTuple(hv_gDispObjOffset[0]), 
              (hv_CenterCol-(hv_TextWidth/2))+HTuple(hv_gDispObjOffset[1]), HTuple(), 
              HTuple(hv_gLabelsDecor[1]));
        }
      }
      // catch (Exception) 
      catch (HException &HDevExpDefaultException)
      {
        HDevExpDefaultException.ToHTuple(&hv_Exception);
        //Unable to get the center of the 3D object model. It is probably empty -> do not display any label
      }
    }
    }
  }
  //
  //Visualize the trackball if desired
  if (0 != hv_VisualizeTrackball)
  {
    SetLineWidth(hv_WindowHandleBuffer, 1);
    GenEllipseContourXld(&ho_TrackballContour, hv_TrackballCenterRow, hv_TrackballCenterCol, 
        0, hv_TrackballRadiusPixel, hv_TrackballRadiusPixel, 0, 6.28318, "positive", 
        1.5);
    SetColor(hv_WindowHandleBuffer, "dim gray");
    DispXld(ho_TrackballContour, hv_WindowHandleBuffer);
  }
  //
  //Visualize the rotation center if desired
  if (0 != (HTuple(int(hv_VisualizeRotationCenter!=0)).TupleAnd(int((hv_RotationCenter.TupleLength())==3))))
  {
    if (0 != (int(HTuple(hv_RotationCenter[2])<1e-10)))
    {
      hv_RotationCenter[2] = 1e-10;
    }
    Project3dPoint(HTuple(hv_RotationCenter[0]), HTuple(hv_RotationCenter[1]), HTuple(hv_RotationCenter[2]), 
        hv_CamParam, &hv_RotCenterRow, &hv_RotCenterCol);
    hv_Orientation = HTuple(90).TupleRad();
    if (0 != (int(hv_VisualizeRotationCenter==1)))
    {
      hv_Orientation = HTuple(45).TupleRad();
    }
    GenCrossContourXld(&ho_CrossRotCenter, hv_RotCenterRow, hv_RotCenterCol, hv_TrackballRadiusPixel/25.0, 
        hv_Orientation);
    SetLineWidth(hv_WindowHandleBuffer, 3);
    QueryColor(hv_WindowHandleBuffer, &hv_Colors);
    SetColor(hv_WindowHandleBuffer, "light gray");
    DispXld(ho_CrossRotCenter, hv_WindowHandleBuffer);
    SetLineWidth(hv_WindowHandleBuffer, 1);
    SetColor(hv_WindowHandleBuffer, "dim gray");
    DispXld(ho_CrossRotCenter, hv_WindowHandleBuffer);
  }
  //
  //Display title
  if (0 != (int((hv_Type.TupleLength())==1)))
  {
    hv_Type1 = hv_Type;
    hv_Message1 = hv_Message;
    write_note(hv_WindowHandleBuffer, hv_Type1, hv_Message1);
  }
  else if (0 != (int((hv_Type.TupleLength())==2)))
  {
    hv_Type1 = ((const HTuple&)hv_Type)[0];
    hv_Type2 = ((const HTuple&)hv_Type)[1];
    hv_Message1 = ((const HTuple&)hv_Message)[0];
    hv_Message2 = hv_Message.TupleSelectRange(1,(hv_Message.TupleLength())-1);
    write_note(hv_WindowHandleBuffer, hv_Type1, hv_Message1);
    SetTposition(hv_WindowHandleBuffer, 1, 12);
    write_note(hv_WindowHandleBuffer, hv_Type2, hv_Message2);
  }
  if (0 != (int(hv_DispViewPoint==HTuple("true"))))
  {
    disp_message(hv_WindowHandleBuffer, (((("ViewPoint [m]\n   X :"+(HTuple(hv_ViewPoint[0]).TupleString(".2f")))+"\n   Y: ")+(HTuple(hv_ViewPoint[1]).TupleString(".2f")))+"\n   Z: ")+(HTuple(hv_ViewPoint[2]).TupleString(".2f")), 
        "window", 300, 12, "#FFA500", "false");
  }

  disp_title_and_information(hv_Parameters, hv_WindowHandleBuffer, hv_Title, hv_Information);
  //
  //Display the 'Exit' button
  if (0 != (int(hv_DisplayButtons==HTuple("true"))))
  {
    disp_buttons(hv_Parameters, hv_WindowHandleBuffer);
  }
  //
  return;
}

// Chapter: Graphics / Output
// Short Description: Render 3D object models in a buffer window. 
void dump_image_output_visualize_object_model_3d (HObject ho_BackgroundImage, HTuple hv_WindowHandleBuffer, 
    HTuple hv_Scene3D, HTuple hv_AlphaOrig, HTuple hv_ObjectModel3DID, HTuple hv_GenParamName, 
    HTuple hv_GenParamValue, HTuple hv_CamParam, HTuple hv_Poses, HTuple hv_ColorImage, 
    HTuple hv_Title, HTuple hv_Information, HTuple hv_Labels, HTuple hv_VisualizeTrackball, 
    HTuple hv_DisplayContinueButton, HTuple hv_TrackballCenterRow, HTuple hv_TrackballCenterCol, 
    HTuple hv_TrackballRadiusPixel, HTuple hv_SelectedObject, HTuple hv_VisualizeRotationCenter, 
    HTuple hv_RotationCenter)
{

  // Local iconic variables
  HObject  ho_ModelContours, ho_TrackballContour;
  HObject  ho_CrossRotCenter;

  // Local control variables
  HTuple  ExpTmpLocalVar_gUsesOpenGL, hv_Exception;
  HTuple  hv_Index, hv_Exception1, hv_DeselectedIdx, hv_DeselectedName;
  HTuple  hv_DeselectedValue, hv_Pose, hv_HomMat3D, hv_Center;
  HTuple  hv_CenterCamX, hv_CenterCamY, hv_CenterCamZ, hv_CenterRow;
  HTuple  hv_CenterCol, hv_Label, hv_Sublabels, hv_Ascent;
  HTuple  hv_Descent, hv_TextWidth, hv_TextHeight, hv_Index2;
  HTuple  hv_TextWidth2, hv_TextHeight2, hv_RotCenterRow;
  HTuple  hv_RotCenterCol, hv_Orientation, hv_Colors;

  //global tuple gAlphaDeselected
  //global tuple gTerminationButtonLabel
  //global tuple gDispObjOffset
  //global tuple gLabelsDecor
  //global tuple gUsesOpenGL
  //
  //Display background image
  ClearWindow(hv_WindowHandleBuffer);
  if (0 != hv_ColorImage)
  {
    DispColor(ho_BackgroundImage, hv_WindowHandleBuffer);
  }
  else
  {
    DispImage(ho_BackgroundImage, hv_WindowHandleBuffer);
  }
  //
  //Display objects
  if (0 != (int((hv_SelectedObject.TupleSum())==(hv_SelectedObject.TupleLength()))))
  {
    if (0 != (int(ExpGetGlobalVar_gUsesOpenGL()==HTuple("true"))))
    {
      try
      {
        DisplayScene3d(hv_WindowHandleBuffer, hv_Scene3D, 0);
      }
      // catch (Exception) 
      catch (HException &HDevExpDefaultException)
      {
        HDevExpDefaultException.ToHTuple(&hv_Exception);
        if (0 != (HTuple(HTuple(int(HTuple(hv_Exception[0])==5185)).TupleOr(int(HTuple(hv_Exception[0])==5188))).TupleOr(int(HTuple(hv_Exception[0])==5187))))
        {
          ExpTmpLocalVar_gUsesOpenGL = "false";
          ExpSetGlobalVar_gUsesOpenGL(ExpTmpLocalVar_gUsesOpenGL);
        }
        else
        {
          throw HException(hv_Exception);
        }
      }
    }
    if (0 != (int(ExpGetGlobalVar_gUsesOpenGL()==HTuple("false"))))
    {
      //* NO OpenGL, use fallback
      disp_object_model_no_opengl(&ho_ModelContours, hv_ObjectModel3DID, hv_GenParamName, 
          hv_GenParamValue, hv_WindowHandleBuffer, hv_CamParam, hv_Poses);
    }
  }
  else
  {
    {
    HTuple end_val32 = (hv_AlphaOrig.TupleLength())-1;
    HTuple step_val32 = 1;
    for (hv_Index=0; hv_Index.Continue(end_val32, step_val32); hv_Index += step_val32)
    {
      if (0 != (int(HTuple(hv_SelectedObject[hv_Index])==1)))
      {
        SetScene3dInstanceParam(hv_Scene3D, hv_Index, "alpha", HTuple(hv_AlphaOrig[hv_Index]));
      }
      else
      {
        SetScene3dInstanceParam(hv_Scene3D, hv_Index, "alpha", ExpGetGlobalVar_gAlphaDeselected());
      }
    }
    }
    try
    {
      if (0 != (int(ExpGetGlobalVar_gUsesOpenGL()==HTuple("false"))))
      {
        throw HException(HTuple());
      }
      DisplayScene3d(hv_WindowHandleBuffer, hv_Scene3D, 0);
    }
    // catch (Exception1) 
    catch (HException &HDevExpDefaultException)
    {
      HDevExpDefaultException.ToHTuple(&hv_Exception1);
      //* NO OpenGL, use fallback
      hv_DeselectedIdx = hv_SelectedObject.TupleFind(0);
      if (0 != (int(hv_DeselectedIdx!=-1)))
      {
        hv_DeselectedName = "color_"+hv_DeselectedIdx;
        hv_DeselectedValue = HTuple(hv_DeselectedName.TupleLength(),"gray");
      }
      disp_object_model_no_opengl(&ho_ModelContours, hv_ObjectModel3DID, hv_GenParamName.TupleConcat(hv_DeselectedName), 
          hv_GenParamValue.TupleConcat(hv_DeselectedValue), hv_WindowHandleBuffer, 
          hv_CamParam, hv_Poses);
    }
    {
    HTuple end_val53 = (hv_AlphaOrig.TupleLength())-1;
    HTuple step_val53 = 1;
    for (hv_Index=0; hv_Index.Continue(end_val53, step_val53); hv_Index += step_val53)
    {
      SetScene3dInstanceParam(hv_Scene3D, hv_Index, "alpha", HTuple(hv_AlphaOrig[hv_Index]));
    }
    }
  }
  //
  //Display labels
  if (0 != (int(hv_Labels!=HTuple())))
  {
    SetColor(hv_WindowHandleBuffer, HTuple(ExpGetGlobalVar_gLabelsDecor()[0]));
    {
    HTuple end_val61 = (hv_ObjectModel3DID.TupleLength())-1;
    HTuple step_val61 = 1;
    for (hv_Index=0; hv_Index.Continue(end_val61, step_val61); hv_Index += step_val61)
    {
      //Project the center point of the current model
      hv_Pose = hv_Poses.TupleSelectRange(hv_Index*7,(hv_Index*7)+6);
      PoseToHomMat3d(hv_Pose, &hv_HomMat3D);
      try
      {
        GetObjectModel3dParams(HTuple(hv_ObjectModel3DID[hv_Index]), "center", &hv_Center);
        AffineTransPoint3d(hv_HomMat3D, HTuple(hv_Center[0]), HTuple(hv_Center[1]), 
            HTuple(hv_Center[2]), &hv_CenterCamX, &hv_CenterCamY, &hv_CenterCamZ);
        Project3dPoint(hv_CenterCamX, hv_CenterCamY, hv_CenterCamZ, hv_CamParam, 
            &hv_CenterRow, &hv_CenterCol);
        hv_Label = HTuple(hv_Labels[hv_Index]);
        if (0 != (int(hv_Label!=HTuple(""))))
        {
          //Work around the fact that get_string_extents() does not handle newlines as we want
          TupleSplit(hv_Label, "\n", &hv_Sublabels);
          GetStringExtents(hv_WindowHandleBuffer, HTuple(hv_Sublabels[0]), &hv_Ascent, 
              &hv_Descent, &hv_TextWidth, &hv_TextHeight);
          {
          HTuple end_val74 = (hv_Sublabels.TupleLength())-1;
          HTuple step_val74 = 1;
          for (hv_Index2=1; hv_Index2.Continue(end_val74, step_val74); hv_Index2 += step_val74)
          {
            GetStringExtents(hv_WindowHandleBuffer, HTuple(hv_Sublabels[hv_Index2]), 
                &hv_Ascent, &hv_Descent, &hv_TextWidth2, &hv_TextHeight2);
            hv_TextHeight += hv_TextHeight2;
            hv_TextWidth = hv_TextWidth.TupleMax2(hv_TextWidth2);
          }
          }
          disp_message(hv_WindowHandleBuffer, hv_Label, "window", (hv_CenterRow-(hv_TextHeight/2))+HTuple(ExpGetGlobalVar_gDispObjOffset()[0]), 
              (hv_CenterCol-(hv_TextWidth/2))+HTuple(ExpGetGlobalVar_gDispObjOffset()[1]), 
              HTuple(), HTuple(ExpGetGlobalVar_gLabelsDecor()[1]));
        }
      }
      // catch (Exception) 
      catch (HException &HDevExpDefaultException)
      {
        HDevExpDefaultException.ToHTuple(&hv_Exception);
        //The 3D object model might not have a center because it is empty
        //-> do not display any label
      }
    }
    }
  }
  //
  //Visualize the trackball if desired
  if (0 != hv_VisualizeTrackball)
  {
    SetLineWidth(hv_WindowHandleBuffer, 1);
    GenEllipseContourXld(&ho_TrackballContour, hv_TrackballCenterRow, hv_TrackballCenterCol, 
        0, hv_TrackballRadiusPixel, hv_TrackballRadiusPixel, 0, 6.28318, "positive", 
        1.5);
    SetColor(hv_WindowHandleBuffer, "dim gray");
    DispXld(ho_TrackballContour, hv_WindowHandleBuffer);
  }
  //
  //Visualize the rotation center if desired
  if (0 != (HTuple(int(hv_VisualizeRotationCenter!=0)).TupleAnd(int((hv_RotationCenter.TupleLength())==3))))
  {
    if (0 != (int(HTuple(hv_RotationCenter[2])<1e-10)))
    {
      hv_RotationCenter[2] = 1e-10;
    }
    Project3dPoint(HTuple(hv_RotationCenter[0]), HTuple(hv_RotationCenter[1]), HTuple(hv_RotationCenter[2]), 
        hv_CamParam, &hv_RotCenterRow, &hv_RotCenterCol);
    hv_Orientation = HTuple(90).TupleRad();
    if (0 != (int(hv_VisualizeRotationCenter==1)))
    {
      hv_Orientation = HTuple(45).TupleRad();
    }
    GenCrossContourXld(&ho_CrossRotCenter, hv_RotCenterRow, hv_RotCenterCol, hv_TrackballRadiusPixel/25.0, 
        hv_Orientation);
    SetLineWidth(hv_WindowHandleBuffer, 3);
    QueryColor(hv_WindowHandleBuffer, &hv_Colors);
    SetColor(hv_WindowHandleBuffer, "light gray");
    DispXld(ho_CrossRotCenter, hv_WindowHandleBuffer);
    SetLineWidth(hv_WindowHandleBuffer, 1);
    SetColor(hv_WindowHandleBuffer, "dim gray");
    DispXld(ho_CrossRotCenter, hv_WindowHandleBuffer);
  }
  //
  //Display title
  disp_title_and_information_visualize_object_model_3d(hv_WindowHandleBuffer, hv_Title, 
      hv_Information);
  //
  //Display the 'Exit' button
  if (0 != (int(hv_DisplayContinueButton==HTuple("true"))))
  {
    disp_continue_button(hv_WindowHandleBuffer);
  }
  //
  return;
}

// Chapter: 3D Reconstruction / Multi-View Stereo
// Short Description: Estimate a bounding box for 3D reconstruction based on a stereo setup. 
void estimate_bounding_box_3d_reconstruction (HTuple hv_StereoModelID, HTuple hv_ObjectHeight, 
    HTuple *hv_BoundingBox)
{

  // Local iconic variables
  HObject  ho_PlaneConeIntersections, ho_ContourFrom;
  HObject  ho_ContourTo, ho_RectangleFrom, ho_RectangleTo;
  HObject  ho_ContoursIntersection, ho_PlaneConeIntersectionUnion;
  HObject  ho_ObjectSelected;

  // Local control variables
  HTuple  hv_CameraSetupModelID, hv_ReferenceCamera;
  HTuple  hv_From, hv_To, hv_NumCameras, hv_ObjectModel3DCone;
  HTuple  hv_DistanceCameras, hv_CameraIndex, hv_CamPose;
  HTuple  hv_DistanceCamera, hv_ConeLength, hv_Type, hv_ObjectModel3D;
  HTuple  hv_Index1, hv_ObjectModel3DIntersectionFrom, hv_ObjectModel3DIntersectionTo;
  HTuple  hv_XFrom, hv_YFrom, hv_XTo, hv_YTo, hv_Row, hv_Column;
  HTuple  hv_Phi, hv_Length1, hv_Length2, hv_Number, hv_Index2;
  HTuple  hv_RowContour, hv_ColumnContour;

  //The goal of this procedure is to estimate bounding box parameters
  //for 3D reconstruction. This is done by intersecting the
  //cones of sight of the cameras with a plane defined by the pose
  //of the reference calibration plate.
  //
  if (0 != (int(hv_ObjectHeight==0)))
  {
    throw HException("Object height must not be zero.");
  }
  //Check whether the coordinate system has been moved by setting a pose
  //with the parameter 'coord_transf_pose' in set_camera_setup_param.
  //If this is not the case, the origin is still in one of the cameras.
  //However, this procedures needs the origin to be in a calibration plate.
  GetStereoModelParam(hv_StereoModelID, "camera_setup_model", &hv_CameraSetupModelID);
  GetCameraSetupParam(hv_CameraSetupModelID, "general", "reference_camera", &hv_ReferenceCamera);
  if (0 != (int(hv_ReferenceCamera!=-1)))
  {
    throw HException("Please set the 'coord_transf_pose' to the pose of an calibration plate that lies horizontally in the image using the get_calib_data and set_camera_setup_param.");
  }
  //Check whether the image pairs have been set.
  GetStereoModelImagePairs(hv_StereoModelID, &hv_From, &hv_To);
  if (0 != (HTuple(int((hv_From.TupleLength())==0)).TupleOr(int((hv_To.TupleLength())==0))))
  {
    throw HException("Please define the image pairs first with 'get_stereo_model_image_pairs.'");
  }
  //
  //First, we generate 3D object models that represent the cones of sight of the cameras,
  //like in the procedure gen_camera_setup_object_model_3d.
  GetCameraSetupParam(hv_CameraSetupModelID, "general", "num_cameras", &hv_NumCameras);
  hv_ObjectModel3DCone = HTuple();
  hv_DistanceCameras = HTuple();
  {
  HTuple end_val28 = hv_NumCameras-1;
  HTuple step_val28 = 1;
  for (hv_CameraIndex=0; hv_CameraIndex.Continue(end_val28, step_val28); hv_CameraIndex += step_val28)
  {
    GetCameraSetupParam(hv_CameraSetupModelID, hv_CameraIndex, "pose", &hv_CamPose);
    hv_DistanceCamera = (((HTuple(hv_CamPose[0])*HTuple(hv_CamPose[0]))+(HTuple(hv_CamPose[1])*HTuple(hv_CamPose[1])))+(HTuple(hv_CamPose[2])*HTuple(hv_CamPose[2]))).TupleSqrt();
    hv_DistanceCameras = hv_DistanceCameras.TupleConcat(hv_DistanceCamera);
    hv_ConeLength = hv_DistanceCamera*2.0;
    //Distinguish cases with/without projection center.
    GetCameraSetupParam(hv_CameraSetupModelID, hv_CameraIndex, "type", &hv_Type);
    if (0 != (hv_Type.TupleRegexpTest("telecentric")))
    {
      gen_cone_telecentric_object_model_3d(hv_CameraSetupModelID, hv_CameraIndex, 
          hv_ConeLength, &hv_ObjectModel3D);
    }
    else
    {
      gen_cone_perspective_object_model_3d(hv_CameraSetupModelID, hv_CameraIndex, 
          hv_ConeLength, &hv_ObjectModel3D);
    }
    hv_ObjectModel3DCone = hv_ObjectModel3DCone.TupleConcat(hv_ObjectModel3D);
  }
  }
  //
  //Then, we intersect these cones of sight with a plane that lies horizontally
  //in the origin of the stereo setup. We do this simultaneously for the
  //previously defined image pairs.
  GenEmptyObj(&ho_PlaneConeIntersections);
  {
  HTuple end_val47 = (hv_From.TupleLength())-1;
  HTuple step_val47 = 1;
  for (hv_Index1=0; hv_Index1.Continue(end_val47, step_val47); hv_Index1 += step_val47)
  {
    IntersectPlaneObjectModel3d(HTuple(hv_ObjectModel3DCone[HTuple(hv_From[hv_Index1])]), 
        ((((((HTuple(0).Append(0)).Append(0)).Append(0)).Append(0)).Append(0)).Append(0)), 
        &hv_ObjectModel3DIntersectionFrom);
    IntersectPlaneObjectModel3d(HTuple(hv_ObjectModel3DCone[HTuple(hv_To[hv_Index1])]), 
        ((((((HTuple(0).Append(0)).Append(0)).Append(0)).Append(0)).Append(0)).Append(0)), 
        &hv_ObjectModel3DIntersectionTo);
    //
    //Get the coordinates of the 3D object models that represent the intersection.
    GetObjectModel3dParams(hv_ObjectModel3DIntersectionFrom, "point_coord_x", &hv_XFrom);
    GetObjectModel3dParams(hv_ObjectModel3DIntersectionFrom, "point_coord_y", &hv_YFrom);
    GetObjectModel3dParams(hv_ObjectModel3DIntersectionTo, "point_coord_x", &hv_XTo);
    GetObjectModel3dParams(hv_ObjectModel3DIntersectionTo, "point_coord_y", &hv_YTo);
    //
    //The, we want to intersect the intersections of the image pair. We do this in 2D using XLDs.
    //Generate the XLD of the 'From' intersection.
    GenContourPolygonXld(&ho_ContourFrom, hv_XFrom, hv_YFrom);
    //Generate the XLD of the 'To' intersection.
    GenContourPolygonXld(&ho_ContourTo, hv_XTo, hv_YTo);
    //
    //The order of the coordinates from get_object_model_3d_params might not be ideal.
    //Thus, we compute the smallest rectangle around the created XLD.
    SmallestRectangle2Xld(ho_ContourFrom, &hv_Row, &hv_Column, &hv_Phi, &hv_Length1, 
        &hv_Length2);
    GenRectangle2ContourXld(&ho_RectangleFrom, hv_Row, hv_Column, hv_Phi, hv_Length1, 
        hv_Length2);
    SmallestRectangle2Xld(ho_ContourTo, &hv_Row, &hv_Column, &hv_Phi, &hv_Length1, 
        &hv_Length2);
    GenRectangle2ContourXld(&ho_RectangleTo, hv_Row, hv_Column, hv_Phi, hv_Length1, 
        hv_Length2);
    //
    //Intersect and concatenate the intersections
    IntersectionClosedContoursXld(ho_RectangleFrom, ho_RectangleTo, &ho_ContoursIntersection
        );
    ConcatObj(ho_PlaneConeIntersections, ho_ContoursIntersection, &ho_PlaneConeIntersections
        );
    ClearObjectModel3d(hv_ObjectModel3DIntersectionFrom);
    ClearObjectModel3d(hv_ObjectModel3DIntersectionTo);
  }
  }
  //
  //Union all intersections of all image pairs.
  GenEmptyObj(&ho_PlaneConeIntersectionUnion);
  CountObj(ho_PlaneConeIntersections, &hv_Number);
  {
  HTuple end_val80 = hv_Number;
  HTuple step_val80 = 1;
  for (hv_Index2=1; hv_Index2.Continue(end_val80, step_val80); hv_Index2 += step_val80)
  {
    SelectObj(ho_PlaneConeIntersections, &ho_ObjectSelected, hv_Index2);
    Union2ClosedContoursXld(ho_ObjectSelected, ho_PlaneConeIntersectionUnion, &ho_PlaneConeIntersectionUnion
        );
  }
  }
  //
  //Get the coordinates of the resulting XLD, which represents the area
  //in 2D where the reconstruction is possible.
  GetContourXld(ho_PlaneConeIntersectionUnion, &hv_RowContour, &hv_ColumnContour);
  //
  //Based on this contour, we can easily access the parameters of the bounding box.
  if (0 != (int(hv_ObjectHeight>0)))
  {
    (*hv_BoundingBox).Clear();
    (*hv_BoundingBox).Append(hv_RowContour.TupleMin());
    (*hv_BoundingBox).Append(hv_ColumnContour.TupleMin());
    (*hv_BoundingBox).Append(-hv_ObjectHeight);
    (*hv_BoundingBox).Append(hv_RowContour.TupleMax());
    (*hv_BoundingBox).Append(hv_ColumnContour.TupleMax());
    (*hv_BoundingBox).Append(0);
  }
  else
  {
    (*hv_BoundingBox).Clear();
    (*hv_BoundingBox).Append(hv_RowContour.TupleMin());
    (*hv_BoundingBox).Append(hv_ColumnContour.TupleMin());
    (*hv_BoundingBox).Append(0);
    (*hv_BoundingBox).Append(hv_RowContour.TupleMax());
    (*hv_BoundingBox).Append(hv_ColumnContour.TupleMax());
    (*hv_BoundingBox).Append(-hv_ObjectHeight);
  }
  //
  //Clean up.
  ClearCameraSetupModel(hv_CameraSetupModelID);
  ClearObjectModel3d(hv_ObjectModel3DCone);
  return;
}

// Chapter: Calibration / Camera Parameters
// Short Description: Estimate the camera parameters of a 3D sensor. 
void estimate_camera_parameters_from_object_model_3d (HTuple hv_ObjectModel3D, HTuple *hv_CameraParam, 
    HTuple *hv_CameraPose)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_XCoords, hv_YCoords, hv_ZCoords, hv_Rows;
  HTuple  hv_Columns, hv_MappingSize, hv_Width, hv_Height;
  HTuple  hv_CameraParamStart, hv_CameraPoseStart, hv_CalibDataID;
  HTuple  hv_Error;

  //
  //This procedure estimates the camera parameters of a 3D sensor.
  //The camera parameters and the camera pose are found such that
  //the observed 3D points are projected onto their original 2D
  //image coordinates.
  //
  //Note that the 3D points must be distributed throughout the
  //relevant volume. If for example all 3D points lie on a single
  //plane, the calibration will be less accurate.
  //
  //The resulting camera parameters and pose can be used to project
  //matching results into the range images.
  //
  //Get 3D coordinates.
  GetObjectModel3dParams(hv_ObjectModel3D, "point_coord_x", &hv_XCoords);
  GetObjectModel3dParams(hv_ObjectModel3D, "point_coord_y", &hv_YCoords);
  GetObjectModel3dParams(hv_ObjectModel3D, "point_coord_z", &hv_ZCoords);
  //Get 2D coordinates.
  GetObjectModel3dParams(hv_ObjectModel3D, "mapping_row", &hv_Rows);
  GetObjectModel3dParams(hv_ObjectModel3D, "mapping_col", &hv_Columns);
  //Start camera parameters.
  GetObjectModel3dParams(hv_ObjectModel3D, "mapping_size", &hv_MappingSize);
  hv_Width = ((const HTuple&)hv_MappingSize)[0];
  hv_Height = ((const HTuple&)hv_MappingSize)[1];
  gen_cam_par_area_scan_division(0.012, 0, 5.2e-006, 5.2e-006, hv_Width/2, hv_Height/2, 
      hv_Width, hv_Height, &hv_CameraParamStart);
  hv_CameraPoseStart.Clear();
  hv_CameraPoseStart[0] = 0;
  hv_CameraPoseStart[1] = 0;
  hv_CameraPoseStart[2] = 0;
  hv_CameraPoseStart[3] = 0;
  hv_CameraPoseStart[4] = 0;
  hv_CameraPoseStart[5] = 0;
  hv_CameraPoseStart[6] = 0;
  //Calibrate the sensor.
  CreateCalibData("calibration_object", 1, 1, &hv_CalibDataID);
  SetCalibDataCalibObject(hv_CalibDataID, 0, (hv_XCoords.TupleConcat(hv_YCoords)).TupleConcat(hv_ZCoords));
  SetCalibDataCamParam(hv_CalibDataID, 0, "area_scan_division", hv_CameraParamStart);
  SetCalibDataObservPoints(hv_CalibDataID, 0, 0, 0, hv_Rows, hv_Columns, "all", hv_CameraPoseStart);
  CalibrateCameras(hv_CalibDataID, &hv_Error);
  GetCalibData(hv_CalibDataID, "camera", 0, "params", &(*hv_CameraParam));
  GetCalibData(hv_CalibDataID, "calib_obj_pose", (HTuple(0).Append(0)), "pose", &(*hv_CameraPose));
  return;
}

// Chapter: 3D Matching / 3D Gripping Point Detection
// Short Description: Propose a direction roughly orthogonal to the surface. 
void estimate_dl_3d_sorting_direction (HObject ho_X, HObject ho_Y, HObject ho_Z, 
    HTuple *hv_Direction)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_ObjectModel3D, hv_ObjectModel3DEdges;
  HTuple  hv_Pose, hv_HomMat3D;

  //Proposes a direction roughly orthogonal to the surface
  //described by X, Y, Z. Results are best for planar
  //surfaces like an empty table or bin bottom.
  //
  XyzToObjectModel3d(ho_X, ho_Y, ho_Z, &hv_ObjectModel3D);
  EdgesObjectModel3d(hv_ObjectModel3D, 0.1, "_debug", "true", &hv_ObjectModel3DEdges);
  GetObjectModel3dParams(hv_ObjectModel3DEdges, "&viewpose", &hv_Pose);
  PoseToHomMat3d((((HTuple(0).Append(0)).Append(0)).TupleConcat(HTuple(hv_Pose[((HTuple(3).Append(4)).Append(5))]))).TupleConcat(0), 
      &hv_HomMat3D);
  (*hv_Direction).Clear();
  (*hv_Direction).Append(HTuple(hv_HomMat3D[2]));
  (*hv_Direction).Append(HTuple(hv_HomMat3D[6]));
  (*hv_Direction).Append(HTuple(hv_HomMat3D[10]));
  return;
}

// Chapter: Image / Features
void estimate_noise_real (HObject ho_Image, HTuple hv_OutlierRemovalAmount, HTuple *hv_Sigma)
{

  // Local iconic variables
  HObject  ho_ImageFiltered, ho_RegionErosion;

  // Local control variables
  HTuple  hv_Rows, hv_Columns, hv_Grayval, hv_NumToRemove;
  HTuple  hv_Exception;

  //See documentation of estimate_noise for more information
  //about the used Immerkaer noise estimation method.

  ConvolImage(ho_Image, &ho_ImageFiltered, (((((((((((HTuple(3).Append(3)).Append(1)).Append(1)).Append(-2)).Append(1)).Append(-2)).Append(4)).Append(-2)).Append(1)).Append(-2)).Append(1)), 
      "mirrored");

  //convol_image will use parts of the background, which might have undefined pixels
  //Remove those parts
  ErosionRectangle1(ho_Image, &ho_RegionErosion, 3, 3);

  GetRegionPoints(ho_RegionErosion, &hv_Rows, &hv_Columns);
  if (0 != (int((hv_Rows.TupleLength())<30)))
  {
    //Too few points for a robust noise estimation
    //This can happen, for example, if the points are very sparse in the XYZ images
    (*hv_Sigma) = -1;
  }
  else
  {
    GetGrayval(ho_ImageFiltered, hv_Rows, hv_Columns, &hv_Grayval);
    hv_Grayval = hv_Grayval.TupleAbs();
    //Instead of the original formula, we use the more robust median
    //to avoid false negatives
    if (0 != (int(hv_OutlierRemovalAmount>0)))
    {
      TupleSort(hv_Grayval, &hv_Grayval);
      hv_NumToRemove = (((hv_Grayval.TupleLength())*hv_OutlierRemovalAmount)*0.5).TupleInt();
      //Catch some special cases
      try
      {
        hv_Grayval = hv_Grayval.TupleSelectRange(hv_NumToRemove,((hv_Grayval.TupleLength())-hv_NumToRemove)-1);
      }
      // catch (Exception) 
      catch (HException &HDevExpDefaultException)
      {
        HDevExpDefaultException.ToHTuple(&hv_Exception);
        //Catch the special case when we'd remove all values
        hv_Grayval = hv_Grayval.TupleMedian();
      }
    }
    (*hv_Sigma) = ((HTuple((HTuple(180).TupleRad())/2.0).TupleSqrt())*(1.0/6.0))*((hv_Grayval.TupleAbs()).TupleMean());
  }

  return;

}

// Chapter: System / Operating System
// Short Description: Estimate the remaining time for a task given the current progress. 
void estimate_progress (HTuple hv_SecondsStart, HTuple hv_ProgressMin, HTuple hv_ProgressCurrent, 
    HTuple hv_ProgressMax, HTuple *hv_SecondsElapsed, HTuple *hv_SecondsRemaining, 
    HTuple *hv_ProgressPercent, HTuple *hv_ProgressPerSecond)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_SecondsNow, hv_Epsilon, hv_ProgressRemaining;

  //
  //This procedure estimates the remaining time in seconds,
  //given a start time and a progress value.
  //
  //Get current time.
  CountSeconds(&hv_SecondsNow);
  //
  //Get elapsed time span.
  (*hv_SecondsElapsed) = hv_SecondsNow-hv_SecondsStart;
  //
  //A very small additive constant to avoid division by zero.
  hv_Epsilon = 1e-6;
  //
  //Estimate remaining time based on elapsed time.
  hv_ProgressRemaining = hv_ProgressMax-hv_ProgressCurrent;
  (*hv_ProgressPerSecond) = ((hv_ProgressCurrent-hv_ProgressMin).TupleReal())/(((*hv_SecondsElapsed).TupleReal())+hv_Epsilon);
  (*hv_SecondsRemaining) = hv_ProgressRemaining/((*hv_ProgressPerSecond)+hv_Epsilon);
  //
  //Get current progress in percent.
  (*hv_ProgressPercent) = (100*((hv_ProgressCurrent-hv_ProgressMin).TupleReal()))/(((hv_ProgressMax-hv_ProgressMin).TupleReal())+hv_Epsilon);
  return;
}

// Chapter: Graphics / Output
void estimate_visualization_pose_object_model_3d (HTuple hv_ObjectModel3D, HTuple hv_WindowHandle, 
    HTuple *hv_PoseEstimated)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_Center, hv_RowNotUsed, hv_ColumnNotUsed;
  HTuple  hv_Width, hv_Height, hv_WPRow1, hv_WPColumn1, hv_WPRow2;
  HTuple  hv_WPColumn2, hv_CamParam, hv_PoseIn, hv_Moments;
  HTuple  hv_Exception, hv_PoseInvert, hv_ObjectModel3DRigidTrans;

  //This procedure estimates a visualization pose PoseEstimated
  //that can be used to visualize the ObjectModel3Dl
  //in the window specified with WindowHandle
  //with disp_object_model_3d or visualize_object_model_3d.
  //
  get_object_models_center(hv_ObjectModel3D, &hv_Center);
  if (0 != (int(hv_Center==HTuple())))
  {
    hv_Center.Clear();
    hv_Center[0] = 0;
    hv_Center[1] = 0;
    hv_Center[2] = 0;
  }
  //
  GetWindowExtents(hv_WindowHandle, &hv_RowNotUsed, &hv_ColumnNotUsed, &hv_Width, 
      &hv_Height);
  GetPart(hv_WindowHandle, &hv_WPRow1, &hv_WPColumn1, &hv_WPRow2, &hv_WPColumn2);
  SetPart(hv_WindowHandle, 0, 0, hv_Height-1, hv_Width-1);
  gen_cam_par_area_scan_division(0.06, 0, 8.5e-6, 8.5e-6, hv_Width/2, hv_Height/2, 
      hv_Width, hv_Height, &hv_CamParam);
  CreatePose(-HTuple(hv_Center[0]), -HTuple(hv_Center[1]), -HTuple(hv_Center[2]), 
      0, 0, 0, "Rp+T", "gba", "point", &hv_PoseIn);
  //
  try
  {
    MomentsObjectModel3d(hv_ObjectModel3D, "principal_axes", &hv_Moments);
  }
  // catch (Exception) 
  catch (HException &HDevExpDefaultException)
  {
    HDevExpDefaultException.ToHTuple(&hv_Exception);
    hv_Moments.Clear();
    hv_Moments[0] = 0;
    hv_Moments[1] = 0;
    hv_Moments[2] = 0;
    hv_Moments[3] = 0;
    hv_Moments[4] = 0;
    hv_Moments[5] = 0;
    hv_Moments[6] = 0;
  }
  PoseInvert(hv_Moments, &hv_PoseInvert);
  //
  RigidTransObjectModel3d(hv_ObjectModel3D, hv_PoseInvert, &hv_ObjectModel3DRigidTrans);
  determine_optimum_pose_distance(hv_ObjectModel3DRigidTrans, hv_CamParam, 0.9, hv_PoseIn, 
      &(*hv_PoseEstimated));
  (*hv_PoseEstimated) = (((((HTuple((*hv_PoseEstimated)[0]).TupleConcat(-HTuple(hv_Moments[2]))).TupleConcat(HTuple((*hv_PoseEstimated)[2]))).TupleConcat(HTuple((*hv_PoseEstimated)[3])-90)).TupleConcat(HTuple((*hv_PoseEstimated)[4]))).TupleConcat(HTuple((*hv_PoseEstimated)[5]))).TupleConcat(0);
  return;
}

// Chapter: Graphics / Output
void estimate_visualization_pose_simple (HTuple hv_SampledModel, HTuple hv_WindowHandleModel, 
    HTuple *hv_PoseEstimated)
{

  // Local control variables
  HTuple  hv_Center, hv_RowNotUsed, hv_ColumnNotUsed;
  HTuple  hv_Width, hv_Height, hv_WPRow1, hv_WPColumn1, hv_WPRow2;
  HTuple  hv_WPColumn2, hv_CamParam, hv_PoseIn;

  get_object_models_center(hv_SampledModel, &hv_Center);
  GetWindowExtents(hv_WindowHandleModel, &hv_RowNotUsed, &hv_ColumnNotUsed, &hv_Width, 
      &hv_Height);
  GetPart(hv_WindowHandleModel, &hv_WPRow1, &hv_WPColumn1, &hv_WPRow2, &hv_WPColumn2);
  SetPart(hv_WindowHandleModel, 0, 0, hv_Height-1, hv_Width-1);
  gen_cam_par_area_scan_division(0.06, 0, 8.5e-6, 8.5e-6, hv_Width/2, hv_Height/2, 
      hv_Width, hv_Height, &hv_CamParam);
  CreatePose(-HTuple(hv_Center[0]), -HTuple(hv_Center[1]), -HTuple(hv_Center[2]), 
      0, 0, 0, "Rp+T", "gba", "point", &hv_PoseIn);
  //
  determine_optimum_pose_distance(hv_SampledModel, hv_CamParam, 0.9, hv_PoseIn, &(*hv_PoseEstimated));

  return;
}

// Chapter: Legacy / DL Classification
// Short Description: Evaluate the performance of a deep-learning-based classifier. 
void evaluate_dl_classifier (HTuple hv_GroundTruthLabels, HTuple hv_DLClassifierHandle, 
    HTuple hv_DLClassifierResultID, HTuple hv_EvaluationMeasureType, HTuple hv_ClassesToEvaluate, 
    HTuple *hv_EvaluationMeasure)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_Classes, hv_TestClassesToEvaluate;
  HTuple  hv_NumEvalMeasureTypes, hv_NumEvalClasses, hv_ComputePrecision;
  HTuple  hv_ComputeRecall, hv_ComputeFScore, hv_ComputeConfusionMatrix;
  HTuple  hv_PredictedClasses, hv_Index, hv_PredictedClass;
  HTuple  hv_ConfusionMatrix, hv_EvalMeasureTypeIndex, hv_CurrentEvalMeasure;
  HTuple  hv_CurrentEvalClass, hv_RegExpTopKError, hv_ComputeTopKError;
  HTuple  hv_K, hv_Indices, hv_TopKError, hv_NumClasses, hv_IndexClass;
  HTuple  hv_ClassPrecisions, hv_MatrixRowSumID, hv_TruePositive;
  HTuple  hv_SumPredictedClass, hv_ClassPrecision, hv_Precision;
  HTuple  hv_ClassRecalls, hv_MatrixColumnSumID, hv_SumLabel;
  HTuple  hv_ClassRecall, hv_Recall, hv_FScore;

  //This procedure can be used to compute various evaluation measures
  //to check the performance of your trained
  //deep-learning-based classifier DLClassifierHandle.
  //For this, the GroundTruthLabels must be given. Additionally,
  //the results of the classification must be given in DLClassifierResultID,
  //as returned by apply_dl_classifier and apply_dl_classifier_batchwise.
  //With EvaluationMeasureType, you can choose which evaluation measure
  //to return. With ClassesToEvaluate, you can choose whether to return
  //the result for a single class, a result for every class, or
  //for all classes combined. The result is returned in EvaluationMeasure.
  //
  //Check input.
  //Check whether ClassesToEvaluate is a class or 'global'.
  GetDlClassifierParam(hv_DLClassifierHandle, "classes", &hv_Classes);
  //
  //Convert the class indices to class labels if necessary
  if (0 != (int(((hv_GroundTruthLabels.TupleIsIntElem()).TupleFind(0))==-1)))
  {
    if (0 != (HTuple(int((hv_GroundTruthLabels.TupleMin())<0)).TupleOr(int((hv_GroundTruthLabels.TupleMax())>((hv_Classes.TupleLength())-1)))))
    {
      throw HException("The Indices of the GroundTruthLabels exceed the range of classes. \nPlease check your data split.");
    }
    hv_GroundTruthLabels = HTuple(hv_Classes[hv_GroundTruthLabels]);
  }
  if (0 != (int(((hv_GroundTruthLabels.TupleSort()).TupleUniq())!=(hv_Classes.TupleSort()))))
  {
    throw HException("Not all classes are represented in the GroundTruthLabels. \nPlease check your data split.");
  }
  hv_TestClassesToEvaluate.Clear();
  hv_TestClassesToEvaluate[0] = "global";
  hv_TestClassesToEvaluate.Append(hv_Classes);
  if (0 != (int((hv_ClassesToEvaluate.TupleDifference(hv_TestClassesToEvaluate))!=HTuple())))
  {
    throw HException("ClassesToEvaluate invalid.");
  }
  //
  //Count the measure types and modes of ClassesToEvaluate.
  hv_NumEvalMeasureTypes = hv_EvaluationMeasureType.TupleLength();
  hv_NumEvalClasses = hv_ClassesToEvaluate.TupleLength();
  //
  //If the numbers are not equal, extend the shorter one.
  if (0 != (int(hv_NumEvalMeasureTypes>hv_NumEvalClasses)))
  {
    if (0 != (HTuple(int(hv_NumEvalMeasureTypes>1)).TupleAnd(int(hv_NumEvalClasses>1))))
    {
      throw HException("Invalid number of elements in EvaluationMeasureType/ClassesToEvaluate.");
    }
    else
    {
      hv_ClassesToEvaluate = HTuple(hv_NumEvalMeasureTypes,hv_ClassesToEvaluate);
    }
  }
  if (0 != (int(hv_NumEvalMeasureTypes<hv_NumEvalClasses)))
  {
    if (0 != (HTuple(int(hv_NumEvalMeasureTypes>1)).TupleAnd(int(hv_NumEvalClasses>1))))
    {
      throw HException("Invalid number of elements in EvaluationMeasureType/ClassesToEvaluate.");
    }
    else
    {
      hv_EvaluationMeasureType = HTuple(hv_NumEvalClasses,hv_EvaluationMeasureType);
    }
  }
  //
  //Check whether we need to compute a confusion matrix.
  //We want to do this only once to save run time.
  hv_ComputePrecision = hv_EvaluationMeasureType.TupleRegexpTest("precision");
  hv_ComputeRecall = hv_EvaluationMeasureType.TupleRegexpTest("recall");
  hv_ComputeFScore = hv_EvaluationMeasureType.TupleRegexpTest("f_score");
  hv_ComputeConfusionMatrix = (hv_ComputePrecision+hv_ComputeRecall)+hv_ComputeFScore;
  if (0 != (int(hv_ComputeConfusionMatrix>0)))
  {
    //Get the top-1 predicted classes from the result handle(s).
    hv_PredictedClasses = HTuple();
    {
    HTuple end_val59 = (hv_DLClassifierResultID.TupleLength())-1;
    HTuple step_val59 = 1;
    for (hv_Index=0; hv_Index.Continue(end_val59, step_val59); hv_Index += step_val59)
    {
      GetDlClassifierResult(HTuple(hv_DLClassifierResultID[hv_Index]), "all", "predicted_classes", 
          &hv_PredictedClass);
      hv_PredictedClasses = hv_PredictedClasses.TupleConcat(hv_PredictedClass);
    }
    }
    //Compute the confusion matrix.
    gen_confusion_matrix(hv_GroundTruthLabels, hv_PredictedClasses, "display_matrix", 
        "none", HTuple(), &hv_ConfusionMatrix);
  }
  //
  //Loop through all given measure types.
  (*hv_EvaluationMeasure) = HTuple();
  {
  HTuple end_val69 = ((hv_NumEvalMeasureTypes.TupleConcat(hv_NumEvalClasses)).TupleMax())-1;
  HTuple step_val69 = 1;
  for (hv_EvalMeasureTypeIndex=0; hv_EvalMeasureTypeIndex.Continue(end_val69, step_val69); hv_EvalMeasureTypeIndex += step_val69)
  {
    //Select the current combination.
    hv_CurrentEvalMeasure = HTuple(hv_EvaluationMeasureType[hv_EvalMeasureTypeIndex]);
    hv_CurrentEvalClass = HTuple(hv_ClassesToEvaluate[hv_EvalMeasureTypeIndex]);
    //Set the output accordingly.
    //Check whether to compute the top-k error.
    hv_RegExpTopKError = "top([0-9]+)_error";
    hv_ComputeTopKError = hv_CurrentEvalMeasure.TupleRegexpTest(hv_RegExpTopKError);
    //Check whether to compute the precision, recall, F-score.
    hv_ComputePrecision = hv_CurrentEvalMeasure.TupleRegexpTest("precision");
    hv_ComputeRecall = hv_CurrentEvalMeasure.TupleRegexpTest("recall");
    hv_ComputeFScore = hv_CurrentEvalMeasure.TupleRegexpTest("f_score");
    //
    if (0 != hv_ComputeTopKError)
    {
      //Get the K from the input string 'topK_error'.
      hv_K = (hv_CurrentEvalMeasure.TupleRegexpMatch(hv_RegExpTopKError)).TupleNumber();
      //Select all labels or only the labels with the respective class.
      if (0 != (int(hv_CurrentEvalClass==HTuple("global"))))
      {
        hv_Indices = HTuple::TupleGenSequence(0,(hv_GroundTruthLabels.TupleLength())-1,1);
      }
      else
      {
        hv_Indices = hv_GroundTruthLabels.TupleFind(hv_CurrentEvalClass);
      }
      compute_top_k_error(hv_DLClassifierHandle, hv_DLClassifierResultID, hv_GroundTruthLabels, 
          hv_Indices, hv_K, &hv_TopKError);
      (*hv_EvaluationMeasure)[hv_EvalMeasureTypeIndex] = hv_TopKError;
    }
    else if (0 != (HTuple(hv_ComputePrecision.TupleOr(hv_ComputeRecall)).TupleOr(hv_ComputeFScore)))
    {
      if (0 != (int(hv_CurrentEvalClass==HTuple("global"))))
      {
        //Compute the mean of the measures for all classes.
        hv_NumClasses = hv_Classes.TupleLength();
        hv_IndexClass = HTuple::TupleGenSequence(0,hv_NumClasses-1,1);
      }
      else
      {
        //Compute the measures for a certain class.
        hv_NumClasses = 1;
        hv_IndexClass = hv_Classes.TupleFind(hv_CurrentEvalClass);
      }
      if (0 != (hv_ComputePrecision.TupleOr(hv_ComputeFScore)))
      {
        hv_ClassPrecisions = HTuple();
        SumMatrix(hv_ConfusionMatrix, "rows", &hv_MatrixRowSumID);
        {
        HTuple end_val106 = hv_NumClasses-1;
        HTuple step_val106 = 1;
        for (hv_Index=0; hv_Index.Continue(end_val106, step_val106); hv_Index += step_val106)
        {
          //Compute the precision for every selected class.
          GetValueMatrix(hv_ConfusionMatrix, HTuple(hv_IndexClass[hv_Index]), HTuple(hv_IndexClass[hv_Index]), 
              &hv_TruePositive);
          GetValueMatrix(hv_MatrixRowSumID, HTuple(hv_IndexClass[hv_Index]), 0, &hv_SumPredictedClass);
          if (0 != (int(hv_SumPredictedClass==0)))
          {
            hv_ClassPrecision = 0;
          }
          else
          {
            hv_ClassPrecision = hv_TruePositive/hv_SumPredictedClass;
          }
          hv_ClassPrecisions = hv_ClassPrecisions.TupleConcat(hv_ClassPrecision);
        }
        }
        hv_Precision = hv_ClassPrecisions.TupleMean();
        ClearMatrix(hv_MatrixRowSumID);
        if (0 != hv_ComputePrecision)
        {
          (*hv_EvaluationMeasure)[hv_EvalMeasureTypeIndex] = hv_Precision;
        }
      }
      if (0 != (hv_ComputeRecall.TupleOr(hv_ComputeFScore)))
      {
        hv_ClassRecalls = HTuple();
        SumMatrix(hv_ConfusionMatrix, "columns", &hv_MatrixColumnSumID);
        {
        HTuple end_val126 = hv_NumClasses-1;
        HTuple step_val126 = 1;
        for (hv_Index=0; hv_Index.Continue(end_val126, step_val126); hv_Index += step_val126)
        {
          //Compute the recall for every class.
          GetValueMatrix(hv_ConfusionMatrix, HTuple(hv_IndexClass[hv_Index]), HTuple(hv_IndexClass[hv_Index]), 
              &hv_TruePositive);
          GetValueMatrix(hv_MatrixColumnSumID, 0, HTuple(hv_IndexClass[hv_Index]), 
              &hv_SumLabel);
          hv_ClassRecall = hv_TruePositive/hv_SumLabel;
          hv_ClassRecalls = hv_ClassRecalls.TupleConcat(hv_ClassRecall);
        }
        }
        hv_Recall = hv_ClassRecalls.TupleMean();
        ClearMatrix(hv_MatrixColumnSumID);
        if (0 != hv_ComputeRecall)
        {
          (*hv_EvaluationMeasure)[hv_EvalMeasureTypeIndex] = hv_Recall;
        }
      }
      if (0 != hv_ComputeFScore)
      {
        //Compute the F-score for a certain class or globally
        //for the averaged precision and recall.
        //Precision and recall were already computed above.
        if (0 != (int((hv_Precision+hv_Recall)==0)))
        {
          hv_FScore = 0.0;
        }
        else
        {
          hv_FScore = ((2*hv_Precision)*hv_Recall)/(hv_Precision+hv_Recall);
        }
        (*hv_EvaluationMeasure)[hv_EvalMeasureTypeIndex] = hv_FScore;
      }
    }
    else
    {
      throw HException(("Invalid option for EvaluationMeasureType: '"+hv_CurrentEvalMeasure)+"'");
    }
  }
  }
  if (0 != hv_ComputeConfusionMatrix)
  {
    ClearMatrix(hv_ConfusionMatrix);
  }
  return;

}

// Chapter: Deep Learning / Model
// Short Description: Evaluate the model given by DLModelHandle on the selected samples of DLDataset. 
void evaluate_dl_model (HTuple hv_DLDataset, HTuple hv_DLModelHandle, HTuple hv_SampleSelectMethod, 
    HTuple hv_SampleSelectValues, HTuple hv_GenParam, HTuple *hv_EvaluationResult, 
    HTuple *hv_EvalParams)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_ModelType, hv_ClassIDs, hv_ClassNames;
  HTuple  hv_Alphabet, hv_BatchSize, hv_OODAvailable, hv_InstanceTypeModel;
  HTuple  hv_Exception, hv_IsInstanceSegmentation, hv_InstanceType;
  HTuple  hv_ModelIgnoreClassIDs, hv_ShowProgress, hv_GenParamKeys;
  HTuple  hv_OptionalKeyNames, hv_GenParamIndex, hv_IoUThreshold;
  HTuple  hv_MaxNumDetections, hv_AreaRanges, hv_DetailedEvaluation;
  HTuple  hv_AllocationBlockLength, hv_InterpolatePRCurves;
  HTuple  hv_IgnoreClassIDs, hv_AllIgnoreClassIDs, hv_EvaluateClassIDs;
  HTuple  hv_ClassesToEvaluate, hv_KeyExists, hv_ClassIDsToEvaluate;
  HTuple  hv_AnomalyClassificationThresholds, hv_EvaluateMask;
  HTuple  hv_Value, hv_Measures, hv_IgnoreDirection, hv_MinConfidence;
  HTuple  hv_OODMeasureRequested, hv_OODEvaluationPossible;
  HTuple  hv_FoundIndex, hv_AllMeasuresRequested, hv_OODThreshold;
  HTuple  hv_ClassInfoExists, hv_DatasetClassIDs, hv_ClassIDsToClassNames;
  HTuple  hv_EvaluateClassNames, hv_DLSamples, hv_SampleIndices;
  HTuple  hv_NumSamples, hv_NumBatches, hv_OODSamplesAvailable;
  HTuple  hv_NumOODSamples, hv_NumOODBatches, hv_TotalNumBatches;
  HTuple  hv_RunningMeasures, hv_Outputs, hv_EvalGCAnomalyNetworks;
  HTuple  hv_ModelGCAnomalyNetworks, hv_DefaultRequested;
  HTuple  hv_EvalAnomalyNetworkIndex, hv_EvalGCAnomalyNetwork;
  HTuple  hv_FindIndex, hv_Progress, hv_TaskInfo, hv_SecondsStart;
  HTuple  hv_BatchIndex, hv_BatchStart, hv_BatchEnd, hv_SamplesIndicesBatch;
  HTuple  hv_DLSamplesBatch, hv_DLResultsBatch, hv_SecondsElapsed;
  HTuple  hv_SecondsRemaining, hv_ProgressPercent, hv_ProgressPerSecond;
  HTuple  hv_TimeElapsedString, hv_TimeRemainingString, hv_SampleIndex;
  HTuple  hv_DLSample, hv_DictPath, hv_DLSampleProc, hv_PreprocessedSampleIsOod;

  //This procedure applies the model given by DLModelHandle on the selected samples
  //of DLDataset and evaluates the results against the ground truth annotations
  //to calculate evaluation measures.
  //
  //Input:
  // - DLDataset.
  // - DLModelHandle.
  // - SampleSelectMethod: Method by which the samples are selected.
  // - SampleSelectValues: Identifier used to retrieve the samples from the DLDataset
  //                       for the corresponding selection method.
  // - GenParam: Parameters of the evaluation that should be changed from the default.
  //
  //Output:
  // - EvaluationResult: Dictionary containing the output measures.
  // - EvalParams: Dictionary with the used evaluation parameters.
  //
  //** Initialization: ***
  //
  GetDlModelParam(hv_DLModelHandle, "type", &hv_ModelType);
  if (0 != (HTuple(HTuple(HTuple(HTuple(HTuple(HTuple(HTuple(HTuple(int(hv_ModelType!=HTuple("3d_gripping_point_detection"))).TupleAnd(int(hv_ModelType!=HTuple("anomaly_detection")))).TupleAnd(int(hv_ModelType!=HTuple("classification")))).TupleAnd(int(hv_ModelType!=HTuple("multi_label_classification")))).TupleAnd(int(hv_ModelType!=HTuple("detection")))).TupleAnd(int(hv_ModelType!=HTuple("gc_anomaly_detection")))).TupleAnd(int(hv_ModelType!=HTuple("ocr_detection")))).TupleAnd(int(hv_ModelType!=HTuple("ocr_recognition")))).TupleAnd(int(hv_ModelType!=HTuple("segmentation")))))
  {
    throw HException(("Current model type is not supported: \""+hv_ModelType)+"\"");
  }
  //
  //Check if model has been normalized, if required by model type.
  if (0 != (int(hv_ModelType==HTuple("gc_anomaly_detection"))))
  {
    check_dl_gc_anomaly_scores_normalization(hv_DLModelHandle, HTuple());
  }
  //
  //Get the class IDs as set in the model.
  if (0 != (int(hv_ModelType==HTuple("3d_gripping_point_detection"))))
  {
    //Only the gripping_map class is evaluated.
    GetDlModelParam(hv_DLModelHandle, "class_ids", &hv_ClassIDs);
    GetDlModelParam(hv_DLModelHandle, "class_names", &hv_ClassNames);
    hv_ClassIDs = HTuple(hv_ClassIDs[hv_ClassNames.TupleFind("gripping_map")]);
  }
  else if (0 != (HTuple(int(hv_ModelType==HTuple("anomaly_detection"))).TupleOr(int(hv_ModelType==HTuple("gc_anomaly_detection")))))
  {
    //Default for anomaly detection and Global Context Anomaly Detection is 0,1.
    hv_ClassIDs.Clear();
    hv_ClassIDs[0] = 0;
    hv_ClassIDs[1] = 1;
  }
  else if (0 != (int(hv_ModelType==HTuple("ocr_recognition"))))
  {
    //No Class IDs in case of ocr_recognition models
    GetDlModelParam(hv_DLModelHandle, "alphabet", &hv_Alphabet);
    TupleGenSequence(0, hv_Alphabet.TupleLength(), 1, &hv_ClassIDs);
  }
  else if (0 != (int(hv_ModelType==HTuple("ocr_detection"))))
  {
    //Default for ocr_detection. Only evaluate word.
    //0: word, 1: char, 2: ignore
    hv_ClassIDs = 0;
  }
  else
  {
    GetDlModelParam(hv_DLModelHandle, "class_ids", &hv_ClassIDs);
  }
  //
  //Get the batch size as set in the model.
  GetDlModelParam(hv_DLModelHandle, "batch_size", &hv_BatchSize);
  //
  //Generate default parameters.
  create_evaluation_default_param(hv_ModelType, hv_ClassIDs, &(*hv_EvalParams));
  //Add out-of-distribution default evaluation param
  if (0 != (int(hv_ModelType==HTuple("classification"))))
  {
    GetDlModelParam(hv_DLModelHandle, "ood_available", &hv_OODAvailable);
    if (0 != (int(hv_OODAvailable==HTuple("true"))))
    {
      SetDictTuple((*hv_EvalParams), "measures", ((*hv_EvalParams).TupleGetDictTuple("measures")).TupleConcat((((((HTuple("ood_confusion_matrix").Append("ood_precision")).Append("ood_recall")).Append("ood_f_score")).Append("ood_false_positive_rate")).Append("ood_score_histogram"))));
    }
  }
  //
  //Get model specific information.
  if (0 != (int(hv_ModelType==HTuple("detection"))))
  {
    try
    {
      GetDlModelParam(hv_DLModelHandle, "instance_type", &hv_InstanceTypeModel);
    }
    // catch (Exception) 
    catch (HException &HDevExpDefaultException)
    {
      HDevExpDefaultException.ToHTuple(&hv_Exception);
      hv_InstanceTypeModel = "rectangle1";
    }
    GetDlModelParam(hv_DLModelHandle, "instance_segmentation", &hv_IsInstanceSegmentation);
    if (0 != (int(hv_IsInstanceSegmentation==HTuple("true"))))
    {
      hv_InstanceType = "mask";
    }
    else
    {
      hv_InstanceType = hv_InstanceTypeModel;
    }
    //Note, these are the defaults. If the user specifies
    //'evaluate_mask' as false, the evaluation will use
    //the instance type of the model (InstanceTypeModel).
  }
  else if (0 != (int(hv_ModelType==HTuple("segmentation"))))
  {
    GetDlModelParam(hv_DLModelHandle, "ignore_class_ids", &hv_ModelIgnoreClassIDs);
  }
  //
  //By default we do not show the progress of evaluation.
  hv_ShowProgress = 0;
  //
  //Set user specified parameters.
  if (0 != (int(hv_GenParam!=HTuple())))
  {
    GetDictParam(hv_GenParam, "keys", HTuple(), &hv_GenParamKeys);
    hv_OptionalKeyNames.Clear();
    hv_OptionalKeyNames[0] = "measures";
    hv_OptionalKeyNames[1] = "evaluation_type";
    hv_OptionalKeyNames[2] = "class_ids";
    hv_OptionalKeyNames[3] = "num_classes";
    hv_OptionalKeyNames[4] = "evaluate_instances";
    hv_OptionalKeyNames[5] = "gc_anomaly_networks";
    hv_OptionalKeyNames[6] = "gripping_point_params";
    {
    HTuple end_val89 = (hv_GenParamKeys.TupleLength())-1;
    HTuple step_val89 = 1;
    for (hv_GenParamIndex=0; hv_GenParamIndex.Continue(end_val89, step_val89); hv_GenParamIndex += step_val89)
    {
      if (0 != (int(HTuple(hv_GenParamKeys[hv_GenParamIndex])==HTuple("show_progress"))))
      {
        //Show the progress of the evaluation.
        GetDictTuple(hv_GenParam, "show_progress", &hv_ShowProgress);
        hv_ShowProgress = HTuple(int(hv_ShowProgress==HTuple("true"))).TupleOr(int(hv_ShowProgress==1));
      }
      else if (0 != (HTuple(int(HTuple(hv_GenParamKeys[hv_GenParamIndex])==HTuple("iou_threshold"))).TupleAnd(HTuple(int(hv_ModelType==HTuple("detection"))).TupleOr(int(hv_ModelType==HTuple("ocr_detection"))))))
      {
        //Set IoU threshold.
        GetDictTuple(hv_GenParam, "iou_threshold", &hv_IoUThreshold);
        SetDictTuple((*hv_EvalParams), "iou_threshold", hv_IoUThreshold);
      }
      else if (0 != (HTuple(int(HTuple(hv_GenParamKeys[hv_GenParamIndex])==HTuple("max_num_detections"))).TupleAnd(HTuple(int(hv_ModelType==HTuple("detection"))).TupleOr(int(hv_ModelType==HTuple("ocr_detection"))))))
      {
        //Set maximal number detections.
        GetDictTuple(hv_GenParam, "max_num_detections", &hv_MaxNumDetections);
        SetDictTuple((*hv_EvalParams), "max_num_detections", hv_MaxNumDetections);
      }
      else if (0 != (HTuple(int(HTuple(hv_GenParamKeys[hv_GenParamIndex])==HTuple("area_ranges"))).TupleAnd(HTuple(int(hv_ModelType==HTuple("detection"))).TupleOr(int(hv_ModelType==HTuple("ocr_detection"))))))
      {
        //Set area ranges.
        GetDictTuple(hv_GenParam, "area_ranges", &hv_AreaRanges);
        SetDictTuple((*hv_EvalParams), "area_ranges", hv_AreaRanges);
      }
      else if (0 != (HTuple(int(HTuple(hv_GenParamKeys[hv_GenParamIndex])==HTuple("detailed_evaluation"))).TupleAnd(HTuple(int(hv_ModelType==HTuple("detection"))).TupleOr(int(hv_ModelType==HTuple("ocr_detection"))))))
      {
        //Set detailed evaluation.
        GetDictTuple(hv_GenParam, "detailed_evaluation", &hv_DetailedEvaluation);
        SetDictTuple((*hv_EvalParams), "detailed_evaluation", hv_DetailedEvaluation);
      }
      else if (0 != (HTuple(int(HTuple(hv_GenParamKeys[hv_GenParamIndex])==HTuple("allocation_block_length"))).TupleAnd(HTuple(int(hv_ModelType==HTuple("detection"))).TupleOr(int(hv_ModelType==HTuple("ocr_detection"))))))
      {
        //Set length of blocks that are allocated during evaluation.
        GetDictTuple(hv_GenParam, "allocation_block_length", &hv_AllocationBlockLength);
        SetDictTuple((*hv_EvalParams), "allocation_block_length", hv_AllocationBlockLength);
      }
      else if (0 != (HTuple(int(HTuple(hv_GenParamKeys[hv_GenParamIndex])==HTuple("interpolate_pr_curves"))).TupleAnd(HTuple(HTuple(int(hv_ModelType==HTuple("detection"))).TupleOr(int(hv_ModelType==HTuple("ocr_detection")))).TupleOr(int(hv_ModelType==HTuple("multi_label_classification"))))))
      {
        //Set interpolation of precision-recall curves.
        GetDictTuple(hv_GenParam, "interpolate_pr_curves", &hv_InterpolatePRCurves);
        SetDictTuple((*hv_EvalParams), "interpolate_pr_curves", hv_InterpolatePRCurves);
      }
      else if (0 != (HTuple(int(HTuple(hv_GenParamKeys[hv_GenParamIndex])==HTuple("ignore_class_ids"))).TupleAnd(int(hv_ModelType==HTuple("segmentation")))))
      {
        //Set ignore class IDs.
        GetDictTuple(hv_GenParam, "ignore_class_ids", &hv_IgnoreClassIDs);
        //Merge the specified ignore class IDs with the model ignore class IDs.
        hv_AllIgnoreClassIDs = ((hv_ModelIgnoreClassIDs.TupleConcat(hv_IgnoreClassIDs)).TupleSort()).TupleUniq();
        SetDictTuple((*hv_EvalParams), "ignore_class_ids", hv_AllIgnoreClassIDs);
        //Remove the ignore class IDs from the model class IDs.
        TupleDifference(hv_ClassIDs, hv_IgnoreClassIDs, &hv_EvaluateClassIDs);
        SetDictTuple((*hv_EvalParams), "class_ids", hv_EvaluateClassIDs);
        SetDictTuple((*hv_EvalParams), "num_classes", hv_EvaluateClassIDs.TupleLength());
      }
      else if (0 != (HTuple(int(HTuple(hv_GenParamKeys[hv_GenParamIndex])==HTuple("class_names_to_evaluate"))).TupleAnd(int(hv_ModelType==HTuple("classification")))))
      {
        //Class names to be used in evaluation.
        //To transform the names to IDs later, one has to remember the class names.
        GetDictTuple(hv_GenParam, "class_names_to_evaluate", &hv_ClassesToEvaluate);
        GetDlModelParam(hv_DLModelHandle, "class_names", &hv_ClassNames);
        SetDictTuple((*hv_EvalParams), "class_names_to_evaluate", hv_ClassesToEvaluate);
        SetDictTuple((*hv_EvalParams), "class_names", hv_ClassNames);
        GetDictParam((*hv_EvalParams), "key_exists", "class_ids_to_evaluate", &hv_KeyExists);
        if (0 != hv_KeyExists)
        {
          //To avoid inconsistent class names/IDs, remove the older ones.
          RemoveDictKey((*hv_EvalParams), "class_ids_to_evaluate");
        }
      }
      else if (0 != (HTuple(int(HTuple(hv_GenParamKeys[hv_GenParamIndex])==HTuple("class_ids_to_evaluate"))).TupleAnd(int(hv_ModelType==HTuple("classification")))))
      {
        //Class IDs to be used in evaluation.
        GetDictTuple(hv_GenParam, "class_ids_to_evaluate", &hv_ClassIDsToEvaluate);
        SetDictTuple((*hv_EvalParams), "class_ids_to_evaluate", hv_ClassIDsToEvaluate);
        GetDictParam((*hv_EvalParams), "key_exists", "class_names_to_evaluate", &hv_KeyExists);
        if (0 != hv_KeyExists)
        {
          //To avoid inconsistent class names/IDs, remove the older ones.
          RemoveDictKey((*hv_EvalParams), "class_names_to_evaluate");
        }
      }
      else if (0 != (int(HTuple(hv_GenParamKeys[hv_GenParamIndex])==HTuple("anomaly_classification_thresholds"))))
      {
        //Set anomaly classification threshold for confusion matrices.
        GetDictTuple(hv_GenParam, "anomaly_classification_thresholds", &hv_AnomalyClassificationThresholds);
        SetDictTuple((*hv_EvalParams), "anomaly_classification_thresholds", hv_AnomalyClassificationThresholds);
      }
      else if (0 != (int(HTuple(hv_GenParamKeys[hv_GenParamIndex])==HTuple("evaluate_mask"))))
      {
        GetDictTuple(hv_GenParam, "evaluate_mask", &hv_EvaluateMask);
        if (0 != (hv_EvaluateMask.TupleNot()))
        {
          hv_InstanceType = hv_InstanceTypeModel;
        }
      }
      else if (0 != (int((hv_OptionalKeyNames.TupleFind(HTuple(hv_GenParamKeys[hv_GenParamIndex])))!=-1)))
      {
        GetDictTuple(hv_GenParam, HTuple(hv_GenParamKeys[hv_GenParamIndex]), &hv_Value);
        SetDictTuple((*hv_EvalParams), HTuple(hv_GenParamKeys[hv_GenParamIndex]), 
            hv_Value);
      }
      else
      {
        throw HException(("Unknown parameter : '"+HTuple(hv_GenParamKeys[hv_GenParamIndex]))+"'");
      }
    }
    }
  }
  //
  //Finally specify the evaluation based on all given parameters and defaults.
  SetDictTuple((*hv_EvalParams), "calculate_ood_measures", 0);
  if (0 != (int(hv_ModelType==HTuple("detection"))))
  {
    if (0 != (int(hv_InstanceType==HTuple("mask"))))
    {
      SetDictTuple((*hv_EvalParams), "evaluate_mask", 1);
      GetDictTuple((*hv_EvalParams), "measures", &hv_Measures);
      SetDictTuple((*hv_EvalParams), "measures", hv_Measures.TupleDifference("soap"));
    }
    else
    {
      SetDictTuple((*hv_EvalParams), "evaluate_mask", 0);
    }
    //Overwrite instance_type
    SetDictTuple((*hv_EvalParams), "instance_type", hv_InstanceType);
    //For rectangle2 detection with ignore_direction set to false, we also evaluate the
    //precision of the predicted angle using the Score of Angle Precision (SoAP).
    if (0 != (int(hv_InstanceType==HTuple("rectangle2"))))
    {
      GetDlModelParam(hv_DLModelHandle, "ignore_direction", &hv_IgnoreDirection);
      if (0 != (int(hv_IgnoreDirection==HTuple("false"))))
      {
        GetDictTuple((*hv_EvalParams), "measures", &hv_Measures);
        SetDictTuple((*hv_EvalParams), "measures", hv_Measures.TupleConcat("soap"));
      }
    }
  }
  else if (0 != (int(hv_ModelType==HTuple("multi_label_classification"))))
  {
    GetDlModelParam(hv_DLModelHandle, "min_confidence", &hv_MinConfidence);
    SetDictTuple((*hv_EvalParams), "min_confidence", hv_MinConfidence);
  }
  else if (0 != (int(hv_ModelType==HTuple("classification"))))
  {
    //Check if an OOD measure is requested.
    hv_OODMeasureRequested = ((*hv_EvalParams).TupleGetDictTuple("measures")).TupleRegexpTest("^ood_");
    hv_OODEvaluationPossible = int(hv_OODAvailable==HTuple("true"));
    if (0 != (hv_OODMeasureRequested.TupleAnd(hv_OODEvaluationPossible.TupleNot())))
    {
      throw HException("Out-of-distribution detection measures can only be computed after 'fit_dl_out_of_distribution' has been called.");
    }
    //If all measures are requested and the prerequisites for
    //OOD detection evaluations are met, all OOD measures are
    //computed.
    hv_FoundIndex = ((*hv_EvalParams).TupleGetDictTuple("measures")).TupleFind("all");
    hv_AllMeasuresRequested = HTuple(int(hv_FoundIndex!=-1)).TupleAnd(int(hv_FoundIndex!=HTuple()));
    if (0 != (hv_OODEvaluationPossible.TupleAnd(hv_AllMeasuresRequested.TupleOr(hv_OODMeasureRequested))))
    {
      SetDictTuple((*hv_EvalParams), "calculate_ood_measures", 1);
      //Write OOD threshold to EvalParams so it can be used for the visualization
      //in dev_display_classification_results.
      GetDlModelParam(hv_DLModelHandle, "ood_threshold", &hv_OODThreshold);
      SetDictTuple((*hv_EvalParams), "ood_threshold", hv_OODThreshold);
    }
  }
  //
  //Set class names.
  if (0 != (int(hv_ModelType==HTuple("3d_gripping_point_detection"))))
  {
    SetDictTuple((*hv_EvalParams), "class_names", "gripping_map");
  }
  else
  {
    //Get the class names from the dataset if present.
    GetDictParam(hv_DLDataset, "key_exists", (HTuple("class_names").Append("class_ids")), 
        &hv_ClassInfoExists);
    if (0 != (int((hv_ClassInfoExists.TupleSum())==(hv_ClassInfoExists.TupleLength()))))
    {
      GetDictTuple(hv_DLDataset, "class_names", &hv_ClassNames);
      GetDictTuple(hv_DLDataset, "class_ids", &hv_DatasetClassIDs);
      //Set the class names only for the class IDs that are evaluated.
      GetDictTuple((*hv_EvalParams), "class_ids", &hv_EvaluateClassIDs);
      hv_ClassIDsToClassNames = HTuple((hv_DatasetClassIDs.TupleMax())+1,"");
      hv_ClassIDsToClassNames[hv_DatasetClassIDs] = hv_ClassNames;
      if (0 != (int((hv_EvaluateClassIDs.TupleLength())==(hv_ClassNames.TupleLength()))))
      {
        hv_EvaluateClassNames = HTuple(hv_ClassIDsToClassNames[hv_EvaluateClassIDs]);
        //Set the class names to EvalParams.
        SetDictTuple((*hv_EvalParams), "class_names", hv_EvaluateClassNames);
      }
    }
  }
  //
  //Get indices of samples to read from the dataset.
  GetDictTuple(hv_DLDataset, "samples", &hv_DLSamples);
  //
  //Check if there are samples present in the dataset.
  if (0 != (int((hv_DLSamples.TupleLength())==0)))
  {
    throw HException("The provided set of samples in the dataset must be non-empty.");
  }
  //
  //Check for empty SampleSelectValues.
  if (0 != (int((hv_SampleSelectValues.TupleLength())==0)))
  {
    if (0 != (int(hv_SampleSelectMethod==HTuple("image_ids"))))
    {
      throw HException("The provided set of samples of the 'image_ids' selection must be non-empty.");
    }
    else if (0 != (int(hv_SampleSelectMethod==HTuple("sample_indices"))))
    {
      throw HException("The provided set of samples of the 'sample_indices' selection must be non-empty.");
    }
    else
    {
      throw HException("Provide a name for 'split' selection.");
    }
  }
  //
  //
  //Get the sample indices according to the sample selection method.
  hv_SampleIndices = HTuple();
  if (0 != (int(hv_SampleSelectMethod==HTuple("split"))))
  {
    //Get the samples of the split specified.
    find_dl_samples(hv_DLSamples, "split", hv_SampleSelectValues, "or", &hv_SampleIndices);
  }
  else if (0 != (int(hv_SampleSelectMethod==HTuple("image_ids"))))
  {
    //Get the samples specified by 'image_ids'.
    if (0 != (int((hv_SampleSelectValues.TupleLength())>(hv_DLSamples.TupleLength()))))
    {
      throw HException("The number of the image ids provided through 'image_id' is invalid.");
    }
    find_dl_samples(hv_DLSamples, "image_id", hv_SampleSelectValues, "or", &hv_SampleIndices);
  }
  else if (0 != (int(hv_SampleSelectMethod==HTuple("sample_indices"))))
  {
    //Get the samples specified by 'sample_indices'.
    if (0 != (HTuple(int((hv_SampleSelectValues.TupleMin())<0)).TupleOr(int((hv_SampleSelectValues.TupleMax())>((hv_DLSamples.TupleLength())-1)))))
    {
      throw HException("The range of the indices provided through 'sample_indices' is invalid.");
    }
    hv_SampleIndices = hv_SampleSelectValues;
  }
  else
  {
    throw HException(("Unknown sample selection method : '"+hv_SampleSelectMethod)+"'");
  }
  //
  //Get the number of batches.
  hv_NumSamples = hv_SampleIndices.TupleLength();
  hv_NumBatches = ((hv_NumSamples/(hv_BatchSize.TupleReal())).TupleCeil()).TupleInt();
  //
  //Get the number of OOD samples.
  if (0 != ((*hv_EvalParams).TupleGetDictTuple("calculate_ood_measures")))
  {
    GetDictParam(hv_DLDataset, "key_exists", "ood_samples", &hv_OODSamplesAvailable);
    if (0 != hv_OODSamplesAvailable)
    {
      hv_NumOODSamples = (hv_DLDataset.TupleGetDictTuple("ood_samples")).TupleLength();
    }
    else
    {
      hv_NumOODSamples = 0;
    }
    hv_NumOODBatches = ((hv_NumOODSamples/(hv_BatchSize.TupleReal())).TupleCeil()).TupleInt();
    hv_TotalNumBatches = hv_NumBatches+hv_NumOODBatches;
  }
  else
  {
    hv_TotalNumBatches = hv_NumBatches;
  }
  //
  //Check for empty samples selected by the selection method.
  if (0 != (int(hv_NumSamples==0)))
  {
    throw HException(("No samples present in the dataset that are part of the '"+hv_SampleSelectMethod)+"' selection.");
  }
  //
  //
  //** Running measures are initialized according to evaluation method.
  //
  init_running_evaluation_measures((*hv_EvalParams), &hv_RunningMeasures);
  //
  //
  //** Apply model to each image and gather evaluation information: ***
  //
  //Use alternative outputs if requested.
  hv_Outputs = HTuple();
  //
  if (0 != (HTuple(int(hv_ModelType==HTuple("gc_anomaly_detection"))).TupleAnd(int(hv_GenParam!=HTuple()))))
  {
    //
    GetDictParam(hv_GenParam, "key_exists", "gc_anomaly_networks", &hv_KeyExists);
    if (0 != hv_KeyExists)
    {
      GetDictTuple(hv_GenParam, "gc_anomaly_networks", &hv_EvalGCAnomalyNetworks);
      hv_EvalGCAnomalyNetworks = hv_EvalGCAnomalyNetworks.TupleSort();
      GetDlModelParam(hv_DLModelHandle, "gc_anomaly_networks", &hv_ModelGCAnomalyNetworks);
      hv_ModelGCAnomalyNetworks = hv_ModelGCAnomalyNetworks.TupleSort();
      //
      hv_DefaultRequested = HTuple(int((hv_EvalGCAnomalyNetworks.TupleLength())==0)).TupleOr(int(hv_EvalGCAnomalyNetworks==hv_ModelGCAnomalyNetworks));
      {
      HTuple end_val318 = (hv_EvalGCAnomalyNetworks.TupleLength())-1;
      HTuple step_val318 = 1;
      for (hv_EvalAnomalyNetworkIndex=0; hv_EvalAnomalyNetworkIndex.Continue(end_val318, step_val318); hv_EvalAnomalyNetworkIndex += step_val318)
      {
        hv_EvalGCAnomalyNetwork = HTuple(hv_EvalGCAnomalyNetworks[hv_EvalAnomalyNetworkIndex]);
        hv_FindIndex = hv_ModelGCAnomalyNetworks.TupleFind(hv_EvalGCAnomalyNetwork);
        if (0 != (HTuple(int(hv_FindIndex==HTuple())).TupleOr(int(hv_FindIndex==-1))))
        {
          throw HException(("Invalid 'gc_anomaly_networks' requested. Model does not contain a "+hv_EvalGCAnomalyNetwork)+" network.");
        }
        if (0 != (hv_DefaultRequested.TupleNot()))
        {
          hv_Outputs = hv_Outputs.TupleConcat("anomaly_image_"+hv_EvalGCAnomalyNetwork);
        }
      }
      }
    }
  }
  //
  //Initialize progress variables.
  if (0 != hv_ShowProgress)
  {
    hv_Progress.Clear();
    hv_Progress[0] = "Procedure: evaluate_dl_model";
    hv_Progress[1] = "";
    hv_Progress[2] = "";
    hv_Progress[3] = "";
    if (0 != (int(hv_ModelType==HTuple("detection"))))
    {
      hv_TaskInfo = "Task: 1/2: Applying the model and collecting running evaluation measures";
      hv_Progress = hv_Progress.TupleConcat(hv_TaskInfo);
    }
    CountSeconds(&hv_SecondsStart);
    // dev_inspect_ctrl(...); only in hdevelop
  }
  //
  //Loop batchwise over the samples to be evaluated.
  {
  HTuple end_val343 = hv_NumBatches-1;
  HTuple step_val343 = 1;
  for (hv_BatchIndex=0; hv_BatchIndex.Continue(end_val343, step_val343); hv_BatchIndex += step_val343)
  {
    hv_BatchStart = hv_BatchIndex*hv_BatchSize;
    hv_BatchEnd = ((hv_BatchStart+hv_BatchSize)-1).TupleMin2(hv_NumSamples-1);
    hv_SamplesIndicesBatch = hv_SampleIndices.TupleSelectRange(hv_BatchStart,hv_BatchEnd);
    //
    //Read samples
    read_dl_samples(hv_DLDataset, hv_SamplesIndicesBatch, &hv_DLSamplesBatch);
    //
    //Apply the model.
    ApplyDlModel(hv_DLModelHandle, hv_DLSamplesBatch, hv_Outputs, &hv_DLResultsBatch);
    //
    //Update the running measures.
    update_running_evaluation_measures(hv_DLSamplesBatch, hv_DLResultsBatch, (*hv_EvalParams), 
        hv_RunningMeasures);
    //
    //Provide progress information.
    if (0 != hv_ShowProgress)
    {
      if (0 != (HTuple(int((hv_BatchIndex%10)==1)).TupleOr(int(hv_BatchIndex==(hv_NumBatches-1)))))
      {
        estimate_progress(hv_SecondsStart, 0, hv_BatchIndex, hv_TotalNumBatches-1, 
            &hv_SecondsElapsed, &hv_SecondsRemaining, &hv_ProgressPercent, &hv_ProgressPerSecond);
        timespan_string(hv_SecondsElapsed, "auto", &hv_TimeElapsedString);
        timespan_string(hv_SecondsRemaining, "top2", &hv_TimeRemainingString);
        hv_Progress[1] = ("Progress: "+(hv_ProgressPercent.TupleRound()))+" %";
        hv_Progress[2] = "Time elapsed: "+hv_TimeElapsedString;
        hv_Progress[3] = "Time left: "+hv_TimeRemainingString;
      }
    }
  }
  }
  //
  //Loop batchwise over the out-of-distribution samples to be evaluated.
  if (0 != ((*hv_EvalParams).TupleGetDictTuple("calculate_ood_measures")))
  {
    {
    HTuple end_val372 = hv_NumOODBatches-1;
    HTuple step_val372 = 1;
    for (hv_BatchIndex=0; hv_BatchIndex.Continue(end_val372, step_val372); hv_BatchIndex += step_val372)
    {
      hv_BatchStart = hv_BatchIndex*hv_BatchSize;
      hv_BatchEnd = ((hv_BatchStart+hv_BatchSize)-1).TupleMin2(hv_NumOODSamples-1);
      //
      //Read samples
      hv_DLSamplesBatch = HTuple();
      {
      HTuple end_val378 = hv_BatchEnd;
      HTuple step_val378 = 1;
      for (hv_SampleIndex=hv_BatchStart; hv_SampleIndex.Continue(end_val378, step_val378); hv_SampleIndex += step_val378)
      {
        hv_DLSample = HTuple((hv_DLDataset.TupleGetDictTuple("ood_samples"))[hv_SampleIndex]);
        GetDictTuple(hv_DLSample, "dlsample_file_name", &hv_DictPath);
        try
        {
          ReadDict(((hv_DLDataset.TupleGetDictTuple("dlsample_dir"))+"/")+hv_DictPath, 
              HTuple(), HTuple(), &hv_DLSampleProc);
        }
        // catch (Exception) 
        catch (HException &HDevExpDefaultException)
        {
          HDevExpDefaultException.ToHTuple(&hv_Exception);
          throw HException((((("An error has occurred while reading "+(hv_DLDataset.TupleGetDictTuple("dlsample_dir")))+"/")+hv_DictPath)+HTuple(" , HALCON error # "))+HTuple(hv_Exception[0]));
        }
        //Add it to the DLSampleBatch.
        GetDictParam(hv_DLSampleProc, "key_exists", "is_ood", &hv_PreprocessedSampleIsOod);
        if (0 != (hv_PreprocessedSampleIsOod.TupleNot()))
        {
          throw HException(((("The preprocessed sample at "+(hv_DLDataset.TupleGetDictTuple("dlsample_dir")))+"/")+hv_DictPath)+" does not contain the key 'is_ood' but the corresponding sample in the DLDataset is part of DLDataset.ood_samples. To ensure proper evaluation of your out-of-distribution data please use the procedure 'add_dl_out_of_distribution_data' to add out-of-distribution samples to your dataset.");
        }
        hv_DLSamplesBatch = hv_DLSamplesBatch.TupleConcat(hv_DLSampleProc);
      }
      }
      //
      //Apply the model.
      ApplyDlModel(hv_DLModelHandle, hv_DLSamplesBatch, hv_Outputs, &hv_DLResultsBatch);
      //
      //Update the running measures.
      update_running_ood_detection_measures(hv_DLSamplesBatch, hv_DLResultsBatch, 
          (*hv_EvalParams), hv_RunningMeasures);
      //
      //Provide progress information.
      if (0 != hv_ShowProgress)
      {
        if (0 != (HTuple(int((hv_BatchIndex%10)==1)).TupleOr(int(hv_BatchIndex==(hv_NumOODBatches-1)))))
        {
          estimate_progress(hv_SecondsStart, 0, hv_NumBatches+hv_BatchIndex, hv_TotalNumBatches-1, 
              &hv_SecondsElapsed, &hv_SecondsRemaining, &hv_ProgressPercent, &hv_ProgressPerSecond);
          timespan_string(hv_SecondsElapsed, "auto", &hv_TimeElapsedString);
          timespan_string(hv_SecondsRemaining, "top2", &hv_TimeRemainingString);
          hv_Progress[1] = ("Progress: "+(hv_ProgressPercent.TupleRound()))+" %";
          hv_Progress[2] = "Time elapsed: "+hv_TimeElapsedString;
          hv_Progress[3] = "Time left: "+hv_TimeRemainingString;
        }
      }
    }
    }
  }
  //
  //Provide progress information.
  if (0 != (hv_ShowProgress.TupleAnd(int(hv_ModelType==HTuple("detection")))))
  {
    hv_Progress.Clear();
    hv_Progress[0] = "Procedure: evaluate_dl_model";
    hv_Progress[1] = "";
    hv_Progress[2] = "";
    hv_Progress[1] = "Please wait...";
    hv_Progress[2] = "Task: 2/2: Calculating final evaluation measures";
  }
  //
  //
  //** Do the actual calculation of measures: ***
  //
  calculate_evaluation_measures(hv_RunningMeasures, (*hv_EvalParams), &(*hv_EvaluationResult));
  //
  //Close progress inspect.
  if (0 != hv_ShowProgress)
  {
    hv_Progress = "Done.";
    // dev_close_inspect_ctrl(...); only in hdevelop
  }
  //
  return;
}

// Chapter: Deep Learning / Object Detection and Instance Segmentation
// Short Description: Filter the instance segmentation masks of a DL sample based on a given selection. 
void filter_dl_sample_instance_segmentation_masks (HTuple hv_DLSample, HTuple hv_BBoxSelectionMask)
{

  // Local iconic variables
  HObject  ho_EmptyMasks, ho_Masks;

  // Local control variables
  HTuple  hv_MaskKeyExists, hv_Indices;

  GetDictParam(hv_DLSample, "key_exists", "mask", &hv_MaskKeyExists);
  if (0 != hv_MaskKeyExists)
  {
    //Only if masks exist (-> instance segmentation).
    TupleFind(hv_BBoxSelectionMask, 1, &hv_Indices);
    if (0 != (int(hv_Indices==-1)))
    {
      //We define here that this case will result in an empty object value
      //for the mask key. Another option would be to remove the
      //key 'mask'. However, this would be an unwanted big change in the dictionary.
      GenEmptyObj(&ho_EmptyMasks);
      SetDictObject(ho_EmptyMasks, hv_DLSample, "mask");
    }
    else
    {
      GetDictObject(&ho_Masks, hv_DLSample, "mask");
      //Remove all unused masks.
      SelectObj(ho_Masks, &ho_Masks, hv_Indices+1);
      SetDictObject(ho_Masks, hv_DLSample, "mask");
    }
  }
  return;
}

// Chapter: Inspection / Structured Light
// Short Description: Find the HALCON calibration plate and set the extracted points and contours in a calibration data model for both the camera and the projector of the structured light model. 
void find_calib_object_structured_light (HObject ho_ImageSequence, HTuple hv_StructuredLightModel, 
    HTuple hv_CalibDataID, HTuple hv_CalibObjIdx, HTuple hv_CalibObjPoseIdx, HTuple hv_GenParamName, 
    HTuple hv_GenParamValue)
{

  // Local iconic variables
  HObject  ho_TextureImage;

  // Local control variables
  HTuple  hv_Pos, hv_RMSPoseErrorMax, hv_Exception;
  HTuple  hv_CamCenterRows, hv_CamCenterCols, hv_TargetIndices;
  HTuple  hv_ObjectPoseInCameraCS, hv_ProjCenterRows, hv_ProjCenterCols;
  HTuple  hv_StartProjParam, hv_X, hv_Y, hv_Z, hv_ObjectPoseInProjectorCS;
  HTuple  hv_Quality;

  //This procedure estimates the initial poses of the camera by
  //using the images of the calibration plate and then the initial
  //pose of the projector by using the correspondence images
  //computed by the structured light model.
  //Both estimated poses are set into the calibration model
  //CalibDataID. Note that the camera of the sensor has to
  //correspond to Index 0 in the calibration data model, the
  //projector of the sensor to Index 1.
  //
  //Check if the parameter 'rms_pose_error_max' was specified
  //in the generic parameters.
  hv_Pos = hv_GenParamName.TupleFind("rms_pose_error_max");
  if (0 != (HTuple(int(hv_Pos==-1)).TupleOr(int(hv_Pos==HTuple()))))
  {
    //Set default value.
    hv_RMSPoseErrorMax = 2.0;
    //
  }
  else
  {
    //Initialize RMSPoseErrorMax.
    hv_RMSPoseErrorMax = HTuple(hv_GenParamValue[hv_Pos]);
    if (0 != ((hv_RMSPoseErrorMax.TupleIsNumber()).TupleNot()))
    {
      hv_Exception = "Please specify a number as RMSPoseErrorMax";
      throw HException(hv_Exception);
    }
    //
    //Remove 'rms_pose_error_max' from the generic parameters.
    hv_GenParamName = hv_GenParamName.TupleRemove(hv_Pos);
    hv_GenParamValue = hv_GenParamValue.TupleRemove(hv_Pos);
    //
  }
  //
  //Extract the position of the calibration marks in the camera
  //image.
  retrieve_texture_structured_light(ho_ImageSequence, &ho_TextureImage);
  //
  //Find the calibration plate.
  FindCalibObject(ho_TextureImage, hv_CalibDataID, 0, hv_CalibObjIdx, hv_CalibObjPoseIdx, 
      hv_GenParamName, hv_GenParamValue);
  //
  //Get the image coordinates of the extracted targets.
  GetCalibDataObservPoints(hv_CalibDataID, 0, hv_CalibObjIdx, hv_CalibObjPoseIdx, 
      &hv_CamCenterRows, &hv_CamCenterCols, &hv_TargetIndices, &hv_ObjectPoseInCameraCS);
  //
  //Now, determine the position of the calibration targets in the
  //projector image.
  determine_camera_to_projector_correspondence_structured_light(ho_ImageSequence, 
      hv_StructuredLightModel, hv_CamCenterRows, hv_CamCenterCols, &hv_ProjCenterRows, 
      &hv_ProjCenterCols);
  //
  //Compute the initial projector pose relative to the coordinate
  //system of the calibration plate.
  GetCalibData(hv_CalibDataID, "camera", 1, "init_params", &hv_StartProjParam);
  GetCalibData(hv_CalibDataID, "calib_obj", hv_CalibObjIdx, "x", &hv_X);
  GetCalibData(hv_CalibDataID, "calib_obj", hv_CalibObjIdx, "y", &hv_Y);
  GetCalibData(hv_CalibDataID, "calib_obj", hv_CalibObjIdx, "z", &hv_Z);
  //
  VectorToPose(HTuple(hv_X[hv_TargetIndices]), HTuple(hv_Y[hv_TargetIndices]), HTuple(hv_Z[hv_TargetIndices]), 
      hv_ProjCenterRows, hv_ProjCenterCols, hv_StartProjParam, "planar_analytic", 
      "error", &hv_ObjectPoseInProjectorCS, &hv_Quality);
  //
  //Check if pose of the projector was estimated accurately.
  if (0 != (int(hv_Quality<hv_RMSPoseErrorMax)))
  {
    //
    //Put the point coordinates and the corresponding pose into
    //the calibration model.
    SetCalibDataObservPoints(hv_CalibDataID, 1, hv_CalibObjIdx, hv_CalibObjPoseIdx, 
        hv_ProjCenterRows, hv_ProjCenterCols, hv_TargetIndices, hv_ObjectPoseInProjectorCS);
  }
  else
  {
    RemoveCalibDataObserv(hv_CalibDataID, 0, hv_CalibObjIdx, hv_CalibObjPoseIdx);
    hv_Exception.Clear();
    hv_Exception[0] = "The estimated projector pose is unreliable and will be ignored";
    hv_Exception[1] = "Error in HALCON procedure";
    hv_Exception[2] = 82;
    hv_Exception[3] = "find_calib_object_structured_light";
    throw HException(hv_Exception);
  }
  //
  return;
}

// Chapter: Deep Learning / Model
// Short Description: Retrieve the indices of Samples that contain KeyName matching KeyValue according to the Mode set. 
void find_dl_samples (HTuple hv_Samples, HTuple hv_KeyName, HTuple hv_KeyValue, HTuple hv_Mode, 
    HTuple *hv_SampleIndices)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_NumKeyValues, hv_NumFound, hv_SampleIndex;
  HTuple  hv_Sample, hv_KeyExists, hv_Tuple, hv_Hit, hv_ValueIndex;
  HTuple  hv_Value;

  //
  //This procedure gets the indices of the samples that contain the
  //requested KeyName matching the requested KeyValue according to the Mode.
  //If there is no match, an empty tuple [] will be returned.
  //
  //Check input parameters.
  if (0 != (int((hv_KeyName.TupleLength())!=1)))
  {
    throw HException(HTuple("Invalid KeyName size: ")+(hv_KeyName.TupleLength()));
  }
  if (0 != (int((hv_Mode.TupleLength())!=1)))
  {
    throw HException(HTuple("Invalid Mode size: ")+(hv_Mode.TupleLength()));
  }
  if (0 != (HTuple(HTuple(int(hv_Mode!=HTuple("match"))).TupleAnd(int(hv_Mode!=HTuple("or")))).TupleAnd(int(hv_Mode!=HTuple("contain")))))
  {
    throw HException("Invalid Mode value: "+hv_Mode);
  }
  hv_NumKeyValues = hv_KeyValue.TupleLength();
  if (0 != (HTuple(int(hv_Mode==HTuple("contain"))).TupleAnd(int(hv_NumKeyValues<1))))
  {
    throw HException("Invalid KeyValue size for contain Mode: "+hv_NumKeyValues);
  }
  //
  //Find the indices.
  (*hv_SampleIndices) = HTuple(hv_Samples.TupleLength(),0);
  hv_NumFound = 0;
  //
  {
  HTuple end_val24 = (hv_Samples.TupleLength())-1;
  HTuple step_val24 = 1;
  for (hv_SampleIndex=0; hv_SampleIndex.Continue(end_val24, step_val24); hv_SampleIndex += step_val24)
  {
    hv_Sample = HTuple(hv_Samples[hv_SampleIndex]);
    GetDictParam(hv_Sample, "key_exists", hv_KeyName, &hv_KeyExists);
    if (0 != hv_KeyExists)
    {
      GetDictTuple(hv_Sample, hv_KeyName, &hv_Tuple);
      if (0 != (int(hv_Mode==HTuple("match"))))
      {
        //Mode 'match': Tuple must be equal KeyValue.
        hv_Hit = int(hv_Tuple==hv_KeyValue);
      }
      else if (0 != (HTuple(int(hv_Mode==HTuple("or"))).TupleAnd(int((hv_Tuple.TupleLength())==1))))
      {
        //Mode 'or': Tuple must have only 1 element and it has to be equal to any of KeyValues elements.
        hv_Hit = int((hv_KeyValue.TupleFindFirst(hv_Tuple))>=0);
      }
      else if (0 != (int(hv_Mode==HTuple("contain"))))
      {
        //Mode 'contain': Tuple must contain any of the elements in KeyValue.
        {
        HTuple end_val37 = hv_NumKeyValues-1;
        HTuple step_val37 = 1;
        for (hv_ValueIndex=0; hv_ValueIndex.Continue(end_val37, step_val37); hv_ValueIndex += step_val37)
        {
          hv_Value = HTuple(hv_KeyValue[hv_ValueIndex]);
          hv_Hit = int((hv_Tuple.TupleFindFirst(hv_Value))>=0);
          if (0 != hv_Hit)
          {
            break;
          }
        }
        }
      }
      else
      {
        //Unsupported configuration.
        hv_Hit = 0;
      }
      if (0 != hv_Hit)
      {
        (*hv_SampleIndices)[hv_NumFound] = hv_SampleIndex;
        hv_NumFound += 1;
      }
    }
  }
  }
  (*hv_SampleIndices) = (*hv_SampleIndices).TupleSelectRange(0,hv_NumFound-1);
  return;
}

// Chapter: OCR / Deep OCR
// Short Description: Find invalid deep ocr recognition samples. 
void find_invalid_samples_dl_ocr_recognition (HTuple hv_Samples, HTuple hv_DLModelHandle, 
    HTuple hv_GenericParam, HTuple *hv_Indices, HTuple *hv_Reasons)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_KeyExists, hv_Alphabet, hv_ImageWidth;
  HTuple  hv_MaxWordLength, hv_InvalidSamples, hv_Words, hv_I;
  HTuple  hv_Word, hv_WordLengths, hv_Equal, hv_EmptyWordIndices;
  HTuple  hv_Greater, hv_TooLongWordIndices, hv_AlphabetDict;
  HTuple  hv_MissingCharIndices, hv_WordChars, hv_N, hv_WordCharArray;
  HTuple  hv_C, hv_CharExist, hv_MissingCharsReason, hv_TooLongWordReason;
  HTuple  hv_EmptyWordIndicesWordReason;

  if (0 != (int((hv_GenericParam.TupleLength())==0)))
  {
    //Use default values.
    CreateDict(&hv_GenericParam);
    SetDictTuple(hv_GenericParam, "pixel_per_char_estimate", 6.0);
  }
  else
  {
    GetDictParam(hv_GenericParam, "key_exists", "pixel_per_char_estimate", &hv_KeyExists);
    if (0 != (hv_KeyExists.TupleNot()))
    {
      SetDictTuple(hv_GenericParam, "pixel_per_char_estimate", 6.0);
    }
    SetDictTuple(hv_GenericParam, "pixel_per_char_estimate", (hv_GenericParam.TupleGetDictTuple("pixel_per_char_estimate")).TupleReal());
  }
  //
  GetDlModelParam(hv_DLModelHandle, "alphabet", &hv_Alphabet);
  GetDlModelParam(hv_DLModelHandle, "image_width", &hv_ImageWidth);
  hv_MaxWordLength = (((hv_ImageWidth.TupleReal())/((hv_GenericParam.TupleGetDictTuple("pixel_per_char_estimate")).TupleReal())).TupleCeil()).TupleInt();
  hv_InvalidSamples = HTuple();
  TupleGenConst(hv_Samples.TupleLength(), -1, &hv_Words);
  {
  HTuple end_val17 = (hv_Samples.TupleLength())-1;
  HTuple step_val17 = 1;
  for (hv_I=0; hv_I.Continue(end_val17, step_val17); hv_I += step_val17)
  {
    GetDictTuple(HTuple(hv_Samples[hv_I]), "word", &hv_Word);
    hv_Words[hv_I] = hv_Word;
  }
  }
  TupleStrlen(hv_Words, &hv_WordLengths);
  TupleEqualElem(hv_WordLengths, 0, &hv_Equal);
  TupleFind(hv_Equal, 1, &hv_EmptyWordIndices);
  if (0 != (int(hv_EmptyWordIndices==-1)))
  {
    hv_EmptyWordIndices = HTuple();
  }
  TupleGreaterElem(hv_WordLengths, hv_MaxWordLength, &hv_Greater);
  TupleFind(hv_Greater, 1, &hv_TooLongWordIndices);
  if (0 != (int(hv_TooLongWordIndices==-1)))
  {
    hv_TooLongWordIndices = HTuple();
  }
  CreateDict(&hv_AlphabetDict);
  {
  HTuple end_val33 = (hv_Alphabet.TupleLength())-1;
  HTuple step_val33 = 1;
  for (hv_I=0; hv_I.Continue(end_val33, step_val33); hv_I += step_val33)
  {
    SetDictTuple(hv_AlphabetDict, HTuple(hv_Alphabet[hv_I]), 1);
  }
  }
  //
  //Search for words that contain characters that are not part of the alphabet.
  TupleGenConst(hv_Words.TupleLength(), 0, &hv_MissingCharIndices);
  {
  HTuple end_val39 = (hv_Words.TupleLength())-1;
  HTuple step_val39 = 1;
  for (hv_I=0; hv_I.Continue(end_val39, step_val39); hv_I += step_val39)
  {
    hv_Word = HTuple(hv_Words[hv_I]);
    TupleUniq(hv_Word, &hv_WordChars);
    hv_N = hv_WordChars.TupleStrlen();
    if (0 != (int(hv_N==0)))
    {
      continue;
    }
    TupleGenConst(hv_N, "", &hv_WordCharArray);
    {
    HTuple end_val47 = hv_N-1;
    HTuple step_val47 = 1;
    for (hv_C=0; hv_C.Continue(end_val47, step_val47); hv_C += step_val47)
    {
      hv_WordCharArray[hv_C] = hv_WordChars.TupleStrBitSelect(hv_C);
    }
    }
    GetDictParam(hv_AlphabetDict, "key_exists", hv_WordCharArray, &hv_CharExist);
    TupleFind(hv_CharExist, 0, &(*hv_Indices));
    hv_MissingCharIndices[hv_I] = int((*hv_Indices)!=-1);
  }
  }
  TupleFind(hv_MissingCharIndices, 1, &hv_MissingCharIndices);
  if (0 != (int(hv_MissingCharIndices==-1)))
  {
    hv_MissingCharIndices = HTuple();
  }
  TupleGenConst(hv_MissingCharIndices.TupleLength(), "unknown char", &hv_MissingCharsReason);
  TupleGenConst(hv_TooLongWordIndices.TupleLength(), "word too long", &hv_TooLongWordReason);
  TupleGenConst(hv_EmptyWordIndices.TupleLength(), "empty word", &hv_EmptyWordIndicesWordReason);
  (*hv_Indices).Clear();
  (*hv_Indices).Append(hv_MissingCharIndices);
  (*hv_Indices).Append(hv_TooLongWordIndices);
  (*hv_Indices).Append(hv_EmptyWordIndices);
  (*hv_Reasons).Clear();
  (*hv_Reasons).Append(hv_MissingCharsReason);
  (*hv_Reasons).Append(hv_TooLongWordReason);
  (*hv_Reasons).Append(hv_EmptyWordIndicesWordReason);
  return;
}

// Chapter: XLD / Creation
// Short Description: Create an arrow shaped XLD contour. 
void gen_arrow_contour_xld (HObject *ho_Arrow, HTuple hv_Row1, HTuple hv_Column1, 
    HTuple hv_Row2, HTuple hv_Column2, HTuple hv_HeadLength, HTuple hv_HeadWidth)
{

  // Local iconic variables
  HObject  ho_TempArrow;

  // Local control variables
  HTuple  hv_Length, hv_ZeroLengthIndices, hv_DR;
  HTuple  hv_DC, hv_HalfHeadWidth, hv_RowP1, hv_ColP1, hv_RowP2;
  HTuple  hv_ColP2, hv_Index;

  //This procedure generates arrow shaped XLD contours,
  //pointing from (Row1, Column1) to (Row2, Column2).
  //If starting and end point are identical, a contour consisting
  //of a single point is returned.
  //
  //input parameters:
  //Row1, Column1: Coordinates of the arrows' starting points
  //Row2, Column2: Coordinates of the arrows' end points
  //HeadLength, HeadWidth: Size of the arrow heads in pixels
  //
  //output parameter:
  //Arrow: The resulting XLD contour
  //
  //The input tuples Row1, Column1, Row2, and Column2 have to be of
  //the same length.
  //HeadLength and HeadWidth either have to be of the same length as
  //Row1, Column1, Row2, and Column2 or have to be a single element.
  //If one of the above restrictions is violated, an error will occur.
  //
  //
  //Initialization.
  GenEmptyObj(&(*ho_Arrow));
  //
  //Calculate the arrow length
  DistancePp(hv_Row1, hv_Column1, hv_Row2, hv_Column2, &hv_Length);
  //
  //Mark arrows with identical start and end point
  //(set Length to -1 to avoid division-by-zero exception)
  hv_ZeroLengthIndices = hv_Length.TupleFind(0);
  if (0 != (int(hv_ZeroLengthIndices!=-1)))
  {
    hv_Length[hv_ZeroLengthIndices] = -1;
  }
  //
  //Calculate auxiliary variables.
  hv_DR = (1.0*(hv_Row2-hv_Row1))/hv_Length;
  hv_DC = (1.0*(hv_Column2-hv_Column1))/hv_Length;
  hv_HalfHeadWidth = hv_HeadWidth/2.0;
  //
  //Calculate end points of the arrow head.
  hv_RowP1 = (hv_Row1+((hv_Length-hv_HeadLength)*hv_DR))+(hv_HalfHeadWidth*hv_DC);
  hv_ColP1 = (hv_Column1+((hv_Length-hv_HeadLength)*hv_DC))-(hv_HalfHeadWidth*hv_DR);
  hv_RowP2 = (hv_Row1+((hv_Length-hv_HeadLength)*hv_DR))-(hv_HalfHeadWidth*hv_DC);
  hv_ColP2 = (hv_Column1+((hv_Length-hv_HeadLength)*hv_DC))+(hv_HalfHeadWidth*hv_DR);
  //
  //Finally create output XLD contour for each input point pair
  {
  HTuple end_val45 = (hv_Length.TupleLength())-1;
  HTuple step_val45 = 1;
  for (hv_Index=0; hv_Index.Continue(end_val45, step_val45); hv_Index += step_val45)
  {
    if (0 != (int(HTuple(hv_Length[hv_Index])==-1)))
    {
      //Create_ single points for arrows with identical start and end point
      GenContourPolygonXld(&ho_TempArrow, HTuple(hv_Row1[hv_Index]), HTuple(hv_Column1[hv_Index]));
    }
    else
    {
      //Create arrow contour
      GenContourPolygonXld(&ho_TempArrow, ((((HTuple(hv_Row1[hv_Index]).TupleConcat(HTuple(hv_Row2[hv_Index]))).TupleConcat(HTuple(hv_RowP1[hv_Index]))).TupleConcat(HTuple(hv_Row2[hv_Index]))).TupleConcat(HTuple(hv_RowP2[hv_Index]))).TupleConcat(HTuple(hv_Row2[hv_Index])), 
          ((((HTuple(hv_Column1[hv_Index]).TupleConcat(HTuple(hv_Column2[hv_Index]))).TupleConcat(HTuple(hv_ColP1[hv_Index]))).TupleConcat(HTuple(hv_Column2[hv_Index]))).TupleConcat(HTuple(hv_ColP2[hv_Index]))).TupleConcat(HTuple(hv_Column2[hv_Index])));
    }
    ConcatObj((*ho_Arrow), ho_TempArrow, &(*ho_Arrow));
  }
  }
  return;
}

// Chapter: 3D Object Model / Creation
void gen_arrow_object_model_3d (HTuple hv_ArrowThickness, HTuple hv_ArrowStart, HTuple hv_ArrowEnd, 
    HTuple *hv_OM3DArrow)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_DirectionVector, hv_ArrowLength, hv_ConeRadius;
  HTuple  hv_ConeLength, hv_CylinderLength, hv_pi, hv_X, hv_Y;
  HTuple  hv_Z, hv_Index, hv_OM3DConeTmp, hv_OM3DCone, hv_ZZero;
  HTuple  hv_ZTop, hv_OM3DCylinderTmp, hv_OM3DCylinder, hv_OM3DArrowTmp;
  HTuple  hv_Scale, hv_OriginX, hv_OriginY, hv_OriginZ, hv_TargetX;
  HTuple  hv_TargetY, hv_TargetZ, hv_HomMat3D;

  //
  //This procedure draws an arrow that starts at the point ArrowStart and ends at ArrowEnd.
  //
  //Get parameters.
  hv_DirectionVector = (hv_ArrowEnd.TupleSelectRange(0,2))-(hv_ArrowStart.TupleSelectRange(0,2));
  hv_ArrowLength = (((HTuple(hv_DirectionVector[0])*HTuple(hv_DirectionVector[0]))+(HTuple(hv_DirectionVector[1])*HTuple(hv_DirectionVector[1])))+(HTuple(hv_DirectionVector[2])*HTuple(hv_DirectionVector[2]))).TupleSqrt();
  hv_ConeRadius = 2.0*hv_ArrowThickness;
  hv_ConeLength = ((2.0*hv_ConeRadius).TupleConcat(hv_ArrowLength*0.9)).TupleMin();
  hv_CylinderLength = hv_ArrowLength-hv_ConeLength;
  //
  //Create cone.
  hv_pi = HTuple(180).TupleRad();
  hv_X = 0;
  hv_Y = 0;
  hv_Z = hv_CylinderLength+hv_ConeLength;
  {
  HTuple end_val15 = 2*hv_pi;
  HTuple step_val15 = 0.1;
  for (hv_Index=0; hv_Index.Continue(end_val15, step_val15); hv_Index += step_val15)
  {
    hv_X = hv_X.TupleConcat(hv_ConeRadius*(hv_Index.TupleCos()));
    hv_Y = hv_Y.TupleConcat(hv_ConeRadius*(hv_Index.TupleSin()));
    hv_Z = hv_Z.TupleConcat(hv_CylinderLength);
  }
  }
  GenObjectModel3dFromPoints(hv_X, hv_Y, hv_Z, &hv_OM3DConeTmp);
  ConvexHullObjectModel3d(hv_OM3DConeTmp, &hv_OM3DCone);
  ClearObjectModel3d(hv_OM3DConeTmp);
  //
  //Create cylinder.
  hv_X = HTuple();
  hv_Y = HTuple();
  {
  HTuple end_val27 = 2*hv_pi;
  HTuple step_val27 = 0.1;
  for (hv_Index=0; hv_Index.Continue(end_val27, step_val27); hv_Index += step_val27)
  {
    hv_X = hv_X.TupleConcat(hv_ArrowThickness*(hv_Index.TupleCos()));
    hv_Y = hv_Y.TupleConcat(hv_ArrowThickness*(hv_Index.TupleSin()));
  }
  }
  TupleGenConst(hv_Y.TupleLength(), 0, &hv_ZZero);
  TupleGenConst(hv_Y.TupleLength(), hv_CylinderLength, &hv_ZTop);
  GenObjectModel3dFromPoints(hv_X.TupleConcat(hv_X), hv_Y.TupleConcat(hv_Y), hv_ZZero.TupleConcat(hv_ZTop), 
      &hv_OM3DCylinderTmp);
  ConvexHullObjectModel3d(hv_OM3DCylinderTmp, &hv_OM3DCylinder);
  ClearObjectModel3d(hv_OM3DCylinderTmp);
  //
  //Union cone and cylinder Create arrow.
  UnionObjectModel3d(hv_OM3DCone.TupleConcat(hv_OM3DCylinder), "points_surface", 
      &hv_OM3DArrowTmp);
  ClearObjectModel3d(hv_OM3DCone);
  ClearObjectModel3d(hv_OM3DCylinder);
  hv_Scale = hv_CylinderLength/hv_ArrowLength;
  hv_OriginX.Clear();
  hv_OriginX[0] = 0;
  hv_OriginX[1] = 0;
  hv_OriginX[2] = 0;
  hv_OriginY.Clear();
  hv_OriginY[0] = 0;
  hv_OriginY[1] = 0;
  hv_OriginY[2] = 0;
  hv_OriginZ.Clear();
  hv_OriginZ[0] = 0;
  hv_OriginZ.Append(hv_CylinderLength);
  hv_OriginZ.Append(hv_ArrowLength);
  hv_TargetX.Clear();
  hv_TargetX.Append(HTuple(hv_ArrowStart[0]));
  hv_TargetX.Append(HTuple(hv_ArrowStart[0])+(hv_Scale*HTuple(hv_DirectionVector[0])));
  hv_TargetX.Append(HTuple(hv_ArrowEnd[0]));
  hv_TargetY.Clear();
  hv_TargetY.Append(HTuple(hv_ArrowStart[1]));
  hv_TargetY.Append(HTuple(hv_ArrowStart[1])+(hv_Scale*HTuple(hv_DirectionVector[1])));
  hv_TargetY.Append(HTuple(hv_ArrowEnd[1]));
  hv_TargetZ.Clear();
  hv_TargetZ.Append(HTuple(hv_ArrowStart[2]));
  hv_TargetZ.Append(HTuple(hv_ArrowStart[2])+(hv_Scale*HTuple(hv_DirectionVector[2])));
  hv_TargetZ.Append(HTuple(hv_ArrowEnd[2]));
  VectorToHomMat3d("rigid", hv_OriginX, hv_OriginY, hv_OriginZ, hv_TargetX, hv_TargetY, 
      hv_TargetZ, &hv_HomMat3D);
  AffineTransObjectModel3d(hv_OM3DArrowTmp, hv_HomMat3D, &(*hv_OM3DArrow));
  ClearObjectModel3d(hv_OM3DArrowTmp);
  return;
}

// Chapter: Deep Learning / Model
// Short Description: Create blank train sample dictionaries for a given model. 
void gen_blank_dl_train_samples (HTuple hv_DLModelHandle, HTuple *hv_TrainSamples)
{

  // Local iconic variables
  HObject  ho_Images, ho_Image, ho_EmptyObject;
  HObject  ho_ConstImage, ho_ConstImage2, ho_Target, ho_Weight;

  // Local control variables
  HTuple  hv_ModelType, hv_BatchSize, hv_ImageWidth;
  HTuple  hv_ImageHeight, hv_ImageNumChannels, hv_ClassIDs;
  HTuple  hv_I, hv_Index, hv_TrainInput, hv_InstanceType;
  HTuple  hv_Exception, hv_InstanceSegmentation, hv_Alphabet;

  //
  //This procedure generates blank input data for the given model.
  //
  //Get model parameters.
  GetDlModelParam(hv_DLModelHandle, "type", &hv_ModelType);
  GetDlModelParam(hv_DLModelHandle, "batch_size", &hv_BatchSize);
  GetDlModelParam(hv_DLModelHandle, "image_width", &hv_ImageWidth);
  GetDlModelParam(hv_DLModelHandle, "image_height", &hv_ImageHeight);
  GetDlModelParam(hv_DLModelHandle, "image_num_channels", &hv_ImageNumChannels);
  if (0 != (HTuple(HTuple(int(hv_ModelType!=HTuple("gc_anomaly_detection"))).TupleAnd(int(hv_ModelType!=HTuple("ocr_recognition")))).TupleAnd(int(hv_ModelType!=HTuple("ocr_detection")))))
  {
    GetDlModelParam(hv_DLModelHandle, "class_ids", &hv_ClassIDs);
  }
  //
  //Collect train inputs.
  (*hv_TrainSamples) = HTuple();
  //
  {
  HTuple end_val16 = hv_BatchSize-1;
  HTuple step_val16 = 1;
  for (hv_I=0; hv_I.Continue(end_val16, step_val16); hv_I += step_val16)
  {
    //Create blank image.
    GenEmptyObj(&ho_Images);
    {
    HTuple end_val19 = hv_ImageNumChannels-1;
    HTuple step_val19 = 1;
    for (hv_Index=0; hv_Index.Continue(end_val19, step_val19); hv_Index += step_val19)
    {
      GenImageConst(&ho_Image, "real", hv_ImageWidth, hv_ImageHeight);
      ConcatObj(ho_Images, ho_Image, &ho_Images);
    }
    }
    ChannelsToImage(ho_Images, &ho_Image);
    //
    //Create train data.
    CreateDict(&hv_TrainInput);
    SetDictObject(ho_Image, hv_TrainInput, "image");
    //
    //Add model specific blank training data.
    if (0 != (int(hv_ModelType==HTuple("classification"))))
    {
      //Assign arbitrary label for image.
      SetDictTuple(hv_TrainInput, "image_label_id", 0);
    }
    else if (0 != (int(hv_ModelType==HTuple("detection"))))
    {
      //Generate blank bounding box labels depending on the instance type.
      hv_InstanceType = "rectangle1";
      try
      {
        GetDlModelParam(hv_DLModelHandle, "instance_type", &hv_InstanceType);
      }
      // catch (Exception) 
      catch (HException &HDevExpDefaultException)
      {
        HDevExpDefaultException.ToHTuple(&hv_Exception);
      }
      if (0 != (int(hv_InstanceType==HTuple("rectangle1"))))
      {
        SetDictTuple(hv_TrainInput, "bbox_label_id", HTuple());
        SetDictTuple(hv_TrainInput, "bbox_row1", HTuple());
        SetDictTuple(hv_TrainInput, "bbox_row2", HTuple());
        SetDictTuple(hv_TrainInput, "bbox_col1", HTuple());
        SetDictTuple(hv_TrainInput, "bbox_col2", HTuple());
      }
      else if (0 != (int(hv_InstanceType==HTuple("rectangle2"))))
      {
        SetDictTuple(hv_TrainInput, "bbox_label_id", HTuple());
        SetDictTuple(hv_TrainInput, "bbox_row", HTuple());
        SetDictTuple(hv_TrainInput, "bbox_col", HTuple());
        SetDictTuple(hv_TrainInput, "bbox_length1", HTuple());
        SetDictTuple(hv_TrainInput, "bbox_length2", HTuple());
        SetDictTuple(hv_TrainInput, "bbox_phi", HTuple());
      }
      else
      {
        throw HException(("The current instance type is not supported: \""+hv_InstanceType)+"\"");
      }
      hv_InstanceSegmentation = 0;
      try
      {
        GetDlModelParam(hv_DLModelHandle, "instance_segmentation", &hv_InstanceSegmentation);
        hv_InstanceSegmentation = int(hv_InstanceSegmentation==HTuple("true"));
      }
      // catch (Exception) 
      catch (HException &HDevExpDefaultException)
      {
        HDevExpDefaultException.ToHTuple(&hv_Exception);
      }
      if (0 != hv_InstanceSegmentation)
      {
        GenEmptyObj(&ho_EmptyObject);
        SetDictObject(ho_EmptyObject, hv_TrainInput, "mask");
      }
    }
    else if (0 != (int(hv_ModelType==HTuple("gc_anomaly_detection"))))
    {
      //Nothing has to be done.
    }
    else if (0 != (int(hv_ModelType==HTuple("ocr_recognition"))))
    {
      //Generate dummy word label with the first alphabet entry.
      GetDlModelParam(hv_DLModelHandle, "alphabet", &hv_Alphabet);
      SetDictTuple(hv_TrainInput, "word", HTuple(hv_Alphabet[0]));
    }
    else if (0 != (int(hv_ModelType==HTuple("ocr_detection"))))
    {
      SetDictTuple(hv_TrainInput, "bbox_label_id", HTuple());
      SetDictTuple(hv_TrainInput, "bbox_row", HTuple());
      SetDictTuple(hv_TrainInput, "bbox_col", HTuple());
      SetDictTuple(hv_TrainInput, "bbox_length1", HTuple());
      SetDictTuple(hv_TrainInput, "bbox_length2", HTuple());
      SetDictTuple(hv_TrainInput, "bbox_phi", HTuple());
      SetDictTuple(hv_TrainInput, "word", HTuple());
      GenImageConst(&ho_ConstImage, "real", hv_ImageWidth/2, hv_ImageHeight/2);
      Compose2(ho_ConstImage, ho_ConstImage, &ho_ConstImage2);
      SetDictObject(ho_ConstImage, hv_TrainInput, "target_text");
      SetDictObject(ho_ConstImage, hv_TrainInput, "target_link");
      SetDictObject(ho_ConstImage2, hv_TrainInput, "target_orientation");
      SetDictObject(ho_ConstImage, hv_TrainInput, "target_weight_text");
      SetDictObject(ho_ConstImage, hv_TrainInput, "target_weight_link");
      SetDictObject(ho_ConstImage2, hv_TrainInput, "target_weight_orientation");
    }
    else if (0 != (int(hv_ModelType==HTuple("segmentation"))))
    {
      //Generate blank weights and targets.
      GenImageConst(&ho_Target, "real", hv_ImageWidth, hv_ImageHeight);
      GenImageConst(&ho_Weight, "real", hv_ImageWidth, hv_ImageHeight);
      //Fill with first color background.
      OverpaintRegion(ho_Target, ho_Target, HTuple(hv_ClassIDs[0]), "fill");
      OverpaintRegion(ho_Weight, ho_Weight, 1, "fill");
      SetDictObject(ho_Target, hv_TrainInput, "segmentation_image");
      SetDictObject(ho_Weight, hv_TrainInput, "weight_image");
    }
    else if (0 != (int(hv_ModelType==HTuple("multi_label_classification"))))
    {
      //Generate blank weights and targets.
      SetDictTuple(hv_TrainInput, "image_label_ids", HTuple());
    }
    else
    {
      throw HException(("The current model type is not supported: \""+hv_ModelType)+"\"");
    }
    (*hv_TrainSamples) = (*hv_TrainSamples).TupleConcat(hv_TrainInput);
  }
  }
  return;
}

// Chapter: 3D Object Model / Creation
// Short Description: Generate a 3D object model which visualizes the bounding box of a stereo model. 
void gen_bounding_box_object_model_3d (HTuple hv_StereoModelID, HTuple *hv_ObjectModel3DBoundingBox)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_BoundingBox, hv_PX, hv_PY, hv_PZ, hv_Index;
  HTuple  hv_Faces;
  HTupleVector  hvec_Points(1);

  //
  //Consistency check:
  GetStereoModelParam(hv_StereoModelID, "bounding_box", &hv_BoundingBox);
  if (0 != (HTuple(HTuple(int(HTuple(hv_BoundingBox[3])<HTuple(hv_BoundingBox[0]))).TupleOr(int(HTuple(hv_BoundingBox[4])<HTuple(hv_BoundingBox[1])))).TupleOr(int(HTuple(hv_BoundingBox[5])<HTuple(hv_BoundingBox[2])))))
  {
    throw HException("Invalid bounding box or bounding box not set yet.");
  }
  //
  //Get the eight corner points from the min/max representation.
  hvec_Points = (HTupleVector(1).Insert(0,HTupleVector(HTuple())));
  hvec_Points[0] = HTupleVector((HTuple(hv_BoundingBox[0]).TupleConcat(HTuple(hv_BoundingBox[1]))).TupleConcat(HTuple(hv_BoundingBox[2])));
  hvec_Points[1] = HTupleVector((HTuple(hv_BoundingBox[3]).TupleConcat(HTuple(hv_BoundingBox[1]))).TupleConcat(HTuple(hv_BoundingBox[2])));
  hvec_Points[2] = HTupleVector((HTuple(hv_BoundingBox[3]).TupleConcat(HTuple(hv_BoundingBox[4]))).TupleConcat(HTuple(hv_BoundingBox[2])));
  hvec_Points[3] = HTupleVector((HTuple(hv_BoundingBox[0]).TupleConcat(HTuple(hv_BoundingBox[4]))).TupleConcat(HTuple(hv_BoundingBox[2])));
  hvec_Points[4] = HTupleVector((HTuple(hv_BoundingBox[0]).TupleConcat(HTuple(hv_BoundingBox[1]))).TupleConcat(HTuple(hv_BoundingBox[5])));
  hvec_Points[5] = HTupleVector((HTuple(hv_BoundingBox[3]).TupleConcat(HTuple(hv_BoundingBox[1]))).TupleConcat(HTuple(hv_BoundingBox[5])));
  hvec_Points[6] = HTupleVector((HTuple(hv_BoundingBox[3]).TupleConcat(HTuple(hv_BoundingBox[4]))).TupleConcat(HTuple(hv_BoundingBox[5])));
  hvec_Points[7] = HTupleVector((HTuple(hv_BoundingBox[0]).TupleConcat(HTuple(hv_BoundingBox[4]))).TupleConcat(HTuple(hv_BoundingBox[5])));
  //
  //Sort the corner points by coordinate direction.
  hv_PX = HTuple();
  hv_PY = HTuple();
  hv_PZ = HTuple();
  for (hv_Index=0; hv_Index<=7; hv_Index+=1)
  {
    hv_PX = hv_PX.TupleConcat(HTuple(hvec_Points[hv_Index].T()[0]));
    hv_PY = hv_PY.TupleConcat(HTuple(hvec_Points[hv_Index].T()[1]));
    hv_PZ = hv_PZ.TupleConcat(HTuple(hvec_Points[hv_Index].T()[2]));
  }
  GenObjectModel3dFromPoints(hv_PX, hv_PY, hv_PZ, &(*hv_ObjectModel3DBoundingBox));
  //
  //Set the sides of the cuboid.
  hv_Faces = HTuple();
  hv_Faces = hv_Faces.TupleConcat(((((HTuple(4).Append(0)).Append(1)).Append(5)).Append(4)));
  hv_Faces = hv_Faces.TupleConcat(((((HTuple(4).Append(1)).Append(2)).Append(6)).Append(5)));
  hv_Faces = hv_Faces.TupleConcat(((((HTuple(4).Append(2)).Append(3)).Append(7)).Append(6)));
  hv_Faces = hv_Faces.TupleConcat(((((HTuple(4).Append(3)).Append(0)).Append(4)).Append(7)));
  hv_Faces = hv_Faces.TupleConcat(((((HTuple(4).Append(0)).Append(1)).Append(2)).Append(3)));
  hv_Faces = hv_Faces.TupleConcat(((((HTuple(4).Append(4)).Append(5)).Append(6)).Append(7)));
  SetObjectModel3dAttribMod((*hv_ObjectModel3DBoundingBox), "polygons", HTuple(), 
      hv_Faces);
  return;
}

