// Chapter: Deep Learning / Model
// Short Description: Generate certain colors for different ClassNames 
void get_dl_class_colors (HTuple hv_ClassNames, HTuple hv_AdditionalGreenClassNames, 
    HTuple *hv_Colors)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_NumColors, hv_ColorsRainbow, hv_ClassNamesGood;
  HTuple  hv_IndexFind, hv_GoodIdx, hv_CurrentColor, hv_GreenIdx;

  //
  //This procedure returns for each class a certain color.
  //
  //Define distinct colors for the classes.
  hv_NumColors = hv_ClassNames.TupleLength();
  //Get distinct colors without randomness makes neighboring colors look very similar.
  //We use a workaround to get deterministic colors where subsequent colors are distinguishable.
  get_distinct_colors(hv_NumColors, 0, 0, 200, &hv_ColorsRainbow);
  TupleInverse(hv_ColorsRainbow, &hv_ColorsRainbow);
  make_neighboring_colors_distinguishable(hv_ColorsRainbow, &(*hv_Colors));
  //If a class 'OK','ok', 'good' or 'GOOD' or a class specified in AdditionalGreenClassNames is present set this class to green.
  //Only the first occurrence found is set to a green shade.
  TupleUnion((((HTuple("good").Append("GOOD")).Append("ok")).Append("OK")), hv_AdditionalGreenClassNames, 
      &hv_ClassNamesGood);
  {
  HTuple end_val13 = (hv_ClassNamesGood.TupleLength())-1;
  HTuple step_val13 = 1;
  for (hv_IndexFind=0; hv_IndexFind.Continue(end_val13, step_val13); hv_IndexFind += step_val13)
  {
    hv_GoodIdx = hv_ClassNames.TupleFindFirst(HTuple(hv_ClassNamesGood[hv_IndexFind]));
    if (0 != (HTuple(int(hv_GoodIdx!=-1)).TupleAnd(int((hv_ClassNames.TupleLength())<=8))))
    {
      //If number of classes is <= 8, swap color with a green color.
      hv_CurrentColor = HTuple((*hv_Colors)[hv_GoodIdx]);
      hv_GreenIdx = HTuple((hv_ClassNames.TupleLength())/2.0).TupleFloor();
      //Set to pure green.
      (*hv_Colors)[hv_GoodIdx] = "#00ff00";
      //Write original color to a green entry.
      (*hv_Colors)[hv_GreenIdx] = hv_CurrentColor;
      break;
    }
    else if (0 != (HTuple(int(hv_GoodIdx!=-1)).TupleAnd(int((hv_ClassNames.TupleLength())>8))))
    {
      //If number of classes is larger than 8, set the respective color to green.
      (*hv_Colors)[hv_GoodIdx] = "#00ff00";
      break;
    }
  }
  }
  return;
}

// Chapter: Legacy / DL Classification
// Short Description: Display and return the classified images. 
void get_dl_classifier_image_results (HObject *ho_Images, HTuple hv_ImageFiles, HTuple hv_GroundTruthLabels, 
    HTuple hv_PredictedClasses, HTuple hv_GenParamName, HTuple hv_GenParamValue, 
    HTuple hv_WindowHandle)
{

  // Local iconic variables
  HObject  ho_Image;

  // Local control variables
  HTuple  hv_LabelSelection, hv_PredictedClassSelection;
  HTuple  hv_GlobalSelection, hv_DisplayImages, hv_DisplayButtons;
  HTuple  hv_GenParamIndex, hv_Mask, hv_ImageIndex, hv_Label;
  HTuple  hv_PredictedClass, hv_Text, hv_Color, hv_Row, hv_Column;
  HTuple  hv_WindowWidth, hv_WindowHeight, hv_ButtonLabel;
  HTuple  hv_Ascent, hv_Descent, hv_TextWidth, hv_TextHeight;
  HTuple  hv_ButtonRow, hv_ButtonColumn, hv_ColorLabels, hv_HighlightColor;
  HTuple  hv_SelectedButton;

  //This procedure can be used to visualize classified
  //ImageFiles selected according to the specifications
  //given with GenParamName and GenParamValue.
  //
  //Set parameter defaults.
  hv_LabelSelection = "all";
  hv_PredictedClassSelection = "all";
  hv_GlobalSelection = "erroneously_classified";
  hv_DisplayImages = "true";
  hv_DisplayButtons = "false";
  //
  //Check if number of elements in
  //GenParamName and GenParamValue is equal.
  if (0 != (int((hv_GenParamName.TupleLength())!=(hv_GenParamValue.TupleLength()))))
  {
    throw HException("Number of generic parameter names does not match number of generic parameter values.");
  }
  //
  //Parse generic parameters.
  {
  HTuple end_val18 = (hv_GenParamName.TupleLength())-1;
  HTuple step_val18 = 1;
  for (hv_GenParamIndex=0; hv_GenParamIndex.Continue(end_val18, step_val18); hv_GenParamIndex += step_val18)
  {
    if (0 != (int(HTuple(hv_GenParamName[hv_GenParamIndex])==HTuple("label_selection"))))
    {
      //Set 'label_selection'.
      hv_LabelSelection = HTuple(hv_GenParamValue[hv_GenParamIndex]);
    }
    else if (0 != (int(HTuple(hv_GenParamName[hv_GenParamIndex])==HTuple("predicted_class_selection"))))
    {
      //Set 'predicted_class_selection'.
      hv_PredictedClassSelection = HTuple(hv_GenParamValue[hv_GenParamIndex]);
    }
    else if (0 != (int(HTuple(hv_GenParamName[hv_GenParamIndex])==HTuple("global_selection"))))
    {
      //Set 'global_selection'.
      hv_GlobalSelection = HTuple(hv_GenParamValue[hv_GenParamIndex]);
    }
    else if (0 != (int(HTuple(hv_GenParamName[hv_GenParamIndex])==HTuple("display_images"))))
    {
      //Set 'display_images'.
      hv_DisplayImages = HTuple(hv_GenParamValue[hv_GenParamIndex]);
    }
    else if (0 != (int(HTuple(hv_GenParamName[hv_GenParamIndex])==HTuple("display_buttons"))))
    {
      //Set 'display_buttons'.
      hv_DisplayButtons = HTuple(hv_GenParamValue[hv_GenParamIndex]);
    }
    else
    {
      throw HException(("Unknown generic parameter: '"+HTuple(hv_GenParamName[hv_GenParamIndex]))+"'");
    }
  }
  }
  //
  //Filter data according to LabelSelection.
  if (0 != (int(hv_LabelSelection!=HTuple("all"))))
  {
    hv_Mask = hv_GroundTruthLabels.TupleEqualElem(hv_LabelSelection);
    if (0 != (int((hv_Mask.TupleSum())==0)))
    {
      throw HException(("LabelSelection '"+hv_LabelSelection)+"' not found in GroundTruthLabels.");
    }
    hv_ImageFiles = hv_ImageFiles.TupleSelectMask(hv_Mask);
    hv_GroundTruthLabels = hv_GroundTruthLabels.TupleSelectMask(hv_Mask);
    hv_PredictedClasses = hv_PredictedClasses.TupleSelectMask(hv_Mask);
  }
  //
  //Filter data according to PredictedClassSelection.
  if (0 != (int(hv_PredictedClassSelection!=HTuple("all"))))
  {
    hv_Mask = hv_PredictedClasses.TupleEqualElem(hv_PredictedClassSelection);
    if (0 != (int((hv_Mask.TupleSum())==0)))
    {
      throw HException(("PredictedClassSelection '"+hv_PredictedClassSelection)+"' not found in PredictedClasses.");
    }
    hv_ImageFiles = hv_ImageFiles.TupleSelectMask(hv_Mask);
    hv_GroundTruthLabels = hv_GroundTruthLabels.TupleSelectMask(hv_Mask);
    hv_PredictedClasses = hv_PredictedClasses.TupleSelectMask(hv_Mask);
  }
  //
  //Filter data according to GlobalSelection.
  if (0 != (int(hv_GlobalSelection!=HTuple("all"))))
  {
    hv_Mask = hv_GroundTruthLabels.TupleEqualElem(hv_PredictedClasses);
    if (0 != (int(hv_GlobalSelection==HTuple("erroneously_classified"))))
    {
      //Flip the mask.
      hv_Mask = (hv_Mask-1).TupleAbs();
    }
    hv_ImageFiles = hv_ImageFiles.TupleSelectMask(hv_Mask);
    hv_GroundTruthLabels = hv_GroundTruthLabels.TupleSelectMask(hv_Mask);
    hv_PredictedClasses = hv_PredictedClasses.TupleSelectMask(hv_Mask);
  }
  //
  if (0 != (int(hv_DisplayImages==HTuple("true"))))
  {
    //Loop over the images.
    GenEmptyObj(&(*ho_Images));
    {
    HTuple end_val76 = (hv_ImageFiles.TupleLength())-1;
    HTuple step_val76 = 1;
    for (hv_ImageIndex=0; hv_ImageIndex.Continue(end_val76, step_val76); hv_ImageIndex += step_val76)
    {
      //
      //Concatenate selected images.
      ReadImage(&ho_Image, HTuple(hv_ImageFiles[hv_ImageIndex]));
      ConcatObj((*ho_Images), ho_Image, &(*ho_Images));
      //
      hv_Label = HTuple(hv_GroundTruthLabels[hv_ImageIndex]);
      hv_PredictedClass = HTuple(hv_PredictedClasses[hv_ImageIndex]);
      //
      hv_Text = (("Image "+(hv_ImageIndex+1))+"/")+(hv_ImageFiles.TupleLength());
      hv_Text[1] = "Label: "+hv_Label;
      hv_Text[2] = "Predicted Class: "+hv_PredictedClass;
      if (0 != (int(hv_Label==hv_PredictedClass)))
      {
        hv_Color = "forest green";
      }
      else
      {
        hv_Color = "red";
      }
      //
      //Display the image.
      dev_resize_window_fit_image(ho_Image, 0, 0, -1, -1);
      if (HDevWindowStack::IsOpen())
        DispObj(ho_Image, HDevWindowStack::GetActive());
      if (HDevWindowStack::IsOpen())
        DispText(HDevWindowStack::GetActive(),hv_Text, "window", "top", "left", (HTuple("black").Append("black")).TupleConcat(hv_Color), 
            "box_color", "#ffffffaa");
      if (0 != (int(hv_DisplayButtons==HTuple("false"))))
      {
        if (HDevWindowStack::IsOpen())
          DispText(HDevWindowStack::GetActive(),"Press Run (F5) to continue", "window", 
              "bottom", "right", "black", "box_color", "#ffffffaa");
        // stop(...); only in hdevelop
      }
      else
      {
        GetWindowExtents(hv_WindowHandle, &hv_Row, &hv_Column, &hv_WindowWidth, &hv_WindowHeight);
        hv_ButtonLabel.Clear();
        hv_ButtonLabel[0] = "Next image";
        hv_ButtonLabel[1] = "Continue";
        GetStringExtents(hv_WindowHandle, HTuple(hv_ButtonLabel[0]), &hv_Ascent, 
            &hv_Descent, &hv_TextWidth, &hv_TextHeight);
        hv_ButtonRow.Clear();
        hv_ButtonRow.Append((hv_WindowHeight-hv_TextHeight)-20);
        hv_ButtonRow.Append((hv_WindowHeight-hv_TextHeight)-20);
        hv_ButtonColumn.Clear();
        hv_ButtonColumn[0] = 20;
        hv_ButtonColumn.Append((hv_WindowWidth-hv_TextWidth)-40);
        hv_ColorLabels = "black";
        hv_Color.Clear();
        hv_Color[0] = "#fce9d4";
        hv_Color[1] = "#fce9d4";
        hv_HighlightColor = "#f28d26";
        dev_disp_button(hv_ButtonLabel, hv_ButtonRow, hv_ButtonColumn, hv_TextWidth*1.2, 
            hv_TextHeight*1.2, hv_ColorLabels, hv_Color, hv_HighlightColor, hv_WindowHandle, 
            &hv_SelectedButton);
        if (0 != (int(hv_SelectedButton==0)))
        {
          WaitSeconds(0.1);
        }
        else
        {
          return;
        }
      }
    }
    }
  }
  else
  {
    ReadImage(&(*ho_Images), hv_ImageFiles);
  }
  return;
}

// Chapter: Deep Learning / Object Detection and Instance Segmentation
// Short Description: Get the 'image_id' for each annotation for a given ThreadIndex. 
void get_dl_dataset_from_coco_annotation_image_id (HTuple hv_AnnotationList, HTuple hv_AnnotationKeys, 
    HTuple hv_NumKeysPerThread, HTuple hv_UniqueIndex, HTuple *hv_AnnotImageIDsOutput, 
    HTuple *hv_Exception)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_Index, hv_Annotation, hv_ImageIDAnnot;
  HTuple  hv_ExceptionAnnot;

  //This procedure gets the 'image_id' for each annotation for a given thread.
  TupleGenConst(hv_NumKeysPerThread, -1, &(*hv_AnnotImageIDsOutput));
  (*hv_Exception) = HTuple();
  //
  //Get the 'image_id' for each annotation for looking it up later.
  {
  HTuple end_val5 = hv_NumKeysPerThread-1;
  HTuple step_val5 = 1;
  for (hv_Index=0; hv_Index.Continue(end_val5, step_val5); hv_Index += step_val5)
  {
    try
    {
      GetDictTuple(hv_AnnotationList, HTuple(hv_AnnotationKeys[hv_Index]), &hv_Annotation);
      GetDictTuple(hv_Annotation, "image_id", &hv_ImageIDAnnot);
    }
    // catch (ExceptionAnnot) 
    catch (HException &HDevExpDefaultException)
    {
      HDevExpDefaultException.ToHTuple(&hv_ExceptionAnnot);
      (*hv_Exception) = ("COCO annotation number "+hv_UniqueIndex)+" does not contain image_id.";
      return;
    }
    (*hv_AnnotImageIDsOutput)[hv_Index] = hv_ImageIDAnnot;
    hv_UniqueIndex += 1;
  }
  }
  //
  return;
}

// Chapter: Deep Learning / Model
// Short Description: Return the intended optimization method based on given evaluation key(s). 
void get_dl_evaluation_optimization_method (HTuple hv_EvaluationKeys, HTuple *hv_OptimizationMethod)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_Matches, hv_Length, hv_ErrorKeys, hv_Sum;

  //Only evaluation keys which contain the name 'error' are minimization problems.
  TupleRegexpMatch(hv_EvaluationKeys, "error", &hv_Matches);
  TupleStrlen(hv_Matches, &hv_Length);
  TupleGreaterElem(hv_Length, 0, &hv_ErrorKeys);
  TupleSum(hv_ErrorKeys, &hv_Sum);
  if (0 != (int(hv_Sum==(hv_ErrorKeys.TupleLength()))))
  {
    (*hv_OptimizationMethod) = "min";
  }
  else if (0 != (int(hv_Sum==0)))
  {
    (*hv_OptimizationMethod) = "max";
  }
  else
  {
    (*hv_OptimizationMethod) = "mixed";
  }
  return;
}

// Chapter: Deep Learning / Model
// Short Description: Get an image of a sample with a certain key. 
void get_dl_sample_image (HObject *ho_Image, HTuple hv_SampleKeys, HTuple hv_DLSample, 
    HTuple hv_Key)
{

  //This procedure returns an image with key Key of a sample.
  //
  if (0 != (int((hv_SampleKeys.TupleFind(hv_Key))!=-1)))
  {
    GetDictObject(&(*ho_Image), hv_DLSample, hv_Key);
  }
  else
  {
    throw HException(("Image with key '"+hv_Key)+"' could not be found in DLSample.");
  }
  return;
}

// Chapter: OCR / Deep OCR
// Short Description: Determine the ocr type of the sample based on the sample structure. 
void get_dl_sample_ocr_type (HTuple hv_DLSample, HTuple *hv_OCRType)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_WordExists, hv_BoundingBoxExists;

  (*hv_OCRType) = "non_ocr";
  GetDictParam(hv_DLSample, "key_exists", "word", &hv_WordExists);
  if (0 != hv_WordExists)
  {
    GetDictParam(hv_DLSample, "key_exists", "bbox_label_id", &hv_BoundingBoxExists);
    if (0 != hv_BoundingBoxExists)
    {
      (*hv_OCRType) = "ocr_detection";
    }
    else
    {
      (*hv_OCRType) = "ocr_recognition";
    }
  }
  return;
}

// Chapter: 3D Object Model / Transformations
void get_extent_by_axis (HTuple hv_OM3D, HTuple hv_XExtent, HTuple hv_YExtent, HTuple hv_ZExtent, 
    HTuple *hv_XExtentOut, HTuple *hv_YExtentOut, HTuple *hv_ZExtentOut)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_BB, hv_Index;

  (*hv_XExtentOut) = hv_XExtent;
  (*hv_YExtentOut) = hv_YExtent;
  (*hv_ZExtentOut) = hv_ZExtent;
  GetObjectModel3dParams(hv_OM3D, "bounding_box1", &hv_BB);
  {
  HTuple end_val4 = ((hv_BB.TupleLength())/6)-1;
  HTuple step_val4 = 1;
  for (hv_Index=0; hv_Index.Continue(end_val4, step_val4); hv_Index += step_val4)
  {
    (*hv_XExtentOut) = ((*hv_XExtentOut).TupleConcat(HTuple(hv_BB[hv_Index*6]))).TupleConcat(HTuple(hv_BB[(hv_Index*6)+3]));
    (*hv_YExtentOut) = ((*hv_YExtentOut).TupleConcat(HTuple(hv_BB[(hv_Index*6)+1]))).TupleConcat(HTuple(hv_BB[(hv_Index*6)+4]));
    (*hv_ZExtentOut) = ((*hv_ZExtentOut).TupleConcat(HTuple(hv_BB[(hv_Index*6)+2]))).TupleConcat(HTuple(hv_BB[(hv_Index*6)+5]));
  }
  }
  return;
}

