// Chapter: Tuple / Selection
void get_find_parameter (HTuple hv_GenParamNames, HTuple hv_GenParamValues, HTuple hv_ParamName, 
    HTuple hv_DefaultValue, HTuple *hv_ParamValue)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_Idx;

  (*hv_ParamValue) = hv_DefaultValue;
  TupleFind(hv_GenParamNames, hv_ParamName, &hv_Idx);
  if (0 != (HTuple(int(hv_Idx!=-1)).TupleAnd(int(hv_Idx!=HTuple()))))
  {
    (*hv_ParamValue) = HTuple(hv_GenParamValues[hv_Idx]);
  }
  return;
}

// Chapter: 3D Matching / Surface-Based
void get_find_surface_model_param (HTuple hv_ParamName, HTuple hv_DefaultValue, HTuple hv_GenParamNames, 
    HTuple hv_GenParamValues, HTuple hv_ConvertBoolToInt, HTuple *hv_ParamValue)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_ValidParamNames, hv_Pos;

  if (true)
  {
    //Debug Check: Is the parameter valid?
    GetParamInfo("find_surface_model_image", "GenParamName", "value_list", &hv_ValidParamNames);
    TupleFind(hv_ValidParamNames, hv_ParamName, &hv_Pos);
    if (0 != (HTuple(int(hv_Pos==-1)).TupleOr(int(hv_Pos==HTuple()))))
    {
      throw HException("Invalid parameter name: "+hv_ParamName);
    }
  }

  hv_Pos = hv_GenParamNames.TupleFind(hv_ParamName);
  if (0 != (HTuple(int(hv_Pos!=HTuple())).TupleAnd(int(hv_Pos!=-1))))
  {
    //If the parameter is set multiple times, use the last.
    (*hv_ParamValue) = HTuple(hv_GenParamValues[HTuple(hv_Pos[(hv_Pos.TupleLength())-1])]);
  }
  else
  {
    (*hv_ParamValue) = hv_DefaultValue;
  }

  if (0 != hv_ConvertBoolToInt)
  {
    if (0 != (int((*hv_ParamValue)==HTuple("true"))))
    {
      (*hv_ParamValue) = 1;
    }
    if (0 != (int((*hv_ParamValue)==HTuple("false"))))
    {
      (*hv_ParamValue) = 0;
    }
  }

  return;
}

// Chapter: Deep Learning / Model
// Short Description: Get a parameter value from GenParamValue with the name RequestedGenParamName. 
void get_genparam_single_value (HTuple hv_GenParamName, HTuple hv_GenParamValue, 
    HTuple hv_RequestedGenParamName, HTuple *hv_FoundGenParamValue)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_Indices;

  //
  //Get a parameter value from GenParamValue with the name RequestedGenParamName,
  //which is allowed to appear only once in GenParamName.
  //
  //Set a default in case no value is provided.
  (*hv_FoundGenParamValue) = HTuple();
  //Set user provided values, if provided.
  hv_Indices = hv_GenParamName.TupleFind(hv_RequestedGenParamName);
  if (0 != (HTuple(int((hv_Indices.TupleLength())==1)).TupleAnd(int(hv_Indices!=-1))))
  {
    (*hv_FoundGenParamValue) = HTuple(hv_GenParamValue[hv_Indices]);
  }
  else if (0 != (int((hv_Indices.TupleLength())>1)))
  {
    //Throw an error if more than one value was provided for RequestedGenParamName.
    throw HException(("Only a single parameter dictionary or none is allowed for '"+hv_RequestedGenParamName)+"'.");
  }
  return;
}

// Chapter: 3D Matching / 3D Gripping Point Detection
// Short Description: Extract gripping points from a dictionary. 
void get_gripping_points_from_dict (HTuple hv_DLResult, HTuple *hv_Rows, HTuple *hv_Columns)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_KeyExists, hv_GrippingPoints, hv_NumberOfResults;
  HTuple  hv_IndexGrippingPointsPoint, hv_GrippingPointCoordDict;

  if (0 != (int(hv_DLResult==HTuple())))
  {
    throw HException("DLResult dict is empty.");
  }
  GetDictParam(hv_DLResult, "key_exists", "gripping_points", &hv_KeyExists);
  if (0 != hv_KeyExists)
  {
    GetDictTuple(hv_DLResult, "gripping_points", &hv_GrippingPoints);
  }
  else
  {
    throw HException("Result data could not be found in DLResult.");
  }
  hv_NumberOfResults = hv_GrippingPoints.TupleLength();
  TupleGenConst(hv_NumberOfResults, 0, &(*hv_Rows));
  TupleGenConst(hv_NumberOfResults, 0, &(*hv_Columns));
  {
  HTuple end_val12 = (hv_GrippingPoints.TupleLength())-1;
  HTuple step_val12 = 1;
  for (hv_IndexGrippingPointsPoint=0; hv_IndexGrippingPointsPoint.Continue(end_val12, step_val12); hv_IndexGrippingPointsPoint += step_val12)
  {
    hv_GrippingPointCoordDict = HTuple(hv_GrippingPoints[hv_IndexGrippingPointsPoint]);
    (*hv_Rows)[hv_IndexGrippingPointsPoint] = hv_GrippingPointCoordDict.TupleGetDictTuple("row");
    (*hv_Columns)[hv_IndexGrippingPointsPoint] = hv_GrippingPointCoordDict.TupleGetDictTuple("column");
  }
  }
  return;
}

// Chapter: Matching / Shape-Based
// Short Description: Calculate the transformation matrix for results of Shape-Based Matching. 
void get_hom_mat2d_from_matching_result (HTuple hv_Row, HTuple hv_Column, HTuple hv_Angle, 
    HTuple hv_ScaleR, HTuple hv_ScaleC, HTuple *hv_HomMat2D)
{

  // Local control variables
  HTuple  hv_HomMat2DIdentity, hv_HomMat2DScale;
  HTuple  hv_HomMat2DRotate;

  //This procedure calculates the transformation matrix for the model contours
  //from the results of Shape-Based Matching.
  //
  HomMat2dIdentity(&hv_HomMat2DIdentity);
  HomMat2dScale(hv_HomMat2DIdentity, hv_ScaleR, hv_ScaleC, 0, 0, &hv_HomMat2DScale);
  HomMat2dRotate(hv_HomMat2DScale, hv_Angle, 0, 0, &hv_HomMat2DRotate);
  HomMat2dTranslate(hv_HomMat2DRotate, hv_Row, hv_Column, &(*hv_HomMat2D));
  return;


}

// Chapter: System / Information
// Short Description: Returns the paths of all HALCON image directories. 
void get_image_dir (HTuple *hv_ImageDir)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_OperatingSystem, hv_IsWindows, hv_Separator;

  //This procedure returns the directories that will be
  //searched by HALCON when reading image files (e.g. with
  //read_image or read_sequence) as a tuple.
  GetSystem("image_dir", &(*hv_ImageDir));
  //Retrieve the Operating System.
  GetSystem("operating_system", &hv_OperatingSystem);
  hv_IsWindows = int((hv_OperatingSystem.TupleSubstr(0,2))==HTuple("Win"));
  if (0 != hv_IsWindows)
  {
    hv_Separator = ";";
  }
  else
  {
    hv_Separator = ":";
  }
  //Split the string returned by get_system into a tuple.
  TupleSplit((*hv_ImageDir), hv_Separator, &(*hv_ImageDir));
  return;
}

// Chapter: File / Misc
// Short Description: Find a matching file in a list of files for a given file and return the index. 
void get_matching_file_index (HTuple hv_FileNames, HTuple hv_FileDirectories, HTuple hv_FileNameToMatch, 
    HTuple hv_FileDirectoryToMatch, HTuple hv_FileExtensionToMatch, HTuple *hv_FileMatchIndex)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_MatchIndex, hv_Match, hv_PathMatchIndex;
  HTuple  hv_FilePath;

  //
  //This procedure tries to find for a given file another file
  //from a list that has a matching name.
  //
  (*hv_FileMatchIndex) = -1;
  //
  //1: Try to match identical file names.
  hv_MatchIndex = hv_FileNames.TupleFind(hv_FileNameToMatch);
  if (0 != (HTuple(int((hv_MatchIndex.TupleLength())==1)).TupleAnd(int(hv_MatchIndex>=0))))
  {
    //Exactly one match was found.
    (*hv_FileMatchIndex) = hv_MatchIndex;
  }
  else
  {
    //2: Try to match file name subparts.
    TupleRegexpMatch(hv_FileNames, hv_FileNameToMatch, &hv_Match);
    TupleFind(hv_Match.TupleNotEqualElem(""), 1, &hv_MatchIndex);
    if (0 != (HTuple(int(hv_MatchIndex>=0)).TupleAnd(int((hv_MatchIndex.TupleLength())==1))))
    {
      //Exactly one match was found.
      (*hv_FileMatchIndex) = hv_MatchIndex;
    }
    else if (0 != (int((hv_MatchIndex.TupleLength())>1)))
    {
      //3: There are several name matches.
      //Check if one of these matches has a common relative
      //path.
      hv_PathMatchIndex = HTuple(hv_FileDirectories[hv_MatchIndex]).TupleFind(hv_FileDirectoryToMatch);
      if (0 != (HTuple(int(hv_PathMatchIndex>=0)).TupleAnd(int((hv_PathMatchIndex.TupleLength())==1))))
      {
        //Exactly one file matches path and name.
        (*hv_FileMatchIndex) = HTuple(hv_MatchIndex[hv_PathMatchIndex]);
      }
      else if (0 != (int((hv_PathMatchIndex.TupleLength())>1)))
      {
        //There should be only one file in the list matching
        //the given file.
        hv_FilePath = ((hv_FileDirectoryToMatch+hv_FileNameToMatch)+".")+hv_FileExtensionToMatch;
        throw HException("Multiple matching files for file "+hv_FilePath);
      }
    }
  }
  //
  return;
}

// Chapter: 3D Matching / Surface-Based
void get_max_min_amplitude (HTuple hv_BoxInformation, HTuple *hv_MaxMinAmplitude)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_GenParamDict, hv_InputLengths, hv_SideLengths;
  HTuple  hv_FactorConst;

  //Get input lengths.
  GetDictTuple(hv_BoxInformation, "gen_param", &hv_GenParamDict);
  GetDictTuple(hv_GenParamDict, "lengths", &hv_InputLengths);
  //Squaring avoids negative inputs to sqrt.
  hv_SideLengths.Clear();
  hv_SideLengths.Append(((HTuple(hv_InputLengths[0]).TuplePow(2))+(HTuple(hv_InputLengths[3]).TuplePow(2))).TupleSqrt());
  hv_SideLengths.Append(((HTuple(hv_InputLengths[3]).TuplePow(2))+(HTuple(hv_InputLengths[5]).TuplePow(2))).TupleSqrt());
  hv_SideLengths.Append(((HTuple(hv_InputLengths[0]).TuplePow(2))+(HTuple(hv_InputLengths[5]).TuplePow(2))).TupleSqrt());
  //
  hv_FactorConst = 3;
  if (0 != (int(HTuple(hv_InputLengths[5])>0)))
  {
    (*hv_MaxMinAmplitude) = hv_FactorConst*(hv_SideLengths.TupleMin());
  }
  else
  {
    (*hv_MaxMinAmplitude) = hv_FactorConst*HTuple(hv_SideLengths[0]);
  }
  return;
}

// Chapter: 3D Matching / Surface-Based
void get_min_amplitude (HTuple hv_BoxInformation, HTuple *hv_MinAmplitude)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_GenParamDict, hv_InputLengths, hv_PositiveIndices;
  HTuple  hv_PositiveLengths;

  //Get input lengths.
  GetDictTuple(hv_BoxInformation, "gen_param", &hv_GenParamDict);
  GetDictTuple(hv_GenParamDict, "lengths", &hv_InputLengths);
  //Ignore -1 lengths
  hv_PositiveIndices = (hv_InputLengths.TupleGreaterElem(0)).TupleFind(1);
  hv_PositiveLengths = HTuple(hv_InputLengths[hv_PositiveIndices]);
  //
  (*hv_MinAmplitude) = hv_PositiveLengths.TupleMin();
  return;
}

// Chapter: Graphics / Mouse
void get_mouse_info (HTuple hv_WindowHandle, HTuple hv_MessageQueue, HTuple hv_Timeout, 
    HTuple *hv_Row, HTuple *hv_Column, HTuple *hv_Button)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_MessageHandle, hv_Exception, hv_H_ERR_TIMEOUT;
  HTuple  hv_MessageType;

  //Initialize as "no event"
  (*hv_Row) = -1;
  (*hv_Column) = -1;
  (*hv_Button) = -1;
  //
  if (0 != (int(hv_MessageQueue==HTuple())))
  {
    GetMpositionSubPix(hv_WindowHandle, &(*hv_Row), &(*hv_Column), &(*hv_Button));
  }
  else
  {
    //Queue-based visualization
    if (0 != (int(hv_Timeout==HTuple())))
    {
      DequeueMessage(HTuple(hv_MessageQueue[0]), HTuple(), HTuple(), &hv_MessageHandle);
    }
    else
    {
      try
      {
        DequeueMessage(HTuple(hv_MessageQueue[0]), "timeout", hv_Timeout, &hv_MessageHandle);
      }
      // catch (Exception) 
      catch (HException &HDevExpDefaultException)
      {
        HDevExpDefaultException.ToHTuple(&hv_Exception);
        hv_H_ERR_TIMEOUT = 9400;
        if (0 != (int(HTuple(hv_Exception[0])==hv_H_ERR_TIMEOUT)))
        {
          return;
        }
        else
        {
          throw HException(hv_Exception);
        }
      }
    }
    GetMessageTuple(hv_MessageHandle, "type", &hv_MessageType);
    if (0 != (int(hv_MessageType==HTuple("mouse_event"))))
    {
      GetMessageTuple(hv_MessageHandle, "mouse_row", &(*hv_Row));
      GetMessageTuple(hv_MessageHandle, "mouse_col", &(*hv_Column));
      GetMessageTuple(hv_MessageHandle, "mouse_button", &(*hv_Button));
      ClearMessage(hv_MessageHandle);
    }
    else
    {
      ClearMessage(hv_MessageHandle);
      throw HException("Unknown or unexpected message type: "+hv_MessageType);
    }
  }

  //Normalize the button
  if (0 != (int((*hv_Button)==HTuple())))
  {
    (*hv_Button) = 0;
  }
  return;
}

// Chapter: Calibration / Hand-Eye
// Short Description: Get the coordinates of the central mark of the closest finder pattern. 
void get_nearest_finder_pattern_coordinates (HObject ho_CalibPlateImage, HTuple hv_RowNearFinderPattern, 
    HTuple hv_ColumNearFinderPattern, HTuple hv_CalibObjectData, HTuple *hv_RowFinderPattern, 
    HTuple *hv_ColumnFinderPattern)
{

  // Local iconic variables
  HObject  ho_Contours, ho_Region, ho_RegionUnion;

  // Local control variables
  HTuple  hv_CamParam, hv_CalPlateDescr, hv_MarksPerRow;
  HTuple  hv_FinderRow, hv_FinderColumn, hv_CalibDataID, hv_Exception;
  HTuple  hv_Row, hv_Column, hv_Index1, hv_Pose, hv_Area1;
  HTuple  hv_Row2, hv_Column2, hv_RowTmp, hv_ColTmp, hv_Diff;
  HTuple  hv_IndexFinal, hv_RowToApproach1, hv_ColToApproach1;
  HTuple  hv_XCal, hv_YCal, hv_ZCal, hv_XFP, hv_YFP, hv_HomMat3D;
  HTuple  hv_ZFP, hv_X1, hv_Y1, hv_Z1;

  //
  hv_CamParam = hv_CalibObjectData.TupleGetDictTuple("CamParam");
  hv_CalPlateDescr = hv_CalibObjectData.TupleGetDictTuple("CalPlateDescr");
  hv_MarksPerRow = hv_CalibObjectData.TupleGetDictTuple("MarksPerRow");
  hv_FinderRow = hv_CalibObjectData.TupleGetDictTuple("FinderRow");
  hv_FinderColumn = hv_CalibObjectData.TupleGetDictTuple("FinderColumn");
  //
  //Check input.
  //
  //Check image coordinates.
  if (0 != (HTuple(int((hv_RowNearFinderPattern.TupleLength())>1)).TupleOr(int((hv_ColumNearFinderPattern.TupleLength())>1))))
  {
    throw HException("Please specify only one image coordinate.");
  }
  //Check number of marks per row.
  if (0 != (int(hv_MarksPerRow<3)))
  {
    throw HException("At least three marks per row are necessary for a valid finder pattern.");
  }
  //Find calibration plate.
  CreateCalibData("calibration_object", 1, 1, &hv_CalibDataID);
  SetCalibDataCamParam(hv_CalibDataID, 0, HTuple(), hv_CamParam);
  SetCalibDataCalibObject(hv_CalibDataID, 0, hv_CalPlateDescr);
  try
  {
    FindCalibObject(ho_CalibPlateImage, hv_CalibDataID, 0, 0, 0, HTuple(), HTuple());
  }
  // catch (Exception) 
  catch (HException &HDevExpDefaultException)
  {
    HDevExpDefaultException.ToHTuple(&hv_Exception);
    throw HException(HTuple("Calibration plate could not be find, please make sure that at least one finder pattern is visible."));
  }
  GetCalibDataObservPoints(hv_CalibDataID, 0, 0, 0, &hv_Row, &hv_Column, &hv_Index1, 
      &hv_Pose);
  GetCalibDataObservContours(&ho_Contours, hv_CalibDataID, "caltab", 0, 0, 0);
  //Get the finder pattern used to find the calibration plate.
  GenRegionContourXld(ho_Contours, &ho_Region, "filled");
  Union1(ho_Region, &ho_RegionUnion);
  AreaCenter(ho_RegionUnion, &hv_Area1, &hv_Row2, &hv_Column2);
  hv_RowTmp = (hv_Row-hv_Row2).TupleAbs();
  hv_ColTmp = (hv_Column-hv_Column2).TupleAbs();
  hv_Diff = ((hv_RowTmp*hv_RowTmp)+(hv_ColTmp*hv_ColTmp)).TupleSqrt();
  TupleFind(hv_Diff, hv_Diff.TupleMin(), &hv_IndexFinal);
  hv_RowToApproach1 = HTuple(hv_Row[hv_IndexFinal]);
  hv_ColToApproach1 = HTuple(hv_Column[hv_IndexFinal]);
  ClearCalibData(hv_CalibDataID);
  //Get remaining finder pattern.
  //
  //Get finder pattern in world coordinates.
  CaltabPoints(hv_CalPlateDescr, &hv_XCal, &hv_YCal, &hv_ZCal);
  hv_XFP = HTuple(hv_XCal[(hv_FinderRow*hv_MarksPerRow)+hv_FinderColumn]);
  hv_YFP = HTuple(hv_YCal[(hv_FinderRow*hv_MarksPerRow)+hv_FinderColumn]);
  //Get finder pattern in camera coordinates.
  PoseToHomMat3d(hv_Pose, &hv_HomMat3D);
  TupleGenConst(hv_XFP.TupleLength(), 0.0, &hv_ZFP);
  AffineTransPoint3d(hv_HomMat3D, hv_XFP, hv_YFP, hv_ZFP, &hv_X1, &hv_Y1, &hv_Z1);
  //Project into the image.
  Project3dPoint(hv_X1, hv_Y1, hv_Z1, hv_CamParam, &hv_Row, &hv_Column);
  //
  //Get the image coordinates that are the closest ones to the passed ones.
  hv_RowTmp = (hv_Row-hv_RowNearFinderPattern).TupleAbs();
  hv_ColTmp = (hv_Column-hv_ColumNearFinderPattern).TupleAbs();
  hv_Diff = ((hv_RowTmp*hv_RowTmp)+(hv_ColTmp*hv_ColTmp)).TupleSqrt();
  TupleFind(hv_Diff, hv_Diff.TupleMin(), &hv_IndexFinal);
  //Return the image coordinates.
  (*hv_RowFinderPattern) = HTuple(hv_Row[hv_IndexFinal]);
  (*hv_ColumnFinderPattern) = HTuple(hv_Column[hv_IndexFinal]);
  return;
}

// Chapter: Graphics / Window
// Short Description: Get the next window that can be used for visualization. 
void get_next_window (HTuple hv_Font, HTuple hv_FontSize, HTuple hv_ShowBottomDesc, 
    HTuple hv_WidthImage, HTuple hv_HeightImage, HTuple hv_MapColorBarWidth, HTuple hv_ScaleWindows, 
    HTuple hv_ThresholdWidth, HTuple hv_PrevWindowCoordinates, HTuple hv_WindowHandleDict, 
    HTuple hv_WindowHandleKey, HTuple *hv_CurrentWindowHandle, HTuple *hv_WindowImageRatioHeight, 
    HTuple *hv_PrevWindowCoordinatesOut)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_OpenNewWindow, hv_WindowHandles, hv_Value;
  HTuple  hv_Exception, hv_Ascent, hv_Descent, hv__, hv_NumLines;
  HTuple  hv_MarginBottom, hv_WindowImageRatioWidth, hv_SetPartRow2;
  HTuple  hv_SetPartColumn2, hv_MetaInfo;

  //
  //This procedure returns the next window that
  //is used for visualization. If ReuseWindows is true
  //and WindowHandleList is suitable, the window handles
  //that are passed over are used. Else, this procedure
  //opens a new window, either next to the last ones, or
  //in a new row.
  //
  //First, check if the requested window is already available.
  hv_OpenNewWindow = 0;
  try
  {
    GetDictTuple(hv_WindowHandleDict, hv_WindowHandleKey, &hv_WindowHandles);
    (*hv_CurrentWindowHandle) = ((const HTuple&)hv_WindowHandles)[0];
    //Check if window handle is valid.
    try
    {
      GetWindowParam((*hv_CurrentWindowHandle), "flush", &hv_Value);
    }
    // catch (Exception) 
    catch (HException &HDevExpDefaultException)
    {
      HDevExpDefaultException.ToHTuple(&hv_Exception);
      //If there is something wrong with the current window, create a new one.
      hv_OpenNewWindow = 1;
      RemoveDictKey(hv_WindowHandleDict, hv_WindowHandleKey);
    }
  }
  // catch (Exception) 
  catch (HException &HDevExpDefaultException)
  {
    HDevExpDefaultException.ToHTuple(&hv_Exception);
    hv_OpenNewWindow = 1;
  }
  //
  //Get next window.
  if (0 != (hv_OpenNewWindow.TupleNot()))
  {
    //
    //If possible, reuse existing window handles.
    HDevWindowStack::SetActive((*hv_CurrentWindowHandle));
    if (HDevWindowStack::IsOpen())
      ClearWindow(HDevWindowStack::GetActive());
    set_display_font((*hv_CurrentWindowHandle), hv_FontSize, hv_Font, "true", "false");
    //
    //Calculate MarginBottom.
    if (0 != hv_ShowBottomDesc)
    {
      GetStringExtents((*hv_CurrentWindowHandle), "test_string", &hv_Ascent, &hv_Descent, 
          &hv__, &hv__);
      hv_NumLines = hv_ShowBottomDesc;
      hv_MarginBottom = (hv_NumLines*(hv_Ascent+hv_Descent))+(2*12);
    }
    else
    {
      hv_MarginBottom = 0;
    }
    //
    //Get and set meta information for current window.
    update_window_meta_information((*hv_CurrentWindowHandle), hv_WidthImage, hv_HeightImage, 
        0, 0, hv_MapColorBarWidth, hv_MarginBottom, &(*hv_WindowImageRatioHeight), 
        &hv_WindowImageRatioWidth, &hv_SetPartRow2, &hv_SetPartColumn2, &(*hv_PrevWindowCoordinatesOut));
    //
    //Update meta information.
    GetDictTuple(hv_WindowHandleDict, "meta_information", &hv_MetaInfo);
    SetDictTuple(hv_MetaInfo, hv_WindowHandleKey+"_window_image_ratio_height", (*hv_WindowImageRatioHeight));
    SetDictTuple(hv_MetaInfo, hv_WindowHandleKey+"_window_image_ratio_width", hv_WindowImageRatioWidth);
    SetDictTuple(hv_MetaInfo, hv_WindowHandleKey+"_set_part_row2", hv_SetPartRow2);
    SetDictTuple(hv_MetaInfo, hv_WindowHandleKey+"_set_part_column2", hv_SetPartColumn2);
    SetDictTuple(hv_MetaInfo, hv_WindowHandleKey+"_margin_bottom", hv_MarginBottom);
    SetDictTuple(hv_MetaInfo, hv_WindowHandleKey+"_map_color_bar_with", hv_MapColorBarWidth);
    SetDictTuple(hv_MetaInfo, hv_WindowHandleKey+"_window_coordinates", (*hv_PrevWindowCoordinatesOut));
  }
  else
  {
    //
    //Open a new window.
    open_next_window(hv_Font, hv_FontSize, hv_ShowBottomDesc, hv_WidthImage, hv_HeightImage, 
        hv_MapColorBarWidth, hv_ScaleWindows, hv_ThresholdWidth, hv_PrevWindowCoordinates, 
        hv_WindowHandleDict, hv_WindowHandleKey, &(*hv_CurrentWindowHandle), &(*hv_WindowImageRatioHeight), 
        &(*hv_PrevWindowCoordinatesOut));
    SetWindowParam((*hv_CurrentWindowHandle), "flush", "false");
  }
  //
  return;
}

// Chapter: Graphics / Output
// Short Description: Compute the center of all given 3D object models. 
void get_object_models_center (HTuple hv_ObjectModel3DID, HTuple *hv_Center)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_Diameters, hv_Index, hv_Diameter, hv_C;
  HTuple  hv_Exception, hv_MD, hv_Weight, hv_SumW, hv_ObjectModel3DIDSelected;
  HTuple  hv_InvSum;

  //Compute the mean of all model centers (weighted by the diameter of the object models)
  hv_Diameters = HTuple(hv_ObjectModel3DID.TupleLength(),0.0);
  {
  HTuple end_val2 = (hv_ObjectModel3DID.TupleLength())-1;
  HTuple step_val2 = 1;
  for (hv_Index=0; hv_Index.Continue(end_val2, step_val2); hv_Index += step_val2)
  {
    try
    {
      GetObjectModel3dParams(HTuple(hv_ObjectModel3DID[hv_Index]), "diameter_axis_aligned_bounding_box", 
          &hv_Diameter);
      GetObjectModel3dParams(HTuple(hv_ObjectModel3DID[hv_Index]), "center", &hv_C);
      hv_Diameters[hv_Index] = hv_Diameter;
    }
    // catch (Exception) 
    catch (HException &HDevExpDefaultException)
    {
      HDevExpDefaultException.ToHTuple(&hv_Exception);
      //Object model is empty, has no center etc. -> ignore it by leaving its diameter at zero
    }
  }
  }

  if (0 != (int((hv_Diameters.TupleSum())>0)))
  {
    //Normalize Diameter to use it as weights for a weighted mean of the individual centers
    hv_MD = (hv_Diameters.TupleSelectMask(hv_Diameters.TupleGreaterElem(0))).TupleMean();
    if (0 != (int(hv_MD>1e-10)))
    {
      hv_Weight = hv_Diameters/hv_MD;
    }
    else
    {
      hv_Weight = hv_Diameters;
    }
    hv_SumW = hv_Weight.TupleSum();
    if (0 != (int(hv_SumW<1e-10)))
    {
      hv_Weight = HTuple(hv_Weight.TupleLength(),1.0);
      hv_SumW = hv_Weight.TupleSum();
    }
    (*hv_Center).Clear();
    (*hv_Center)[0] = 0;
    (*hv_Center)[1] = 0;
    (*hv_Center)[2] = 0;
    {
    HTuple end_val26 = (hv_ObjectModel3DID.TupleLength())-1;
    HTuple step_val26 = 1;
    for (hv_Index=0; hv_Index.Continue(end_val26, step_val26); hv_Index += step_val26)
    {
      if (0 != (int(HTuple(hv_Diameters[hv_Index])>0)))
      {
        hv_ObjectModel3DIDSelected = HTuple(hv_ObjectModel3DID[hv_Index]);
        GetObjectModel3dParams(hv_ObjectModel3DIDSelected, "center", &hv_C);
        (*hv_Center)[0] = HTuple((*hv_Center)[0])+(HTuple(hv_C[0])*HTuple(hv_Weight[hv_Index]));
        (*hv_Center)[1] = HTuple((*hv_Center)[1])+(HTuple(hv_C[1])*HTuple(hv_Weight[hv_Index]));
        (*hv_Center)[2] = HTuple((*hv_Center)[2])+(HTuple(hv_C[2])*HTuple(hv_Weight[hv_Index]));
      }
    }
    }
    hv_InvSum = 1.0/hv_SumW;
    (*hv_Center)[0] = HTuple((*hv_Center)[0])*hv_InvSum;
    (*hv_Center)[1] = HTuple((*hv_Center)[1])*hv_InvSum;
    (*hv_Center)[2] = HTuple((*hv_Center)[2])*hv_InvSum;
  }
  else
  {
    (*hv_Center) = HTuple();
  }
  return;
}

// Chapter: Deep Learning / Model
// Short Description: This procedure determines the common directory part CommonDir between ImageDir and ImageDirectories and places the relative part from ImageDirectories into ImageDirectoriesRelative. 
void get_relative_image_directories (HTuple hv_ImageDir, HTuple hv_ImageDirectories, 
    HTuple *hv_CommonDir, HTuple *hv_ImageDirectoriesRelative)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_Slash, hv_ToFind, hv_D, hv_ImageDirectory;
  HTuple  hv_String, hv_ToFindFixed, hv_ToFindAddPrefix, hv_ToFindAddSuffix;
  HTuple  hv_StringFixed, hv_StringAddPrefix, hv_StringAddSuffix;
  HTuple  hv_PositionFixed, hv_Position, hv_CommonLastPosition;
  HTuple  hv_ImageDirectoryLen, hv_ImageDirectoriesRelativeLen;

  //This procedure determines the common directory part CommonDir
  //between ImageDir and ImageDirectories and places the relative
  //part from ImageDirectories into ImageDirectoriesRelative.
  //For multiple occurrences of ImageDir in ImageDirectories, the
  //first match determines the common directory part.
  //
  //Check inputs.
  if (0 != (int((hv_ImageDir.TupleLength())!=1)))
  {
    throw HException("Invalid size of input parameter ImageDir.");
  }
  if (0 != (int((hv_ImageDirectories.TupleLength())<1)))
  {
    throw HException("Invalid size of input parameter ImageDirectories.");
  }
  //
  //Determine the common directory part.
  (*hv_CommonDir) = "";
  hv_Slash = "/";
  hv_ToFind = hv_ImageDir;
  {
  HTuple end_val18 = (hv_ImageDirectories.TupleLength())-1;
  HTuple step_val18 = 1;
  for (hv_D=0; hv_D.Continue(end_val18, step_val18); hv_D += step_val18)
  {
    hv_ImageDirectory = HTuple(hv_ImageDirectories[hv_D]);
    hv_String = hv_ImageDirectory;
    //
    //Grant slash at the beginning and end to make the search robust.
    hv_ToFindFixed = hv_ToFind;
    hv_ToFindAddPrefix = int((hv_ToFind.TupleStrBitSelect(0))!=hv_Slash);
    hv_ToFindAddSuffix = int((hv_ToFind.TupleStrBitSelect((hv_ToFind.TupleStrlen())-1))!=hv_Slash);
    if (0 != hv_ToFindAddPrefix)
    {
      hv_ToFindFixed = hv_Slash+hv_ToFindFixed;
    }
    if (0 != hv_ToFindAddSuffix)
    {
      hv_ToFindFixed += hv_Slash;
    }
    //
    hv_StringFixed = hv_String;
    if (0 != (int(hv_String!=HTuple(""))))
    {
      hv_StringAddPrefix = int((hv_String.TupleStrBitSelect(0))!=hv_Slash);
      hv_StringAddSuffix = int((hv_String.TupleStrBitSelect((hv_String.TupleStrlen())-1))!=hv_Slash);
    }
    else
    {
      hv_StringAddPrefix = 1;
      hv_StringAddSuffix = 1;
    }
    if (0 != hv_StringAddPrefix)
    {
      hv_StringFixed = hv_Slash+hv_StringFixed;
    }
    if (0 != hv_StringAddSuffix)
    {
      hv_StringFixed += hv_Slash;
    }
    //
    //Determine the common directory part.
    hv_PositionFixed = hv_StringFixed.TupleStrstr(hv_ToFindFixed);
    if (0 != (int(hv_PositionFixed<0)))
    {
      //No common directory part.
      (*hv_CommonDir) = "";
      (*hv_ImageDirectoriesRelative) = hv_ImageDirectories;
      return;
    }
    hv_Position = (hv_PositionFixed-hv_StringAddPrefix)+hv_ToFindAddPrefix;
    //
    hv_CommonLastPosition = ((hv_Position+(hv_ToFind.TupleStrlen()))-1).TupleMin2((hv_ImageDirectory.TupleStrlen())-1);
    (*hv_CommonDir) = hv_ImageDirectory.TupleSubstr(0,hv_CommonLastPosition);
    hv_ToFind = (*hv_CommonDir);
  }
  }
  //
  //Remove the common directory part from the image directories.
  (*hv_ImageDirectoriesRelative) = HTuple(hv_ImageDirectories.TupleLength(),"");
  {
  HTuple end_val65 = (hv_ImageDirectories.TupleLength())-1;
  HTuple step_val65 = 1;
  for (hv_D=0; hv_D.Continue(end_val65, step_val65); hv_D += step_val65)
  {
    hv_ImageDirectory = HTuple(hv_ImageDirectories[hv_D]);
    hv_ImageDirectoryLen = hv_ImageDirectory.TupleStrlen();
    if (0 != (int(hv_CommonLastPosition<(hv_ImageDirectoryLen-1))))
    {
      (*hv_ImageDirectoriesRelative)[hv_D] = hv_ImageDirectory.TupleSubstr(hv_CommonLastPosition+1,hv_ImageDirectoryLen-1);
      //
      //Remove leading slash if any from relative directories.
      if (0 != (int((HTuple((*hv_ImageDirectoriesRelative)[hv_D]).TupleStrBitSelect(0))==hv_Slash)))
      {
        hv_ImageDirectoriesRelativeLen = HTuple((*hv_ImageDirectoriesRelative)[hv_D]).TupleStrlen();
        if (0 != (int(hv_ImageDirectoriesRelativeLen>1)))
        {
          (*hv_ImageDirectoriesRelative)[hv_D] = HTuple((*hv_ImageDirectoriesRelative)[hv_D]).TupleSubstr(1,hv_ImageDirectoriesRelativeLen-1);
        }
        else
        {
          (*hv_ImageDirectoriesRelative)[hv_D] = "";
        }
      }
    }
  }
  }
  //
  return;
}

// Chapter: Deep Learning / Model
// Short Description: Return all pixel measures from a specified list of measures. 
void get_requested_pixel_measures (HTuple hv_Measures, HTuple hv_EvaluationType, 
    HTuple *hv_PixelMeasures)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_ValidMeasures, hv_M;

  //
  //This helper procedure returns for a given list of
  //requested measures all pixel measures for the specified
  //evaluation type.
  //
  (*hv_PixelMeasures) = HTuple();
  get_valid_pixel_measures(hv_EvaluationType, &hv_ValidMeasures);
  //
  {
  HTuple end_val8 = (hv_Measures.TupleLength())-1;
  HTuple step_val8 = 1;
  for (hv_M=0; hv_M.Continue(end_val8, step_val8); hv_M += step_val8)
  {
    if (0 != (int(HTuple(hv_Measures[hv_M])==HTuple("all"))))
    {
      (*hv_PixelMeasures) = (*hv_PixelMeasures).TupleConcat(hv_ValidMeasures);
    }
    else if (0 != (int((hv_ValidMeasures.TupleFind(HTuple(hv_Measures[hv_M])))!=-1)))
    {
      (*hv_PixelMeasures) = (*hv_PixelMeasures).TupleConcat(HTuple(hv_Measures[hv_M]));
    }
  }
  }
  //
  return;
}

// Chapter: Transformations / Misc
// Short Description: Calculate the touching point in tool coordinates. 
void get_robot_touching_point_in_tool_coordinates (HTupleVector/*{eTupleVector,Dim=1}*/ hvec_ToolInBasePosesTouchingPoint, 
    HTuple *hv_RobotTouchingPointInToolCoordinates)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_LHS, hv_RHS, hv_HomMat3D0, hv_Mat0;
  HTuple  hv_MatRot0, hv_MatTrans0, hv_Index, hv_HomMat3D;
  HTuple  hv_Mat, hv_MatRot, hv_MatTrans, hv_MatrixResultID;
  HTuple  hv_DetailedErrors, hv_MinDiffToIdentity, hv_MinCosAngle;
  HTuple  hv_Index1, hv_CosAngle, hv_MaxAngleBetweenRotationAxes;
  HTuple  hv_MatrixUID, hv_MatrixSID, hv_MatrixVID, hv_SingularValues;
  HTuple  hv_MinSingularValue;
  HTupleVector  hvec_RotationAxisRelativ(1), hvec_DiffToIdentity(1);

  //To estimate the touching point with respect to the tool coordinate system, we have to
  //arrange three equations in the following form:
  //Rp + T = q,
  //where R is a is the rotation matrix that rotates a point from the tool to the base coordinate
  //system and T is a translation that translates a point from the tool to the base coordinate.
  //q is the touching point with respect to the base coordinate system
  //and p the unknown touching point with respect to the tool coordinate system.
  //
  //Approaching the same point three times while rotating the tool leads to three rotation matrices
  //R0, R1 and R2 and three translations T0, T1 and T2.
  //Solving this equation for the unknown touching point yields therefore:
  //R0*p + T0 = q, R1*p + T1 = q and R2*p + T2 = q.
  //After building two equations in the form (R1-R0)*p = T0-T1 and (R2-R0)*p = T0-T2,
  //the DLT (direct linear transformation) can be used to efficiently solve for the unknown
  //touching point p.


  //Check input.
  if (0 != (int(HTuple(hvec_ToolInBasePosesTouchingPoint.Length())<3)))
  {
    throw HException("Please specify at least three robot poses.");
  }

  //Initialize equation.
  CreateMatrix((HTuple(hvec_ToolInBasePosesTouchingPoint.Length())-1)*3, 3, 0, &hv_LHS);
  CreateMatrix((HTuple(hvec_ToolInBasePosesTouchingPoint.Length())-1)*3, 1, 0, &hv_RHS);
  hvec_RotationAxisRelativ = (HTupleVector(1).Insert(0,HTupleVector(HTuple())));
  hvec_DiffToIdentity = (HTupleVector(1).Insert(0,HTupleVector(HTuple())));
  //Decompose first pose.
  PoseToHomMat3d(hvec_ToolInBasePosesTouchingPoint[0].T(), &hv_HomMat3D0);
  CreateMatrix(3, 4, hv_HomMat3D0, &hv_Mat0);
  GetSubMatrix(hv_Mat0, 0, 0, 3, 3, &hv_MatRot0);
  GetSubMatrix(hv_Mat0, 0, 3, 3, 1, &hv_MatTrans0);
  //
  {
  HTuple end_val33 = HTuple(hvec_ToolInBasePosesTouchingPoint.Length())-1;
  HTuple step_val33 = 1;
  for (hv_Index=1; hv_Index.Continue(end_val33, step_val33); hv_Index += step_val33)
  {
    //Decompose current pose.
    PoseToHomMat3d(hvec_ToolInBasePosesTouchingPoint[hv_Index].T(), &hv_HomMat3D);
    CreateMatrix(3, 4, hv_HomMat3D, &hv_Mat);
    GetSubMatrix(hv_Mat, 0, 0, 3, 3, &hv_MatRot);
    GetSubMatrix(hv_Mat, 0, 3, 3, 1, &hv_MatTrans);
    //Get rotation axis relative to first pose.
    {
    HTuple ExpTmpOutVar_0;HTuple ExpTmpOutVar_1;
    get_rotation_axis(hv_MatRot, hv_MatRot0, &ExpTmpOutVar_0, &ExpTmpOutVar_1);
    hvec_RotationAxisRelativ[hv_Index].T() = ExpTmpOutVar_0;
    hvec_DiffToIdentity[hv_Index].T() = ExpTmpOutVar_1;
    }
    //Fill equation.
    SubMatrixMod(hv_MatRot, hv_MatRot0);
    SetSubMatrix(hv_LHS, hv_MatRot, (hv_Index-1)*3, 0);
    SubMatrixMod(hv_MatTrans, hv_MatTrans0);
    ScaleMatrixMod(hv_MatTrans, -1.0);
    SetSubMatrix(hv_RHS, hv_MatTrans, (hv_Index-1)*3, 0);
    //Clear.
    ClearMatrix(hv_Mat);
    ClearMatrix(hv_MatRot);
    ClearMatrix(hv_MatTrans);
  }
  }
  //Solve.
  SolveMatrix(hv_LHS, "general", 0, hv_RHS, &hv_MatrixResultID);
  GetFullMatrix(hv_MatrixResultID, &(*hv_RobotTouchingPointInToolCoordinates));
  //Detailed errors.
  hv_DetailedErrors = 0;
  if (0 != hv_DetailedErrors)
  {
    //Check that the tool was tilted enough compared to the first pose.
    hv_MinDiffToIdentity = 1e8;
    {
    HTuple end_val60 = HTuple(hvec_ToolInBasePosesTouchingPoint.Length())-1;
    HTuple step_val60 = 1;
    for (hv_Index=1; hv_Index.Continue(end_val60, step_val60); hv_Index += step_val60)
    {
      if (0 != (int(hvec_DiffToIdentity[hv_Index].T()<hv_MinDiffToIdentity)))
      {
        hv_MinDiffToIdentity = hvec_DiffToIdentity[hv_Index].T();
      }
    }
    }
    //Check that different rotation axis were used when tilted away from first pose.
    hv_MinCosAngle = 1.5;
    {
    HTuple end_val67 = HTuple(hvec_ToolInBasePosesTouchingPoint.Length())-2;
    HTuple step_val67 = 1;
    for (hv_Index=1; hv_Index.Continue(end_val67, step_val67); hv_Index += step_val67)
    {
      {
      HTuple end_val68 = HTuple(hvec_ToolInBasePosesTouchingPoint.Length())-1;
      HTuple step_val68 = 1;
      for (hv_Index1=hv_Index+1; hv_Index1.Continue(end_val68, step_val68); hv_Index1 += step_val68)
      {
        hv_CosAngle = ((hvec_RotationAxisRelativ[hv_Index].T()*hvec_RotationAxisRelativ[hv_Index1].T()).TupleSum()).TupleAbs();
        if (0 != (int(hv_CosAngle<hv_MinCosAngle)))
        {
          hv_MinCosAngle = hv_CosAngle;
        }
      }
      }
    }
    }
    hv_MaxAngleBetweenRotationAxes = (hv_MinCosAngle.TupleAcos()).TupleDeg();
  }
  SvdMatrix(hv_LHS, "full", "both", &hv_MatrixUID, &hv_MatrixSID, &hv_MatrixVID);
  GetValueMatrix(hv_MatrixSID, ((HTuple(0).Append(1)).Append(2)), ((HTuple(0).Append(1)).Append(2)), 
      &hv_SingularValues);
  hv_MinSingularValue = (hv_SingularValues.TupleAbs()).TupleMin();
  if (0 != (int(hv_MinSingularValue<0.15)))
  {
    //Consider the rotations of the tool from its first position to each following position.
    //Please rotate the tool enough away from the first position.
    //Furthermore, please use at least two significantly different rotation axis when rotating the tool
    //from its first position (preferably orthogonal directions?).
    //The maximum angle between the corresponding rotation axis is MaxAngleBetweenRotationAxes.
    //
    throw HException("The estimated touching point might not be reliable. Try to use at least two different rotation axis and/or increase the rotations around these axis.");
  }
  //
  //Clear.
  ClearMatrix(hv_MatrixUID);
  ClearMatrix(hv_MatrixSID);
  ClearMatrix(hv_MatrixVID);
  ClearMatrix(hv_Mat0);
  ClearMatrix(hv_MatRot0);
  ClearMatrix(hv_MatTrans0);
  ClearMatrix(hv_LHS);
  ClearMatrix(hv_RHS);
  return;
}

// Chapter: Matrix / Arithmetic
void get_rotation_axis (HTuple hv_MatRot, HTuple hv_MatRot0, HTuple *hv_RotationAxis, 
    HTuple *hv_DiffToIdentity)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_MatrixMultID, hv_Identity, hv_MatrixSubID;
  HTuple  hv_Values, hv_MatrixUID, hv_MatrixSID, hv_MatrixVID;
  HTuple  hv_SingularValues, hv_AbsSingularValues, hv_Indices;

  //
  //Get (R_i)^(-1)R_0
  MultMatrix(hv_MatRot, hv_MatRot0, "ATB", &hv_MatrixMultID);
  //Get some measure for how far the matrix is from the identity.
  CreateMatrix(3, 3, "identity", &hv_Identity);
  SubMatrix(hv_MatrixMultID, hv_Identity, &hv_MatrixSubID);
  GetFullMatrix(hv_MatrixSubID, &hv_Values);
  (*hv_DiffToIdentity) = (hv_Values*hv_Values).TupleSum();
  //Get its rotation axis.
  SvdMatrix(hv_MatrixSubID, "full", "both", &hv_MatrixUID, &hv_MatrixSID, &hv_MatrixVID);
  GetValueMatrix(hv_MatrixSID, ((HTuple(0).Append(1)).Append(2)), ((HTuple(0).Append(1)).Append(2)), 
      &hv_SingularValues);
  hv_AbsSingularValues = hv_SingularValues.TupleAbs();
  TupleSortIndex(hv_AbsSingularValues, &hv_Indices);
  GetValueMatrix(hv_MatrixVID, ((HTuple(0).Append(1)).Append(2)), (HTuple(hv_Indices[0]).TupleConcat(HTuple(hv_Indices[0]))).TupleConcat(HTuple(hv_Indices[0])), 
      &(*hv_RotationAxis));
  //Clear matrices.
  ClearMatrix(hv_MatrixMultID);
  ClearMatrix(hv_MatrixUID);
  ClearMatrix(hv_MatrixSID);
  ClearMatrix(hv_MatrixVID);
  ClearMatrix(hv_MatrixSubID);
  ClearMatrix(hv_Identity);
  return;
}

