// Chapter: Deep Learning / Model
// Short Description: Returns the list of available pixel evaluation measures for the specified type. 
void get_valid_pixel_measures (HTuple hv_EvaluationType, HTuple *hv_EvaluationMeasures)
{

  // Local iconic variables

  //
  //This helper procedure returns for the given evaluation type
  //all pixel measures available for this type.
  //
  (*hv_EvaluationMeasures) = HTuple();
  if (0 != (int(hv_EvaluationType==HTuple("segmentation"))))
  {
    (*hv_EvaluationMeasures).Clear();
    (*hv_EvaluationMeasures)[0] = "pixel_accuracy";
    (*hv_EvaluationMeasures)[1] = "mean_accuracy";
    (*hv_EvaluationMeasures)[2] = "mean_iou";
    (*hv_EvaluationMeasures)[3] = "class_iou";
    (*hv_EvaluationMeasures)[4] = "class_pixel_accuracy";
    (*hv_EvaluationMeasures)[5] = "pixel_confusion_matrix";
    (*hv_EvaluationMeasures)[6] = "frequency_weighted_iou";
  }
  else if (0 != (int(hv_EvaluationType==HTuple("3d_gripping_point_detection"))))
  {
    (*hv_EvaluationMeasures).Clear();
    (*hv_EvaluationMeasures)[0] = "mean_precision";
    (*hv_EvaluationMeasures)[1] = "mean_iou";
  }
  //
  return;
}

// Chapter: Deep Learning / Semantic Segmentation and Edge Extraction
// Short Description: Get the weight image of a sample. 
void get_weight_image (HObject *ho_ImageWeight, HTuple hv_SampleKeys, HTuple hv_DLSample)
{

  //
  //This procedure returns the segmentation weight image of a sample.
  //
  if (0 != (int((hv_SampleKeys.TupleFind("weight_image"))!=-1)))
  {
    GetDictObject(&(*ho_ImageWeight), hv_DLSample, "weight_image");
  }
  else
  {
    throw HException("Weight image could not be found in DLSample.");
  }
  return;
}

// Chapter: Identification / Data Code
// Short Description: Grade data code according to a quality standard. 
void grade_data_code_2d (HTuple hv_DataCodeHandle, HTuple hv_ResultHandle, HTuple hv_Standard, 
    HTuple hv_Format, HTuple hv_Mode, HTuple *hv_GradingResults)
{

  // Local iconic variables
  HObject  ho_Modules, ho_ModuleCenters, ho_EmptyObject;
  HObject  ho_GradeModules;

  // Local control variables
  HTuple  hv_QualityStandards, hv_Message, hv_GradeFormats;
  HTuple  hv_GradingResultModes, hv_ParamQualityStd, hv_ParamLabels;
  HTuple  hv_ResultParams, hv_QualityResultParams, hv_SymbolType;
  HTuple  hv_CodeTypes, hv_ParamsAvailable, hv_IndexParamLabels;
  HTuple  hv_GradeNumbers, hv_GradeLetters, hv_ParamGrades;
  HTuple  hv_Labels, hv_Grades, hv_Index, hv_Grade, hv_ParamFloatGrades;
  HTuple  hv_FloatGrades, hv_ParamValues, hv_Values, hv_GradesData;
  HTuple  hv_Data, hv_ParamAdditionalReflectanceCheck, hv_AdditionalReflectanceCheck;
  HTuple  hv_ParamIntermLabels, hv_ParamIntermGrades, hv_ParamIntermValues;
  HTuple  hv_ParamIntermFloatGrades, hv_IntermediateResults;
  HTuple  hv_IntermediateLabels, hv_IntermediateGrades, hv_IntermediateValues;
  HTuple  hv_IntermediateFloatGrades, hv_IntermediateGrade;
  HTuple  hv_ModuleData, hv_ParamRows, hv_ParamCols, hv_Rows;
  HTuple  hv_Cols, hv_Aperture, hv_ModuleWidth, hv_ModuleHeight;
  HTuple  hv_Radius, hv_RadiusTup, hv_ParamReflectanceMargin;
  HTuple  hv_ReflectanceData, hv_ReflectanceMarginModuleGrades;
  HTuple  hv_GradeIndices, hv_NameModuleGrade, hv_GradeRows;
  HTuple  hv_GradeCols, hv_GradeRadius, hv_Keys;

  //This procedure performs print quality inspection on
  //data codes and returns all results in a dictionary.
  //
  //The corresponding quality standard can be selected
  //with Standard. Quality grades can be returned as
  //numbers 0-4 or letters F-A (Format).
  //Mode defines if only the grades or all (intermediate)
  //quality grading results are returned.
  //
  //
  //First, check the input parameters.
  //
  //Parameter Standard.
  if (0 != (int((hv_Standard.TupleLength())!=1)))
  {
    throw HException("Wrong number of values for the parameter Standard. Please specify exactly one quality standard.");
  }
  hv_QualityStandards.Clear();
  hv_QualityStandards[0] = "isoiec15415";
  hv_QualityStandards[1] = "isoiec29158";
  hv_QualityStandards[2] = "aimdpm_1_2006";
  hv_QualityStandards[3] = "semi_t10";
  hv_QualityStandards[4] = "isoiec_tr_29158";
  if (0 != (int((hv_QualityStandards.TupleFind(hv_Standard))==-1)))
  {
    //The parameter 'isoiec_tr_29158' was replaced by 'isoiec29158' and
    //is only available for backward compatibility.
    hv_Message = "Invalid quality standard. Possible values for Standard are: ";
    hv_Message = (hv_Message+((hv_QualityStandards.TupleSelectRange(0,3)).TupleJoin(HTuple(", "))))+".";
    throw HException(hv_Message);
  }
  //Parameter Format.
  if (0 != (int((hv_Format.TupleLength())!=1)))
  {
    throw HException("Wrong number of values for the parameter Format. Please specify exactly one grade format.");
  }
  hv_GradeFormats.Clear();
  hv_GradeFormats[0] = "numeric";
  hv_GradeFormats[1] = "alphabetic";
  if (0 != (int((hv_GradeFormats.TupleFind(hv_Format))==-1)))
  {
    hv_Message = "Invalid grade format. Possible values for Format are: ";
    hv_Message = (hv_Message+(hv_GradeFormats.TupleJoin(HTuple(", "))))+".";
    throw HException(hv_Message);
  }
  if (0 != (HTuple(int(hv_Standard==HTuple("semi_t10"))).TupleAnd(int(hv_Format==HTuple("alphabetic")))))
  {
    throw HException("Alphabetic grades are not supported for the selected quality standard. Please use the numeric format.");
  }
  //Parameter Mode.
  if (0 != (int((hv_Mode.TupleLength())!=1)))
  {
    throw HException("Wrong number of values for the parameter Mode. Please specify exactly one grading result mode.");
  }
  hv_GradingResultModes.Clear();
  hv_GradingResultModes[0] = "grades";
  hv_GradingResultModes[1] = "all";
  if (0 != (int((hv_GradingResultModes.TupleFind(hv_Mode))==-1)))
  {
    hv_Message = "Invalid grading result mode. Possible values for Mode are: ";
    hv_Message = (hv_Message+(hv_GradingResultModes.TupleJoin(HTuple(", "))))+".";
    throw HException(hv_Message);
  }
  //Query the possible quality results for the given data code type.
  hv_ParamQualityStd = "quality_"+hv_Standard;
  hv_ParamLabels = hv_ParamQualityStd+"_labels";
  QueryDataCode2dParams(hv_DataCodeHandle, "get_result_params", &hv_ResultParams);
  hv_QualityResultParams = hv_ResultParams.TupleRegexpSelect("quality_");
  if (0 != (int(hv_Standard==HTuple("isoiec_tr_29158"))))
  {
    //The parameters 'quality_isoiec_tr_29158_...' were replaced by the parameters
    //'quality_isoiec29158_...' and are only available for backward compatibility.
    GetDataCode2dParam(hv_DataCodeHandle, "symbol_type", &hv_SymbolType);
    hv_CodeTypes.Clear();
    hv_CodeTypes[0] = "Data Matrix ECC 200";
    hv_CodeTypes[1] = "GS1 DataMatrix";
    hv_CodeTypes[2] = "QR Code";
    hv_CodeTypes[3] = "Micro QR Code";
    hv_CodeTypes[4] = "GS1 QR Code";
    hv_CodeTypes[5] = "Aztec Code";
    hv_CodeTypes[6] = "GS1 Aztec Code";
    hv_ParamsAvailable = int((hv_CodeTypes.TupleFind(hv_SymbolType))>=0);
    if (0 != hv_ParamsAvailable)
    {
      hv_QualityResultParams = hv_QualityResultParams.TupleConcat(((HTuple("quality_isoiec_tr_29158").Append("quality_isoiec_tr_29158_labels")).Append("quality_isoiec_tr_29158_values")));
      if (0 != (HTuple(int(hv_SymbolType==HTuple("Data Matrix ECC 200"))).TupleOr(int(hv_SymbolType==HTuple("GS1 DataMatrix")))))
      {
        hv_QualityResultParams = hv_QualityResultParams.TupleConcat((((((HTuple("quality_isoiec_tr_29158_intermediate").Append("quality_isoiec_tr_29158_intermediate_labels")).Append("quality_isoiec_tr_29158_intermediate_values")).Append("quality_isoiec_tr_29158_rows")).Append("quality_isoiec_tr_29158_cols")).Append("quality_isoiec_tr_29158_reflectance_margin_module_grades")));
      }
    }
  }
  //
  hv_IndexParamLabels = hv_QualityResultParams.TupleFind(hv_ParamLabels);
  if (0 != (HTuple(int(hv_IndexParamLabels==-1)).TupleOr(int(hv_IndexParamLabels==HTuple()))))
  {
    hv_Message = ("The quality standard "+hv_Standard)+" is not supported for this code type.";
    throw HException(hv_Message);
  }
  //
  //Now, perform quality grading and add results to output dictionary.
  //
  CreateDict(&(*hv_GradingResults));
  hv_GradeNumbers.Clear();
  hv_GradeNumbers[0] = 0;
  hv_GradeNumbers[1] = 1;
  hv_GradeNumbers[2] = 2;
  hv_GradeNumbers[3] = 3;
  hv_GradeNumbers[4] = 4;
  hv_GradeLetters.Clear();
  hv_GradeLetters[0] = "F";
  hv_GradeLetters[1] = "D";
  hv_GradeLetters[2] = "C";
  hv_GradeLetters[3] = "B";
  hv_GradeLetters[4] = "A";
  if (0 != (int(hv_Standard==HTuple("semi_t10"))))
  {
    //For the SEMI T10 standard no grades but values are returned.
    hv_ParamGrades = hv_ParamQualityStd+"_values";
  }
  else
  {
    hv_ParamGrades = hv_ParamQualityStd;
  }
  //
  GetDataCode2dResults(hv_DataCodeHandle, hv_ResultHandle, hv_ParamLabels, &hv_Labels);
  GetDataCode2dResults(hv_DataCodeHandle, hv_ResultHandle, hv_ParamGrades, &hv_Grades);
  if (0 != (HTuple(HTuple(int(hv_Mode==HTuple("grades"))).TupleAnd(int(hv_Format==HTuple("numeric")))).TupleOr(int(hv_Standard==HTuple("semi_t10")))))
  {
    //Return labels and corresponding grades in numbers (0 to 4).
    {
    HTuple end_val88 = (hv_Labels.TupleLength())-1;
    HTuple step_val88 = 1;
    for (hv_Index=0; hv_Index.Continue(end_val88, step_val88); hv_Index += step_val88)
    {
      SetDictTuple((*hv_GradingResults), HTuple(hv_Labels[hv_Index]), HTuple(hv_Grades[hv_Index]));
    }
    }
  }
  else if (0 != (HTuple(int(hv_Mode==HTuple("grades"))).TupleAnd(int(hv_Format==HTuple("alphabetic")))))
  {
    //Return labels and corresponding grades in letters (F to A).
    {
    HTuple end_val93 = (hv_Labels.TupleLength())-1;
    HTuple step_val93 = 1;
    for (hv_Index=0; hv_Index.Continue(end_val93, step_val93); hv_Index += step_val93)
    {
      if (0 != ((HTuple(hv_Grades[hv_Index]).TupleIsInt()).TupleAnd(int((hv_GradeNumbers.TupleFind(HTuple(hv_Grades[hv_Index])))>=0))))
      {
        hv_Grade = HTuple(hv_GradeLetters[HTuple(hv_Grades[hv_Index])]);
      }
      else
      {
        hv_Grade = HTuple(hv_Grades[hv_Index]);
      }
      SetDictTuple((*hv_GradingResults), HTuple(hv_Labels[hv_Index]), hv_Grade);
    }
    }
  }
  else if (0 != (int(hv_Mode==HTuple("all"))))
  {
    //Return labels and corresponding grades in numbers or letters
    //as well as the raw values for all directly measurable grades.
    hv_ParamFloatGrades = hv_ParamQualityStd+"_float_grades";
    if (0 != (int((hv_QualityResultParams.TupleFind(hv_ParamFloatGrades))>=0)))
    {
      GetDataCode2dResults(hv_DataCodeHandle, hv_ResultHandle, hv_ParamFloatGrades, 
          &hv_FloatGrades);
    }
    else
    {
      hv_FloatGrades = HTuple();
    }
    hv_ParamValues = hv_ParamQualityStd+"_values";
    GetDataCode2dResults(hv_DataCodeHandle, hv_ResultHandle, hv_ParamValues, &hv_Values);
    CreateDict(&hv_GradesData);
    {
    HTuple end_val113 = (hv_Labels.TupleLength())-1;
    HTuple step_val113 = 1;
    for (hv_Index=0; hv_Index.Continue(end_val113, step_val113); hv_Index += step_val113)
    {
      CreateDict(&hv_Data);
      if (0 != (HTuple(HTuple(int(hv_Format==HTuple("alphabetic"))).TupleAnd(HTuple(hv_Grades[hv_Index]).TupleIsInt())).TupleAnd(int((hv_GradeNumbers.TupleFind(HTuple(hv_Grades[hv_Index])))>=0))))
      {
        hv_Grade = HTuple(hv_GradeLetters[HTuple(hv_Grades[hv_Index])]);
      }
      else
      {
        hv_Grade = HTuple(hv_Grades[hv_Index]);
      }
      SetDictTuple(hv_Data, "Grade", hv_Grade);
      if (0 != (int(hv_FloatGrades!=HTuple())))
      {
        SetDictTuple(hv_Data, "Grade (float)", HTuple(hv_FloatGrades[hv_Index]));
      }
      SetDictTuple(hv_Data, "Value", HTuple(hv_Values[hv_Index]));
      SetDictTuple(hv_GradesData, HTuple(hv_Labels[hv_Index]), hv_Data);
    }
    }
    SetDictTuple((*hv_GradingResults), "Grades", hv_GradesData);
  }
  //
  if (0 != (int(hv_Mode==HTuple("all"))))
  {
    //Additional reflectance check (if available).
    hv_ParamAdditionalReflectanceCheck = "quality_isoiec15415_additional_reflectance_check";
    if (0 != (int(hv_Standard==HTuple("isoiec15415"))))
    {
      if (0 != (int((hv_QualityResultParams.TupleFind(hv_ParamAdditionalReflectanceCheck))>=0)))
      {
        GetDataCode2dResults(hv_DataCodeHandle, hv_ResultHandle, hv_ParamAdditionalReflectanceCheck, 
            &hv_AdditionalReflectanceCheck);
        SetDictTuple((*hv_GradingResults), "Additional Reflectance Check", hv_AdditionalReflectanceCheck);
      }
    }
    //
    //Intermediate grading results (if available).
    hv_ParamIntermLabels = hv_ParamQualityStd+"_intermediate_labels";
    hv_ParamIntermGrades = hv_ParamQualityStd+"_intermediate";
    hv_ParamIntermValues = hv_ParamQualityStd+"_intermediate_values";
    hv_ParamIntermFloatGrades = hv_ParamQualityStd+"_intermediate_float_grades";
    if (0 != (int((hv_QualityResultParams.TupleFind(hv_ParamIntermLabels))>=0)))
    {
      CreateDict(&hv_IntermediateResults);
      GetDataCode2dResults(hv_DataCodeHandle, hv_ResultHandle, hv_ParamIntermLabels, 
          &hv_IntermediateLabels);
      GetDataCode2dResults(hv_DataCodeHandle, hv_ResultHandle, hv_ParamIntermGrades, 
          &hv_IntermediateGrades);
      GetDataCode2dResults(hv_DataCodeHandle, hv_ResultHandle, hv_ParamIntermValues, 
          &hv_IntermediateValues);
      if (0 != (int((hv_QualityResultParams.TupleFind(hv_ParamIntermFloatGrades))>=0)))
      {
        GetDataCode2dResults(hv_DataCodeHandle, hv_ResultHandle, hv_ParamIntermFloatGrades, 
            &hv_IntermediateFloatGrades);
      }
      else
      {
        hv_IntermediateFloatGrades = HTuple();
      }

      {
      HTuple end_val156 = (hv_IntermediateLabels.TupleLength())-1;
      HTuple step_val156 = 1;
      for (hv_Index=0; hv_Index.Continue(end_val156, step_val156); hv_Index += step_val156)
      {
        CreateDict(&hv_Data);
        if (0 != (HTuple(HTuple(int(hv_Format==HTuple("alphabetic"))).TupleAnd(HTuple(hv_IntermediateGrades[hv_Index]).TupleIsInt())).TupleAnd(int((hv_GradeNumbers.TupleFind(HTuple(hv_IntermediateGrades[hv_Index])))>=0))))
        {
          hv_IntermediateGrade = HTuple(hv_GradeLetters[HTuple(hv_IntermediateGrades[hv_Index])]);
        }
        else
        {
          hv_IntermediateGrade = HTuple(hv_IntermediateGrades[hv_Index]);
        }
        SetDictTuple(hv_Data, "Grade", hv_IntermediateGrade);
        if (0 != (int(hv_IntermediateFloatGrades!=HTuple())))
        {
          SetDictTuple(hv_Data, "Grade (float)", HTuple(hv_IntermediateFloatGrades[hv_Index]));
        }
        SetDictTuple(hv_Data, "Value", HTuple(hv_IntermediateValues[hv_Index]));
        SetDictTuple(hv_IntermediateResults, HTuple(hv_IntermediateLabels[hv_Index]), 
            hv_Data);
      }
      }
      SetDictTuple((*hv_GradingResults), "Intermediate Results", hv_IntermediateResults);
    }
    //
    //Module Data (if available).
    CreateDict(&hv_ModuleData);
    hv_ParamRows = hv_ParamQualityStd+"_rows";
    hv_ParamCols = hv_ParamQualityStd+"_cols";
    if (0 != (int((hv_QualityResultParams.TupleFind(hv_ParamRows))>=0)))
    {
      GetDataCode2dResults(hv_DataCodeHandle, hv_ResultHandle, hv_ParamRows, &hv_Rows);
      GetDataCode2dResults(hv_DataCodeHandle, hv_ResultHandle, hv_ParamCols, &hv_Cols);
      SetDictTuple(hv_ModuleData, "Rows", hv_Rows);
      SetDictTuple(hv_ModuleData, "Cols", hv_Cols);
      if (0 != (int((hv_Rows.TupleLength())>0)))
      {
        //Create module rois and centers using aperture and module size.
        hv_Aperture = HTuple(hv_Grades[hv_Labels.TupleFind("Aperture")]);
        GetDataCode2dResults(hv_DataCodeHandle, hv_ResultHandle, "module_width", 
            &hv_ModuleWidth);
        GetDataCode2dResults(hv_DataCodeHandle, hv_ResultHandle, "module_height", 
            &hv_ModuleHeight);
        hv_Radius = (0.5*hv_Aperture)*(hv_ModuleWidth.TupleMin2(hv_ModuleHeight));
        hv_RadiusTup = HTuple(hv_Rows.TupleLength(),hv_Radius);
        GenCircleContourXld(&ho_Modules, hv_Rows, hv_Cols, hv_RadiusTup, HTuple(0).TupleRad(), 
            HTuple(360).TupleRad(), "positive", 1);
        GenCrossContourXld(&ho_ModuleCenters, hv_Rows, hv_Cols, 2*hv_Radius, HTuple(0).TupleRad());
      }
      else
      {
        GenEmptyObj(&ho_Modules);
        GenEmptyObj(&ho_ModuleCenters);
      }
      SetDictObject(ho_Modules, hv_ModuleData, "Rois");
      SetDictObject(ho_ModuleCenters, hv_ModuleData, "Centers");
    }
    //Get reflectance margin module grades.
    hv_ParamReflectanceMargin = hv_ParamQualityStd+"_reflectance_margin_module_grades";
    if (0 != (int((hv_QualityResultParams.TupleFind(hv_ParamReflectanceMargin))!=-1)))
    {
      CreateDict(&hv_ReflectanceData);
      GetDataCode2dResults(hv_DataCodeHandle, hv_ResultHandle, hv_ParamReflectanceMargin, 
          &hv_ReflectanceMarginModuleGrades);
      SetDictTuple(hv_ReflectanceData, "Module Grades", hv_ReflectanceMarginModuleGrades);
      for (hv_Grade=0; hv_Grade<=4; hv_Grade+=1)
      {
        hv_GradeIndices = hv_ReflectanceMarginModuleGrades.TupleFind(hv_Grade);
        hv_NameModuleGrade = "Modules Grade "+hv_Grade;
        if (0 != (HTuple(int(hv_GradeIndices==-1)).TupleOr(int(hv_Rows==HTuple()))))
        {
          GenEmptyObj(&ho_EmptyObject);
          SetDictObject(ho_EmptyObject, hv_ReflectanceData, hv_NameModuleGrade);
          continue;
        }
        hv_GradeRows = HTuple(hv_Rows[hv_GradeIndices]);
        hv_GradeCols = HTuple(hv_Cols[hv_GradeIndices]);
        hv_GradeRadius = HTuple(hv_GradeRows.TupleLength(),hv_Radius);
        GenCircleContourXld(&ho_GradeModules, hv_GradeRows, hv_GradeCols, hv_GradeRadius, 
            HTuple(0).TupleRad(), HTuple(360).TupleRad(), "positive", 1);
        SetDictObject(ho_GradeModules, hv_ReflectanceData, hv_NameModuleGrade);
      }
      SetDictTuple(hv_ModuleData, "Reflectance Margin", hv_ReflectanceData);
    }
    GetDictParam(hv_ModuleData, "keys", HTuple(), &hv_Keys);
    if (0 != (int(hv_Keys!=HTuple())))
    {
      SetDictTuple((*hv_GradingResults), "Modules", hv_ModuleData);
    }
  }
  //
  return;
}

// Chapter: Deep Learning / Model
// Short Description: Handle the 'auto' option of the 'overwrite_files' parameter in preprocess_dl_dataset. 
void handle_overwrite_files_auto_in_preprocess_dl_dataset (HTuple hv_DLDataset, HTuple hv_DLPreprocessParam, 
    HTuple hv_DLDatasetFileName, HTuple *hv_OverwriteFiles)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_ExistingDLDataset, hv_Exception, hv_ExistingDLPreprocessParam;
  HTuple  hv_ExistingKeys, hv_Keys, hv_Equal, hv_I, hv_Key;
  HTuple  hv_Value, hv_ExistingValue, hv_ExistingNormType;
  HTuple  hv_NormType, hv_Samples, hv_ExistingSamples, hv_Sample;
  HTuple  hv_ExistingSample, hv_ExistingImageId, hv_ImageId;
  HTuple  hv_SplitExists, hv_SplitExistsSample, hv_SplitExisting;
  HTuple  hv_SplitSample, hv_KeyIdx;

  //Check if the given preprocessed dataset matches with the
  //given DLDataset and DLPreprocessParam.
  (*hv_OverwriteFiles) = "true";
  while (true)
  {
    try
    {
      //Read the preprocessed dataset.
      ReadDict(hv_DLDatasetFileName, HTuple(), HTuple(), &hv_ExistingDLDataset);
    }
    // catch (Exception) 
    catch (HException &HDevExpDefaultException)
    {
      HDevExpDefaultException.ToHTuple(&hv_Exception);
      break;
    }
    //Check if preprocess parameters are equal.
    GetDictTuple(hv_ExistingDLDataset, "preprocess_param", &hv_ExistingDLPreprocessParam);
    //Check if preprocessing keys are equal.
    GetDictParam(hv_ExistingDLPreprocessParam, "keys", HTuple(), &hv_ExistingKeys);
    GetDictParam(hv_DLPreprocessParam, "keys", HTuple(), &hv_Keys);
    hv_ExistingKeys = hv_ExistingKeys.TupleSort();
    hv_Keys = hv_Keys.TupleSort();
    TupleEqual(hv_Keys, hv_ExistingKeys, &hv_Equal);
    if (0 != (hv_Equal.TupleNot()))
    {
      break;
    }
    //Check if preprocessing values are equal.
    hv_Equal = 1;
    {
    HTuple end_val23 = (hv_Keys.TupleLength())-1;
    HTuple step_val23 = 1;
    for (hv_I=0; hv_I.Continue(end_val23, step_val23); hv_I += step_val23)
    {
      hv_Key = HTuple(hv_Keys[hv_I]);
      GetDictTuple(hv_DLPreprocessParam, HTuple(hv_Keys[hv_I]), &hv_Value);
      GetDictTuple(hv_ExistingDLPreprocessParam, HTuple(hv_Keys[hv_I]), &hv_ExistingValue);
      TupleEqual(hv_Value, hv_ExistingValue, &hv_Equal);
      if (0 != (hv_Equal.TupleNot()))
      {
        if (0 != (HTuple(int(hv_Key==HTuple("image_range_min"))).TupleOr(int(hv_Key==HTuple("image_range_max")))))
        {
          try
          {
            GetDictTuple(hv_ExistingDLPreprocessParam, "normalization_type", &hv_ExistingNormType);
            GetDictTuple(hv_ExistingDLPreprocessParam, "normalization_type", &hv_NormType);
            //If the normalization type is constant_values the range is fixed no matter what
            //values are given in image_range_min/max.
            if (0 != (HTuple(int(hv_ExistingNormType==hv_NormType)).TupleAnd(int(hv_NormType==HTuple("constant_values")))))
            {
              hv_Equal = 1;
              continue;
            }
          }
          // catch (Exception) 
          catch (HException &HDevExpDefaultException)
          {
            HDevExpDefaultException.ToHTuple(&hv_Exception);
            break;
          }
        }
        break;
      }
    }
    }
    if (0 != (hv_Equal.TupleNot()))
    {
      break;
    }
    //Check if samples are plausible.
    try
    {
      GetDictTuple(hv_DLDataset, "samples", &hv_Samples);
      GetDictTuple(hv_ExistingDLDataset, "samples", &hv_ExistingSamples);
    }
    // catch (Exception) 
    catch (HException &HDevExpDefaultException)
    {
      HDevExpDefaultException.ToHTuple(&hv_Exception);
      break;
    }

    //Are the number of samples equal?
    if (0 != (int((hv_Samples.TupleLength())!=(hv_ExistingSamples.TupleLength()))))
    {
      break;
    }
    hv_Equal = 1;
    {
    HTuple end_val62 = (hv_Samples.TupleLength())-1;
    HTuple step_val62 = 1;
    for (hv_I=0; hv_I.Continue(end_val62, step_val62); hv_I += step_val62)
    {
      hv_Sample = HTuple(hv_Samples[hv_I]);
      hv_ExistingSample = HTuple(hv_ExistingSamples[hv_I]);
      try
      {
        GetDictTuple(hv_ExistingSample, "image_id", &hv_ExistingImageId);
        GetDictTuple(hv_Sample, "image_id", &hv_ImageId);

        //Are the image_id entries exactly the same?
        hv_Equal = int(hv_ImageId==hv_ExistingImageId);
        if (0 != (hv_Equal.TupleNot()))
        {
          break;
        }
        GetDictParam(hv_ExistingSample, "key_exists", "split", &hv_SplitExists);
        GetDictParam(hv_Sample, "key_exists", "split", &hv_SplitExistsSample);
        if (0 != (int((hv_SplitExistsSample.TupleNot())==hv_SplitExists)))
        {
          hv_Equal = 0;
          break;
        }
        if (0 != hv_SplitExistsSample)
        {
          GetDictTuple(hv_ExistingSample, "split", &hv_SplitExisting);
          GetDictTuple(hv_Sample, "split", &hv_SplitSample);
          if (0 != (int(hv_SplitExisting!=hv_SplitSample)))
          {
            hv_Equal = 0;
            break;
          }
        }
      }
      // catch (Exception) 
      catch (HException &HDevExpDefaultException)
      {
        HDevExpDefaultException.ToHTuple(&hv_Exception);
        hv_Equal = 0;
        break;
      }
    }
    }
    if (0 != (hv_Equal.TupleNot()))
    {
      break;
    }
    (*hv_OverwriteFiles) = "auto";
    break;
  }
  if (0 != (int((*hv_OverwriteFiles)==HTuple("auto"))))
  {
    //Finally overwrite all the key/values in the input dataset with the preprocessed entries.
    GetDictParam(hv_ExistingDLDataset, "keys", HTuple(), &hv_Keys);
    {
    HTuple end_val102 = (hv_Keys.TupleLength())-1;
    HTuple step_val102 = 1;
    for (hv_KeyIdx=0; hv_KeyIdx.Continue(end_val102, step_val102); hv_KeyIdx += step_val102)
    {
      hv_Key = HTuple(hv_Keys[hv_KeyIdx]);
      try
      {
        GetDictTuple(hv_ExistingDLDataset, hv_Key, &hv_Value);
        SetDictTuple(hv_DLDataset, hv_Key, hv_Value);
      }
      // catch (Exception) 
      catch (HException &HDevExpDefaultException)
      {
        HDevExpDefaultException.ToHTuple(&hv_Exception);
      }
    }
    }
  }
  return;
}

// Chapter: File / Misc
void images_exist (HTuple hv_ImageList)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_OS, hv_Separator, hv_HalconImages;
  HTuple  hv_Index, hv_ImageExists, hv_DirIndex;

  //
  //Get HalconImages directories.
  GetSystem("operating_system", &hv_OS);
  if (0 != (int((hv_OS.TupleSubstr(0,2))==HTuple("Win"))))
  {
    hv_Separator = ";";
  }
  else
  {
    hv_Separator = ":";
  }
  GetSystem("image_dir", &hv_HalconImages);
  TupleSplit(hv_HalconImages, hv_Separator, &hv_HalconImages);
  //
  //Loop over images and segmentations.
  {
  HTuple end_val12 = (hv_ImageList.TupleLength())-1;
  HTuple step_val12 = 1;
  for (hv_Index=0; hv_Index.Continue(end_val12, step_val12); hv_Index += step_val12)
  {
    FileExists(HTuple(hv_ImageList[hv_Index]), &hv_ImageExists);
    if (0 != (hv_ImageExists.TupleNot()))
    {
      //Check in HalconImages directories.
      {
      HTuple end_val16 = (hv_HalconImages.TupleLength())-1;
      HTuple step_val16 = 1;
      for (hv_DirIndex=0; hv_DirIndex.Continue(end_val16, step_val16); hv_DirIndex += step_val16)
      {
        FileExists((HTuple(hv_HalconImages[hv_DirIndex])+"/")+HTuple(hv_ImageList[hv_Index]), 
            &hv_ImageExists);
        if (0 != hv_ImageExists)
        {
          break;
        }
      }
      }
      if (0 != (hv_ImageExists.TupleNot()))
      {
        throw HException(("Image "+HTuple(hv_ImageList[hv_Index]))+" does not exist");
      }
    }
  }
  }
  return;
}

// Chapter: Deep Learning / Model
// Short Description: Initialize the dictionary RunningMeasures for the evaluation. 
void init_running_evaluation_measures (HTuple hv_EvalParams, HTuple *hv_RunningMeasures)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_Valid, hv_Exception, hv_NumClasses;
  HTuple  hv_EvaluationType, hv_Measures, hv_ClassIDs, hv_PixelMeasures;
  HTuple  hv_CalcRegionMeasures, hv_CalcGrippingPointMeasures;
  HTuple  hv_Index, hv_ClassDict, hv_ClassKey, hv_InstanceType;
  HTuple  hv_EvalOrientation, hv_AllocationBlockLength, hv_IoUThreshs;
  HTuple  hv_MaxNumDetections, hv_AreaRanges, hv_AreaNames;
  HTuple  hv_MinAreas, hv_MaxAreas, hv_DetailedEvaluation;
  HTuple  hv_MaxNumIdx, hv_MaxNum, hv_CurrentRunningMeasure;
  HTuple  hv_AreaIdx, hv_AreaRunningMeasure, hv_I, hv_IoURunningMeasure;
  HTuple  hv_ClsIdx, hv_ClassRunningMeasures, hv_Confidence;
  HTuple  hv_IgnoreClassIDs, hv_CalcConfMatrix, hv_MatrixSize;
  HTuple  hv_PixelConfusionMatrix, hv_MaxId, hv_ClsIDToClsIdx;
  HTuple  hv_TP, hv_FP, hv_FN, hv___Tmp_Ctrl_Dict_Init_1;

  //
  //This procedure initializes the dictionary RunningMeasures for evaluation.
  //It uses the evaluation parameters to initialize the running measures accordingly.
  //
  //The structure of RunningMeasures depends on the entry 'evaluate_instances' in the dictionary EvalParams.
  //
  //The dictionary RunningMeasures can be updated based on the per-batch/per-image evaluation results.
  //
  CreateDict(&(*hv_RunningMeasures));
  //Check that the necessary evaluation parameters exist.
  validate_evaluation_param(hv_EvalParams, &hv_Valid, &hv_Exception);
  if (0 != (hv_Valid.TupleNot()))
  {
    throw HException(HTuple("Invalid EvalParams, ")+hv_Exception);
  }
  //
  //Get general evaluation parameters.
  GetDictTuple(hv_EvalParams, "num_classes", &hv_NumClasses);
  GetDictTuple(hv_EvalParams, "evaluation_type", &hv_EvaluationType);
  GetDictTuple(hv_EvalParams, "measures", &hv_Measures);
  GetDictTuple(hv_EvalParams, "class_ids", &hv_ClassIDs);
  //
  if (0 != (int(hv_EvaluationType==HTuple("3d_gripping_point_detection"))))
  {
    //RunningMeasures contains:
    //if pixel measures:
    //- tp/fp/fn (pixel numbers for the gripping_map class)
    //if region measures:
    //- gt_overlap (accumulated overlap of ground truth regions with the prediction)
    //- num_gt_regions (overall number of ground truth regions)
    //if gripping point measures:
    //- gp_tp/gp_fp/gp_fn (gripping point true positives, false positives, and
    //  false negatives w.r.t. ground truth gripping point region).
    get_requested_pixel_measures(hv_Measures, hv_EvaluationType, &hv_PixelMeasures);
    if (0 != (int((hv_PixelMeasures.TupleLength())>0)))
    {
      SetDictTuple((*hv_RunningMeasures), "tp", 0);
      SetDictTuple((*hv_RunningMeasures), "fp", 0);
      SetDictTuple((*hv_RunningMeasures), "fn", 0);
    }
    hv_CalcRegionMeasures = HTuple(int((hv_Measures.TupleFind("mean_pro"))>-1)).TupleOr(int((hv_Measures.TupleFind("all"))>-1));
    if (0 != hv_CalcRegionMeasures)
    {
      SetDictTuple((*hv_RunningMeasures), "gt_overlap", 0);
      SetDictTuple((*hv_RunningMeasures), "num_gt_regions", 0);
    }
    hv_CalcGrippingPointMeasures = int((HTuple(hv_Measures.TupleRegexpSelect("gripping_point_.*|all")).TupleLength())>0);
    if (0 != hv_CalcGrippingPointMeasures)
    {
      SetDictTuple((*hv_RunningMeasures), "gp_tp", 0);
      SetDictTuple((*hv_RunningMeasures), "gp_fp", 0);
      SetDictTuple((*hv_RunningMeasures), "gp_fn", 0);
    }
  }
  else if (0 != (HTuple(int(hv_EvaluationType==HTuple("anomaly_detection"))).TupleOr(int(hv_EvaluationType==HTuple("gc_anomaly_detection")))))
  {
    //RunningMeasures contains:
    //- image_ids:          IDs of the images.
    //- anomaly_label_ids:  Class IDs of ground truth labels.
    //- anomaly_scores:     Predicted image level anomaly scores.
    SetDictTuple((*hv_RunningMeasures), "image_ids", HTuple());
    SetDictTuple((*hv_RunningMeasures), "anomaly_label_ids", HTuple());
    SetDictTuple((*hv_RunningMeasures), "anomaly_scores", HTuple());
  }
  else if (0 != (int(hv_EvaluationType==HTuple("classification"))))
  {
    //RunningMeasures contains:
    //- image_ids:          IDs of the images.
    //- image_label_ids:    Class IDs of ground truth labels.
    //- top1_predictions:   Class IDs of the top predicted class.
    //- topk_predictions:   Class IDs of top-K predicted classes.
    SetDictTuple((*hv_RunningMeasures), "image_ids", HTuple());
    SetDictTuple((*hv_RunningMeasures), "image_label_ids", HTuple());
    SetDictTuple((*hv_RunningMeasures), "top1_predictions", HTuple());
    SetDictTuple((*hv_RunningMeasures), "topk_predictions", HTuple());
  }
  else if (0 != (int(hv_EvaluationType==HTuple("multi_label_classification"))))
  {
    //RunningMeasures contains:
    //- image_ids:        IDs of the images.
    //- correct_predictions: The number of correctly classified samples
    //- class_{class_id}: A dictionary for each class
    //  -- ground_truth     A tuple with the ground_truth labels
    //  -- confidences      A tuple with the prediction confidence values
    //  -- tp               The number of true positives at min_confidence threshold
    //  -- fp               The number of false positives at min_confidence threshold
    //  -- fn               The number of false negatives at min_confidence threshold
    //  -- f_score          The f_score at min_confidence threshold
    SetDictTuple((*hv_RunningMeasures), "image_ids", HTuple());
    SetDictTuple((*hv_RunningMeasures), "correct_predictions", 0);
    {
    HTuple end_val79 = (hv_ClassIDs.TupleLength())-1;
    HTuple step_val79 = 1;
    for (hv_Index=0; hv_Index.Continue(end_val79, step_val79); hv_Index += step_val79)
    {
      CreateDict(&hv_ClassDict);
      SetDictTuple(hv_ClassDict, "ground_truth", HTuple());
      SetDictTuple(hv_ClassDict, "confidences", HTuple());
      //
      SetDictTuple(hv_ClassDict, "tp", 0);
      SetDictTuple(hv_ClassDict, "fp", 0);
      SetDictTuple(hv_ClassDict, "fn", 0);
      hv_ClassKey = "class_"+HTuple(hv_ClassIDs[hv_Index]);
      SetDictTuple((*hv_RunningMeasures), hv_ClassKey, hv_ClassDict);
    }
    }
  }
  else if (0 != (HTuple(int(hv_EvaluationType==HTuple("detection"))).TupleOr(int(hv_EvaluationType==HTuple("ocr_detection")))))
  {
    //RunningMeasures contains:
    //For each maximal number of regions (MaxNumDetections):
    // - For each area range (AreaRanges):
    //   -- confidence:     Confidence (score) of each result.
    //   -- num_gt:         Total number of ground truth instances per class.
    //   -- num_pred:       Total number of predictions per class.
    //   -- num_gt_ignore:  Number of ignored ground truth instances per class.
    //   -- for each IoU-threshold:
    //      --- For each class:
    //          ---- is_tp:                  TP/FP assignment of result.
    //          ---- ignore:                 Ignore/Not-Ignore assignment of result.
    //          ---- abs_orientation_diff (for instance_type 'rectangle2' with measure SoAP):
    //                                       Absolute orientation difference of the result.
    //
    //Check if the orientation difference is to be evaluated.
    GetDictTuple(hv_EvalParams, "instance_type", &hv_InstanceType);
    hv_EvalOrientation = 0;
    if (0 != (HTuple(int(hv_InstanceType==HTuple("rectangle2"))).TupleAnd(HTuple(int((hv_Measures.TupleFind("soap"))!=-1)).TupleOr(int((hv_Measures.TupleFind("all"))!=-1)))))
    {
      hv_EvalOrientation = 1;
    }
    //
    //Calculating the measures confidence, is_tp, ignore, and abs_orientation_diff,
    //arrays are allocated with -1 in blocks of AllocationBlockLength
    //(thus, if a block is filled, the next block is allocated).
    //Otherwise the arrays have to be concatenated which is rather slow.
    //The actual length of the array is garnered in num_pred.
    GetDictTuple(hv_EvalParams, "allocation_block_length", &hv_AllocationBlockLength);
    GetDictTuple(hv_EvalParams, "iou_threshold", &hv_IoUThreshs);
    GetDictTuple(hv_EvalParams, "max_num_detections", &hv_MaxNumDetections);
    GetDictTuple(hv_EvalParams, "area_ranges", &hv_AreaRanges);
    //AreaRanges is a dictionary containing 'name', 'min_area', 'max_area'.
    GetDictTuple(hv_AreaRanges, "name", &hv_AreaNames);
    GetDictTuple(hv_AreaRanges, "min", &hv_MinAreas);
    GetDictTuple(hv_AreaRanges, "max", &hv_MaxAreas);
    //Check if a detailed evaluation will be performed.
    GetDictTuple(hv_EvalParams, "detailed_evaluation", &hv_DetailedEvaluation);
    //Set a result dictionary for each maximal number of detections and IoU-threshold.
    {
    HTuple end_val128 = (hv_MaxNumDetections.TupleLength())-1;
    HTuple step_val128 = 1;
    for (hv_MaxNumIdx=0; hv_MaxNumIdx.Continue(end_val128, step_val128); hv_MaxNumIdx += step_val128)
    {
      hv_MaxNum = HTuple(hv_MaxNumDetections[hv_MaxNumIdx]);
      CreateDict(&hv_CurrentRunningMeasure);
      {
      HTuple end_val131 = (hv_AreaNames.TupleLength())-1;
      HTuple step_val131 = 1;
      for (hv_AreaIdx=0; hv_AreaIdx.Continue(end_val131, step_val131); hv_AreaIdx += step_val131)
      {
        CreateDict(&hv_AreaRunningMeasure);
        {
        HTuple end_val133 = (hv_IoUThreshs.TupleLength())-1;
        HTuple step_val133 = 1;
        for (hv_I=0; hv_I.Continue(end_val133, step_val133); hv_I += step_val133)
        {
          CreateDict(&hv_IoURunningMeasure);
          {
          HTuple end_val135 = hv_NumClasses-1;
          HTuple step_val135 = 1;
          for (hv_ClsIdx=0; hv_ClsIdx.Continue(end_val135, step_val135); hv_ClsIdx += step_val135)
          {
            CreateDict(&hv_ClassRunningMeasures);
            SetDictTuple(hv_ClassRunningMeasures, "is_tp", HTuple(hv_AllocationBlockLength,-1));
            SetDictTuple(hv_ClassRunningMeasures, "ignore", HTuple(hv_AllocationBlockLength,-1));
            if (0 != hv_EvalOrientation)
            {
              SetDictTuple(hv_ClassRunningMeasures, "abs_orientation_diff", HTuple(hv_AllocationBlockLength,-1));
            }
            if (0 != hv_DetailedEvaluation)
            {
              SetDictTuple(hv_ClassRunningMeasures, "is_fp_class", HTuple(hv_AllocationBlockLength,-1));
              SetDictTuple(hv_ClassRunningMeasures, "is_fp_background", HTuple(hv_AllocationBlockLength,-1));
              SetDictTuple(hv_ClassRunningMeasures, "is_fp_localization", HTuple(hv_AllocationBlockLength,-1));
              SetDictTuple(hv_ClassRunningMeasures, "is_fp_duplicate", HTuple(hv_AllocationBlockLength,-1));
              SetDictTuple(hv_ClassRunningMeasures, "is_fp_multiple", HTuple(hv_AllocationBlockLength,-1));
              if (0 != hv_EvalOrientation)
              {
                SetDictTuple(hv_ClassRunningMeasures, "abs_orientation_diff_class", 
                    HTuple(hv_AllocationBlockLength,-1));
                SetDictTuple(hv_ClassRunningMeasures, "abs_orientation_diff_localization", 
                    HTuple(hv_AllocationBlockLength,-1));
                SetDictTuple(hv_ClassRunningMeasures, "abs_orientation_diff_duplicate", 
                    HTuple(hv_AllocationBlockLength,-1));
                SetDictTuple(hv_ClassRunningMeasures, "abs_orientation_diff_multiple", 
                    HTuple(hv_AllocationBlockLength,-1));
              }
              SetDictTuple(hv_IoURunningMeasure, "image_ids_with_false_negatives", 
                  HTuple(hv_AllocationBlockLength,-1));
              SetDictTuple(hv_IoURunningMeasure, "image_ids_with_false_positives", 
                  HTuple(hv_AllocationBlockLength,-1));
              SetDictTuple(hv_IoURunningMeasure, "num_image_ids_with_false_negatives", 
                  0);
              SetDictTuple(hv_IoURunningMeasure, "num_image_ids_with_false_positives", 
                  0);
            }
            SetDictTuple(hv_IoURunningMeasure, "class_"+HTuple(hv_ClassIDs[hv_ClsIdx]), 
                hv_ClassRunningMeasures);
          }
          }
          SetDictTuple(hv_AreaRunningMeasure, "iou_"+((""+HTuple(hv_IoUThreshs[hv_I])).TupleRegexpReplace("\\.","")), 
              hv_IoURunningMeasure);
        }
        }
        CreateDict(&hv_Confidence);
        {
        HTuple end_val164 = hv_NumClasses-1;
        HTuple step_val164 = 1;
        for (hv_ClsIdx=0; hv_ClsIdx.Continue(end_val164, step_val164); hv_ClsIdx += step_val164)
        {
          SetDictTuple(hv_Confidence, "class_"+HTuple(hv_ClassIDs[hv_ClsIdx]), HTuple(hv_AllocationBlockLength,-1.0));
        }
        }
        SetDictTuple(hv_AreaRunningMeasure, "confidence", hv_Confidence);
        SetDictTuple(hv_AreaRunningMeasure, "num_gt", HTuple(hv_NumClasses,0));
        SetDictTuple(hv_AreaRunningMeasure, "num_pred", HTuple(hv_NumClasses,0));
        SetDictTuple(hv_AreaRunningMeasure, "num_gt_ignore", HTuple(hv_NumClasses,0));
        SetDictTuple(hv_CurrentRunningMeasure, "area_"+HTuple(hv_AreaNames[hv_AreaIdx]), 
            hv_AreaRunningMeasure);
      }
      }
      if (0 != (int(hv_MaxNum==-1)))
      {
        hv_MaxNum = "all";
      }
      SetDictTuple((*hv_RunningMeasures), "max_num_detections_"+hv_MaxNum, hv_CurrentRunningMeasure);
    }
    }
  }
  else if (0 != (int(hv_EvaluationType==HTuple("segmentation"))))
  {
    //RunningMeasures contains:
    //if confusion matrix in Measures (slower but more information).
    // - confusion matrix per pixel.
    //else:
    // - TP/FP/FN (pixel numbers per class).
    //
    //Incorporate ignore class IDs.
    GetDictTuple(hv_EvalParams, "ignore_class_ids", &hv_IgnoreClassIDs);
    //
    //Check if we need to compute/update the confusion matrix.
    hv_CalcConfMatrix = HTuple(int((hv_Measures.TupleFind("pixel_confusion_matrix"))>-1)).TupleOr(int((hv_Measures.TupleFind("all"))>-1));
    if (0 != hv_CalcConfMatrix)
    {
      //Define the size of the confusion matrix.
      hv_MatrixSize = hv_NumClasses+(int((hv_IgnoreClassIDs.TupleLength())>0));
      CreateMatrix(hv_MatrixSize, hv_MatrixSize, 0, &hv_PixelConfusionMatrix);
      SetDictTuple((*hv_RunningMeasures), "pixel_confusion_matrix", hv_PixelConfusionMatrix);
      //
      //If the class IDs are not running indices from 0 to NumClasses we
      //define a mapping from class IDs to class indices.
      if (0 != (HTuple(int(hv_ClassIDs!=HTuple::TupleGenSequence(0,(hv_ClassIDs.TupleLength())-1,1))).TupleOr(int((hv_IgnoreClassIDs.TupleLength())>0))))
      {
        //Get the max ID that can occur.
        hv_MaxId = (hv_ClassIDs.TupleMax())+(int((hv_IgnoreClassIDs.TupleLength())>0));
        //Define the basic mapping.
        TupleGenConst(hv_MaxId+1, -1, &hv_ClsIDToClsIdx);
        hv_ClsIDToClsIdx[hv_ClassIDs] = HTuple::TupleGenSequence(0,(hv_ClassIDs.TupleLength())-1,1);
        //Map ignore IDs to the next higher one.
        hv_ClsIDToClsIdx[hv_IgnoreClassIDs] = (hv_ClsIDToClsIdx.TupleMax())+1;
        //Set the mapping to the evaluation parameters.
        SetDictTuple(hv_EvalParams, "class_id_mapping", hv_ClsIDToClsIdx);
      }
    }
    else
    {
      hv_TP = HTuple(hv_NumClasses,0);
      hv_FP = HTuple(hv_NumClasses,0);
      hv_FN = HTuple(hv_NumClasses,0);
      SetDictTuple((*hv_RunningMeasures), "tp", hv_TP);
      SetDictTuple((*hv_RunningMeasures), "fp", hv_FP);
      SetDictTuple((*hv_RunningMeasures), "fn", hv_FN);
    }
  }
  else if (0 != (int(hv_EvaluationType==HTuple("ocr_recognition"))))
  {
    //RunningMeasures for OCR recognition models.
    SetDictTuple((*hv_RunningMeasures), "image_ids", HTuple());
    SetDictTuple((*hv_RunningMeasures), "words_ground_truth", HTuple());
    SetDictTuple((*hv_RunningMeasures), "words_prediction", HTuple());
  }
  //
  //Add out-of-distribution detection items if necessary.
  if (0 != (hv_EvalParams.TupleGetDictTuple("calculate_ood_measures")))
  {
    //RunningMeasures additionally contains:
    //- ood_predictions:    Out-of-distribution detection predictions.
    //- ood_scores:         Out-of-distribution scores.
    //For in-distribution samples, these are stored directly
    //in entries of RunningMeasures.
    //For out-of-distribution samples, they are stored in the
    //sub-dictionary RunningMeasures.evaluated_ood_samples.
    //Additionally, the IDs of the out-of-distribution images
    //are stored in RunningMeasures.evaluated_ood_samples.image_ids.
    SetDictTuple((*hv_RunningMeasures), "ood_predictions", HTuple());
    SetDictTuple((*hv_RunningMeasures), "ood_scores", HTuple());
    CreateDict(&hv___Tmp_Ctrl_Dict_Init_1);
    SetDictTuple((*hv_RunningMeasures), "evaluated_ood_samples", hv___Tmp_Ctrl_Dict_Init_1);
    hv___Tmp_Ctrl_Dict_Init_1 = HTuple::TupleConstant("HNULL");
    SetDictTuple((*hv_RunningMeasures).TupleGetDictTuple("evaluated_ood_samples"), 
        "image_ids", HTuple());
    SetDictTuple((*hv_RunningMeasures).TupleGetDictTuple("evaluated_ood_samples"), 
        "ood_predictions", HTuple());
    SetDictTuple((*hv_RunningMeasures).TupleGetDictTuple("evaluated_ood_samples"), 
        "ood_scores", HTuple());
  }
  //
  return;
}

// Chapter: Deep Learning / Model
// Short Description: Initialize change strategies data. 
void init_train_dl_model_change_strategies (HTuple hv_TrainParam, HTuple *hv_ChangeStrategyData)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_ChangeStrategies, hv_Enabled, hv_Index;
  HTuple  hv_ChangeStrategy, hv_ModelParam, hv_Epochs, hv_Values;
  HTuple  hv_Initial, hv_Indices, hv_ScaleThresholdExists;

  //
  //Initialize a dictionary with the change strategies data.
  CreateDict(&(*hv_ChangeStrategyData));
  GetDictTuple(hv_TrainParam, "change_strategies", &hv_ChangeStrategies);
  hv_Enabled = int((hv_ChangeStrategies.TupleLength())>0);
  SetDictTuple((*hv_ChangeStrategyData), "enabled", hv_Enabled);
  if (0 != (hv_Enabled.TupleNot()))
  {
    return;
  }
  //
  //Sort all epochs in all change strategies.
  {
  HTuple end_val11 = (hv_ChangeStrategies.TupleLength())-1;
  HTuple step_val11 = 1;
  for (hv_Index=0; hv_Index.Continue(end_val11, step_val11); hv_Index += step_val11)
  {
    hv_ChangeStrategy = HTuple(hv_ChangeStrategies[hv_Index]);
    GetDictTuple(hv_ChangeStrategy, "model_param", &hv_ModelParam);
    GetDictTuple(hv_ChangeStrategy, "epochs", &hv_Epochs);
    GetDictTuple(hv_ChangeStrategy, "values", &hv_Values);
    GetDictTuple(hv_ChangeStrategy, "initial_value", &hv_Initial);
    //Check that the length are equal.
    if (0 != (int((hv_Epochs.TupleLength())!=(hv_Values.TupleLength()))))
    {
      throw HException("ChangeStrategy parameter error: 'epochs' and 'values' need to have same length.");
    }
    //We need sorted arrays for faster access.
    TupleSortIndex(hv_Epochs, &hv_Indices);
    SetDictTuple(hv_ChangeStrategy, "epochs", HTuple(hv_Epochs[hv_Indices]));
    SetDictTuple(hv_ChangeStrategy, "values", HTuple(hv_Values[hv_Indices]));
    //
    //For the learning rate, there can be an additional parameter
    //indicating if the momentum should be scaled as well.
    if (0 != (int(hv_ModelParam==HTuple("learning_rate"))))
    {
      GetDictParam(hv_ChangeStrategy, "key_exists", "scale_momentum_threshold", &hv_ScaleThresholdExists);
      if (0 != (hv_ScaleThresholdExists.TupleNot()))
      {
        //If not given, the threshold is set to an empty tuple such that no scaling is performed.
        SetDictTuple(hv_ChangeStrategy, "scale_momentum_threshold", HTuple());
      }
    }
  }
  }
  SetDictTuple((*hv_ChangeStrategyData), "strategies", hv_ChangeStrategies);
  return;
}

// Chapter: Deep Learning / Model
// Short Description: Initialize the dictionary setting for serialization strategies. 
void init_train_dl_model_serialization_strategies (HTuple hv_TrainParam, HTuple *hv_SerializationData)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_SerializationStrategies, hv_RawData;
  HTuple  hv_Types, hv_SerializeFinal, hv_Index, hv_Strategy;
  HTuple  hv_Type, hv_Data, hv_Epochs, hv_NumEpochs;

  //
  //This procedure initializes the dictionary setting the serialization strategies.
  //
  //Initialize each serialization strategy.
  GetDictTuple(hv_TrainParam, "serialization_strategies", &hv_SerializationStrategies);
  CreateDict(&(*hv_SerializationData));
  SetDictTuple((*hv_SerializationData), "strategies", hv_SerializationStrategies);
  hv_RawData = HTuple();
  hv_Types = HTuple();
  hv_SerializeFinal = 0;
  {
  HTuple end_val10 = (hv_SerializationStrategies.TupleLength())-1;
  HTuple step_val10 = 1;
  for (hv_Index=0; hv_Index.Continue(end_val10, step_val10); hv_Index += step_val10)
  {
    hv_Strategy = HTuple(hv_SerializationStrategies[hv_Index]);
    GetDictTuple(hv_Strategy, "type", &hv_Type);
    CreateDict(&hv_Data);
    if (0 != (int(hv_Type==HTuple("best"))))
    {
      SetDictTuple(hv_Data, "best_value", -1);
    }
    else if (0 != (int(hv_Type==HTuple("epochs"))))
    {
      GetDictTuple(hv_Strategy, "epochs", &hv_Epochs);
      //Store sorted values in order to search faster during updates.
      TupleSort(hv_Epochs, &hv_Epochs);
      SetDictTuple(hv_Data, "epochs", hv_Epochs);
      SetDictTuple(hv_Data, "last_epoch_index", -1);
    }
    else if (0 != (int(hv_Type==HTuple("current"))))
    {
      GetDictTuple(hv_TrainParam, "num_epochs", &hv_NumEpochs);
      SetDictTuple(hv_Data, "epochs", HTuple::TupleGenSequence(1,hv_NumEpochs,1));
      SetDictTuple(hv_Data, "last_epoch_index", -1);
    }
    else if (0 != (int(hv_Type==HTuple("final"))))
    {
      SetDictTuple(hv_Data, "serialize_final", 1);
    }
    else
    {
      throw HException(("Unknown serialization strategy type: '"+hv_Type)+"'");
    }
    hv_Types = hv_Types.TupleConcat(hv_Type);
    hv_RawData = hv_RawData.TupleConcat(hv_Data);
  }
  }
  SetDictTuple((*hv_SerializationData), "raw_data", hv_RawData);
  SetDictTuple((*hv_SerializationData), "types", hv_Types);
  return;
}

// Chapter: 3D Object Model / Features
void inspect_normal_direction (HObject ho_MenuRegions, HTuple hv_WindowHandle1, HTuple hv_WindowHandle2, 
    HTuple hv_WindowHandleMenu, HTuple hv_SurfaceModelID, HTuple hv_ObjectModel3DScene, 
    HTuple hv_RelSamplingDistance, HTuple hv_KeyPointFraction, HTuple hv_MinScore, 
    HTuple hv_GenParamNames, HTuple hv_GenParamValues, HTuple hv_SurfaceMatchingResultID, 
    HTuple hv_MenuText, HTuple hv_CurrentCase, HTuple hv_CasesDone, HTuple hv_FontSize, 
    HTuple hv_WindowScaling, HTuple *hv_CreateNames, HTuple *hv_CreateValues, HTuple *hv_FindNames, 
    HTuple *hv_FindValues)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_Instructions, hv_SampledScene, hv_SampledModel;
  HTuple  hv_VC_P_Model, hv_VC_P_Scene, hv_NXYZOrig, hv_MessageQueues1;
  HTuple  hv_Buttons, hv_ShowNormals1, hv_MessageQueues2;
  HTuple  hv_ShowNormals2, hv_PreviousState1, hv_PreviousState2;
  HTuple  hv_DidFinish1, hv_DidFinish2, hv_Row, hv_Column;
  HTuple  hv_Width, hv_Height, hv_WindowHandleBufferMenu;
  HTuple  hv_SceneFast, hv_SceneMLS, hv_SceneNormalsInverted;
  HTuple  hv_SceneNormalsToggled, hv_NormalCompMode, hv_Edges3DTrained;
  HTuple  hv_SceneHasMapping, hv_SceneHasNormals, hv_FastMethod;
  HTuple  hv_ModelNormalsInverted, hv_ModelNormalsToggled;
  HTuple  hv_Message, hv_MessageChanged, hv_ButtonPressed;
  HTuple  hv_Poses, hv_NXYZ, hv_MessageHandle, hv_Pose, hv_Score;
  HTuple  hv_Indices, hv_Row1, hv_Column1, hv_Row2, hv_Column2;
  HTuple  hv_TIT;
  HTupleVector  hvec_TI(1);

  // +++ Threading variables 
  HDevThread*         hcppthread_handle;
  HDevThreadContext   hcppthread_context; // <-signals begin of procedure

  hv_Instructions[0] = "Rotate: Left mouse button";
  hv_Instructions[1] = "Zoom:   Shift + left mouse button";
  hv_Instructions[2] = "Move:   Ctrl  + left mouse button";
  //
  GetSurfaceMatchingResult(hv_SurfaceMatchingResultID, "sampled_scene", HTuple(), 
      &hv_SampledScene);
  GetSurfaceModelParam(hv_SurfaceModelID, "sampled_model", &hv_SampledModel);
  //
  //Visualization of the model's normals
  estimate_visualization_pose_object_model_3d(hv_SampledModel, hv_WindowHandle1, 
      &hv_VC_P_Model);
  //
  //Visualization of the scene's normals
  estimate_visualization_pose_object_model_3d(hv_SampledScene, hv_WindowHandle2, 
      &hv_VC_P_Scene);
  //
  GetObjectModel3dParams(hv_SampledModel, HTuple("point_normal_")+((HTuple("x").Append("y")).Append("z")), 
      &hv_NXYZOrig);
  //
  create_visualization_message_queues(&hv_MessageQueues1);
  hv_Buttons.Clear();
  hv_Buttons[0] = "Continue";
  hv_Buttons[1] = "right";
  hv_Buttons[2] = "bottom";
  hv_Buttons[3] = -1;
  hv_Buttons[4] = -1;
  hv_Buttons[5] = "Invert Normals";
  hv_Buttons[6] = "left";
  hv_Buttons[7] = "bottom";
  hv_Buttons[8] = -1;
  hv_Buttons[9] = -1;
  hv_Buttons[10] = "Hide Normals";
  hv_Buttons[11] = "center";
  hv_Buttons[12] = "bottom";
  hv_Buttons[13] = -1;
  hv_Buttons[14] = -1;
  hv_ShowNormals1 = 1;
  // Create a thread instance
  hcppthread_handle = new HDevThread(hcppthread_context,
              (void*)HDevExportCpp::_hcppthread_visualize_object_model_3d_ext,15,0);
  // Set thread procedure call arguments 
  hcppthread_handle->SetInputCtrlParamTuple(0,hv_WindowHandle1);
  hcppthread_handle->SetInputCtrlParamTuple(1,hv_SampledModel);
  hcppthread_handle->SetInputCtrlParamTuple(2,HTuple());
  hcppthread_handle->SetInputCtrlParamTuple(3,hv_VC_P_Model);
  hcppthread_handle->SetInputCtrlParamTuple(4,(((HTuple("color_0").Append("normal_color_0")).Append("disp_normals")).Append("disp_pose")));
  hcppthread_handle->SetInputCtrlParamTuple(5,(((HTuple("cyan").Append("gray")).Append("true")).Append("true")));
  hcppthread_handle->SetInputCtrlParamTuple(6,"Model");
  hcppthread_handle->SetInputCtrlParamTuple(7,HTuple());
  hcppthread_handle->SetInputCtrlParamTuple(8,hv_Instructions);
  hcppthread_handle->SetInputCtrlParamTuple(9,hv_MessageQueues1);
  hcppthread_handle->SetInputCtrlParamTuple(10,hv_Buttons);
  hcppthread_handle->SetInputCtrlParamTuple(11,HTuple());
  hcppthread_handle->SetInputCtrlParamTuple(12,HTuple());
  hcppthread_handle->SetInputCtrlParamTuple(13,"false");
  hcppthread_handle->SetInputCtrlParamTuple(14,HTuple());

  // Start proc line in thread
  hcppthread_handle->ParStart(&hvec_TI[0].T());


  create_visualization_message_queues(&hv_MessageQueues2);
  hv_Buttons.Clear();
  hv_Buttons[0] = "Hide Normals";
  hv_Buttons[1] = "center";
  hv_Buttons[2] = "bottom";
  hv_Buttons[3] = -1;
  hv_Buttons[4] = -1;
  hv_Buttons[5] = "Normals: fast";
  hv_Buttons[6] = "right";
  hv_Buttons[7] = "bottom";
  hv_Buttons[8] = -1;
  hv_Buttons[9] = -1;
  hv_Buttons[10] = "Normals: mls ";
  hv_Buttons[11] = "right";
  hv_Buttons[12] = "above_bottom";
  hv_Buttons[13] = -1;
  hv_Buttons[14] = -1;
  hv_Buttons[15] = "Invert Normals";
  hv_Buttons[16] = "left";
  hv_Buttons[17] = "bottom";
  hv_Buttons[18] = -1;
  hv_Buttons[19] = -1;
  hv_ShowNormals2 = 1;
  // Create a thread instance
  hcppthread_handle = new HDevThread(hcppthread_context,
              (void*)HDevExportCpp::_hcppthread_visualize_object_model_3d_ext,15,0);
  // Set thread procedure call arguments 
  hcppthread_handle->SetInputCtrlParamTuple(0,hv_WindowHandle2);
  hcppthread_handle->SetInputCtrlParamTuple(1,hv_SampledScene);
  hcppthread_handle->SetInputCtrlParamTuple(2,HTuple());
  hcppthread_handle->SetInputCtrlParamTuple(3,hv_VC_P_Scene);
  hcppthread_handle->SetInputCtrlParamTuple(4,(((HTuple("color_0").Append("normal_color_0")).Append("disp_normals")).Append("disp_pose")));
  hcppthread_handle->SetInputCtrlParamTuple(5,(((HTuple("cyan").Append("gray")).Append("true")).Append("true")));
  hcppthread_handle->SetInputCtrlParamTuple(6,"Scene");
  hcppthread_handle->SetInputCtrlParamTuple(7,HTuple());
  hcppthread_handle->SetInputCtrlParamTuple(8,hv_Instructions);
  hcppthread_handle->SetInputCtrlParamTuple(9,hv_MessageQueues2);
  hcppthread_handle->SetInputCtrlParamTuple(10,hv_Buttons);
  hcppthread_handle->SetInputCtrlParamTuple(11,HTuple());
  hcppthread_handle->SetInputCtrlParamTuple(12,HTuple());
  hcppthread_handle->SetInputCtrlParamTuple(13,"false");
  hcppthread_handle->SetInputCtrlParamTuple(14,HTuple());

  // Start proc line in thread
  hcppthread_handle->ParStart(&hvec_TI[1].T());

  hv_PreviousState1 = HTuple();
  hv_PreviousState2 = HTuple();
  hv_DidFinish1 = 0;
  hv_DidFinish2 = 0;
  //
  //Open a second (invisible) buffer window to avoid flickering
  GetWindowExtents(hv_WindowHandleMenu, &hv_Row, &hv_Column, &hv_Width, &hv_Height);
  OpenWindow(0, 0, hv_Width, hv_Height, 0, "buffer", "", &hv_WindowHandleBufferMenu);
  SetPart(hv_WindowHandleBufferMenu, 0, 0, hv_Height-1, hv_Width-1);
  set_display_font(hv_WindowHandleBufferMenu, hv_FontSize, "mono", "true", "false");
  //
  //Cached scene normals
  hv_SceneFast = HTuple();
  hv_SceneMLS = HTuple();
  GetSurfaceMatchingResult(hv_SurfaceMatchingResultID, "scene_invert_normals", HTuple(), 
      &hv_SceneNormalsInverted);
  if (0 != (int(hv_SceneNormalsInverted==HTuple("true"))))
  {
    hv_SceneNormalsToggled = 1;
  }
  else
  {
    hv_SceneNormalsToggled = 0;
  }
  get_find_parameter(hv_GenParamNames, hv_GenParamValues, "scene_normal_computation", 
      "fast", &hv_NormalCompMode);
  GetSurfaceModelParam(hv_SurfaceModelID, "3d_edges_trained", &hv_Edges3DTrained);
  GetObjectModel3dParams(hv_ObjectModel3DScene, "has_xyz_mapping", &hv_SceneHasMapping);
  GetObjectModel3dParams(hv_ObjectModel3DScene, "has_point_normals", &hv_SceneHasNormals);
  if (0 != (HTuple(int(hv_Edges3DTrained==HTuple("true"))).TupleAnd(int(hv_SceneHasMapping==HTuple("true")))))
  {
    hv_FastMethod = HTuple("(default, using XYZ-mapping)");
  }
  else
  {
    if (0 != (int(hv_SceneHasNormals==HTuple("true"))))
    {
      hv_FastMethod = HTuple("(default, using existing scene normals)");
    }
    else
    {
      hv_FastMethod = HTuple("(default, using XYZ-mapping)");
    }
  }
  //Model normals
  GetSurfaceMatchingResult(hv_SurfaceMatchingResultID, "model_invert_normals", HTuple(), 
      &hv_ModelNormalsInverted);
  if (0 != (int(hv_ModelNormalsInverted==HTuple("true"))))
  {
    hv_ModelNormalsToggled = 1;
  }
  else
  {
    hv_ModelNormalsToggled = 0;
  }
  (*hv_CreateNames) = HTuple();
  (*hv_CreateValues) = HTuple();
  (*hv_FindNames) = HTuple();
  (*hv_FindValues) = HTuple();
  //
  hv_Message[0] = HTuple("Check visually, if the normals of the model point approximately in the same direction as the normals of the scene by moving the model and the scene accordingly");
  if (0 != (hv_ModelNormalsToggled.TupleNot()))
  {
    hv_Message[1] = "Model normals are not inverted (default)";
  }
  else
  {
    hv_Message[1] = "Model normals are inverted";
  }
  if (0 != (hv_SceneNormalsToggled.TupleNot()))
  {
    hv_Message[2] = "Scene normals are not inverted (default)";
  }
  else
  {
    hv_Message[2] = "Scene normals are inverted";
  }
  if (0 != (int(hv_NormalCompMode==HTuple("fast"))))
  {
    hv_Message[3] = "Scene normals are computed based on the fast method "+hv_FastMethod;
  }
  else if (0 != (int(hv_NormalCompMode==HTuple("mls"))))
  {
    hv_Message[3] = "Scene normals are computed based on the mls method";
  }
  else
  {
    hv_Message[3] = "Scene normals are computed based on an unknown method";
  }
  hv_MessageChanged = 1;
  //
  do
  {
    //Process first visualization window
    process_visualize_events_generic(hv_WindowHandle1, hv_MessageQueues1, hv_PreviousState1, 
        &hv_DidFinish1, &hv_PreviousState1, &hv_ButtonPressed, &hv_Poses);

    if (0 != (HTuple(int(hv_ButtonPressed==0)).TupleOr(hv_DidFinish1)))
    {
      //Exit-button
      break;
    }
    else if (0 != (int(hv_ButtonPressed==1)))
    {
      //Invert Model Normals
      GetObjectModel3dParams(hv_SampledModel, HTuple("point_normal_")+((HTuple("x").Append("y")).Append("z")), 
          &hv_NXYZ);
      SetObjectModel3dAttribMod(hv_SampledModel, HTuple("point_normal_")+((HTuple("x").Append("y")).Append("z")), 
          HTuple(), -hv_NXYZ);
      //Redraw to show the flipped normals
      CreateMessage(&hv_MessageHandle);
      SetMessageTuple(hv_MessageHandle, "type", "force_redraw");
      EnqueueMessage(HTuple(hv_MessageQueues1[1]), hv_MessageHandle, HTuple(), HTuple());
      hv_ModelNormalsToggled = hv_ModelNormalsToggled.TupleNot();
      //Update parameter display
      if (0 != (hv_ModelNormalsToggled.TupleNot()))
      {
        hv_Message[1] = "Model normals are not inverted (default)";
        (*hv_CreateNames) = HTuple();
        (*hv_CreateValues) = HTuple();
      }
      else
      {
        hv_Message[1] = "Model normals are inverted";
        (*hv_CreateNames) = "model_invert_normals";
        (*hv_CreateValues) = "true";
      }
      hv_MessageChanged = 1;
    }
    else if (0 != (int(hv_ButtonPressed==2)))
    {
      //Toggle normals
      hv_ShowNormals1 = hv_ShowNormals1.TupleNot();
      CreateMessage(&hv_MessageHandle);
      SetMessageTuple(hv_MessageHandle, "type", "toggle_param");
      SetMessageTuple(hv_MessageHandle, "param", "disp_normals");
      EnqueueMessage(HTuple(hv_MessageQueues1[1]), hv_MessageHandle, HTuple(), HTuple());
      CreateMessage(&hv_MessageHandle);
      SetMessageTuple(hv_MessageHandle, "type", "change_button_text");
      SetMessageTuple(hv_MessageHandle, "index", 2);
      if (0 != hv_ShowNormals1)
      {
        SetMessageTuple(hv_MessageHandle, "text", "Hide Normals");
      }
      else
      {
        SetMessageTuple(hv_MessageHandle, "text", "Show Normals");
      }
      EnqueueMessage(HTuple(hv_MessageQueues1[1]), hv_MessageHandle, HTuple(), HTuple());
    }

    //Process second visualization window
    process_visualize_events_generic(hv_WindowHandle2, hv_MessageQueues2, hv_PreviousState2, 
        &hv_DidFinish2, &hv_PreviousState2, &hv_ButtonPressed, &hv_Pose);

    if (0 != (int(hv_ButtonPressed==0)))
    {
      hv_ShowNormals2 = hv_ShowNormals2.TupleNot();
      //Toggle normals
      CreateMessage(&hv_MessageHandle);
      SetMessageTuple(hv_MessageHandle, "type", "toggle_param");
      SetMessageTuple(hv_MessageHandle, "param", "disp_normals");
      EnqueueMessage(HTuple(hv_MessageQueues2[1]), hv_MessageHandle, HTuple(), HTuple());
      CreateMessage(&hv_MessageHandle);
      SetMessageTuple(hv_MessageHandle, "type", "change_button_text");
      SetMessageTuple(hv_MessageHandle, "index", 0);
      if (0 != hv_ShowNormals2)
      {
        SetMessageTuple(hv_MessageHandle, "text", "Hide Normals");
      }
      else
      {
        SetMessageTuple(hv_MessageHandle, "text", "Show Normals");
      }
      EnqueueMessage(HTuple(hv_MessageQueues2[1]), hv_MessageHandle, HTuple(), HTuple());
    }
    else if (0 != (int(hv_ButtonPressed==1)))
    {
      //FAST
      //Use very fast find parameters, since we are only interested in the sampled scene
      if (0 != (int(hv_SceneFast==HTuple())))
      {
        FindSurfaceModel(hv_SurfaceModelID, hv_ObjectModel3DScene, hv_RelSamplingDistance, 
            0.00001, 0, "true", ((HTuple("dense_pose_refinement").Append("sparse_pose_refinement")).Append("scene_normal_computation")), 
            ((HTuple("false").Append("false")).Append("fast")), &hv_Pose, &hv_Score, 
            &hv_SurfaceMatchingResultID);
        GetSurfaceMatchingResult(hv_SurfaceMatchingResultID, "sampled_scene", 0, 
            &hv_SceneFast);
      }
      //Send the new 3D object model to the visualization thread
      CreateMessage(&hv_MessageHandle);
      SetMessageTuple(hv_MessageHandle, "type", "replace_object_model");
      SetMessageTuple(hv_MessageHandle, "index", 0);
      SetMessageTuple(hv_MessageHandle, "model", hv_SceneFast);
      EnqueueMessage(HTuple(hv_MessageQueues2[1]), hv_MessageHandle, HTuple(), HTuple());
      hv_SampledScene = hv_SceneFast;
      hv_Message[3] = "Scene normals are computed based on the fast method "+hv_FastMethod;
      hv_MessageChanged = 1;
      TupleFind((*hv_FindNames), "scene_normal_computation", &hv_Indices);
      if (0 != (int(hv_Indices!=-1)))
      {
        TupleRemove((*hv_FindNames), hv_Indices, &(*hv_FindNames));
        TupleRemove((*hv_FindValues), hv_Indices, &(*hv_FindValues));
      }
    }
    else if (0 != (int(hv_ButtonPressed==2)))
    {
      //MLS
      if (0 != (int(hv_SceneMLS==HTuple())))
      {
        //Use very fast find parameters, since we are only interested in the sampled scene
        FindSurfaceModel(hv_SurfaceModelID, hv_ObjectModel3DScene, hv_RelSamplingDistance, 
            0.00001, 0, "true", ((HTuple("dense_pose_refinement").Append("sparse_pose_refinement")).Append("scene_normal_computation")), 
            ((HTuple("false").Append("false")).Append("mls")), &hv_Pose, &hv_Score, 
            &hv_SurfaceMatchingResultID);
        GetSurfaceMatchingResult(hv_SurfaceMatchingResultID, "sampled_scene", 0, 
            &hv_SceneMLS);
      }
      //Send the new 3D object model to the visualization thread
      CreateMessage(&hv_MessageHandle);
      SetMessageTuple(hv_MessageHandle, "type", "replace_object_model");
      SetMessageTuple(hv_MessageHandle, "index", 0);
      SetMessageTuple(hv_MessageHandle, "model", hv_SceneMLS);
      EnqueueMessage(HTuple(hv_MessageQueues2[1]), hv_MessageHandle, HTuple(), HTuple());
      hv_SampledScene = hv_SceneMLS;
      hv_Message[3] = "Scene normals are computed based on the mls method";
      hv_MessageChanged = 1;
      (*hv_FindNames) = (*hv_FindNames).TupleConcat("scene_normal_computation");
      (*hv_FindValues) = (*hv_FindValues).TupleConcat("mls");
    }
    else if (0 != (int(hv_ButtonPressed==3)))
    {
      //Invert Scene Normals
      GetObjectModel3dParams(hv_SampledScene, HTuple("point_normal_")+((HTuple("x").Append("y")).Append("z")), 
          &hv_NXYZ);
      SetObjectModel3dAttribMod(hv_SampledScene, HTuple("point_normal_")+((HTuple("x").Append("y")).Append("z")), 
          HTuple(), -hv_NXYZ);
      //Redraw to show the flipped normals
      CreateMessage(&hv_MessageHandle);
      SetMessageTuple(hv_MessageHandle, "type", "force_redraw");
      EnqueueMessage(HTuple(hv_MessageQueues2[1]), hv_MessageHandle, HTuple(), HTuple());
      hv_SceneNormalsToggled = hv_SceneNormalsToggled.TupleNot();
      //Update parameter display
      if (0 != (hv_SceneNormalsToggled.TupleNot()))
      {
        hv_Message[2] = "Scene normals are not inverted (default)";
        TupleFind((*hv_FindNames), "scene_invert_normals", &hv_Indices);
        if (0 != (int(hv_Indices!=-1)))
        {
          TupleRemove((*hv_FindNames), hv_Indices, &(*hv_FindNames));
          TupleRemove((*hv_FindValues), hv_Indices, &(*hv_FindValues));
        }
      }
      else
      {
        hv_Message[2] = "Scene normals are inverted";
        (*hv_FindNames) = (*hv_FindNames).TupleConcat("scene_invert_normals");
        (*hv_FindValues) = (*hv_FindValues).TupleConcat("true");
      }
      hv_MessageChanged = 1;
    }

    //Update the menu window
    if (0 != hv_MessageChanged)
    {
      ClearWindow(hv_WindowHandleBufferMenu);
      SetColor(hv_WindowHandleBufferMenu, "black");
      disp_menu_ext(ho_MenuRegions, hv_WindowHandleBufferMenu, hv_MenuText, hv_CasesDone, 
          hv_CurrentCase, hv_WindowScaling);
      //
      SmallestRectangle1(ho_MenuRegions, &hv_Row1, &hv_Column1, &hv_Row2, &hv_Column2);
      SetTposition(hv_WindowHandleBufferMenu, (hv_Row2.TupleMax())+6, 1);
      write_note(hv_WindowHandleBufferMenu, "instruction", HTuple(hv_Message[0]));
      write_note(hv_WindowHandleBufferMenu, "info", HTuple(hv_Message[1]));
      write_note(hv_WindowHandleBufferMenu, "info", HTuple(hv_Message[2]));
      write_note(hv_WindowHandleBufferMenu, "none", HTuple(hv_Message[3]));
      CopyRectangle(hv_WindowHandleBufferMenu, hv_WindowHandleMenu, 0, 0, hv_Height-1, 
          (hv_Width*2)-1, 0, 0);
      hv_MessageChanged = 0;
    }
  }
  while (0 == (hv_DidFinish1.TupleOr(hv_DidFinish2)));
  //
  //Send termination message to all subthreads
  CreateMessage(&hv_MessageHandle);
  SetMessageTuple(hv_MessageHandle, "type", "exit");
  EnqueueMessage(HTuple(hv_MessageQueues1[1]), hv_MessageHandle, HTuple(), HTuple());
  CreateMessage(&hv_MessageHandle);
  SetMessageTuple(hv_MessageHandle, "type", "exit");
  EnqueueMessage(HTuple(hv_MessageQueues2[1]), hv_MessageHandle, HTuple(), HTuple());
  //
  hv_TIT = hvec_TI.ConvertVectorToTuple();
  HDevThread::ParJoin(hv_TIT);
  //
  return;
}

// Chapter: 3D Object Model / Features
void inspect_scene_edge_directions (HTuple hv_WindowHandle1, HTuple hv_SurfaceModelID, 
    HTuple hv_ObjectModel3DScene, HTuple hv_SurfaceMatchingResultID, HTuple hv_MaxGapIn, 
    HTuple hv_MinAmplitudeIn)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_SampledScene, hv_Exception, hv_SceneNormalsInverted;
  HTuple  hv_ObjectModel3DEdges, hv_DiameterModel, hv_EdgeDirs;
  HTuple  hv_ObjectModel3DEdgeDirs, hv_Instructions, hv_Message;
  HTuple  hv_PoseOut;

  //Get data
  try
  {
    GetSurfaceMatchingResult(hv_SurfaceMatchingResultID, "sampled_scene", HTuple(), 
        &hv_SampledScene);
  }
  // catch (Exception) 
  catch (HException &HDevExpDefaultException)
  {
    HDevExpDefaultException.ToHTuple(&hv_Exception);
    //Unable to extract -> create a dummy 3D object model instead
  }
  try
  {
    GetSurfaceMatchingResult(hv_SurfaceMatchingResultID, "scene_invert_normals", 
        HTuple(), &hv_SceneNormalsInverted);
    EdgesObjectModel3d(hv_ObjectModel3DScene, hv_MinAmplitudeIn, (HTuple("max_gap").Append("_scene_invert_normals")), 
        hv_MaxGapIn.TupleConcat(hv_SceneNormalsInverted), &hv_ObjectModel3DEdges);
    GetSurfaceModelParam(hv_SurfaceModelID, "diameter", &hv_DiameterModel);
    SampleObjectModel3d(hv_ObjectModel3DEdges, "fast_compute_normals", hv_DiameterModel*0.02, 
        HTuple(), HTuple(), &hv_ObjectModel3DEdges);
    GetObjectModel3dParams(hv_ObjectModel3DEdges, HTuple("edge_dir_")+((HTuple("x").Append("y")).Append("z")), 
        &hv_EdgeDirs);
    SetObjectModel3dAttrib(hv_ObjectModel3DEdges, HTuple("point_normal_")+((HTuple("x").Append("y")).Append("z")), 
        HTuple(), hv_EdgeDirs, &hv_ObjectModel3DEdgeDirs);
  }
  // catch (Exception) 
  catch (HException &HDevExpDefaultException)
  {
    HDevExpDefaultException.ToHTuple(&hv_Exception);
    //Unable to extract edges -> create a dummy 3D object model instead
    GenEmptyObjectModel3d(&hv_ObjectModel3DEdges);
    GenEmptyObjectModel3d(&hv_ObjectModel3DEdgeDirs);
  }
  //
  //Generate visualization
  hv_Instructions[0] = "Rotate: Left mouse button";
  hv_Instructions[1] = "Zoom:   Shift + left mouse button";
  hv_Instructions[2] = "Move:   Ctrl  + left mouse button";
  hv_Message = "Inspect viewing and edge directions";
  //
  visualize_object_model_3d(hv_WindowHandle1, (hv_SampledScene.TupleConcat(hv_ObjectModel3DEdges)).TupleConcat(hv_ObjectModel3DEdgeDirs), 
      HTuple(), HTuple(), (((((HTuple("color_0").Append("color_1")).Append("color_2")).Append("disp_pose")).Append("disp_normals_1")).Append("disp_normals_2")), 
      (((((HTuple("gray").Append("green")).Append("red")).Append("true")).Append("true")).Append("true")), 
      hv_Message, HTuple(), hv_Instructions, &hv_PoseOut);
  //
  HDevWindowStack::SetActive(hv_WindowHandle1);
  if (HDevWindowStack::IsOpen())
    ClearWindow(HDevWindowStack::GetActive());
  return;

}

// Chapter: 3D Object Model / Features
void inspect_scene_edge_parameters (HTuple hv_WindowHandle1, HTuple hv_WindowHandle2, 
    HTuple hv_SurfaceModelID, HTuple hv_ObjectModel3DScene, HTuple hv_SurfaceMatchingResultID, 
    HTuple hv_MaxGapIn, HTuple hv_MinAmplitudeAbsIn, HTuple *hv_MaxGap, HTuple *hv_MinAmplitudeAbs)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_Diameter, hv_DefaultAmplitude, hv_MinAmplitude;
  HTuple  hv_MaxAmplitude, hv_DefaultMaxGap, hv_MappingSize;
  HTuple  hv_MinMaxGap, hv_MaxMaxGap, hv_ObjectModel3DSceneSampled;
  HTuple  hv_SceneNormalsInverted, hv_ObjectModel3DEdges;
  HTuple  hv_Instructions, hv_Buttons, hv_MessageQueues1;
  HTuple  hv_PreviousState1, hv_DidFinish1, hv_MessageQueues2;
  HTuple  hv_MinAmplitudeRel, hv_XXScene, hv_YYScene, hv_ZZScene;
  HTuple  hv_PreviousState2, hv_ButtonPressed, hv_Poses, hv_DidFinish2;
  HTuple  hv_MessageHandle, hv_TIT;
  HTupleVector  hvec_TI(1);

  // +++ Threading variables 
  HDevThread*         hcppthread_handle;
  HDevThreadContext   hcppthread_context; // <-signals begin of procedure

  //Initial, Minimum and Maximum parameter values
  GetSurfaceModelParam(hv_SurfaceModelID, "diameter", &hv_Diameter);
  hv_DefaultAmplitude = hv_MinAmplitudeAbsIn/hv_Diameter;
  hv_MinAmplitude = 0.0001;
  hv_MaxAmplitude = 1;
  hv_DefaultMaxGap = hv_MaxGapIn;
  GetObjectModel3dParams(hv_ObjectModel3DScene, "mapping_size", &hv_MappingSize);
  hv_MinMaxGap = 0;
  hv_MaxMaxGap = hv_MappingSize.TupleMax();
  //
  GetSurfaceMatchingResult(hv_SurfaceMatchingResultID, "sampled_scene", 0, &hv_ObjectModel3DSceneSampled);
  GetSurfaceMatchingResult(hv_SurfaceMatchingResultID, "scene_invert_normals", HTuple(), 
      &hv_SceneNormalsInverted);
  EdgesObjectModel3d(hv_ObjectModel3DScene, hv_DefaultAmplitude*hv_Diameter, (HTuple("max_gap").Append("_scene_invert_normals")), 
      hv_DefaultMaxGap.TupleConcat(hv_SceneNormalsInverted), &hv_ObjectModel3DEdges);
  //
  //Start the 3D visualization window
  hv_Instructions[0] = "Rotate: Left mouse button";
  hv_Instructions[1] = "Zoom:   Shift + left mouse button";
  hv_Instructions[2] = "Move:   Ctrl  + left mouse button";
  //
  hv_Buttons.Clear();
  hv_Buttons[0] = "Continue";
  hv_Buttons[1] = "right";
  hv_Buttons[2] = "bottom";
  hv_Buttons[3] = -1;
  hv_Buttons[4] = -1;
  create_visualization_message_queues(&hv_MessageQueues1);
  // Create a thread instance
  hcppthread_handle = new HDevThread(hcppthread_context,
              (void*)HDevExportCpp::_hcppthread_visualize_object_model_3d_ext,15,0);
  // Set thread procedure call arguments 
  hcppthread_handle->SetInputCtrlParamTuple(0,hv_WindowHandle1);
  hcppthread_handle->SetInputCtrlParamTuple(1,hv_ObjectModel3DSceneSampled.TupleConcat(hv_ObjectModel3DEdges));
  hcppthread_handle->SetInputCtrlParamTuple(2,HTuple());
  hcppthread_handle->SetInputCtrlParamTuple(3,HTuple());
  hcppthread_handle->SetInputCtrlParamTuple(4,((HTuple("color_0").Append("color_1")).Append("disp_pose")));
  hcppthread_handle->SetInputCtrlParamTuple(5,((HTuple("gray").Append("red")).Append("true")));
  hcppthread_handle->SetInputCtrlParamTuple(6,"Inspection");
  hcppthread_handle->SetInputCtrlParamTuple(7,HTuple());
  hcppthread_handle->SetInputCtrlParamTuple(8,hv_Instructions);
  hcppthread_handle->SetInputCtrlParamTuple(9,hv_MessageQueues1);
  hcppthread_handle->SetInputCtrlParamTuple(10,hv_Buttons);
  hcppthread_handle->SetInputCtrlParamTuple(11,HTuple());
  hcppthread_handle->SetInputCtrlParamTuple(12,HTuple());
  hcppthread_handle->SetInputCtrlParamTuple(13,"false");
  hcppthread_handle->SetInputCtrlParamTuple(14,HTuple());

  // Start proc line in thread
  hcppthread_handle->ParStart(&hvec_TI[0].T());

  //
  hv_PreviousState1 = HTuple();
  hv_DidFinish1 = 0;
  //
  //Start the 2D Slider window
  create_visualization_message_queues(&hv_MessageQueues2);
  // Create a thread instance
  hcppthread_handle = new HDevThread(hcppthread_context,
              (void*)HDevExportCpp::_hcppthread_set_edge_parameter_sliders,8,2);
  // Set thread procedure call arguments 
  hcppthread_handle->SetInputCtrlParamTuple(0,hv_WindowHandle2);
  hcppthread_handle->SetInputCtrlParamTuple(1,hv_ObjectModel3DScene);
  hcppthread_handle->SetInputCtrlParamTuple(2,hv_MessageQueues2);
  hcppthread_handle->SetInputCtrlParamTuple(3,hv_MessageQueues1);
  hcppthread_handle->SetInputCtrlParamTuple(4,hv_Diameter);
  hcppthread_handle->SetInputCtrlParamTuple(5,(hv_MinAmplitude.TupleConcat(hv_MaxAmplitude)).TupleConcat(hv_DefaultAmplitude));
  hcppthread_handle->SetInputCtrlParamTuple(6,(hv_MinMaxGap.TupleConcat(hv_MaxMaxGap)).TupleConcat(hv_DefaultMaxGap));
  hcppthread_handle->SetInputCtrlParamTuple(7,hv_SceneNormalsInverted);
  hcppthread_handle->BindOutputCtrlParamTuple(0,0,&hv_MinAmplitudeRel);
  hcppthread_handle->BindOutputCtrlParamTuple(1,0,&(*hv_MaxGap));

  // Start proc line in thread
  hcppthread_handle->ParStart(&hvec_TI[1].T());

  //
  GetObjectModel3dParams(hv_ObjectModel3DScene, "point_coord_x", &hv_XXScene);
  GetObjectModel3dParams(hv_ObjectModel3DScene, "point_coord_y", &hv_YYScene);
  GetObjectModel3dParams(hv_ObjectModel3DScene, "point_coord_z", &hv_ZZScene);
  //
  hv_PreviousState2 = HTuple();
  //
  while (0 != (hv_DidFinish1.TupleNot()))
  {
    process_visualize_events_generic(hv_WindowHandle1, hv_MessageQueues1, hv_PreviousState1, 
        &hv_DidFinish1, &hv_PreviousState1, &hv_ButtonPressed, &hv_Poses);

    if (0 != (HTuple(int(hv_ButtonPressed==0)).TupleOr(hv_DidFinish1)))
    {
      //Exit button pressed
      break;
    }

    process_slider_events(hv_WindowHandle2, hv_MessageQueues2, hv_PreviousState2, 
        &hv_PreviousState2, &hv_DidFinish2);
    if (0 != hv_DidFinish2)
    {
      //Window closed
      break;
    }
  }

  CreateMessage(&hv_MessageHandle);
  SetMessageTuple(hv_MessageHandle, "type", "exit");
  EnqueueMessage(HTuple(hv_MessageQueues1[1]), hv_MessageHandle, HTuple(), HTuple());
  CreateMessage(&hv_MessageHandle);
  SetMessageTuple(hv_MessageHandle, "type", "exit");
  EnqueueMessage(HTuple(hv_MessageQueues2[1]), hv_MessageHandle, HTuple(), HTuple());
  //
  hv_TIT = hvec_TI.ConvertVectorToTuple();
  HDevThread::ParJoin(hv_TIT);
  //
  //Convert from relative to absolute
  (*hv_MinAmplitudeAbs) = hv_MinAmplitudeRel*hv_Diameter;
  //
  return;
}

// Chapter: 3D Object Model / Features
void inspect_scene_edge_parameters_find_box_3d (HTuple hv_WindowHandle1, HTuple hv_WindowHandle2, 
    HTuple hv_ObjectModel3DBox, HTuple hv_ObjectModel3DScene, HTuple hv_BoxInformation, 
    HTuple *hv_MaxGapOut, HTuple *hv_MinAmplitude)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_GenParamDict, hv_DefaultAmplitude;
  HTuple  hv_MinMinAmplitude, hv_MaxMinAmplitude, hv_DefaultMaxGap;
  HTuple  hv_MappingSize, hv_MinMaxGap, hv_MaxMaxGap, hv_ObjectModel3DSceneSampled;
  HTuple  hv_ObjectModel3DEdgesSampled, hv_Instructions, hv_Buttons;
  HTuple  hv_MessageQueues1, hv_PreviousState1, hv_DidFinish1;
  HTuple  hv_MessageQueues2, hv_XXScene, hv_YYScene, hv_ZZScene;
  HTuple  hv_PreviousState2, hv_ButtonPressed, hv_Poses, hv_DidFinish2;
  HTuple  hv_MessageHandle, hv_TIT;
  HTupleVector  hvec_TI(1);

  // +++ Threading variables 
  HDevThread*         hcppthread_handle;
  HDevThreadContext   hcppthread_context; // <-signals begin of procedure

  //Get Dictionary with generic parameters.
  GetDictTuple(hv_BoxInformation, "gen_param", &hv_GenParamDict);
  //Prepare initial, minimal and maximal parameter values.
  //Get MinAmplitude parameter and prepare MinMinAmplitude and MaxMinAmplitude.
  GetDictTuple(hv_GenParamDict, "3d_edge_min_amplitude", &hv_DefaultAmplitude);
  if (0 != (int(hv_DefaultAmplitude==0.0)))
  {
    get_min_amplitude(hv_BoxInformation, &hv_DefaultAmplitude);
  }
  hv_MinMinAmplitude = 0.0001;
  get_max_min_amplitude(hv_BoxInformation, &hv_MaxMinAmplitude);
  //Get max_gap parameter and prepare MinMaxGap and MaxMaxGap.
  GetDictTuple(hv_GenParamDict, "max_gap", &hv_DefaultMaxGap);
  GetObjectModel3dParams(hv_ObjectModel3DScene, "mapping_size", &hv_MappingSize);
  hv_MinMaxGap = 0;
  hv_MaxMaxGap = hv_MappingSize.TupleMax();
  //
  //Get edges in scene with the Params used for the call to find_box_3d.
  GetDictTuple(hv_BoxInformation, "sampled_scene", &hv_ObjectModel3DSceneSampled);
  GetDictTuple(hv_BoxInformation, "sampled_edges", &hv_ObjectModel3DEdgesSampled);
  //
  //Start the 3D visualization window.
  hv_Instructions[0] = "Rotate: Left mouse button";
  hv_Instructions[1] = "Zoom:   Shift + left mouse button";
  hv_Instructions[2] = "Move:   Ctrl  + left mouse button";
  //
  hv_Buttons.Clear();
  hv_Buttons[0] = "Continue";
  hv_Buttons[1] = "right";
  hv_Buttons[2] = "bottom";
  hv_Buttons[3] = -1;
  hv_Buttons[4] = -1;
  create_visualization_message_queues(&hv_MessageQueues1);
  // Create a thread instance
  hcppthread_handle = new HDevThread(hcppthread_context,
              (void*)HDevExportCpp::_hcppthread_visualize_object_model_3d_ext,15,0);
  // Set thread procedure call arguments 
  hcppthread_handle->SetInputCtrlParamTuple(0,hv_WindowHandle1);
  hcppthread_handle->SetInputCtrlParamTuple(1,hv_ObjectModel3DSceneSampled.TupleConcat(hv_ObjectModel3DEdgesSampled));
  hcppthread_handle->SetInputCtrlParamTuple(2,HTuple());
  hcppthread_handle->SetInputCtrlParamTuple(3,HTuple());
  hcppthread_handle->SetInputCtrlParamTuple(4,((HTuple("color_0").Append("color_1")).Append("disp_pose")));
  hcppthread_handle->SetInputCtrlParamTuple(5,((HTuple("gray").Append("red")).Append("true")));
  hcppthread_handle->SetInputCtrlParamTuple(6,"Inspection");
  hcppthread_handle->SetInputCtrlParamTuple(7,HTuple());
  hcppthread_handle->SetInputCtrlParamTuple(8,hv_Instructions);
  hcppthread_handle->SetInputCtrlParamTuple(9,hv_MessageQueues1);
  hcppthread_handle->SetInputCtrlParamTuple(10,hv_Buttons);
  hcppthread_handle->SetInputCtrlParamTuple(11,HTuple());
  hcppthread_handle->SetInputCtrlParamTuple(12,HTuple());
  hcppthread_handle->SetInputCtrlParamTuple(13,"false");
  hcppthread_handle->SetInputCtrlParamTuple(14,HTuple());

  // Start proc line in thread
  hcppthread_handle->ParStart(&hvec_TI[0].T());

  //
  hv_PreviousState1 = HTuple();
  hv_DidFinish1 = 0;
  //
  //Start the 2D Slider window.
  create_visualization_message_queues(&hv_MessageQueues2);
  // Create a thread instance
  hcppthread_handle = new HDevThread(hcppthread_context,
              (void*)HDevExportCpp::_hcppthread_set_edge_parameter_sliders_find_box_3d,7,2);
  // Set thread procedure call arguments 
  hcppthread_handle->SetInputCtrlParamTuple(0,hv_WindowHandle2);
  hcppthread_handle->SetInputCtrlParamTuple(1,hv_ObjectModel3DScene);
  hcppthread_handle->SetInputCtrlParamTuple(2,hv_MessageQueues2);
  hcppthread_handle->SetInputCtrlParamTuple(3,hv_MessageQueues1);
  hcppthread_handle->SetInputCtrlParamTuple(4,(hv_MinMinAmplitude.TupleConcat(hv_MaxMinAmplitude)).TupleConcat(hv_DefaultAmplitude));
  hcppthread_handle->SetInputCtrlParamTuple(5,(hv_MinMaxGap.TupleConcat(hv_MaxMaxGap)).TupleConcat(hv_DefaultMaxGap));
  hcppthread_handle->SetInputCtrlParamTuple(6,hv_GenParamDict);
  hcppthread_handle->BindOutputCtrlParamTuple(0,0,&(*hv_MinAmplitude));
  hcppthread_handle->BindOutputCtrlParamTuple(1,0,&(*hv_MaxGapOut));

  // Start proc line in thread
  hcppthread_handle->ParStart(&hvec_TI[1].T());

  //
  GetObjectModel3dParams(hv_ObjectModel3DScene, "point_coord_x", &hv_XXScene);
  GetObjectModel3dParams(hv_ObjectModel3DScene, "point_coord_y", &hv_YYScene);
  GetObjectModel3dParams(hv_ObjectModel3DScene, "point_coord_z", &hv_ZZScene);
  //
  hv_PreviousState2 = HTuple();
  //
  while (0 != (hv_DidFinish1.TupleNot()))
  {
    process_visualize_events_generic(hv_WindowHandle1, hv_MessageQueues1, hv_PreviousState1, 
        &hv_DidFinish1, &hv_PreviousState1, &hv_ButtonPressed, &hv_Poses);
    //
    if (0 != (HTuple(int(hv_ButtonPressed==0)).TupleOr(hv_DidFinish1)))
    {
      //Exit button pressed.
      break;
    }
    //
    process_slider_events(hv_WindowHandle2, hv_MessageQueues2, hv_PreviousState2, 
        &hv_PreviousState2, &hv_DidFinish2);
    if (0 != hv_DidFinish2)
    {
      //Window closed.
      break;
    }
  }
  //
  CreateMessage(&hv_MessageHandle);
  SetMessageTuple(hv_MessageHandle, "type", "exit");
  EnqueueMessage(HTuple(hv_MessageQueues1[1]), hv_MessageHandle, HTuple(), HTuple());
  CreateMessage(&hv_MessageHandle);
  SetMessageTuple(hv_MessageHandle, "type", "exit");
  EnqueueMessage(HTuple(hv_MessageQueues2[1]), hv_MessageHandle, HTuple(), HTuple());
  //
  hv_TIT = hvec_TI.ConvertVectorToTuple();
  HDevThread::ParJoin(hv_TIT);
  //
  return;
}

// Chapter: Deep Learning / Model
// Short Description: Generate various image lists and corresponding annotation file list. 
void list_image_and_annotation_files (HTuple hv_Type, HTuple hv_ImageDir, HTuple hv_XYZDir, 
    HTuple hv_NormalsDir, HTuple hv_AnnotationDir, HTuple hv_ImageListIn, HTuple hv_GenParam, 
    HTuple *hv_ImageListOut, HTuple *hv_XYZListOut, HTuple *hv_NormalsListOut, HTuple *hv_AnnotationListOut, 
    HTuple *hv_LabelListOut)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_ImageSubDirs, hv_XYZSubDirs, hv_NormalsSubDirs;
  HTuple  hv_AnnotationSubDirs, hv_FileNameImageOnly, hv_FileNameXYZOnly;
  HTuple  hv_FileNameNormalsOnly, hv_FileNameAnnoOnly, hv_IgnoreUnmatched;
  HTuple  hv_Keys, hv_KeyIndex, hv_AnnotationType, hv_ImageBaseNames;
  HTuple  hv_ImageBaseNamesToMatch, hv_ImageExtensions, hv_ImageDirectories;
  HTuple  hv_ImageDirectoriesRel, hv_XYZBaseNames, hv_XYZBaseNamesToMatch;
  HTuple  hv_XYZExtensions, hv_XYZDirectories, hv_XYZDirectoriesRel;
  HTuple  hv_Exception, hv_NormalsBaseNames, hv_NormalsBaseNamesToMatch;
  HTuple  hv_NormalsExtensions, hv_NormalsDirectories, hv_NormalsDirectoriesRel;
  HTuple  hv_GroundTruthLabels, hv_AnomalyExtensions, hv_AnnoBaseNames;
  HTuple  hv_AnnoBaseNamesToMatch, hv_AnnoExtensions, hv_AnnoDirectories;
  HTuple  hv_AnnoDirectoriesRel, hv_ImageMatchIndices, hv_XYZMatchIndices;
  HTuple  hv_NormalsMatchIndices, hv_AnnoMatchIndices, hv_ImageIndex;
  HTuple  hv_ImageNameToMatch, hv_ImageDirectoryToMatch, hv_ImageExtensionToMatch;
  HTuple  hv_XYZMatchIndex, hv_NormalsMatchIndex, hv_AnnoMatchIndex;
  HTuple  hv_ImageIndices, hv_AnnotationList;

  //
  //This procedure generates lists of images and corresponding
  //annotation files, whereby the first one can also be handed
  //over through ImageListIn.
  //The lists are generated by listing the files in the given
  //directory:
  // - ImageDir specifies the base directory for the images,
  // - XYZDir specifies the base directory for the XYZ-images,
  // - NormalsDir specifies the base directory for the normals
  //   images,
  // - AnnotationDir specifies the base directory for the
  //   annotation files.
  //
  //The file names of images and annotation files must give a
  //unique match in the sense that for each image exactly one
  //annotation is matched. To obtain a match, the following steps
  //are done (in the given order):
  //1) Exact name match.
  //2) Image name is a subpart of a single annotation file name.
  //3) Image name is a subpart of more than one annotation file
  //   names and only one of these matches has the same subfolder
  //   structure.
  //The additional image types (XYZ- and normals images) are
  //matched in a similar way.
  //
  //With the parameters specified in GenParam, the lists can be
  //limited to specific file names.
  //
  //Set defaults.
  hv_ImageSubDirs = HTuple();
  hv_XYZSubDirs = HTuple();
  hv_NormalsSubDirs = HTuple();
  hv_AnnotationSubDirs = HTuple();
  hv_FileNameImageOnly = "";
  hv_FileNameXYZOnly = "";
  hv_FileNameNormalsOnly = "";
  hv_FileNameAnnoOnly = "";
  hv_IgnoreUnmatched = 0;
  //
  //Read generic parameters and overwrite defaults.
  if (0 != (int(hv_GenParam!=HTuple())))
  {
    GetDictParam(hv_GenParam, "keys", HTuple(), &hv_Keys);
    {
    HTuple end_val42 = (hv_Keys.TupleLength())-1;
    HTuple step_val42 = 1;
    for (hv_KeyIndex=0; hv_KeyIndex.Continue(end_val42, step_val42); hv_KeyIndex += step_val42)
    {
      if (0 != (int(HTuple(hv_Keys[hv_KeyIndex])==HTuple("image_sub_dirs"))))
      {
        GetDictTuple(hv_GenParam, "image_sub_dirs", &hv_ImageSubDirs);
      }
      else if (0 != (int(HTuple(hv_Keys[hv_KeyIndex])==HTuple("xyz_sub_dirs"))))
      {
        GetDictTuple(hv_GenParam, "xyz_sub_dirs", &hv_XYZSubDirs);
      }
      else if (0 != (int(HTuple(hv_Keys[hv_KeyIndex])==HTuple("normals_sub_dirs"))))
      {
        GetDictTuple(hv_GenParam, "normals_sub_dirs", &hv_NormalsSubDirs);
      }
      else if (0 != (int(HTuple(hv_Keys[hv_KeyIndex])==HTuple("segmentation_sub_dirs"))))
      {
        GetDictTuple(hv_GenParam, "segmentation_sub_dirs", &hv_AnnotationSubDirs);
      }
      else if (0 != (int(HTuple(hv_Keys[hv_KeyIndex])==HTuple("anomaly_sub_dirs"))))
      {
        GetDictTuple(hv_GenParam, "anomaly_sub_dirs", &hv_AnnotationSubDirs);
      }
      else if (0 != (int(HTuple(hv_Keys[hv_KeyIndex])==HTuple("file_name_image_only"))))
      {
        GetDictTuple(hv_GenParam, "file_name_image_only", &hv_FileNameImageOnly);
      }
      else if (0 != (int(HTuple(hv_Keys[hv_KeyIndex])==HTuple("file_name_xyz_only"))))
      {
        GetDictTuple(hv_GenParam, "file_name_xyz_only", &hv_FileNameXYZOnly);
      }
      else if (0 != (int(HTuple(hv_Keys[hv_KeyIndex])==HTuple("file_name_normals_only"))))
      {
        GetDictTuple(hv_GenParam, "file_name_normals_only", &hv_FileNameNormalsOnly);
      }
      else if (0 != (int(HTuple(hv_Keys[hv_KeyIndex])==HTuple("file_name_segmentation_only"))))
      {
        GetDictTuple(hv_GenParam, "file_name_segmentation_only", &hv_FileNameAnnoOnly);
      }
      else if (0 != (int(HTuple(hv_Keys[hv_KeyIndex])==HTuple("file_name_anomaly_only"))))
      {
        GetDictTuple(hv_GenParam, "file_name_anomaly_only", &hv_FileNameAnnoOnly);
      }
      else if (0 != (int(HTuple(hv_Keys[hv_KeyIndex])==HTuple("ignore_unmatched_images"))))
      {
        GetDictTuple(hv_GenParam, "ignore_unmatched_images", &hv_IgnoreUnmatched);
      }
      else
      {
        throw HException(("Unknown generic parameter name : '"+HTuple(hv_Keys[hv_KeyIndex]))+"'");
      }
    }
    }
  }
  //
  //Check for model type and set corresponding annotation type
  //string to use (e.g. in error messages).
  if (0 != (HTuple(int(hv_Type==HTuple("segmentation"))).TupleOr(int(hv_Type==HTuple("3d_gripping_point_detection")))))
  {
    hv_AnnotationType = "segmentation";
  }
  else if (0 != (int(hv_Type==HTuple("anomaly_detection"))))
  {
    hv_AnnotationType = "anomaly";
  }
  else
  {
    throw HException("Unknown type "+hv_Type);
  }
  //
  //Check generic parameters.
  if (0 != (int(hv_ImageSubDirs!=HTuple())))
  {
    if (0 != (int(((hv_ImageSubDirs.TupleIsStringElem()).TupleMin())!=1)))
    {
      throw HException("'image_sub_dirs' must be a tuple of strings");
    }
  }
  if (0 != (int(hv_AnnotationSubDirs!=HTuple())))
  {
    if (0 != (int(((hv_AnnotationSubDirs.TupleIsStringElem()).TupleMin())!=1)))
    {
      throw HException(("'"+hv_AnnotationType)+"_sub_dirs' must be a tuple of strings");
    }
  }
  if (0 != (int(hv_FileNameImageOnly!=HTuple(""))))
  {
    if (0 != (int((hv_FileNameImageOnly.TupleLength())!=1)))
    {
      throw HException("'file_name_image_only' must be a single string");
    }
    else if (0 != ((hv_FileNameImageOnly.TupleIsString()).TupleNot()))
    {
      throw HException("'file_name_image_only' must be a string");
    }
  }
  if (0 != (int(hv_FileNameAnnoOnly!=HTuple(""))))
  {
    if (0 != (int((hv_FileNameAnnoOnly.TupleLength())!=1)))
    {
      throw HException(("'file_name_"+hv_AnnotationType)+"_only' must be a single string");
    }
    else if (0 != ((hv_FileNameAnnoOnly.TupleIsString()).TupleNot()))
    {
      throw HException(("'file_name_"+hv_AnnotationType)+"_only' must be a string");
    }
  }
  if (0 != (int(hv_Type==HTuple("3d_gripping_point_detection"))))
  {
    if (0 != (int(hv_XYZSubDirs!=HTuple())))
    {
      if (0 != (int(((hv_XYZSubDirs.TupleIsStringElem()).TupleMin())!=1)))
      {
        throw HException("'xyz_sub_dirs' must be a tuple of strings");
      }
    }
    if (0 != (int(hv_NormalsSubDirs!=HTuple())))
    {
      if (0 != (int(((hv_NormalsSubDirs.TupleIsStringElem()).TupleMin())!=1)))
      {
        throw HException("'normals_sub_dirs' must be a tuple of strings");
      }
    }
    if (0 != (int(hv_FileNameXYZOnly!=HTuple(""))))
    {
      if (0 != (int((hv_FileNameXYZOnly.TupleLength())!=1)))
      {
        throw HException("'file_name_xyz_only' must be a single string");
      }
      else if (0 != ((hv_FileNameXYZOnly.TupleIsString()).TupleNot()))
      {
        throw HException("'file_name_xyz_only' must be a string");
      }
    }
    if (0 != (int(hv_FileNameNormalsOnly!=HTuple(""))))
    {
      if (0 != (int((hv_FileNameNormalsOnly.TupleLength())!=1)))
      {
        throw HException("'file_name_normals_only' must be a single string");
      }
      else if (0 != ((hv_FileNameNormalsOnly.TupleIsString()).TupleNot()))
      {
        throw HException("'file_name_normals_only' must be a string");
      }
    }
  }
  if (0 != (HTuple(int(hv_IgnoreUnmatched!=0)).TupleAnd(int(hv_IgnoreUnmatched!=1))))
  {
    throw HException("Unsupported value for 'ignore_unmatched_images' : "+hv_IgnoreUnmatched);
  }
  //
  //Prepare image list.
  prepare_image_lists(hv_ImageDir, hv_ImageListIn, hv_ImageSubDirs, hv_FileNameImageOnly, 
      "default", &hv_ImageBaseNames, &hv_ImageBaseNamesToMatch, &hv_ImageExtensions, 
      &hv_ImageDirectories, &hv_ImageDirectoriesRel);
  //
  //Prepare XYZ file list.
  try
  {
    hv_XYZBaseNames = HTuple();
    hv_XYZBaseNamesToMatch = HTuple();
    hv_XYZExtensions = HTuple();
    hv_XYZDirectories = HTuple();
    hv_XYZDirectoriesRel = HTuple();
    prepare_image_lists(hv_XYZDir, HTuple(), hv_XYZSubDirs, hv_FileNameXYZOnly, "default", 
        &hv_XYZBaseNames, &hv_XYZBaseNamesToMatch, &hv_XYZExtensions, &hv_XYZDirectories, 
        &hv_XYZDirectoriesRel);
  }
  // catch (Exception) 
  catch (HException &HDevExpDefaultException)
  {
    HDevExpDefaultException.ToHTuple(&hv_Exception);
    if (0 != (int(hv_Type==HTuple("3d_gripping_point_detection"))))
    {
      //XYZ-images are required for 3D Gripping Point Detection.
      throw HException("No XYZ-images found");
    }
  }
  //
  //Prepare normals file list.
  try
  {
    hv_NormalsBaseNames = HTuple();
    hv_NormalsBaseNamesToMatch = HTuple();
    hv_NormalsExtensions = HTuple();
    hv_NormalsDirectories = HTuple();
    hv_NormalsDirectoriesRel = HTuple();
    prepare_image_lists(hv_NormalsDir, HTuple(), hv_NormalsSubDirs, hv_FileNameNormalsOnly, 
        "default", &hv_NormalsBaseNames, &hv_NormalsBaseNamesToMatch, &hv_NormalsExtensions, 
        &hv_NormalsDirectories, &hv_NormalsDirectoriesRel);
  }
  // catch (Exception) 
  catch (HException &HDevExpDefaultException)
  {
    HDevExpDefaultException.ToHTuple(&hv_Exception);
    //It is okay since normals are optional.
  }
  //
  //Get ground truth labels from the image directory names.
  TupleRegexpMatch("/"+hv_ImageDirectories, ".*/([^/]+)/$", &hv_GroundTruthLabels);
  //
  //Prepare annotation file list.
  try
  {
    if (0 != (int(hv_Type==HTuple("anomaly_detection"))))
    {
      hv_AnomalyExtensions.Clear();
      hv_AnomalyExtensions[0] = "hobj";
      hv_AnomalyExtensions[1] = "ima";
      hv_AnomalyExtensions[2] = "tif";
      hv_AnomalyExtensions[3] = "tiff";
      hv_AnomalyExtensions[4] = "gif";
      hv_AnomalyExtensions[5] = "bmp";
      hv_AnomalyExtensions[6] = "jpg";
      hv_AnomalyExtensions[7] = "jpeg";
      hv_AnomalyExtensions[8] = "jp2";
      hv_AnomalyExtensions[9] = "jxr";
      hv_AnomalyExtensions[10] = "png";
      hv_AnomalyExtensions[11] = "pcx";
      hv_AnomalyExtensions[12] = "ras";
      hv_AnomalyExtensions[13] = "xwd";
      hv_AnomalyExtensions[14] = "pbm";
      hv_AnomalyExtensions[15] = "pnm";
      hv_AnomalyExtensions[16] = "pgm";
      hv_AnomalyExtensions[17] = "ppm";
      prepare_image_lists(hv_AnnotationDir, HTuple(), hv_AnnotationSubDirs, hv_FileNameAnnoOnly, 
          hv_AnomalyExtensions, &hv_AnnoBaseNames, &hv_AnnoBaseNamesToMatch, &hv_AnnoExtensions, 
          &hv_AnnoDirectories, &hv_AnnoDirectoriesRel);
    }
    else
    {
      prepare_image_lists(hv_AnnotationDir, HTuple(), hv_AnnotationSubDirs, hv_FileNameAnnoOnly, 
          "default", &hv_AnnoBaseNames, &hv_AnnoBaseNamesToMatch, &hv_AnnoExtensions, 
          &hv_AnnoDirectories, &hv_AnnoDirectoriesRel);
    }
  }
  // catch (Exception) 
  catch (HException &HDevExpDefaultException)
  {
    HDevExpDefaultException.ToHTuple(&hv_Exception);
    if (0 != (int(hv_Type==HTuple("anomaly_detection"))))
    {
      (*hv_ImageListOut) = ((hv_ImageDirectoriesRel+hv_ImageBaseNames)+".")+hv_ImageExtensions;
      TupleRegexpReplace((*hv_ImageListOut), "^/", "", &(*hv_ImageListOut));
      (*hv_LabelListOut) = hv_GroundTruthLabels;
      (*hv_AnnotationListOut) = HTuple(hv_ImageBaseNames.TupleLength(),"");
      return;
    }
    else
    {
      throw HException("No annotation images found");
    }
  }
  //
  //
  //Match image, XYZ, normals and annotation lists.
  hv_ImageMatchIndices = HTuple();
  hv_XYZMatchIndices = HTuple();
  hv_NormalsMatchIndices = HTuple();
  hv_AnnoMatchIndices = HTuple();
  {
  HTuple end_val195 = (hv_ImageBaseNames.TupleLength())-1;
  HTuple step_val195 = 1;
  for (hv_ImageIndex=0; hv_ImageIndex.Continue(end_val195, step_val195); hv_ImageIndex += step_val195)
  {
    hv_ImageNameToMatch = HTuple(hv_ImageBaseNamesToMatch[hv_ImageIndex]);
    hv_ImageDirectoryToMatch = HTuple(hv_ImageDirectoriesRel[hv_ImageIndex]);
    hv_ImageExtensionToMatch = HTuple(hv_ImageExtensions[hv_ImageIndex]);
    //
    //Match to every image file a XYZ file.
    get_matching_file_index(hv_XYZBaseNamesToMatch, hv_XYZDirectoriesRel, hv_ImageNameToMatch, 
        hv_ImageDirectoryToMatch, hv_ImageExtensionToMatch, &hv_XYZMatchIndex);
    //
    //Match to every image file a normals file.
    get_matching_file_index(hv_NormalsBaseNamesToMatch, hv_NormalsDirectoriesRel, 
        hv_ImageNameToMatch, hv_ImageDirectoryToMatch, hv_ImageExtensionToMatch, 
        &hv_NormalsMatchIndex);
    //
    //Match to every image file an annotation file.
    get_matching_file_index(hv_AnnoBaseNamesToMatch, hv_AnnoDirectoriesRel, hv_ImageNameToMatch, 
        hv_ImageDirectoryToMatch, hv_ImageExtensionToMatch, &hv_AnnoMatchIndex);
    //
    //Collect found indices in case all required images were found.
    if (0 != (int(hv_AnnoMatchIndex!=-1)))
    {
      if (0 != (HTuple(int(hv_Type==HTuple("3d_gripping_point_detection"))).TupleAnd(int((hv_NormalsBaseNamesToMatch.TupleLength())>0))))
      {
        if (0 != (HTuple(int(hv_XYZMatchIndex!=-1)).TupleAnd(int(hv_NormalsMatchIndex!=-1))))
        {
          hv_ImageMatchIndices = hv_ImageMatchIndices.TupleConcat(hv_ImageIndex);
          hv_XYZMatchIndices = hv_XYZMatchIndices.TupleConcat(hv_XYZMatchIndex);
          hv_NormalsMatchIndices = hv_NormalsMatchIndices.TupleConcat(hv_NormalsMatchIndex);
          hv_AnnoMatchIndices = hv_AnnoMatchIndices.TupleConcat(hv_AnnoMatchIndex);
        }
      }
      else if (0 != (HTuple(int(hv_Type==HTuple("3d_gripping_point_detection"))).TupleAnd(int((hv_NormalsBaseNamesToMatch.TupleLength())==0))))
      {
        if (0 != (int(hv_XYZMatchIndex!=-1)))
        {
          hv_ImageMatchIndices = hv_ImageMatchIndices.TupleConcat(hv_ImageIndex);
          hv_XYZMatchIndices = hv_XYZMatchIndices.TupleConcat(hv_XYZMatchIndex);
          hv_AnnoMatchIndices = hv_AnnoMatchIndices.TupleConcat(hv_AnnoMatchIndex);
        }
      }
      else
      {
        hv_ImageMatchIndices = hv_ImageMatchIndices.TupleConcat(hv_ImageIndex);
        hv_AnnoMatchIndices = hv_AnnoMatchIndices.TupleConcat(hv_AnnoMatchIndex);
      }
    }
  }
  }
  //
  //
  //Final checks.
  //
  //Check if the corresponding matches are collected correctly.
  if (0 != (int(hv_Type==HTuple("3d_gripping_point_detection"))))
  {
    if (0 != (int((hv_XYZMatchIndices.TupleLength())!=(hv_ImageMatchIndices.TupleLength()))))
    {
      throw HException("An error occurred while trying to match XYZ and image files");
    }
    if (0 != (HTuple(int((hv_NormalsBaseNamesToMatch.TupleLength())>0)).TupleAnd(int((hv_NormalsMatchIndices.TupleLength())!=(hv_ImageMatchIndices.TupleLength())))))
    {
      throw HException("An error occurred while trying to match normals and image files");
    }
  }
  if (0 != (int((hv_AnnoMatchIndices.TupleLength())!=(hv_ImageMatchIndices.TupleLength()))))
  {
    throw HException("An error occurred while trying to match annotation and image files");
  }
  //
  //Check if each match is unique.
  if (0 != (int(((hv_XYZMatchIndices.TupleSort()).TupleUniq())!=(hv_XYZMatchIndices.TupleSort()))))
  {
    throw HException("A single XYZ file has matched with multiple images");
  }
  if (0 != (int(((hv_NormalsMatchIndices.TupleSort()).TupleUniq())!=(hv_NormalsMatchIndices.TupleSort()))))
  {
    throw HException("A single normals file has matched with multiple images");
  }
  if (0 != (int(((hv_AnnoMatchIndices.TupleSort()).TupleUniq())!=(hv_AnnoMatchIndices.TupleSort()))))
  {
    throw HException(("A single "+hv_AnnotationType)+" file has matched with multiple images");
  }
  //
  //Check if every image was collected, i.e. there is no image
  //without a match.
  hv_ImageIndices = hv_ImageMatchIndices;
  if (0 != (int(hv_Type==HTuple("anomaly_detection"))))
  {
    //For anomaly detection, images without a matching annotation
    //file are okay. So in this case, we use all images and not
    //only the ones with a match.
    hv_ImageIndices = HTuple::TupleGenSequence(0,(hv_ImageBaseNames.TupleLength())-1,1);
  }
  else if (0 != (hv_IgnoreUnmatched.TupleNot()))
  {
    if (0 != (int((hv_ImageMatchIndices.TupleLength())!=(hv_ImageBaseNames.TupleLength()))))
    {
      throw HException("Not every image has all required matching files");
    }
  }
  //
  //Create final image list.
  (*hv_ImageListOut) = ((hv_ImageDirectoriesRel+hv_ImageBaseNames)+".")+hv_ImageExtensions;
  (*hv_ImageListOut) = HTuple((*hv_ImageListOut)[hv_ImageIndices]);
  TupleRegexpReplace((*hv_ImageListOut), "^/", "", &(*hv_ImageListOut));
  //
  //Create final XYZ list.
  (*hv_XYZListOut) = ((hv_XYZDirectoriesRel+hv_XYZBaseNames)+".")+hv_XYZExtensions;
  (*hv_XYZListOut) = HTuple((*hv_XYZListOut)[hv_XYZMatchIndices]);
  TupleRegexpReplace((*hv_XYZListOut), "^/", "", &(*hv_XYZListOut));
  //
  //Create final normals list.
  (*hv_NormalsListOut) = ((hv_NormalsDirectoriesRel+hv_NormalsBaseNames)+".")+hv_NormalsExtensions;
  (*hv_NormalsListOut) = HTuple((*hv_NormalsListOut)[hv_NormalsMatchIndices]);
  TupleRegexpReplace((*hv_NormalsListOut), "^/", "", &(*hv_NormalsListOut));
  //
  //Create final ground truth label list.
  (*hv_LabelListOut) = HTuple(hv_GroundTruthLabels[hv_ImageIndices]);
  //
  //Create final annotation list.
  (*hv_AnnotationListOut) = ((hv_AnnoDirectoriesRel+hv_AnnoBaseNames)+".")+hv_AnnoExtensions;
  if (0 != (int(hv_Type==HTuple("anomaly_detection"))))
  {
    hv_AnnotationList = HTuple((*hv_ImageListOut).TupleLength(),"");
    hv_AnnotationList[hv_ImageMatchIndices] = HTuple((*hv_AnnotationListOut)[hv_AnnoMatchIndices]);
    (*hv_AnnotationListOut) = hv_AnnotationList;
  }
  else
  {
    (*hv_AnnotationListOut) = HTuple((*hv_AnnotationListOut)[hv_AnnoMatchIndices]);
  }
  TupleRegexpReplace((*hv_AnnotationListOut), "^/", "", &(*hv_AnnotationListOut));
  //
  return;
}

// Chapter: File / Misc
// Short Description: Get all image files under the given path 
void list_image_files (HTuple hv_ImageDirectory, HTuple hv_Extensions, HTuple hv_Options, 
    HTuple *hv_ImageFiles)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_ImageDirectoryIndex, hv_ImageFilesTmp;
  HTuple  hv_CurrentImageDirectory, hv_HalconImages, hv_OS;
  HTuple  hv_Directories, hv_Index, hv_Length, hv_NetworkDrive;
  HTuple  hv_Substring, hv_FileExists, hv_AllFiles, hv_i;
  HTuple  hv_Selection;

  //This procedure returns all files in a given directory
  //with one of the suffixes specified in Extensions.
  //
  //Input parameters:
  //ImageDirectory: Directory or a tuple of directories with images.
  //   If a directory is not found locally, the respective directory
  //   is searched under %HALCONIMAGES%/ImageDirectory.
  //   See the Installation Guide for further information
  //   in case %HALCONIMAGES% is not set.
  //Extensions: A string tuple containing the extensions to be found
  //   e.g. ['png','tif',jpg'] or others
  //If Extensions is set to 'default' or the empty string '',
  //   all image suffixes supported by HALCON are used.
  //Options: as in the operator list_files, except that the 'files'
  //   option is always used. Note that the 'directories' option
  //   has no effect but increases runtime, because only files are
  //   returned.
  //
  //Output parameter:
  //ImageFiles: A tuple of all found image file names
  //
  if (0 != (HTuple(HTuple(int(hv_Extensions==HTuple())).TupleOr(int(hv_Extensions==HTuple("")))).TupleOr(int(hv_Extensions==HTuple("default")))))
  {
    hv_Extensions.Clear();
    hv_Extensions[0] = "ima";
    hv_Extensions[1] = "tif";
    hv_Extensions[2] = "tiff";
    hv_Extensions[3] = "gif";
    hv_Extensions[4] = "bmp";
    hv_Extensions[5] = "jpg";
    hv_Extensions[6] = "jpeg";
    hv_Extensions[7] = "jp2";
    hv_Extensions[8] = "jxr";
    hv_Extensions[9] = "png";
    hv_Extensions[10] = "pcx";
    hv_Extensions[11] = "ras";
    hv_Extensions[12] = "xwd";
    hv_Extensions[13] = "pbm";
    hv_Extensions[14] = "pnm";
    hv_Extensions[15] = "pgm";
    hv_Extensions[16] = "ppm";
    //
  }
  (*hv_ImageFiles) = HTuple();
  //Loop through all given image directories.
  {
  HTuple end_val27 = (hv_ImageDirectory.TupleLength())-1;
  HTuple step_val27 = 1;
  for (hv_ImageDirectoryIndex=0; hv_ImageDirectoryIndex.Continue(end_val27, step_val27); hv_ImageDirectoryIndex += step_val27)
  {
    hv_ImageFilesTmp = HTuple();
    hv_CurrentImageDirectory = HTuple(hv_ImageDirectory[hv_ImageDirectoryIndex]);
    if (0 != (int(hv_CurrentImageDirectory==HTuple(""))))
    {
      hv_CurrentImageDirectory = ".";
    }
    GetSystem("image_dir", &hv_HalconImages);
    GetSystem("operating_system", &hv_OS);
    if (0 != (int((hv_OS.TupleSubstr(0,2))==HTuple("Win"))))
    {
      hv_HalconImages = hv_HalconImages.TupleSplit(";");
    }
    else
    {
      hv_HalconImages = hv_HalconImages.TupleSplit(":");
    }
    hv_Directories = hv_CurrentImageDirectory;
    {
    HTuple end_val41 = (hv_HalconImages.TupleLength())-1;
    HTuple step_val41 = 1;
    for (hv_Index=0; hv_Index.Continue(end_val41, step_val41); hv_Index += step_val41)
    {
      hv_Directories = hv_Directories.TupleConcat((HTuple(hv_HalconImages[hv_Index])+"/")+hv_CurrentImageDirectory);
    }
    }
    TupleStrlen(hv_Directories, &hv_Length);
    TupleGenConst(hv_Length.TupleLength(), 0, &hv_NetworkDrive);
    if (0 != (int((hv_OS.TupleSubstr(0,2))==HTuple("Win"))))
    {
      {
      HTuple end_val47 = (hv_Length.TupleLength())-1;
      HTuple step_val47 = 1;
      for (hv_Index=0; hv_Index.Continue(end_val47, step_val47); hv_Index += step_val47)
      {
        if (0 != (int((HTuple(hv_Directories[hv_Index]).TupleStrlen())>1)))
        {
          TupleStrFirstN(HTuple(hv_Directories[hv_Index]), 1, &hv_Substring);
          if (0 != (HTuple(int(hv_Substring==HTuple("//"))).TupleOr(int(hv_Substring==HTuple("\\\\")))))
          {
            hv_NetworkDrive[hv_Index] = 1;
          }
        }
      }
      }
    }
    hv_ImageFilesTmp = HTuple();
    {
    HTuple end_val57 = (hv_Directories.TupleLength())-1;
    HTuple step_val57 = 1;
    for (hv_Index=0; hv_Index.Continue(end_val57, step_val57); hv_Index += step_val57)
    {
      FileExists(HTuple(hv_Directories[hv_Index]), &hv_FileExists);
      if (0 != hv_FileExists)
      {
        ListFiles(HTuple(hv_Directories[hv_Index]), HTuple("files").TupleConcat(hv_Options), 
            &hv_AllFiles);
        hv_ImageFilesTmp = HTuple();
        {
        HTuple end_val62 = (hv_Extensions.TupleLength())-1;
        HTuple step_val62 = 1;
        for (hv_i=0; hv_i.Continue(end_val62, step_val62); hv_i += step_val62)
        {
          TupleRegexpSelect(hv_AllFiles, ((".*"+HTuple(hv_Extensions[hv_i]))+"$").TupleConcat("ignore_case"), 
              &hv_Selection);
          hv_ImageFilesTmp = hv_ImageFilesTmp.TupleConcat(hv_Selection);
        }
        }
        TupleRegexpReplace(hv_ImageFilesTmp, (HTuple("\\\\").Append("replace_all")), 
            "/", &hv_ImageFilesTmp);
        if (0 != (HTuple(hv_NetworkDrive[hv_Index])))
        {
          TupleRegexpReplace(hv_ImageFilesTmp, (HTuple("//").Append("replace_all")), 
              "/", &hv_ImageFilesTmp);
          hv_ImageFilesTmp = "/"+hv_ImageFilesTmp;
        }
        else
        {
          TupleRegexpReplace(hv_ImageFilesTmp, (HTuple("//").Append("replace_all")), 
              "/", &hv_ImageFilesTmp);
        }
        break;
      }
    }
    }
    //Concatenate the output image paths.
    (*hv_ImageFiles) = (*hv_ImageFiles).TupleConcat(hv_ImageFilesTmp);
  }
  }
  return;
}

// Chapter: Deep Learning / Model
// Short Description: Shuffle the input colors in a deterministic way 
void make_neighboring_colors_distinguishable (HTuple hv_ColorsRainbow, HTuple *hv_Colors)
{

  // Local iconic variables

  // Local control variables
  HTuple  hv_NumColors, hv_NumChunks, hv_NumLeftOver;
  HTuple  hv_ColorsPerChunk, hv_StartIdx, hv_S, hv_EndIdx;
  HTuple  hv_IdxsLeft, hv_IdxsRight;

  //
  //Shuffle the input colors in a deterministic way
  //to make adjacent colors more distinguishable.
  //Neighboring colors from the input are distributed to every NumChunks
  //position in the output.
  //Depending on the number of colors, increase NumChunks.
  hv_NumColors = hv_ColorsRainbow.TupleLength();
  if (0 != (int(hv_NumColors>=8)))
  {
    hv_NumChunks = 3;
    if (0 != (int(hv_NumColors>=40)))
    {
      hv_NumChunks = 6;
    }
    else if (0 != (int(hv_NumColors>=20)))
    {
      hv_NumChunks = 4;
    }
    (*hv_Colors) = HTuple(hv_NumColors,-1);
    //Check if the Number of Colors is dividable by NumChunks.
    hv_NumLeftOver = hv_NumColors%hv_NumChunks;
    hv_ColorsPerChunk = (hv_NumColors/hv_NumChunks).TupleInt();
    hv_StartIdx = 0;
    {
    HTuple end_val19 = hv_NumChunks-1;
    HTuple step_val19 = 1;
    for (hv_S=0; hv_S.Continue(end_val19, step_val19); hv_S += step_val19)
    {
      hv_EndIdx = (hv_StartIdx+hv_ColorsPerChunk)-1;
      if (0 != (int(hv_S<hv_NumLeftOver)))
      {
        hv_EndIdx += 1;
      }
      hv_IdxsLeft = HTuple::TupleGenSequence(hv_S,hv_NumColors-1,hv_NumChunks);
      hv_IdxsRight = HTuple::TupleGenSequence(hv_StartIdx,hv_EndIdx,1);
      (*hv_Colors)[HTuple::TupleGenSequence(hv_S,hv_NumColors-1,hv_NumChunks)] = hv_ColorsRainbow.TupleSelectRange(hv_StartIdx,hv_EndIdx);
      hv_StartIdx = hv_EndIdx+1;
    }
    }
  }
  else
  {
    (*hv_Colors) = hv_ColorsRainbow;
  }
  return;
}

